pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands on
    // "coarse" residue classes (large unusable gaps) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement; quantize into 20 harmonic buckets.
    let frac = post / cap;
    let bucket = (frac * 20.0).floor() as i32;

    // Dead-space penalty grows quadratically for small leftovers (hard-to-fill).
    if post > 0 {
        score += (20.0 - frac * 20.0).powi(2) * 0.35;
    } else {
        // Perfect fit is heavily rewarded.
        score -= 60.0;
    }

    // Modulo-class logic: leftovers divisible by common item sizes (10, 20, 25, 50)
    // are reusable; reward them.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 8.0;
    }
    if pr > 0 && pr < 10 {
        // Tiny sliver: nearly dead space.
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin; if next item cannot fit, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            if slack == 0.0 {
                score -= 45.0;
            } else if slack <= 10.0 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
            // Harmonic match: next item divides post residual evenly.
            if (post_residual % next_item_size) == 0 {
                score -= 12.0;
            }
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: prefer keeping it closed early; allow opening later
    // when open bins are congested (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (cap - mean_residual) / cap;
        score = cap - 30.0 * progress + 25.0 * congestion;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Mild tie-break toward consolidating fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space". Penalize them quadratically.
    let dead_threshold = 25.0;
    if (post_residual as f64) < dead_threshold {
        let gap = dead_threshold - post_residual as f64;
        score += 6.0 * gap * gap;
    } else {
        // Reward leaving a residual that can host a mid-size item
        score -= 4.0 * ((post_residual as f64) - dead_threshold).sqrt();
    }

    // Perfect or near-perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0;
        if slack < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; mildly penalize leaving a gap it almost fits
        if next_item_size - post_residual <= 8 {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6
            + pressure * 3.0
            + if fitting_bins_count == 0 { -100.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= item_size { -5.0 } else { 0.0 };
    }

    // Slight progression term: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is typical or tight
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    // Penalize gaps too small for the smallest plausible item (1..100 range),
    // especially gaps below the typical item scale.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 200.0; // tiny sliver: dead space
        } else if gap < 20.0 {
            score += 60.0;
        } else if gap < 30.0 {
            score += 20.0;
        }
        // Reward gaps that can still fit the next item (k=2 lookahead).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else if next_item_size > 0 {
            score += 25.0; // gap cannot host the lookahead item
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let pressure = open_bins_count as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += pressure * (1.0 - tightness) * 8.0;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 120.0;
        // If existing bins are crowded / few fit, opening is reasonable.
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 80.0;
        }
        // Late in the stream, prefer consolidating.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 40.0 * progress;
        }
    }

    // Mild preference for bins with below-average residual (fill emptier bins less,
    // keep larger residuals flexible)? Invert: prefer bins with residual close to item
    // size (best-fit character) beyond raw post_residual.
    score += 0.05 * (bin_residual as f64 - item_size as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1)
    // but practically, gaps below ~10 waste the bin. Penalize sub-10 gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling: post_residual that cannot fit the lookahead item is dead space
    // unless the next item could be placed elsewhere; penalize moderately.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also serve the lookahead item (chain fits).
        score -= 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current item
    // is large and open bins would suffer heavy dead space.
    if bin_residual == bin_capacity {
        let waste_if_forced = mean_residual - item_size as f64;
        let mut new_bin_score = 18.0 + open_bins_count as f64 * 0.1;
        if waste_if_forced < 0.0 {
            new_bin_score -= waste_if_forced * 0.5;
        }
        if next_item_size > 0 && item_size >= next_item_size {
            new_bin_score += 3.0;
        }
        score = new_bin_score;
    } else {
        // Mild reward for tight fits relative to mean residual.
        let tightness = (bin_residual - item_size) as f64;
        if tightness < mean_residual * 0.5 {
            score -= 2.0;
        }
    }

    // Late-stream urgency: as the stream ends, prioritize closing bins cleanly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 && post_residual == 0 {
            score -= 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let small_dead = (bin_capacity / 10) as f64; // leftover below 10 is unusable dead space
    if pr > 0.0 && pr < small_dead {
        score += 60.0; // penalize creating unusable slivers
    }

    // Modulo arithmetic on post_residual: common harmonic residual classes (0, 25, 50, 75, 100)
    let class = post_residual % 25;
    if class == 0 && post_residual > 0 {
        score -= 25.0; // harmonically aligned leftover, reusable by quarter-sized items
    } else {
        score += class as f64 * 0.5;
    }

    // Lookahead coupling: if next item fits harmonically into post_residual, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 25;
            if nxt_class == 0 {
                score -= 40.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 35.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: prefer new bin when current bins are fragmented
    if bin_residual == bin_capacity {
        // new empty bin: baseline score; penalize slightly so decent fits win
        score += 15.0;
        // but if open bins are fragmented (mean residual low), opening new bin is good
        if mean_residual < 0.35 * c {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 45.0;
        }
    }

    // Progress-based mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * (post_residual as f64 / c);

    // Tie-break: prefer bins with residual close to item (tight fit)
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item are pure waste; penalize super-linearly.
    if post_residual > 0 {
        let dead = post_residual < 10; // cannot hold even the smallest item
        if dead {
            score += 60.0 + (10 - post_residual) as f64 * 8.0;
        } else {
            // Fragility: small-but-usable gaps are risky; scale penalty with gap smallness.
            let fragility = (100.0 - post_residual as f64) / 100.0;
            score += fragility * fragility * 12.0;
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or tightly,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 18.0 - slack * 2.0;
            } else {
                score += slack * 0.3;
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; opening new bins is penalized via the empty-bin call.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin starts with a baseline penalty
    // so consolidation wins unless this bin's fit is bad.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.2 - (open_bins_count as f64).sqrt() * 5.0;
        // If no open bin fits well (this call is the fallback), allow opening.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Progress: later in the stream, tighten up (value dense packing more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small residuals that are hard to reuse later.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 - pr * 4.0; // dead space under 10 is nearly unusable (min item = 1..100 range)
        }
        // Reward residuals that can host the next item (2-step lookahead matching).
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                // Perfect 2-chain: post_residual exactly matches next item.
                let gap = pr - nxt;
                if gap == 0.0 {
                    score -= 400.0;
                } else {
                    // Scaled reward: smaller gap is better, but bounded.
                    score -= 150.0 * (1.0 - gap / bin_capacity as f64);
                }
            } else {
                // Next item won't fit in the leftover: mild penalty proportional to shortfall.
                score += 0.5 * (nxt - pr);
            }
        }
    }

    // Compare this bin's residual against the mean residual of open bins.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        // Bins with residual below mean are "tighter" — prefer using them up
        // (they are less likely to serve future items), so reward choosing them.
        let rel = (res - mean_residual) / mean_residual;
        score += 8.0 * rel;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // fits poorly everywhere else. Penalize opening a new bin unless the item
    // is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of a new bin, discounted for large items.
        score = 100.0 - 40.0 * fill_ratio;
        // If many bins are open and fragmented, opening fresh is more acceptable.
        score -= 2.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If the next item is small, a fresh big residual is valuable.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let left = (bin_capacity as f64) - item_size as f64;
            if left >= nxt {
                score -= 20.0 * (1.0 - (left - nxt) / bin_capacity as f64);
            }
        }
    }

    // Mild tie-breaking: prefer bins with larger residual when all else equal
    // (keeps small-residual bins for small items).
    score -= 0.01 * res;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * fit_ratio;
    }

    // Dead-space penalty: post_residual gaps that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // If the leftover can exactly fit the lookahead item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If leftover cannot fit the next item and is small, penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheap so favor consolidation instead.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Give it a moderate baseline so tight fits in existing
    // bins beat it, but large dead space in existing bins loses to it.
    if bin_residual == bin_capacity {
        score = 35.0 + item_size as f64 * 0.1;
        if fitting_bins_count == 1 {
            // An existing last-chance bin should beat a new bin.
            score += 25.0;
        }
    }

    // Slight preference for bins below mean residual (consolidating slack).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress) - 6.0 * norm_post * (1.0 - norm_post) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_post).powi(3) * 10.0 * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.5 + progress);
        } else {
            score -= 2.0 * (1.0 - (post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.15;

    // Pull toward mean residual to keep bins balanced
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are worthless.
    if post_residual > 0 {
        // Dead-space penalty grows sharply as the gap becomes unusable.
        // A gap is "dead" if it's smaller than the smallest plausible item (1)
        // or smaller than the lookahead item, making it unlikely to be reused.
        let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < dead_threshold {
            score += 40.0 * (1.0 - post_residual as f64 / dead_threshold.max(1) as f64);
        }
        // General convex penalty on leftover space: prefer tight fits strongly.
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward using a bin that would otherwise be the last chance before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the fit would be poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 18.0;
        // Pressure from number of open bins: with many open bins, prefer packing
        // into existing ones; with few, a fresh bin is cheap.
        score -= open_bins_count as f64 * 1.5;
        // If no existing bin fits well (post_residual of this empty bin is the
        // best possible), opening is more attractive when the stream is early.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 6.0;
        }
    } else {
        // Slight preference for bins with larger residuals when fits are comparable,
        // keeping big gaps available for big future items.
        score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;
        // Coupling with mean residual: avoid destroying the largest remaining gaps
        // when the fleet is already tight.
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    // Lookahead synergy: reward placements leaving room for the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap -> unusable dead space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, zero waste
    }

    // Non-linear penalty on residual that falls into awkward mid-range
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 50.0 {
        score += 0.6 * (50.0 - pr); // smaller leftover in awkward zone penalized more
    }

    // Lookahead coupling: leftover that can still host the next item is valuable
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0; // can host next item
            score -= 0.1 * nx;
        } else if post_residual > 0 {
            score += 0.25 * (nx - pr).min(60.0); // dead space relative to next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight
    let open_pressure = open_bins_count as f64;
    if fitting_bins_count == 1 {
        // last chance bin: strongly favor using it over opening a new bin
        score -= 45.0;
    } else {
        score += 0.08 * open_pressure;
    }

    // New-bin candidate: allow opening a fresh bin when all fits are bad,
    // but only if current open bins are crowded (high mean residual usage).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 20.0;
        if crowded || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 15.0; // keep packing into existing bins when there is room
        }
    }

    // Mild stream-progression term: later in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (100.0 - pr) / 100.0;

    // Reward bins already tighter than average (good fit quality)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.15 * (mean_residual - res);
    } else {
        score += 0.10 * (res - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure loss.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space: penalize heavily
    } else if post_residual <= 20 {
        score += 10.0; // small gap, likely unusable soon
    } else {
        score -= 2.0; // usable residual is good
    }

    // Lookahead: reward residuals that can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad dead space.
    if bin_residual == bin_capacity {
        // Opening a new bin costs a base penalty; compare against dead space created here.
        let dead = post_residual as f64;
        score = 60.0 + dead * 0.2 - pressure * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins near the mean to keep balance.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight lookahead match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item fits here: reward closeness to perfect match
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space relative to lookahead item: penalize proportionally
            score += 0.8 * gap;
        }
        // Extra penalty if leftover is unusable-small relative to typical item scale
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Compare against mean residual: prefer bins that stay near the pack's average fill
    let drift = post_residual as f64 - mean_residual;
    score += 0.15 * drift;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating many sparse bins when many bins are already open
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let escape_pressure = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        score = bin_capacity as f64 - escape_pressure
            + 0.5 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Slight stream-position modulation: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Squared dead-space penalty, amplified for very small leftovers.
        let pr = post_residual as f64;
        score += (bin_capacity as f64 - pr) * 0.0;
        score += 60.0 / (1.0 + (bin_capacity as f64 - pr) / 10.0);
    }

    // Lookahead: reward when next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 80.0 / (1.0 + gap / 8.0);
        } else {
            // Next item cannot fit here: mild penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless current item is large relative to capacity
    // and open bins are crowded (poor fits). Encourage fresh bin only for big items.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let crowd = open_bins_count as f64;
        score += 120.0 - fill_ratio * 100.0 - crowd * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0; // fresh bin can host current + next
        }
    }

    // Slight preference for using bins earlier in the stream (stability term).
    score += (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but still usable).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 15 {
        score -= 25.0; // tight fit, likely reusable
    }

    // Reward good relative fill ratio of the bin.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 40.0;

    // Lookahead: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for next item: penalize mildly unless it's dead space.
        score += 8.0;
    }

    // Open-bin pressure: prefer placing into existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: penalize bins whose residual deviates far above
    // the mean (they are likely to become dead-space bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.max(0.0);

    // Early stream: be slightly more conservative (favor new bins for large
    // items so small ones can fill later); late stream: pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // New-bin candidate: give it a moderate baseline so it is chosen only
    // when existing bins have bad fits (their penalties push them above this).
    if bin_residual == bin_capacity {
        score = 55.0 + item_size as f64 * 0.2 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the minimum item (1..=100 range,
    // but small gaps < 20 are unlikely to be filled later) are heavily penalized.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits: large fill ratio of the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize creating a gap that cannot fit the known next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward using the bin when it's the only fitting bin (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Encourage consolidating into bins with low mean residual (nearly full bins),
    // and prefer opening a new bin only when open bins have little room.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from mean residual of open bins.
        score += 25.0;
        if mean_residual < item_size as f64 {
            score -= 20.0; // open bins can't help much; new bin is fine
        }
        // Late in the stream, opening new bins is less costly than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // Favor bins whose residual is close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 6.0 + 4.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(3.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Many fitting bins: slight penalty to preserve diversity of residuals.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Time horizon: early in stream, encourage consolidation; late, tolerate new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (1.0 - progress);

    // Penalize bins far below the mean residual (unbalanced fills).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Reward filling bins nearly to capacity (waste minimization).
    if post_residual <= 5 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 40.0 - 30.0 * pressure - 10.0 * progress;
        if item_size >= 70 {
            score -= 15.0; // large items are fine in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable.
    if post_residual > 0 && post_residual < 11 {
        score += 60.0;
    } else if post_residual < 21 {
        score += 25.0;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose leftover can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that almost fits the next item (near-miss waste).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Pressure: many open bins -> discourage spreading, prefer tight packing.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score = 80.0 + post_residual as f64
            - (fitting_bins_count == 0) as i32 as f64 * 70.0
            + open_bins_count as f64 * 0.5;
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score -= 40.0 * (1.0 - tight).powi(6);
    }

    // Penalize dead space that no future item (sizes 1..=100) could ever fill poorly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.2 * (next_item_size as f64);
        } else {
            // Penalize leaving a gap just larger than the next item.
            let gap = post_residual as f64 - (next_item_size as f64);
            if gap < 0.0 && gap > -20.0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when current
    // bins are crowded or the fit here would be terrible.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = (open_bins_count as f64) / 20.0;
        let mean_tight = 1.0 - (mean_residual / (bin_capacity as f64));
        // Prefer new bin when existing bins are quite full or many are open.
        let bonus = 30.0 * mean_tight + 10.0 * crowd + 20.0 * progress;
        // But penalize if this bin would fit the item well (waste of a fresh bin).
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        score += 50.0 - bonus - 40.0 * fit_quality;
    }

    // Mild global regularization: prefer bins whose residual is below the mean
    // (fill the emptier-feeling bins less when they are above-average full).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Slight preference for using more open bins early, consolidating late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: small gap between post_residual and next item size.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            // Bin can still host the next item: reward closeness.
            score -= (60.0 / (1.0 + gap)).min(50.0);
        } else {
