            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare post_residual against mean residual: leaving typical slack is good.
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Discourage leaving tiny unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: default competitive baseline, adjusted by stream phase
    // and how fragmented existing bins are.
    if bin_residual == bin_capacity {
        score = 45.0
            - 30.0 * (step_index as f64 / total_items.max(1) as f64)
            - 0.3 * mean_residual;
        // If some open bin achieves a perfect lookahead match, keep the new bin out.
        if next_item_size > 0 && post_residual == next_item_size {
            score += 2000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post-residuals that are too small to be
    // usable by future items are heavily penalized (quadratic in gap smallness).
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        let dead = (min_useful - post_residual) as f64;
        score += dead * dead * 0.35;
    }
    // Zero post-residual (perfect fit) is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: the smaller the item relative to residual, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins when few bins fit.
    let obp = open_bins_count as f64;
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 30.0;
    } else {
        score += obp * 1.5;
    }

    // New-bin candidate handling: only attractive when open bins have poor fit
    // potential (high mean residual wasted) or stream is early.
    if bin_residual == bin_capacity {
        let waste = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - waste * 20.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0; // new bin will perfectly serve the next item too
        }
    } else {
        // Slight penalty proportional to how much mean residual deviates
        // from this bin's residual (prefer bins consistent with fleet state).
        score += (bin_residual as f64 - mean_residual).abs() * 0.1;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_fit = next_item_size as f64 / post_residual as f64;
        if nxt_fit > 0.8 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction classes
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / 10) as f64; // decade class 0..10

    // Reward small post_residual strongly (best-fit core with non-linear coupling)
    score -= (post_residual == 0) as f64 * 1000.0;
    score -= (pr * pr) / (c * c) * 60.0;

    // Penalize "dead" residuals that few item sizes can use (harmonic classes):
    // residuals in (0,10) are unusable for any item; 10..=19 only usable by tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Modulo-arithmetic coupling: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be exactly filled later.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 50 == 0 { score -= 5.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 1.5;
        } else {
            // next item cannot use this residual; penalize proportionally
            score += ((next_item_size - post_residual) as f64).min(c) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we prefer good existing fits,
    // but allow opening a new bin when existing residuals are dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
        // if mean residual across open bins is small (mostly dead space), new bin is fine
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins (prefer filling existing ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_residual != bin_capacity) as i32 as f64;

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Class-based tie-breaker: prefer bins whose decade class matches residual
    score -= class * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero residuals are unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual exactly, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use this gap: penalize proportional dead space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that leave large residuals when many bins are open.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 0.3;
    score += pressure * post_residual as f64;

    // New-bin candidate: mostly neutral score so it's chosen only when fits are bad,
    // but slightly discourage when a good existing fit exists.
    if bin_residual == bin_capacity {
        score = 30.0 + 0.25 * mean_residual - (fitting_bins_count as f64).min(4.0) * 2.0;
        if next_item_size > 0 && item_size <= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Reward using bins that are nearly full (tight packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or bin pressure is high.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.5;
        // Penalize opening new bin if the next item could share this bin with current item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: must open new bin
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open with slack.
    score += open_bins_count as f64 * 0.3;

    // Deviation from mean residual: prefer bins close to mean (balanced packing),
    // but allow using large-residual bins late in the stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near-match bonus: how close post_residual is to next_item_size (relative).
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score += diff * 0.6;
        // If next item fits in the post residual, reward proportionally.
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space relative to lookahead: penalize wasted gap.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins with residuals far below the mean (already fragmented),
    // reward bins that are tighter than average.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Encourage tight packing: small post_residual is good (already base score),
    // extra reward for very tight fits.
    if post_residual < 10 {
        score -= 10.0;
    }

    // New-bin candidate: default attractiveness; make it less attractive when
    // decent fitting bins exist, more attractive when this item would leave
    // a large unusable gap in any existing bin.
    if bin_residual == bin_capacity {
        let gap_penalty = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).max(0.0)
        } else {
            0.0
        };
        // New bin baseline: slightly worse than a good fit, better than bad fits.
        score = 25.0 + 0.2 * gap_penalty
            + 0.5 * (open_bins_count as f64).ln().max(0.0)
            - 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // exactly fills the post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0);
        } else {
            // Next item would NOT fit: penalize creating dead space,
            // worse when the leftover chunk is small (unusable).
            let dead = post_residual as f64;
            let deadness = if dead < 10.0 { 120.0 } else { 60.0 * (10.0 - dead / 100.0).max(0.0) };
            score += deadness;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (compact packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0) * 0.8;
    } else {
        score += (pr - mean_residual).min(50.0) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make opening a fresh bin attractive only when the
    // current item is large relative to capacity and no good chain exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; discounted when many bins already open
        // (amortized) or item is huge.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 95.0 - 40.0 * item_frac;
        if open_bins_count == 0 {
            new_bin_score = -1000.0;
        }
        // If the next item is large, a fresh bin has good future utility.
        if next_item_size > 0 {
            new_bin_score -= (next_item_size as f64 / bin_capacity as f64) * 70.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 25.0;
        // Blend: score for a new bin is essentially its own residual (full capacity)
        // plus the calibrated adjustment.
        score = score.max(0.0) * 0.0 + bin_capacity as f64 + new_bin_score - (bin_capacity as f64);
        score = bin_capacity as f64 + new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1).max(next_item_size.min(item_size)) {
        // Unusable sliver: heavy penalty scaled by how close it is to a "just barely unusable" gap.
        score += 40.0 + (bin_capacity as f64 - post_residual as f64) * 0.2;
    }
    // Penalize any residual that cannot fit the lookahead item (k=2 lookahead dead zone).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
    }
    // Reward a perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins, opening new ones is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);
    score += pressure;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to mean residual space
    // (i.e., existing bins would be shredded) or late in the stream with tight bins.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let tightness = mean_residual / bin_capacity as f64;
        let base = 45.0 + 0.5 * post_residual as f64;
        let discount = 55.0 * (fit_ratio - 0.35).max(0.0) * (1.0 - tightness).max(0.0);
        score = base - discount + pressure;
    }

    // Mild preference for bins whose residual is close to the item (best-fit sharpening).
    score += 0.15 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: exact fill leaves no dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly accommodates the next item (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // reward small slack after the hypothetical next placement
            let after_next = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize tight residuals that
            // waste space relative to the mean residual of open bins.
            score += 40.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score -= 200.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a brand-new bin when open bins fit reasonably well,
    // unless the fit into existing bins would be very poor.
    if bin_residual == bin_capacity {
        let poor_fit_threshold = bin_capacity as f64 * 0.5;
        if post_residual as f64 >= poor_fit_threshold {
            // opening a new bin is fine for large items
            score -= 60.0;
        } else {
            // discourage new bin when item fits decently elsewhere
            score += 80.0 + (open_bins_count as f64).sqrt() * 10.0;
        }
    }

    // Slight preference for tighter bins overall relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early-stream tie-break: prefer filling bins tightly when few bins open.
    if open_bins_count > 0 {
        score -= 10.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into residue buckets mod small numbers.
    // Leftovers <= 10 are near-dead space (items are >= 1 but large items common); penalize heavily.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 60.0; // near-dead space
    } else if pr <= 20 {
        score += 15.0;
    }

    // Modulo-class analysis: leftover congruence classes that pair well with common item sizes.
    // If next item can exactly fill the leftover, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr {
            let after2 = pr - next_item_size;
            if after2 <= 10 {
                score += 40.0; // would create near-dead space for the item after
            } else {
                score -= 30.0; // leftover reusable by lookahead
            }
            // harmonic class: leftover divisible into halves/quarters of capacity
            if pr % 25 == 0 || pr % 20 == 0 || pr % 50 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's leftover: leftover is frozen for at least one step
            score += 25.0;
            if pr <= 30 {
                score += 30.0; // frozen small leftover is very bad
            }
        }
    } else {
        // last item: just prefer tight packing
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize unless current bins are all tight or item is huge
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fit win
        score += 120.0;
        // but if item is large relative to mean residual, opening fresh is fine
        let mean_r = mean_residual;
        if (item_size as f64) > mean_r {
            score -= 80.0 * ((item_size as f64 - mean_r) / bin_capacity as f64);
        }
        // early in stream, new bins are cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Prefer bins already below mean residual (consolidating small leftovers)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Integer-division threshold: leftover >= 50 is half a bin, still very usable
    if pr >= 50 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2) when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if lookahead item can no longer fit anywhere after this placement.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only if this bin would leave bad dead space
    // and mean residual across open bins is already low.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual < 20 { 40.0 } else { 0.0 };
        score -= 10.0 - dead_space_penalty + mean_residual * 0.3;
    }

    // Slight stream-progression tiebreaker.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space quadratically, modulated by stream progress.
    let mut score = post * (1.0 + 1.5 * progress * x);

    // Smooth polynomial coupling: reward tight fits more as stream progresses.
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post residual (smooth ramp).
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let fit_deg = ((x - nx) / cap).max(0.0);
        score -= 10.0 * (-fit_deg * 8.0).exp() * (1.0 - progress * 0.5);
        // Penalize post residual that is too small for the next item (dead space).
        if x < nx {
            score += 6.0 * (nx - x) * cap * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
