    let waste = pr / cap;
    score += 12.0 * waste * waste * waste * waste * cap;

    // Reward tight fits (small post_residual) with smooth coupling to stream progress
    let tightness = 1.0 - waste;
    score -= 8.0 * tightness * tightness * (1.0 + 2.0 * progress);

    // Lookahead coupling: favor residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 4.0 * (1.0 - slack * slack) * (1.0 + progress);
        } else {
            // post-residual cannot fit next item: penalize proportionally to shortfall
            let gap = (nx - pr) / nx;
            score += 5.0 * gap * gap * cap * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
