    let dev = (mean_residual - pr) / cap;
    score += 2.0 * dev * dev * cap;

    // New-bin candidate: keep it competitive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = cap + 6.0 * (1.0 - progress) * open_bins_count as f64 - 2.0 * crowding;
        if fitting_bins_count == 1 {
            score += 25.0; // never open a new bin when a unique last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item perfectly fills bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward near-exact matches with next item (tight 2-step packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
