    // Reward bins whose post residual exactly or nearly fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so it is only
    // chosen when open bins would create large waste.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, opening new bins is more costly (fewer items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Global state coupling: prefer bins below mean residual when many bins are open
    // (balances load and keeps larger residuals consolidated).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 5.0 * dev;
    }

    // Time horizon: early on, be greedy for tight fits; late, avoid fragmenting
    // residuals that can never be filled.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let frag_penalty = if post_residual < 10 { 8.0 * (1.0 - progress) } else { 2.0 * (1.0 - progress) };
    score += frag_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 24.0 * pr_norm * pr_norm * (1.0 + progress)
        - 30.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Reward tight fits more strongly later in the stream
    score -= (fit_ratio * pr_norm) * 40.0 * (0.5 + 0.5 * progress);

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 18.0 * last_chance * (0.3 + 0.7 * progress);

    // Penalize bins far from mean residual (fragmentation smoothing)
    score += 0.08 * (pr - mean_residual).abs();

    // Lookahead: reward residual that fits the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score -= 12.0 * (1.0 - gap / cap) * (1.0 - progress);
        score += 6.0 * (gap / cap) * (1.0 - progress);
    }

    // Slight penalty for many open bins to encourage consolidation early
    score += 0.5 * open_bins_count as f64 * pr_norm * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    match class {
        0 => score -= 30.0,                       // near-perfect fit class
        1 => score -= 10.0,                       // good class
        2 => score += 8.0,                        // mediocre class
        _ => score += 20.0,                       // large dead space class
    }

    // Reward when next item exactly or near fills the post-residual (harmonic pairing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= quarter / 2 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // next item can't use this bin's leftover; penalize proportionally
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize unless current bin would leave big dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.05;
    }

    // Penalize wasting a large residual on a small item (integer division threshold).
    if post_residual > bin_capacity / 2 && item_size < bin_capacity / 4 {
        score += 15.0;
    }

    // Progress coupling: late in stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Prefer bins with residual close to mean (balanced harmonic spread).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual as i32).abs() as f64 * 5.0;
    } else if post_residual < 20 {
        // Medium-small gaps: mildly risky, only usable by small items.
        score += 8.0;
    } else {
        // Large usable residuals are good; reward them.
        score -= 6.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // this placement sets up a chain; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item nearly fits but leaves a tiny remainder, penalize slightly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score += 6.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading items;
    // with few open bins, opening a new bin is cheaper so add pressure to
    // existing bins only mildly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (3.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure so new bins are
        // opened only when existing fits are bad (dead space, poor fit).
        score += 25.0 + pressure;
    } else {
        score += pressure * 0.5;
    }

    // Prefer bins whose residual is below the mean (consolidation into
    // emptier-of-space / tighter bins keeps other bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for tighter fits overall (fit ratio).
    score += (item_size as f64 / bin_residual.max(1) as f64) * -5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item would leave a tiny remainder.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (-slack / 12.0).exp();
    }
    // Penalize residuals too small for the next item (dead space) more when small.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 1.5 * dead;
    }

    // Reward tight fits relative to mean residual.
    let tightness = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host both items
        }
    }

    // Early in stream: keep bins flexible (prefer larger residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // nothing can ever use is worse. Penalize residuals that are too small
    // to be useful (below the minimum plausible item size of 1, scaled up).
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_ratio * waste_ratio; // quadratic dead-space penalty
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot follow here: slight penalty if we leave
            // a gap that is "almost" but not quite the next item.
            let miss = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.15 * miss;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin should only win when the item
    // is large relative to capacity (a "cornerstone" item) or when open
    // bins are already quite full on average.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        let pressure = mean_residual / bin_capacity as f64; // high = bins full
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Reward new bin for big items or under pressure; penalize otherwise.
        score -= 20.0 * fill + 15.0 * pressure - 10.0 * (1.0 - pressure);
        // Late in the stream, avoid spawning bins that end mostly empty.
        score += 10.0 * progress * (1.0 - fill);
        // Many open bins already: discourage proliferation.
        score += 0.5 * open_bins_count as f64 * (1.0 - fill);
    } else {
        // Favor fuller bins (best-fit flavor) beyond raw post_residual:
        // reward using a large fraction of the bin's current residual.
        let usage = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * usage;
        // Slight preference for bins below the mean residual (balancing),
        // so very empty bins get used before they fragment.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Global pacing: early in the stream, be liberal (open bins freely to
    // keep options); late, be frugal and squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual
    let r = post_residual as f64 / cap;

    // Non-linear polynomial coupling: waste penalty grows superlinearly
    // and is modulated by stream progress.
    let waste = r * r * (1.0 + 2.0 * progress);
    score += 60.0 * waste;

    // Sweet spot coupling: residuals near half capacity are valuable later in stream
    let half = 0.5;
    let deviation = (r - half) * (r - half);
    score -= 40.0 * (1.0 - progress) * deviation;
    score += 25.0 * progress * deviation;

    // Tight fit reward, smoothed with progress
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * (0.5 + 0.5 * progress);

    // Last-chance bonus (smooth sigmoid-like on fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - progress);
    }

    // Lookahead: penalize if next item can't use the post residual
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0) / cap;
        score += 50.0 * gap * gap;
    }

    // Mean residual divergence penalty (smooth quadratic)
    let div = (post_residual as f64 - mean_residual) / cap;
    score += 20.0 * div * div;

    // New-bin candidate: mild penalty so it's chosen only when clearly better,
    // penalty fades as stream progresses (favor consolidation early).
    if bin_residual == bin_capacity {
        score += 15.0 + 35.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core)
    score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into
    // integer-division buckets. Leftovers in the smallest buckets
    // (0..=10, i.e. "dead space") are worthless; larger leftovers
    // that can still host future items (>= next_item_size) are valuable.
    let pr = post_residual;
    let class = pr / 10; // harmonic bucket 0..=10
    match class {
        0 => score -= 25.0,           // near-perfect fit, tiny dead space
        1 => score -= 10.0,           // good fit
        2 => score -= 4.0,            // decent
        3 => score += 3.0,            // mediocre leftover
        4 | 5 => score += 6.0,        // half-empty bin
        _ => score += 10.0,           // barely touched bin
    }

    // Reward when the leftover can exactly host the lookahead item:
    // harmonic pairing of post_residual with next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if pr == nxt {
            score -= 18.0; // perfect two-item chain
        } else if pr >= nxt {
            // leftover is reusable by the next item; scale bonus by slack
            let slack = (pr - nxt) as f64;
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // leftover too small for the next item: penalize dead space
            score += (nxt - pr) as f64 * 0.15;
        }
    }

    // Modulo arithmetic on capacity fractions: items that fill exact
    // fractions of the bin (e.g. 50, 25, 20) create harmonically
    // composable leftovers; reward placements keeping residual divisible
    // by common item-friendly units.
    if pr > 0 && (pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0) {
        score -= 5.0;
    }
    // Odd, awkward residuals (prime-ish, not divisible by 5/10) are
    // harder to fill later.
    if pr > 0 && pr % 10 != 0 {
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin
    // fits well. Make the empty bin score = "moderate", so tight fits
    // in existing bins always win, but poor fits (large post_residual
    // relative to capacity) lose to a fresh bin.
    if bin_residual == bin_capacity {
        // fresh bin leaves full capacity; score it relative to mean
        // residual of open bins: if open bins are mostly full (small
        // mean residual), opening fresh is fine.
        score = cap * 0.55 - mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced: nothing fits elsewhere
        }
        if open_bins_count == 0 {
            score -= 20.0; // must open the first bin
        }
    }

    // Stream progression: late in the stream, consolidate aggressively
    // (avoid opening new bins), reward using existing bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a tighter-than-average bin keeps looser bins flexible.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 6.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items (<= 10) are effectively wasted space.
    if post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure is ideal
    }

    // Reward tight fits: fraction of the bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Penalize leaving a gap that is "awkward": large enough to waste,
    // but too small for the lookahead item to reuse.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // gap can't serve the next item
        }
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 12.0; // gap is a near-perfect match for the next item
        }
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit, or when open-bin pressure is low.
    if bin_residual == bin_capacity {
        // Mild penalty so existing bins with good fits are preferred,
        // but discounted when many bins are already open.
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 25.0 - 6.0 * pressure;
        // If the item is large relative to capacity, opening a fresh bin
        // is more attractive (avoids fragmenting a partially filled bin).
        if item_size as f64 / cap > 0.6 {
            score -= 10.0;
        }
        // Last-chance avoidance: if several bins fit, don't open a new one.
        if fitting_bins_count > 2 {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: discourage spreading items across many bins
    // when residuals are already plentiful.
    let avg_gap = if open_bins_count > 0 { mean_residual } else { 0.0 };
    if avg_gap > item_size as f64 * 1.5 {
        score += 5.0; // plenty of slack elsewhere; prefer tightest fit
    }

    // Slight late-stream tightening: as the stream progresses, prefer
    // closing bins out to reduce the count of lingering residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it attractive only when nothing else fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly, but softened when the current item
        // fits poorly anywhere (few fitting bins) or bins are already fragmented.
        let scarcity = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        let fragmentation = (open_bins_count as f64).ln().max(0.0) * 4.0;
        score = 100.0 - scarcity - fragmentation;
        // If the next item perfectly fills this fresh bin after the current one,
        // strongly encourage opening it (post_residual == next_item_size after placing item).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
        return score;
    }

    // --- 2-step lookahead matching for existing bins ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: next item exactly fills the leftover space.
        if diff < 0.5 {
            score -= 45.0;
        } else {
            // Gradual reward as post_residual approaches next_item_size.
            score -= 20.0 * (-diff / 15.0);
        }
        // Penalize leaving a residual that is too small for the next item
        // (dead space unless future tiny items arrive).
        if post_residual < next_item_size && post_residual > 0 {
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
        }
        // Bonus if next item fits this bin's post-residual AND current fit is tight.
        if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Tightness reward: small post_residual generally means efficient packing.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual across open bins: placing into a bin whose
    // residual is below average concentrates waste and preserves large gaps.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Early in the stream, allow slightly looser packing to build structure;
    // later, be stricter about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: strong reward for tight fits.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to the lookahead item
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strong incentive to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it when all open fits would waste a lot of space.
    if bin_residual == bin_capacity {
        let waste = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        score += 30.0 - 0.8 * waste;
        // early in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer filling bins with large residuals when many bins are open (bin consolidation).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Mild reward for placing large items (hard to place later).
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) sharpening
    let mut score = post + 40.0 * norm_post * norm_post * cap;

    // Smooth coupling: early in stream, tolerate larger residual slack;
    // late in stream, strongly avoid wasted space (cubic in progress)
    let progress_bias = 0.5 * (progress - 0.5) * (progress - 0.5) * (progress - 0.5) * cap;
    score += progress_bias * (1.0 - norm_post) - progress_bias * norm_post;

    // Tight-fit reward: smooth Gaussian-like bump when post_residual is small
    let tightness = (-norm_post * norm_post * 12.0).exp();
    score -= 15.0 * tightness;

    // Penalize dead space that likely can't fit typical items: smooth sigmoid on norm_post
    let dead = 1.0 / (1.0 + (-(norm_post - 0.35) * 10.0)).exp();
    score += 10.0 * dead;

    // Lookahead: reward if next item fits in post residual (smooth coupling)
    if next_item_size > 0 {
        let fits_next = (post - next_item_size as f64).max(0.0) / cap;
        let next_norm = next_item_size as f64 / cap;
        score -= 12.0 * (1.0 - fits_next) * next_norm * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it (smooth reward scaled by scarcity)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_item);
    }

    // Mild penalty when many bins are open and this bin is very full (fragmentation)
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_pressure * norm_post * (1.0 - progress);

    // Deviation from mean residual: prefer bins near mean (smooth)
    let dev = (mean_residual - post) / cap;
    score += 3.0 * dev * dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into residue classes.
    // Small residuals (< 10) are dead space — heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 3.0;
    }

    // Perfect-fit harmonic classes: residuals divisible by common item sizes
    // (10, 20, 25, 50) are reusable by future items — reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }
        if post_residual % 50 == 0 {
            score -= 10.0;
        }
    } else {
        // Exact fill is ideal.
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        } else {
            // next item fits: reward if the leftover after next item is small
            let after = post_residual - next_item_size;
            score -= (post_residual - after) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Prefer it only
    // when the item would leave awkward space in existing bins.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 10.0;
        // If mean residual of open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.3;
        // When many bins already fit the item, definitely don't open a new one.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Small items can pair later; medium/large items justify fresh bins more.
        if item_size > 50 {
            score -= 8.0;
        }
    }

    // Tight-fit bonus: item filling most of the bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Penalize bins whose residual deviates far below the mean (fragmentation).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is good, but non-linearly).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Strict dead-space avoidance: penalize unusable gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range, assume min ~10)
    // or smaller than the next item's size (lookahead).
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 45.0; // unusable sliver
    }
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // gap can't hold the next item: dead space risk, worse when small
            let gap_ratio = post_residual as f64 / next_item_size as f64;
            score += 25.0 * (1.0 - gap_ratio);
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
            // next item fits snugly afterwards: reward this pairing
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= min_item {
            score -= 20.0; // still nearly-full after placement
        }
    }

    // Open-bin pressure: with many open bins, avoid spreading into fresh bins;
    // with few open bins, allow mild preference for tighter fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Slight preference for bins below mean residual (keeps residuals uniform,
    // preserving flexibility), but only when not a last-chance fit.
    if bin_residual as f64 > mean_residual && fitting_bins_count > 1 {
        score += 3.0;
    }

    // New-bin candidate: only attractive when current fit would be very poor
    // (large dead space) — otherwise strongly penalize opening new bins.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        if fit_quality > 0.7 {
            // item is small relative to capacity; new bin is acceptable
            score -= 5.0;
        } else {
            score += 40.0; // discourage wasting a fresh bin on a large item
        }
        score += pressure * 3.0;
    }

    // Mild progression term: later in the stream, be more conservative (fill existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fit relative to mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // 2-step lookahead: reward bins whose post residual accommodates the next item exactly or well.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // next item fits here: reward closeness of post_residual to next_item_size
            score -= 40.0 * (1.0 - ((post_residual as f64 - n) / cap).min(1.0));
            // perfect chain (post_residual == next_item_size) gets big bonus
            if post_residual as u32 == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item cannot follow here: penalize dead space that is too small to be useful
            if post_residual > 0 {
                score += 8.0 * (1.0 - (post_residual as f64 / cap));
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so we only open bins when existing ones are poor fits,
    // but allow it when residuals are all large (item fits badly everywhere).
    if bin_residual == bin_capacity {
        score += 15.0;
        // If lookahead chains well into a fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual as u32 >= next_item_size {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount bins where post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.25;
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the next item too.
            score -= 3.0;
        }
    } else {
        // Last item: just minimize post_residual aggressively.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // When many bins are open, encourage consolidation (prefer existing bins
    // over opening new ones) to reduce fragmentation.
    let open_frac = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 4.0 * open_frac;

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (keep residuals large for future large items); late in the stream,
    // pack tightly into whatever exists.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late.
        score += 10.0 * progress - 6.0 * (1.0 - progress);
        // A new bin is good if the item is large and lookahead item is large too.
        score -= 0.05 * item_size as f64;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // Large next item: fresh bin with big residual is valuable.
            score -= 4.0;
        }
    } else {
        // Existing bins: late in stream, discount them more (pack tightly).
        score -= 5.0 * progress * tightness;
    }

    // Compare bin residual against mean residual across open bins:
    // prefer bins with below-average residual (the fullest bins).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 6.0 * dev;

    // Mild penalty for very large post_residual on existing bins (wasteful placement).
    if bin_residual != bin_capacity && post_residual > bin_capacity / 2 {
        score += (post_residual - bin_capacity / 2) as f64 * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: quadratic dead-space penalty
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling with stream progress
    let t = progress;
    score -= 30.0 * t * (1.0 - t) * pr_norm;      // mid-stream: prefer tight fills
    score += 25.0 * t * t * pr_norm;              // late stream: penalize leftovers more

    // Interaction: post_residual vs mean residual (fragmentation context)
    let mr_norm = mean_residual / cap;
    score += 15.0 * (pr_norm - mr_norm) * (pr_norm - mr_norm);
    score -= 10.0 * pr_norm * mr_norm;

    // Lookahead coupling (smooth): reward residual that fits next item well
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns).abs() / cap;
        score += 20.0 * fit_gap * fit_gap;
        score -= 8.0 * (1.0 - fit_gap) * (pr_norm * (1.0 - pr_norm));
    }

    // Last-chance bonus (smooth sigmoid-like)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild new-bin preference early vs late
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - t) * (1.0 - t);
    }

    // Encourage using existing bins as open count grows
    score += 2.0 * (open_bins_count as f64).sqrt() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    let q = post_residual / (bin_capacity / 10); // class 0..=9
    score -= 12.0 * (q as f64); // reward larger residual classes (better fill)

    // Exact-fill harmonic bonus: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: small unusable residual classes (1..=9) are wasted space.
    if post_residual >= 1 && post_residual <= 9 {
        score += 20.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward proportional to how well it fills
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize leaving medium residuals that trap nothing
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * (open_bins_count as f64);
        // but if all residuals are tiny (fragmented), opening fresh bin is fine
        if mean_residual < 10.0 {
            score -= 25.0;
        }
    }

    // Mean-residual alignment: prefer bins close to the mean residual (harmonic balance).
    score += 0.2 * ((bin_residual as f64) - mean_residual).abs();

    // Late-stream tightening: as stream progresses, be greedier about fill quality.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (q as f64);

    // Modulo texture: residual divisible by common item sizes (10,20,25,50) pairs well.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        // Dead space: leftover too small for the smallest plausible item.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        } else if post_residual < next_item_size as f64 && next_item_size > 0 {
            // Gap cannot fit the next item: likely dead space.
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward a bin that can still fit the next item after placement.
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // (especially when this is the only fitting bin).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    score += open_bins_count as f64 * 0.5;

    // Late in the stream, consolidation matters more: penalize waste harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.3 * progress;

    // New-bin candidate: mildly penalize so we only open when open bins are bad.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step chain: item fills bin, next item fills remainder.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial lookahead credit: next item can still fit in the leftover.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit: leftover is dead space relative to lookahead.
        score += 15.0 + 0.25 * post_residual as f64;
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64).min(50.0) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual).min(50.0) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when existing bins could fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0;
        } else {
            score -= 10.0;
        }
        // Early in stream, slightly discourage hoarding new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference to keep large residuals for large future items.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
