pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 6.0 * prn * prn * (0.5 + 2.0 * progress) * cap;
    score -= 4.0 * prn * (1.0 - p2) * cap;
    score += 3.0 * prn * p3 * cap;

    // Penalize dead space relative to mean residual, smoothly
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        let fits = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 8.0 * fits * (0.5 + 0.5 * progress);
        // penalize residual just barely too small for next item
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 && gap < 20.0 {
            score += 0.4 * (20.0 - gap) * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space that is too small to be
    // useful for typical items is heavily penalized.
    // Classes (integer division thresholds on post_residual):
    //   0        -> perfect fit (best possible)
    //   1..=9    -> near-perfect, small penalty
    //   10..=19  -> can hold small items (10..20 class)
    //   20..=39  -> moderately useful
    //   >=40     -> still flexible, mild penalty
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 9 {
        score -= 25.0;
    } else if post_residual <= 19 {
        score -= 12.0;
    } else if post_residual <= 39 {
        score -= 5.0;
    } else {
        score -= 0.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward; if it cannot fit at all, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward tight chains: next item leaves a small remainder again
            let rem = post_residual - next_item_size;
            let chain_bonus = if rem <= 9 { 18.0 } else if rem <= 19 { 12.0 } else if rem <= 39 { 6.0 } else { 2.0 };
            score -= chain_bonus;
        } else {
            // next item won't fit here: dead-space risk grows with the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 60 {
        score -= 30.0;
    }

    // Prefer bins whose residual is already below the mean (consolidating
    // fragmentation into few bins) using a capacity-fraction coupling.
    let frac = post_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    if frac < mean_frac {
        score -= (mean_frac - frac) * 15.0;
    } else {
        score += (frac - mean_frac) * 8.0;
    }

    // Modulo-arithmetic harmonic penalty: residuals that align with common
    // item sizes (multiples of 10, and 25/50/75) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let harmonic = if pr % 10 == 0 { 10.0 }
            else if pr % 25 == 0 { 8.0 }
            else if pr % 5 == 0 { 5.0 }
            else { 0.0 };
        score -= harmonic;
    }

    // Late in the stream, be more aggressive about tight packing (waste matters
    // more); early on, keep bins flexible.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (60.0 - post_residual as f64).max(0.0) * 0.1;

    // New-bin candidate: only attractive when current bin fits are all bad
    // (high post_residual relative to capacity) or many bins already open.
    if bin_residual == bin_capacity {
        score = 55.0 + frac * 40.0 + (open_bins_count as f64).sqrt() * 2.0 - progress * 10.0;
        if fitting_bins_count == 1 {
            score += 25.0; // discourage abandoning the sole fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can't fit even the smallest
    // future item (size 1..100 unknown, assume min ~10) are pure waste.
    let min_future = 10u32;
    if post_residual > 0 && post_residual < min_future {
        score += 60.0; // unusable dead space
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fits (small leftover) are good; large leftovers waste capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Penalize leaving a gap that could fit the known next item awkwardly:
    // if post_residual < next_item_size but next item is large, this bin
    // becomes a dead-end for the lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few,
    // filling existing bins is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current residuals are large
    // (poor fits everywhere) — otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 30.0 - 0.2 * mean_residual;
        if mean_residual < item_size as f64 {
            score -= 20.0; // no bin can usefully absorb; new bin is fine
        }
    }

    // Slight preference for bins whose residual deviates from mean
    // (consolidate small residuals together).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: small gap between post_residual and next item size.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            // Bin can still host the next item: reward closeness.
            score -= (60.0 / (1.0 + gap)).min(50.0);
        } else {
            // Dead space relative to the lookahead item: penalize the shortfall.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare post_residual against mean residual: leaving typical slack is good.
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Discourage leaving tiny unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: default competitive baseline, adjusted by stream phase
    // and how fragmented existing bins are.
    if bin_residual == bin_capacity {
        score = 45.0
            - 30.0 * (step_index as f64 / total_items.max(1) as f64)
            - 0.3 * mean_residual;
        // If some open bin achieves a perfect lookahead match, keep the new bin out.
        if next_item_size > 0 && post_residual == next_item_size {
            score += 2000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit tightness: reward near-full packing (small post_residual).
    let fit_tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fit_tightness * fit_tightness;

    // Lookahead: strongly reward if the NEXT item exactly fills the leftover space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining of two items
        } else if next_item_size <= post_residual {
            // leftover usable by next item: reward proportionally to how much it consumes
            let use_frac = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * use_frac;
        } else {
            // leftover too small for next item: penalize dead space, worse if very small
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 10.0; // tiny unusable sliver
            } else {
                score += 4.0 * (1.0 - waste / 40.0).max(0.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no tight fit exists among open bins.
    if bin_residual == bin_capacity {
        // Penalize opening new bins generally; more so late in the stream or with few open bins.
        score += 20.0 + 15.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Global state coupling: many open bins with low mean residual -> prefer consolidating
    // into bins that bring residual toward the mean (reduce fragmentation spread).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for packing into bins with larger pre-existing residual when
    // many bins are open (balance load across bins, keep small residuals for small items).
    if open_bins_count > 3 {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: early in stream, be pickier about waste (long future to regret it);
    // late in stream, accept decent fits more readily.
    score *= 0.8 + 0.4 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly scaled by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling: dead space penalty grows super-linearly,
    // and its strength increases as the stream progresses.
    let dead = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 120.0 * dead * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in stream.
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 40.0 * progress;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 15.0 + 20.0 * snug * progress;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving large unusable gaps.
        score += 10.0 * (pr / cap) * (pr / cap);
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps bin states balanced), smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev;

    // Congestion: with many open bins, slightly favor consolidation.
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity-fraction bands.
    let quarter = bin_capacity / 4;
    let post_class: u32 = if post_residual == 0 { 0 }
        else if post_residual < quarter { 1 }
        else if post_residual < 2 * quarter { 2 }
        else if post_residual < 3 * quarter { 3 }
        else { 4 };
    // Dead-space penalty grows super-linearly for mid classes (worst: half-empty leftovers)
    score += match post_class {
        0 => -8.0,                    // perfect fit, strongly rewarded
        1 => 2.0,                     // small leftover is fine
        2 => 9.0,                     // half-full leftover is wasteful
        3 => 5.0,
        _ => 0.0,                     // near-empty bin leftover ~ new bin anyway
    };

    // Exact modulo arithmetic: reward post_residual that is a "harmonic" divisor-friendly value
    // (leftover divisible by 25 or 20 pairs well with common item sizes).
    if post_residual > 0 && (post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0) {
        score -= 3.0;
    }
    // Penalize awkward leftovers: prime-ish residues > 5 that few sizes can use
    if post_residual > 5 && post_residual % 10 != 0 && post_residual % 5 != 0 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mildly penalize leaving big gaps it could have used elsewhere
            score += 1.5;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it attractive only when existing bins would leave bad residues.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: keep it slightly worse than a decent fit.
        score = cap * 0.75;
        // But if current bin's post_residual is terrible, allow opening.
        if post_class >= 2 && post_residual > 0 {
            score -= (post_residual as f64) * 0.35;
        }
        // Late in the stream, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
        // Many open bins: discourage opening more.
        score += open_bins_count as f64 * 1.2;
    }

    // Prefer filling bins that are already mostly full (tighten with mean residual context).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 4.0 * fill_ratio;
    if (bin_residual as f64) < mean_residual {
        score -= 1.0; // tighter-than-average bin gets priority
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..=100 interface range, but items >= 10 typical) are
    // wasted space. Penalize sharply when post_residual is a "dead gap":
    // small but nonzero, unusable by the next item.
    if post_residual > 0 {
        let dead_threshold = 10.0f64.min(next_item_size as f64);
        if (post_residual as f64) < dead_threshold {
            // Unusable sliver: heavy penalty proportional to how close
            // it is to being perfectly wasted.
            score += 40.0 * (1.0 - (post_residual as f64) / dead_threshold.max(1.0));
        }
    }

    // Reward near-perfect fits: post_residual close to zero is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Reward bins whose residual the NEXT item could consume exactly,
    // turning this placement into a two-item completion.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Bin stays viable for lookahead item: mild reward.
        score -= 4.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Lookahead item cannot use this bin's remainder: mild penalty.
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; discourage opening new bins
    // unless the fit is genuinely good.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has no dead space yet.
    // Only prefer it when the current item would leave a bad gap in every
    // existing bin (approximated by mean_residual pressure and poor fit).
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // New bin is attractive for large items or when open bins are tight.
        let open_tightness = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            1.0
        };
        if fit_quality > 0.6 || open_tightness < item_size as f64 / bin_capacity as f64 {
            score -= 18.0 + 15.0 * fit_quality;
        } else {
            // Existing bins can absorb it: make new bin unattractive.
            score += 25.0 + 10.0 * pressure;
        }
    }

    // Mild stream-progression term: later in the stream, closing bins
    // tightly matters more, so tighten the dead-space penalty.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 10.0 * progress;
    }

    // Prefer bins with residual already below mean (consolidate small bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step chain: this bin will be exactly filled by the next item
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + slack / 20.0);
        } else {
            // Next item won't fit here afterwards; penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 15.0 * (overshoot / 40.0).min(1.5);
        }
    } else {
        // Last item: tightest fit is best
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // Penalize leaving large unusable dead space (nothing left for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless sliver
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for bins with more open competition (keep flexibility)
    if fitting_bins_count > 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor the last bin that can fit the item (avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.5 * next_item_size as f64;
    }
    // Penalize leaving a residual that is too small for any plausible item (dead space).
    if post_residual > 0 && next_item_size > post_residual {
        score += 0.3 * post_residual as f64;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 200.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin when
    // existing bins fit, unless residuals are all tight (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // When open bins are fragmented (low mean residual), opening a fresh bin
        // becomes more attractive late in the stream.
        score += 30.0 - 40.0 * (1.0 - fragmentation) - 20.0 * progress;
        // If no open bin can fit, opening is necessary: make it cheap.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Prefer packing into bins with larger residuals when residuals are plentiful
    // (best-fit bias modulated by global mean).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Mild time pressure: later in the stream, consolidate harder.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * t * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Core: quadratic penalty on wasted space, amplified as stream progresses.
    let mut score = pr * pr / cap;

    // Tight fit reward: smooth coupling of post_residual with item size.
    score -= (cap - pr) * (item_size as f64 / cap) * 0.5;

    // Smooth progress interaction: later in the stream, waste hurts more.
    score += pr * (0.5 + 1.5 * progress * progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here anyway; slightly penalize leaving medium gaps.
        score += 2.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score = cap * (1.0 - tightness) * (0.6 + 0.8 * progress) - 6.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 20.0; // forced new bin
        }
    }

    // Mild diversity pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;

    // Anchor to mean residual: bins far below average waste are preferable.
    score -= (mean_residual - pr) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items come in size bands
    // (1..=20 small, 21..=50 medium, 51..=80 large, 81..=100 huge).
    // A post_residual is only "usable" if a plausible future item fits in it.
    let usable = |r: u32| -> bool {
        (r >= 1 && r <= 20) || (r >= 21 && r <= 50) || (r >= 51 && r <= 80) || r == 0
    };

    if post_residual == 0 {
        // Perfect closure: best possible outcome.
        score -= 1000.0;
    } else if usable(post_residual) {
        // Reward leftovers that match a harmonic class band, scaled by band depth.
        let band = if post_residual <= 20 { post_residual as f64 }
                   else if post_residual <= 50 { (post_residual - 20) as f64 }
                   else { (post_residual - 50) as f64 };
        score -= 30.0 + band * 0.5;
    } else {
        // Dead space: leftover that no future item can plausibly consume.
        score += 40.0 + 0.3 * post_residual as f64;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if usable(chain_left) {
                score -= 80.0 - 0.5 * chain_left as f64;
            } else {
                score += 20.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by gap.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is fine early or when
    // many bins are open and mean residual is already fragmented, but
    // penalize it when existing bins have room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0
            - 100.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0))
            - 50.0 * progress
            + (mean_residual / cap) * 60.0;
        // A new bin is attractive if the item is huge (poor fit elsewhere likely).
        if item_size >= 81 { score -= 60.0; }
    } else {
        // Prefer bins whose residual is close to the item (tight fit),
        // using integer-division threshold classes on residual.
        let tightness = bin_residual - item_size;
        let class = tightness / 10; // harmonic decade class
        score += class as f64 * 2.0;
    }

    // Mild preference to spread load when many bins are open and mean residual is high.
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0 + (dead_threshold - post_residual) as f64 * 20.0;
    }

    // Gap that cannot fit the known next item is partially wasted; penalize
    // proportionally to how close it is to fitting (near-miss is worst).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        score += 40.0 + 3.0 * miss;
    }
    // Perfect lookahead fit: strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0; // still reusable for the next item
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // consolidating into existing bins; when few, opening new bins is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 2.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus open-bin pressure.
        score = bin_capacity as f64 + pressure * 8.0;
        // Early in the stream, opening bins is more acceptable.
        score -= 30.0 * (1.0 - progress);
        // If no open bin fits well (large dead-space risk elsewhere handled by
        // their scores), a fresh bin with full residual is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    } else {
        // Fitting into an existing bin reduces open-bin pressure.
        score -= pressure * 4.0;
        // Prefer bins whose residual is close to the item (tight fit),
        // measured against the mean residual of open bins.
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 20.0 * tightness;
        // Penalize bins far below mean residual (fragmented bins).
        if (bin_residual as f64) < mean_residual - 20.0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 500.0; // perfect chaining: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= (30.0 - diff.min(30.0)) * 2.0; // closer match => better reward
        } else {
            // next item cannot fit here; penalize proportionally to wasted gap
            score += diff * 1.5;
        }
    }

    // Relative-to-mean-residual term: prefer bins that are already "tight"
    // (below-average residual) so loose bins stay available for big items.
    score += (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 120.0;
        // If no open bin fits (this call is the only candidate), make new bin cheap.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Early in stream, opening bins is cheaper (build flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
        // If next item is large and this item is small, a fresh bin wastes capacity.
        if next_item_size > 0 && next_item_size > item_size * 2 {
            score += 60.0;
        }
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small unusable sliver is fine (item min size 1..100 unknown, mild)
    }

    // Lookahead: bonus if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residual already below average (consolidate waste).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be conservative about filling bins; later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Many open bins: discourage spreading; few open bins: mild encouragement to reuse.
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere (large item, poor tightness) or late in the stream
    // with few open bins.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        let new_bin_score = 30.0
            - 20.0 * (1.0 - poor_fit_penalty)
            - 15.0 * progress
            - 3.0 * open_bins_count as f64;
        // Anchor new-bin score near typical scores of poor fits.
        score = new_bin_score.max(0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), scaled by smooth progress coupling
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - norm_pr));

    // Non-linear polynomial coupling: dead-space penalty grows superlinearly as residual shrinks
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Mild penalty when bin is far from mean residual (encourage balanced fills)
    score += 0.05 * ((pr - mean_residual) * (pr - mean_residual)) / cap;

    // New-bin candidate: penalize mildly early, more when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * fitting_bins_count as f64 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead zones" (residuals that few items can ever fill) are penalized.
    // Dead zones: post_residual in 1..=9 (too small for min item 1.. but
    // items are 1..100, so use finer classes): class by integer division.
    let post = post_residual;
    let cls = post / 10; // harmonic class 0..=10
    match cls {
        0 => { score += 0.0; }                       // near-perfect fit
        1 => { score -= 6.0; }                       // leftover 10..19: often reusable
        2 => { score -= 3.0; }                       // 20..29
        3 => { score += 2.0; }                       // 30..39: awkward
        4 => { score += 5.0; }                       // 40..49: dead-ish
        5 => { score += 8.0; }                       // 50..59: half-empty penalty
        6 => { score += 10.0; }
        7 => { score += 12.0; }
        8 => { score += 14.0; }
        9 => { score += 16.0; }
        _ => { score += 18.0; }                      // 100: untouched bin
    }

    // Exact-fill reward
    if post == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or in the same harmonic class.
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= post {
            let gap = post - nx;
            if gap == 0 {
                score -= 40.0;                       // next item fills bin exactly
            } else if gap <= 10 {
                score -= 12.0;                       // near-exact follow-up
            } else {
                // penalize if leftover after next item lands in a dead class
                let gcls = gap / 10;
                score += gcls as f64 * 1.5;
            }
        } else {
            // next item cannot fit here: residual must stay attractive
            score += 4.0;
        }
    }

    // Prefer bins whose residual is below mean (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild pressure to close bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 2.0 * (1.0 - progress));

    // New-bin candidate handling: only open a new bin if all open fits are bad
    if bin_residual == bin_capacity {
        score = 60.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            score += 100.0;                          // never open when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score += 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item are pure waste; penalize them super-linearly.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 && post_residual > 0 {
        score += 40.0;
    }
    // Dead space that cannot fit the lookahead item either is doubly wasted.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Fractional tightness reward: smaller post_residual relative to capacity.
        score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Open-bin pressure: with many open bins, avoid opening new ones
    // (penalize the empty-bin candidate implicitly since its post_residual is large).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the fit in existing bins would be very poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If mean residual across open bins is small (all bins nearly full),
        // opening a new bin is reasonable; soften the penalty.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: compare post_residual against next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: item now, next item exactly fills bin.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.25;
        } else {
            // Dead space: next item cannot use the remaining room.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.6;
            // Extra penalty if dead space is small-but-unusable (worst waste zone).
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Prefer tight fits relative to the mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Compare post_residual to mean residual: leaving less than average is good.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut open_bonus = 0.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            open_bonus = 30.0; // fresh bin reserves space for next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0 + open_bonus; // forced: no open bin fits
        } else {
            score += 55.0 - open_bonus; // discourage abandoning a fitting bin
        }
    }

    // Late in the stream, close out bins aggressively (fewer partial bins at end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that nothing can use (post_residual < 10).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // bin_residual of the current stream; only attractive when this bin's fit is bad.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste_pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residuals are large (open bins are fragmented)
        // and the current fit into this bin would be poor anyway.
        score += 8.0 + 15.0 * (1.0 - waste_pressure) - 10.0 * progress;
        // If item is huge relative to capacity, new bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - next_fit / bin_capacity as f64);
    }
    // Penalize if next item would be stranded by a large awkward residual.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // suggests we should consolidate into existing bins rather than spread.
    if open_bins_count > 3 {
        score += 2.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild time-horizon shaping: early in the stream, be more conservative
    // (slightly prefer existing bins); late, allow looser fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual) mildly; late in the stream,
    // dead space becomes more costly, so weight grows with progress.
    let w = 0.5 + 2.0 * progress * progress;
    score += w * (pr / cap) * (pr / cap) * cap * 0.3;

    // Reward bins whose residual exactly accommodates the next item (smooth coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 4.0 * (1.0 - progress);
    }

    // Penalize near-full residual fragmentation when few fitting alternatives exist.
    if fitting_bins_count <= 1 {
        score += 3.0 * (pr / cap);
    } else {
        score -= 0.5 * (1.0 - (pr / cap)).powi(3);
    }

    // Coupling with mean residual: favor bins below mean residual (tighter than average).
    score += 0.4 * (mean_residual - pr) / cap;

    // Slight bonus for using an existing bin vs opening a new one.
    if bin_residual < bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic classes: classify post_residual by integer division thresholds.
        // Class 0: unusable dead space (small leftovers) -> heavy penalty.
        // Class 1: medium leftovers -> mild penalty.
        // Class 2+: large leftovers -> acceptable.
        let cls = post_residual / (bin_capacity / 4);
        match cls {
            0 => score += 40.0,                       // dead space (<25)
            1 => score += 10.0,                       // moderate space (25..50)
            _ => { score -= 5.0; }                    // roomy leftover (>=50)
        }

        // Coupling with lookahead: if next item fits exactly in post_residual,
        // strongly reward this bin (chain packing).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 300.0;
            } else if next_item_size < post_residual {
                let next_left = post_residual - next_item_size;
                let ncls = next_left / (bin_capacity / 4);
                match ncls {
                    0 => score += 25.0,   // next placement would create dead space
                    1 => score += 8.0,
                    _ => score -= 15.0,
                }
            } else {
                // next item cannot follow here; mild penalty proportional to gap
                score += ((next_item_size - post_residual) as f64) * 0.5;
            }
        } else {
            // Last item: only perfect fits matter.
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // fragmented (mean residual low relative to item) or many bins already open.
    if bin_residual == bin_capacity {
        score += 60.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 * 0.5 && mean_residual > 0.0 {
            score -= 80.0; // open bins too fragmented; new bin is fine
        }
        if open_bins_count > 20 && progress < 0.5 {
            score -= 10.0;
        }
    }

    // Slight preference for fuller bins among open ones.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest plausible item (1..100, min ~10 in practice)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits the post-residual, strongly reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if next item is slightly larger than post residual (wasted opportunity)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open bins pressure: many open bins -> favor filling existing ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.0;

    // New-bin candidate: penalize moderately so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 35.0 + 0.5 * open_bins_count as f64;
    }

    // Late in stream, be more conservative about opening bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here; penalize proportionally to the miss.
        let miss = (next_item_size - post_residual) as f64;
        score += 12.0 * (miss / bin_capacity as f64);
    }

    // Exact-ish fits are gold: strong reward for tiny post_residual (but nonzero waste).
    let pr = post_residual as f64;
    if pr > 0.0 {
        score -= 25.0 * (1.0 - pr / bin_capacity as f64).powi(4);
    } else {
        score -= 40.0; // perfect fill
    }

    // Penalize bins deviating from the mean residual (prefer balanced usage).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
        // But if lookahead suggests a fresh bin helps, soften slightly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving small unusable dead space (best-fit core)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.6;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist, pushing toward best fit
        score += (fitting_bins_count as f64) * 2.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current bin
    // would be badly fragmented or when residuals are globally tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is cheaper late in the stream when open bins are crowded
        let open_pressure = (open_bins_count as f64) * 3.0;
        // Prefer new bin if mean residual is small (existing bins nearly full)
        let tight = (mean_residual - item_size as f64).max(0.0);
        score = 60.0 + open_pressure * 0.2 - tight * 0.1 - progress * 20.0;
    }

    // Time-horizon coupling: early in the stream, be conservative with new bins;
    // late, prefer tight packing of existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (mean_residual / bin_capacity.max(1) as f64) * 8.0;

    // Slight preference to balance residuals across open bins
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr as f64;

    // Smooth dead-space penalty: cubic in normalized residual, weighted by progress.
    score += 40.0 * x * x * x * (0.5 + progress);

    // Reward tight fits (small post-residual) more strongly later in the stream.
    score -= 30.0 * (1.0 - x) * (1.0 - x) * progress;

    // Interaction: lookahead fit quality — smooth quadratic coupling with post-residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        let fits_next = if pr >= ns { 1.0 } else { 0.0 };
        score += 12.0 * (1.0 - fits_next) * (gap / cap) * (1.0 + progress);
        score -= 10.0 * fits_next * (1.0 - gap / cap).powi(2) * (1.0 - progress);
    }

    // Last-chance bonus: smoothly stronger when few fitting bins.
    let fbn = fitting_bins_count as f64;
    score -= 25.0 * (1.0 / (1.0 + fbn)) * (0.5 + progress);

    // Slight preference for bins below mean residual early, above later (smooth coupling).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (progress - 0.5);

    // Mild pressure to consolidate when many bins are open.
    score -= 5.0 * (open_bins_count as f64).ln() * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into residue buckets mod small numbers.
    // Leftovers <= 10 are near-dead space (items are >= 1 but large items common); penalize heavily.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 60.0; // near-dead space
    } else if pr <= 20 {
        score += 15.0;
    }

    // Modulo-class analysis: leftover congruence classes that pair well with common item sizes.
    // If next item can exactly fill the leftover, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr {
            let after2 = pr - next_item_size;
            if after2 <= 10 {
                score += 40.0; // would create near-dead space for the item after
            } else {
                score -= 30.0; // leftover reusable by lookahead
            }
            // harmonic class: leftover divisible into halves/quarters of capacity
            if pr % 25 == 0 || pr % 20 == 0 || pr % 50 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's leftover: leftover is frozen for at least one step
            score += 25.0;
            if pr <= 30 {
                score += 30.0; // frozen small leftover is very bad
            }
        }
    } else {
        // last item: just prefer tight packing
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize unless current bins are all tight or item is huge
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fit win
        score += 120.0;
        // but if item is large relative to mean residual, opening fresh is fine
        let mean_r = mean_residual;
        if (item_size as f64) > mean_r {
            score -= 80.0 * ((item_size as f64 - mean_r) / bin_capacity as f64);
        }
        // early in stream, new bins are cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Prefer bins already below mean residual (consolidating small leftovers)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Integer-division threshold: leftover >= 50 is half a bin, still very usable
    if pr >= 50 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else if post_residual <= 10 {
        // Unusable-ish dead space: heavy penalty.
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Pressure on number of open bins: when many bins are open, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 0.5;

    // New-bin candidate handling: empty bin gets a moderate default score;
    // it should win only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream or with lookahead mismatch, opening a new bin is safer.
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
            score -= 70.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Prefer bins with below-average residual (tighter bins) slightly.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly empty post-residual is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills this bin's post-residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // Next item fits here too: mild bonus proportional to leftover after both.
            let two_step_leftover = post_residual - next_item_size;
            score -= 50.0 * (1.0 - two_step_leftover as f64 / bin_capacity as f64);
        } else {
            // Next item CANNOT fit here: penalize wasting capacity the next item needs.
            let overflow = next_item_size - post_residual;
            score += 30.0 + 2.0 * overflow as f64;
        }
    }

    // Compare post_residual against mean residual: creating below-average residual
    // (tight packing) is good; creating above-average residual (fragmenting) is bad.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.8 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize large dead space that no plausible small item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 80.0; // small gap, likely fillable later
    } else if post_residual >= 10 && post_residual < 40 {
        score += 10.0; // moderately awkward gap
    }

    // New-bin candidate: opening a new bin should only win when open bins
    // offer poor fits. Give the empty bin a moderate baseline penalty so it
    // loses to good fits but beats fragmented placements.
    if bin_residual == bin_capacity {
        score += 150.0 - 100.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Early in the stream, slight preference to consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize residual waste nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Reward near-perfect packing (residual close to 0).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: small unusable leftovers are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0;
        } else if (post_residual as u32) + next_item_size <= bin_capacity
            && post_residual > 0
            && (next_item_size as f64) > post_residual as f64
        {
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins mildly; it must only win when fits are terrible.
        score += 45.0 + open_bins_count as f64 * 0.5;
        // But if lookahead item is large and current fits waste a lot, new bin is fine.
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 30.0 && open_bins_count > 2 && !is_new_bin {
        score -= (mean_residual - 30.0) * 0.3;
    }
    // Late in the stream, avoid leaving fragmented bins.
    if progress > 0.8 && post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Mild preference for filling larger residual bins when few bins are open.
    if open_bins_count <= 2 {
        score += bin_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer tight fits, smooth polynomial decay of residual usefulness.
    let mut score = pr as f64;

    // Non-linear coupling: residual waste penalized more as stream progresses.
    let progress_coupling = x * (1.0 - x) * (0.5 + t);
    score -= 40.0 * progress_coupling;

    // Penalize large residuals late in stream (dead space accumulates).
    score += t * x * x * 30.0;

    // Reward near-perfect fits with smooth bump around x ~ 0.
    score -= (1.0 - x).powi(3) * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 15.0 * nx * (1.0 - nx);
    } else if next_item_size > 0 {
        // Next item cannot follow here: mild penalty scaled by tightness.
        score += 8.0 * (1.0 - x) * t;
    }

    // Deter spreading across many open bins; consolidation pressure.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - t);

    // Deviation from mean residual: prefer bins close to mean to keep balance,
    // but late in stream prefer tighter-than-mean bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0 - dev * 5.0 * t;

    // New-bin candidate: make empty bins mildly unattractive unless residual
    // structure is bad; smooth gate on tightness of other options.
    if bin_residual == bin_capacity {
        score += 12.0 - 20.0 * t * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via integer division thresholds.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class the leftover by harmonic bands: 0-5 (nearly perfect), 6-12 (small),
        // 13-25 (medium, still useful for small items), >25 (large, fine).
        let pr = post_residual;
        if pr <= 5 {
            score -= 25.0;
        } else if pr <= 12 {
            score -= 10.0;
        } else if pr <= 25 {
            score -= 2.0;
        }
        // Modulo-10 harmonic: leftovers that are multiples of 10 tend to match
        // quantized item sizes better (items often arrive on a 10-grid).
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead: does the next item fit in the post_residual? Reward if yes (chaining),
    // penalize if the leftover is just barely too small (dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin: strong reward, scaled by
            // how snugly the next item fits (small slack is good).
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.3 * slack;
            if post_residual == next_item_size {
                score -= 15.0; // exact two-item completion
            }
        } else {
            // Leftover cannot host the next item: penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(30.0);
        }
    }

    // Last-chance logic: if this is the only bin that fits the item, using it avoids
    // opening a new bin -> reward strongly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when few open bins fit the item
        // (fragmentation risk) or when the current item is large (poor fits elsewhere).
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
        score -= 10.0 * pressure + large_item_bonus + 3.0 * progress;
        // But if the item fits snugly into an existing bin (small post_residual),
        // discourage the new bin.
        if post_residual <= 10 {
            score += 20.0;
        }
    }

    // Mild penalty for creating leftovers far below the smallest plausible item
    // (1..10 dead zone) when next_item_size is unknown or larger.
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 8.0;
    }

    // Tie-break: prefer bins whose residual is below the mean residual (tighter bins
    // get filled first, keeping loose bins flexible).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps below the minimum item size (1..=10)
    // are worthless; gaps that can't fit the known next item are also suspect.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = (item_size as f64) / (bin_residual as f64);
        score -= 25.0 * tightness;
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // (new bin has bin_residual == bin_capacity, so it gets this penalty).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 18.0 + 25.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);
    } else {
        // Slight reward for reusing bins when many are open
        score -= 2.0 * open_bins_count as f64 * 0.05;
    }

    // Prefer bins whose residual deviates from the mean (consolidating waste)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: reward leaving room exactly for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect chain: item fits and next item exactly fills remainder
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize if next item cannot fit the remainder (dead space for next step)
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal leftover
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong incentive to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * (bin_capacity - item_size) as f64;
    }

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // next item can still fit here
        } else {
            // dead space penalty scaled by how close post_residual is to small-item range
            score += 6.0 * (1.0 - (post_residual as f64 / 10.0).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless current
    // bins are nearly full or the fit here is bad.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let horizon = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 12.0;
        if avg_tightness > 0.6 { new_bin_cost -= 10.0 * (avg_tightness - 0.6); }
        if fit_ratio > 0.5 { new_bin_cost += 20.0 * fit_ratio; } // bad fit elsewhere -> new bin cheaper
        if horizon > 0.9 { new_bin_cost -= 3.0; }
        score += new_bin_cost.max(-5.0);
    }

    // Mild preference for fuller bins among open bins (residual close to item size).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += 5.0 * residual_frac;

    // Slight global pressure: many open bins -> prefer using existing ones.
    score += 0.2 * open_bins_count as f64;

    // Time-horizon modulation: early in stream, be a bit greedy toward tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space quadratically, modulated by stream progress.
    let mut score = post * (1.0 + 1.5 * progress * x);

    // Smooth polynomial coupling: reward tight fits more as stream progresses.
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post residual (smooth ramp).
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let fit_deg = ((x - nx) / cap).max(0.0);
        score -= 10.0 * (-fit_deg * 8.0).exp() * (1.0 - progress * 0.5);
        // Penalize post residual that is too small for the next item (dead space).
        if x < nx {
            score += 6.0 * (nx - x) * cap * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized early,
    // more attractive late when open bins have fragmented residuals.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) + 0.1 * mean_residual * progress;
    }

    // Mild dispersion penalty: prefer bins close to mean residual (smooth term).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does leftover space fall into
    // reusable classes (multiples of common item sizes)?
    let pr = post_residual;
    let reusable = if pr == 0 {
        3.0 // perfect fit
    } else if pr <= 10 {
        2.0 // tiny dead space, nearly perfect
    } else if pr % 10 == 0 {
        1.5 // aligns with size grid, likely reusable
    } else if pr % 5 == 0 {
        1.0
    } else if pr >= 20 {
        0.5 // large-ish leftover still usable
    } else {
        0.0 // awkward dead space
    };
    score -= reusable * 6.0;

    // Penalize awkward mid-range leftovers via modulo structure
    if pr > 10 && pr < 20 && pr % 5 != 0 {
        score += 8.0;
    }
    if pr > 50 && pr < 60 && pr % 10 != 0 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 10.0;
            } else if slack % 10 == 0 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty for tight classes
            score += 3.0;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Slight preference for tighter bins (best-fit flavor) when many bins fit
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 4.0;

    // Progress-based pressure: later in stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted when few fitting bins exist
        score = 30.0 - progress * 10.0 - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item may deserve fresh bin
        }
    } else if fitting_bins_count <= 2 {
        score -= 5.0; // scarcity of alternatives favors reuse
    }

    // Mean-residual context: if this bin is far below mean residual, it's a good "garbage collector"
    if (mean_residual - bin_residual as f64).abs() < 5.0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host the
    // smallest plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // "Almost dead" gaps: usable only for tiny items; strong penalty.
        score += 18.0;
    } else if post_residual <= 30 {
        score += 6.0;
    } else {
        // Large gaps are flexible; reward mildly.
        score -= 4.0;
    }

    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item:
    // preserves a future perfect fit in this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // If the next item still fits here, keep this bin attractive.
            score -= 5.0;
        } else {
            // Next item cannot use this residual: mild penalty scaled by waste.
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the residual (dense packing).
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins; but relax
    // pressure late in the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 - 0.75 * progress);

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin; pushing items into tight bins keeps loose ones
    // available for awkward future items.
    let residual_diff = (bin_residual as f64) - mean_residual;
    score += 0.10 * residual_diff;

    // Last-chance bin: if this is the only fitting bin, using it avoids
    // opening a new bin; strong reward unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual < 10 {
            score += 30.0; // ...but not at the cost of creating dead space.
        }
    }

    // New-bin candidate handling: an empty bin has maximal flexibility.
    // Prefer it only when no open bin offers a decent fit, or when the
    // current fit would strand a nearly-full bin's tiny residual.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a good existing fit...
        score += 12.0;
        // ...but much better than a bad fit in an open bin.
        if post_residual < 10 {
            score -= 55.0;
        }
        if next_item_size > 0 && (bin_capacity as u64) >= (next_item_size as u64 + item_size as u64) {
            score -= 8.0; // empty bin can absorb item + lookahead.
        }
        // Early in the stream, opening bins is cheap and flexible.
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect two-item fit: post_residual exactly matches next item -> strong reward.
        if post_residual as f64 == nxt {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Bin can still host the next item: reward closeness of the match.
            let gap = post_residual as f64 - nxt;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space, worse when residual is tiny.
            let dead = nxt - post_residual as f64;
            score += 0.5 * dead;
            if post_residual < 10 {
                score += 20.0; // nearly unusable sliver
            }
        }
    } else {
        // Last item: prefer tightest fit only.
        score = post_residual as f64;
    }

    // --- Relative-to-mean residual coupling ---
    // Bins tighter than average are more valuable to fill; loose bins less so.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score -= 0.3 * (mean_residual - res);
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- Progress-aware conservatism: later in the stream, prefer tight packing ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a good
        // two-step fit (post_residual would be large there anyway).
        score = bin_capacity as f64 - 10.0;
        if next_item_size > 0 && (bin_capacity as u32) >= next_item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 55.0 * fill_ratio * fill_ratio;

    // Penalize small unusable post-residual "dead space" (nonzero but tiny).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 0.35 * item_size as f64;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // no open bin gives a decent fit; scale penalty with number of open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But early in the stream, opening bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward;
    // if next item is larger than post-residual but smaller than typical residual, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64).min(1.0));
        } else if next_item_size <= bin_residual {
            score += 6.0;
        }
    }

    // Global residual pressure: if mean residual across open bins is high,
    // prefer using existing bins rather than fragmenting space.
    score -= 0.15 * mean_residual;
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Late-stream consolidation: as stream ends, be greedier about filling bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 40.0 * poly;

    // Reward tight fits, smoothly scaled by progress
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + t);

    // Penalize post_residual that cannot fit the lookahead item (smooth falloff)
    if next_item_size > 0 {
        let gap = norm_next - norm_pr;
        if gap > 0.0 {
            score += 25.0 * gap * gap * (1.0 + t);
        } else {
            score -= 10.0 * (-gap) * (1.0 - t);
        }
    }

    // Last-chance bin: reward strongly, smoothly decaying with open bins count
    if fitting_bins_count == 1 {
        score -= 20.0 / (1.0 + open_bins_count as f64);
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // New empty bin candidate: smooth penalty that relaxes as stream progresses
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small leftovers are "dead space"
    let class = match post_residual {
        0 => 0.0,                       // perfect fill
        1..=5 => 1.0,
        6..=15 => 2.0,
        16..=30 => 3.0,
        31..=49 => 4.0,
        _ => 5.0,                       // large residual: reusable
    };
    score += class * class * 3.0;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Harmonic pairing: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot use leftover: penalize proportional to mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += mismatch * 0.08;
        }
    } else {
        // last item: prefer exact fill
        score -= 8.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins have healthy mean residual
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        score += 25.0 - pressure * 8.0 - progress * 5.0;
        // new bin has zero class penalty already; re-add baseline so it competes fairly
        score += 6.0;
    }

    // Slight penalty for bins whose residual deviates from mean (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Modulo harmonic bonus: residuals that are multiples of common item chunks (e.g. 25)
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized,
    // with a superlinear ramp as the gap shrinks toward zero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tight-fit bonus: item occupies most of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer packing into existing
    // bins rather than spreading; makes new-bin candidate less attractive.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate calibration: an empty bin has no dead-space risk, but
    // discourage it when decent fits exist (mean residual is healthy).
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual > item_size as f64 + 10.0 {
            score += 20.0;
        }
        // Late in the stream, opening bins is cheaper than leaving dead space.
        if step_index as f64 / total_items.max(1) as f64 > 0.8 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits in the post residual, reward this
    // placement for enabling a chained fit.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }
    // Penalize leaving a gap that just barely fails to fit the next item.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0 * (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), penalize outliers.
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near-match: next item can still fit after this placement.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional to how close the next item is to filling the remainder.
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit in the leftover: penalize dead space, worse when small.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates upward from the mean (fragmented bins).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        // Slightly discourage opening new bins as stream progresses, unless desperate.
        score += 12.0 + 10.0 * progress - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on tightness: prefer small but nonzero waste
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score += tight * tight * 50.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        }
        // If placing here leaves residual that can't fit anything useful (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += post_residual as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: opening a new bin wastes residual of existing bins.
    // Penalize opening a new bin unless it's a perfect fit for a large item
    if bin_residual == bin_capacity {
        // waste of existing capacity if we open new bin
        score += open_bins_count as f64 * mean_residual * 0.3;
        // reward opening a new bin for large items that would leave tiny dead space elsewhere
        if post_residual as f64 <= mean_residual {
            score -= 80.0;
        }
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, close out bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * mean_residual * 0.1;
    score -= progress * post_residual as f64 * 0.3;

    // Many open bins: prefer consolidating into fuller bins
    if open_bins_count > 4 {
        score -= (bin_residual as f64 - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Smooth non-linear polynomial coupling: post_residual^2 scaled by progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let quad = pr_norm * pr_norm; // in [0,1]

    // Early stream: penalize large residuals quadratically (keep bins tight early).
    // Late stream: relax the quadratic penalty, favoring any fit.
    score += 30.0 * quad * (1.0 - progress);

    // Cubic coupling: dead-space penalty grows super-linearly for very full fits,
    // modulated smoothly by progress.
    score += 15.0 * quad * pr_norm * progress;

    // Reward tight fits (small post_residual) with a smooth exponential term.
    score -= 12.0 * (-pr / 15.0).exp();

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize bins that deviate from the mean residual (smooth quadratic term),
    // encouraging balanced residual distribution across open bins.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // New-bin candidate: make empty bins mildly unattractive unless residuals
    // elsewhere are poor (smoothly scaled by open-bin count).
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it cannot
    // plausibly fit typical future items. Classify post_residual by integer
    // division into size-class buckets (items are 1..=100).
    let pr = post_residual;
    let dead_class = if pr == 0 {
        0.0 // perfect fit, best possible
    } else if pr <= 10 {
        1.0 // tiny dead space, nearly perfect
    } else if pr <= 25 {
        2.0 // can only host small items
    } else if pr <= 50 {
        3.0 // mid-class leftover
    } else {
        4.0 // large residual, bin is still flexible
    };
    score += dead_class * 8.0;

    // Reward exact modular harmony: post_residual divisible by small units
    // (10/20/25) is reusable by class-structured streams.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead: strongly reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            // next item won't fit here; leftover is dead until later
            score += 5.0;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / cap;
    score -= fill * 20.0;

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well (poor fit here) or bins are scarce.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 15.0;
        // If many bins already fit the item, discourage opening another.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 6.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If mean residual across open bins is large, reuse them.
        if mean_residual > item_size as f64 {
            score += 8.0;
        }
    }

    // Slight penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if smaller than the minimum item size (1) is never
    // an issue, but gaps too small for typical next items waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more expensive.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins would leave
    // large dead space or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let dead_space_penalty = post_residual as f64;
        let pressure = (open_bins_count as f64) * 2.0;
        score = 30.0 + dead_space_penalty + pressure;
        // If no open bin fits well (many fitting bins means good alternatives exist),
        // new bin gets relatively better.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Large items justify fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for leaving mid gaps.
        score += 2.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins) when item fits.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins (fewer remaining items to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with little slack left.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this leftover.
        let dead = post_residual as f64;
        let dead_frac = dead / bin_capacity as f64;
        score += 20.0 * dead_frac * dead_frac;
    }

    // Reward small absolute post_residual (tight packing).
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual across open bins: prefer bins that tighten the spread.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Early in stream: mild preference to open new bins to build a good bin pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, discounted early, penalized late.
        score = 45.0 + 55.0 * progress;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residual that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.25 * post_residual as f64;
        } else {
            // Reward residuals that exactly accommodate the lookahead item
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (-slack / 20.0).exp();
        }
    } else {
        // Last item: strongly prefer minimal final residual
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (1.0 - progress);
        // But if existing bins fit poorly (high mean residual waste), allow new bin
        score -= 0.1 * mean_residual;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.3 * open_bins_count as f64;

    // Prefer bins whose residual deviates from mean (fill outliers first)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, shaped non-linearly
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, prefer filling bins tightly (waste matters less later? actually
    // dead space early compounds); weight waste more as stream progresses.
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 25.0 * prog_poly * norm_pr;

    // Interaction with mean residual: penalize bins whose post residual deviates
    // from the pack average, rewarding residual consolidation.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward leaving room for the next item, penalize near-miss dead space
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack_fit = 1.0 - (pr - ns) / cap;
            score -= 12.0 * slack_fit * slack_fit;
        } else {
            let miss = (ns - pr) / cap;
            score += 18.0 * miss * (1.0 + prog_poly);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * prog_poly;
    } else if fitting_bins_count > 1 {
        // mild competition scaling: tighter bins among many candidates
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * norm_pr;
    }

    // Slight penalty for spreading across many open bins early
    score += 0.5 * (open_bins_count as f64) * (1.0 - prog_poly) * norm_pr;

    // Perfect fit reward (smooth)
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting post_residual: bins whose leftover falls
    // into "usable" residue classes (multiples of common item granularities)
    // are favored, since future items are more likely to slot in exactly.
    let classes: [u32; 6] = [10, 20, 25, 50, 33, 100];
    let mut class_bonus = 0.0;
    for (i, &c) in classes.iter().enumerate() {
        if c > 0 && post_residual % c == 0 && post_residual > 0 {
            class_bonus += 6.0 - i as f64; // finer classes first, more reward
        }
    }
    score -= class_bonus;

    // Integer-division threshold on post_residual: dead space bands.
    let pr = post_residual;
    if pr < 10 && pr > 0 {
        // Unusable sliver: heavy penalty unless it exactly zeroed the bin.
        score += 25.0;
    } else if pr <= 20 {
        // Small but plausibly fillable by min-size items.
        score += 4.0;
    } else if pr > 50 {
        // Large leftover: this bin was "wasted" on a small item.
        score += (pr as f64 - 50.0) * 0.3;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead harmonic coupling: if next item exactly divides post_residual
    // (or matches a class multiple), strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 18.0;
        } else {
            let q = post_residual / next_item_size;
            if q >= 2 {
                score -= 5.0 * q.min(4) as f64;
            }
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot go here anyway; slight penalty for stranding.
        score += 6.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    // (large post_residual waste) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // Prefer fresh bin when it yields a large, class-aligned residual.
        let fresh_bonus = waste_ratio * 30.0 * (1.0 - progress) + mean_residual * 0.2;
        score -= fresh_bonus;
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
    } else {
        // Mild preference for tighter existing bins as stream matures.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Coupling with mean residual: placing into a bin far below mean residual
    // evens out residuals (good); placing into a much-above-mean bin strands it.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Modulo threshold on item_size: large items (>= half capacity) prefer
    // exact-class bins, penalize leaving awkward halves.
    if item_size >= bin_capacity / 2 && post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps hard.
    // A gap is "dead" if it's too small for even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small-but-usable gaps are risky; moderate penalty.
        score += 18.0;
    }

    // Reward tight fits: near-zero post residual is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space is worse when few bins are open (less slack to absorb waste).
    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    if post_residual > 0 && post_residual < 25 {
        score += 8.0 / open_pressure;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a brand-new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Many alternatives: mild penalty to prefer better-fitting bins.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > 0 {
        // Next item won't fit here; slightly penalize leaving a gap it almost fits.
        if post_residual > 0 && (next_item_size as i32 - post_residual as i32) < 15 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has full residual; make it
    // moderately attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        // Base new-bin cost: discourage opening bins when a decent fit exists.
        score += 30.0;
        // But if this item would leave dead space everywhere, opening is fine.
        if post_residual < 10 {
            score -= 45.0;
        }
        // Late in stream with many bins, opening a fresh bin is safer.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 {
            score -= 5.0;
        }
    }

    // Mean residual coupling: if open bins are already slack-heavy,
    // penalize adding more slack to them; favor the fresh bin implicitly.
    if bin_residual != bin_capacity && (post_residual as f64) > mean_residual + 10.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight dead space more as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 + 2.0 * progress;
    score *= tightness;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when the NEXT item exactly matches
    // the post-residual (perfect chaining), or fits reasonably well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // exact chain: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Reward good chain fits, scaled by how tight the chain is.
            score -= 30.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize by the gap size,
            // worse if the gap is small (nearly-useless dead space).
            let gap = next_item_size - post_residual;
            score += 12.0 + 0.35 * gap as f64;
        }
    }

    // Relative to mean residual: bins with more residual than average are
    // better candidates to absorb this item (keep tight bins for small items).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we only open a new bin
    // when no open bin offers a decent fit; but keep it competitive when the
    // item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += 15.0 - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when the item is large or
    // existing residuals are poor (fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 8.0; // base reluctance to open new bins
        if item_size >= 60 { score -= 6.0; }                 // big items fine in fresh bin
        if mean_residual < item_size as f64 { score -= 12.0; } // nothing useful open
        if fitting_bins_count == 0 { score -= 20.0; }
        score += 0.05 * fragmentation;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Late-stream pressure: consolidate more aggressively near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let is_new = (bin_residual as u64 == bin_capacity as u64) as f64;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // tighter packing matters more as the stream progresses.
    let tightness = (1.0 - norm_pr).powi(2);
    score -= 30.0 * tightness * (0.5 + progress) * (pr / (pr + 10.0));

    // Penalize large dead space quadratically, modulated by progress.
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 12.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 8.0 * (ni - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening new bins early, allow later.
    score += is_new * (15.0 + 25.0 * (1.0 - progress) * (1.0 - progress));

    // Mild pressure toward consolidating into fewer bins.
    score += open_bins_count as f64 * 0.05;

    // Prefer bins whose residual is close to the mean (balance residuals smoothly).
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues modulo 10 define
    // "usable" leftover classes (multiples of 10 are re-combinable).
    let post = post_residual;
    let residue = (post % 10) as f64;
    if post == 0 {
        score -= 50.0; // perfect fit: ideal
    } else if residue == 0.0 {
        score -= 12.0; // leftover in a harmonic class: easy to refill later
    } else {
        // penalize non-harmonic leftovers proportionally to how far they are
        // from the next multiple of 10 (dead space)
        score += (10.0 - residue) * 2.5;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 15.0;
            // harmonic bonus if next item lands exactly on a class boundary
            if (post % 10) == (next_item_size % 10) {
                score -= 8.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish, but prefer it only when the
    // current bin would leave large dead space and many bins are open.
    if bin_residual == bin_capacity {
        score = 40.0 + (mean_residual / 10.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Early in the stream: tolerate more slack, slightly favor fresh bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual below the minimum item size (1..100
    // interface, but sizes >=10 historically; treat <12 as unusable) is pure waste.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0; // dead space penalty
    }
    // Zero residual is perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness reward: the fuller the bin, the better (relative to capacity).
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual pressure is high.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening bins is less costly (no future to amortize).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        // If many open bins already exist, avoid spreading further.
        score += 2.0 * open_bins_count as f64;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if the next item fits into the post residual, reward leaving room.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in the leftover, the leftover is likely waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins whose residual is close to item need
    // (avoid dumping into bins with huge residual when a tight fit exists).
    let res_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * res_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a post_residual that exactly
    // matches the next item size (perfect chain), and reward near matches.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - match_gap / bin_capacity as f64).max(0.0);
        // Exact match bonus
        if match_gap == 0.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize dead space creation,
        // scaled by how much space is wasted relative to the next item.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead;
    }

    // Penalize large post_residual relative to mean residual across open bins
    // (creating oversized slack spreads capacity poorly).
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.35 * (pr - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - pr);
    }

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or the
    // stream is early and future capacity is valuable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer reusing bins; opening a new bin should lose unless the fit
        // elsewhere is terrible. Base penalty decays slightly over the stream.
        score += 55.0 - 15.0 * progress;
        // If many bins are open and mean residual is small, a fresh bin is
        // more acceptable.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        if mean_residual < 10.0 {
            score -= 20.0;
        }
        // If the next item is huge and won't fit anywhere anyway, fresh space helps.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter fits overall (small post_residual already
    // favored by the base term; add convex penalty for mid-range slack).
    if pr > 0 && pr < 10 {
        score -= 5.0; // nearly-perfect fill
    } else if pr >= 10 && pr < 30 {
        score += 3.0; // awkward mid-range dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a slight convex penalty
    // on wasted space so mid-range leftovers are discouraged more than tiny ones.
    let waste_frac = post_residual as f64 / cap;
    score += 25.0 * waste_frac * waste_frac;

    // Lookahead coupling: if the next item fits into the post-residual, reward
    // this placement strongly (chain-packing bonus).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0;
        // Extra bonus proportional to how snugly the next item will fit too.
        let next_leftover = post_residual as f64 - next_item_size as f64;
        score -= 8.0 * (1.0 - next_leftover / cap).max(0.0);
    } else if next_item_size > 0 {
        // If next item cannot follow here, penalize large dead space a bit more.
        score += 6.0 * waste_frac;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding
    // a pointless new bin when an option exists.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // the current item is large (leaves a useful residual) or when existing
    // bins are crowded / fragmented.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        // Early stream: opening bins is cheap; later: prefer consolidation.
        score -= 20.0 * (1.0 - early);
        // Reward opening when item is big (good use of fresh capacity).
        score -= (item_size as f64 / cap) * 10.0;
        // Penalize opening when many bins already fit the item.
        score += 8.0 * (fitting_bins_count as f64).min(4.0);
        // Penalize opening when mean residual across open bins is still high.
        score += 0.05 * mean_residual;
        // If the next item is huge, a fresh bin is risky; discourage.
        if next_item_size as f64 / cap > 0.7 {
            score += 5.0;
        }
    } else {
        // Mild bonus for using existing bins when they are plentiful.
        score -= 2.0 * (open_bins_count as f64).min(6.0) / 6.0;
        // Favor bins whose residual is close to the item (tight fit signal).
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += 10.0 * tightness;
    }

    // Global fragmentation guard: if mean residual is low (bins nearly full),
    // reward placements that nearly empty a bin (completing it).
    if mean_residual < 20.0 && post_residual < 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, waste is less costly; late, tight packing matters more.
    let mut score = pr * (1.0 + 1.5 * progress * progress) + 0.35 * pr * pr / cap;

    // Smooth interaction: how well post_residual aligns with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        score += 0.6 * fit_gap * (1.0 + progress);
        // Reward exact-ish preparation for next item (smooth kernel).
        score -= 0.9 * (-fit_gap / 12.0).exp() * pr.min(nxt);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0 + 30.0 * progress;
    }

    // Penalize scattering across many open bins relative to mean residual.
    score += 0.4 * (open_bins_count as f64).ln() * (pr / cap);
    score += 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate: smooth sigmoid gate — open a new bin only when
    // the current bin would leave a large dead zone relative to capacity.
    if is_new_bin {
        let dead_zone = pr / cap;
        let gate = 1.0 / (1.0 + (-18.0 * (dead_zone - 0.25 - 0.2 * progress)).exp());
        score += 55.0 * gate + 10.0;
    } else {
        // Reward consuming a large fraction of residual (smooth saturation).
        let used_frac = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * (1.0 - (-3.0 * used_frac).exp());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible by common item granularities (5, 10, 20, 25) are more
    // likely to be filled by future items, so reward them (subtract).
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
    }

    // Integer-division thresholds: classify post_residual into dead-space bands.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        // Tiny leftover: near-perfect packing, strongly reward.
        score -= 20.0;
    } else if post_residual < half {
        // Medium leftover: mildly reward.
        score -= 5.0;
    } else {
        // Large leftover: bin was poorly used; penalize proportionally.
        score += (post_residual - half) as f64 * 0.15;
    }

    // Coupling with the lookahead item: if the next item fits exactly (or well)
    // into post_residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0; // exact harmonic match
        } else if gap < quarter {
            score -= 10.0;
        } else {
            score -= gap as f64 * 0.05;
        }
    }
    // If the next item cannot fit here, the leftover must attract later items:
    // penalize awkward non-harmonic leftovers.
    if next_item_size > post_residual && post_residual > 0 && post_residual % 5 != 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let fragmented = mean_residual < bin_capacity as f64 * 0.25 && open_bins_count > 2;
        if !(big_item || fragmented) {
            score += 40.0; // keep using open bins
        } else {
            score += 5.0;
        }
    }

    // Stream progression: late in the stream, tighten packing (dead space is
    // less likely to be recovered), so scale the residual penalty up.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * 0.1 * progress;

    // Mild tie-breaker: prefer bins whose residual deviates from the mean
    // (best-fit against the average state).
    score += (bin_residual as f64 - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
