pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        // Exact match is ideal: post_residual == next_item_size
        let diff = (post - nxt).abs();
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Extra reward if next item fits exactly after this placement
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual that is too small for the next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Next item fits: mild bonus proportional to how snugly it fits
            score -= 0.3 * ((post_residual - next_item_size) as f64).min(20.0);
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 15.0;
    }

    // Reward bins tighter than the mean residual (good packing), penalize looser ones
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless it is genuinely attractive
    if bin_residual == bin_capacity {
        // Opening a new bin is only good if current item is large and no good fits exist
        let crowding = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let urgency = (item_size as f64 / bin_capacity as f64).powi(2);
        score = 100.0 + 40.0 * urgency - 10.0 / crowding;
        // With lookahead, opening a bin sized for the next item can be smart
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that cannot hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly usable by the lookahead item.
            let slack = post_residual - next_item_size;
            score -= 2.5 / (1.0 + slack as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // late in stream, tolerate opening new bins to avoid fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 6.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
    } else {
        score += new_bin_bonus * 0.5;
    }

    // Global state coupling: penalize placements into bins whose residual
    // deviates badly from the mean residual (keeps bin pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // When many bins are open, discourage spreading; favor filling existing ones.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Perfect closure bonus: exactly filling a bin.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Mild penalty for residual just below common small item sizes (10..=20),
    // which tends to create unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly shaped
    let mut score = pr;

    // Smooth polynomial coupling: penalize small-but-nonzero residuals (dead space),
    // reward near-zero or large residuals, modulated by stream progress.
    let dead = norm_pr * (1.0 - norm_pr); // peaks at norm_pr=0.5
    score += 80.0 * dead * (0.5 + progress);

    // Cubic shaping: very small residuals are good (tight fit), very large are neutral
    let tight = 1.0 - norm_pr;
    score -= 40.0 * tight * tight * tight * (1.0 - progress);

    // Progress-scaled urgency: late in stream, prefer filling bins tightly
    score -= 30.0 * progress * (1.0 - norm_pr * norm_pr);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 35.0 * (1.0 - progress);
        } else {
            // penalize leaving residual that nothing typical can use
            let waste = pr - (pr % next_item_size as f64);
            score += 10.0 * (waste / cap);
        }
    }

    // Spread vs mean residual: prefer bins below mean (consolidation)
    score += 5.0 * (pr - mean_residual) / cap;

    // New-bin candidate: neutral baseline with slight penalty unless open bins are scarce
    if bin_residual == bin_capacity {
        score = cap + 15.0 - 10.0 * progress - (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable bands"
    let residue = post_residual % 10;
    let band = post_residual / 10;

    // Dead space penalty: post_residual too small to ever host a min item (1..=100)
    // treat < 10 as nearly dead; small residues are penalized via harmonic weight
    let dead = (10u32.saturating_sub(post_residual)) as f64;
    score += 2.5 * dead;

    // Harmonic class reward: post_residual divisible by 10 (clean fit) is valuable
    if residue == 0 && post_residual > 0 {
        score -= 4.0;
    } else if residue <= 2 {
        score += 1.0 * (residue as f64);
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item fits; reward proportional to tightness of fit
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack % 10 == 0 {
                score -= 2.0; // harmonic alignment after chaining
            }
        } else {
            // next item cannot use this bin's remainder; penalize large leftovers
            score += 0.05 * (post_residual as f64);
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 18.0;
        // cheaper to open a new bin late in the stream or when few bins fit
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 6.0; // big next item benefits from a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's "wasted space" elsewhere;
    // prefer filling bins below the mean (consolidate)
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Small-band bonus: post_residual in 10..=20 is a highly reusable class
    if post_residual >= 10 && post_residual <= 20 {
        score -= 3.0;
    }
    // Very large leftover relative to capacity is mildly bad unless bin was fresh
    if post_residual as f64 > 0.7 * bin_capacity as f64 && bin_residual != bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (post residual near zero but not dead).
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Perfect-fit shaping: reward post_residual that can host next_item_size.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            // Gap too small for lookahead: penalize proportionally.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Utilization term: the fuller the bin relative to capacity, the better.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bins pressure: with many open bins, favor consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 15.0 * open_pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when item is large
    // or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Large items justify fresh bins.
        score -= 0.35 * item_size as f64;
        // If many bins are open, discourage proliferation.
        score += 1.5 * open_bins_count as f64;
        // If mean residual across open bins is high, discourage new bin.
        score += 0.4 * mean_residual;
    } else {
        // Existing-bin bonus scaled by how well residual matches item.
        let waste = (bin_residual - item_size) as f64;
        score -= 10.0 * (1.0 - waste / bin_capacity as f64);
    }

    // Mild stream-progression damping: early on, be more conservative about
    // committing to tight fits since future distribution is unknown.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: as stream advances, be greedier (prefer tight fits more strongly).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 + 2.0 * progress;

    // Reward exact 2-step match: post_residual equals next item size (perfect fill next turn).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 * tightness;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to how much of post_residual it consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill * tightness;
        } else {
            // Next item cannot fit in post_residual: penalize dead space, scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(50.0) * (0.5 + progress);
        }
    } else {
        // Last item: strongly prefer the bin with the smallest post_residual.
        score -= 30.0;
    }

    // Reward filling bins below the mean residual (consolidating space).
    if (post_residual as f64) < mean_residual {
        score -= 8.0 + (mean_residual - post_residual as f64).min(40.0) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual).min(40.0) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are very full/crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / 20.0;
        let mean_full = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Prefer new bin only when existing bins are quite full and many are open.
        score += 55.0 - 30.0 * mean_full - crowded.min(25.0);
        // If next item also fits in a fresh bin, slightly less penalizing.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Penalize large exact-fit leftovers that are hard to reuse (odd residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base, amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: leftovers too small for typical items (below min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0 + (10 - post_residual) as f64 * 0.8;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            // Reward if next item leaves still-usable space; penalize if it strands space.
            if nxt_left >= 10 {
                score -= 6.0;
            } else {
                score += 4.0 + nxt_left as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when current
    // open bins have fragmented residuals (mean residual small relative to item),
    // or when there are many open bins already.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: slightly above average so it's chosen only when needed.
        score += 10.0;
        // More open bins => higher cost of adding another (encourage consolidation).
        score += (open_bins_count as f64) * 1.5;
        // If mean residual across open bins is large, prefer reusing them.
        score += mean_residual * 0.4;
        // Early in the stream, opening bins is cheaper (build a pool); late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If next item is large and this bin would be fresh, mild discount.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    } else {
        // Mild penalty proportional to how "wasted" the bin's residual was.
        let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
        score += 5.0 * waste_ratio;
    }

    // Global fragmentation pressure: when many bins are open with small mean residual,
    // push toward filling bins completely.
    if open_bins_count > 3 && mean_residual < 40.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic in normalized post residual (dead space penalized super-linearly)
    let mut score = x * x * cap;

    // Smooth cubic coupling with stream progress: early on, tolerate slack;
    // late in the stream, punish leftover space more aggressively.
    score += (1.0 + progress * progress) * (1.0 - x) * (1.0 - x) * 4.0 * (1.0 - progress);

    // Reward tight fits: item_size close to bin_residual lowers score smoothly.
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit * fit * 6.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 3.0;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += open_bins_count as f64 * 0.05 * (x - mean_residual / cap).abs();

    // New-bin candidate: bin_residual == capacity -> large x -> high base score,
    // but allow opening a new bin when post residual would be very small (impossible here)
    // or when existing bins are all nearly full; smooth adjustment:
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 equal classes.
    let class_width = bin_capacity as f64 / 10.0;
    let post_class = (post_residual as f64 / class_width).floor() as f64;
    let next_class = (next_item_size as f64 / class_width).floor() as f64;

    // Reward when post_residual class matches the next item's class (perfect reuse).
    if next_item_size > 0 {
        let class_gap = (post_class - next_class).abs();
        score -= 8.0 * (1.0 - class_gap / 10.0).max(0.0);
        // Exact fit of next item into post_residual is golden.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits with small slack left: mild reward.
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 12.0 - slack as f64;
            }
        } else {
            // Next item cannot reuse this residue: penalize proportionally.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Integer-division threshold: residue divisible into 100/2, /4, /5 chunks is "usable".
    for d in [2u32, 4, 5, 10] {
        if post_residual > 0 && bin_capacity % post_residual == 0 && post_residual >= bin_capacity / d {
            score -= 3.0;
            break;
        }
    }

    // Penalize awkward residues (small prime-ish dead space that few items can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // dead space class
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-ish; only prefer it when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * item_size as f64;
        if post_residual < 25 {
            score -= 15.0; // big items deserve fresh bins
        }
    }

    // Late in stream: consolidate, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: classify post_residual into usable vs unusable gaps.
    // Gaps smaller than the minimum conceivable item (1..100 range, but keep a margin)
    // are "dead space" and must be heavily penalized.
    let dead_threshold = 20.0; // gaps <= 20 are unlikely to fit typical items
    if post_residual == 0 {
        // Perfect fit: strongest reward
        score -= 60.0;
    } else if (post_residual as f64) < dead_threshold {
        // Unusable sliver: penalize proportionally to how close it is to dead_threshold
        let deadness = (dead_threshold - post_residual as f64) / dead_threshold;
        score += 25.0 * deadness;
    } else {
        // Usable gap: mild reward for leaving room that could serve a future item
        score -= 2.0;
        // If the gap exactly accommodates the lookahead item, reward it
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 15.0 {
                score -= 8.0 * (1.0 - slack / 15.0);
            }
        }
        // If the gap cannot fit even the next item, add mild penalty
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Reward tight fits: small post_residual relative to bin capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling
    // existing bins, i.e., penalize the new-bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, but less if no bin fits or all fits are poor
        let mut new_bin_score = 30.0 + 4.0 * pressure;
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // forced: no alternative
        } else if fitting_bins_count == 1 {
            // Last-chance bin: strongly discourage opening a new bin
            new_bin_score += 20.0;
        }
        // If mean residual across open bins is small (they are nearly full),
        // opening a new bin is more acceptable.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 10.0;
        score += new_bin_score;
    } else {
        // Existing bin: mild penalty scaled by how contested it is
        if fitting_bins_count == 1 {
            // This is the only bin that fits: strongly favor using it
            score -= 20.0;
        }
        // Prefer bins whose residual is close to mean (balanced packing),
        // but with dead-space dominance this stays a secondary term.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead coupling: if placing here leaves a gap that fits the next item
    // exactly or nearly exactly, this is a chain opportunity.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        if chain_fit <= 5.0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

