        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus if after placing next item residual is small (chain packing).
            let chain_res = post_residual as u32 - next_item_size;
            if chain_res <= 10 {
                score -= 60.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item: just minimize residual.
        score -= 50.0;
    }

    // Penalize bins far above mean residual (large leftover bins are valuable; don't waste them on small items).
    if (post_residual as f64) > mean_residual + 20.0 {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if next item is large and this item is small, opening fresh may pay off.
        if next_item_size > 50 && item_size < 30 {
            score -= 100.0;
        }
    }

    // Early in stream, be slightly conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 10 {
        score += 0.1 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
