        }
        if (bin_residual as f64 - mean_residual) < 5.0 && fitting_bins_count > 0 {
            new_bin_score += 10.0; // existing residuals already tight
        }
        if good_fit_exists {
            new_bin_score += 5.0;
        }
        score += new_bin_score - 15.0; // calibrated so decent fits beat opening
    } else {
        // Mild preference for bins already below mean residual (consolidation)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Time horizon: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - tightness);

    // Many open bins: encourage filling rather than spreading
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post-residual with smooth non-linear shaping
    let mut score = r + 40.0 * rn * rn * (1.0 - rn);

    // Stream-progress coupling: penalize residual more as stream advances
    score *= 1.0 + 0.5 * t * t;

    // Reward tight fits (small post_residual) with smooth decay
    score -= 25.0 * (-r / 15.0).exp();

    // Lookahead coupling: bonus if next item fits in post residual
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) - 5.0 * t;
    }

    // Mean-residual coupling: prefer bins deviating below mean (consolidation)
    score += 0.15 * (mean_residual - r).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod 10.
    let res_mod = post_residual % 10;
    // Exact-fit classes are golden: reward them strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if res_mod == 0 {
        // Leftover divisible by 10 keeps small items (10..80) packable later.
        score -= 12.0;
    } else if res_mod <= 3 {
        // Tiny dead sliver, nearly useless: penalize.
        score += 15.0;
    } else if res_mod <= 6 {
        score += 4.0;
    } else {
        // res_mod in 7..9: moderately reusable.
        score -= 2.0;
    }

    // Integer-division thresholds on post_residual: which size classes can still fit.
    if post_residual >= 80 {
        score -= 8.0;
    } else if post_residual >= 50 {
        score -= 4.0;
    } else if post_residual >= 30 {
        score -= 1.0;
    } else if post_residual < 10 {
        // Bin essentially closed; neutralize residual bias so near-full bins win.
        score -= 20.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect or near-perfect lookahead match is highly desirable.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0;
            } else if gap <= 5 {
                score -= 25.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; slightly penalize wasting this bin's slot.
            score += 3.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste < 0.25 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // but relax the penalty late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (open_bins_count as f64 / 20.0).min(1.0);
        score += 18.0 - 10.0 * progress - 6.0 * crowding;
        // A new bin is attractive if the best fit leaves a big unusable remainder.
        if post_residual < 10 && item_size < bin_capacity {
            score += 5.0;
        }
    }

    // Mild consolidation pressure: prefer bins whose residual is below mean
    // (filling the emptiest bins first keeps many mid-size residuals alive).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size is 1) are penalized, especially gaps that cannot hold
    // the known next item.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 25.0; // tiny dead gap, nearly unusable
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap cannot host the lookahead item: dead space until a small item arrives
        score += 12.0 + 0.4 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0; // gap exactly fits the next item: excellent chain
    }

    // Reward tight fits relative to item size
    score -= 30.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Pressure from many open bins: prefer consolidating into existing bins
    // rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when existing bins would
    // leave large unusable gaps; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 55.0 + 1.5 * open_bins_count as f64;
        // if current item is huge relative to mean residual, opening fresh is ok
        if mean_residual > 0.0 && (item_size as f64) > mean_residual + 30.0 {
            score -= 70.0;
        }
    }

    // Mild pull toward bins with residual close to the mean (typicality)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // 2-step lookahead: reward exact/near match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / (bin_capacity as f64));
        } else {
            // next item cannot fit here; penalize leaving large unusable residue
            let gap = next_item_size - post_residual;
            score += 0.35 * gap as f64;
        }
    }

    // Relative-to-mean residual: bins far below mean residual are "drier";
    // prefer filling them to consolidate.
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.15 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize the new-bin candidate unless it offers a great lookahead chain
    // (empty bin has residual == capacity; tightness ~ item_size/100 keeps it competitive).
    if bin_residual == bin_capacity {
        score += 6.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Slight preference to keep number of open bins low late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (best-fit core).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize residual too small for the next item (likely dead space).
            let waste = (next_item_size - post_residual).min(item_size) as f64;
            score += 6.0 * waste / bin_capacity as f64;
        }
    }

    // Penalize opening a new bin when existing bins fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let pressure = mean_residual / bin_capacity as f64;
            // Open new bin only under high residual pressure / late stream.
            score += 25.0 + 15.0 * (1.0 - pressure) - 10.0 * progress;
        } else {
            score -= 5.0; // last resort: new bin is fine
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 18.0;
    }

    // Mild preference to fill bins with larger residuals (consolidation).
    score -= 0.05 * bin_residual as f64 / bin_capacity as f64 * mean_residual.max(1.0).ln();

    // Slight penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimizing leftover space after placement
    let mut score = post;

    // Normalized post-residual for smooth non-linear coupling
    let post_norm = post / cap;

    // Reward tight fits with a non-linear (quadratic) term:
    // tight fits (small post_residual) get progressively larger discounts
    score -= 2.5 * (1.0 - post_norm) * (1.0 - post_norm) * cap * 0.1;

    // Penalize dead space that grows super-linearly (hard-to-fill leftovers)
    score += 0.8 * post_norm * post_norm * cap * 0.1;

    // Stream progress coupling: early on, keep bins flexible (mild penalty for very tight fills
    // wastes nothing since future items unknown); late in stream, reward tightness more strongly.
    let tightness = 1.0 - post_norm;
    score -= 1.5 * progress * tightness * tightness;
    score += 0.5 * (1.0 - progress) * post_norm;

    // Lookahead: if next item fits exactly in post_residual, strongly reward this placement
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post;
        if next_fits {
            let next_norm = next_item_size as f64 / cap;
            score -= 3.0 * (1.0 - ((post - next_item_size as f64) / cap).abs());
        } else {
            // If next item cannot fit here anyway, slight penalty for wasting large residual
            score += 0.3 * post_norm * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 2.0 * tightness;
    }

    // New-bin candidate handling: brand-new empty bin should only win when no open bin
    // offers a decent fit. Penalize it, more so as open bins exist and fit is acceptable.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, consolidation matters more; make new bins even less attractive
        score += 3.0 * progress;
    }

    // Mild penalty for proliferating bins when mean residual is still large (consolidation pressure)
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).max(0.0) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (eighths). Small leftovers in low classes are dead space.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Penalize residuals in "awkward" harmonic bands: (0.25,0.5) and (0.5,0.75)
    // are hard to fill for typical items; exact quarters are reusable.
    let eighth = (frac * 8.0).floor();
    match eighth as u32 {
        0 => score -= 8.0,          // near-perfect fill
        1 => score -= 2.0,          // small but usable
        2 | 3 => score += 6.0,      // awkward half-ish band
        4 => score -= 1.0,          // exact half: flexible
        5 | 6 => score += 3.0,      // awkward three-quarter band
        _ => score -= 4.0,          // nearly empty bin: very flexible
    }

    // Integer-division threshold: can next item fit exactly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        // Bonus for exact harmonic match (next item fills residual to a quarter multiple)
        let new_res = post_residual - next_item_size;
        if new_res % (bin_capacity / 4) == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: this residual is likely terminal dead space
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish, slightly worse than a good fit
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in stream, opening bins is cheap; late, discourage proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If many bins are open already, discourage new ones
        score += (open_bins_count as f64) * 0.4;
    }

    // Mild coupling to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to be
    // useful for typical items are heavily penalized (unusable dead space).
    if post_residual > 0 {
        if post_residual < 10 {
            // Gap too small for any item -> pure dead space, strong penalty.
            score += 60.0;
        } else if post_residual < 25 {
            // Small gap: likely unusable dead space, strong penalty.
            score += 35.0;
        } else if post_residual < 50 {
            // Medium gap: moderate penalty scaled by gap size.
            score += 12.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 50.0;
    }

    // Reward placements that leave room for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap blocks the next item: dead space from lookahead perspective.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (filling existing bins) rather than spreading items.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * 4.0;

    // Slight preference for bins with below-mean residual (fill emptier bins less,
    // keep balanced residuals): penalize bins whose residual is far above mean.
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 5.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 3.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; only
    // attractive if the current item would leave a tiny dead gap everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        if post_residual < 10 {
            // But if no open bin fits well, a fresh bin is fine (its post_residual
            // is large, so this branch rarely triggers for the empty bin itself).
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight lookahead match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item fits here: reward closeness to perfect match
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space relative to lookahead item: penalize proportionally
            score += 0.8 * gap;
        }
        // Extra penalty if leftover is unusable-small relative to typical item scale
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Compare against mean residual: prefer bins that stay near the pack's average fill
    let drift = post_residual as f64 - mean_residual;
    score += 0.15 * drift;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating many sparse bins when many bins are already open
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let escape_pressure = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        score = bin_capacity as f64 - escape_pressure
            + 0.5 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Slight stream-position modulation: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Penalize large dead space quadratically
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: reward if the next item fits into post_residual (chaining placements)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + 0.5 * (next_item_size as f64);
        } else {
            // dead space unusable by next item -> mild penalty scaled by gap
            let gap = (post_residual as f64) - (next_item_size as f64);
            score += 20.0 + gap.abs().min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer bins with below-mean residual (keeps mean residual spread balanced)
    score += (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.8;

    // New-bin candidate: usually worse than reusing, unless all fits are terrible
    if bin_residual == bin_capacity {
        let best_possible_penalty = (post_residual as f64).powi(2) / (bin_capacity as f64);
        score += 120.0 - best_possible_penalty.min(120.0);
        // late in stream, opening a fresh bin is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * progress;
    }

    // Slight preference for filling nearly-full bins as stream progresses
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / cap;

    // Base: waste after placement, softly penalized
    let mut score = pr_n * pr_n * 30.0 + pr_n * 10.0;

    // Smooth polynomial coupling of waste with stream progress:
    // late in the stream, tight fits matter more
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (pr_n * pr_n) * (60.0 * p2 + 40.0 * p3);
    score -= 15.0 * progress * (1.0 - pr_n);

    // Perfect fit reward (smooth, quadratic in small residual)
    if pr == 0 {
        score -= 50.0 + 30.0 * progress;
    } else {
        score += 20.0 * (1.0 - (pr_n * 4.0).min(1.0)) * pr_n;
    }

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (1.0 + p2);
        } else {
            let gap = (ni - pr) / cap;
            score += 18.0 * gap * (1.0 + p2);
        }
    }

    // Last-chance bin: strong reward to use it rather than open new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening bins late, mildly early
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (smooth)
    score += (pr - mean_residual) / cap * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is worse
    let pr = post_residual;
    let class = pr % 10;
    score -= (10 - class) as f64 * 0.35; // reward residuals near "clean" multiples

    // Fractional capacity coupling: post_residual as fraction of capacity
    let frac = pr as f64 / cap;
    if frac < 0.05 {
        score -= 25.0; // near-perfect fill
    } else if frac < 0.15 {
        score -= 8.0;
    } else if frac > 0.5 {
        score += 10.0; // wasteful half-empty placement
    }

    // Integer-division threshold: can post_residual host a small future item?
    let min_item = 1u32;
    if pr >= min_item && pr < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead harmonic check: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item divides into residual nicely
            let ratio = pr as f64 / next_item_size as f64;
            if (ratio.fract() - 0.5).abs() < 0.25 {
                score -= 12.0;
            }
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            score += 5.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening unless existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= bin_residual - item_size.min(bin_residual) {
            score += 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Deviation from mean residual: prefer bins whose residual differs from mean
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space): residuals that nothing small (<=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // semi-dead: only tiny items could fit
        score += 8.0;
    }

    // Reward tight fits (perfect fills)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if next item fits in post_residual, reward keeping this bin viable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit: this bin becomes dead for the future
        score += 5.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open bins pressure: many open bins -> avoid opening/keeping bins with slack
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.4 * open_pressure;

    // New-bin candidate: penalize opening a new bin, more so if good fitting bins exist
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * fitting_bins_count as f64;
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize residual too small for the next item (dead space creation)
        if post_residual < next_item_size && post_residual > 0 {
            score += 20.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity {
        score += 50.0 + 10.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0; // new bin can host both current and next item
        }
    }

    // Late-stream consolidation: tighten as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: if next item can fit into post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // exact pairing bonus
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slightly penalize wasting a good bin
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless current
    // bins have poor fits (large mean residual mismatch with item)
    if bin_residual == bin_capacity {
        let poor_fit_pressure = (mean_residual - item_size as f64).max(0.0);
        let late_stream = step_index as f64 / (total_items.max(1) as f64);
        // base cost of a new bin
        score += 40.0;
        // if open bins are full-ish and item is large, new bin becomes attractive
        score -= poor_fit_pressure * 0.8;
        score -= late_stream * 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // avoid opening extra bins when many are already open with room
        score += open_bins_count as f64 * 1.5;
    } else {
        // Mild reward for filling existing bins deeper
        let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 4.0 * fill_ratio;
    }

    // Penalize creating residual far from mean (fragmentation of the pool)
    let drift = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * drift;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Quadratic waste penalty: dead space grows super-linearly in cost
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Coupling with stream progress: early on, tolerate loose fits to keep bins flexible;
    // later, prioritize filling bins tightly.
    score -= 8.0 * (1.0 - progress) * (pr / (1.0 + pr));

    // Mean residual coupling: if this bin's post-residual deviates below mean, reward it
    let mean_norm = mean_residual / cap;
    score -= 5.0 * (mean_norm - norm_pr) * (1.0 - norm_pr).max(0.0);

    // Lookahead: reward if next item fits exactly in the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor using a bin when it's the only one that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for proliferating bins
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: keep it slightly unattractive unless post_residual is large
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: which "slot" of 10 units.
    let slot = post_residual / 10;
    let frac = (post_residual % 10) as f64;

    // Dead space penalty grows sharply for small unusable residuals (1..9).
    if post_residual > 0 {
        score += 60.0 / (post_residual as f64 + 1.0);
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Reward residuals that form "harmonic" slots: multiples of 10 or 25 are reusable.
    if post_residual % 10 == 0 {
        score -= 12.0 + slot as f64;
    }
    if post_residual % 25 == 0 {
        score -= 10.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward more when the leftover after next item is again harmonically clean.
            let nx = post_residual - next_item_size;
            score -= 20.0 + (nx % 10 == 0) as i32 as f64 * 10.0;
        } else {
            // Next item can't use this residue: penalize by how much is stranded.
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: prefer tightest packing, minimal leftover.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: bias depends on stream progress and mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0
            - 20.0 * progress
            - (mean_residual / 10.0).min(10.0)
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
    }

    // Mild preference for fuller bins early (leave big bins for big items).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Discourage scattering across too many open bins.
    score += open_bins_count as f64 * 0.3;

    // Fractional residue penalty: odd remainders create dead space.
    score += frac * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100
    // interface => use a conservative small-item threshold of 10).
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Coupling: penalize leaving a gap that the next item cannot use
    // (wasted residual relative to lookahead).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual {
            // Gap unusable by next item: penalize proportionally to gap size
            score += 0.5 * post_residual as f64;
        } else {
            // Gap usable by next item: reward
            score -= 0.5 * post_residual as f64;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins
    // and encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many open bins exist or
        // mean residual is large (existing bins have plenty of room).
        score += 25.0 + 5.0 * open_pressure + 10.0 * (1.0 - progress);
        // If no open bin can fit, this penalty is moot anyway since other
        // candidates score high; keep baseline so it's chosen when necessary.
    } else {
        // Existing bin: mild reward scaled by how much it reduces fragmentation
        score -= 2.0 * (bin_residual - post_residual) as f64 / bin_capacity as f64;
    }

    // Prefer bins with residual close to the item (tightest fit wins).
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual can host the next item,
    // extra reward for an exact 2-chain match (post_residual == next_item_size
    // or next_item_size + a small trailing remainder).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0; // perfect 2-chain
        } else {
            score -= (gap as f64).min(30.0) * 0.5; // closer match = better
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow in this bin: penalize proportional to wasted potential.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize small unusable dead space (dead space < typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean term: prefer bins whose residual deviates favorably.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 + (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else (large item, few fitting bins) or the
    // stream is early (plenty of future items to fill a fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Cost of a fresh bin: high late in the stream or for small items.
        score += 120.0 - fit_ratio * 80.0 + progress * 60.0;
        if fitting_bins_count > 2 {
            score += 40.0; // plenty of alternatives, don't open a new bin
        }
        // Large item near capacity: new bin is fine.
        if fit_ratio > 0.7 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: square the post-residual so small leftovers dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Penalize bins far from the mean residual (avoid stragglers).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.25;
        } else {
            // Next item won't fit here; penalize dead space that can't serve lookahead.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item in stream: minimize post residual aggressively.
        score -= 20.0;
    }

    // Time horizon: early on, be more willing to open fresh bins (penalize new bin less);
    // late in the stream, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 - 30.0 * progress;
        // Opening a new bin is attractive only if no bin fits well (large post residual elsewhere).
        if fitting_bins_count > 0 {
            let best_possible = post_residual.min(100);
            let _ = best_possible;
            score += 15.0;
        }
    }

    // Reward using bins that are nearly full already.
    if bin_residual < bin_capacity && post_residual <= 10 {
        score -= 12.0;
    }

    // Mild penalty for accumulating too many open bins early.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Penalize exact 50/50 splits slightly (flexibility loss).
    if post_residual == bin_capacity / 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post;

    // Smooth polynomial shaping: penalize mid-range waste more as stream progresses
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like in [0,1]
    score += poly * (20.0 + 60.0 * progress);

    // Tight fits (small post residual) are rewarded more early, and extra late
    let tight = (1.0 - x) * (1.0 - x);
    score -= tight * (10.0 + 30.0 * progress);

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= (nx / cap) * 15.0;
        } else {
            let gap = (nx - post) / cap;
            score += gap * gap * 40.0;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Mild pressure toward consolidation when many bins are open
    score += (open_bins_count as f64).ln_1p() * 2.0;
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by 10 pair better with typical item sizes.
    let post = post_residual;
    let class = post % 10;
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if class == 0 {
        score -= 18.0; // round residual, highly reusable
    } else if class == 5 {
        score -= 8.0; // half-class, moderately reusable
    } else if class <= 3 {
        score += 12.0; // tiny dead space
    } else {
        score += 4.0;
    }

    // Integer-division thresholds: can the leftover host a "harmonic bucket"
    // of the next item (or a small generic item)?
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits here: strong reward, scaled by tightness of fit
            let slack = (post - next_item_size) as f64;
            score -= 30.0 - 0.25 * slack;
            if (post % next_item_size.max(1)) == 0 {
                score -= 10.0; // exact harmonic division
            }
        } else {
            score += 10.0; // lookahead cannot chain here
        }
    } else {
        // last item: just minimize waste
        score -= 20.0;
    }

    // Generic small-item hosting capacity: how many 10-units fit in leftover
    let units = post / 10;
    score -= 3.0 * units as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a bin unless current placement
    // would leave a badly fragmented residual.
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if residual after would be very small for the next item anyway,
        // and this is late in the stream, opening fresh is fine
        if next_item_size > 0 && post > 0 && (post as f64) < 0.35 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Stream progression: early on, keep bins open and flexible;
    // late, prefer tight packing aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post as f64 / bin_capacity as f64);

    // Spread pressure: many open bins with high mean residual -> favor
    // filling existing bins rather than proliferating.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gap threshold ~ smallest item 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 8.0 * (1.0 - tightness.min(1.0));
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 15.0 - slack;
        }
    }
    // Penalize if next item would NOT fit here (bin becomes dead for next step).
    if next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: bins far below mean residual are "loose";
    // prefer bins whose residual is closer to the mean to keep balance.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Late in the stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powf(2.0) * 10.0;

    // 2-step lookahead: perfect match for the next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // exact fill: bin becomes perfect for next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward leaving room for next item, penalize large leftover slack
            score -= 15.0 - 0.15 * slack;
        } else {
            // next item cannot fit here; dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap;
        }
    }

    // Relative-to-mean residual coupling: avoid leaving residuals far from mean.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
    }

    // Late in stream: consolidation matters more; discourage spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.02 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * chain_quality;
        } else {
            // Post residual can't host next item: mild penalty scaled by waste size.
            score += 0.05 * (post_residual as f64 - (post_residual as f64 % next_item_size.max(1) as f64));
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be picky (penalize loose fits); late, fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.15 * post_residual as f64;
    score -= progress * 10.0 * tightness;

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual here = full empty capacity) or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_waste = mean_residual - item_size as f64;
        let existing_bad = if mean_residual > 0.0 && mean_waste < 15.0 { 1.0 } else { 0.0 };
        score += 18.0
            - 20.0 * desperation
            - 15.0 * existing_bad
            - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth non-linear penalty on post_residual, growing with stream progress
    score += 4.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits via cubic coupling with progress
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio * fit_ratio * (1.0 - progress);

    // Penalize dead space far from mean residual (smooth quadratic coupling)
    let dev = post - mean_residual;
    score += 0.02 * dev * dev;

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 3.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 1.5 * (-gap / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild preference for consolidating into fewer bins early
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable"
    // (>= 10 or exactly 0) are good; tiny non-zero residues are dead space.
    let r = post_residual;
    if r == 0 {
        score -= 30.0; // perfect closure
    } else if r < 10 {
        score += (10 - r) as f64 * 2.0; // unusable dead space penalty
    }

    // Integer-division threshold: how well the residual decomposes into
    // typical item classes (mod-10 granularity).
    let deciles = r / 10;
    score -= deciles as f64 * 1.5; // reward residuals that hold future items

    // Tightness: reward filling a large fraction of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Lookahead coupling: penalize if post_residual cannot host the next item
    // but is too large to be dead space either.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward residuals that keep useful, next-item-compatible slack
            score -= 4.0;
            // harmonic class: residual exactly matching a future-friendly band
            if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
                score -= 3.0;
            }
        } else if post_residual > 0 {
            score += 5.0; // stranded slack
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, favor consolidation (lower residual bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= mean_residual * 0.05 * (open_bins_count as f64).sqrt() * (1.0 - progress * 0.5);

    // New-bin candidate: neutral-ish baseline; only attractive when no
    // open bin offers a decent fit (post_residual here == capacity - item).
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 20.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // forced open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderate dead space: partial penalty unless next item could use it.
        if next_item_size > post_residual {
            score += 15.0;
        } else {
            score -= 20.0; // gap is usable by lookahead: reward tight fit
        }
    }

    // If lookahead item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead cannot use remaining space: penalize proportionally.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: penalize placing into already-open bins when many are open,
    // encouraging consolidation; but a brand-new bin (residual == capacity) gets
    // a baseline penalty so it's only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 80.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
        // Favor fullest bins (tight packing): lower residual = better fit.
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Early in stream, be slightly more willing to open bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if item_size > 50 && bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when the residual after placement
    // matches the next item size (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space relative to the next item: penalize unusable leftovers.
            let dead = post_residual as f64;
            score += dead * dead * 0.05;
        }
        // If next item can't fit anywhere else either, prefer bins leaving room for it.
        if next_item_size > post_residual && post_residual > 0 {
            score += 20.0;
        }
    } else {
        // Last item: prefer filling as tightly as possible.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight"
    // and should be prioritized for filling; bins above mean are loose.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (post_residual would be large dead space) or the stream
    // is early with few open bins.
    if bin_residual == bin_capacity {
        let is_last_chance = fitting_bins_count == 0;
        let poor_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.25 && open_bins_count < 4;
        if is_last_chance || (poor_fit && !early) {
            score -= 80.0;
        } else {
            score += 150.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 6.0 + 4.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(3.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Many fitting bins: slight penalty to preserve diversity of residuals.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Time horizon: early in stream, encourage consolidation; late, tolerate new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (1.0 - progress);

    // Penalize bins far below the mean residual (unbalanced fills).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Reward filling bins nearly to capacity (waste minimization).
    if post_residual <= 5 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 40.0 - 30.0 * pressure - 10.0 * progress;
        if item_size >= 70 {
            score -= 15.0; // large items are fine in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: penalize leftover space quadratically (wasted capacity grows superlinearly)
    let mut score = post * post / cap;

    // Smooth normalized residual: reward tight fits via saturating term
    let norm_post = post / cap;
    score += 30.0 * (norm_post * norm_post / (1.0 + norm_post));

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap) * (0.5 + progress);
        } else {
            // residual too small for next item: penalize dead space more later in stream
            score += 8.0 * progress * (1.0 - norm_post);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: prefer opening a new bin only when existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, reduced late in stream / when many bins open
        score = 55.0 - 10.0 * progress - (open_bins_count as f64).sqrt() * 2.0;
        // if item is large, new bin is attractive (little waste left anywhere)
        score -= 0.3 * item;
        // if mean residual across open bins is small, opening is fine
        score += 0.2 * mean_residual;
    } else {
        // mild reward for draining existing bins when many are open
        score -= 0.05 * open_bins_count as f64 * (1.0 - norm_post);
        // early stream: slight preference to fill existing bins to limit bin count
        score -= 5.0 * (1.0 - progress) * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (residual 0) are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes: residuals that are multiples of common item sizes (10..80)
        // are more likely reusable. Reward residuals divisible by small harmonics.
        let r = post_residual;
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if r % m == 0 {
                harmony += 8.0;
            }
        }
        if r % 5 == 0 { harmony += 2.0; }
        score -= harmony;

        // Dead-space penalty: residual too small for the smallest plausible item.
        if r < 10 {
            score += 60.0;
        } else if r < 20 {
            score += 25.0;
        }

        // Integer-division thresholds: residual in [1, half-cap] is "fragmented".
        let half = (r * 2) / bin_capacity; // 1 if r >= cap/2
        if half == 0 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Fractional tightness of the lookahead fit
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 60.0 * tight;
        } else {
            // Next item won't fit here: slight penalty scaled by waste
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize opening a new bin early on; relax later in stream
    // and when many bins are open with high mean residual (fragmentation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 25.0 * progress;
        if open_bins_count > 0 {
            score += 0.15 * (mean_residual - 50.0).max(0.0);
        }
        // Opening a bin is fine if item is large relative to capacity
        score -= 0.3 * item_size as f64;
    }

    // Prefer tighter fits generally: reward small post_residual via capacity fraction
    score -= 0.5 * (1.0 - post_residual as f64 / cap) * (post_residual as f64 / cap) * 4.0;

    // Mild penalty for spreading across too many bins when mean residual is low
    if open_bins_count > 3 {
        score += 0.02 * open_bins_count as f64 * (50.0 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    let dead_threshold = 10.0f64.min(cap * 0.5);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: fraction of bin used.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill;

    // Prefer bins whose residual is close to item size (low fragmentation).
    let waste_ratio = (bin_residual - item_size) as f64 / cap;
    score += 20.0 * waste_ratio * waste_ratio;

    // Lookahead: if the next item fits in post_residual, reward; else penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > bin_residual {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3;

    // New-bin candidate: only attractive if it enables a good future fit
    // (e.g., next item is large and no open bin has room for both).
    if bin_residual == bin_capacity {
        let base = cap * 0.85 + pressure * 0.5;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score = base - 10.0;
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but discount relative to mean residual
    score -= 0.5 * mean_residual;

    // Aggressive 2-step lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Perfect match: next item exactly fills the leftover space
            let diff = pr - nxt;
            if diff == 0.0 {
                score -= 40.0;
            } else {
                // Reward proportional to how close next item is to filling post_residual
                let tightness = 1.0 - diff / pr.max(1.0);
                score -= 25.0 * tightness;
            }
        } else {
            // Next item cannot fit: leftover space is likely dead space for lookahead
            // Penalize wasted space that the next item cannot use
            let waste = (pr - (pr % nxt)) / pr.max(1.0); // fraction unusable by next item
            score += 15.0 * (1.0 - waste);
        }
    }

    // Penalize small unusable remnants (dead space < 10, likely wasted)
    if post_residual < 10 && post_residual > 0 {
        score -= 20.0; // nearly-full bin is excellent
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    }

    // Penalize very large post_residual (bin left mostly empty) unless it matches next item
    if post_residual as f64 > mean_residual * 1.5 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in stream: be more liberal with opening bins (favor tight fits over spreading)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little waste.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect or near-perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Lookahead (k=2): reward bins whose post-residual could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that is useless for the next item
        // (dead space between 1 and next_item_size - 1).
        let dead = post_residual as f64 / next_item_size as f64;
        score += 8.0 * dead;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current bin's fit is poor (large post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1 - item/C
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheap; late, avoid fragmentation.
        let open_cost = 60.0 - 30.0 * horizon;
        score += open_cost * (1.0 - scarcity) - 10.0 * poor_fit * poor_fit;
        // Prefer new bin when it enables a better long-run structure:
        // large items deserve fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Global pressure: when many bins are open with high mean residual,
    // encourage consolidating into existing bins rather than spreading.
    if bin_residual < bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 5.0 * pressure * (open_bins_count as f64).ln().max(0.0) / 4.0;
    }

    // Mild penalty for leaving residuals in the awkward 1..=10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 - progress) + norm_pr * norm_pr * progress;
    score += 20.0 * poly;

    // Penalize very small dead space more strongly as stream advances
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 15.0 * tightness * (0.5 + progress);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 10.0 * fit_quality * (0.4 + 0.6 * progress);
    } else if next_item_size > post_residual {
        score += 5.0 * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: mildly penalize early, allow later
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Discourage scattering across many bins when residuals are large
    let mr = mean_residual / cap;
    score += 5.0 * (norm_pr - mr).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Class-1: post_residual in a "golden" small band (near-perfect fit) -> reward heavily.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Class-2: dead-space classes via modulo 10 — residuals like 1..9 (mod 10) are hard to fill.
    let dead_class = post_residual % 10;
    if dead_class > 0 && dead_class < 5 {
        score += 8.0; // awkward sliver
    } else if dead_class >= 5 && dead_class <= 9 {
        score += 3.0;
    }

    // Integer-division thresholds: post_residual / 10 classes.
    let post_div = post_residual / 10;
    score += (post_div as f64) * 2.5; // larger leftover class penalized mildly

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // harmonic match classes: exact / near / coarse match
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 50.0;
            } else if slack <= 10 {
                score -= 30.0;
            } else if slack <= 25 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize proportional to wasted potential
            score += (next_item_size as f64 - post).min(40.0) * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it's chosen only
    // when open bins would create bad fits.
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.15;
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - post).max(0.0) * 0.2;

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post / cap);

    // Mild penalty per open bin to encourage consolidation when residuals are similar.
    score += (open_bins_count as f64).ln().max(0.0) * (post / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more aggressively than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fits are highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure on open bin count: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 2.0;
    } else {
        score -= (open_bins_count as f64).sqrt() * 1.5;
    }

    // Lookahead: if next item fits into the post residual, reward keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Prefer filling bins with lower residual relative to mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this is an ideal pairing — heavily reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let next_post = post_residual - next_item_size;
            // Reward pairings that leave a small, still-usable remainder.
            score -= (next_item_size as f64) * 0.8;
            if next_post <= 5 {
                score -= 100.0;
            } else {
                score -= (5.0 / next_post as f64) * 20.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much of the post-residual is "wasted" relative to next item.
            let waste = next_item_size as f64 - post_residual as f64;
            score += waste * 0.5;
        }
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins that are already relatively full (low residual vs mean).
    let residual_gap = mean_residual - bin_residual as f64;
    score -= residual_gap * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent open bins exist and the
    // stream is progressing (late items should consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 50.0 + 100.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin is attractive if the next item is large
            // and would pair well with a full bin after this placement.
            if post_residual >= next_item_size {
                score -= 80.0;
            }
        }
    }

    // Mild penalty for leaving large dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    if dead_frac > 0.2 {
        score += dead_frac * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative waste penalty (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing (min size 1..100 unknown) can use,
    // but reward near-zero post residuals strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    } else if post_residual > 50 {
        score += 6.0; // leaving huge slack is wasteful for medium items
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: penalize opening a new bin when decent
    // alternatives exist; allow it when open bins are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_open_fullness = (bin_capacity as f64 - mean_residual).max(0.0);
        let pressure = avg_open_fullness / bin_capacity as f64;
        // new bins are attractive early (many future items) or when bins are full
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 35.0 * pressure - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must use this bin
        }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fit;
        } else {
            // next item won't fit here; slight penalty for leaving medium gaps
            score += 3.0;
        }
    }

    // Global state coupling: when mean residual is low, conserve slack in
    // bins that still have room; when mean residual is high, spread items.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.05 * (post_residual as f64 - mr).abs();

    // Mild preference for using already-open bins vs opening many bins.
    if !is_new_bin {
        score -= 2.0 * (open_bins_count.min(20) as f64).ln().max(0.0);
    }

    // Small time-varying jitter-free modulation of tightness pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize large post residual, non-linearly
    let mut score = pr * (1.0 + norm_pr * norm_pr * 2.0);

    // Smooth interaction: residual vs stream progress (late stream: prefer tight fills)
    let prog_sq = progress * progress;
    score += 20.0 * norm_pr * prog_sq * (1.0 - progress);

    // Reward tight fits more as stream progresses
    score -= 12.0 * norm_item * norm_item * (0.5 + progress);

    // Dead space penalty: post residual too small for typical future items
    let tiny = (1.0 - (pr / 10.0).min(1.0)) * (pr / 10.0).max(0.0);
    score += 8.0 * (1.0 - tiny) * (1.0 - pr / 10.0).max(0.0) * (1.0 + progress);

    // Lookahead coupling: bonus if next item fits post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_q = (nx / pr).max(0.0);
            score -= 10.0 * fit_q * (1.0 - fit_q) * 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * ((nx - pr) / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mean residual deviation: prefer bins below mean residual (consolidate fullness)
    let dev = (mean_residual - pr) / cap;
    score += 5.0 * dev * (0.5 + progress);

    // Mild penalty for many open bins when residual is still large
    score += (open_bins_count as f64).ln() * norm_pr * 3.0;

    // New-bin candidate: penalize slightly unless current bins are all poor fits
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual relative to capacity quarters.
    let q = bin_capacity / 4;
    if post_residual > 0 {
        if post_residual < q / 4 {
            // Tiny dead space (1..6): nearly unusable — penalize hard.
            score += 40.0;
        } else if post_residual < q {
            score += 10.0; // small leftover, mildly wasteful
        } else if post_residual < 2 * q {
            score -= 5.0; // quarter-to-half space still reusable
        } else if post_residual < 3 * q {
            score -= 10.0; // half-to-three-quarter: very reusable
        } else {
            score -= 15.0; // large residual: best reuse potential
        }
    }

    // Modular affinity: reward if next item divides into post_residual
    // (post_residual % next_item_size small => good chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let r = post_residual % next_item_size;
        let ratio = next_item_size as f64 / post_residual as f64;
        if r == 0 {
            score -= 25.0 * ratio; // next item tiles residual exactly
        } else if r < q / 4 {
            score += 8.0 * ratio;  // next item leaves a sliver: bad chain
        } else {
            score -= 6.0 * ratio;  // decent chain fit
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; leftover becomes dead unless large.
        if post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: baseline high; open only when no decent fit exists.
    if bin_residual == bin_capacity {
        score = cap + 50.0;
        // Open a fresh bin early in the stream when bins are few (future flexibility),
        // or when the current fit is terrible (large item into a bin it barely fits,
        // leaving a sliver).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual > 0 && post_residual < q / 4;
        if open_bins_count < 3 && progress < 0.5 {
            score -= 70.0;
        }
        if poor_fit && fitting_bins_count <= 2 {
            score -= 55.0;
        }
        // Late in stream, avoid proliferation: keep new bins expensive.
        if progress > 0.8 {
            score += 20.0;
        }
    }

    // Mild tie-break toward consolidating into fuller bins.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize moderately so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is huge, a fresh bin is fine.
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 10.0;
    }
    if next_item_size > 0 && (post_residual as i64) > 0 && (post_residual as i64) < (next_item_size as i64) {
        score += 5.0;
    }

    // Prefer bins below mean residual (keeps residuals balanced).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial lookahead reward: how well the leftover matches the next item.
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (-gap / 20.0).exp();
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to how much dead space remains.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }

    // Reward tight fills relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Compare post_residual against mean residual: leaving near-mean residual is neutral,
    // much smaller residual (good packing) is rewarded, much larger is penalized.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Brand-new bin candidate: penalize mildly so we only open new bins when
    // existing bins have genuinely poor fits; scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 6.0 * progress;
    }

    // Prefer bins with less residual overall (best-fit core), slightly damped.
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, normalized by capacity.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * post_frac * post_frac;

    // Reward tight fits: small post residual relative to item size.
    if item_size > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / item_size as f64).max(0.0);
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize slightly unless this is a perfect fit.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residuals close to item size (best-fit style) among many options.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.35 * gap;

    // Global state coupling: when mean residual is high and many bins are open,
    // encourage filling existing bins rather than spreading.
    if open_bins_count > 2 {
        score -= 0.10 * mean_residual.min(100.0);
    }

    // Time horizon: early in stream, be more willing to open new bins (score for
    // empty bin candidate relatively attractive); late in stream, consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 30.0 * t;
        // But if nothing open fits well, opening is fine early.
        if fitting_bins_count == 0 {
            score -= 20.0 * (1.0 - t);
        }
    }

    // Mild penalty for leaving residuals that no plausible small item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty growth
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Polynomial coupling of post-residual with stream progress:
    // early on, waste is cheap; late, waste is heavily penalized
    let progress_coupling = norm_pr * (1.0 + 2.0 * progress + 3.0 * progress * progress);
    score += 40.0 * progress_coupling * cap;

    // Reward tight fits (post_residual near zero) more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: favor bins whose residual can hold the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let fit_quality = (pr - n) / cap;
            score -= 20.0 * (1.0 - fit_quality) * (1.0 - fit_quality);
        } else {
            score += 15.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Penalize bins far from mean residual (fragmentation signal)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // Many open bins: mild pressure to consolidate into existing bins
    score -= 2.0 * (open_bins_count as f64).ln() * tightness;

    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: coarse granularity buckets.
    // Leftovers in [0,10) are near-perfect; [10,50) moderately useful; [50,100) wasteful.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,
        1..=10 => 1.0,
        11..=25 => 2.0,
        26..=50 => 3.0,
        _ => 4.0,
    };
    score += class * 6.0;

    // Exact-fill bonus: zero waste is ideal.
    if pr == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: does the leftover exactly accommodate a future class?
    // Use integer division thresholds on next_item_size vs post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect lookahead fit
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score += slack * 0.4;
            // Bonus if leftover splits into two harmonic slots (next fits twice)
            if pr >= 2 * next_item_size && pr / next_item_size >= 2 {
                score -= 8.0;
            }
        } else {
            // Lookahead cannot use this bin's leftover; penalize proportionally
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Modulo arithmetic on residual: leftovers that are multiples of common
    // item classes (10,20,25,50) are more reusable.
    if pr >= 10 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Avoid fragmenting when many bins fit (prefer tightest anyway via base term).
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Dead-space penalty: leftover below the minimum item size (1..10 band)
    // is fine, but leftover in the awkward 1..5 range after a large item is dead.
    if pr > 0 && pr < 5 {
        score -= 3.0; // small but truly dead space is acceptable
    }

    // New-bin candidate: only prefer opening a new bin when no open bin gives
    // a good fit (post_residual would be small) or the item is huge.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // Large items are better in fresh bins to preserve small-bin flexibility.
        if item_size >= 60 {
            score -= 20.0;
        }
        if item_size >= 80 {
            score -= 15.0;
        }
        // If open bins are already fragmented (high mean residual), fresh bin ok.
        score -= (mean_residual / cap) * 10.0;
        // Fewer open bins -> slightly cheaper to open one more.
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // Lookahead: if next item is small, a fresh bin can host it too.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 6.0;
        }
    }

    // Slight time-decay: later in stream, consolidation matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 2.0 * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are worthless, penalize hard.
    if post_residual < item_size.min(10) {
        // gap smaller than smallest plausible item -> fully wasted space
        score += 40.0 + post_residual as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap can't fit the lookahead item -> likely dead space
        score += 15.0 + 0.5 * (post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; but for
    // the new-bin candidate (residual == capacity) add a fixed opening cost
    // so it only wins when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // new bin is fine if current item is large and would leave a big gap anyway
        if item_size >= 80 { score -= 30.0; }
    } else {
        score += 0.3 * open_bins_count as f64;
    }

    // Prefer bins whose residual is already below the mean (consolidate waste).
    score += 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight late-stream bias toward closing bins out (fewer leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and next_item_size (perfect two-item fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills this bin afterwards
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item would also fit after current placement (triple stacking)
        if next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Last item: strongly prefer tightest fill
        score -= 25.0;
    }

    // Prefer bins with residuals below mean (compact bins absorb waste better)
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: only bin that fits; strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening new bin is fine if next item is large and would pair well
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 20.0;
        }
    }

    // Small penalty scaling with number of open bins to discourage sprawl
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space relative to capacity (waste fraction).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Lookahead: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax when many bins
    // are open with fragmented residuals or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 40.0;
        penalty -= progress * 15.0;
        penalty -= (open_bins_count as f64).ln() * 2.0;
        // If mean residual is small (bins are tight), new bin is more attractive.
        penalty -= (mean_residual / bin_capacity as f64) * 20.0;
        score += penalty.max(5.0);
    }

    // Mild preference for filling bins that are already quite full.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    // Slight exploration term coupling open-bin count with time.
    score += (open_bins_count as f64).sqrt() * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized post residual
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post;

    // Tight fit reward: smooth Gaussian-like bump near post_residual == 0
    let tightness = (-norm_post * 6.0).exp();
    score -= 15.0 * tightness;

    // Lookahead coupling: penalize if next item cannot use post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (nx <= post).max(0.0) as f64;
        let gap = (nx - post).abs() / cap;
        score += (1.0 - usable) * 20.0 * (1.0 - (-gap * gap * 8.0).exp());
        score -= usable * 10.0 * (1.0 - progress);
    }

    // Last-chance bin bonus: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate handling: mildly discourage early, allow late
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 30.0 * (1.0 - progress * progress) - 10.0 * progress;
    }

    // Stream-progress polynomial coupling: late stream favors consolidation
    let p2 = progress * progress;
    score -= 12.0 * p2 * (mean_residual / cap);

    // Many open bins: encourage filling existing ones
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let frac = post / cap; // 0..1
    let class = if post_residual == 0 { 0 }
        else if frac <= 0.10 { 1 }      // near-dead space
        else if frac <= 0.25 { 2 }
        else if frac <= 0.50 { 3 }
        else if frac <= 0.75 { 4 }
        else { 5 };                      // large leftover, reusable

    // Penalize small unusable leftovers, reward large reusable ones.
    let class_score = match class {
        0 => -1000.0,
        1 => 60.0,
        2 => 25.0,
        3 => 0.0,
        4 => -15.0,
        _ => -30.0,
    };
    score += class_score;

    // Modulo arithmetic: leftover that is a multiple of small item sizes (10/20)
    // is likely reusable -> reward.
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 8.0;
    }
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: reward proportionally to how well next item fills leftover.
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 20.0 + 30.0 * fill;
            // Perfect chain: next item exactly consumes leftover.
            if next_item_size == post_residual {
                score -= 150.0;
            }
        } else {
            // Next item won't fit here -> leftover risks becoming dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * gap.min(50.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or many bins are open (diversification) and item is large.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for opening a new bin.
        let mut new_bin_score = 120.0 + 5.0 * open_f;
        // If this bin is the only fit, opening is necessary -> neutralize.
        if fitting_bins_count == 0 {
            new_bin_score -= 500.0;
        }
        // Large items prefer fresh bins late in stream.
        if item_size >= 60 {
            new_bin_score -= 30.0 + 40.0 * progress;
        }
        // If mean residual is small, open bins are crowded -> new bin ok.
        if mean_residual < item_size as f64 {
            new_bin_score -= 50.0;
        }
        score = score.min(new_bin_score + post) - 0.0;
        // Ensure new bin never beats a perfect fit.
        score = score.max(-999.0);
        return score;
    }

    // Slight tie-break: prefer bins with residual close to item (tight fits).
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..=100)
    // can plausibly use are wasted. Penalize gaps in the "dead zone" heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusably tiny gap
    } else if post_residual >= 10 && post_residual <= 25 {
        // Only small items can fill this; treat as semi-dead unless lookahead fits.
        if (next_item_size as f64) > post_residual as f64 {
            score += 25.0;
        } else {
            score -= 10.0; // lookahead item fits the gap: excellent
        }
    }

    // Reward tight fits (near-perfect packing).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Reward exact closure of a bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: strongly favor bins where the next item also fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer
    // filling existing bins and avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += open_pressure * 2.0;

    // New-bin candidate (empty bin): penalize opening a new bin when existing bins
    // have reasonable residuals; allow it when current item leaves a bad gap anyway.
    if bin_residual == bin_capacity {
        score += 30.0 + open_pressure * 3.0;
        if post_residual <= 20 {
            score += 20.0; // opening a bin that immediately becomes near-dead is bad
        }
    }

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (balanced depletion) rather than outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild preference for using bins with smaller residual first (best-fit core).
    score += 0.3 * (bin_residual as f64 - post_residual as f64).signum();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score -= 100.0 - leftover_after_next as f64 * 0.5;
            if leftover_after_next == 0 {
                score -= 300.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to the gap
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // new bin still useful for chaining
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize bins that could also fit the NEXT item after placing this one
    // (wasting flexibility), unless post_residual is tiny anyway.
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score += 0.5 * waste;
    }
    // Bonus if this placement leaves exactly the next item's size (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with large mean residual => prefer consolidating into
    // bins with below-average residual (tighter bins).
    if open_bins_count > 1 {
        let deviation = mean_residual - bin_residual as f64;
        score += 0.3 * deviation;
        // Mild penalty for opening new bins when many are already open.
        if bin_residual == bin_capacity {
            score += 10.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Early in the stream: allow opening new bins more freely (exploration);
    // late in the stream: strongly prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
        score -= 5.0 * progress;
    }

    // Penalize leaving awkward residuals that few item sizes can fill
    // (residuals just above common small sizes are okay; tiny slivers are bad).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_coupling = norm_pr * norm_pr * (1.0 + t) * 30.0;
    score += progress_coupling;

    // Penalize large dead space late in the stream (smooth cubic term)
    score += norm_pr.powi(3) * t * 50.0;

    // Reward tight fits: small post_residual gets a smooth quadratic discount
    score -= (1.0 - norm_pr).powi(2) * 15.0;

    // Last-chance bin bonus (smooth, exponential saturation)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - t.exp());
    }

    // Lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 20.0).exp();
    }

    // Mild penalty when bin residual deviates from mean residual across open bins
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 5.0;

    // Slight preference to fill bins when many are open (smooth in open count)
    score += (open_bins_count as f64).ln() * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "dead space quality"
    let post_mod = post_residual % 10;
    // Residuals that are exact multiples of 10 are "harmonic" — easily filled by
    // typical item sizes; non-multiples create dead space. Penalize inharmonic.
    let inharmony = (post_mod as f64) / 10.0;
    score += inharmony * 6.0;

    // Exact harmonic fit (post_residual divisible by 10, or zero) gets a bonus
    if post_mod == 0 {
        score -= 8.0;
    }

    // Perfect fill: reward strongly
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small post_residual that is inharmonic is dead space: penalize
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // next item leaves a residual; check harmonic class of double residual
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 {
                score -= 6.0;
            } else {
                score += (r2 % 10) as f64 * 0.4;
            }
            // penalize if next item cannot fit this bin anyway (wasted pairing)
        } else {
            // next item too big for residual: residual becomes terminal —
            // penalize proportionally to how much is stranded
            score += (post_residual as f64) * 0.3;
        }
    }

    // Integer-division threshold on post_residual: classify into bands
    let band = post_residual / 20; // 0..5
    match band {
        0 => score -= 3.0,        // nearly full: good
        1 => score += 1.0,        // 20-39: awkward mid zone
        2 => score += 2.0,        // 40-59
        3 => score -= 1.0,        // 60-79: roomy but usable
        _ => score += 0.5,        // mostly empty
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to encourage tighter bins instead
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(4.0);
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity and no open bin fits well (residual of open bins would be wasted)
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Opening new bin is good for large items when mean residual is small
        let pressure = mean_residual / bin_capacity as f64;
        if frac > 0.6 && pressure < 0.25 {
            score -= 10.0;
        } else if frac > 0.75 {
            score -= 5.0;
        } else {
            // discourage scattering into new bins
            score += 10.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Progress-based mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Tie-break toward bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are dead space; penalize them heavily and non-linearly.
    if post_residual > 0 {
        let dead = (post_residual < 10) as f64;
        score += dead * 60.0;
        // Quadratic penalty on residual waste, normalized by capacity.
        let r = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * r * r;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: fraction of the bin actually consumed by this item.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: discourage spreading across many bins unless the
    // placement is genuinely good.
    score += 2.5 * open_bins_count as f64 * (1.0 - fill);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no existing bin fits well (residual far from item) or bins are few.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let best_gap = mean_residual - item_size as f64;
            // If open bins already have small residuals, opening new is wasteful.
            score += 35.0 + 3.0 * open_bins_count as f64;
            if best_gap < 5.0 {
                score += 40.0;
            }
        } else {
            // No alternative: new bin is necessary, make it cheap.
            score -= 60.0;
        }
    }

    // Lookahead coupling: prefer bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Late-stream conservatism: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference to fill bins that deviate below the mean residual
    // (concentrate waste in fewer bins).
    if bin_residual < bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: perfect match with next item is a jackpot ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            // This bin becomes exactly filled by the next item: extremely desirable.
            score -= 40.0;
        } else {
            // Penalize distance of post_residual from the next item's size.
            let gap = (pr - nxt).abs();
            score += 0.15 * gap;
            // Bonus if next item fits into the post-residual (chainable placement).
            if nxt <= pr {
                score -= 6.0 + 4.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
            }
        }
    }

    // --- Compare post_residual to mean residual of open bins ---
    let mr = mean_residual;
    if mr > 0.0 {
        let pr = post_residual as f64;
        // Post-residual far below mean => we squeezed hard: good.
        let rel = (pr - mr) / mr;
        score += 4.0 * rel;
        // Very small leftover (< mean/4) is nearly a perfect fit.
        if pr < mr * 0.25 {
            score -= 5.0;
        }
        // Large leftover (wasted dead space) is bad.
        if pr > mr * 1.5 {
            score += 6.0;
        }
    }

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if:
        //  - no existing bin fits (fitting_bins_count == 0), or
        //  - the item is large and early bins are fragmented.
        let item_frac = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a new bin
        } else if item_frac > 0.6 && progress < 0.7 {
            // Large item: a fresh bin may be better than fragmenting a good bin.
            score -= 3.0 + 5.0 * item_frac;
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 8.0 + 4.0 * (1.0 - progress);
        }
    }

    // --- Tight fit reward: small absolute post residual ---
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 10.0 {
        score -= 8.0 * (1.0 - pr / 10.0);
    }

    // Mild pressure to keep open-bin count low.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let res = bin_residual as f64;

    // Base: prefer minimizing leftover space, with a non-linear (concave) penalty
    // so that very large leftovers are disproportionately punished.
    let mut score = post + 0.35 * (post * post) / cap;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item / res.max(1.0);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Perfect-fit shaping: reward residuals that leave "usable" chunks (multiples of 10)
    let usable = (post / 10.0).floor() * 10.0;
    score -= 3.0 * (usable / cap);

    // Last-chance bonus: if this is the only bin that fits, placing here avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let next_fit = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 6.0 + 8.0 * next_fit;
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize creating stranded space.
        score += 2.0 * (post / cap);
    }

    // Global state: many open bins with high mean residual -> discourage spreading.
    if open_bins_count > 0 {
        let spread = (mean_residual - post).abs() / cap;
        score += 2.5 * spread;
    }

    // Time horizon: early in the stream, be frugal with bins (favor filling existing);
    // late in the stream, allow opening new bins slightly more readily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive when the item is large relative to
    // capacity or no good fit exists; otherwise penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        let item_frac = item / cap;
        if item_frac > 0.6 {
            score -= 5.0 + 10.0 * (item_frac - 0.6);
        } else {
            score += 10.0 + 20.0 * (0.6 - item_frac);
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic waste penalty on post-residual (dead space grows super-linearly)
    let mut score = pr * pr / cap;

    // Smooth progress coupling: early on, tolerate residual; late, punish it harder
    let prog_coupling = pr * (0.5 + 2.0 * progress * progress);
    score += prog_coupling;

    // Reward tight fits (small post_residual relative to item) via smooth interaction
    score -= (1.0 - pr / cap) * fit_ratio * 10.0;

    // Lookahead: if next item fits the post-residual exactly-ish, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize opening new bins when many open bins exist with residual
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (5.0 + 20.0 * (mean_residual / cap) * (1.0 - progress));

    // Slight preference to balance residuals across bins
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "usable" residue class (small, or matching common item sizes) are favored.
    let cap = bin_capacity as f64;

    // Fraction of capacity left after placement.
    let frac = post_residual as f64 / cap;

    // Penalize large-but-unusable leftovers: residual > 50 is awkward
    // (items are 1..100, so a residual in (50, 80) fits few future items well).
    if post_residual > 0 && post_residual < 10 {
        // Tiny dead space: nearly perfect fit, strong reward.
        score -= 12.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        // Sweet-spot residual: likely to absorb a future small item.
        score -= 6.0 * (1.0 - frac);
    } else if post_residual > 50 {
        // Large leftover is fine only if it's an exact half-class (50) or
        // leaves room for a known next item.
        score += 3.0;
    }

    // Modulo-class bonus: residuals divisible by common item granularities
    // (10s and 25s) compose better with typical discrete item streams.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.5;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: reward residuals that exactly or nearly fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0; // perfect two-step chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: mild penalty scaled by waste.
            let gap = (next_item_size - post_residual) as f64;
            score += 1.5 * (gap / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // New-bin candidate: opening a fresh bin should only win when the current
    // fit is bad (large post_residual) or the stream is early and we can afford
    // to build a well-structured bin.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: its residual is full capacity.
        // Make it unattractive unless the item is large (good anchor).
        let anchor = item_size as f64 / cap;
        score -= 4.0 * anchor;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
        // Many open bins with high mean residual: don't add another bin.
        score += 0.15 * open_bins_count as f64;
        score += 0.02 * mean_residual;
    }

    // Mild pressure against proliferating bins when mean residual is already high.
    score += 0.01 * mean_residual * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: post_residual, with strong penalty for small unusable gaps.
    let mut score = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // dead space: gap too small for any plausible item (min size 1..100 unknown, but small gaps are waste)
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 - slack as f64 * 0.5;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; slight penalty for leaving a gap that strands it
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating many open bins, more so early in the stream.
    if is_new_bin {
        score = bin_capacity as f64 - 10.0 + open_bins_count as f64 * (2.0 + 3.0 * (1.0 - progress));
        // If no existing bin is a good fit (large post_residual elsewhere), allow new bin sometimes.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Prefer filling bins with larger residual when many bins are open (consolidation).
        score += (mean_residual - bin_residual as f64).abs() * 0.1;
        score += open_bins_count as f64 * 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match bonus: next item perfectly fills this bin.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.6;
        }
        // Penalize post_residual that is small but unusable by the next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Perfect fill is always excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Compare against mean residual: prefer bins whose post-residual stays near
    // the average (balanced packing), penalize extreme outliers.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when open bins fit well (small post_residual).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, modulated by stream phase.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 20.0 * (1.0 - progress);
        // If no open bins exist at all, opening is necessary.
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter fits overall (waste-relative penalty).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    }
    // Penalize if next item is slightly larger than post residual (near miss creates dead space).
    if next_item_size > post_residual && next_item_size - post_residual <= 15 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (0.5 + progress) * 3.0;

    // Compare residual to mean residual: prefer bins with below-average residual (fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual > 30 { 60.0 } else { 0.0 };
        score += 20.0 + bad_fit_penalty - progress * 10.0;
        if next_item_size > 0 && (bin_capacity - next_item_size) < item_size {
            score -= 10.0; // next item pairs well with a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with polynomial shaping
    let mut score = pr;

    // Smooth non-linear coupling: small residuals get extra reward,
    // large residuals get extra penalty, modulated by stream progress.
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += 30.0 * quad * (0.5 + progress) - 20.0 * cube * (1.0 - progress);

    // Dead-space penalty: residual too small to be useful for any future item
    let dead = (norm_pr - 0.1).max(0.0).min(1.0);
    score -= 15.0 * (1.0 - dead) * (1.0 - dead);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((post_residual as i64 - next_item_size as i64).abs() as f64 / cap);
        score -= 12.0 * fits_next * closeness;
    }

    // Mean residual deviation: prefer bins near the mean to keep flexibility
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Late stream: mild pressure to consolidate into fewer bins
    score += 5.0 * progress * (open_bins_count as f64).ln().max(0.0) * 0.1;

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * (open_bins_count as f64) - 0.2 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well the leftover space
    // decomposes into "friendly" chunk sizes (divisors of capacity).
    let pr = post_residual;
    let friendly = [1u32, 2, 4, 5, 10, 20, 25, 50];
    let mut harmony: f64 = 0.0;
    for &f in &friendly {
        if f <= pr {
            harmony += (pr / f) as f64 * (f as f64).ln();
        }
    }
    // Reward residuals that align with harmonic divisors (waste is reusable).
    score -= 0.35 * harmony / (1.0 + pr as f64 / cap);

    // Dead-space penalty: small, non-harmonic leftovers are useless.
    if pr > 0 && pr < 10 {
        score += 6.0 * (10 - pr) as f64;
    }

    // Exact fit is perfect.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: prefer leaving room that fits the next item exactly.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            score -= 4.0 / (1.0 + gap as f64);
        } else {
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Late-stream consolidation: tighter packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Large residuals remain reusable: reward proportionally.
        score -= 0.15 * post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual can still host a plausible next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Penalize wasting a large bin residual on a small item (poor match).
    let mismatch = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    if mismatch > 0.5 {
        score += 20.0 * mismatch;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when few bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative: new bin is fine
        }
    }

    // Mild alignment with mean residual: prefer bins below mean residual
    // (tighter bins) to preserve larger gaps elsewhere.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        // Aggressive 2-step lookahead: reward bins whose post-residual
        // exactly or nearly accommodates the next item.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;

        // Perfect match: post_residual == next_item_size -> strong reward.
        if post_residual == next_item_size {
            score -= 40.0 + 15.0 * progress;
        } else if post_residual >= next_item_size {
            // Next item fits: reward closeness of the match (tight packing chain).
            score -= 20.0 - 8.0 * (gap / bin_capacity as f64).min(1.0);
        } else {
            // Next item does NOT fit: penalize leftover dead space, worse when
            // the leftover is small-but-unusable (fragmentation).
            let frag = post_residual as f64 / bin_capacity as f64;
            score += 10.0 + 25.0 * (1.0 - frag);
        }

        // Coupling with mean residual: prefer bins that leave the fleet of
        // open bins with a healthy mean residual (space for future items).
        let post_f = post_residual as f64;
        if post_f > mean_residual {
            score -= 5.0 * (post_f - mean_residual).min(30.0) / 30.0;
        } else {
            score += 5.0 * (mean_residual - post_f).min(30.0) / 30.0;
        }
    } else {
        // Last item: just fill tightest bin.
        score -= 10.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to capacity or open bins are fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let pressure = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64).min(1.0)
        } else {
            1.0
        };
        // Attractive for big items / high fragmentation pressure,
        // unattractive when small items could fill existing space.
        score += 30.0 * (1.0 - large_item) - 30.0 * pressure * large_item;
        // Slightly discourage new bins early in the stream.
        score += 10.0 * (1.0 - progress);
    }

    // Mild bonus for keeping the number of open bins from exploding.
    if open_bins_count > 0 {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (<=10).
    if post_residual < 10 {
        score -= 25.0; // perfect fill bonus
    } else if post_residual < 20 {
        score += 8.0; // awkward dead zone
    } else if post_residual < 35 {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits via mild competition term
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowded = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.02 * crowded * (1.0 - progress);

    // Mean residual alignment: prefer bins whose residual is close to the item (efficient packing).
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * mean_gap;

    // New-bin candidate logic: empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over time (late streams waste more).
        let mut new_bin_cost = 18.0 + 10.0 * progress;
        // If next item is large and current item is small, reserving a fresh bin may help.
        if next_item_size > 60 && item_size < 40 {
            new_bin_cost -= 8.0;
        }
        // If many open bins already, opening more is costlier.
        new_bin_cost += 0.5 * open_bins_count as f64;
        score += new_bin_cost;
    } else {
        // Existing bin: reward using bins with larger residual when item is large.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * large_item * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_frac = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 40.0 * pr_frac * pr_frac * (0.5 + progress)
        - 25.0 * (1.0 - pr_frac) * (1.0 - pr_frac) * progress;

    // Reward tight fits (low post_residual) more strongly as stream progresses
    score -= 30.0 * (1.0 - pr_frac).powi(3) * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 20.0 + 30.0 * (1.0 - pr / nxt);
        } else {
            score -= 10.0 * (pr / (pr + nxt)).powi(2);
        }
    } else {
        score += 15.0 * pr_frac;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate: mildly penalize early, allow late when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).abs();
        score = cap + 60.0 * (1.0 - progress) - 40.0 * fragmentation * progress;
    }

    // Mild penalty for too many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: treat post_residual by capacity fractions (quarters).
    let q = post_residual * 4 / bin_capacity; // 0..4
    match q {
        0 => score -= 40.0,                 // near-perfect fill
        1 => score -= 12.0,                 // small dead space
        2 => score += 5.0,                  // half empty: awkward class
        _ => score += 10.0,                 // nearly empty bin wasted
    }

    // Modulo-10 harmonic class of post_residual: residuals divisible by 10
    // are "harmonic" with common item sizes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Odd residuals are harder to fill later.
    if post_residual % 2 == 1 {
        score += 3.0;
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt_post = post_residual - next_item_size;
        score -= 15.0 + (nxt_post as f64) * 0.3;
        if nxt_post % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here regardless; dead space penalty scales with gap
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins when many are open (bin count pressure).
    score -= open_bins_count as f64 * 0.5;

    // Progress-scaled tightness: late in stream, waste is costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Mean residual alignment: bins far below mean residual are good targets.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Integer-division threshold on item_size thirds.
    let t = item_size * 3 / bin_capacity;
    if t == 0 { score += 2.0; } else if t == 2 { score -= 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable item are pure waste; punish them hard.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Residual that cannot hold the lookahead item is semi-dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // the new-bin candidate (residual == capacity) gets penalized.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Slight preference for bins with below-average residual (fill emptier bins
    // less, keep tight bins tight is wrong direction -> prefer filling tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: place here if next item fits exactly in the gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item at least fits in the leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0 + next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportional to dead space created.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Penalize leaving residual far from mean residual (fragmentation signal).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        // But if next item is large and current fit is terrible, new bin is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 40.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        let too_small = (post_residual < 10) as i32 as f64;
        score += 8.0 * too_small * (1.0 - progress);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; slight penalty for wasting space now.
        score += 5.0;
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space usage).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // When many bins are open, encourage filling existing ones over new bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no tight option exists.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= 50 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: non-linearly shrink score as post_residual shrinks.
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small for the average useful item.
    let dead = (post_residual as i64 - next_item_size as i64).max(0) as f64;
    score += 0.05 * dead * dead / cap;

    // If the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        let fit_slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - fit_slack / cap);
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Stream progress coupling: later in the stream, prefer consolidating into few bins.
    let consolidation = (pr - mean_residual) / cap;
    score += 6.0 * progress * consolidation * consolidation;
    score -= 4.0 * (1.0 - progress) * (pr / cap);

    // New-bin candidate: penalize mildly so it's chosen only when it beats poor fits,
    // with the penalty easing as the stream progresses (fewer chances left to fill it).
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions (integer division).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=8 harmonic class
    let next_class = (next_item_size + eighth - 1) / eighth; // ceil class of lookahead

    // Reward when next item fits exactly into the post-residual class.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        // Perfect harmonic match: slack in lowest class => strong reward.
        if slack <= eighth {
            score -= 30.0;
        } else {
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Dead space: next item cannot use this bin's remainder.
        score += 8.0 + post_residual as f64 * 0.15;
    }

    // Modulo-style coupling between post class and next class.
    if next_item_size > 0 {
        let diff = (post_class as i32 - next_class as i32).abs();
        score += (diff as f64) * 2.5;
    }

    // Penalize residual in awkward harmonic band (just above half, unusable mid sizes).
    if post_residual > bin_capacity / 2 && post_residual < quarter * 3 {
        score += 6.0;
    }
    // Reward residuals in the small "fillable" band.
    if post_residual <= quarter {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 4 && mean_residual > 25.0 {
        score -= 3.0 + mean_residual * 0.05;
    }

    // Prefer tight fits generally: reward small post_residual non-linearly.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Early stream: be slightly greedy for tight packing; late stream: keep bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // New-bin candidate: penalize so it only wins when open bins are truly poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if item is large and nothing fits well elsewhere, opening is fine.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (post_residual 0 or exactly matching a plausible next item).
    if post_residual == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // gap still usable by the lookahead item
    } else if next_item_size > 0 {
        // gap unusable by next item: dead space risk
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin wastes the mean residual of open bins.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Only attractive if existing bins would leave bad dead space.
        score += 20.0 + 30.0 * pressure;
        if post_residual < 10 {
            score += 40.0; // a fresh bin leaving a tiny gap is terrible
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild progression term: early on, be slightly conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        // Exact match: next item fills this bin completely afterwards
        if (pr - nxt).abs() < 0.5 {
            score -= 150.0;
        } else if nxt <= pr {
            // Next item fits here: reward closeness of match
            let match_quality = 1.0 - (pr - nxt) / bin_capacity as f64;
            score -= 40.0 * match_quality;
            // Extra bonus if next item then leaves near-zero residual (two-step chain)
            let chain_residual = pr - nxt;
            if chain_residual <= 10.0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional dead space
            score += 0.5 * (pr - nxt).min(pr);
        }
    }

    // Tightness relative to bin capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Compare against mean residual: prefer bins that become below-average residual (tighter)
    let pr_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr_f - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent fits exist, unless residual would be tiny
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so existing bins are preferred
        score += 80.0;
        // But if no open bin fits well (large item), allow new bin: item_size large relative to capacity
        if (item_size as f64) > 0.6 * (bin_capacity as f64) {
            score -= 100.0;
        }
        // Late in the stream, avoid opening many bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 30.0 * progress * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Mild penalty for leaving residual in the awkward 1..10 dead zone
    if post_residual >= 1 && post_residual <= 10 && next_item_size > post_residual {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space after placement).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Penalize placing a small item into a bin with a large residual (waste of good space).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.25 * waste * (item_size as f64 / 100.0);

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_gap = post_residual - next_item_size;
        score -= 12.0 * (1.0 - pair_gap as f64 / bin_capacity as f64);
    }
    // If next item would NOT fit after placement, mild penalty unless post residual is tiny anyway.
    if next_item_size > post_residual && post_residual < 10 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins with below-average residual (more filled bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for keeping the number of open bins low early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless it's the only option or the fit is poor everywhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If no open bin fits well (this call context: few fitting bins), relax new-bin cost.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, opening a new bin is cheaper than fragmenting.
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (fraction of capacity left over)
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: waste grows super-linearly with leftover space
    let waste = pr_norm * pr_norm * (1.0 + 2.0 * pr_norm);
    score += 60.0 * waste;

    // Reward tight fits more strongly as the stream progresses (consolidation pressure)
    let tightness = 1.0 - pr_norm;
    score -= 40.0 * progress * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild preference for bins that are not the only option, to spread load
        score += 5.0 / fitting_bins_count as f64;
    }

    // Lookahead: if the post-residual exactly accommodates the next item, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score += 20.0 * slack * slack;
        }
    }

    // Penalize bins whose residual is far from the mean (keeps residuals balanced)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev;

    // Mild penalty for many open bins: encourage closing bins out
    score += 2.0 * open_bins_count as f64;

    // Smooth progress-coupled tilt: later in the stream, prefer reusing existing bins
    score -= 10.0 * progress;

    // New-bin candidate (empty bin): its post_residual is large, but add a small
    // opening cost so it only wins when fits in open bins are genuinely poor.
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best fit).
    if post_residual == 0 {
        score -= 1000.0; // perfect fill, overwhelming preference
    }

    // Harmonic class of post_residual: residual buckets by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals that are "dead zones": small but unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver = dead space
    }

    // Lookahead coupling: reward residuals that exactly or nearly fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0); // big reward when next item fits snugly
            // Modulo harmony: next item divides residual nicely
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // Residual cannot host next item: penalize proportionally to wasted potential
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.4 * bin_capacity as f64;
        if poor_fit {
            score -= 45.0; // open fresh bin rather than fragment
        } else {
            score += 20.0; // discourage opening bins when fit is decent
        }
        // Early in stream, slightly favor consolidation instead of opening.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from the mean in a useful (small) way.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Harmonic class penalty: residuals in awkward classes (mod 10 classes 1..9 small)
    let class = post_residual % 10;
    if class > 0 && post_residual < 50 {
        score += class as f64 * 0.4;
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot host the next item
    // (or any plausible item) are "dead space" -> strong penalty.
    let min_item = 1u32;
    if post_residual > 0 {
        if post_residual < next_item_size.max(min_item) {
            // Dead space relative to lookahead item
            score += 25.0 + 0.5 * (post_residual as f64);
        }
        if post_residual < 10 {
            // Unusable gap for typical distributions
            score += 30.0;
        }
    } else {
        // Perfect closure: excellent
        score -= 40.0;
    }

    // Reward tight fits (small post_residual overall)
    score -= 0.3 * (bin_capacity as f64 - post_residual as f64);

    // Lookahead harmony: post_residual exactly fits next item -> big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.2 * next_item_size as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is loose
    if bin_residual < bin_capacity {
        score += 0.15 * open_bins_count as f64;
    }

    // Mean-residual coupling: placing into a bin far from the mean residual
    // (creating outlier gaps) is penalized mildly
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate: opening a new bin is only attractive if no open bin
    // fits well; make the empty-bin default score moderately high so tight
    // fits in existing bins win, but allow it when fits are terrible.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.2 * open_bins_count as f64
            - if next_item_size > 0 && item_size >= next_item_size { 5.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / 100.0).max(0.0) * (1.0 - diff / 100.0);
    } else {
        // Last item: prefer tightest fit
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space that is too small to be useful for typical items (1..100 range)
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter; reward filling tight bins
    let rel = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * rel;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 45.0 + 0.05 * open_bins_count as f64;
    }

    // Mild pressure to consolidate as stream progresses
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly: prefer bins where post_residual is small.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 60.0;
    } else {
        // penalize large dead space, superlinear
        let dead = post_residual as f64;
        score += (dead * dead) / (bin_capacity as f64);
    }

    // Favor bins whose residual was already fragmented (waste little of a big hole)
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_cost = 120.0 + 40.0 * (open_bins_count as f64).ln();
        // If next item is large, a fresh bin is more valuable
        let lookahead_bonus = if next_item_size > item_size && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            30.0
        } else {
            0.0
        };
        score += open_cost - lookahead_bonus - 20.0 * progress;
        // If this bin is the only fitting option, soften the new-bin cost
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing existing space
    if mean_residual > 0.0 && !is_new_bin {
        score -= 15.0 * (mean_residual / bin_capacity as f64);
    }

    // Prefer bins whose post-residual still accommodates a typical future item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Slight time decay: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, scaled non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: post_residual polynomial interacting with progress
    score += 4.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Reward near-perfect fits (post_residual small) more strongly later in stream
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Dead-space penalty: residual too small to hold even the smallest item
    if pr > 0.0 && pr < 1.0 {
        score += 50.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 5.0 * (1.0 - slack * slack) * (1.0 + progress);
        } else {
            score += 1.5 * ((nx - pr) / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild pressure from many open bins with large mean residual: prefer filling existing bins
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 3.0;
        if post_residual as f64 / cap > 0.2 {
            score += 5.0 * (post_residual as f64 / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in residue classes of 10.
    let post_class = (post_residual / 10) as f64;
    score += post_class * post_class * 1.5;

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward if next item fits exactly into post residual (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Penalize leaving space that only a small item can use: wasted potential.
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.4;
        } else {
            // Next item cannot fit here: post residual is likely dead space.
            score += (post_residual as f64) * 0.6;
        }
    }

    // Integer-division threshold: bins whose residual is in the "awkward" 41..60 band
    // are less useful; penalize leaving them there, reward escaping that band.
    let awkward = post_residual >= 41 && post_residual <= 60;
    if awkward {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor or no good bins exist.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Empty bin starts with residual = capacity; base score high unless item is large.
        score = 95.0 - fit_quality * 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // new bin can also host next item
        }
    }

    // Slight pressure against bin sprawl late in the stream.
    score += (open_bins_count as f64) * 0.05 * (step_index as f64 / total_items.max(1) as f64);

    // Small tie-break toward bins with residual close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Heavy penalty on small unusable gaps (dead space): residuals 1..=10 are nearly worthless
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual but nonzero)
    if post_residual > 0 {
        score -= (bin_capacity as f64 - post_residual as f64) * 0.05;
    }

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits in the post residual, reward keeping that space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Slight preference for fuller bins relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * lookahead_gap;
        // Perfect two-item pairing bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item fits snugly after this placement
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 12.0; // next item won't reuse this bin's space
        }
    }

    // Penalize dead space relative to mean residual across open bins
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.35 * dead;
    } else {
        score += 0.15 * dead; // slight reward for tighter-than-average residual
    }

    // Prefer tight fits: small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discard opening a new bin when good open candidates exist
    if bin_residual == bin_capacity {
        score += 18.0 + 0.25 * item_size as f64;
        if fitting_bins_count > 0 && post_residual as f64 >= mean_residual {
            score += 10.0;
        }
    }

    // Early stream: be more selective about tight fits; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead bonus: if the next item can still fit in the post residual,
    // this placement preserves future usability -> reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 0.05 * next_item_size as f64;
    }
    // If next item almost fits (within 5), mild reward for near chaining.
    else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual + 5 {
        score -= 1.5;
    }

    // Dead-space penalty: very small post residual wastes capacity.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // (avoids opening a new bin).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.02 * tightness;

    // Global state coupling: if mean residual across open bins is high,
    // we should prefer filling existing bins rather than spreading.
    if !is_new_bin {
        score -= 0.03 * mean_residual;
    }

    // Time horizon: late in the stream, avoid opening new bins even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        // New-bin candidate: penalize, more so with many open bins and late stream.
        let mut new_penalty = 8.0 + 1.5 * open_bins_count as f64 + 10.0 * progress;
        // Exception: if the item is huge relative to capacity and no bin fits well,
        // opening a fresh bin is reasonable -> soften penalty.
        if item_size >= 70 && fitting_bins_count == 0 {
            new_penalty -= 15.0;
        }
        // If next item is large, a fresh bin can host the pair.
        if next_item_size > 0 && next_item_size <= post_residual && item_size + next_item_size <= bin_capacity {
            new_penalty -= 6.0;
        }
        score += new_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste (post_residual), softly normalized and non-linearly coupled with progress.
    let mut score = post / cap;

    // Non-linear polynomial coupling: waste penalty grows super-linearly as stream progresses.
    let waste_term = (post / cap).powi(2) * (0.5 + 1.5 * progress);
    score += waste_term;

    // Cubic interaction: late in the stream, near-full bins are heavily favored (low post residual).
    score += (post / cap).powi(3) * (1.0 + 3.0 * progress * progress);

    // Tight-fit reward: subtract when the item fills most of the bin (post residual small).
    let tightness = 1.0 - (post / cap);
    score -= 0.6 * tightness.powi(2) * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward if post residual can still fit the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 0.3 * (1.0 - slack).powi(2);
        } else {
            // Penalize leaving a residual that just barely fails to fit the next item.
            let gap = (nxt - post) / cap;
            score += 0.4 * gap * (1.0 - progress);
        }
    }

    // Mean residual coupling: penalize bins whose residual deviates far from the mean
    // (keeps residual distribution homogeneous, preserving combinability).
    let dev = (post - mean_residual) / cap;
    score += 0.2 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 0.8 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild competition pressure: prefer tighter fits.
        score += 0.05 * (fitting_bins_count as f64).ln() * (post / cap);
    }

    // New-bin candidate handling: an empty bin has post_residual == cap - item_size.
    // Penalize opening a new bin unless the item is large relative to capacity
    // (i.e., the resulting residual is small), making fresh bins attractive only for big items.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 0.5 * (1.0 - fill).powi(2) * (1.0 + progress);
        // Mild penalty scaling with number of already open bins to avoid bin proliferation.
        score += 0.02 * open_bins_count as f64 * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space buckets
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual in small harmonic class)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else {
        // dead-space penalty grows quadratically as residual shrinks into "waste" class
        let frac = pr / cap;
        score += (frac * frac) * 40.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair better with typical sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer-division thresholds: post_residual class via (post_residual / 10)
    let pr_class = post_residual / 10;
    score += (pr_class as f64) * 2.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let mut base = 60.0;
        if fitting_bins_count == 0 {
            base -= 200.0; // must open a bin
        } else if fitting_bins_count == 1 {
            base -= 20.0; // weak alternative exists
        }
        // perfect-fit lookahead: if next item is huge, fresh bin is valuable
        if next_item_size >= 70 {
            base -= 30.0;
        }
        score += base;
    }

    // Lookahead coupling: if next item exactly fills post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward proportional to how snugly
        score -= 20.0 * (next_item_size as f64 / cap);
        // harmonic class match: post_residual - next_item divisible by 10
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here: penalize leaving a large unusable-ish residual
        score += 10.0 * (pr / cap);
    }

    // Stream progression: late in stream, prefer tight packing / consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - pr / cap);

    // Mean residual coupling: penalize bins far below mean residual (fragmented bin)
    score += ((mean_residual - pr).abs()) * 0.3;

    // Many open bins: discourage spreading, reward filling existing bins
    if open_bins_count > 3 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small for the next item (or the
    // smallest plausible item) are effectively wasted capacity.
    let min_future = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual < min_future {
        score += 40.0 + (min_future - post_residual) as f64;
    }

    // Tight fit reward: quadratic bonus for small post_residual.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 25.0 * (1.0 - tightness);

    // Perfect-fit style bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == min_future && next_item_size > 0 {
        score -= 35.0; // leaves exactly the next item's size
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual) or many bins are already open (pressure).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - poor_fit);
        score += 4.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the next item would fit in the fresh bin's residual anyway,
        // opening is slightly more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for bins whose residual is far from the mean (keeps
    // residuals uniform so future items pack predictably).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for more-filled bins.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match bonus: next item exactly fills this bin after placement.
        if post_residual == next_item_size {
            score -= 60.0 + item_size as f64;
        } else {
            // Penalize proportional to mismatch, stronger when post_residual < next_item_size
            // (next item can't use this bin, dead space locked in).
            if (post_residual as u32) < next_item_size {
                score += diff * 1.5;
            } else {
                score += diff * 0.6;
            }
        }
        // Extra reward if after two placements bin is (nearly) full.
        let two_step = post_residual as i64 - next_item_size as i64;
        if two_step >= 0 && two_step <= 5 {
            score -= 40.0;
        }
    }

    // Relative-to-mean term: prefer bins whose residual deviates favorably from the mean.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist (new-bin candidate detection).
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        // But allow new bin early in stream or when open bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 0 && mean_residual < item_size as f64 * 0.8 {
            score -= 20.0;
        }
        if progress < 0.1 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter fits overall.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect pairing strongly rewarded; decays with leftover slack.
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot use the leftover: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Penalize wasting a scarce fitting bin on a loose fit.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 0.5 * (post_residual as f64);
    }

    // Fragmentation pressure: if mean residual is small, prefer reusing bins
    // (opening a new bin is expensive when open bins are nearly full).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        // Existing bin: reward reuse more as stream progresses.
        score -= 10.0 + 15.0 * progress;
        // Extra reward when this bin's residual is below average (denser bin).
        let diff = mean_residual - bin_residual as f64;
        score += 0.2 * diff;
    } else {
        // New-bin candidate: penalize unless open bins are very full on average
        // or many bins are already open (consolidation).
        let avg_fullness = 1.0 - mean_residual / (bin_capacity as f64);
        let pressure = avg_fullness * avg_fullness;
        score += 20.0 * (1.0 - pressure) + 2.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, opening new bins is cheaper than fragmenting.
        score -= 8.0 * progress;
    }

    // Perfect fill: overwhelming reward for exact closure.
    if post_residual == 0 {
        score -= 1000.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fit (small post_residual), with convex penalty on waste
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth interaction: waste matters more as stream progresses
    score += 25.0 * norm_post * norm_post * progress;

    // Mean-residual coupling: penalize bins far from the fleet mean waste (encourages uniformity)
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 12.0 * scarcity * (1.0 - norm_post);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (post - ns).abs();
        score += 0.15 * gap;
        if post >= ns {
            score -= 8.0 * (1.0 - gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: smooth discouragement unless current bin would be badly wasted
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress - 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality by residue classes mod 10.
    let pr = post_residual;
    let dead = match pr {
        0 => -40.0,                     // perfect fit
        1..=5 => -10.0 + pr as f64,     // near-perfect: small residue is fine
        6..=10 => 5.0 + pr as f64,      // awkward small gap
        _ => {
            // Larger gaps: classify by divisibility (harmonic classes)
            if pr % 10 == 0 {
                (pr as f64) * 0.9       // round gaps pair well with common sizes
            } else if pr % 5 == 0 {
                (pr as f64) * 1.0
            } else if pr % 2 == 0 {
                (pr as f64) * 1.05
            } else {
                (pr as f64) * 1.15      // odd prime-ish gaps are worst
            }
        }
    };
    score += dead;

    // Integer-division thresholds on post_residual: can it host a future item?
    let t = step_index as f64 / (total_items.max(1) as f64);
    if pr >= 80 { score -= 6.0; }        // huge gap still very reusable
    else if pr >= 50 { score -= 2.0; }
    else if pr >= 30 { score += 3.0; }
    else if pr > 0 { score += 8.0; }     // tiny dead space

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // harmonic match: next item size divides post_residual nicely
            if pr % next_item_size == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize leaving a gap just below it
            if pr >= next_item_size.saturating_sub(10) && pr < next_item_size {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when no open bin is good.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (1.0 - t); // early stream: slightly prefer new bins
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Mean residual drift: prefer bins close to mean (balance), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1)
    // but practically, gaps below ~10 waste the bin. Penalize sub-10 gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling: post_residual that cannot fit the lookahead item is dead space
    // unless the next item could be placed elsewhere; penalize moderately.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also serve the lookahead item (chain fits).
        score -= 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current item
    // is large and open bins would suffer heavy dead space.
    if bin_residual == bin_capacity {
        let waste_if_forced = mean_residual - item_size as f64;
        let mut new_bin_score = 18.0 + open_bins_count as f64 * 0.1;
        if waste_if_forced < 0.0 {
            new_bin_score -= waste_if_forced * 0.5;
        }
        if next_item_size > 0 && item_size >= next_item_size {
            new_bin_score += 3.0;
        }
        score = new_bin_score;
    } else {
        // Mild reward for tight fits relative to mean residual.
        let tightness = (bin_residual - item_size) as f64;
        if tightness < mean_residual * 0.5 {
            score -= 2.0;
        }
    }

    // Late-stream urgency: as the stream ends, prioritize closing bins cleanly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 && post_residual == 0 {
            score -= 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near-match bonus: how close post_residual is to next_item_size (relative).
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score += diff * 0.6;
        // If next item fits in the post residual, reward proportionally.
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space relative to lookahead: penalize wasted gap.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins with residuals far below the mean (already fragmented),
    // reward bins that are tighter than average.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Encourage tight packing: small post_residual is good (already base score),
    // extra reward for very tight fits.
    if post_residual < 10 {
        score -= 10.0;
    }

    // New-bin candidate: default attractiveness; make it less attractive when
    // decent fitting bins exist, more attractive when this item would leave
    // a large unusable gap in any existing bin.
    if bin_residual == bin_capacity {
        let gap_penalty = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).max(0.0)
        } else {
            0.0
        };
        // New bin baseline: slightly worse than a good fit, better than bad fits.
        score = 25.0 + 0.2 * gap_penalty
            + 0.5 * (open_bins_count as f64).ln().max(0.0)
            - 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score -= 40.0 * (1.0 - tight).powi(6);
    }

    // Penalize dead space that no future item (sizes 1..=100) could ever fill poorly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.2 * (next_item_size as f64);
        } else {
            // Penalize leaving a gap just larger than the next item.
            let gap = post_residual as f64 - (next_item_size as f64);
            if gap < 0.0 && gap > -20.0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when current
    // bins are crowded or the fit here would be terrible.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = (open_bins_count as f64) / 20.0;
        let mean_tight = 1.0 - (mean_residual / (bin_capacity as f64));
        // Prefer new bin when existing bins are quite full or many are open.
        let bonus = 30.0 * mean_tight + 10.0 * crowd + 20.0 * progress;
        // But penalize if this bin would fit the item well (waste of a fresh bin).
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        score += 50.0 - bonus - 40.0 * fit_quality;
    }

    // Mild global regularization: prefer bins whose residual is below the mean
    // (fill the emptier-feeling bins less when they are above-average full).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Slight preference for using more open bins early, consolidating late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += poly * cap * 0.5;

    // Reward tight fits, more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + progress) * 6.0;

    // Penalize dead space relative to mean residual
    score += (pr - mean_residual).abs() * 0.3;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= ((pr - ni) / cap) * 10.0;
        } else {
            score += ((ni - pr) / cap) * 12.0;
        }
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // accept them late when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small,
    // "dead" classes (residual < 10) are perfectly packed -> strong reward.
    if post_residual == 0 {
        score -= 100.0; // exact fill: ideal
    } else if post_residual < 10 {
        score -= 60.0; // unusable dead space eliminated
    }

    // Modulo-class coupling: post_residual divisible by small harmonics is
    // more likely to be reusable by future items (sizes 1..100).
    let pr = post_residual as u64;
    let mut harmonic_bonus = 0.0;
    for m in [2u64, 4, 5, 8, 10, 20, 25, 50].iter() {
        if pr % m == 0 && pr > 0 {
            harmonic_bonus += 6.0;
        }
    }
    // Harmonic match with lookahead item: residual that divides evenly
    // against next_item_size predicts a future perfect fit.
    if next_item_size > 0 && pr >= next_item_size as u64 {
        if pr % next_item_size as u64 == 0 {
            harmonic_bonus += 25.0;
        } else if (pr - next_item_size as u64) < 10 {
            harmonic_bonus += 18.0; // next item nearly fills this bin
        }
    } else if next_item_size > 0 && next_item_size as u64 > pr {
        // residual too small for next item: penalize mildly unless dead space
        harmonic_bonus -= 8.0;
    }
    score -= harmonic_bonus;

    // Integer-division threshold on bin_residual: bins in the "large residual"
    // class (more than half capacity) are flexible; small-residual bins should
    // be drained first to close them out.
    if bin_residual <= bin_capacity / 4 {
        score -= 20.0; // drain nearly-full bins
    } else if bin_residual > bin_capacity / 2 {
        score += 10.0; // prefer not to fragment large bins with bad fits
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer
    // it when no open bin fits well (high mean residual fragmentation) or the
    // stream is early and building a diverse pool helps.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Opening new bins early is cheap; late in the stream it is wasteful.
        let openness = (1.0 - progress) * 40.0 - open_bins_count as f64 * 4.0;
        score += 55.0 - openness.max(0.0) - fragmentation.max(0.5) * 20.0;
    }

    // Mild penalty for wasting space relative to mean residual: bins far above
    // mean are precious, avoid dumping big items there.
    if (bin_residual as f64) > mean_residual + 25.0 && item_size > 40 {
        score += 12.0;
    }

    // Tightness reward: the closer the fit, the better (relative waste term).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to ever hold the smallest
    // item (1..=min_item) are pure waste. Penalize proportionally to how
    // close the gap is to being "just barely unusable".
    let min_item = 1u32;
    if post_residual < min_item {
        // exact fit: perfect, heavily reward
        score -= 40.0;
    } else {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // tiny sliver: nearly dead space, strong penalty
            score += (10.0 - gap) * 3.0;
        } else if gap < 30.0 {
            // awkward mid gap: moderate penalty scaled by mean residual context
            score += (30.0 - gap) * 0.8;
        } else {
            // large gap still usable: mild reward to prefer big leftovers
            score -= (gap - 30.0) * 0.15;
        }
    }

    // Tight-fit reward: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // a new bin is recognizable by bin_residual == bin_capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // base cost of opening a bin, grows with open count and progress
        score += 20.0 + open_bins_count as f64 * 2.5 + progress * 15.0;
        // but if the item is huge and no tight fit exists elsewhere, a fresh
        // bin guarantees a clean placement: soften cost for large items.
        score -= fill_ratio * 10.0;
    } else {
        // reusing an existing bin is good: reward modestly, more when many
        // bins are already open
        score -= (open_bins_count as f64).sqrt() * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            let next_gap = post_residual - next_item_size;
            if next_gap < 10 {
                // would leave next placement nearly dead: penalize
                score += (10 - next_gap) as f64 * 1.5;
            }
        }
        // if next item is large, keep residual roomy bins attractive
        if next_item_size >= 50 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is below average (consolidate waste in
    // already-partial bins, keep roomy bins for future big items).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit bonus: reward placements leaving zero or tiny residual.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, strongly reward this placement (chained fit).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize wasting residual that
            // is "almost" large enough for the next item (dead space).
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 45.0 * (1.0 - miss / 20.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // are quite full (residual close to capacity and few bins open).
    if bin_residual == bin_capacity {
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 120.0 - 100.0 * fullness;
    }

    // Prefer bins tighter than the mean residual (good fits first).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Late in the stream, be more conservative: favor closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }
    // Penalize dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: avoid wasting the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Tight-fit reward: quadratic reward for small post-residual.
    score -= 0.05 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 30.0;

    // Time horizon: later in the stream, prefer tighter packing / avoid new bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * t;

    // Mean residual coupling: penalize bins far below mean residual (fragmenting).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate handling: make empty bins attractive only when current
    // bin fits are poor (large post-residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let pressure = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score = 40.0 * pressure + 30.0 * poor_fit - 10.0 * t;
        if next_item_size > 0 && bin_capacity >= next_item_size + item_size {
            score -= 8.0; // fresh bin leaves room for lookahead
        }
    }

    // Mild penalty for bin proliferation late in stream.
    score += 0.3 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (small post_residual), with smooth quadratic shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // residual waste is penalized more heavily as the stream progresses.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += coupling;

    // Smooth progress-weighted penalty for large leftover relative to mean residual
    score += 0.3 * progress * (pr - mean_residual).abs();

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (1.0 - progress) * (nxt / cap) * 10.0;
        } else {
            // penalize residuals that strand the next item
            score += (1.0 - pr / nxt.max(1.0)) * 5.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the gap left behind: small gaps are dead space, large gaps reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement (harmonic fraction classes).
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;

    // Class A: gap falls in "unusable" band (< 10% of capacity) -> heavy penalty
    if post_residual < bin_capacity / 10 {
        score += 40.0;
    }
    // Class B: gap in mid band (10%..30%) -> moderate penalty, worse for small next items
    else if post_residual < bin_capacity * 3 / 10 {
        score += 12.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // next item can still use this class of gap
        }
    }
    // Class C: large gap -> mild reward, it stays flexible
    else {
        score -= 5.0;
    }

    // Integer-division harmonic classes on post_residual (mod 10 buckets).
    let gap_class = post_residual / 10;
    score -= (gap_class as f64) * 1.5;

    // Perfect-ish fits: reward tight packing.
    if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 8 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 10.0 - (leftover as f64) * 0.3;
        } else {
            // next item cannot use this bin's gap; penalize proportional to wasted potential
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual < bin_capacity / 10 && next_item_size > post_residual && next_item_size > 0 {
            score += 25.0; // dead space and next item can't follow -> prefer new bin
        }
    }

    // New-bin candidate logic: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Early in stream: opening bins is cheap, keep flexibility.
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score = cap - item_size as f64; // baseline: how much of new bin gets used now
        score -= fill_frac * 0.0;
        if progress < 0.3 {
            score -= 8.0;
        } else if progress > 0.8 {
            score += 6.0; // late stream: consolidate into open bins
        }
        // If many open bins with fat residuals, prefer reusing them over a new bin.
        if mean_residual > cap * 0.4 && open_bins_count > 2 {
            score += 10.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size > cap / 2 {
            score -= 6.0;
        }
    } else {
        // Reward filling bins that are already more than half full (harmonic half-class).
        if fill_frac >= 0.5 {
            score -= 8.0 * fill_frac;
        }
        // Spread penalty when too many bins are open with thin residuals.
        if open_bins_count > 6 && mean_residual < cap * 0.2 {
            score += 5.0;
        }
    }

    // Modulo-class coupling between item and gap (harmonic residue alignment).
    if post_residual > 0 && item_size % 10 == post_residual % 10 && post_residual >= item_size {
        score -= 3.0; // aligned residue classes tend to chain well
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is small relative to the plausible item range (1..100).
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny sliver: almost certainly unusable dead space.
            score += 60.0;
        } else if post_residual <= 25 {
            // Small gap: risky, only partially usable.
            score += 20.0 + (25 - post_residual) as f64 * 1.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits generally: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 40.0; // next item closes this bin nearly perfectly
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: slight penalty for stranding capacity.
        score += 8.0;
    }

    // Open-bins pressure: discourage spreading across many bins early,
    // but relax pressure as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (1.0 - 0.5 * progress) * 3.0;
    score += open_bins_count as f64 * pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless the
    // current item is large and would leave a clean, useful residual.
    if bin_residual == bin_capacity {
        let base_cost = 90.0 + 2.0 * open_bins_count as f64;
        // Large items leave little dead space; slightly cheaper to open for them.
        let large_item_discount = if item_size >= 70 { 30.0 } else if item_size >= 50 { 10.0 } else { 0.0 };
        score += base_cost - large_item_discount;
        // If no open bin fits, opening is unavoidable: soften the cost.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild alignment with mean residual: prefer bins that deviate less from
    // the fleet average (keeps residual distribution homogeneous).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward an exact match with the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => big bonus (subtract a lot); near match => graded bonus.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 25.0 / (1.0 + diff / 10.0);
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            score += 5.0 + diff / 8.0;
        }
        // If next item cannot even fit an empty bin, lookahead is useless; dampen.
        if next_item_size >= bin_capacity {
            score += 10.0;
        }
    } else {
        // Last item: just minimize leftover, slightly reward tight fit.
        score -= 5.0 / (1.0 + post_residual as f64);
    }

    // Penalize post_residual that is small and unusable (dead space) relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr); // tighter than average: good
    } else {
        score += 0.3 * (pr - mean_residual); // looser than average: bad
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; reduced when few bins open or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 12.0;
        if open_bins_count <= 1 {
            new_bin_cost -= 6.0;
        }
        if progress < 0.2 {
            new_bin_cost -= 3.0;
        }
        // If lookahead item could perfectly fill this fresh bin later, soften cost.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            new_bin_cost -= 4.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: post residuals too small to ever be useful (< 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: penalize if the next item cannot fit in post_residual.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 4.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room for the next item, more if it's a snug fit.
            let gap = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding: when many bins are open, prefer filling existing ones;
    // when few are open, opening new bins is cheaper.
    let crowding = (open_bins_count as f64) / (1.0 + (step_index as f64).max(1.0) / (total_items.max(1) as f64).max(1.0));
    score += 0.35 * crowding * (post_residual as f64) / (bin_capacity as f64);

    // Global mean residual coupling: if this bin is far below mean residual
    // (it is emptier), slightly penalize; prefer bins closer to being full.
    score += 0.5 * ((mean_residual - bin_residual as f64).abs() / (bin_capacity as f64));

    // New-bin candidate: base penalty so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // But if item is huge and mean residual is low, new bin is attractive.
        if item_size as f64 > mean_residual + 15.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, scaled by stream progress
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * 100.0;

    // Smooth interaction: reward tight fits more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 + progress) * 10.0;

    // Penalize residuals that are too small to ever fit typical items (dead space)
    let dead = ((10.0 - pr).max(0.0)) / 10.0; // 1.0 if residual < min item size
    score += dead * dead * 50.0 * (1.0 + progress);

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins
    let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).max(0.0));
    score -= scarcity * 15.0 * (1.0 - norm_pr);

    // Lookahead coupling: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        let kernel = (-gap * gap / (2.0 * 100.0)).exp();
        score -= kernel * 12.0;
    } else {
        // Last item: strongly prefer filling existing bins
        score += 25.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: make it attractive only when current bins have poor fit
    if bin_residual == bin_capacity {
        // Slight penalty so new bins are opened only when genuinely better
        score += 5.0 + 20.0 * progress;
        // But if the item is large relative to capacity, opening fresh is fine
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild dispersion penalty: bins far from mean residual create fragmentation
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" residue classes modulo common item sizes are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are multiples of common item sizes (10, 20, 25, 50)
        if pr % 50 == 0 {
            score -= 12.0;
        } else if pr % 25 == 0 {
            score -= 8.0;
        } else if pr % 10 == 0 {
            score -= 5.0;
        }
        // Penalize "dead space" residues: tiny leftovers that few items can use
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
    } else {
        // Perfect fill is ideal
        score -= 30.0;
    }

    // Lookahead coupling: does the residual class match the next item's class?
    if next_item_size > 0 && pr >= next_item_size {
        // Next item fits exactly or with a harmonic remainder
        let rem = pr - next_item_size;
        if rem % 10 == 0 {
            score -= 10.0;
        } else if rem < 10 {
            score += 6.0; // leaves dead space for the item after next
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && pr < next_item_size {
        // This bin becomes useless for the next item; penalize proportionally
        score += (next_item_size - pr) as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals
    // are badly fragmented relative to the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 20.0;
        // If open bins have plenty of average room and this item is small,
        // prefer reusing them (raise new-bin score).
        if open_bins_count > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            let reuse_pressure = (mean_residual - item_size as f64).max(0.0);
            score += reuse_pressure * 0.3;
            // Late in the stream, be more conservative about new bins
            score += progress * 5.0;
        }
        // Large items with no good fit elsewhere justify a fresh bin
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Slight preference for fuller bins overall (tightness coupling)
    let fill_fraction = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_fraction * 8.0;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (12.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit: big reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits (small but usable leftovers less harshly).
        score -= (bin_capacity as f64 - post_residual as f64) * 0.15;
    }

    // Coupling with lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // next item can't use this bin: penalize large wasted residuals relative to next item
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.3;
        }
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when it avoids dead space or no good fit exists.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.3;
        if item_size >= 60 {
            score -= 15.0; // large items fine in fresh bins
        }
    }

    // Mild drift with stream progression: tighten up as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted gap
            score += 50.0 + 0.5 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual: avoid fragmenting average
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to residual
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0; // fresh bin can absorb the pair
        }
    }

    // Late in the stream: prefer tight packing of open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 40.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 2.0 * tightness * tightness * (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: penalize opening a new bin, but less
    // if existing residuals are small relative to the item
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let base_penalty = 18.0;
        let scarcity = (item_size as f64) / (bin_residual as f64);
        // If mean residual across open bins is low, new bin is more acceptable
        let mean_rel = mean_residual / (bin_capacity as f64);
        score += base_penalty - 10.0 * (1.0 - mean_rel) * scarcity;
    } else {
        // Using an existing bin is generally good
        score -= 4.0;
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            let chain_fit = (next_item_size as f64) / (post_residual as f64);
            score -= 8.0 * chain_fit;
        } else if (post_residual as i64) + (next_item_size as i64) <= (bin_capacity as i64)
            && post_residual < next_item_size {
            // dead space that could combine with next item elsewhere: mild penalty
            score += 2.0;
        }
        // If post residual is too small for next item but > 0, penalize stranded slivers
        if post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
            score += 3.0;
        }
    }

    // Time horizon: early in stream, be more conservative with new bins
    // (plenty of future items to fill them); late in stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= 6.0 * (1.0 - progress); // cheaper to open bins early
    } else {
        score -= 3.0 * progress; // pack tightly as stream ends
    }

    // Many open bins: encourage closing them out by filling
    if open_bins_count > 4 {
        if !is_new_bin {
            score -= 1.0 * ((open_bins_count as f64).ln());
        }
    }

    // Prefer bins whose residual deviates from mean when it means better utilization
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on wasted residual (dead space), smoothed
    let mut score = 8.0 * norm_pr * norm_pr + pr;

    // Non-linear coupling of residual with stream progress:
    // early on, tolerate leftover space; later, penalize it harder
    score += 30.0 * norm_pr * (0.5 + progress).powi(2) * (1.0 - progress * 0.5);

    // Cubic interaction: small residuals late in stream are very costly
    score -= 12.0 * (1.0 - norm_pr).powi(3) * progress;

    // Reward tight fits (post residual near zero) especially with lookahead
    if next_item_size > 0 {
        let nl = next_item_size as f64;
        let gap = (pr - nl).abs() / cap;
        score -= 20.0 * (-6.0 * gap).exp();
        // penalize residual that can't fit the next item (dead space for lookahead)
        score += 10.0 * (pr < nl) as i32 as f64 * norm_pr * (1.0 + progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: prefer bins deviating from mean to balance load
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev * progress;

    // Mild penalty for spreading across many bins early
    score += 1.5 * (open_bins_count as f64) * (1.0 - progress) * norm_item;

    // New-bin candidate: neutral-ish baseline with progress-dependent cost
    if bin_residual == bin_capacity {
        score = 55.0 + 40.0 * progress - 15.0 * norm_item;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // capacity-fraction buckets (0-24: tiny, 25-49: quarter, 50-74: half, 75-99: large).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let residual_class = match post_residual {
        0 => 0u32,
        r if r < quarter => 1,
        r if r < half => 2,
        r if r < 3 * quarter => 3,
        _ => 4,
    };

    // Reward exact fits and near-exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual < quarter {
        score -= 30.0;
    }

    // Penalize residuals in the "awkward" class: too small for the minimum
    // item (1..=100 range means < 10 is dead), too large to feel tight.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 150.0; // unusable dead space
    }

    // Harmonic coupling: modulo structure of residual vs item size.
    // If post_residual is an exact multiple of a plausible next-item size
    // class, reward it (the leftover is reusable).
    let gcd_like = |a: u32, b: u32| -> u32 {
        let (mut x, mut y) = (a, b);
        while y > 0 { let t = x % y; x = y; y = t; }
        x
    };
    if next_item_size > 0 && post_residual >= next_item_size {
        let g = gcd_like(post_residual, next_item_size);
        if g > 1 {
            score -= (g as f64) * 2.0; // divisible leftovers are reusable
        }
        // exact modular fit: next item divides post_residual cleanly
        if post_residual % next_item_size == 0 {
            score -= 40.0;
        } else if post_residual % next_item_size <= 5 {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin gives a
        // tight fit, i.e. when the best post-residual we'd otherwise get
        // is large. Penalize opening new bins mildly but increasingly
        // with how many bins are already open.
        score += 60.0 + (open_bins_count as f64).sqrt() * 10.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 70.0;
        }
    }

    // Tightness reward scaled by capacity fraction: prefer filling bins
    // to harmonically nice levels (half, three-quarters, full).
    let fill_level = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let harmonic_bonus = match (fill_level * 4.0).round() as i32 {
        4 => 60.0,
        3 => 35.0,
        2 => 20.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Late in the stream, consolidate: fewer open bins is better.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (open_bins_count as f64) * 3.0;

    // Prefer bins whose residual deviates favorably from the mean:
    // below-mean residual bins are the "tight" ones; use them first.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.5;

    // Small overall preference for tighter post-fit residual (quadratic).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any future item (min size 1..100 unknown,
    // but typical small items ~10) are wasted. Penalize unusable gaps quadratically.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Gap must fit the lookahead item: otherwise this bin wastes space next_item_size could use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving a usable gap for the next item.
            score -= (next_item_size as f64).min(post_residual as f64) * 0.5;
        } else {
            // Penalize creating a gap that can't fit the lookahead item.
            score += 12.0;
        }
    }

    // Tight fit reward: fraction of bin filled by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; favor closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // New-bin candidate handling: empty bin gets baseline cost, only attractive
    // when current fit is poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 2.0 - fill_ratio * 10.0;
        // If this bin would be the only fitting bin and fit is decent, opening is bad.
        if fitting_bins_count == 1 && post_residual < dead_threshold + item_size / 2 {
            score += 25.0;
        }
        return score;
    }

    // Deviation from mean residual: prefer bins below mean (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but heavily penalize dead space below next item size
    // (space that the lookahead item cannot use).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose leftover can host the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * slack;
        } else {
            // Leftover is unusable for next item: penalize proportionally.
            let dead = next_item_size as f64 - post_residual as f64;
            score += 6.0 + 0.4 * dead;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Compare residual against mean residual: prefer using bins with above-average
    // residual (large leftovers) to keep tight bins flexible.
    let res = post_residual as f64;
    if res > mean_residual {
        score -= 0.1 * (res - mean_residual);
    } else {
        score += 0.15 * (mean_residual - res);
    }

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item is
    // large relative to capacity or fits are poor elsewhere.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline for a fresh bin.
        score = bin_capacity as f64 - item_size as f64 + 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if item_size >= 70 {
            score -= 10.0; // large items are fine to start fresh
        }
        if fitting_bins_count == 1 {
            score += 15.0; // don't open new bin when an existing one is last chance
        }
    }

    // Slight late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize unusable dead space: residual too small for the smallest plausible item.
        let dead_threshold = 10.0f64.min(cap * 0.1);
        if (post_residual as f64) < dead_threshold {
            score += 25.0;
        }
    }

    // Tightness: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / cap;
    score -= 30.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next == 0 {
                score -= 40.0;
            } else {
                // mild reward proportional to how well next item uses leftover
                score -= 12.0 * (next_item_size as f64 / post_residual as f64);
                if leftover_after_next < 10 {
                    score += 15.0; // would strand a tiny remainder
                }
            }
        } else if next_item_size > post_residual {
            // next item won't fit here; leaving a very small residual is bad
            if post_residual < next_item_size && post_residual < 15 {
                score += 10.0;
            }
        }
    } else {
        // Last item in stream: prioritize closing bins tightly.
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins with high mean residual: encourage consolidation into emptier bins.
    let res_gap = (bin_residual as f64) - mean_residual;
    score += 0.15 * res_gap;

    // Time horizon: late in the stream, avoid opening new bins; early, allow spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; small early bonus
        score += 45.0 * (0.3 + 0.7 * progress);
        if open_bins_count == 0 {
            score -= 100.0; // must have a bin
        }
        // Don't open a new bin if an open bin fits nearly perfectly
        if fitting_bins_count > 0 && (bin_residual - item_size) as f64 / cap <= 0.1 {
            score += 30.0;
        }
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 10.0 * progress;
    }

    // Slight penalty for spreading across too many bins when few items remain.
    let items_left = total_items.saturating_sub(step_index) as f64;
    if open_bins_count as f64 > items_left * 1.5 && items_left > 0.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Prefer tight fits: penalize normalized waste non-linearly.
    let waste_frac = post / cap;
    score += 40.0 * waste_frac * waste_frac * (1.0 + progress);

    // Reward bins whose residual is close to item size (perfect fill).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Lookahead: bonus if the next item fits into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if next_item_size as u32 <= post_residual {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Stream-progress coupling: late in stream, consolidate more aggressively.
    score -= 8.0 * progress * (1.0 - post / cap);

    // Slight penalty when bin residual deviates from mean residual (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = cap - post + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of small divisors
    // are more reusable. Reward post_residual divisible by common item granules.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // Dead space penalty: tiny unusable residues (harmonic dead zone)
        if pr < 10 { score += 30.0 + (10 - pr) as f64 * 4.0; }
    } else {
        // Perfect fit: strongly reward closing a bin exactly
        score -= 60.0;
    }

    // Tight fit reward: fraction of capacity consumed by this item
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fit is bad
    if bin_residual == bin_capacity {
        score += 35.0 + 0.15 * open_bins_count as f64;
        // But if no open bin fits well, new bin is fine
        if fitting_bins_count == 0 { score -= 45.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement is part of a perfect chain.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 25.0; }
        else if next_item_size < pr && pr - next_item_size <= 10 { score -= 10.0; }
        else if next_item_size > pr && next_item_size <= bin_residual { score += 5.0; }
    }

    // Prefer filling bins whose residual is below the mean (consolidate waste)
    let mr = mean_residual;
    if (bin_residual as f64) < mr { score -= 6.0; } else { score += 3.0; }

    // Early stream: be a bit more willing to open bins (spread risk)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // Integer-division threshold on post_residual: mid-range residues (30..60)
    // are the most flexible for future items
    if (30..=60).contains(&pr) { score -= 8.0; }
    if (61..=80).contains(&pr) { score += 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (<= 10 units) are pure waste. Penalize hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small leftover gaps are only usable by tiny items; dampen the
        // apparent desirability of a "tight" fit that strands space.
        score += 12.0;
    }

    // Reward near-perfect fits (very low post residual relative to item).
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as f64) < 0.15 * item_size as f64 {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the item (relative fit quality).
    score += 0.35 * ((bin_residual as f64 - item_size as f64).abs());

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.05 + 0.10 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty proportional to open-bin pressure,
        // relaxed when this is the only fitting option elsewhere.
        score += 55.0 + pressure * 8.0;
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild reward for consolidating, stronger when many bins open.
        score -= pressure;
        if fitting_bins_count == 1 {
            // Last-chance bin: strongly prefer using it over opening a new bin.
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits into the resulting residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item won't fit here; if residual becomes dead space, penalize mildly.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Slight preference for bins below the mean residual (fill the emptiest
    // usable bins first, keeping tight bins for tight items).
    score += 0.10 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 12 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 5 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space proportionally.
        score += 8.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize new-bin opening unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 {
            score -= 5.0; // open bins too full; new bin is fine
        } else {
            score += 25.0; // keep using open bins
        }
    }

    // Late in the stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post-residual is good, but dead space below a
    // threshold is nearly worthless, so penalize tiny leftovers less than
    // medium leftovers (non-linear coupling).
    if post_residual > 0 {
        let pr = post_residual as f64;
        // dead-space penalty grows super-linearly for mid-range residuals
        score += 0.35 * (pr / bin_capacity as f64) * (1.0 - (pr / bin_capacity as f64)) * 100.0;
    }

    // Lookahead: if next item fits exactly into the resulting residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward proportional to how well it fills
        let fill_after = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - fill_after / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: penalize creating unusable gap
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        // extra urgency late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins, but allow opening when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // if many bins are open with large mean residual, prefer reuse more
        score += 0.05 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 2.0 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Prefer bins with residual above mean (keep small-residual bins for small items)
    if (bin_residual as f64) < mean_residual && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: strongly penalize large residuals (prefer tight fits).
    // Late stream: relax slightly, favor keeping bins usable.
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;
    score += 8.0 * pr_norm * pr_norm * w_early - 4.0 * pr_norm * w_late;

    // Reward tight fits (small post_residual) with a smooth cubic shaping.
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Dead-space penalty: residuals too small to fit typical future items.
    let dead = if pr < 10.0 { 1.0 } else { 0.0 };
    score += 15.0 * dead * pr_norm * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 10.0 * fits_next * snug * snug;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Mild penalty when many bins are open and residual is far above mean
    // (prefer consolidating space near the mean).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a fresh bin smoothly, unless
    // post_residual is large relative to capacity (i.e., nothing else fits well).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 5.0 + 10.0 * (1.0 - pr_norm) * w_early;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue
    // classes modulo 10 (item sizes are multiples of 10 in classic streams).
    // Leftovers in "dead" classes (1..=9 mod 10 after exact multiples) are
    // hard to reuse; leftovers that are themselves multiples of 10 are
    // reusable "harmonic" space.
    let pr = post_residual;
    let harmonic = pr % 10 == 0;
    if harmonic {
        // Reward reusable leftover: the larger the reusable chunk, the better,
        // but with diminishing returns (sqrt coupling).
        score -= 6.0 * (pr as f64).sqrt();
    } else {
        // Penalize dead space, more so for very small dead slivers.
        let dead = pr % 10;
        score += (10 - dead) as f64 * 0.8;
    }

    // Perfect fit gets a strong reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward only if the fit is tight (next item consumes most of it).
            let tightness = next_item_size as f64 / pr as f64;
            if tightness > 0.75 {
                score -= 12.0 * tightness;
            } else {
                score += 3.0 * (1.0 - tightness);
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much leftover would be stranded.
            score += 4.0 + 0.1 * pr as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // unless the resulting leftover is a tiny dead sliver.
    if fitting_bins_count == 1 {
        if pr <= 9 && pr > 0 {
            score += 5.0; // creating a useless sliver in the only fitting bin
        } else {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // all open bins would leave a bad (non-harmonic, small) leftover.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for wasting a fresh bin.
        let mut nb = 25.0;
        // If current fit in open bins is poor, relax the penalty.
        let poor_fit = (bin_residual - item_size) % 10 != 0 || (bin_residual - item_size) < 10;
        if poor_fit && fitting_bins_count <= 2 {
            nb -= 20.0;
        }
        // Early in the stream, keeping bins consolidated matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 5.0 * (1.0 - progress);
        score += nb;
    }

    // Mild pressure to prefer bins whose residual deviates from the mean
    // in a useful way: prefer filling bins with above-average residual
    // (they are the "loose" ones) to keep tight bins for tight items.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Small crowding bonus: with many open bins, prefer consolidating.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2) when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if lookahead item can no longer fit anywhere after this placement.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only if this bin would leave bad dead space
    // and mean residual across open bins is already low.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual < 20 { 40.0 } else { 0.0 };
        score -= 10.0 - dead_space_penalty + mean_residual * 0.3;
    }

    // Slight stream-progression tiebreaker.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly-ish: strong reward proportional to snugness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize unusable gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // Last item: pure tight fit
        score -= 8.0;
    }

    // Compare against mean residual: bins tighter than average are more precious
    if (bin_residual as f64) < mean_residual {
        score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 1.5 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly avoid opening a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * item_size as f64;
        // If lookahead would pair well with a fresh bin, soften penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let tightness = item_size as f64 / bin_residual as f64; // in (0,1]
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect pair
        } else if next_item_size < post_residual {
            score -= 12.0;
        } else {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Last-chance bonus: only one bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or the item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        // Opening a bin is better when existing bins are quite full on average.
        score += 55.0 - 60.0 * mean_fill + 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    } else {
        // Slight preference for fuller bins among open candidates.
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mild preference to balance: avoid scattering across too many bins early.
    if open_bins_count > 4 && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, but with diminishing returns (quadratic coupling)
    let mut score = pr * (1.0 + 0.008 * pr / cap);

    // Smooth stream-progress coupling: later in the stream, dead space matters more
    score += 12.0 * pr / cap * progress * progress;

    // Reward tight fits: interaction of item_size with residual
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * (1.0 - pr / cap);

    // Lookahead: penalize leaving residual that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 4.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild pressure against opening many bins when mean residual is large
    score += 0.05 * (open_bins_count as f64).sqrt() * mean_residual / cap * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, penalized slightly unless open bins are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residues that are multiples of 5 or 10 are more reusable; penalize odd dead space.
    let residue10 = post_residual % 10;
    let residue5 = post_residual % 5;
    if residue10 == 0 {
        score -= 8.0; // perfectly aligned leftover
    } else if residue5 == 0 {
        score -= 4.0;
    } else {
        score += (5 - residue5) as f64 * 1.5; // odd dead space penalty
    }

    // Integer-division thresholds: classify post_residual into usability bands.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 6.0;
    } else if post_residual >= quarter {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 3.0; // tiny sliver, likely dead space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            let nres10 = nxt_res % 10;
            if nres10 == 0 { score -= 5.0; }
            else if nres10 % 5 == 0 { score -= 2.5; }
            else { score += 1.5; }
        } else {
            score += 2.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or many bins open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac < 0.6 {
            score += 20.0;
        }
        score += open_bins_count as f64 * 0.3;
    }

    // Tight fits are excellent: reward small post_residual.
    if post_residual < item_size {
        score -= 4.0;
    }

    // Progress modulation: later in stream, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical future items
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 5.0;
    }

    // Lookahead: prefer bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }

    // Mild tightening toward stream end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize leftover dead space
            let dead = post_residual as f64;
            score += 0.5 * dead;
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 20.0; // stranded small residual
            }
        }
    }

    // Compare post_residual relative to mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins with good fits,
    // but allow opening when existing bins would waste too much space
    if bin_residual == bin_capacity && bin_capacity == 100 {
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin pairs well with next item
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Penalize dead space: post_residual that is too small to hold a typical item.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 40.0;
        // Mid-range leftover is least useful (can't fit small items well either when fragmented)
        let frag = 1.0 - ((post_residual as f64 / 50.0) - 1.0).abs().min(1.0);
        score += frag * 8.0;
    } else {
        // Perfect fill is excellent.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad leftover
    // or when the item fits nothing well and lookahead suggests a big follow-up.
    if bin_residual == bin_capacity {
        let bad_leftover = post_residual > 0 && post_residual < 15;
        let big_next = next_item_size as f64 > mean_residual;
        if bad_leftover || (big_next && post_residual < next_item_size as u32) {
            score -= 20.0;
        } else {
            // Keep using open bins when fit is decent.
            score += 15.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / 50.0).max(0.0) * 18.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; mild penalty for hogging space it needs.
        score += 6.0;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (open_bins_count as f64 / 20.0).min(1.0) * mean_residual / bin_capacity as f64;
    score -= consolidation * (10.0 + 20.0 * progress);

    // Late in the stream, waste matters more (no time to fill leftover space).
    score += post_residual as f64 * progress * 0.5;

    // Prefer bins whose residual is close to item size (exactness reward).
    let exactness = 1.0 - ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);
    score -= exactness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual with non-linear growth (dead space aversion)
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream -> tolerate larger residuals; late stream -> punish them more
    let progress_weight = 0.5 + 1.5 * progress * progress * (3.0 - 2.0 * progress);
    score += norm_pr * norm_pr * cap * 0.35 * progress_weight;

    // Reward tight fits (small post_residual) with smooth falloff
    let tightness = (-norm_pr * 4.0).exp();
    score -= 12.0 * tightness * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // slight penalty when many options: encourage consolidation elsewhere
        score += 2.0 * (fitting_bins_count.min(8) as f64).ln();
    }

    // Lookahead: reward leaving space that can fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let fit_quality = 1.0 - ((pr - ni) / cap).powf(2.0);
            score -= 8.0 * fit_quality * (0.5 + 0.5 * progress);
        } else {
            // post-residual too small for next item: penalize proportionally
            score += 4.0 * (ni - pr) / cap * (1.0 + progress);
        }
    }

    // Mean residual coupling: prefer bins whose residual differs from mean
    // (moves toward bimodal residual structure: full-ish or roomy)
    let dev = (pr - mean_residual) / cap;
    score -= 3.0 * dev * dev.abs() * cap * 0.1;

    // Mild penalty for proliferation of open bins
    score += 0.4 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: make empty bin mildly attractive only for poor fits
    if bin_residual == bin_capacity {
        let poor_fit = (pr as f64 / cap) > 0.5;
        score += if poor_fit { 6.0 } else { 25.0 * (1.0 + progress) };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by common item sizes is reusable
    let pr = post_residual as i64;
    if pr > 0 {
        for m in [10u32, 20, 25, 50, 100].iter() {
            if pr % *m as i64 == 0 {
                score -= 8.0 + *m as f64 * 0.15;
            }
        }
        // small dead space penalty (unusable slivers)
        if pr < 10 {
            score += 30.0 - pr as f64;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large residual
            score += gap_of(post_residual, next_item_size);
        }
    }

    // Last-chance bin: avoid wasting it on a sloppy fit
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Prefer filling bins with low residual relative to mean (tight packing)
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Capacity fraction classes of item size
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 10.0 * frac;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 60.0 - 70.0 * pressure - 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    score
}

fn gap_of(post_residual: u32, next_item_size: u32) -> f64 {
    let d = (next_item_size - post_residual) as f64;
    if d < 20.0 { d * 0.5 } else { 0.0 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that exactly matches the next item's size potential poorly:
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // gap perfectly reusable by next item
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 8.0; // next item would create new dead space here
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + post_residual as f64 * 0.5;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving exactly zero space is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when the residual left behind matches the
    // next item size exactly (chained perfect fit).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 20.0 - diff * 2.0;
        } else {
            // Penalize residuals that are too small for the next item
            // (dead space) but large enough to be wasted.
            if post_residual > 0 && (post_residual as f64) < next {
                score += (next - post_residual as f64).min(30.0);
            }
        }
    }

    // Penalize small unusable post-residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: bins tighter than average are more
    // valuable to fill; looser-than-average bins are cheaper to use.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be more willing to open bins (keep flexibility);
    // later, consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 + 30.0 * progress;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Penalize dead space: residuals too small for the smallest plausible next item.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual < next_item_size as f64 * 1.0 && next_item_size > 0 {
        score += 8.0;
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 12.0 + 10.0 * fit_quality;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to how far off.
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that would otherwise waste space.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a bin is good when existing residuals are large (poor fits) or few bins fit.
        let poor_fit = open_pressure * 40.0;
        let scarcity = if fitting_bins_count == 0 { 30.0 } else { (fitting_bins_count as f64).min(5.0) * -4.0 };
        score += 55.0 - poor_fit - scarcity;
        // Early in the stream, be more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (0.5 - progress) * 10.0;
    }

    // Time horizon: late in the stream, consolidate aggressively (avoid opening new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    }

    // Global balance: prefer bins whose residual deviates favorably from the mean.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on post residual (wasted space), scaled by capacity.
    let mut score = post * (1.0 + post / cap);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post residual) are rewarded more strongly.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= tightness * tightness * (post * (0.5 + progress));

    // Cubic progress interaction: as the stream advances, penalize loose fits harder.
    let loose = (post / cap).min(1.0);
    score += loose * loose * loose * cap * (0.2 + 0.8 * progress);

    // Mean residual coupling: prefer bins whose post residual moves toward the mean.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // Lookahead: reward residual that can host the next item (smooth gate).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = if post >= n { 1.0 } else { 0.0 };
        let near = (-((post - n).abs() / cap)).exp();
        score -= 6.0 * fits_next * near + 3.0 * fits_next;
        // Penalize residual slightly too large for next item (dead space risk).
        score += 2.0 * (1.0 - fits_next) * (post / cap) * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * (1.0 - post / cap);
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    score += 0.01 * open_bins_count as f64 * (0.5 + progress) * (post / cap + 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" fractions of capacity
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 12.0; // decile-aligned residual
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else {
        score += (pr % 5) as f64 * 2.0; // penalize awkward remainders
    }

    // Dead-space threshold: residuals too small for the minimum item class
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable dead space
    }

    // Integer-division class: residual bucket via capacity / residual
    if pr > 0 {
        let div_class = bin_capacity / pr; // 1..=100
        score += match div_class {
            1 => -10.0,       // residual > 50: plenty of room
            2 => -5.0,        // residual in (33,50]
            3 => 0.0,
            4 => 4.0,
            _ => 8.0,         // small residual
        };
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward proportional to how well it packs
            let slack_after_next = pr - next_item_size;
            score -= 15.0 + (slack_after_next % 10) as f64;
            // harmonic bonus if next item exactly fills
            if slack_after_next == 0 {
                score -= 20.0;
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it over wasting it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is huge
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        if fill_frac > 0.5 {
            score -= 5.0; // big item: fresh bin acceptable
        } else {
            score += 40.0 + (open_bins_count as f64).max(1.0) * 2.0; // prefer existing bins
        }
    }

    // Late-stream tightening: as stream progresses, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64).min(50.0) * 0.2;

    // Mild pressure toward bins below mean residual (balance across bins)
    score += ((mean_residual - bin_residual as f64) * 0.05).clamp(-8.0, 8.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
