        }
        // If many bins fit the item, opening a new one is wasteful.
        score += fitting_bins_count as f64 * 3.0;
    } else {
        // Mild preference for fuller bins among open bins (best-fit flavor).
        score += (bin_capacity - bin_residual) as f64 * 0.1;
        // Prefer bins whose residual is close to the mean (keeps bin set balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Time horizon: as the stream progresses, be more conservative about opening bins,
    // i.e., reward using existing bins more strongly late in the stream.
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    // Slight penalty when many bins are already open (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (1.5 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count.max(1) as f64;
    let open_c = open_bins_count.max(1) as f64;

    // Base: post residual, with smooth non-linear polynomial in normalized residual
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Progress coupling: later in stream, penalize residual more (waste hurts more)
    score += 25.0 * norm_pr * progress * (1.0 - progress) * 4.0 * norm_pr;

    // Reward tight fits: subtract bonus that grows as post_residual shrinks (smooth)
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bin bonus (only fitting bin): smooth reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Scarcity of fitting bins: penalize mildly when many alternatives exist
    score += 3.0 * (fit - 1.0) / (fit + 2.0);

    // Mean residual coupling: prefer bins whose residual deviates smoothly from mean
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap * (0.5 + progress);
        }
    }

    // Open bins pressure: many open bins -> favor filling existing ones
    score -= 2.0 * (open_c / (open_c + 5.0)) * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a fresh bin unless residual savings are large
    if bin_residual == bin_capacity {
        score += 18.0 + 20.0 * progress - 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by capacity fractions (1/4, 1/2, 3/4)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let item_class = if item_size >= half + quarter { 3 }
        else if item_size >= half { 2 }
        else if item_size >= quarter { 1 }
        else { 0 };

    // Post-residual harmonic class: dead space granularity
    let post_class = post_residual / 10; // coarse class of leftover space

    // Reward tight fits: post_residual in a low class gets a bonus
    if post_residual == 0 {
        score -= 100.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_class <= 2 {
        score -= 10.0;
    }

    // Penalize dead space that no future item (min size ~1) can use well:
    // residual in (0, 10) is nearly wasted; residual in (10, 25) is semi-usable
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual > 10 && post_residual < quarter {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 60.0;
        } else if next_post < 10 {
            score -= 25.0;
        } else {
            score -= next_post as f64 * 0.2;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: slight penalty if we waste
        // a bin that could have hosted next item instead
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    // Make new bin unattractive unless residual here is tiny and next item is large.
    if bin_residual == bin_capacity {
        // Empty-bin candidate: base cost plus penalty scaled by how many open bins exist
        score += 30.0 + (open_bins_count as f64).sqrt() * 5.0;
        // But if current bin residual can't hold next item well and item is big, allow it
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Harmonic modulo logic on post_residual: prefer residuals that are multiples
    // of common item sizes (10, 20, 25, 50) — these are reusable classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Progress-aware mild pressure: late in the stream, favor consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * mean_residual * 0.05;
    score += (mean_residual - post_residual as f64).abs() * 0.03;

    // Small tie-breaker favoring fuller bins
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Check if next item could use the post_residual gap: reward keeping usable space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that the known next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Last chance before opening a new bin: strong incentive to use this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // (penalize the new-bin candidate relatively more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * open_bins_count as f64 + 30.0 * progress;
    } else {
        score -= 5.0 * open_bins_count.min(20) as f64;
    }

    // Prefer bins tighter than the mean residual (better packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.12;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on wasted space, amplified by stream progress
    let mut score = post * (1.0 + 1.5 * progress) + 0.004 * post * post;

    // Reward tight fits (small post_residual relative to capacity)
    score -= 30.0 * (1.0 - post / cap).powi(6);

    // Non-linear coupling of post_residual with mean residual of all bins:
    // placing in a bin whose post-residual aligns with mean residual is harmonious
    let align = (post - mean_residual) / cap;
    score += 12.0 * align * align;

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size as f64 <= post {
        let slack = post - next_item_size as f64;
        score -= 18.0 * (1.0 - slack / cap).powi(3);
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving dead space
        score += 6.0 * (post / cap).powi(2);
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: mild penalty early (prefer filling), decreasing late;
    // also penalize if existing bins are plentiful
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 0.8 * open_bins_count as f64;
        // allow new bin if item is large and fits poorly anywhere
        score -= 10.0 * (item / cap).powi(2);
    }

    // Slight preference for bins already partially filled (avoid bin proliferation)
    score += 0.05 * (bin_residual as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands (dead-space classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Penalize leftovers that are "unusable" harmonic classes:
    // tiny slivers (<10% of capacity) are nearly dead space.
    if frac < 0.10 {
        score += 25.0 * (0.10 - frac) / 0.10;
    }
    // Mid-range leftovers (10%..20%) are moderately wasteful.
    if frac >= 0.10 && frac < 0.20 {
        score += 8.0 * (frac - 0.10) / 0.10;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr).abs() < 0.5 {
            score -= 60.0;
        } else if ni <= pr {
            // reward proportionally to how well next item uses the leftover
            score -= 30.0 * (ni / pr);
        } else {
            // next item won't fit: leftover likely becomes dead space,
            // penalize more the smaller (more stranded) the leftover is.
            score += 10.0 * (1.0 - pr / ni).min(1.0);
        }
    }

    // Modular arithmetic on post_residual: leftovers congruent to small
    // residues mod 10 tend to pair well with common item sizes (multiples of 10).
    let residue_class = post_residual % 10;
    score -= match residue_class {
        0 => 6.0,
        1 | 9 => 1.0,
        2 | 8 => 0.5,
        _ => 0.0,
    };

    // Integer-division threshold: leftover >= half capacity is a "fresh half",
    // still very usable; mild reward.
    if post_residual >= bin_capacity / 2 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is huge relative
    // to typical residuals or no bins fit well; penalize otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (open_bins_count as f64) / (1.0 + mean_residual / cap.max(1.0));
        // Prefer new bin when open bins are crowded and item is large.
        let item_pressure = item_size as f64 / cap;
        score += 40.0 - 35.0 * item_pressure - 4.0 * crowding.min(5.0) + 10.0 * progress;
    }

    // Slight preference for tighter (more filled) bins overall.
    score -= 0.05 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32; // interface allows sizes from 1
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // Gaps that cannot hold the lookahead item are likely dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward gaps that still accommodate the next item.
        score -= 15.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving exactly-tiny residuals relative to capacity.
    if post_residual > 0 && (post_residual as f64) < 0.1 * bin_capacity as f64 {
        score += 25.0;
    }

    // Open-bin pressure: with many bins open, prefer compacting into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing bins would leave large wasted space.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = 55.0 + 0.6 * waste - 0.1 * open_bins_count as f64;
    }

    // Mild stream-progression bias: later in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect chain: post_residual exactly fits the next item -> strong reward.
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Next item fits in the post residual -> moderate reward, scaled by tightness.
        else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        }
        // Next item does NOT fit -> penalize dead space that blocks the chain.
        else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Tight fit reward relative to mean residual across open bins.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 25.0;

    // Penalize bins whose residual deviates far above the mean (hoarding space).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New empty bin candidate: only attractive when residual is large (item small)
    // or no good fit exists; otherwise discourage wasting a fresh bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Penalize dead space that can't fit a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // Reward bins that can still host the lookahead item.
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it if fit is decent,
    // otherwise penalize heavily to push toward a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= 20 {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate: prefer it only when current residual is large and fragmented.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.1 + open_bins_count as f64 * 0.5;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 8.0;
        }
    }

    // Prefer bins with residual close to item (best fit shape).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // Time horizon: early on, be picky (favor tight fits more); later, accept good-enough fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // Small tie-break toward bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear tightness reward: quadratic in normalized post-residual
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * cap;

    // Perfect fit bonus (smooth exponential decay)
    score -= 20.0 * (-pr as f64 / 4.0).exp();

    // Penalize dead space relative to mean residual (waste coupling)
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize early, allow late when residual is small
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) * (1.0 - progress) * cap / 10.0;
        score -= 5.0 * progress;
    }

    // Lookahead coupling: reward leaving space that fits the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 6.0 * (-slack * 8.0).exp();
        } else {
            score += 3.0 * (ni - pr) / cap * cap / 10.0;
        }
    }

    // Congestion term: many open bins -> favor consolidation
    score += 0.4 * open_bins_count as f64 * pr_norm;

    // Stream-progress drift: late in stream, be greedier about tight fits
    score -= 8.0 * progress * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into 10-wide classes (capacity/10).
    let class = (post_residual / 10) as f64;
    score += class * 1.5;

    // Reward near-perfect fits: post_residual in the "harmonic residue" band.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that no future item can use well:
    // residues in (0,10) are unusable for items >= 10 in the classic regime.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Modulo-20 coupling: residues that are multiples of 20 pair well with
    // common item sizes; small prime residues are risky.
    let r = post_residual % 20;
    if r == 0 && post_residual > 0 {
        score -= 6.0;
    } else if r > 0 && r < 5 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // next item cannot use this bin's remainder anyway
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // (mean residual small) or the current fit is poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        if post_residual as f64 > bin_capacity as f64 - item_size as f64 - 0.5 {
            // this is the empty-bin call itself
            if crowded > 0.35 || fitting_bins_count == 0 {
                score -= 30.0; // open a fresh bin
            } else {
                score += 10.0; // prefer packing into existing bins
            }
        }
    }

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Late-stream tightening: waste matters more near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Usable leftover: mild reward scaled by how much usable space remains.
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward filling large chunks of the bin (tight packing).
    score -= 25.0 * (item_size as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins when residuals are plentiful.
    if open_bins_count > 0 {
        score += 2.0 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; penalize leaving a gap it almost fits.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 20.0 * (10.0 - gap);
            }
        }
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = mean_residual >= item_size as f64 * 1.05;
        if good_fit_exists && fitting_bins_count > 0 {
            score += 35.0; // prefer an existing bin
        } else {
            score -= 10.0; // allow opening a fresh bin for poor fits
        }
        // Late in the stream, opening new bins is cheaper than hoarding dead space.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with slight superlinear penalty on waste.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // --- 2-step lookahead: does the leftover space fit the next item? ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits; the smaller the gap between post_residual and next size,
            // the better (less residual left after two placements).
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - (slack / bin_capacity as f64) * 35.0;
        } else {
            // Next item cannot fit in the leftover: dead space risk, penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += (waste / bin_capacity as f64) * 45.0;
        }
    } else {
        // Last item: just minimize post_residual strongly.
        score -= 20.0;
    }

    // --- Last-chance bonus: if this is the only bin that fits, use it. ---
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline with mild penalty so it only wins when
        // no open bin offers a decent (low-waste) fit.
        score = 55.0 + (item_size as f64 / bin_capacity as f64) * 25.0;
        // Favor opening a new bin for large items that would leave big waste elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If next item is huge, a fresh bin is attractive.
        if next_item_size >= bin_capacity / 2 && item_size + next_item_size <= bin_capacity {
            score -= 35.0;
        }
        // Many open bins with slack: discourage yet another bin.
        if mean_residual > 30.0 {
            score += 20.0;
        }
        return score;
    }

    // Compare against mean residual: bins tighter than average are better to fill.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 5.0;
    }

    // Early in the stream, allow slightly more bins to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 0.35 * (post_residual as f64 - next_item_size as f64).min(50.0);
        } else {
            // next item cannot use this residual: slight penalty proportional to gap
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bin residuals are fragmented or the item fits nothing well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Discount new bin when existing bins are fragmented (low mean residual).
        score -= 0.4 * mean_residual;
        // Discount when many bins already open (consolidation pressure lower).
        score -= 1.5 * (open_bins_count as f64).sqrt();
        // Discount late in stream? No: prefer consolidation late.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If item is large, a fresh bin is more attractive.
        score -= 0.2 * item_size as f64;
    }

    // Prefer bins whose residual is close to mean (balanced usage) early on.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 - norm_pr * progress * 30.0
                 + norm_pr.powi(3) * 15.0 * (0.5 + progress);
    score += coupling;

    // Penalize last-chance bins mildly, reward tight fits
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - (next_item_size as f64 - pr) / cap);
    }

    // New-bin candidate: prefer it when existing residuals are large
    if bin_residual == bin_capacity {
        score -= 10.0 + 20.0 * (mean_residual / cap) * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 create "good" leftover classes
    let residue_class = post_residual % 10;
    // Residues that pair well with typical small items (0, 10, 20...) are desirable
    let class_bonus: f64 = match residue_class {
        0 => 14.0,
        1 | 9 => 2.0,
        2 | 8 => -1.5,
        3 | 7 => -3.0,
        4 | 6 => -5.0,
        _ => -8.0, // class 5: half-full leftover, least reusable
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: dead space bands
    let band = post_residual / 10;
    if band == 0 {
        // near-perfect fit: strong reward
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual > 50 {
        // large leftover wastes capacity unless bin is fresh
        score += 6.0;
    }

    // Coupling with next item lookahead (k=2)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // this bin can also host the next item: reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.08;
        } else {
            // next item cannot follow here; penalize if we burned a scarce fitting bin
            score += 3.0;
        }
        // harmonic check: does post_residual mod next_item_size leave a small tail?
        if next_item_size > 0 && post_residual % next_item_size.max(1) <= 5 {
            score -= 4.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: fresh bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // open a new bin when existing bins are fragmented or item is large
        if item_size >= 60 || mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Stream progression: late in stream, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Mild pressure to prefer fuller bins when many bins are open
    score += open_bins_count as f64 * 0.15;

    // Mean residual coupling: if this bin's residual is far below mean, it is a good consolidation target
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        // Small gap: only usable by tiny items, mildly penalize.
        score += 12.0;
    } else if post_residual >= 50 {
        // Large leftover keeps future flexibility; reward.
        score -= 8.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; slight penalty.
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-attractive only when all
    // open bins would leave tiny dead space; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 45.0; // opening fresh bin beats tiny-gap placement elsewhere
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter packing).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect lookahead: next item can fit with small leftover slack.
    if next_item_size > 0 && post_residual >= next_item_size {
