        // Next item cannot follow into this bin: penalize proportionally to the shortfall.
        let shortfall = next_item_size - post_residual;
        score += shortfall as f64 * 0.6;
    }

    // Penalize dead space relative to the mean residual of open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Small bonus when the bin becomes nearly full (tight packing).
    if post_residual <= 10 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Discard tiny residual slivers that likely become dead space.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Mild pressure to prefer already-open bins over opening a new one early in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

