    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves waste; mild reward scaled by fit quality
            let next_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 25.0 * next_fit;
        } else {
            // next item cannot use this residual: penalize dead space creation
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: slight penalty to prefer the best-fitting one
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: prefer filling bins when many bins are open (reduce fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier
    // worth consolidating into; if far above mean, deprioritize.
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += 0.10 * residual_gap;

    // Late in the stream, be conservative: avoid leaving large unusable residuals.
    if progress > 0.8 {
        score += 0.20 * (post_residual as f64);
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit
    // (large post_residual for open bins means wasted space; fresh bin starts clean).
    if bin_residual == bin_capacity {
        // A new bin is good when item is large relative to capacity or few bins fit.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count <= 2 {
            score -= 30.0 + 40.0 * large_item;
        } else {
            score += 20.0; // discourage opening new bins when open bins fit fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Penalize large dead space quadratically, scaled by stream progress.
    score += (norm_pr * norm_pr) * cap * (0.2 + 0.6 * progress);

    // Reward tight fits (small post_residual) more strongly later in stream.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0 * (0.5 + progress);

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits in post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - norm_pr) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize wasting residual capacity.
        score += (next_item_size as f64 / cap) * 8.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many bins vs. mean residual alignment.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);
    score += (mean_residual - pr).abs() * 0.1;

    // New-bin candidate: keep it attractive when residuals are all poor.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 20.0 * (1.0 - progress) + norm_pr * cap;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

