    let residue_class = (post_residual % 10) as f64;
    // Penalize residues that are hard to fill later (small nonzero remainders are worst).
    if post_residual > 0 {
        score += 12.0 - residue_class * 1.2; // residue 0 (perfect) best, residue 1 worst
    } else {
