    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable dead space
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0; // partially usable
    }

    // Capacity fraction coupling: how much of the bin the item consumes.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0; // reward large fill of existing bin

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post_residual exactly or well, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 18.0;
        } else {
            // next item won't fit here: penalize leaving residual just below next size
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; overcome only if existing bins have bad fits.
        score = 55.0;
        // If many bins fit the item, discourage opening a new one.
        score += fitting_bins_count as f64 * 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // If mean residual across open bins is large, no need for a new bin.
        score += (mean_residual / bin_capacity as f64) * 30.0;
        // If current item is small, it should go into an existing bin.
        score += (bin_capacity as f64 - item_size as f64) * 0.6;
        // But if item is huge and nothing fits well, new bin becomes attractive.
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 70.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            score -= 20.0; // pair big items in fresh bins
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
