        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Bonus: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0; // chain fit: post_residual almost exactly fits next item
        } else {
            score -= 8.0; // next item fits comfortably
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= 20 {
        // Next item won't fit here; if post_residual is a sliver, penalize slightly more.
        if post_residual < 20 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // unless the fit is truly bad (handled above via dead-space penalties).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty growing with open bins and stream progress.
        score += 15.0 + (open_bins_count as f64) * 2.0 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // A new bin is attractive only if the current item is large relative to capacity
        // (leaves a big usable residual in a fresh bin anyway).
        score -= (item_size as f64) * 0.2;
    } else {
        // Mild reward for consolidating into existing bins when open bins are numerous.
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fit) relative to fleet mean.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Slight preference for bins below mean residual (filling emptier bins first
    // keeps tight bins available for tight items) — inverted: prefer bins ABOVE mean
    // residual being consumed, i.e. penalize placing into already-tight bins.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this is a chained perfect fit — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * gap;
        }
    }

    // Compare against mean residual: bins tighter than average are better
    // candidates for filling; looser bins slightly penalized.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins exist with decent fit:
    // make the empty-bin candidate less attractive unless current bins are tight.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let tightness = mean_residual / bin_capacity as f64;
        // New bin gets a base penalty that shrinks when existing bins are very tight
        // (mean_residual small means open bins are nearly full).
        score += 60.0 + 100.0 * tightness - 30.0 * progress;
        // But if nothing else fits and item is large, allow new bin:
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Small reward for placing larger items early (best-fit decreasing flavor
    // via item size coupling with progress).
    score -= 0.1 * item_size as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual), with a non-linear quadratic term.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Penalize dead space: residuals too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize more if post residual is small.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: only one bin can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins with residual below the mean (compact bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Discourage opening new bins when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if no open bin fits well, opening a bin is fine (post_residual == capacity - item)
        if (bin_capacity as f64 - item_size as f64) <= 5.0 {
            score -= 45.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.35 * progress * progress)
        - 0.9 * norm_post * norm_post * cap * (1.0 - progress);

    // Reward tight fits smoothly (low post_residual)
    score -= 12.0 * (1.0 - norm_post).powi(3);

    // Penalize large dead space more than linearly
    score += 6.0 * norm_post.powi(3) * cap * 0.01;

    // Lookahead: favor bins whose post residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 3.0 * progress;
    }

    // Last-chance bin: reward strongly to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress) * (mean_residual / cap).abs().min(1.0);
    }

    // Slight preference for consolidating when many bins are open
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual divisible by 10 -> clean slot for standard sizes.
    // Class 1: divisible by 5 -> moderately usable.
    // Class 2: dead space (odd/prime-ish residues) -> penalize.
    let post = post_residual;
    let class = if post % 10 == 0 { 0 } else if post % 5 == 0 { 1 } else { 2 };
    score += match class { 0 => -6.0, 1 => 0.0, _ => 8.0 };

    // Integer-division threshold: tiny unusable leftovers are wasted capacity.
    if post > 0 && post < 10 {
        score += 20.0;
    }
    // Perfect fit: reward strongly.
    if post == 0 {
        score -= 40.0;
    }

    // Tightness ratio: prefer bins where item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill * fill;

    // Lookahead coupling: harmonic class of next item vs. post residual.
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item fits exactly into a harmonic class of the leftover.
            if post % 10 == 0 && next_item_size % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            score += 4.0 + (next_item_size - post) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: prefer only when current bin would leave bad dead space
    // and the stream is early (lots of future items to amortize the new bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = class == 2 || (post > 0 && post < 10);
        if bad_fit {
            score -= 25.0 + 20.0 * (1.0 - progress);
        } else {
            score += 10.0 + 15.0 * progress;
        }
    }

    // Spread across open bins: with many open bins, consolidate into tighter bins.
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual - post as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize if next item cannot fit here and would be stranded.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (2.0 + 3.0 * progress) * 0.1;

    // Prefer bins tighter than the mean residual (better consolidation).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., item barely fits nowhere / residual would be tiny elsewhere),
    // or when the item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if item_size >= 50 && fragmentation < 0.35 {
            score -= 25.0;
        } else {
            score += 45.0 + 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain (post_residual == next_item_size) is ideal.
            score -= 45.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // exact 2-step chain bonus
            }
        } else {
            // Next item cannot chain into this bin: penalize proportionally to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.30 * overflow;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual near mean are "normal" targets;
    // prefer placing into bins whose residual is above mean (bigger slack absorbs item).
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.15 * (res - mean_residual);
    } else {
        score += 0.10 * (mean_residual - res);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the item
    // is large or the current fit is poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.8 {
            score -= 30.0; // large item: fresh bin is fine
        } else {
            score += 55.0 - 40.0 * tightness; // small item: discourage wasting a fresh bin
        }
    }

    // Slight preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is barely above item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Dead-space penalty: small post-residuals that can't fit a typical item are wasted.
    if post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).min(1.0);
        }
    }

    // Prefer bins with residual close to the mean residual (keeps bin pool balanced),
    // unless the bin is a fresh new-bin candidate.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    } else {
        // New-bin candidate: penalize opening a new bin unless current pool is crowded
        // or the fit in existing bins would be terrible.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fit_quality = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        let open_penalty = (open_bins_count as f64) * 1.5;
        score += 60.0 - open_penalty - 30.0 * fit_quality * (1.0 - progress);
    }

    // Late in the stream, consolidate: favor using existing bins more aggressively.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Large items: prefer bins with larger residuals to avoid fragmentation.
    if item_size >= 50 {
        score += 0.1 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual as u64) == (bin_capacity as u64);

    // Base: prefer small post residual (tight fit).
    let mut score = pr;

    // Smooth non-linear coupling: normalized post-residual shaped by stream progress.
    let prn = pr / cap;
    // Late in the stream, dead space matters more (less chance to fill it).
    let urgency = 0.5 + 0.5 * progress;
    score += (prn * prn) * cap * 0.35 * urgency;

    // Perfect-fit reward: smooth bump when post_residual is tiny.
    let tight = (-prn * 12.0).exp();
    score -= tight * 6.0;

    // Reward filling a bin completely (post_residual == 0 handled by tightness),
    // also reward item_size close to bin_residual smoothly.
    let fill_ratio = it / (bin_residual.max(1) as f64);
    score -= (fill_ratio * fill_ratio) * 8.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (penalize alternatives implicitly by lowering this score).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins with residual far below mean residual (fragmented bins),
    // smoothly scaled by how much of the bin is used.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += (dev * dev) * 4.0;

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs() / cap;
        score -= (-diff * 10.0).exp() * 9.0;
        // If next item can't fit here anyway, slightly penalize leaving awkward gaps.
        if nx > pr {
            score += (prn * prn) * 5.0;
        }
    }

    // New-bin candidate: must lose against good fits, win against terrible fits.
    // Smoothly scale its score with stream progress and current open-bin count.
    if is_new_bin {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score = cap * (0.85 - 0.10 * progress) + crowd * 2.0 - 12.0 * (1.0 - fill_ratio.min(1.0));
        // If no open bin fits at all (fitting_bins_count counts only open bins, new bin excluded),
        // opening is forced; make it clearly attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 create
    // "usable" classes (0,5) vs awkward classes (1,9). Reward clean classes.
    let cls = (post_residual % 10) as f64;
    let class_bonus = match post_residual % 10 {
        0 => 14.0,
        5 => 9.0,
        2 | 8 => 4.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Dead-space penalty grows super-linearly for small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly or well,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
        // Exact chain fit
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for the next item: penalize awkward leftovers.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Fragmentation pressure: prefer bins whose residual is far below the mean
    // (fill the emptiest-feeling bins) scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.35 * (mean_residual - bin_residual as f64) * (0.5 + progress);

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits or the current fit is terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else if post_residual > 60 {
            // Plenty of room elsewhere; new bin mildly attractive for big items.
            score -= 5.0 + 0.1 * item_size as f64;
        } else {
            score += 25.0; // discourage wasteful new bins
        }
    }

    // Mild preference for tighter fits overall.
    score += 0.15 * (bin_residual - item_size) as f64 * 0.0; // (kept neutral)

    // Modulo-class harmonic on item size vs residual: pair large items with
    // large residuals (coarse class matching).
    let item_cls = item_size / 20;
    let res_cls = bin_residual / 20;
    if item_cls == res_cls {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

