    }

    // Reward using bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tightness) * 0.15;

    // Open-bin pressure: prefer keeping the number of open bins low.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residual below mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Last chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

