    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0 - gap as f64;
            } else {
                score += gap as f64 * 0.2;
            }
        } else if post_residual > 0 {
            score += 5.0; // next item cannot use this leftover space
        }
    }

    // New-bin candidate: only attractive when few fitting bins exist or item is large.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score = score - pressure + 20.0 + (open_bins_count as f64).sqrt() * 5.0;
        if item_size > 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize relative to leftover dead space
        score += 50.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual to mean residual: prefer leaving residuals near the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins can fit reasonably well
    if bin_residual == bin_capacity {
        score += 150.0;
        // if next item is large, a fresh bin may be attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Late in stream: prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward filling bins almost exactly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize creating dead space too small for any plausible item (min size 1..10 range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Many fitting bins: mild penalty for hogging a scarce-residual bin.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // New-bin candidate logic: only open a new bin when it's genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, shrinking as stream fills up.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 55.0 - 25.0 * progress;
        // If existing bins are fragmented, opening fresh is more attractive.
        open_cost -= 0.4 * (mean_residual - post_residual as f64).max(0.0);
        // If no open bin fits at all (this call is the only candidate), opening is fine.
        if fitting_bins_count == 0 {
            open_cost -= 70.0;
        }
        // Lookahead: if next item is large, a fresh bin preserves flexibility.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            open_cost -= 20.0;
        }
        // Late in stream, prefer closing out existing bins.
        if progress > 0.8 {
            open_cost += 20.0;
        }
        score += open_cost.max(-80.0);
    }

    // Lookahead synergy: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Prefer bins with residual above mean (keep balanced pool) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer placing into emptier bins when few bins open (consolidation).
    if open_bins_count > 1 {
        score += 0.1 * (open_bins_count as f64 - 1.0) * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;

    // Base: post residual, with non-linear shaping (quadratic waste term)
    let mut score = pr - 12.0 * fit_ratio * (1.0 - fit_ratio);

    // Smooth stream-progress coupling: later in stream, prefer tighter fits
    score -= 10.0 * progress * fit_ratio * fit_ratio;

    // Penalize dead space relative to mean residual (smooth cubic coupling)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * (1.0 + progress);

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.08 * gap;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        }
    } else {
        // Last item: strongly prefer minimal post residual
        score += 5.0 * fit_ratio;
    }

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits: post_residual in low harmonic classes.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < eighth {
        score -= 25.0;
    } else if post_residual < quarter {
        score -= 10.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    } else {
        score += 20.0; // large dead space
    }

    // Modulo-class logic: residuals congruent to common item sizes (e.g. multiples of 10)
    // are more likely reusable by future items; penalize awkward residues.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 6.0;
    } else if residue_class >= 7 {
        score += 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / c);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            score += 6.0 * ((next_item_size - post_residual) as f64 / c);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / c; // high mean residual => open bins have room
        let mut penalty = 12.0 + 30.0 * crowding + 10.0 * progress;
        // If next item is large and no open bin will likely fit it, opening new bin is OK.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            penalty -= 8.0;
        }
        score += penalty.max(0.0);
    }

    // Slight preference for filling fuller bins (small residual before placement).
    score += 0.05 * (bin_residual as f64 / c) * 10.0;

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small post_residual gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap 1 -> +56, gap 9 -> +24
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Reward filling a bin deeply (waste minimization).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits into post_residual, bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // dead space relative to lookahead
    }

    // New-bin candidate: keep it neutral-ish, only attractive when open bins are tight.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        if post_residual >= 70 {
            score -= 10.0; // large bin leaves flexible space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post_residual as f64 - next).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if next <= post_residual as f64 {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64); // next item still fits here
        } else {
            score += 10.0 + diff * 0.2; // next item would NOT fit after this placement
        }
    }

    // Penalize creating small unusable dead space (below typical minimum item size 1..100,
    // treat tiny residuals as waste unless they match the next item).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 15.0;
    }

    // Prefer bins tighter than the mean (best-fit style), penalize loose bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if post_residual as f64 >= next_item_size as f64 && next > 0.0 {
            score -= 5.0; // fresh bin can also host the next item
        }
        score += 25.0 * (1.0 - fragmentation); // costly when open bins still have room
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative: open a new bin
        }
    }

    // Mild stream-progression pressure: as stream advances, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward this bin; otherwise penalize dead space that can't host it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 12.0 * (nxt / bin_capacity as f64);
        } else {
            let dead = (post_residual as f64).min(nxt - 1.0);
            score += 0.25 * dead;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    // when mean residual is high relative to this bin's post residual.
    if open_bins_count > 1 {
        let gap = mean_residual - post_residual as f64;
        if gap > 0.0 {
            score += 0.10 * gap;
        } else {
            score -= 0.05 * gap.abs();
        }
    }

    // Time horizon: early in the stream, be conservative (favor open bins);
    // late in the stream, exactness matters more since waste is permanent.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 8.0 * (1.0 - tightness);

    // Mild penalty for opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let escape = if fitting_bins_count == 0 { 0.0 } else { 6.0 + tightness * 10.0 };
        score += escape;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Quadratic dead-space penalty: small residuals are disproportionately bad.
    score += (post / cap).powi(3) * cap * 0.5;

    // Stream-progress coupling: as stream advances, tighten packing (favor small post_residual more).
    score *= 1.0 + 0.6 * progress * (post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: penalize if next item cannot fit in the post-residual.
    if next_item_size > 0 {
        if (next_item_size as f64) > post {
            score += 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Reward leaving space exactly usable by the next item.
            let gap = post - next_item_size as f64;
            score -= 6.0 * (1.0 - gap / cap);
        }
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are poor fits.
    if is_new_bin {
        score += 12.0 + 0.1 * open_bins_count as f64 - 10.0 * progress;
    }

    // Slight penalty if this bin's residual deviates from mean residual (encourage balance).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create dead-space bands.
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    if pr > 0 {
        // Penalize residuals that are "unusable" for typical item sizes (1..100):
        // small nonzero residuals below the minimum item size are dead space.
        if pr < 10 {
            score += 60.0 - (pr as f64) * 4.0;
        }
        // Penalize odd harmonic classes slightly; even classes pair better.
        if pr % 2 == 1 {
            score += 3.0;
        }
        // Reward residuals in friendly classes (multiples of 10 or 20).
        if pr % 20 == 0 {
            score -= 6.0;
        } else if pr % 10 == 0 {
            score -= 3.0;
        }
        // Mid-band penalty: residuals in [10, 25) rarely fit mid-size items.
        if pr >= 10 && pr < 25 {
            score += 8.0 - residue * 0.3;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // Reward proportionally to how well the next item fills this bin.
            let fill = (next_item_size as f64) / (pr as f64);
            score -= 12.0 * fill;
        } else {
            // Next item won't fit here: penalize large leftover residues modulo classes.
            score += residue * 0.4;
        }
        // Harmonic check: next item's residue class vs post_residual class.
        if pr % 10 == (next_item_size as u32 % 10) && pr >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild penalty to keep tight fits prioritized.
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good residual class exists
    // among open bins (mean residual low) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a fresh bin scaled by stream progress.
        score += 30.0 + 20.0 * (1.0 - progress);
        if mean_residual > item_size as f64 + 5.0 {
            // Open bins have plenty of room; discourage new bin.
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size <= 50 {
            score += 5.0;
        }
    }

    // Fraction-of-capacity harmonic: reward bins whose post_residual is a
    // clean fraction of capacity (1/4, 1/2, 3/4 classes).
    let quarter = bin_capacity / 4;
    if pr == quarter || pr == 2 * quarter || pr == 3 * quarter {
        score -= 5.0;
    }

    // Small coupling with mean residual: prefer bins below the mean (tighter).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for anything useful are heavily penalized.
    // A residual that cannot fit the next item (or a minimal item) is "dead space".
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 12.0;
    }

    // Penalize residuals below the next item's size harder when next item is known
    // (this bin's leftover likely can't serve the immediate future).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 40.0;
    } else {
        score -= (item_size as f64) / (post_residual as f64 + 1.0) * 3.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize the new-bin candidate implicitly by
    // discounting this bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or this
    // bin would leave a very awkward gap. Penalize opening new bins under
    // open_bins_count pressure.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
        // But if no open bin fits well (this is called for the new bin anyway),
        // soften when mean residual is low.
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Slight progression coupling: later in the stream, tighten up more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: bonus if next item fits the post residual exactly or well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 100.0 * tight;
        } else {
            // next item cannot fit here: penalize dead space creation
            score += 50.0 * (nxt / 100.0);
        }
    }

    // Penalize large leftover relative to mean residual (fragmentation)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Slight preference for filling bins more tightly early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is good, especially when it's an exact fill.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize dead space that no plausible item can fill (min item size 1).
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // Lookahead: if the next item fits the post residual, this is a great pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_pair = post_residual - next_item_size;
        score -= 15.0 + 0.5 * (next_item_size as f64);
        if slack_after_pair == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving awkward gap.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (consolidate small leftovers), avoid draining large-residual bins.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: late in the stream, prioritize closing bins out (tight fits matter more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Mild penalty for spreading across many open bins when few are needed.
    score += 0.2 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth progress coupling: early stream, tolerate larger residuals;
    // late stream, penalize residual more strongly (quadratic in t)
    score *= 1.0 + 0.8 * t * t;

    // Dead-space penalty: residual too small for typical future items
    let dead = if pr > 0.0 {
        let min_item = 1.0f64;
        ((min_item - norm_pr).max(0.0)).powi(3)
    } else {
        0.0
    };
    score += 12.0 * dead;

    // Reward filling a bin nearly completely (smooth exponential bonus)
    score -= 6.0 * (-(1.0 - norm_pr).max(0.0) * 4.0).exp();

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * t;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Mean residual alignment: prefer bins close to mean residual (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 1.5 * dev * dev;

    // Many open bins: slight penalty to spreading into new bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: make empty bin attractive only when it beats poor fits
    if bin_residual == bin_capacity {
        score = 55.0 - 10.0 * t - 4.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residuals divisible by large
    // "friendly" steps (25, 20, 10, 5) are more reusable by future items.
    let pr = post_residual;
    let friendly = if pr == 0 { 4.0 }
        else if pr % 25 == 0 { 3.0 }
        else if pr % 20 == 0 { 2.5 }
        else if pr % 10 == 0 { 2.0 }
        else if pr % 5 == 0 { 1.0 }
        else { 0.0 };
    score -= friendly * 4.0;

    // Small residuals are dead space unless zero: penalize tiny leftovers.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit bonus, stronger near the end of the stream.
    if pr == 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= 8.0;
        } else {
            // next item cannot use leftover: mild penalty scaled by waste
            score += (pr as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (penalize new bins early, mildly reward when open bins are crowded).
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count > 0 {
            mean_residual / cap
        } else { 0.0 };
        score += 40.0 - 30.0 * crowded.min(1.0);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item pairs well in a fresh bin
        }
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - cap) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the minimum item (1) are fine, but gaps below a usable threshold are
    // penalized super-linearly since they trap capacity.
    let usable_gap = if post_residual >= 10 { 0.0 } else {
        let d = (10 - post_residual) as f64;
        12.0 + d * d * 1.5
    };
    score += usable_gap;

    // Reward near-perfect fits (small post_residual that is still usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 8.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure is always excellent
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; penalize candidates proportionally.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are few or the
        // item is huge relative to capacity and fits nowhere well.
        let huge = (item_size as f64 / bin_capacity as f64) > 0.6;
        if open_bins_count <= 2 || huge {
            score -= 6.0;
        } else {
            score += 4.0 + pressure * 0.5;
        }
    } else {
        // Existing bin: mild reward for using already-open bins.
        score -= 1.0 + 0.3 * pressure.min(10.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if post_residual > 30 {
            score += 6.0; // but not if it wastes more than 30
        }
    }

    // Lookahead coupling: if the next item fits exactly into the resulting
    // residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 9.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            score -= 4.0;
        }
    }

    // Mean-residual coupling: prefer bins whose post-residual keeps the
    // fleet's average residual balanced (avoid creating outliers).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Stream progression: late in the stream, tighten up — waste less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: tiny post_residual is excellent.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size (perfect chain placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Exact chain match bonus
        if post_residual == next_item_size {
            score -= 150.0;
        }
        // Penalize post_residual that is too small for the next item
        // (dead space the next item cannot use).
        if (post_residual as u64) < next_item_size as u64 {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (use up nearly-full bins first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin unless the fit is exceptional.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But allow new bin if no open bin gives a good fit
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score += 10.0;
        }
    }

    // Mild preference for using more open bins rather than growing the count.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize small-but-annoying post residuals (dead space that is hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize proportionally to waste.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer filling bins with large residuals when many bins are open (consolidation).
    if bin_residual != bin_capacity {
        let residual_frac = bin_residual as f64 / bin_capacity as f64;
        score -= (open_bins_count as f64).ln().max(0.0) * residual_frac * 2.0;

        // Penalize placing into a bin whose residual is far below the mean residual
        // (keep big residuals available for big future items), unless it's a tight fit.
        let deviation = mean_residual - bin_residual as f64;
        if deviation > 0.0 && post_residual > 0 {
            score += 0.15 * deviation;
        }
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    // or the item is large relative to residuals; otherwise discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && post_residual > 0 && post_residual < item_size / 2);
        if poor_fits {
            score -= 10.0 + 5.0 * progress;
        } else {
            score += 15.0 + open_bins_count as f64;
        }
        // Early stream: opening bins is cheap; late stream: consolidate harder.
        score -= 8.0 * (1.0 - progress);
    }

    // Mild time-horizon coupling: as stream progresses, tighten fits more aggressively.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

