    let mut score = pr;

    // non-linear coupling of post_residual with stream progress:
    // early on, keep residuals flexible; late, minimize waste aggressively
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (20.0 + 60.0 * progress * progress);

    // dead-space penalty grows quadratically when residual becomes unusable
    let dead = (pr / (item_size.max(1) as f64)).ln().max(0.0);
    score -= 8.0 * (1.0 - dead.min(1.0));

    // last chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let fit_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 12.0 * fit_next * (1.0 - progress);
        // penalize wasting space if next item won't fit anywhere else
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap > 0.0 {
            score += 0.05 * gap * (1.0 - fit_next);
        }
    }

    // crowd control: many open bins -> prefer filling existing ones
    score += 0.6 * (open_bins_count as f64).powf(1.3) * (1.0 - progress);

    // mean residual coupling: bins far from mean residual get smooth penalty
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev * progress;

    // new-bin candidate: penalize opening a fresh bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 18.0 + 25.0 * (1.0 - progress) + 3.0 * mean_residual / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize by 10s (capacity fractions)
    let post_class = post_residual / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward when next item fits harmonically into post_residual class
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_class = (post_residual - next_item_size) / 10;
        score -= 6.0 - slack_class as f64 * 0.5;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize wasted potential
        score += 4.0;
