    // Modulo arithmetic on post_residual: dead-space classes
    let r = post_residual % 20;
    if r == 0 {
        score -= 3.0; // perfectly aligned residual, reusable
    } else if r >= 15 {
        score += 2.0; // awkward near-full residual
    } else if r >= 10 {
        score -= 1.0;
    }

    // Penalize very small post residuals (dead space) nonlinearly
    if post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 60.0 + fragmentation * 0.3 - progress * 5.0;
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 45.0; // no alternative
        }
    }

    // Tight fit reward
    if post_residual == 0 {
        score -= 7.0;
    }

    // Mild preference for fuller bins late in stream
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since with items >= 10 they are pure waste.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize leaving a residual that is awkwardly large but likely wasted:
    // residual in (9, 20) can only accept tiny items; mild penalty.
    if post_residual > 9 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer opening a new bin only when existing bins are
    // crowded (few alternatives) is bad; penalize new bin more when many bins fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 55.0 + 12.0 * pressure;
        // If the next item is large and this item is small, opening a fresh bin
        // is risky only if it wastes capacity; slight penalty relief when item is large.
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item does NOT fit in post-residual but would fit a fresh bin, penalize
    // slightly when post_residual is small (dead end).
    if next_item_size > post_residual as u32 && post_residual <= 15 && bin_residual != bin_capacity {
        score += 6.0;
    }

    // Mean-residual coupling: bins deviating far above the mean residual are less
    // attractive targets (their space is better saved for other items).
    if mean_residual > 0.0 {
        let dev = post_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += 0.15 * dev;
        } else {
            score += 0.05 * dev; // small reward for below-mean residual bins
        }
    }

    // Early in the stream, be slightly more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && post_residual > 0 && post_residual < 25 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a superlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Aggressive 2-step lookahead: strongly reward exact match of next item
    // into post_residual; penalize wasted potential if next item misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nr = post_residual as f64;
            let nxt = next_item_size as f64;
            // closeness of next item to post residual
            let closeness = 1.0 - (nr - nxt) / nr.max(1.0);
            score -= closeness * 10.0;
            // leftover after the next placement would be even tighter
            let post2 = post_residual - next_item_size;
            score -= (1.0 - post2 as f64 / bin_capacity as f64) * 5.0;
        } else {
            // next item cannot use the leftover: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += (waste / bin_capacity as f64) * 8.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual well below average wastes bin space elsewhere.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins
    // would leave large unusable dead space and the stream is early enough
    // that consolidation still matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = post_residual as f64; // = capacity - item_size
        let poor_fit = dead / bin_capacity as f64;
        if poor_fit > 0.55 && progress < 0.85 {
            score -= 6.0 * poor_fit;
        } else {
            score += 10.0; // discourage opening new bins by default
        }
        // late in the stream, prefer packing into existing bins
        score += progress * 8.0;
    }

    // Mild reward when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
