    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Reward leaving exactly the next item's size (perfect lookahead match).
    if post_residual == next_item_size && next_item_size > 0 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or the fit into open bins would be very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        // Penalize opening new bins when existing bins are underutilized.
        score += 12.0 * (1.0 - avg_fill);
        // Late in the stream, opening fresh bins is cheaper (fewer future items to waste).
        score -= 6.0 * progress;
        // If many bins already fit the item, a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 5.0 * (fitting_bins_count as f64 - 1.0);
        }
        // A new bin is fine if the item is huge (poor fit anywhere).
        if item_size > bin_capacity * 3 / 4 {
            score -= 4.0;
        }
    }

    // Slight preference for filling bins with larger residuals (balance load):
    // keeps small residuals from proliferating.
    score += 0.02 * (post_residual as f64 - mean_residual).abs();

    // Mild time-decay of tightness reward: early on, conserve space aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly warped by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Polynomial coupling of post_residual with progress:
    // small residuals get increasingly penalized late in the stream (dead space)
    let tightness = 1.0 - norm_pr;
    score += 12.0 * tightness * tightness * (0.5 + progress);

    // Reward near-perfect fits (post_residual small relative to capacity)
    score -= 6.0 * (1.0 - norm_pr * norm_pr).max(0.0) * (1.0 - progress);

    // Lookahead synergy: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 3.0 * progress;
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize wasted space proportionally
        score += 0.05 * pr.min(next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 5.0 * progress;
    }

    // Spread pressure: many open bins -> prefer consolidating into existing ones
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Mean residual coupling: bin far from mean residual gets mild penalty
    score += 0.1 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Tight-fit reward: scale score by capacity fraction filled
    score -= 8.0 * (1.0 - pr as f64 / cap);

    // Harmonic class of post_residual (base-10 classes on C=100):
    // residuals that are multiples of 10 pair well with the 10..80 item range
    if pr > 0 && pr % 10 == 0 {
        score -= 4.0;
    } else if pr > 0 && pr % 5 == 0 {
        score -= 1.5;
    }

    // Penalize tiny dead space (unusable slivers)
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    // Lookahead coupling: does the next item fit the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item exactly fills or leaves a multiple-of-10 class
            let leftover = pr - next_item_size;
            score -= 7.0;
            if leftover % 10 == 0 { score -= 3.0; }
        } else {
            score += 2.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate penalty: only open a new bin when nothing else fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * (1.0 - t);
    }

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (consolidating space into fewer, fuller bins)
    score += 0.06 * (mean_residual - pr as f64);

    // Progression: later in the stream, prioritize packing into existing bins
    score += 4.0 * t;

    // Slight penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
