pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: smaller post_residual is generally better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // 2-step lookahead: exact match between post_residual and next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            // next item still fits; reward proportional to leftover after that
            let second_left = post_residual - next_item_size;
            score -= 8.0 - (second_left as f64) * 0.1;
        } else {
            // next item can't use this residual: penalize dead space more
            // if residual is small (unusable) but less if large (reusable later)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
            if post_residual < 10 {
                score += 15.0; // tiny unusable sliver
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { (mean_residual / bin_capacity as f64).powi(2) } else { 0.0 };
        score = bin_capacity as f64 * 0.9 - fragmentation * 20.0;
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference toward fuller bins relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize residuals too small for the next item (dead space),
    // reward residuals that can still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item fits snugly too.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, softened when few bins open or mean residual is high (fragmented state).
        let mut new_bin_cost = 12.0;
        if open_bins_count > 0 {
            new_bin_cost += mean_residual * 0.3;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_cost += 10.0 * progress;
        // If no other bin fits, opening a new bin is inevitable-ish; reduce penalty.
        if fitting_bins_count == 0 {
            new_bin_cost *= 0.4;
        }
        score += new_bin_cost;
    } else {
        // Mild global pressure: with many open bins, favor using existing ones.
        score -= (open_bins_count as f64).ln() * 0.5;
    }

    // Penalize bins whose residual is far from the mean (outliers), keeping residuals uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 30.0 * norm_pr * norm_pr
        - 20.0 * norm_pr * norm_pr * norm_pr;

    // Reward near-perfect fits (small post residual) with smooth quadratic bonus
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (item_size as f64 / cap);

    // Coupling with stream progress: early on, tolerate waste; later, demand tight fits
    score *= 1.0 + 0.4 * (1.0 - progress) * norm_pr - 0.3 * progress * (1.0 - norm_pr);

    // Lookahead: if next item fits in post residual, reward this bin strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 10.0 * progress;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Dead space penalty grows with progress if next item cannot use leftover
        score += 8.0 * progress * (pr / 100.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening new bins early, penalize later
    if bin_residual == bin_capacity {
        score += 12.0 * progress - 6.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    // Residuals in the "dead zone" (very small, < 10) are penalized heavily.
    let dead = if post_residual < 10 { 60.0 } else { 0.0 };
    score += dead;

    // Modulo-10 harmonic class: residuals that are multiples of 10 are
    // "harmonious" with common item sizes -> reward them.
    let class = (post_residual % 10) as f64;
    score += 0.35 * class;

    // Integer-division threshold: which harmonic band does post_residual live in?
    let band = post_residual / 25; // 0..4
    score += match band {
        0 => 8.0,   // tiny leftover: nearly wasted bin
        1 => 0.0,   // sweet spot 25..49
        2 => 2.0,   // acceptable
        _ => 4.0,   // large leftover: bin was underfilled
    };

    // Lookahead: if the next item fits exactly or well into the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.25 * gap.min(40.0);
        if post_residual == next_item_size {
            score -= 10.0; // perfect chain
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 15.0;
    } else if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New-bin candidate: neutral-ish baseline. Prefer it only when existing bins
    // would leave large or dead residuals. Anchor at a moderate value.
    if bin_residual == bin_capacity {
        score = 55.0 - 0.15 * (open_bins_count as f64);
        // Late in the stream, be slightly more willing to consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * (1.0 - progress);
        return score;
    }

    // Mild pressure toward filling bins tightly as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * ((post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post-residuals are unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    }

    // Reward near-perfect fits (post_residual very small but >= 0 handled above).
    if post_residual == 0 {
        score -= 100.0; // perfect closure: huge reward
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else if slack < 10 {
            score += 15.0; // next item would leave dead space
        } else {
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless open-bin fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * open_bins_count as f64;
        // But if existing fits leave dead space, new bin becomes attractive:
        if post_residual >= 20 && mean_residual < item_size as f64 {
            score -= 55.0;
        }
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residuals close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * tightness;

    // Early stream: be slightly more willing to open bins to keep options open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 2.0;
        } else {
            // Next item will NOT fit: penalize large dead space that blocks it.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare post_residual against mean residual: prefer bins leaving
    // residuals in line with (or below) the average open residual.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would be very wasteful. Scale pressure with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = if next_item_size > 0 && post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += 400.0 - waste * 3.0 - progress * 100.0;
    }

    // Mild preference for filling fuller bins first.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect/near-perfect closure reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space penalty: small residuals that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward mid-range residual.
            let waste = post_residual as f64 - (post_residual as f64 - next_item_size as f64).max(0.0);
            if post_residual < next_item_size {
                score += 6.0;
            }
            let _ = waste;
        }
    } else {
        // Last item: strongly prefer closing bins out.
        score -= 40.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is a bad host.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0;
        // If many bins already open and mean residual is large, prefer reusing them.
        score += 0.3 * mean_residual;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If no open bin fits (this is the only candidate), opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins with residual close to the item (best-fit flavor) via absolute gap.
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs().sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 6.0 * fit_ratio * fit_ratio * (1.0 + 2.0 * prog_poly);
    score -= 4.0 * fit_ratio * (1.0 - fit_ratio) * prog_poly;

    // Penalize dead space relative to mean residual (non-linear)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + prog_poly);
    }

    // Lookahead: reward if next item fits in post residual (smooth coupling)
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * fits * (1.0 - gap * gap);
        score += 3.0 * (1.0 - fits) * fit_ratio * progress;
    }

    // Mild pressure against spreading across many open bins late in stream
    score += 0.05 * (open_bins_count as f64) * prog_poly * fit_ratio;

    // Slight bias toward tighter fits overall
    score -= 0.5 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near 0 (tight fit) are good.
    let cap: u32 = bin_capacity;
    let pr = post_residual;
    let tight_bonus = match pr {
        0 => 60.0,                       // perfect fill
        1..=5 => 40.0,
        6..=10 => 25.0,
        11..=15 => 12.0,
        _ => 0.0,
    };
    score -= tight_bonus;

    // Modulo classes on post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are more likely to be filled later.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
    }

    // Dead-space penalty: post-residual that no plausible small item (>=1)
    // can pair with is fine, but mid-range dead space (11..=19, 21..=24, 26..=29)
    // is awkward; penalize odd awkward bands.
    if pr >= 11 && pr <= 19 { score += 6.0; }
    if pr >= 26 && pr <= 29 { score += 4.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap as f64);
        } else {
            // next item cannot use this residual at all: mild penalty proportional to gap
            score += 3.0 + (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != cap {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item leaves a large residual anyway (small item) or few bins open.
    if bin_residual == cap {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins moderately; relax late in the stream when mean residual is high
        let mut nb = 25.0
            - 10.0 * progress
            - 0.5 * open_bins_count as f64
            + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size > item_size {
            // big item coming: fresh bin may serve it better
            nb -= 12.0;
        }
        score += nb.clamp(-5.0, 40.0);
    }

    // Prefer filling bins whose residual is below the mean (consolidating emptier space).
    if bin_residual != cap {
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: penalize tiny unusable gaps (1..=9).
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0
            + 6.0 * open_bins_count as f64
            + 0.5 * mean_residual.max(0.0);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open new bin
        }
        if post_residual < 20 {
            score += 30.0; // opening a bin for a big item wastes little
        }
    }

    // Mild pressure to consolidate into fewer bins.
    score -= 2.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residuals close to what remains (tight packing).
    score += 0.1 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // 2-step lookahead: perfect chain (item + next item fills bin exactly).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let chain_residual = post_residual - next_item_size;
            if chain_residual <= 5 {
                score -= 350.0;
            } else if chain_residual <= 15 {
                score -= 120.0;
            } else {
                score -= (post_residual as f64 - next_item_size as f64).sqrt() * 8.0;
            }
        } else {
            // Next item cannot follow here: penalize large leftover space.
            score += (next_item_size as f64 - post_residual as f64) * 3.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when good fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0;
        }
    }

    // Late-stream tightening: waste matters more as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fills.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 150.0;
    } else if post_residual < 20 {
        score -= 40.0;
    }

    // Dead-space penalty: leftover that next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.8 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    }

    // Last-chance bin: avoid opening a new bin if this fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0
            + 0.3 * mean_residual
            + 10.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Prefer fuller bins: reward small post_residual relative to capacity.
        score += 0.2 * (bin_capacity - bin_residual) as f64;
    }

    // Prefer bins whose residual is close to item size (tight fit).
    score += 0.6 * (bin_residual as f64 - item_size as f64).abs();

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins below mean residual (balance avoidance of waste).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;

    // Base: raw post residual (larger leftover = worse fit).
    let mut score = pr;

    // Smooth non-linear penalty on dead space: residual squared normalized.
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * cap;

    // Tight-fit reward: smooth bell around small post_residual.
    let tightness = (-pr_norm * 6.0).exp();
    score -= 25.0 * tightness;

    // Lookahead coupling: reward if next item fits smoothly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        let gap_norm = fit_gap / cap;
        score += 8.0 * gap_norm * gap_norm * cap;
        if pr >= nxt {
            score -= 10.0 * (-((pr - nxt) / cap) * 8.0).exp();
        }
    }

    // Stream progress coupling: late in stream, penalize wasting residual space more.
    let progress_coupling = 1.0 + 3.0 * progress * progress;
    score *= 0.5 + 0.5 * progress_coupling * (0.5 + 0.5 * pr_norm);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Slight preference for fewer open bins when residual is similar.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Mean residual alignment: prefer bins whose residual deviates smoothly from mean.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    // New-bin candidate: smooth adaptive penalty based on progress and item size.
    if bin_residual == bin_capacity {
        let new_bin_cost = 30.0 + 60.0 * progress + 0.4 * item;
        score = new_bin_cost + pr * 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes are more valuable (waste less capacity).
    // Classes keyed on post_residual / 10 (integer division thresholds).
    let class = post_residual / 10;
    let class_weight = match class {
        0 => -40.0,          // near-perfect fit
        1 => -28.0,
        2 => -18.0,
        3 => -10.0,
        4 => -4.0,
        5 => 2.0,
        6 => 8.0,
        7 => 14.0,
        8 => 20.0,
        9 => 26.0,
        _ => 32.0,           // large dead space (post_residual ~ capacity)
    };
    score += class_weight;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: penalize if the next item cannot use this bin's post-residual
    // (dead space confirmed), reward if it can.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.35 * next_item_size as f64;
        }
        // Harmonic coupling: next item divisible into the residual class
        if post_residual > 0 && next_item_size % post_residual.max(1) == 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current open
    // bins are nearly full on average and this placement wastes a lot.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: reusing an existing bin is usually better.
        score += 45.0;
        // But if open bins are crowded (low mean residual), opening is fine.
        score -= (100.0 - mean_residual).max(0.0) * 0.4;
        // Early in the stream, opening bins is cheap; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If no open bin could even be considered, relax slightly.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer filling bins that are already relatively full (tighter packing).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fullness;

    // Mild penalty for spreading across many bins when mean residual is high.
    if open_bins_count > 1 {
        score += 0.05 * open_bins_count as f64 * (mean_residual / 100.0);
    }

    // Modulo harmonic bonus: item divides capacity cleanly -> good fits.
    if bin_capacity % item_size.max(1) == 0 && post_residual < item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat residual < 10 (min item) as fully dead; residual in [1,30) as risky.
    if post_residual < 10 {
        score += 40.0; // completely unusable gap
    } else if post_residual < 30 {
        // partial dead space: smaller gap = worse
        score += 0.8 * (30.0 - post_residual as f64);
    }

    // Reward tight fits: the smaller the leftover relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: bonus if leftover exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leftovers that are just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 30 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 0.6 * open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Discourage opening new bins when open bins have plenty of room on average.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline = capacity minus item, plus penalty if open bins are roomy
        score += 15.0;
        if open_bins_count > 0 {
            score += 0.5 * mean_residual;
        }
        // late in the stream, opening a new bin is costlier
        score += 10.0 * progress;
    } else {
        // existing bin: slight reward relative to mean residual (below-mean residual = compact bin)
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        return -1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement is ideal (chain match).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits but leaves slack: mildly good.
    else if next_item_size > 0 && post_residual > next_item_size {
        score -= 50.0 + post_residual as f64 - next_item_size as f64;
    }
    // Next item does NOT fit in post residual: dead space unless residual is tiny.
    else if next_item_size > 0 {
        // Penalize wasted residual relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64) * 120.0;
        // If next item could have fit here had we chosen differently, extra penalty.
        if next_item_size <= bin_residual {
            score += 60.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Compare residual against mean residual across open bins.
    // Placing into a bin with residual near/below mean keeps bins balanced.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Prefer bins that are already fairly full (small residual) to consolidate.
    score += (bin_residual as f64 / bin_capacity as f64) * 40.0;

    // Late in stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    // New empty bin candidate: penalize opening a new bin unless it enables
    // a near-exact two-item pairing.
    if bin_residual == bin_capacity {
        let pair_waste = bin_capacity as f64 - item_size as f64 - next_item_size as f64;
        if next_item_size > 0 && pair_waste >= 0.0 && pair_waste <= 5.0 {
            score -= 250.0; // perfect pair with next item
        } else {
            score += 150.0; // discourage new bin generally
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * (0.5 + progress);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small dead space that likely nothing can use (waste zone).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else {
            // Penalize leaving a residual just below the next item's size (near-miss waste).
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > -10.0 && gap < 0.0 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are very full on average or many bins already fit the item.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        // Penalize new bins generally; discount when existing residuals are tiny.
        score += 18.0 * (1.0 - crowding) + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0; // fresh bin has full room for lookahead
        }
    }

    // Mild penalty when this bin's residual is far below the mean (fragmented bin).
    let frag = (mean_residual - bin_residual as f64).abs();
    score += 0.05 * frag;

    // Encourage consolidating into bins when many bins are open (reduce spread).
    if open_bins_count > 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: early on tolerate residual,
    // later become stricter (tight packing matters more as stream ends)
    let poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 30.0 * poly * norm_pr * (1.0 - norm_pr);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening new bins mildly,
    // more so early in the stream
    if bin_residual == bin_capacity {
        score += 40.0 - 25.0 * poly;
    }

    // Lookahead: reward if next item fits exactly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let tightness = 1.0 - ((pr - nxt) / cap).abs();
            score -= 25.0 * tightness * tightness;
        } else {
            score += 10.0;
        }
    }

    // Penalize bins far below mean residual (wasted space elsewhere)
    score += 0.2 * (mean_residual - pr).max(0.0);

    // Mild penalty for many open bins when post residual is large
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // classes (multiples of 10, or small enough to be near-full) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0; // residual is a harmonic multiple of 10
    } else {
        // penalize awkward residuals by distance to nearest multiple of 10
        let d = (pr % 10).min(10 - pr % 10) as f64;
        score += d * 1.5;
    }

    // Integer-division thresholds: classify residual into coarse buckets.
    let bucket = pr / 20; // 0..5
    score += match bucket {
        0 => -8.0,        // 0..19: nearly full bin, great
        1 => 0.0,
        2 => 4.0,
        3 => 9.0,
        _ => 14.0,        // large residual: wasteful use of this bin
    };

    // Coupling with next item: reward leaving exactly enough room for the
    // lookahead item (harmonic pairing), penalize just-missing it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 10.0;
            } else {
                score += slack as f64 * 0.3;
            }
        } else {
            // next item cannot fit here; residual becomes dead space
            let miss = next_item_size - post_residual;
            score += miss as f64 * 0.6;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when current
    // fit is terrible and plenty of stream remains.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress);
        // but discourage hoarding many open bins
        score += open_bins_count as f64 * 2.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Small item into a large residual bin: mild penalty to save big space.
    if (item_size as f64) < 0.35 * cap && (post_residual as f64) > 0.5 * cap {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable
        score -= 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Gap still usable by smallest items: mild reward
        score -= 5.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item would no longer fit anywhere comfortably
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * 4.0 * (item_size as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (better fit)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, tolerate opening new bins slightly more
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 3.0;

    // New-bin candidate: only attractive if item is large and no good fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0 + (item_size as f64) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward proportional to tightness of fit.
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // Penalize mismatch, scaled by how large the mismatch is.
            score += diff * 0.35;
        }
        // If next item fits the post-residual, mild bonus.
        if next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Tightness of current fit: small post_residual is generally good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Compare against mean residual: prefer bins that reduce spread.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is even less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Early stream: slight preference for consolidating into fewer bins.
    if open_bins_count > 0 && step_index < total_items / 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space left behind (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
        } else if post_residual > 0 {
            // leftover too small for the next item: penalize proportionally to waste
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // or this is a poor fit elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.5;
        if fitting_bins_count == 0 || (crowded && fit_ratio < 0.4) {
            score -= 20.0 + 10.0 * progress;
        } else {
            // discourage opening new bins when good fits exist
            score += 35.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild preference to balance residuals toward the mean across open bins.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Early-stream: be a bit greedy toward filling bins; late-stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual (waste) with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * x * x);

    // Smooth interaction: tight fits (small post residual) favored more as stream progresses
    let tightness = 1.0 - x; // 1 = perfect fit
    score -= 30.0 * progress * tightness * tightness;

    // Penalize large dead space late in stream (less time to fill it)
    score += 40.0 * progress * x * x * x;

    // Lookahead coupling: reward residuals that can fit the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = ((x - nx) / (nx + 0.05)).abs().min(1.0);
        score -= 12.0 * (1.0 - fit_next) * (1.0 + progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Mean residual coupling: prefer bins near mean residual (keeps bin population homogeneous)
    let dev = ((pr - mean_residual) / cap).abs();
    score += 10.0 * dev * dev;

    // Slight preference for filling fuller bins when many bins open
    score += 0.5 * open_bins_count as f64 * x;

    // New-bin candidate: penalize opening a new bin mildly, more early on
    if bin_residual == bin_capacity {
        score += 25.0 + 60.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals that are multiples of common item sizes (or near capacity fractions)
    // are valuable; prime-ish / tiny leftovers are dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0 // aligns with the 10-grid of typical sizes
    } else if pr % 5 == 0 {
        -6.0
    } else if pr < 10 {
        18.0 // unusable sliver
    } else if pr < 20 {
        8.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // leftover can serve the next item: reward, stronger if exactly fits
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 6.0 * (next_item_size as f64 - pr as f64) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would leave a badly fragmented residual and many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so open bins are normally preferred
        score += 30.0;
        // but if the best alternative leaves tiny dead space and we have
        // few open bins, opening fresh is fine: soften the penalty.
        if post_residual as f64 > 0.7 * cap {
            score -= 45.0;
        }
        if open_bins_count as f64 > 6.0 + 4.0 * (step_index as f64 / total_items.max(1) as f64) {
            score += 10.0; // too many open bins, don't spawn more
        }
    }

    // Prefer filling bins that are already relatively full (tight fits).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 8.0 * fill * fill;

    // Mild preference to keep mean residual spread tight.
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest future item
    // (assume min item ~1, but practically gaps below ~10 are hard to reuse).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 50.0;
    }

    // Penalize leaving a gap that the NEXT item cannot use (lookahead-aware dead space).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual >= next_item_size {
            // Reward leaving room for the lookahead item.
            score -= 5.0;
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 20.0 * (fill_ratio - 0.9) * 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; penalize slightly per extra open bin to avoid fragmentation.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity && post_residual < bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // If several bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count - 1) as f64;
        }
        // If the item fits snugly in the fresh bin and mean residual of open bins is low,
        // a new bin is more acceptable.
        let snug = (bin_capacity - item_size) as f64;
        if snug < 10.0 {
            score -= 10.0;
        }
        if mean_residual < 10.0 {
            score -= 10.0;
        }
    }

    // Mild stream-progression term: later in the stream, be slightly more conservative
    // about opening bins (wasted space matters more over long streams).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Alignment with mean residual: prefer bins whose resulting residual is near the
    // mean (keeps residual distribution tight and reusable).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / cap;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 35.0 * (1.0 - diff / cap).max(0.0);
        // Exact chain: this bin becomes perfectly filled by the next item
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving dead space that the next item cannot use
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Penalize bins far from the mean residual (prefer balancing or extreme fills)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    if bin_residual == bin_capacity {
        score += 20.0 - 0.2 * item_size as f64;
        // Opening a new bin is fine if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late in the stream, be more aggressive about closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    // Slight preference for filling larger residual bins when many bins are open
    score -= 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize large dead space, especially if next item can't use it
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.5 * post_residual as f64;
    }
    // Reward if next item fits into post residual (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.3 * next_item_size as f64;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 50.0 * fill_ratio * fill_ratio;

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New bin candidate handling: only attractive when fits are poor
    if bin_residual == bin_capacity {
        // Base new-bin cost; grows with number of open bins
        score = 60.0 + 2.0 * open_bins_count as f64;
        // If this bin is the only fit, opening new bin is bad
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // If item fits snugly somewhere, discourage new bin
        if fill_ratio > 0.7 {
            score += 100.0;
        }
        // Late in stream, discourage opening new bins slightly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins with residual far below mean (compact them), keep roomy bins for big items
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Mild penalty on very small post residual that is wasted (dead space below min item)
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex to punish dead space
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling with stream progress:
    // late in the stream, tight fits (small post_residual) matter more
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 30.0 * progress * tightness * tightness;

    // Perfect fit reward (smooth bump around post_residual == 0)
    score -= 25.0 * (-norm_pr * 6.0).exp();

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let nx = next_item_size as f64 / cap;
        let match_quality = 1.0 - ((pr - nx * cap) / cap).abs();
        score -= 20.0 * match_quality * match_quality;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item can't use this residual: penalize leaving large unusable gaps
        score += 8.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Crowding: many open bins -> prefer consolidating into fuller bins
    let crowding = (open_bins_count as f64 / 10.0).min(3.0);
    score += 3.0 * crowding * norm_pr;

    // Mean residual deviation: prefer bins near the mean (balanced packing)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize slightly unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 + 20.0 * avg_tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals landing in "usable" classes.
    // Class boundaries at multiples of 20 (capacity / 5): 0,20,40,60,80 are ideal anchors.
    let anchor_dist = {
        let m = post_residual % 20;
        let d = if m > 10 { 20 - m } else { m };
        d as f64
    };
    score += 1.5 * anchor_dist;

    // Reward exact hits of harmonic anchors (perfect future splits).
    if post_residual % 20 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 2.0;
    }

    // Dead space penalty: tiny unusable residuals (1..=9) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward when next placement also lands on an anchor
            let m = nxt_post % 20;
            let d = if m > 10 { 20 - m } else { m };
            score -= 6.0 - 0.5 * d as f64;
            if nxt_post < 10 && nxt_post > 0 {
                score += 8.0;
            }
        } else {
            // next item cannot fit here: residual becomes final; penalize waste
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: baseline slightly above good fits so we only open
    // a new bin when existing fits are poor (large residual waste).
    if bin_residual == bin_capacity {
        score = 55.0 - 0.2 * open_bins_count as f64;
        // If no open bin fits, opening is mandatory anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference to fill fuller bins (smaller residual before placement).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure loss.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space: penalize heavily
    } else if post_residual <= 20 {
        score += 10.0; // small gap, likely unusable soon
    } else {
        score -= 2.0; // usable residual is good
    }

    // Lookahead: reward residuals that can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad dead space.
    if bin_residual == bin_capacity {
        // Opening a new bin costs a base penalty; compare against dead space created here.
        let dead = post_residual as f64;
        score = 60.0 + dead * 0.2 - pressure * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins near the mean to keep balance.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 / (1.0 + gap / 10.0));
        // Exact match for next item is a strong win
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins tighter than the mean residual (good fits)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 {
            score -= 0.1 * next_item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that can't host the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.9 * (next_item_size as f64 - post_residual as f64);
        }
        // Reward residuals that exactly or nearly fit the lookahead item.
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 1.5 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Perfect closure bonus: bin exactly filled is always excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are large (fragmented) or the item is big relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins moderately; relax penalty as stream matures and fragments.
        score += 18.0 - 14.0 * fragmentation - 6.0 * progress;
        // Small items into a fresh bin waste capacity early on.
        score += 0.25 * (bin_capacity - item_size) as f64 * (1.0 - progress);
    } else {
        // Prefer bins with smaller residuals among open bins (best-fit flavor),
        // scaled by global mean residual to avoid over-tightening.
        score += 0.3 * ((mean_residual - bin_residual as f64).abs());
    }

    // Mild preference to spread load when many bins are open.
    score -= 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post_residual).
    let mut score = pr;

    // Smooth non-linear coupling: dead space penalty grows super-linearly
    // with wasted space, and grows with stream progress (late stream = less
    // tolerance for unusable leftovers).
    let waste = norm_pr * norm_pr;
    score += waste * cap * (0.5 + 1.5 * progress);

    // Reward filling a bin almost exactly (smooth bump near zero residual).
    score -= 20.0 * (1.0 - norm_pr).powi(6);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (smooth in fitting count).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 12.0 * (1.0 - gap / cap).powi(3);
        } else {
            score += 5.0 * (gap / cap);
        }
    }

    // Mild penalty for spreading across many bins when residuals are high.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate handling: brand-new bin has bin_residual == bin_capacity.
    // Its post_residual = capacity - item_size. Make the new bin attractive when
    // the item is large (leaves little dead space), unattractive for small items
    // when existing bins could hold it.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score -= 25.0 * fill * fill; // large items favor fresh bins
        score += 10.0 * (1.0 - fill); // small items slightly deter new bins
    }

    // Tie-break toward consolidating into bins with low mean residual
    // (bin nearly full relative to others) via smooth deviation term.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes mod 10.
    let post_class = post_residual % 10;
    let dead_penalty: f64 = match post_class {
        0 => -6.0,   // perfectly aligned residual, most reusable
        1 | 9 => 2.0,
        2 | 8 => 1.0,
        3 | 7 => 0.5,
        4 | 6 => 0.0,
        _ => 3.0,    // class 5: half-capacity dead zone, awkward
    };
    score += dead_penalty;

    // Integer-division thresholds on post_residual: which harmonic bands of items fit after.
    let band = post_residual / 10; // 0..10 usable bands
    let band_value = match band {
        0 => 25.0,               // nearly full bin, good (tight fit)
        1 => 5.0,
        2 => 2.0,
        3 | 4 => 0.0,
        5 | 6 => -1.0,           // mid residual is fine
        7 | 8 => 1.5,
        _ => 4.0,                // leaving >70 free is wasteful unless new bin
    };
    score += band_value;

    // Reward exact fill: item is a divisor-aligned fraction of capacity.
    if post_residual == 0 {
        score -= 30.0;
    } else if bin_capacity % post_residual == 0 {
        score -= 8.0; // residual is a harmonic fraction of capacity (e.g. 50, 25, 20, 10)
    }

    // Lookahead coupling: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's class aligns with residual class
            if next_item_size % 10 == post_class && post_residual > 0 {
                score -= 12.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item won't fit here; penalize leaving mid-sized residual
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins are tight
    // and the item is large relative to remaining capacity.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // avg fullness of open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > 0.6 * cap;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        } else if large_item && pressure < 0.35 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 40.0 + 20.0 * (1.0 - pressure); // default: avoid new bins
        }
    }

    // Mild penalty for spreading across too many open bins when residuals are fragmented.
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst waste.
    // Penalize post_residual that is too small to hold any plausible future item
    // (assume min useful slot ~10; anything below is dead space).
    let min_slot = 10.0f64;
    if (post_residual as f64) < min_slot && post_residual > 0 {
        score += (min_slot - post_residual as f64) * 12.0; // heavy dead-space penalty
    }

    // Reward tight fits: small (but usable) post_residual is excellent.
    if post_residual > 0 && post_residual <= 15 {
        score -= 8.0;
    } else if post_residual <= 30 {
        score -= 3.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    // existing bins and penalize opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; also slightly worse
        // late in the stream when consolidation matters.
        score += 25.0 + pressure * 6.0 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // But if no open bin gives a decent fit, new bin is fine: handled by
        // other bins getting dead-space penalties.
    } else {
        // Using an open bin is mildly rewarded under pressure.
        score -= pressure * 2.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward proportional to how well next item uses the gap
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Discourage leaving residuals far below the mean (fragmentation).
    if bin_residual < bin_capacity {
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score += dev * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Penalize post_residual that is just barely too small for next item
        if (post_residual as i64) < (next_item_size as i64) && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: minimize waste directly
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins that will end up tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual as i64 >= next_item_size as i64 {
            score -= 10.0; // fresh bin still useful for lookahead
        }
    }

    // Slight preference for fuller bins early vs late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Penalize creating dead space that no plausible future item can use.
    // Small residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well the next item would fill the leftover.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 10.0;
        } else {
            // Next item cannot use this bin's leftover: mild penalty for large leftovers.
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 20 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin when good options exist.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 60.0;
        // More open bins with slack -> cheaper to reuse, so keep new-bin penalty high.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // If no open bin fits (fitting_bins_count == 0 excluding new bin), allow opening.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid leaving many tiny open bins; prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Global state coupling: if mean residual across open bins is high, there is
    // plenty of slack overall -> prefer the bin that reduces fragmentation most
    // (i.e., tight fits). If mean residual is low, bins are nearly full, so
    // avoid dumping into nearly-full bins unless it's a great fit.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.05;

    // Prefer fuller bins slightly (fill existing bins before new space).
    score += (1.0 - bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mild penalty for each additional open bin to discourage bin proliferation
    // when spreading items across many bins.
    if open_bins_count > 4 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let g = progress * progress;
    // Dead-space penalty grows super-linearly with progress (tighten late)
    score += 18.0 * g * prn * prn * prn;
    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + 0.5 * progress);

    // Coupling with mean residual: prefer bins whose residual deviates favorably from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * dev; // penalize much-larger-than-mean residuals (wasteful bins)

    // Lookahead: if next item fits the post residual, big reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 15.0 * snug * snug;
    } else if next_item_size > 0 {
        // penalize leaving residual that next item cannot use, scaled by progress
        score += 8.0 * prn * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - prn);
    }

    // Many open bins: mild pressure to fill existing bins rather than spread
    score += 0.4 * (open_bins_count as f64).sqrt() * prn;

    // New-bin candidate: keep it competitive only when current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize dead space that no future item (10..80 typical, but 1..100 here) can use
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 500.0; // perfect fill
    }

    // Class A: post_residual is a multiple of capacity/4 -> "harmonic" residual, easy to fill later
    let quarter = bin_capacity / 4;
    let harmonic = post_residual % quarter == 0 && post_residual > 0;
    if harmonic { score -= 20.0; } else { score += 8.0; }

    // Integer division threshold classes on post_residual
    let cls = post_residual / 25; // 0..4 harmonic classes
    score += match cls {
        0 => 30.0,  // tiny residual: nearly full, great
        1 => 10.0,
        2 => 0.0,
        3 => -5.0,
        _ => 5.0,
    } as f64;

    // Lookahead: can next item fit into post_residual? Reward exact/near co-fit
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: mild penalty scaled by overflow
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 45.0;
        // if this bin is the ONLY fitting option, new bin is necessary
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // early in stream, more open bins -> prefer consolidation less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
        // if mean residual of open bins is small, they are nearly full -> new bin ok
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
    }

    // Slight preference for tighter bins when many are open
    score += 0.05 * open_bins_count as f64 * frac;

    // Coupling: penalize residual classes that rarely admit items (odd residues)
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, minimum item size)
    // are essentially unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps that only fit tiny items are semi-dead space.
        score += 25.0;
    }

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward tightness relative to bin capacity: fraction of bin filled.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Coupling: if the next item fits exactly into the post_residual,
    // this placement is excellent (chain fit) -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial reward if next item can still be accommodated.
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        // Leftover that the known next item cannot use: mild penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: when many bins are open, avoid opening new ones
    // (raise new-bin score, reward using existing bins).
    if bin_residual == bin_capacity {
        // New-bin candidate score: base cost + pressure from open bins.
        score = bin_capacity as f64 + 40.0 + 12.0 * open_bins_count as f64;
        // Late in the stream, new bins are even less desirable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If next item is large, a fresh bin is somewhat more attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin reduces fragmentation pressure slightly
        // when many bins are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Mild normalization against mean residual: prefer bins that are
    // already below-average residual (i.e., fuller than average).
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

