}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward high fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * 20.0;

    // Lookahead coupling: penalize residuals too small for the next item (dead space),
    // reward residuals that can still host the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post < n {
            score += (n - post) * 1.5;
        } else {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // but never treat the fresh-bin candidate as a last chance.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, less so for large items.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * fill;
    }

    // Time horizon: as the stream progresses, prefer consolidating into open bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= t * 5.0;
    }

    // Avoid consuming large residual space with small items.
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += slack * 0.05;

    // Global coupling: prefer bins whose post-residual sits near the mean residual
    // (keeps the open-bin pool homogeneous and reusable).
    score += (mean_residual - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with smooth non-linear shaping of dead space
    let mut score = pr + 8.0 * norm_pr * norm_pr * cap;

    // Progress coupling: later in stream, penalize large residuals more (waste matters more)
    let prog_sq = progress * progress;
    score += 20.0 * prog_sq * norm_pr * norm_item * cap;

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward if next item fits into post residual (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_deg = ((norm_pr - nxt) / cap).max(0.0);
        score -= 10.0 * (1.0 - fit_deg * cap) * nxt * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mean residual interaction: penalize bins whose residual deviates from mean
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 6.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it fall into?
    // Class 0: tiny slivers (<=10) are near-perfect closures -> big reward.
    // Class 1: 11..25 dead space -> penalize (hard to fill).
    // Class 2: 26..50 -> moderate.
    // Class 3: >50 -> large residual, still reusable.
    let post_class: u32 = if post_residual <= 10 { 0 }
        else if post_residual <= 25 { 1 }
        else if post_residual <= 50 { 2 }
        else { 3 };

    match post_class {
        0 => score -= 60.0 + 4.0 * (10 - post_residual) as f64, // perfect/near-perfect closure
        1 => score += 25.0 + (25 - post_residual) as f64 * 1.5, // awkward dead zone
        2 => score -= 5.0, // mildly ok
        _ => {} // large residual: neutral
    }

    // Exact fill is divine.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead harmony: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Next item fits: reward proportional to how snugly it nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * slack;
            if slack == 0.0 {
                score -= 120.0; // chain of perfect fits
            }
        } else {
            // Next item cannot use this residual: penalize more for mid-band residuals.
            let waste = (next_item_size as u32 - post_residual) as f64;
            score += 0.6 * waste;
        }
        // Harmonic divisibility: residual that is an integer multiple of a
        // plausible small item class (mod arithmetic on post_residual).
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 8.0; // residual aligned to common item granularity
        }
        if post_residual % 20 == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_class != 1 {
        score -= 35.0;
    } else if fitting_bins_count == 1 && post_class == 1 {
        score -= 10.0; // weak rescue of a bad-fit bin
    }

    // Prefer denser packing when many bins are open: compare residual to mean.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten up: discourage spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / cap);

    // New-bin candidate (empty bin): make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.3 * open_bins_count as f64;
        if post_class == 0 || post_residual == 0 {
            score -= 40.0; // but allow fresh bin if item exactly fills a bin
        }
    }

    // Small tie-breaker on item size: bigger items first into roomier bins.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (< 10, minimum item size)
    // are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits: leftover barely above the minimum item size is good.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 12.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let next_left = post_residual - next_item_size;
            if next_left < 10 {
                score += 20.0; // would create new dead space
            } else {
                score -= 8.0;
            }
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // with few open bins, opening a new bin (residual == capacity) is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; slightly worse early.
        score += 5.0 + 4.0 * pressure + 6.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    } else {
        // Existing bin: mild reward that grows with open-bin count.
        score -= 2.0 * pressure;
    }

    // Prefer bins whose residual is close to the item (relative tightness).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Slight penalty if this bin is far emptier than average (fragmentation).
    if (bin_residual as f64) > mean_residual * 1.5 && bin_residual != bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leftovers that are too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Reward tight fits relative to current mean residual.
    score -= 15.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).max(0.0));

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize unless current bin would leave very awkward waste.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 30.0; // next item could still chain in an existing bin
        }
    }

    // Prefer filling bins when many are open (consolidation pressure).
    score -= (open_bins_count as f64) * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Late in stream: value tightness more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for large leftover.
            score += 8.0;
        }
    }

    // Compare against mean residual: prefer bins that are more filled than average.
    let fill_gap = mean_residual - bin_residual as f64;
    score -= fill_gap * 0.5;

    // Penalize opening new bins when many open bins exist that could fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score += 55.0;
        // Opening is attractive only if the item is large and few bins fit it.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * large_item * large_item;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: post residual, slightly discounted by stream progress
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let t = progress;
    let poly = t * t - t + 0.5; // smooth convex bowl
    score += 8.0 * poly * (pr / cap) * (1.0 - fit_ratio);

    // Reward tight fits (small post_residual) with a smooth superlinear bonus
    let tight = 1.0 - (pr / cap);
    score -= 12.0 * tight * tight * tight * fit_ratio;

    // Penalize dead space that cannot fit the next item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = pr - next_ratio * cap;
        if gap > 0.0 {
            score += 0.05 * gap * gap / cap;
        } else {
            // Next item fits perfectly: reward
            score -= 6.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let open_norm = (open_bins_count as f64).ln1p();
    score += 0.5 * open_norm * (pr / cap) * (1.0 - t);

    // Mean residual coupling: prefer bins whose residual deviates smoothly from mean
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate handling: make empty bins moderately attractive only when
    // the item is large or no good fit exists
    if bin_residual == bin_capacity {
        let large = fit_ratio * fit_ratio;
        score = pr + 10.0 - 20.0 * large - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "usable" residue class (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post_residual;

    // Reward small post-residuals strongly (non-linear).
    score -= 30.0 * (-post / 40.0).exp();

    // Harmonic class bonus: post_residual divisible by small sizes (10..=20)
    // means the leftover is reusable by typical items.
    if pr > 0 {
        let mut harm: f64 = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                harm += 6.0;
            }
        }
        // Exact match with lookahead item size is ideal.
        if next_item_size > 0 && next_item_size == pr {
            harm += 25.0;
        } else if next_item_size > 0 && next_item_size <= pr {
            // Lookahead fits: mild reward scaled by tightness.
            harm += 8.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else if next_item_size > 0 && next_item_size > pr {
            // Lookahead cannot use this bin's leftover: penalize.
            harm -= 5.0;
        }
        score -= harm;
    }

    // Penalize dead space in the awkward zone (1..10) that nothing can use.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Capacity fraction classes: residual near half-capacity is flexible.
    let half = cap / 2.0;
    let frac = (post - half).abs();
    score -= 4.0 * (-frac / 25.0).exp();

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it attractive only when current bin would leave
    // large awkward leftovers or bin is nearly full anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // But if placing here would waste a lot (large post residual not
        // matching lookahead), opening fresh is fine.
        if next_item_size > 0 && pr > 0 && next_item_size > pr {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Late in the stream, prefer tight packing over opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post / cap);

    // Mean residual coupling: if open bins are generally roomy, discourage
    // spreading into this bin unless it's a good fit.
    if mean_residual > 40.0 && post > 40.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (or the lookahead item) are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item.max(1) {
        score -= 1000.0; // perfect fill, ideal
    } else if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space: gap too small for the next item is wasted capacity.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 35.0 + 0.5 * (post_residual as f64);
        }
        // Very small residual (< 10) is almost certainly dead space.
        if post_residual < 10 {
            score += 60.0;
        }
        // Reward tight fits: small positive residual is good, but only if
        // it can still be used (>= min item size).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 12.0 * tightness;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 250.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 90.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate implicitly).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when no open bin offers a decent fit, i.e. when the
    // mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        if mean_residual >= item_size as f64 {
            // Some open bin likely fits reasonably; discourage new bin.
            score += 45.0 + 0.3 * mean_residual;
        } else {
            // Open bins are nearly full; a new bin is justified.
            score -= 30.0;
        }
    } else {
        // Favor bins whose residual is close to the item (good utilization
        // relative to what's available).
        let fit_ratio = item_size as f64 / (bin_residual.max(1) as f64);
        score -= 20.0 * fit_ratio;
    }

    // Slight preference to keep residuals aligned with mean (balance bins).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted potential
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fill_ratio;

    // Penalize creating dead space below typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins with larger residuals (use emptier bins first)
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 150.0 + post_residual as f64;
    }

    // Late in stream: consolidate, prefer tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the next item cannot use.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating small unusable residuals (dead space below minimum item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer filling bins with larger-than-average residuals less; keep low-residual bins busy.
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Time horizon: early in the stream, be conservative (slightly favor new bins for balance);
    // late in the stream, aggressively close out open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Non-linear coupling of post_residual with stream progress:
    // early on, waste is cheap (bins are plentiful); late, waste is costly.
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score *= waste_weight;

    // Quadratic penalty on dead space relative to capacity, amplified by progress.
    let norm_post = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Lookahead: penalize residuals too small for the next item (potential dead space),
    // reward residuals that leave room for a follow-up item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if (post_residual as f64) < ns {
            score += 12.0 * (ns - post_residual as f64) / 100.0;
        } else {
            score -= 6.0 * (1.0 - ((post_residual as f64 - ns) / 100.0).abs());
        }
    }

    // Perfect fit bonus (smooth, non-linear).
    if post_residual == 0 {
        score -= 25.0 + 15.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 20.0 * progress;
    }

    // New-bin candidate: prefer it only when the current fit is poor and
    // many bins are open (consolidation pressure). Smooth logistic gate.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / 100.0).powi(2); // large post_residual => poor fit
        let gate = 1.0 / (1.0 + (-(open_bins_count as f64 - 6.0) / 3.0).exp());
        score = 55.0 - 45.0 * poor_fit * (1.0 - gate) + 20.0 * gate;
    }

    // Mild tie-break toward tighter bins (small residual before placement).
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in "hard" residue classes
    // is less reusable (items 1..100, so small residues are valuable).
    let pr = post_residual;
    if pr > 0 {
        // Residues in [1,10] are gold (tiny items can still land); reward heavily.
        if pr <= 10 {
            score -= 12.0;
        } else if pr <= 25 {
            score -= 4.0;
        }
        // Modulo classes: residues that are multiples of 5/10 align with common
        // item sizes and stay reusable.
        if pr % 10 == 0 {
            score -= 5.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        }
        // Odd, non-divisible residues are awkward: penalize mildly.
        if pr % 2 == 1 && pr % 5 != 0 {
            score += 3.0;
        }
    } else {
        // Perfect fill is the ideal outcome.
        score -= 40.0;
    }

    // Tightness: fraction of bin consumed by this placement.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr && (pr - next_item_size) <= 10 {
            score -= 10.0;
        } else if next_item_size > pr && next_item_size <= bin_residual {
            // Next item would prefer this bin's current residual; leaving it
            // untouched may be better - penalize stealing that space.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity and open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - cap).abs() / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 25.0 + 10.0 * progress;
        if item_size as f64 / cap >= 0.7 {
            new_bin_score -= 20.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 50.0; // no alternative: new bin mandatory anyway
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 + 15.0 {
            new_bin_score += 10.0; // open bins have room; discourage new bin
        }
        score += new_bin_score;
    }

    // Slight preference for fuller bins overall (best-fit core).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps that no future item
    // (sizes >= 1) can use well are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: nearly wasted capacity.
        score += 60.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Gap too small for the known next item: likely dead space.
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are congested or this
    // bin's residual would leave a bad gap anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0
            + 4.0 * open_bins_count as f64
            - 15.0 * progress
            - 0.3 * mean_residual;
        // If the next item is large and current residuals are small, new bin is fine.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins when residuals
    // are already low on average.
    score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Mild lookahead coupling: prefer bins whose post_residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits here afterwards: reward closeness to exact match
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize proportionally
            score += 25.0 + 0.5 * diff;
        }
        // Exact 2-step match is gold.
        if post_residual == next_item_size {
            score -= 120.0;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize creating small unusable dead space (1..10) relative to item range.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward placing into bins with below-mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: prefer it only when no good fit exists.
    if bin_residual == bin_capacity {
        score = 150.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
        if fitting_bins_count == 1 {
            score += 200.0; // never open new bin when this is last chance
        }
    }

    // Late in stream: consolidate, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Penalize dead space that no typical item can use.
    // Items range 1..100; residual smaller than the minimum plausible item is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small leftover is fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual < 30 {
        // medium dead space: penalize more as it becomes less usable
        score += 4.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * bin_residual as f64;
    }

    // New-bin candidate handling: empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; tuned relative to wasted-space scale
        score += 55.0;
        // cheaper to open new bins early in the stream (more future items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // fewer open bins => new bin less costly to manage
        score -= 2.0 * (open_bins_count as f64).min(10.0);
    } else {
        // Prefer bins with lower residual already (best-fit flavor), scaled by global mean.
        score += 0.05 * (bin_residual as f64 - mean_residual);
        // Slight preference for reducing number of open bins by filling existing ones.
        score -= 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Time-horizon coupling: late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual (waste minimization)
    let mut score = pr;

    // Non-linear polynomial coupling: residual^2 normalized, modulated by progress
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);

    // Tight fits reward: smooth cubic of (1 - norm_pr)
    let tight = (1.0 - norm_pr).max(0.0);
    score -= 60.0 * tight * tight * tight;

    // Dead-space penalty: residual too small for smallest plausible item (smooth softplus-like)
    let small_gap = ((20.0 - pr) / 20.0).max(0.0);
    score += 30.0 * small_gap * small_gap;

    // Lookahead coupling: if next item fits post residual, reward
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_frac = next_item_size as f64 / cap;
        score -= 25.0 * fit_frac * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty growing with progress
        score += 10.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Dispersion from mean residual: prefer bins near mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate handling: empty bin gets neutral-ish score with progress-dependent cost
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score = cap * (1.2 + progress); // force using the lone fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which capacity fraction band does it fall into?
    // Classes: [0..10) perfect, [10..25) good, [25..50) mediocre, [50..100) wasteful.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -40.0 // perfect fit: strongly reward
    } else if pr <= 10 {
        -15.0
    } else if pr <= 25 {
        0.0
    } else if pr <= 50 {
        10.0
    } else {
        25.0
    };
    score += class_penalty;

    // Modular harmonic: residual divisible by common item sizes is reusable.
    if pr > 0 {
        let mut reusable = false;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                reusable = true;
                break;
            }
        }
        if reusable {
            score -= 8.0;
        }
        // Non-reusable odd residues get a mild penalty scaled by size.
        if pr % 5 != 0 {
            score += (pr as f64) * 0.05;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // Reward proportionally to how well next item fills the leftover.
            let fill = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 10.0 * fill;
        } else {
            // Next item cannot use this leftover: penalize large dead space.
            score += (pr as f64) * 0.10;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin, more so early in the stream
    // and when many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If truly nothing fits elsewhere, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (tighter bins get packed first, keeping loose bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual as f64;

    // ---- Strict dead-space avoidance ----
    // Perfect fill: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Lookahead coupling: exact match with next item -> near-perfect plan.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            score -= 25.0;
        } else if post_residual > 0 && pr < nxt {
            // Gap exists but cannot hold the lookahead item: unusable dead space.
            score += 10.0 + 0.3 * pr;
        }
    }
    // Tiny residual gaps are statistically unlikely to be usable (items 1..100,
    // but small slivers accumulate fragmentation): penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    if is_new_bin {
        // ---- Open-bins pressure: opening a bin when many are already open
        // fragments the packing; make the fresh-bin candidate progressively
        // less attractive. Base score is already 100 (full residual).
        score += 20.0 + 1.5 * open_bins_count as f64;
    } else {
        // Reward using existing bins, more urgently as the open set grows.
        score -= 0.5 * open_bins_count as f64;
        // Last-chance bin: if this is the only bin that fits, avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer tighter-than-average bins (keeps large residuals pooled
        // for future large items).
        let tightness = (mean_residual - bin_residual as f64).max(0.0);
        score -= 0.05 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter residual is better (already in score via post_residual).

    // Aggressive 2-step lookahead: reward perfect match between post_residual
    // and the next item's size (bin becomes exactly usable again).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 25.0; // exact 2-step chain: post_residual == next_item_size
        } else {
            // Penalize residuals that cannot host the next item but are too
            // large to be considered "dead" (wasted middle-ground space).
            let can_host_next = post_residual >= next_item_size;
            if can_host_next {
                // Mild reward proportional to how much of the next item fits.
                score -= 4.0 * (next_item_size as f64 / post_residual as f64);
            } else {
                // Dead space: post_residual < next_item_size and post_residual
                // is small enough that nothing useful fits later.
                let dead = post_residual as f64;
                if dead < 10.0 {
                    score += 2.0 * dead; // tiny crumbs are nearly unusable
                } else {
                    score += 0.5 * dead;
                }
            }
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin far below the mean creates an outlier residual that
    // is hard to fill; leaving it near the mean keeps the bin portfolio balanced.
    let pr = post_residual as f64;
    let deviation = (pr - mean_residual).abs();
    score += 0.15 * deviation;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means a fresh bin.
    // Prefer it only when existing bins would leave terrible residuals, i.e.
    // when the item nearly fills an empty bin and no good match exists.
    if bin_residual == bin_capacity {
        // Neutral baseline for a new bin; add a mild penalty so we only open
        // a new bin when open bins score worse through dead-space penalties.
        score += 6.0;
        // If the item is large relative to capacity, a fresh bin wastes little.
        if (item_size as f64) / (bin_capacity as f64) > 0.7 {
            score -= 8.0;
        }
        // Early in the stream with few open bins, opening is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.1 && open_bins_count < 3 {
            score -= 5.0;
        }
    }

    // Slight reward for very tight placements overall.
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small dead space is fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual <= 80 {
        // residual in the item range is reusable; mild reward scaled by reusability
        score -= 3.0 * (post_residual as f64 / 80.0);
    } else if post_residual > 80 {
        score += 2.0; // huge leftover suggests item was tiny; slight penalty
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to overflow
            score += 1.5 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 20.0;
        // Cheaper to open new bins late in the stream (fewer future items to serve).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If many bins are open with scattered residuals, consolidation is better.
        score += 0.3 * open_bins_count as f64;
        // If mean residual across open bins is large, prefer using them.
        score += 0.15 * mean_residual;
    } else {
        // Reward using existing bins, more so when open-bin count is high.
        score -= 0.1 * open_bins_count as f64;
        // Prefer bins with residuals close to the item (best-fit style refinement).
        let gap = (bin_residual - item_size) as f64;
        score += 0.05 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Base: quadratic dead-space penalty (convex in post residual)
    let mut score = pr * (1.0 + 0.9 * x * x);

    // Smooth progress coupling: later in the stream, residual waste matters more
    let late = progress * progress;
    score *= 1.0 + 0.6 * late * x;

    // Reward tight fits: subtract a smooth bump centered at small residuals
    let tight = (-4.0 * x).exp();
    score -= 12.0 * tight * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: penalize if the next item can't use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 8.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 5.0 * (pr - nxt) / cap;
        }
    }

    // Slight preference for bins with residuals near the mean (keeps spread uniform)
    score += 0.15 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue modulo 10 defines "dead space quality"
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residue = post_residual % 10;

    // Residues near multiples of 10 are more reusable (items are multiples of 10 often);
    // penalize awkward residues (1..9 away from a decade boundary).
    let residue_penalty = match residue {
        0 => -6.0,
        1 | 9 => 2.0,
        2 | 8 => 4.0,
        3 | 7 => 6.5,
        4 | 6 => 9.0,
        _ => 11.0,
    };
    score += residue_penalty * (1.0 + post / cap);

    // Small post-residuals are excellent (tight fit): reward quadratically.
    if post_residual <= 10 {
        score -= 18.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // Harmonic compatibility: does next item land on a good residue too?
            let next_post = post_residual - next_item_size;
            let next_res_class = match next_post % 10 {
                0 => 0.0,
                1 | 9 => 3.0,
                2 | 8 => 5.0,
                3 | 7 => 7.0,
                4 | 6 => 9.0,
                _ => 11.0,
            };
            score -= 12.0 * (nxt / cap) - next_res_class * 0.4;
        } else {
            // Next item cannot use the leftover: mild penalty proportional to slack mismatch
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
        // Extra protection when the fit is decent (post_residual small)
        if post_residual <= 25 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented
    // or the fit in open bins would be bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Cheaper to open new bins early in the stream (more future items to amortize)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If many open bins already, opening another fragments capacity more
        score += 1.5 * open_bins_count as f64;
        // If mean residual across open bins is large, open bins are reusable; discourage new bin
        score += 0.35 * mean_residual;
        // If next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 12.0;
        }
    } else {
        // Slight preference for using more-open bins when their residual is large
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Fractional capacity coupling: reward placing items into bins whose residual
    // is in the same "harmonic class" (same decade) as the item.
    let item_dec = item_size / 10;
    let resid_dec = bin_residual / 10;
    if item_dec == resid_dec && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else {
        // Large usable residuals are mildly attractive.
        score -= 2.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins are
    // fragmented (high open count, low mean residual) or post fit is bad.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a bin; grows with open bin pressure.
        score += 10.0 + (open_bins_count as f64) * 0.5;
        if post_residual >= 60 {
            score -= 8.0; // roomy new bin fine when others are tight
        }
    } else {
        // Reusing an open bin reduces bin count: reward.
        score -= 5.0;
        // Reward tighter average bins (using fragmented space well).
        score -= (mean_residual - post_residual as f64).max(-20.0).min(20.0) * 0.1;
    }

    // Lookahead (k=2): bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here: post residual becomes dead space
            // for the immediate future; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins since amortization window shrinks.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect packing (small post_residual).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = (post_residual - next_item_size) as f64;
        score -= 15.0 + 20.0 / (1.0 + lookahead_gap);
        if lookahead_gap <= 5.0 {
            score -= 20.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post_residual likely dead space relative to the next item.
        score += (post_residual as f64) * 0.3;
        // But if post_residual is tiny, it's fine (bin nearly full).
        if post_residual <= 10 {
            score -= 5.0;
        }
    }

    // Compare post_residual against mean residual: keep residuals balanced/low.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        score += 35.0 + 10.0 * (1.0 - progress) - 0.5 * pressure;
        // A new bin is only attractive if no open bin fits well (large post_residual everywhere).
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild penalty for very large dead space that nothing can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful later (non-linear).
    if post_residual > 0 {
        let dead = 100.0 / (post_residual as f64).powf(1.4);
        score += dead * 0.15;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_residual as f64) * 25.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect coupling with lookahead
            let coupling = 1.0 - ((post_residual - next_item_size) as f64 / 100.0);
            score -= 20.0 * coupling;
        } else {
            // next item won't fit here; slight penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // New-bin candidate: prefer only when fits are poor or many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_gap = (mean_residual - item_size as f64).abs();
        let reluctance = 60.0 + 40.0 * progress + avg_fit_gap * 0.3 + open_bins_count as f64 * 2.0;
        score += reluctance;
    }

    // Global state: when mean residual is high, prefer bins consuming it.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Time-horizon modulation: early stream, be conservative (favor new bins less);
    // late stream, squeeze into existing bins more aggressively.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= horizon * 8.0 * (1.0 - post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear waste penalty: small residuals are dead space.
    let norm_pr = pr / cap;
    score += 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins moderately; later, demand tighter fits.
    let tightness = (cap - pr) / cap; // fraction of bin used after placement
    let progress_coupling = 60.0 * progress * (0.5 - tightness) * (0.5 - tightness);
    score += progress_coupling;

    // Reward if next item fits exactly into post_residual (perfect lookahead pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            score -= 30.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 10.0 * (gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0 * (1.0 + progress);
    }

    // Mild preference for bins with below-average residual (consolidate emptier bins).
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // (large items leave useful residuals in fresh bins).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 55.0 * (1.0 - item_frac) * (1.0 - item_frac) - 20.0 * item_frac;
    }

    // Slight openness pressure: with many open bins, favor existing bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable, so reward them.
    if post_residual > 0 {
        let mut bonus = 0.0;
        if post_residual % 10 == 0 { bonus += 6.0; }
        if post_residual % 20 == 0 { bonus += 4.0; }
        if post_residual % 25 == 0 { bonus += 4.0; }
        if post_residual % 50 == 0 { bonus += 8.0; }
        score -= bonus;

        // Dead-space penalty: small awkward residuals (1..9) are near-useless.
        if post_residual < 10 {
            score += 25.0;
        } else {
            // Fraction-of-capacity class penalty: mid-range residuals in
            // awkward bands are less useful than large residuals.
            let frac = post_residual as f64 / bin_capacity as f64;
            if frac < 0.25 { score += 8.0; }
            else if frac < 0.5 { score += 3.0; }
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    // (harmonic chain), penalize if next item almost fits (wasted opportunity).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 { score -= 10.0; }
            else if slack % 10 == 0 { score -= 6.0; }
        } else {
            // Next item cannot fit here; slight penalty for tight residuals.
            if post_residual > 0 && post_residual < 20 { score += 6.0; }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer packing into existing bins when many are open (avoid fragmentation).
    score -= (open_bins_count as f64) * 0.4;

    // New-bin candidate handling: make a fresh bin mildly attractive only for
    // large items or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size > bin_capacity / 2;
        if large_item || progress < 0.15 || mean_residual < item_size as f64 * 0.6 {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // Mild trend adjustment: later in the stream, tighten packing (favor low
    // post_residual more aggressively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // Dead space that can't fit even the smallest item is pure waste.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 40 {
            score += 8.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: post_residual becomes dead space.
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score -= pressure;

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin has residual = capacity, so post_residual is huge;
        // add a moderate penalty so it's chosen only when alternatives are bad.
        score += 45.0 + (open_bins_count as f64).min(10.0) * 2.0;
        // Early in stream, opening new bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Slight preference for bins with residuals close to mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match reward: leftover exactly fits the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight match to next item (subtracted heavily when diff small).
        score -= 45.0 / (1.0 + diff);
        // Penalize leftover that is smaller than next item (dead space for lookahead).
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals far above the mean (wasteful bins) but reward near-mean tightness.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Mild penalty for opening a new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0;
    }

    // Prefer filling bins tighter as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fit_ratio;

    // Penalize large dead space relative to typical item size
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny slivers are useless
    }

    // Last-chance bin: strongly favor if this is the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin if no open bin fits well, or lookahead won't fit anywhere
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let mut nb = 40.0;
        if pressure > 0.0 {
            nb -= 300.0;
        }
        if next_item_size > 0 && !lookahead_fits {
            nb -= 50.0;
        }
        // Early in stream: opening bins is cheap; late: consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += 80.0 * progress;
        // Many open bins with high mean residual: avoid opening more
        if mean_residual > item_size as f64 {
            nb += 60.0;
        }
        score += nb;
    } else {
        // Lookahead synergy: reward leaving space for the next item
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 150.0; // sets up a perfect fit next step
            } else if next_item_size < post_residual {
                score -= 20.0 * (next_item_size as f64 / post_residual as f64);
            } else {
                score += 15.0; // next item won't fit here; keep other bins flexible
            }
        }
        // Prefer bins with below-average residual (conserving large residuals)
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
        // Late stream: penalize leaving any residual harder
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear penalty for residual size (quadratic dead-space growth)
    score += 0.35 * (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - (pr / (item_size.max(1) as f64 + pr));
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        let match_q = 1.0 - gap / cap;
        score -= 14.0 * match_q * match_q;
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize proportionally to wasted space
        score += 6.0 * (pr / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 22.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins below mean residual (consolidate emptier space usage)
    score += 0.12 * (pr - mean_residual);

    // New-bin candidate: penalize mildly early, more as stream progresses unless
    // all fits are poor (large pr across open bins)
    if bin_residual == bin_capacity {
        let avg_fit_quality = mean_residual / cap;
        let escape_bonus = 25.0 * avg_fit_quality * avg_fit_quality;
        score = cap + 30.0 * (1.0 - progress) - escape_bonus;
    }

    // Smooth stream-progress coupling: later in stream, tighten more aggressively
    score -= 8.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and small residues
    // that pair with common item sizes are valuable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 35 {
        score += 10.0;
    } else {
        score += 25.0;
    }

    // Modulo-10 harmonic class: dead space congruent to values that many
    // item sizes (multiples of 5/10) can fill is less dead.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 15.0;
    } else if r10 == 5 {
        score -= 8.0;
    } else {
        score += (r10 as f64) * 1.5;
    }

    // Reward if next item exactly fits the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // next item cannot use this bin's residue: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when few bins fit or
    // residual is large (avoid fragmenting many open bins unnecessarily).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score -= 40.0 + scarcity - (open_bins_count as f64) * 2.0;
    } else {
        // Penalize spreading across too many open bins.
        score += (open_bins_count as f64) * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin — slightly deprioritize; tight bins favored.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Progress: late in stream, prefer tighter packing (larger residuals worse).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // even the smallest plausible item (<= 12) are pure waste.
    if post_residual > 0 && post_residual < 12 {
        score += 30.0 + (12 - post_residual) as f64 * 4.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Lookahead: reward if the post residual can still host the next item,
    // penalize if it blocks it (but not if next is unknown).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless
    // the placement is genuinely tight; encourage consolidation early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * (1.0 + 2.0 * (1.0 - progress)) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keep the pool homogeneous), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: it should only win when all open bins fit poorly.
    // Penalize the empty-bin candidate mildly, harder late in the stream
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 10.0 + 8.0 * progress + 0.6 * (open_bins_count as f64);
        score += new_bin_penalty;
        // But if the item is huge and no open bin fits well, allow new bin.
        if fill > 0.6 && open_bins_count > 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain two perfect placements
        } else if post_residual >= next_item_size {
            // next item fits: small bonus proportional to slack quality
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item will NOT fit here: penalize leaving dead space
            let dead = post_residual as f64;
            score += 1.5 * dead;
            // extra penalty if dead space is tiny (unusable fragment)
            if dead < 10.0 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 250.0;
        // but if open bins have small residuals (poor fits anyway), opening is fine
        if open_bins_count > 0 && mean_residual < 20.0 {
            score -= 200.0;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * (1.0 - progress);
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight preference to use more-opened bins (close them out sooner).
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: penalize if next item no longer fits this bin after placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps chain-placements viable
        } else {
            score += 6.0; // dead space for the known next item
            // partial credit if next item nearly fits
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a very full bin's remaining space on a small item
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.35 && bin_residual < bin_capacity {
        score += 10.0 * (0.35 - fill_ratio);
    }

    // Early in stream: be greedy with new bins is fine; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins open
        score += 12.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
        // Opening a new bin is acceptable if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Favor bins with below-average residual (fill emptier bins first)
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: residual after placement (tighter fit = lower score).
    let mut score = pr;

    // Smooth non-linear coupling: normalized residual^2 penalizes large dead space,
    // weighted by stream progress (late in stream, dead space hurts more).
    let norm_pr = pr / cap;
    score += progress * cap * norm_pr * norm_pr;

    // Cubic interaction between post_residual and mean residual: placing into a bin
    // whose residual stays close to the mean is mildly preferred (keeps balance).
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 25.0 * fits_next * (1.0 - gap / cap).max(0.0) * (0.5 + progress);
    }

    // New-bin candidate handling: opening a new bin is penalized early (consolidate),
    // but becomes acceptable late in the stream or when the fit is very tight.
    if is_new_bin {
        let tightness = 1.0 - norm_pr; // 1.0 when item nearly fills the new bin
        score += 20.0 * (1.0 - progress) * (1.0 - progress) * (1.0 - tightness);
        score -= 15.0 * tightness * tightness * (0.5 + progress);
    }

    // Reward using existing bins over opening new ones, scaled by open bin count.
    if !is_new_bin {
        score -= 5.0 * (open_bins_count.min(20) as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Harmonic class of post_residual: dead space in small remainders is worse
    // Class the residual by integer division thresholds (capacity fractions)
    let class = post_residual / (bin_capacity / 4); // 0..=4 harmonic class
    score += match class {
        0 => -15.0, // near-perfect fit, strongly reward
        1 => -5.0,  // residual <= 25, still usable for small items
        2 => 3.0,   // residual <= 50, moderate
        3 => 8.0,   // residual <= 75, poor
        _ => 12.0,  // large waste
    };

    // Modulo arithmetic on residual: residuals divisible by small sizes are reusable
    if post_residual > 0 {
        let m = post_residual % 10;
        if m == 0 {
            score -= 6.0; // clean residual, likely to match future items
        } else if m >= 7 {
            score += 4.0; // awkward sliver
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual - next_item_size) as f64;
        score -= 25.0 - exact * 0.3;
        // Harmonic bonus if next item leaves another clean residual
        if exact as u32 % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item can't use this residual: penalize wasted space proportionally
        score += (post_residual as f64).min(next_item_size as f64) * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline; only open
    // a new bin when existing fits are bad or lookahead demands it
    if bin_residual == bin_capacity {
        score = 60.0
            + fit_ratio * 0.0
            + (open_bins_count as f64) * 0.5
            - (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening fresh is fine if next item is large
            score -= (next_item_size as f64) * 0.1;
        }
        if step_index as f64 / (total_items.max(1) as f64) > 0.9 {
            score += 5.0; // late stream: consolidate rather than open
        }
    }

    // Mean residual coupling: when open bins are already slack, avoid adding slack
    if bin_residual < bin_capacity {
        score += (mean_residual - post_residual as f64) * 0.05;
    }

    // Progress modulation: early stream, be picky about fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A post_residual that is too small to hold even the smallest item (1)
    // is pure waste; a post_residual below next_item_size is dead for the lookahead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver of space
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // dead space relative to the lookahead item
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // bin remains useful for the next item
    }

    // Reward tight fits (small post_residual overall) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Open-bins pressure: discourage scattering across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when existing bins would
    // leave bad dead space or are nearly full anyway.
    if bin_residual == bin_capacity {
        // Slight inherent cost of opening a new bin, offset if current
        // mean residual is low (existing bins nearly exhausted).
        score = 20.0 - mean_residual * 0.5 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin is valuable
        }
        if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the only usable bin lightly
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to 0 is best.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size (chained exact packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 45.0;
        } else if diff <= 5 {
            score -= 20.0;
        } else if diff <= 15 {
            score -= 6.0;
        } else {
            // Post-residual too large relative to next item: penalize
            // leaving awkward space that no near-future item will use.
            score += (diff as f64 - 15.0).min(25.0) * 0.3;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins
    // are badly fragmented (high mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0
            - (mean_residual / bin_capacity as f64) * 30.0
            - progress * 10.0;
    }

    // Tie-break: prefer fuller bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base best-fit: strongly prefer tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual is reusable by next item: reward proportionally.
            score -= 1.5 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Residual becomes dead space for the lookahead item.
            let waste = post_residual as f64 - (next_item_size as f64 * (post_residual as f64 / bin_capacity as f64));
            score += 0.8 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 6.0;
        // Extra weight late in the stream when opening bins is costly.
        score -= 4.0 * progress;
    }

    // New-bin candidate: empty bin should only win when the item is large
    // or no open bin fits well. Penalize opening new bins by default.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If item is big relative to capacity, new bin is more acceptable.
        score -= 6.0 * (item_size as f64 / bin_capacity as f64);
        // Late in stream, prefer reusing open bins.
        score += 8.0 * progress;
        // Many open bins: discourage yet another one.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // bins below mean residual are already tight, keep filling them.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Mild preference for bins with small post-residual unusable slivers
    // (sliver = residual too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * (1.0 - progress);
    score += 6.0 * poly;

    // Reward tight fits, smoothly scaled by progress
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64)) * (1.0 + progress);
    } else if next_item_size > 0 {
        score -= 2.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild penalty for new-bin candidate when open bins are plentiful
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mean residual alignment term
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into capacity fractions
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;

    // Dead-space penalty by class: residuals <=10 are near-useless (min item is 10 classically, but sizes go to 1)
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= quarter {
        score += 15.0;
    } else if post_residual <= half {
        score += 5.0;
    }

    // Reward residuals that exactly match harmonic slots for next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 {
                score -= 30.0; // next item fills this bin nearly perfectly
            } else {
                score -= (20.0 * (1.0 - leftover as f64 / cap)).max(0.0);
            }
        } else {
            // next item cannot fit here; penalize proportionally to how badly it misses
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Integer-division threshold coupling: residual class via division into eighths
    let class = post_residual / (bin_capacity / 8).max(1);
    score += class as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are poor
    if bin_residual == bin_capacity {
        // neutral-ish base, adjusted by stream progression and open bins
        score = cap * 0.6 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // later in stream, slightly discourage hoarding new bins
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mild preference for tighter bins overall
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1..100
    // but typical small items ~10) are wasted; penalize the "unusable gap" zone hard.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 35.0; // unusable sliver
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill is ideal
    }

    // Penalize gaps that can't fit the known next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward gaps that exactly fit the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins, encourage filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when nothing fits well,
        // penalized when open bins are plentiful or residual is large.
        score += 30.0 + 2.0 * open_bins_count as f64 + 25.0 * progress;
        // If current bin would leave a dead gap, opening fresh is fine.
        if post_residual > 0 && post_residual < dead_threshold {
            score -= 40.0;
        }
    } else {
        // Reusing an open bin reduces bin count: reward.
        score -= 1.5 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins whose residual is already small
    // (concentrate waste) rather than spreading it.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let residual_f = bin_residual as f64;
    let item_f = item_size as f64;
    let post_f = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_err = (post_f - nxt).abs();
        // Perfect chain: this bin's leftover exactly feeds the next item.
        if match_err == 0.0 {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if post_f >= nxt {
            // Next item can still fit here later; reward proportional closeness.
            let closeness = 1.0 - (match_err / 100.0);
            score -= 25.0 * closeness * closeness;
        } else {
            // Dead space relative to next item: penalize unusable remainder.
            score += 15.0 * (1.0 - post_f / nxt);
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful leftover).
    score += 0.5 * (post_f - mean_residual).max(0.0);

    // Penalize tiny unusable slivers (< 10) harder as stream progresses.
    if post_f > 0.0 && post_f < 10.0 {
        score += 20.0 + 30.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins (small residual before placement) among fitting bins.
    score += 0.3 * (residual_f - item_f);

    // New-bin candidate: default cost; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 55.0 + 25.0 * (1.0 - progress);
        // If next item is huge, a fresh bin is more attractive (keep space flexible).
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Slight preference to keep many open bins consolidated when few are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), with quadratic penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Exact fit is superb.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if post-residual is too small for the next item
    // (wasted space), reward if next item fits perfectly into post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild penalty so tight existing fits win, but relax when alternatives are bad.
        let mut nb = 30.0;
        // If many bins are open and mean residual is large, opening new bins is wasteful.
        nb += open_bins_count as f64 * 1.5;
        nb += (mean_residual - post_residual as f64).max(0.0) * 0.4;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += progress * 20.0;
        // If the current bin can't fit the item well elsewhere... (new bin always fits)
        // If no other bin fits (fitting_bins_count == 1 and this is new bin), open it.
        if fitting_bins_count <= 1 {
            nb -= 100.0;
        }
        score += nb;
    } else {
        // Existing bin: reward using bins with below-average residual
        // (consolidate small residuals into fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Reward packing into bins whose residual is close to item size.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 10.0;
    }

    // Penalize leaving post-residual in the awkward 1..10 "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference for keeping the number of open bins stable when many open.
    if open_bins_count > 10 && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: penalize large residuals superlinearly,
    // with strength growing over stream progress.
    let norm_pr = pr / cap;
    let coupling = 1.0 + 2.0 * progress;
    score += coupling * norm_pr * norm_pr * cap;

    // Reward tight fits (small post_residual) with a smooth quartic bonus.
    score -= 12.0 * (1.0 - norm_pr).powi(4) * (1.0 + progress);

    // Lookahead: reward residuals that can still host the next item,
    // penalize residuals that strand space just above it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 6.0 * (1.0 - (diff / cap).powi(2));
        } else {
            score += 3.0 + (-diff / cap) * cap * 0.05;
        }
    }

    // Last-chance bin: strong reward to avoid opening a needless new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: neutral-to-slightly-high baseline, dropping late in
    // the stream when consolidation matters less than containment.
    if bin_residual == bin_capacity {
        score = cap * (0.55 - 0.25 * progress) + 0.3 * mean_residual;
    }

    // Mild penalty when many bins are open and this fit is loose.
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: exact-fill class heavily rewarded ---
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take
    } else {
        // Classify residual into harmonic buckets: tiny / small / medium / large
        let pr = post_residual;
        if pr <= 10 {
            score -= 60.0; // near-perfect: dead space almost unusable anyway
        } else if pr <= 20 {
            score -= 25.0;
        } else if pr <= 40 {
            score += 10.0; // mid residual: moderate dead space
        } else {
            score += 30.0; // large residual: wasteful placement
        }

        // Integer-division harmonic: residual divisible into likely item sizes (multiples of 10)
        let harmonic = pr % 10 == 0;
        if harmonic {
            score -= 8.0;
        } else {
            score += 6.0;
        }

        // Modulo-3 class on residual: penalize awkward thirds
        if pr % 3 == 0 && pr > 20 {
            score -= 4.0;
        }
    }

    // --- Lookahead coupling: does the next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: strong reward, scaled by how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.5;
        } else {
            // Next item won't fit: penalize leaving residual that traps the stream
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.3;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; only attractive when existing bins fit badly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap_f + 20.0 - 15.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 10.0; // fresh bin could serve next item too: slightly better
        }
        if post_residual == 0 {
            score -= cap_f; // item exactly fills a fresh bin: excellent
        }
    }

    // --- Congestion: many open bins -> prefer tightening existing ones ---
    if open_bins_count > 4 {
        let tightness = (mean_residual / cap_f).clamp(0.0, 1.0);
        score += tightness * 10.0;
    }

    // Fractional capacity coupling: reward when item fills a clean fraction of bin
    let fill_frac = (item_size as f64) / cap_f;
    if (fill_frac * 4.0).fract() < 1e-9 {
        score -= 5.0; // quarter/half fills are harmonic-friendly
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Perfect (or near-perfect) fill: strongly reward.
        score -= 40.0;
    } else if (post_residual as f64) < 2.0 * dead_threshold {
        // Semi-dead zone: residual too small for most items; penalize extra.
        score += 12.0;
    }

    // Reward exact/tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    // Last chance: this is the only open bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin.
        score += 30.0;
        // If several bins fit, discourage spreading; if none fit well (large
        // mean residual mismatch), opening fresh is more acceptable.
        if fitting_bins_count == 0 {
            score -= 45.0;
        } else if fitting_bins_count == 1 {
            score += 10.0;
        }
        // Early in the stream, allow more bins (future packing flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Pressure from too many open bins: penalize opening yet another.
        score += 2.0 * (open_bins_count as f64).powf(0.9);
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item would fit in the post-residual, reward;
    // if post-residual is just barely too small for the next item, penalize.
    if next_item_size > 0 {
        let pr = post_residual as u32;
        if next_item_size <= pr {
            score -= 8.0;
        } else if pr > 0 && next_item_size - pr <= 10 {
            score += 6.0; // near-miss dead space for the upcoming item
        }
    }

    // Mild alignment with mean residual: prefer bins whose leftover tracks
    // the fleet average (keeps residual distribution uniform and usable).
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // residual left that can host next item: prefer tight chains
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + chain_tightness / 10.0);
        } else {
            // next item cannot fit here; penalize proportional to wasted potential
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small dead space that nothing (min size 1) can use
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 80.0;
        // allow new bin late in stream if many bins already open (dispersion strategy)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio;

    // Penalize leaving residuals that no plausible item can fill (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }
    if post_residual > 0 {
        // dead-space grows if residual is below the minimum item size (1..100 interface)
        let usable = (post_residual as f64 / 100.0).min(1.0);
        score += (1.0 - usable) * 25.0;
    }

    // Perfect or near-perfect closure bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; slight penalty for wasting large residual
            score += 5.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Congestion: many open bins with high mean residual -> prefer packing into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score += congestion * (0.5 + 0.5 * progress);

    // New-bin candidate handling: make empty bin attractive only when current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // costly early, cheaper late when bins are scattered
        score += 20.0 + 30.0 * (1.0 - fragmentation) * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild time-decay regularization toward best-fit behavior late in the stream
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: normalized wasted space, mildly convex so big leftovers hurt disproportionately.
    let mut score = (pr / cap).powi(2) * 100.0 + 0.35 * pr;

    // Smooth non-linear coupling of leftover waste with stream progress:
    // late in the stream, large leftovers are more costly (less time to fill them).
    let late_penalty = (pr / cap) * (1.0 - progress) * (1.0 - progress) * 30.0;
    score += late_penalty;

    // Reward tight fits with a saturating non-linear term.
    let tight = (1.0 - pr / cap).powf(3.0);
    score -= tight * 45.0;

    // Lookahead: reward bins whose post_residual can host the next item (smooth sigmoid-like).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 20.0 + 25.0 * fit_quality * fit_quality;
        } else {
            // Penalize leftovers that are just barely too small for the next item (dead space).
            let gap = (nx - pr) / cap;
            score += 15.0 * (-8.0 * gap).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins where competition is low (fewer alternatives), mildly.
        score += (fitting_bins_count as f64).ln() * 6.0;
    }

    // Mean-residual coupling: penalize bins far below mean residual (they are the "hole" makers),
    // favor bins consistent with fleet state; smooth quadratic deviation.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // New-bin candidate: give it a calibrated baseline so it wins only when
    // existing fits are poor (its post_residual == cap makes base term large already),
    // but soften with progress so late-stream new bins are discouraged.
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual scaled by harmonic class of residual.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Harmonic classes: residual buckets by integer division on capacity/8
        let class = pr / 13; // class width ~ capacity/8
        score -= 8.0 * (8 - class.min(8)) as f64; // smaller residual classes get bigger reward
        // Dead-space penalty if residual can't fit even the smallest plausible item
        if pr < 5 {
            score += 25.0;
        }
    }

    // Coupling with next item: bonus if post_residual exactly accommodates lookahead
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 45.0; // chains a perfect follow-up
            } else {
                score -= 15.0 * (1.0 - slack as f64 / cap);
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 10.0 * (next_item_size as f64 - pr as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin should be penalized unless
    // this is a poor fit everywhere (item large relative to residuals).
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.35 * open_bins_count as f64;
        // If item is big, new bin is attractive (large items pack cleanly alone)
        let size_frac = item_size as f64 / cap;
        score = base - 30.0 * size_frac;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // room to chain next item in fresh bin
        }
    }

    // Mild preference for filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (bin_residual as f64 / cap));

    // Tie-break toward bins with below-mean residual (consolidate emptier bins)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the minimum item (1..=100 range,
    // but small gaps < 20 are unlikely to be filled later) are heavily penalized.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits: large fill ratio of the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize creating a gap that cannot fit the known next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward using the bin when it's the only fitting bin (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Encourage consolidating into bins with low mean residual (nearly full bins),
    // and prefer opening a new bin only when open bins have little room.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from mean residual of open bins.
        score += 25.0;
        if mean_residual < item_size as f64 {
            score -= 20.0; // open bins can't help much; new bin is fine
        }
        // Late in the stream, opening new bins is less costly than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // Favor bins whose residual is close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // 2-step lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 300.0 + 0.5 * next_item_size as f64;
        // chain fit quality: how snugly next item fits
        let chain_gap = post_residual - next_item_size;
        score -= (20.0 - chain_gap.min(20) as f64) * 5.0;
    } else if next_item_size > 0 {
        // Penalize leaving residual that is just barely too small for next item (dead space)
        let miss = next_item_size - post_residual;
        if miss <= 10 {
            score += 40.0 + 3.0 * miss as f64;
        }
    }

    // Tightness of current fit relative to capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * tightness;

    // Prefer bins with residual below mean residual (denser bins) when fit is decent.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or lookahead suggests a dedicated bin is valuable.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 60.0 && item_size <= 40;
        let lookahead_waste = next_item_size > 0 && next_item_size > post_residual && (next_item_size - post_residual) <= 15;
        if !poor_fit && !lookahead_waste {
            score += 250.0;
        } else if poor_fit {
            score += 50.0;
        }
        // Late in stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress) + 8.0 * norm_pr * norm_pr * (1.0 - progress);
    // reward tight fits, stronger late in stream
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);
    // penalize waste relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);
    // last-chance bin: strong bonus to avoid opening new bins late
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }
    // lookahead: favor leaving space usable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - ((pr - nx) / cap)).min(1.0) * (1.0 - progress);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }
    // mild penalty for many open bins to discourage sprawl
    score += 0.05 * open_bins_count as f64 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual belongs to a
    // "harmonizable" class (multiples of small divisors) are more likely to
    // be filled by future items. Penalize residuals in awkward classes.
    let pr = post_residual as i64;
    let class_penalty: f64 = if pr == 0 {
        0.0
    } else if pr % 10 == 0 {
        -30.0
    } else if pr % 5 == 0 {
        -15.0
    } else if pr % 2 == 0 {
        -5.0
    } else {
        // odd residual: hard to fill exactly; penalty grows with oddness
        10.0 + (pr % 7) as f64 * 2.0
    };
    score += class_penalty;

    // Dead-space penalty: residuals too small for the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: evaluate chain
            let chain_res = post_residual - next_item_size;
            score -= 40.0 - (chain_res % 10) as f64 * 2.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much of post_residual is wasted relative to next item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Integer-division threshold on residual fraction: prefer bins whose
    // fill ratio crosses harmonic thresholds (1/2, 3/4).
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    if fill >= 0.75 {
        score -= 60.0;
    } else if fill >= 0.5 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        let attract = 80.0
            + item_size as f64 * 0.5
            + progress * 40.0
            - crowding * 120.0
            - if fitting_bins_count == 1 { 300.0 } else { 0.0 };
        score = attract + post_residual as f64 * 0.1;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the next item
    // (or the smallest plausible item) are pure waste -> heavy penalty.
    let fits_next = next_item_size > 0 && post_residual >= next_item_size;
    if !fits_next {
        // Dead space: the smaller the residual, the more "sealed" the bin.
        // Penalize hardest for tiny residuals (< 10).
        if post_residual < 10 {
            score += 40.0;
        } else {
            score += 15.0;
        }
    } else {
        // Reward bins that can still host the lookahead item.
        score -= 8.0;
        // Extra reward for near-perfect two-item packing.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Reward tight fits overall (low post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual) as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage closing bins out when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when current bin leaves
    // bad dead space or many bins are already open.
    if bin_residual == bin_capacity {
        score -= 6.0;
        if post_residual < 10 && item_size < bin_capacity {
            // fresh bin after a near-sealed placement is fine
        }
        if open_bins_count > 3 {
            score -= 3.0;
        }
    }

    // Mild alignment with mean residual: prefer bins below mean residual
    // (denser bins) to consolidate fill.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        // perfect chain fit is highly desirable
        score -= (slack_after_next == 0) as i32 as f64 * 40.0;
        // small slack after chain placement is good
        score -= 15.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // penalize residuals that cannot host the next item
        score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // compare post_residual against mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // tight fits are good
    score -= 10.0 * (item_size as f64 / bin_residual as f64);

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // penalize leaving large unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill
    }

    // new-bin candidate handling: prefer opening a new bin only when current fit is poor
    if bin_residual == bin_capacity {
        // opening fresh is attractive early or when many bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 + 10.0 * progress;
        if item_size > 60 {
            score -= 10.0; // large items fit best in empty bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, this placement is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 8.0 * (next_item_size as f64 / 100.0);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys capacity for the next item
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 5.0 + 30.0 * fit_quality - 8.0 * pressure.min(3.0);
        // early in stream, opening bins is cheap; late, prefer consolidation
        nb += 15.0 * progress;
        // if many bins fit the item, opening a new one is wasteful
        nb += 4.0 * fitting_bins_count as f64;
        score += nb;
    }

    // Prefer bins whose residual deviates from mean (consolidate small residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild penalty for leaving large awkward gaps (dead space in mid range).
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // small but unusable gap: better than large gap, slight bonus
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0; // awkward dead zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear sharpening over progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (quadratic in normalized residual).
    score += 12.0 * progress * norm_pr * norm_pr * cap;

    // Reward filling bins deeply (item_size relative to capacity), smoothed.
    let fill = item_size as f64 / cap;
    score -= 8.0 * fill * fill * (1.0 - progress);

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_quality = 1.0 - gap / cap;
        if fit_quality > 0.0 {
            score -= 10.0 * fit_quality * fit_quality;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Penalize spreading across many open bins relative to mean residual.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for opening a new bin when open bins already exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: residues that form "nice" future
    // item slots (multiples of 10, 25, 50) are less dead than odd remainders.
    let pr = post_residual as u32;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongest reward
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        4.0 // prime-ish residue: likely dead space
    };
    score += harmonic_bonus;

    // Integer-division threshold: classify residual into usable slot sizes.
    let slot_class = pr / 10; // 0..=10
    score += slot_class as f64 * 0.8; // bigger leftover generally worse

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well the next item fills the remainder
            let fill = nxt / post.max(1.0);
            score -= 10.0 * fill;
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(30.0);
        }
        // harmonic coupling: next item landing on a class boundary is good
        if next_item_size % 10 == 0 && pr % 10 == 0 && next_item_size <= post_residual {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: an empty bin should only win when existing fits
    // are poor. Penalize the fresh bin mildly, more when many bins are open
    // (consolidation pressure) and when mean residual is large.
    if bin_residual == bin_capacity {
        let consolidation = (open_bins_count as f64).ln_1p();
        score += 18.0 + 4.0 * consolidation + 0.05 * mean_residual;
        // but if the item is huge relative to capacity, opening fresh is safer
        let frac = item_size as f64 / capacity;
        if frac > 0.7 {
            score -= 10.0 * (frac - 0.7);
        }
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score -= 0.1 * (1.0 - bin_residual as f64 / capacity);

    // Early in the stream, allow slightly more exploration of new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items (<= 10) are essentially wasted; punish them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small, barely usable gap: moderate penalty growing as gap shrinks.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward very tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: mild penalty scaled to gap size.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // New-bin candidate handling: an empty bin has large post_residual,
    // which is fine (fully usable), so soften its score when the current
    // item is large or fits are poor.
    if bin_residual == bin_capacity {
        score = 25.0 + item_size as f64 * 0.2 - tightness * 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: new bin is required
        }
    }

    // Mean residual context: placing into a bin far below mean residual
    // (i.e., using a large gap) is slightly favored.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly or nearly host the next item.
    if next_item_size > 0 {
        let lookahead = post_residual as i64 - next_item_size as i64;
        if lookahead == 0 {
            score -= 400.0; // chain fit: post residual exactly matches next item
        } else if lookahead > 0 {
            score -= 150.0 - (lookahead as f64).min(100.0); // next item still fits
        } else {
            // dead space relative to next item: penalize small unusable gaps
            let gap = (-lookahead) as f64;
            if gap < 10.0 {
                score += 60.0 + gap * 4.0;
            }
        }
    } else {
        // last item: strongly prefer filling bins completely
        score -= 300.0;
    }

    // Compare post_residual against mean residual: leaving a bin far below
    // the mean residual wastes capacity elsewhere.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.5 * mean_gap.max(0.0);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base penalty keeps new bins from being opened casually.
        score += 250.0;
        // But if the item is large relative to capacity or many bins are open
        // with fragmented residuals, a fresh bin gains appeal.
        score -= 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 80.0; // new bin also supports the next item
        }
    }

    // Slight late-stream tightening: waste hurts more as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual > 0 {
        // If next item fits exactly in the leftover, reward heavily.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else if next_item_size > post_residual {
            score += 6.0; // leftover likely wasted for lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            let min_waste = (bin_residual - item_size) as f64;
            (min_waste / bin_capacity as f64).min(1.0)
        };
        // Opening a bin is cheap early, expensive late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let cost = 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        score += cost;
        if poor_fit > 0.5 { score -= 35.0 * poor_fit; } // allow escape from bad fits
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin pairs well with upcoming large item
        }
    }

    // Mild preference for bins whose residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer fuller bins slightly as stream matures.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 0.6 * t * t + 0.4 * t * t * t;
    score *= poly;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tight = pr / cap;
    score -= 12.0 * (1.0 - tight) * (1.0 - tight) * (0.5 + t);

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that next item cannot use
        score += 0.05 * pr;
    }

    // Many open bins: mild penalty for spreading, favor consolidation
    score += 0.3 * open_bins_count as f64 * (1.0 - tight);

    // New empty bin candidate: penalize unless it enables a large-item fit
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit with tie-breaking toward fuller bins.
    score = post_residual as f64 * 1.0 + item_size as f64 * 0.05;

    // Harmonic class of post_residual: residues divisible by common item
    // classes (10/20/25/50) are more reusable.
    let pr = post_residual;
    let bonus = if pr == 0 {
        -60.0 // perfect fit is always ideal
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else {
        0.0
    };
    score += bonus;

    // Lookahead: reward if next item fits exactly into post_residual,
    // penalize if next item barely misses (creates dead space risk).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use the leftover; leftover likely dead space
            score += (next_item_size - pr).min(30) as f64 * 0.4;
        }
    }

    // Penalize tiny unusable residuals harder.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize when decent existing fits exist,
    // but allow opening when open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin costs roughly one bin; make it worse than any
        // reasonable fit but better than wasting a nearly-full bin.
        let mean_r = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let fragmentation = if mean_r < 20.0 { 1.0 } else { 0.0 };
        score = 100.0 - fragmentation * 10.0
            - if fitting_bins_count == 0 { 15.0 } else { 0.0 };
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 5.0;
    }

    // Mild pressure against accumulating many open bins with high residual.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item's size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual large enough to still fit next item: mild reward for closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (-slack / 15.0).exp();
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted lookahead.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap;
    }

    // Penalize post_residual far above mean residual (leaving others behind).
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev.max(0.0);

    // Reward tight fits (small post_residual) especially when item is large.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it slightly unattractive unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open already.
        score = 100.0 - 2.0 * open_bins_count.min(20) as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New empty bin gives perfect room for the next item.
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            // A real last-chance bin exists; prefer it over a new bin.
            score += 30.0;
        }
        if item_size >= 70 {
            // Large items: fresh bin can be reasonable.
            score -= 15.0;
        }
    }

    // Mild late-stream tightening: prefer filling bins fully as stream progresses.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this bin becomes doubly valuable.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 18.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 4.0;
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by dead space.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is already small.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: brand-new empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin; decreases as the stream progresses
        // and as the number of fitting alternatives grows.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 35.0 - 12.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 10.0 * (fitting_bins_count as f64).min(3.0);
        }
        // If the item is large relative to capacity and residuals are tight, opening
        // a fresh bin becomes more attractive.
        let size_frac = item_size as f64 / bin_capacity as f64;
        if size_frac > 0.7 && mean_residual < item_size as f64 {
            new_bin_penalty -= 20.0;
        }
        score += new_bin_penalty;
    }

    // Small time-horizon modulation: late in the stream, prefer consolidating
    // into bins with larger residuals to close them out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item / cap;
    let post_norm = post / cap;

    // Base: penalize leftover space, with smooth non-linear growth
    let mut score = post + 6.0 * post * post_norm;

    // Reward tight fits: smooth polynomial coupling of fill ratio and post-residual
    let tightness = (1.0 - post_norm) * (1.0 - post_norm);
    score -= 14.0 * tightness * (0.5 + fit_ratio);

    // Stream progress modulation: later in the stream, be greedier about tight fits
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 10.0 * prog_term * tightness;

    // Penalize bins whose residual deviates from mean (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 + prog_term);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 8.0 * prog_term;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // or when the fit is terrible; smooth logistic gate on fit quality
    if bin_residual == bin_capacity {
        let badness = 1.0 - (1.0 - post_norm); // = 0 for empty bin... use item-based fit
        let waste = fit_ratio; // small item into fresh bin wastes capacity
        let open_gate = 1.0 / (1.0 + (-6.0 * (waste - 0.35)).exp());
        score = post + 8.0 * post * post_norm
            + 30.0 * open_gate * (0.4 + prog_term)
            + 10.0 * (1.0 - prog_term);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" is the leftover space
    // modulo common item-size classes (capacity fractions).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical items
    // (below the smallest plausible class) are nearly worthless.
    if post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class bonus: post_residual divisible by small moduli tends to
    // accommodate future items drawn from modular size classes.
    let mut harmony = 0.0;
    for m in [10u32, 20, 25, 50].iter() {
        if post_residual % m == 0 && post_residual > 0 {
            harmony += 4.0;
        }
    }
    // Perfect fills are ideal regardless of divisibility.
    if post_residual == 0 {
        harmony += 30.0;
    }
    score -= harmony;

    // Lookahead coupling: reward when next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well the next item packs the leftover
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 10.0 * fill;
        } else {
            // next item cannot use this leftover; penalize large stranded space
            score += 0.05 * post;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin for this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when existing residuals are poor fits (large post_residual waste).
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin: cheap early, expensive late
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.9 + 40.0 * progress - mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big upcoming item benefits from a fresh bin
        }
    }

    // Mild preference for bins whose residual deviates from the mean in a
    // "packable" direction (keep mean residual low across open bins).
    score += 0.1 * (post - mean_residual).abs();

    // Tie-break noise-free deterministic coupling with stream position.
    score += 0.01 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
