        // Strong reward when next item exactly fills the post residual
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.6;
        }
        // Bonus if next item fits exactly or nearly after this placement
        if next_item_size <= post_residual && (post_residual - next_item_size) <= 5 {
            score -= 25.0;
        }
        // Penalize leaving post residual too small for next item (dead space)
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += post_residual as f64 * 0.3;
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean (tighter bins)
    let res = post_residual as f64;
    let mean_gap = res - mean_residual;
    score += mean_gap * 0.25;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to capacity (poor fit elsewhere) or no good lookahead pairing
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let new_bin_bonus = 8.0 - tightness * 10.0;
        score += new_bin_bonus;
        // If lookahead pairs perfectly with this item in a fresh bin, allow opening
        if next_item_size > 0 {
            let rem = bin_capacity - item_size;
            if next_item_size == rem {
                score -= 35.0;
            }
        }
    }

    // Progression: slightly favor consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Dead-space penalty: very small unusable residuals are wasteful
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

