    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize post-residual dead space that is too small to be useful
    // (smaller than the minimum plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual exactly or well,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 20.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; slight penalty for
            // fragmenting this bin.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins: prefer the tightest one; slight penalty to spread
    // competition when choice is abundant.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global balance: penalize bins whose residual deviates far above the
    // mean residual (wasteful bins), reward bins near the mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Time horizon: early in the stream, be conservative (prefer keeping
    // flexibility, penalize near-full bins slightly less); late in the
    // stream, aggressively fill bins to close them out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give it a moderate base penalty that shrinks
