    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * fill;
    }

    // Mild penalty for opening many bins relative to stream length.
    if total_items > 0 {
        score += 0.05 * (open_bins_count as f64 / total_items as f64) * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let smooth = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 8.0 * smooth * norm_pr * norm_pr * cap;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + smooth);

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - norm_next) * (0.5 + smooth);
    } else if next_item_size > 0 {
        // Reward leaving room for the next item, scaled by how well it fits
        score -= 4.0 * (1.0 - (pr - next_item_size as f64) / cap).abs() * smooth;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 10.0 * (1.0 - pr / 10.0);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + smooth);
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * 1.5 * norm_pr;

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * smooth;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual (mod 10 buckets)
    let pr = post_residual;
    let tight_class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect packing
    } else if tight_class == 0 {
        score -= 25.0; // residual divisible by 10 -> likely reusable
    } else if pr < 10 {
        score -= 15.0; // small dead space anyway, harmless
    } else {
        // penalize unusable residue: below smallest plausible item (1..100 unknown, use 10)
        if pr < 10 {
            score += 10.0;
        }
        // fraction-of-capacity coupling: residual in awkward mid-band
        let frac = post_residual as f64 / cap;
        if frac > 0.25 && frac < 0.45 {
            score += 8.0;
        }
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // extra reward if next item also lands on a harmonic class boundary
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize wasting good residuals
        score += 6.0;
    }

    // Last-chance bin: strongly favor filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // discourage opening new bins when open bins fit decently
            let best_possible = item_size as f64 / cap;
            score += 15.0 + 10.0 * (open_bins_count as f64).sqrt();
            if item_size % 10 == 0 {
                score += 5.0; // round items pack well anywhere; prefer existing bins
            }
            let _ = best_possible;
        }
    }

    // Mild stream-progression term: consolidate more as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (mean_residual / cap);

    // Prefer bins already below mean residual (consolidation)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space is worse than a large gap
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // moderately risky gap
    }

    // Reward tight fits (small post_residual in the usable range).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual >= 25 {
        score -= 8.0;  // large residual stays usable for future items
    }

    // Lookahead coupling: if next item can use the leftover, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0; // leftover cannot serve the next item
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mild penalty unless its residual is genuinely better.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Opening fresh is attractive only if no tight fit exists elsewhere.
        if post_residual >= 20.0 && fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Progress-based nudge: later in stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 - progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fit (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 15 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: big reward, scaled by how snugly it fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 150.0 + slack_after_next as f64 * 0.5;
            // Extra reward for a near-perfect two-item packing.
            if slack_after_next == 0 {
                score -= 300.0;
            } else if slack_after_next <= 5 {
                score -= 120.0;
            }
        } else {
            // Next item won't fit after placing here: penalize, worse if the
            // leftover dead space is small and unusable.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 250.0;
            } else {
                score += 30.0;
            }
        }
    }

    // Prefer bins whose residual is below mean (tight bins get filled first),
    // penalize bins that are much looser than average.
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 400.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Make the empty-bin baseline costly
    // so it wins only via exact/near-exact two-step matches.
    if bin_residual == bin_capacity {
        score += 350.0;
        // But if the next item is large and current item is small, a fresh
        // bin may be a good pairing anchor.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> slightly prefer
    // filling existing ones rather than spreading.
    score += open_bins_count as f64 * 2.0;

    // Late in the stream, tighten up: waste matters more as we approach the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual strongly (non-linear)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no typical item can use.
    // If post_residual is smaller than the smallest plausible item (1..),
    // treat as perfect fill; otherwise penalize unusable slivers.
    if post_residual > 0 {
        let unusable = post_residual < item_size.min(next_item_size.max(1));
        if unusable {
            score -= 15.0; // actually good: residual too small to waste on future items? no—reward instead
        }
    }
    // Reward residuals that exactly match the lookahead item (perfect chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // residual can host the next item: mildly good
        score -= 8.0;
    } else if next_item_size > 0 {
        // residual cannot host next item: penalize proportionally
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // competition exists: prefer bins with least waste relative to mean residual
        let spread = bin_residual as f64 - mean_residual;
        score += 0.25 * spread; // prefer tighter-than-average bins
    }

    // New-bin decision: opening a new bin is costly; penalize unless current
    // fit is poor (post_residual large) or the bin is nearly empty of use.
    if is_new_bin {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        let late_stream = progress > 0.8;
        let many_open = open_bins_count as f64 > 10.0 + 20.0 * progress;
        if poor_fit || late_stream || many_open {
            score -= 20.0; // allow opening when fit elsewhere is bad
        } else {
            score += 25.0; // discourage opening when decent fits exist
        }
        // Slight time-dependent modulation of new-bin cost
        score += 10.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with high mean residual -> consolidate
    if mean_residual > 0.0 {
        let consolidation = (mean_residual - post_residual as f64) / mean_residual.max(1.0);
        score -= 5.0 * consolidation.clamp(-1.0, 1.0);
    }

    // Mild penalty for very large post_residual (waste), scaled by stream progress
    score += 0.05 * post_residual as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - norm_pr;
    let item_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Base: prefer tight fits, but non-linearly (quadratic in normalized post-residual).
    let mut score = 1.0 + 2.0 * norm_pr * norm_pr + 0.8 * norm_pr;

    // Reward high fill ratio, amplified as stream progresses (late items want tighter packing).
    score -= (1.0 + 1.5 * progress) * fill * fill;

    // Coupling: post-residual usefulness vs. next item size.
    // If post_residual closely matches next item, big reward (smooth Gaussian-like kernel).
    if next_item_size > 0 {
        let gap = (pr - next_frac * cap) / cap;
        let kernel = (-6.0 * gap * gap).exp();
        score -= 2.5 * kernel * (1.0 - progress * 0.5);
        // Penalize post-residual that is too small to ever be useful (dead space), worse early.
        let dead = norm_pr * (1.0 - item_frac);
        score += 1.2 * dead * (1.0 - 0.5 * progress);
    } else {
        // Last item: just minimize waste linearly.
        score += 0.5 * norm_pr;
    }

    // Scarcity pressure: if few bins can fit this item, strongly favor using one of them
    // over opening a new bin (smooth in fitting_bins_count).
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 3.0 * scarcity;

    // Mild penalty for proliferating bins relative to mean residual: if open bins are already
    // loose on average, prefer filling them rather than opening new ones.
    let mean_norm = mean_residual / cap;
    score += 0.6 * mean_norm * (open_bins_count as f64).sqrt() * 0.2;

    // New-bin candidate (empty bin): penalize unless residuals across bins are poor or
    // item is large relative to typical residual (smooth logistic gate).
    let is_new_bin = if (bin_residual as f64 - cap).abs() < 1e-9 { 1.0 } else { 0.0 };
    let tightness = 1.0 / (1.0 + (mean_norm * 8.0 - 4.0).exp()); // ~1 when mean residual is low
    let largeness = 1.0 / (1.0 + (4.0 - item_frac * 8.0).exp()); // ~1 when item is big
    score += is_new_bin * (6.0 * tightness * largeness * (1.0 - 0.5 * progress) + 2.0);

    // Small tie-breaker on exact fit.
    if post_residual == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in "usable" classes
    // (small enough to be filled by typical items, or exactly zero) are rewarded.
    let cap_f = bin_capacity as f64;

    // Exact fit is best possible.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Modulo arithmetic on post_residual: classify residual into harmonic classes
    // of capacity/10. Residuals divisible by 10 (and by 20, 25, 50) are "harmonic"
    // sizes that future items (integer sizes 1..100) more likely complement.
    let pr = post_residual;
    if pr % 10 == 0 { score -= 6.0; }
    if pr % 20 == 0 { score -= 3.0; }
    if pr % 25 == 0 { score -= 2.0; }
    if pr % 50 == 0 { score -= 2.0; }

    // Dead-space penalty: residuals too small for typical items (integer division
    // threshold). Items >= 10 are common; residual < 10 is nearly dead space,
    // but tiny residuals still beat mid-size waste.
    if pr < 10 {
        score -= 8.0; // near-perfect packing, small waste
    } else {
        // Integer division thresholds: bucket residual by capacity fifths.
        let fifth = bin_capacity / 5; // 20
        let bucket = pr / fifth;
        score += bucket as f64 * 2.5; // larger residual buckets penalized mildly
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly reward; if next item fits at all, reward; if next item cannot
    // use the residual, penalize (residual becomes dead space).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item would leave a badly fragmented residual in every open bin.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full residual as future potential,
        // discounted by stream progress (late in stream, prefer reusing bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap_f * (1.0 - 0.25 * progress);
        // If next item is large and would fit perfectly with current item in a
        // fresh bin, reward opening it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let combined_slack = (bin_capacity - item_size - next_item_size) as f64;
            score -= 40.0 - combined_slack * 0.5;
        }
        // If current item fits well somewhere (small post residual exists),
        // fresh bin looks worse; approximate via mean residual alignment.
        if (mean_residual - post_residual as f64).abs() < 5.0 {
            score += 5.0;
        }
    }

    // Mild penalty for proliferating bins when residual structure is poor.
    if open_bins_count > 4 && post_residual > bin_capacity / 2 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small leftover gaps are unusable dead space. Penalize them super-linearly.
    let min_item = 1u32; // interface allows sizes from 1
    let dead_threshold = 10u32; // gaps this small rarely get filled
    if post_residual > 0 && post_residual < dead_threshold {
        // deep penalty: unusable sliver
        score += 25.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 40.0;
    } else {
        // reward tight fits: fraction of bin consumed
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * tightness;
    }

    // Penalize residuals that cannot fit the lookahead item (wasted for next step)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // bin stays useful for the lookahead item
    }

    // --- Open-bin pressure ---
    // Many open bins: prefer consolidating into existing bins rather than spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64;
    score += 0.15 * pressure * (0.5 + progress);

    // Relative fit quality vs mean residual of open bins
    if bin_residual as f64 > mean_residual {
        score += 2.0; // this bin is emptier than average -> less attractive
    } else {
        score -= 2.0;
    }

    // --- Last-chance bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // only this bin can fit the item: strongly prefer it over opening a new bin
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins create dead space
        // or are nearly full. Otherwise penalize spreading.
        let poor_options = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { 0.0 } else { 12.0 };
        score += 18.0 - poor_options + 0.5 * open_bins_count as f64 * progress;
        // empty bin gives a perfect full residual; slightly reward fresh capacity late in stream
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits strongly (aggressive tight packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // heavily reward this placement (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_tight / bin_capacity as f64);
        // Bonus when the chain leaves near-zero dead space.
        if next_tight < 5.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Next item would NOT fit here after placement: penalize blocking.
        score += 10.0;
    }

    // Relative to mean residual: prefer bins that are already "below average" fill
    // (small residual) to consolidate waste into few bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist and item is small.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.2 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // a fresh bin is fine if it enables a lookahead chain
        }
    }

    // Early in stream: slightly prefer keeping bins open and flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
