    // current item fits very poorly anywhere else (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) / (bin_capacity as f64); // == 1.0 for empty bin
        // Base cost of a new bin, reduced when item is large or stream is early
        // and many bins remain to be filled anyway.
        let mut new_bin_cost = 55.0
            - 20.0 * (item_size as f64 / 100.0)
            - 15.0 * (1.0 - progress);
        // If other fitting bins exist, opening a new bin is wasteful unless
        // this bin would be nearly perfectly filled by the item.
        if fitting_bins_count > 0 {
            new_bin_cost += 30.0 * (1.0 - (item_size as f64 / bin_capacity as f64));
        }
        // Discourage proliferation when many bins are already open with slack.
        new_bin_cost += 3.0 * (open_bins_count as f64).sqrt();
        new_bin_cost += 0.15 * mean_residual;
        score += new_bin_cost * (0.5 + 0.5 * poor_fit);
    }

    // Mild preference for fuller bins among equals (best-fit-like tilt).
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Global slack balancing: prefer bins whose residual is below mean
    // (concentrate fill), penalize drawing from above-mean bins.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.08 * (residual_f - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - residual_f);
    }

    // Late-stream conservatism: as the stream ends, avoid leaving tiny residues.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let t = progress;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * t * (1.0 - t) * 4.0);
    score += coupling * cap * 0.5;

    // Penalize waste more as the stream matures (quadratic in progress).
    score += pr_norm * (t * t) * 30.0;

    // Reward tight fits with smooth term.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 10.0;

    // Last-chance bin bonus (smooth in fitting count).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * 1.5;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score -= fits_next * (1.0 - gap * gap) * 8.0;
        score += (1.0 - fits_next) * 5.0;
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += (open_bins_count as f64 / (1.0 + t * 10.0)) * 0.05 * (1.0 - pr_norm);

    // Deviation from mean residual (smooth quadratic).
    score += ((pr - mean_residual) / cap).powi(2) * 5.0;

    // Slight bias toward opening new bins early (smooth in progress).
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - t) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / c;

    // Penalize dead space that cannot host typical items (harmonic thresholds at 1/4, 1/2, 3/4)
    if post > 0 {
        if post < 10 {
            score += 60.0; // unusable sliver
        } else if frac < 0.25 {
            score += 25.0;
        } else if frac < 0.5 {
            score += 8.0;
        } else if frac < 0.75 {
            score -= 5.0;
        } else {
            score -= 12.0; // roomy leftover is good
        }
    }

    // Integer-division class: how many items of the lookahead size fit in the leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits = post_residual / next_item_size;
        score -= 15.0 * fits as f64;
        // exact match coupling: leftover exactly hosts the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host the next item: penalize proportionally
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Modulo-class bonus: residual sharing divisor structure with capacity
    if post_residual > 0 && bin_capacity % post_residual.max(1) == 0 {
        score -= 10.0;
    }
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 5.0; // round residual classes are easier to fill later
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 * (fitting_bins_count as f64);
        score -= 0.05 * (open_bins_count as f64);
        if next_item_size > 0 {
            score += (c - next_item_size as f64) * 0.1;
        }
    }

    // Progress-aware mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (mean_residual - post) * 0.15 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize gaps too small to ever hold a plausible future item (>= ~10).
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        }
        // Non-linear penalty on small gaps in general (quadratic dead space).
        score += (dead * dead) / (bin_capacity as f64 * 2.0);
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item would fit better here than in post residual,
    // slight penalty for "wasting" this bin's space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 15.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else if nxt <= bin_residual as f64 {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: penalize adding to bins when many are open,
    // encouraging consolidation; but opening new bin has inherent cost too.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score = bin_capacity as f64 * 0.9 - 20.0 * progress
            + 4.0 * open_bins_count as f64;
        // If next item is large and no open bin will likely hold both, opening is fine.
        if next_item_size > 60 && item_size > 60 {
            score -= 25.0;
        }
    } else {
        // Mild pressure to prefer fuller bins when many bins are open.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Reward tightness relative to mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item size.
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            // Exact two-item fill: strongly reward.
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 25.0 - diff * 2.0;
        } else {
            // Penalize leftover that next item cannot use.
            if next_item_size > post_residual as u32 {
                // Next item won't fit here; leftover likely dead space.
                score += diff * 0.4;
            } else {
                score += diff * 0.15;
            }
        }
        // If next item fits exactly into bin_residual (two-step chain fill), reward mildly.
        if next_item_size == bin_residual {
            score -= 15.0;
        }
    } else {
        // Last item: only current fill matters.
        score -= 10.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose residual is below mean (tighter bins get filled first),
    // keeping looser bins flexible for future items.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.3;
    }

    // --- Dead space penalty (non-linear) ---
    // Small leftovers (< 10) are nearly unusable given item sizes >= 1..100 unknown,
    // but with unknown distribution treat very small leftovers as risky.
    if res > 0.0 && res < 8.0 {
        score += (8.0 - res) * 3.0;
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; avoid opening a new bin unless fit is terrible.
        score -= 20.0 + 0.1 * bin_residual as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when many bins are open and mean residual is high
        // (existing bins are fragmented), or when the current fit is poor.
        let fragmentation = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        let poor_fit = (post_residual as f64) > 40.0;
        if fragmentation > 3.0 || (next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual > 25) {
            score -= 18.0 + fragmentation;
        } else if poor_fit && fitting_bins_count > 0 {
            score -= 5.0;
        } else {
            // Prefer reusing existing bins normally.
            score += 12.0;
        }
        // Late in the stream, slightly discourage opening new bins to consolidate.
        score += progress * 8.0;
    }

    // --- Mild pressure to keep number of open bins bounded ---
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear waste penalty: squared residual relative to capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr * pr) / (2.0 * cap);

    // Reward tight fits (small post_residual) more aggressively
    if pr <= 5.0 {
        score -= 25.0;
    } else if pr <= 10.0 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 40.0;
        } else if nxt <= pr {
            score -= 10.0 * (nxt / (pr + 1.0));
        } else {
            // next item won't fit: mildly penalize leaving awkward gaps
            score += 5.0 * (1.0 - (pr / nxt).min(1.0));
        }
    }

    // New-bin candidate handling: empty bin gets a penalty so we prefer existing bins,
    // unless no open bin fits well (post_residual of empty bin is large anyway).
    if bin_residual == bin_capacity {
        let base_penalty = 20.0 + 0.3 * open_bins_count as f64;
        // If this bin is the only fitting option, soften the penalty
        if fitting_bins_count <= 1 {
            score += base_penalty * 0.4;
        } else {
            score += base_penalty;
        }
        // Late in the stream, opening new bins is more acceptable
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Global state: if mean residual is high, bins are loose — prefer packing into
    // bins below mean residual (tighter bins) to consolidate.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Mild pressure to fill existing bins as open bin count grows
    if bin_residual < bin_capacity {
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    // Early on, waste matters less (bins will be reused); late, tight packing matters.
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Smooth interaction: reward small post-residuals that match the next item size
    // via a Gaussian-like coupling (smooth, non-piecewise).
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let sigma = 8.0 + 6.0 * (1.0 - progress);
        let match_bonus = -35.0 * (-(diff * diff) / (2.0 * sigma * sigma)).exp();
        score += match_bonus;
    } else {
        // Last item: waste is permanent, penalize strongly.
        score += 25.0 * norm_pr;
    }

    // Last-chance bin: strongly favor using it (smoothly scaled by progress).
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild reward when bin residual is below mean residual (tighter bins first),
    // as a smooth normalized term.
    if mean_residual > 0.0 {
        let tightness = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 10.0 * tightness * (0.5 + progress);
    }

    // Slight preference for consolidating into fewer bins as stream advances.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Prefer filling larger fractions of the bin (smooth saturating term).
    score -= 15.0 * (item_size as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that are hard to fill (small odd classes).
    let class = post_residual % (bin_capacity / 10); // class width 10
    let class_f = class as f64;
    if post_residual > 0 {
        // Odd/tiny classes are dead space; even multiples of 10 are reusable.
        if class == 0 {
            score -= 6.0; // perfect decile residual: very reusable
        } else if class_f <= 5.0 {
            score += 10.0 - class_f; // small unusable sliver
        } else {
            score -= (class_f - 5.0) * 0.8; // moderately reusable
        }
    } else {
        score -= 12.0; // perfect fill
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % (bin_capacity / 10);
            score -= 4.0 - (nxt_class as f64) * 0.3;
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early when few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
    } else {
        // Favor bins tighter than the mean residual (good fills).
        let dev = mean_residual - post;
        score += dev * 0.15;
    }

    // Mild preference for bins whose residual is a harmonic multiple of common item sizes.
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 1.5;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Strict dead-space penalty: residuals in the unusable small-gap zone
    // (too small for the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - 5.0 * post_residual as f64; // 55..5 penalty, worst at 1
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using a bin whose residual was already small (consolidation)
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage opening a new bin when few are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the current item
    // would leave a bad dead space in every existing bin, or when the
    // next item pairs well with the fresh residual.
    if bin_residual == bin_capacity {
        // fresh bin baseline
        score -= 15.0;
        // penalize opening a new bin if the item fits nicely somewhere already
        if post_residual >= 12 || post_residual == 0 {
            score += 20.0;
        }
        // lookahead pairing: fresh bin residual after placement should fit next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
    } else {
        // lookahead: penalize placements that destroy room for the next item
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
        // reward leaving exactly the next item's size (perfect chaining)
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Mild stream-progression adaptation: later in the stream, be more
    // conservative about dead space (pack tighter).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a good "garbage collector" bin — use it.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space relative to mean residual
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;
    }

    // 2-step lookahead: reward when post_residual matches next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item can also fit: good chaining, but small residual remains
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: the leftover is likely dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress + open_bins_count as f64 * 0.5;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Slight preference for tighter bins overall
    score += (bin_capacity as f64 - bin_residual as f64) * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
        } else {
            // next item cannot use this residual: penalize large dead space
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * dead * dead;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0 * tightness;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is fine early or when
    // open bins would leave large unusable residuals; penalize it late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 18.0 * progress;
        // if many bins open and mean residual is large, discourage new bins
        score += 0.3 * open_bins_count as f64;
        if mean_residual > item_size as f64 + 10.0 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across too many bins when residuals are small
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual - 5.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted space, damped by stream progress
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm) * (1.0 - 0.3 * progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (cap - pr) * 0.1 * (0.5 + 0.5 * progress);

    // Penalize deviation of post_residual from mean residual (fragmentation coupling)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-resort bonus: strongly favor this bin if it's the only one that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).abs()) * (1.0 - progress);
        } else {
            score += 0.05 * (-gap);
        }
    }

    // Mild pressure against opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Harmonic class of post_residual: small remainders are "dead" space classes.
    // Class by integer division thresholds (0 = perfect, small = good).
    let dead_class = post_residual / 10; // 0..10 classes
    score += dead_class as f64 * 2.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = post_residual - next_item_size;
        if next_fit == 0 {
            score -= 60.0;
        } else {
            score -= 25.0 * (1.0 - next_fit as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a mid-range residual that
        // is too large to waste but too small to be useful (harmonic dead zone).
        if post_residual >= 10 && post_residual < 30 {
            score += 15.0;
        }
        // Reward leaving residuals that match modulo classes of common sizes.
        let m = post_residual % 10;
        if m == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive when open bins fit.
    if bin_residual == bin_capacity {
        // Base cost of a new bin (roughly a full bin's worth of score).
        score = bin_capacity as f64 * 1.2;
        // Cheaper to open a new bin late in the stream or when few bins fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64; // no alternative: new bin is fine
        }
        // If item is large, new bin gives a clean harmonic class start.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else if fitting_bins_count == 0 {
        // Should not happen for open bins, but guard.
        score += 1000.0;
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.5 * open_bins_count as f64;

    // Nudge toward bins whose residual is below mean (consolidating emptier space).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0 * ((res_f - mean_residual) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item, 1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    } else if post_residual > 80 {
        // Large leftover is fine (still versatile)
        score -= 6.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins
    score += (open_bins_count as f64) * 1.5;

    // If this is the only bin that fits, strongly prefer using it over opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        score += 20.0 + (mean_residual / bin_capacity as f64) * 30.0;
        // If next item is large and current residual would be tiny, opening new bin is better
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Lookahead: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        }
        // If next item would NOT fit in post_residual, mild penalty (dead-ish space ahead)
        if next_item_size > post_residual && post_residual > 0 {
            score += 6.0;
        }
    }

    // Early in stream: be slightly conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 3.0 * (bin_capacity as f64 - diff) / bin_capacity as f64;
        // Perfect two-item fill bonus
        if next_item_size as u32 == post_residual {
            score -= 25.0;
        }
        // Next item fits exactly after current placement
        if post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 15.0;
        }
    } else {
        // Last item: prefer minimal residual, strongly
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: penalize bins far above mean (wasteful), reward tight bins
    let cap = bin_capacity as f64;
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Tight fit reward: small post residual relative to capacity
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that nothing (min item 1) can use less; small items exist so mild
    score += 0.05 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current placement would be very wasteful
    if bin_residual == bin_capacity {
        // Opening new bin: baseline penalty so we only open when existing fits are poor
        score += 18.0;
        // But if lookahead says next item is large and no tight fit possible, opening is okay
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty normalized by capacity.
    let post = post_residual as f64;
    score += (post * post) / (bin_capacity as f64);

    // Lookahead: if the next item fits in the post-residual, reward this bin (it becomes useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.25;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space unusable by next item: penalize proportionally to how close it is.
        let waste_ratio = post / (next_item_size as f64).max(1.0);
        score += 8.0 * (1.0 - waste_ratio.min(1.0));
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins slightly when mean residual is high.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.3 * (mean_residual / (bin_capacity as f64));
    }

    // New-bin candidate logic: prefer new bin only when the item is large and would leave
    // a big residual in existing bins, or late in the stream with few fitting bins.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 45.0;
        if item_frac > 0.6 { new_bin_score -= 20.0 * (item_frac - 0.6) / 0.4; }
        if fitting_bins_count == 0 { new_bin_score -= 40.0; }
        if next_item_size > 0 && post_residual >= next_item_size { new_bin_score -= 15.0; }
        new_bin_score += progress * 10.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize waste more strongly
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * norm_pr * norm_pr;

    // Reward filling bins deeply early, penalize near-empty-bin usage late
    let fill = 1.0 - fit_ratio;
    score -= (1.0 - t) * fill * fill * 2.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / cap;
        score += gap * gap * 3.0;
        if next_item_size as u32 == post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mild penalty so open bins are preferred unless waste is huge
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * t;
    }

    // Mean residual divergence: penalize bins far from mean residual (nonlinear)
    let dev = norm_pr * cap - mean_residual;
    score += 0.02 * dev * dev / cap;

    // Congestion: many open bins -> favor consolidating into existing bins
    score += (open_bins_count as f64).ln() * norm_pr * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in low classes are "dead space".
    let class_width = bin_capacity / 5; // classes of size 20
    let post_class = post_residual / class_width;
    // Penalize low classes (small residuals) super-linearly.
    score += (4 - post_class.min(4)) as f64 * 8.0;

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic pairing: does next item fit into the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect pairing classes: post_residual mod next_item_size == 0 is ideal.
        let pair_mod = post_residual % next_item_size.max(1);
        score -= 12.0 + (bin_capacity as f64 / next_item_size.max(1) as f64) * 0.5;
        if pair_mod == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Lookahead doesn't fit: penalize proportionally to wasted pairing potential.
        let gap = next_item_size - post_residual;
        score += gap as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Open a new bin if item is large relative to typical residual (poor fit everywhere).
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Harmonic: large items (high class) start bins well.
        let item_class = item_size / class_width;
        if item_class >= 3 {
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        score += open_bins_count as f64 * 1.5;
    } else {
        // Prefer bins whose residual is close to the item (tight fit) via modulo distance.
        let div = bin_residual / item_size.max(1);
        if div >= 1 {
            score -= 3.0; // item divides residual into reusable chunks
        }
        // Favor bins below mean residual (already partially filled efficiently).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Integer-division threshold on post_residual: residuals < 10 are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are pure waste -> heavy quadratic penalty.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    // Mid-range unusable gaps (too small for typical items) get a softer bump.
    if post_residual >= dead_threshold && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: waste ratio drives the score down.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += pressure * (1.0 - fill_ratio) * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 - gap * 0.3;
    }
    // If next item would not fit here but fits a fresh bin, penalize slightly.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // New-bin candidate (empty bin): prefer it only when it enables the next
    // item or no open bin fits well; otherwise make it unattractive.
    if bin_residual == bin_capacity {
        let opens_attractive = next_item_size > 0 && next_item_size <= post_residual - item_size;
        if fitting_bins_count > 0 && !opens_attractive {
            score += 40.0;
        } else if opens_attractive {
            score -= 12.0;
        }
        // Mild encouragement to open fresh bins when mean residual is fragmented.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 5.0;
        }
    }

    // Slight preference for bins with residual closest to item size (best fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional closeness to full fill
            let chain_fill = nxt / post_residual as f64;
            score -= 40.0 * chain_fill;
        } else {
            // next item won't fit in residual: penalize wasted space scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }

        // Two-item packing: item + next <= residual means near-perfect packing
        if item_size + next_item_size <= bin_residual {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize post_residual hard
        score -= 30.0;
    }

    // Penalize post_residual far below mean_residual (fragmenting small leftovers)
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.3 * (mean_residual - pr);
    } else {
        score -= 0.1 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current fits are bad
    if bin_residual == bin_capacity {
        let bad_fits = if next_item_size > 0 {
            (post_residual as f64).max(0.0)
        } else { 0.0 };
        let pressure = if fitting_bins_count <= 1 { 80.0 } else { 0.0 };
        score = score.min(0.0) + 55.0 - pressure - 0.2 * (open_bins_count as f64);
        let _ = bad_fits;
        // Penalize opening new bins when many bins are open and item is small
        if item_size <= 30 && open_bins_count > 3 {
            score += 40.0;
        }
    }

    // Mild stream-phase modulation: be more conservative late in the stream
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness: reward small post residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 5.0;

    // Lookahead: penalize leaving a residual that is too small for the next item
    // (dead space), but reward leaving exactly enough room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // residual becomes dead space unless it is near zero
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: default penalty so it's chosen only when
    // all open bins fit poorly (their scores will be higher due to waste terms)
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
        // early in the stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with large mean residual ->
    // encourage filling existing bins rather than spreading
    if open_bins_count > 0 {
        let fill_pressure = mean_residual / bin_capacity as f64;
        score -= fill_pressure * 6.0;
    }

    // Penalize bins whose post residual is an awkward small value (unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: minimize post residual (tight packing)
    let mut score = r;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tighter fits matter more (penalize large residuals)
    let tightness = norm_r * norm_r * (1.0 - progress);
    score += 40.0 * tightness * (1.0 - norm_r);

    // Reward near-perfect fits smoothly via cubic shaping of norm_r
    score -= 30.0 * (1.0 - norm_r) * (1.0 - norm_r) * (1.0 - norm_r);

    // Dead-space penalty: residuals too small for typical items are wasted
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = next - r;
        if gap > 0.0 {
            score += gap * (0.5 + 0.5 * progress);
        } else {
            // next item fits: reward leaving a usable residual
            score -= 8.0 * (r / next) * (1.0 - r / next) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Prefer bins with residual below mean (consolidate large holes)
    score += 5.0 * (mean_residual - r) / cap;

    // Mild penalty for spreading across many bins late in stream
    score += 0.3 * (open_bins_count as f64) * norm_r * progress;

    // New-bin candidate: discourage unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress) - (fitting_bins_count as f64) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i64; // 0..7 harmonic bands

    // Reward tight fits: post_residual in lowest harmonic band
    match class {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score -= 8.0,
        3 => score -= 0.0,
        4 => score += 6.0,
        5 => score += 14.0,
        6 => score += 24.0,
        _ => score += 35.0,
    }

    // Dead-space penalty: residual that no future item (min size 1..small) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable sliver
    }

    // Coupling with next item: reward if next item fits the post residual exactly or near
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 45.0; // perfect chaining
        } else if gap > 0 && gap <= 10 {
            score -= 18.0;
        } else if gap < 0 {
            score += 10.0; // next item won't fit here
        }
        // modulo harmony: next item and post residual share divisibility structure
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 12.0;
        }
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalty when many bins are open and this placement leaves a bad residual
    if open_bins_count > 4 {
        let spread = (post_residual as f64 - mean_residual).abs();
        score += spread * 0.3;
    }

    // Early stream: be slightly greedy toward tight fits; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64 / cap) * 10.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -100.0; // must open a new bin
        } else {
            // prefer new bin only if best existing fit would waste a lot
            score = 40.0 + mean_residual * 0.2;
            if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size.min(bin_capacity) {
                score -= 15.0; // next item pairs well with fresh bin
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (post_residual < 10)
    // are heavily penalized since no future item can use them.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (best-fit flavor beyond raw residual).
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading items across many bins
    // unless the fit is genuinely good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this placement chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item would be blocked by remaining residual, mild penalty
    // unless residual is too small to matter anyway.
    if next_item_size > post_residual && post_residual >= next_item_size.min(9) {
        score += 5.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit, otherwise
    // keep it slightly unattractive so existing space gets used.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // Compete with open bins: only win if their fits are poor
            // (large residuals wasted). Scale with mean residual.
            score = 55.0 + mean_residual * 0.3 - (item_size as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Progress-based mild tightening: later in the stream, prefer
    // consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weigh against mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Perfect chain: next item fills bin exactly -> strong reward.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how close the next item comes to filling remainder.
                let fill_ratio = nxt / post;
                score -= 40.0 * fill_ratio * fill_ratio;
                // Penalize leaving a remainder that is awkwardly small (< 10 typical min item).
                if gap < 10.0 {
                    score += 15.0;
                }
            }
        } else {
            // Next item cannot fit here regardless; slight penalty for hoarding space.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin if existing fits are poor.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Neutral base for a fresh bin; discourage if current item leaves large unusable gap
        // relative to capacity, or if next item is small and could be packed elsewhere.
        score += 30.0;
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 10.0; // fresh bin won't chain either
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer filling existing ones.
    score += 0.3 * open_bins_count as f64;

    // Late-stream tightening: as stream progresses, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving residual that cannot fit the next item
    // (dead space), reward residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
            // Extra reward if leftover exactly chains with next item.
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            // Dead space too small for the next item.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are large (poor fits everywhere) or bins are few.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let mean_fit = mean_residual.max(0.0);
        // If open bins have plenty of room, discourage opening a new one.
        score += 18.0 + open_bins_count as f64 * 0.5;
        // But if mean residual is high (bad fits), soften the penalty.
        score -= (mean_fit / bin_capacity as f64) * 20.0;
        // Early in the stream, having bins available is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
    } else {
        // Favor bins whose residual is far below the mean (already well-packed).
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Mild preference for larger residual bins when many fit (spread load).
    if fitting_bins_count > 3 {
        score -= 0.02 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = 4.0 * norm_pr * norm_pr * cap + 0.5 * pr;

    // Stream-progress coupling: early on, tolerate loose fits (explore); later, punish waste
    let progress_penalty = (1.0 + t * t) * pr * (pr / (pr + item_size as f64 + 1.0));
    score += 0.8 * progress_penalty;

    // Smooth interaction: post residual vs mean residual — avoid creating outliers far below mean
    let dev = (mean_residual - pr) / cap;
    score += 12.0 * dev * dev * (1.0 + t);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * t;
    }

    // Lookahead: reward leaving room for the next item (smooth bell around next fit)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (-diff * diff * 400.0).exp();
    }

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 3.0 + 20.0 * t + (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets capture "usable chunk" structure.
    let post = post_residual;
    let class = post % 10;
    // Dead-space penalty: residuals that are small but nonzero are hard to fill.
    if post > 0 && post < 10 {
        score += 12.0;
    } else {
        // Reward residuals that are multiples of common item sizes (harmonic fit).
        if post % 10 == 0 && post > 0 { score -= 8.0; }
        if post % 20 == 0 && post > 0 { score -= 4.0; }
        if post % 25 == 0 && post > 0 { score -= 4.0; }
        if post == 0 { score -= 20.0; } // perfect closure
        // Small class-based nudge: odd leftovers slightly penalized.
        score += (class as f64) * 0.3;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 15.0;
        } else if next_item_size < post {
            let r2 = post - next_item_size;
            if r2 % 10 == 0 { score -= 5.0; }
            score += (r2 % 10) as f64 * 0.2;
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += ((next_item_size - post).min(20) as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it is only
    // chosen when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.05 * (open_bins_count as f64);
    } else {
        // Prefer bins tighter than the mean residual (better packing).
        score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.15;
    }

    // Progress-based aggression: late in the stream, close bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0;
    if post == 0 { score -= progress * 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Reward leaving gaps that can plausibly host a future item.
        score -= (post_residual as f64).powf(0.35) * 3.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading out.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make opening a fresh bin mildly unattractive
    // unless existing bins would leave very poor fits.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.2;
        // Early in the stream, opening bins is cheaper; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit in the gap: penalize small leftover gaps more.
            if post_residual < next_item_size && post_residual > 0 {
                score += 6.0;
            }
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post_residual can host the next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
