    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves terrible residual.
    if bin_residual == bin_capacity {
        let lookahead_penalty = if next_item_size > 0 {
            (item_size as f64 + next_item_size as f64) / bin_capacity as f64
        } else {
            item_size as f64 / bin_capacity as f64
        };
        // Opening a new bin is attractive only if it enables a near-perfect 2-item fit.
        score += 60.0 - lookahead_penalty * 50.0;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
    }

    // Mild bonus for packing into already-open bins to limit bin count.
    score += (open_bins_count as f64) * 0.05;

    // Slight preference for tighter fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
