    }

    // New-bin candidate logic: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, decayed over the stream (amortization).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 45.0 * (1.0 - 0.4 * progress);
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            open_cost -= 20.0;
        } else {
            // Compare best possible fit in existing bins vs new bin.
            let best_existing_waste = post_residual; // placeholder; actual best unknown, use mean residual
            let mean_waste = mean_residual - item_size as f64;
            if mean_waste < 0.0 {
                open_cost += 10.0;
            } else if (best_existing_waste as f64) > mean_waste {
