        // Many open bins with large mean residual: prefer packing into them.
        open_cost += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += open_cost;
    } else {
        // Existing bin: slight bonus when its residual deviates favorably from mean.
        score += 0.1 * (bin_residual as f64 - mean_residual);
        // Prefer filling bins with small residuals first (best-fit bias).
        score += 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
