        score += 55.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that belong to "usable" classes.
    // Class 1: exact fit (post_residual == 0) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class 2: post_residual can host next item -> lookahead coupling.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space relative to lookahead item.
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Modulo classes on post_residual: residuals divisible by common size
    // granularities (e.g., 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Very small residuals are dead space unless near-zero class.
        if pr < 10 { score += 12.0; }
    }

    // Integer-division thresholds: residual fraction of capacity.
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.4 {
        // Wasteful fit into a mostly-empty bin when other bins could take it.
        score += 15.0 * frac;
    } else if frac > 0.2 {
        score -= 5.0; // sweet spot: fills bin to 60-80%
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are poor,
    // unless many bins are open with fragmented residuals.
    if bin_residual == bin_capacity {
        let base = 55.0;
        // If open bins are highly fragmented, opening fresh is fine.
        score = base + mean_residual * 0.2
            - (post_residual as f64 * 0.1)
            - if next_item_size > 0 && post_residual >= next_item_size { 20.0 } else { 0.0 };
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Progress coupling: late in the stream, prefer tighter packs.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    // Penalize gaps too small for the smallest plausible item (1..100 range),
    // especially gaps below the typical item scale.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 200.0; // tiny sliver: dead space
        } else if gap < 20.0 {
            score += 60.0;
        } else if gap < 30.0 {
            score += 20.0;
        }
        // Reward gaps that can still fit the next item (k=2 lookahead).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else if next_item_size > 0 {
            score += 25.0; // gap cannot host the lookahead item
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let pressure = open_bins_count as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += pressure * (1.0 - tightness) * 8.0;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 120.0;
        // If existing bins are crowded / few fit, opening is reasonable.
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 80.0;
        }
        // Late in the stream, prefer consolidating.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 40.0 * progress;
        }
    }

    // Mild preference for bins with below-average residual (fill emptier bins less,
    // keep larger residuals flexible)? Invert: prefer bins with residual close to item
    // size (best-fit character) beyond raw post_residual.
    score += 0.05 * (bin_residual as f64 - item_size as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits nonlinearly.
        let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 40.0 * tight * tight;

        // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0; // chain-perfect placement
            } else if next_item_size <= post_residual {
                // Next item fits: reward proportionally to how well it uses the leftover.
                let use_ratio = next_item_size as f64 / post_residual as f64;
                score -= 60.0 * use_ratio * use_ratio;
                // Reward leaving a residual close to next item size (small gap).
                let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
                score -= 30.0 * (1.0 - gap);
            } else {
                // Next item cannot use the leftover: penalize large dead space.
                score += 20.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            }
        }
    }

    // Penalize leaving residuals too small for typical items (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 80.0;
        // But if no other bin fits well, allow new bin (post_residual == capacity - item).
        if bin_residual - item_size <= 5 {
            score -= 200.0;
        }
        // Fewer open bins => slightly cheaper to open new bin.
        score -= (open_bins_count as f64).min(10.0);
    }

    // Prefer bins below mean residual (keeps residuals balanced) mildly.
    score += 0.3 * ((post_residual as f64) - mean_residual).max(-20.0).min(20.0);

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for plausible future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward leaving a residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin; mild penalty scaled by how much it misses.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Many open bins: discourage fragmenting further; few open bins: consolidation is cheaper.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).ln().max(1.0);
    score += 4.0 * pressure * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: only attractive when current fit is poor or no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = fit_ratio < 0.5;
        if poor_fit && (open_bins_count == 0 || fitting_bins_count == 0 || (post_residual as f64) > mean_residual) {
            score -= 50.0; // opening fresh space is worthwhile
        } else {
            score += 70.0; // prefer filling existing bins
        }
    }

    // Late-stream consolidation: as the stream ends, tighten packing aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * fit_ratio;

    // Mild preference for bins with above-average residual when the item is small.
    if (item_size as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual) mildly; late in the stream,
    // waste becomes more costly, so amplify the penalty on large residuals.
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward bins whose post_residual can still host the next item (smooth term).
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - fit_margin) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Encourage balancing residuals toward the mean (smooth quadratic).
    score += 2.0 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate: keep it competitive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress - 5.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fill is perfect, small residuals are dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else {
        // Dead-space penalty grows quadratically for residuals that few item sizes can fill.
        let r = post_residual as f64;
        score += 0.15 * r * r;
    }

    // Modulo-class: residual in a "friendly" class (divisible into common small sizes)
    // is more likely to be filled later.
    let friendly = (post_residual % 10 == 0)
        || (post_residual % 25 == 0)
        || (post_residual % 20 == 0);
    if friendly {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nr = next_item_size as f64;
            score -= 40.0 * (nr / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        score += 120.0;
        if mean_residual < 25.0 {
            score -= 100.0; // open bins are tight, new bin is fine
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap;
    score -= 50.0 * fill_ratio;

    // Late in stream: prefer closing bins (waste less residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / cap);

    // Prefer bins below mean residual (keep a spread of bin loads).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..100 range, treat <12 as likely dead)
    if post_residual > 0 {
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 3.0; // harsh penalty for tiny unusable slivers
        }
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Utilization coupling: prefer bins where item fills a large fraction of residual
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 12.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidating into existing bins
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * 2.5;

    // Last-chance bin: strongly favor using the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && post_residual as f64 <= mean_residual;
        if good_fit_exists {
            score += 10.0 + mean_residual * 0.2; // discourage opening new bin when decent fit exists
        } else {
            score -= 5.0; // encourage fresh bin when all fits are poor
        }
    }

    // Lookahead: if next item would fit the post-residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap unusable by next item: mild penalty scaled by gap size
        score += (post_residual as f64) * 0.15;
    }

    // Stream progression: early on, be slightly more conservative about bin count
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 1.5;

    // Prefer bins with residuals below the mean (tighter bins first)
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is barely above the item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).max(0.0);

    // 2-step lookahead: strongly reward exact match of next item into post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // partial credit proportional to how well next item fits
            let fit_frac = nr / post_residual as f64;
            score -= 30.0 * fit_frac;
        } else {
            // post_residual too small for next item: penalize dead space more
            // when next item is small (wasted capacity)
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste * (1.0 - nr / bin_capacity as f64);
        }
    } else {
        // last item: prefer minimal post_residual
        score -= 10.0;
    }

    // Relative to mean residual: bins below mean residual are more "committed";
    // filling them is good. Bins far above mean are fresh; penalize dumping large items there.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev.max(0.0);
    score -= 0.15 * (-dev).max(0.0);

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin early in the stream or when
    // many bins are open; encourage when item is large and fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress;
        score += 0.5 * open_bins_count as f64;
        if item_size >= 50 && next_item_size >= item_size {
            score -= 20.0; // large item with large next item: fresh bin useful
        }
    }

    // Slight bonus for filling bins with large items (compactness).
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fit bonus
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // small but usable gap: mild penalty
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if we wasted a lot.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or mean residual is too small to be useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        score += 20.0;                 // base cost of opening a new bin
        score -= 18.0 * congestion;    // worth it if many bins, little usable space
        score -= 10.0 * progress;      // late in stream, fresh bins keep options open
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            // fresh bin guarantees room for the next item too
            score -= 8.0;
        }
    } else {
        // Prefer bins with larger residual among equally tight fits (first-fit-decreasing flavor)
        score += 0.05 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Mild preference to spread load when many bins are open (reduces fragmentation).
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    // Tight fits rewarded more strongly as stream progresses
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tight * tight * (1.0 + progress) * 12.0;
