        } else if next_item_size <= post_residual {
            // bonus scaled by how well the next item fills the remainder
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 8.0 * fill;
        } else {
            // next item cannot use the remainder: penalize large dead space
            score += 0.05 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin fits well (this call's residual == capacity means the
    // item would sit alone in a fresh bin).
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 55.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If the item is large, a fresh bin is more acceptable.
        score -= 0.3 * (item_size as f64);
    } else {
        // Mild penalty for spreading across too many open bins.
        score += 0.15 * (open_bins_count as f64);
        // Prefer bins whose residual is close to the item (good fit density).
        let gap = (bin_residual as f64 - item_size as f64).max(0.0);
        score += 0.10 * gap;
        // Slight preference for bins below the mean residual (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Small deterministic tie-breaker via harmonic class of step index.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: prefer consolidating into existing bins.
    score += 3.0 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    if fitting_bins_count == 1 && bin_residual == bin_capacity {
        score += 25.0;
    }

    // New-bin candidate: only attractive when item barely fits elsewhere
    // or no open bin is a good fit (mean residual too small).
    if bin_residual == bin_capacity {
        score += 120.0;
        if mean_residual < item_size as f64 {
            score -= 60.0;
        }
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }
    // If next item won't fit anywhere in this bin's post residual and post residual is dead space, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Stream progression: early on, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight super-linear penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize proportional to leftover waste after both placements.
            score -= 20.0 - 0.15 * ((post_residual - next_item_size) as f64);
        } else {
            // Next item does NOT fit in this bin's remainder: penalize more as gap grows.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.10 * gap;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving a residual near the mean keeps bin population homogeneous (good for future packing).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, closing out bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral residual, discourage unless item is large relative to capacity.
        score = 0.55 * bin_capacity as f64 + 0.2 * (item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can host both current and next item
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // few alternatives: opening a new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Reward near-perfect fills heavily
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize dead space that cannot plausibly fit future items
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover can host the next item
            score -= 0.3 * post_residual.min(next_item_size) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer reusing existing ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when item is large and no tight fit exists
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 15.0 + 20.0 * (1.0 - big_item);
        // Late in the stream, opening new bins is fine (bins can be left partially filled)
        score -= 10.0 * progress;
    }

    // Global residual pressure: if mean residual is small, conserve space carefully
    score += 0.2 * (mean_residual - post_residual as f64).abs() * 0.1;

    // Mild preference for bins already below mean residual (balancing)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling: penalize large post-residual quadratically,
    // scaled by stream progress (dead space matters more later in the stream).
    let norm_post = post / cap;
    score += (norm_post * norm_post) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * cap * 0.35;

    // Interaction: post_residual vs mean residual — avoid making residuals uniform/wasteful.
    let dev = post - mean_residual;
    score += (dev * dev) / cap * (0.15 + 0.25 * progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * (0.6 + 0.4 * progress);
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize mildly.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 8.0 + 10.0 * progress;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so when good fitting bins exist.
    if bin_residual == bin_capacity {
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        score += cap * (0.8 + 0.5 * progress) + open_bonus * 6.0;
        if fitting_bins_count > 0 {
            score += cap * 0.5;
        }
    }

    // Small tie-break: prefer bins with more residual among equals (consolidation).
    score -= 0.001 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" classes (<= 10, <= 20) are nearly perfectly packed -> reward.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    } else if post_residual <= 30 {
        score -= 6.0;
    } else {
        // large leftovers are dead space, modulo structure: penalize classes
        // of post_residual in (30,60] more than (60,90] since mid-range gaps
        // fit fewer future item sizes (items are 1..100).
        let cls = (post_residual / 15) % 4; // 0..3 harmonic bucket
        score += cls as f64 * 4.0;
        score += (post_residual as f64 - 30.0) * 0.15;
    }

    // Lookahead coupling: reward residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 + (slack as f64).sqrt() * 2.0;
        // harmonic check: post_residual divisible-ish class with next item
        if post_residual % next_item_size.max(1) <= 5 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here anyway; mild penalty proportional to gap
        score += (next_item_size - post_residual) as f64 * 0.08;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins
    // would leave very poor fits (big post_residual) or none fit well.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; relax late in the stream when many
        // bins are open and mean residual is large (fragmentation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits -> must open
        } else if fitting_bins_count == 1 {
            // competing with the lone fitting bin; open new bin only if
            // that bin would leave a large dead class
            score += 8.0;
        }
        if open_bins_count > 0 {
            score += (mean_residual / bin_capacity as f64) * 12.0;
        }
    }

    // Slight preference for filling already-open bins over hoarding space
    // in low-fragmentation regimes.
    if bin_residual < bin_capacity {
        score -= mean_residual * 0.05;
    }

    // Tie-break by tightness ratio (harmonic fraction of capacity used).
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (items >= 1, but practically small gaps) are poison.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit is gold
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: prefer bins whose residual is near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // item fits poorly everywhere else (large post_residual in this bin).
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: neutral residual plus mild open-bin penalty
        score = post_residual as f64 + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin can also host the lookahead item
        }
        if fitting_bins_count > 0 && post_residual > 40 {
            score += 20.0; // don't open new bins when decent fits exist
        }
    }

    // Lookahead: if the next item exactly fills this bin's post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near matches to the next item (small dead space after next placement)
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 20.0_f64.min((post_residual - next_item_size) as f64 * -1.0).max(-20.0) * -1.0;
        score += (post_residual - next_item_size) as f64 * 0.25;
    }

    // Penalize creating unusable dead space (post_residual smaller than any plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (well-packed bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when open bins are all poor fits
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.5 };
        score = bin_capacity as f64 - 40.0 * pressure;
        if fitting_bins_count == 1 {
            score += 50.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness.powi(3);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual == next_item_size {
            // Perfect lookahead fit: strong reward.
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening new bins when many open bins already fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with number of usable open bins.
        if fitting_bins_count > 0 {
            score += 15.0 + 8.0 * (fitting_bins_count as f64).ln().max(0.0);
        } else {
            score -= 10.0; // no alternative: new bin is fine
        }
        // Early in the stream, opening bins is cheaper (future items can share).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: spread items across bins when mean residual is high,
    // concentrate when residuals are scarce.
    if mean_residual > 50.0 && bin_residual > mean_residual {
        score -= 3.0;
    } else if mean_residual < 20.0 && bin_residual < mean_residual + 10.0 {
        score -= 3.0;
    }

    // Mild penalty for leaving exactly unusable slivers (residual < min item size ~1).
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Slight preference for filling bins that are already partially used.
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // reward tight fits smoothly (non-linear in fill fraction)
    score -= 30.0 * fit_ratio * fit_ratio;
    // reward small residuals non-linearly (dead space penalty shaped)
    let rn = pr / capacity;
    score += 20.0 * rn * rn * rn;
    // progress coupling: late in stream, prefer conserving space in bins that can still host future items
    let future_need = next_item_size as f64 / capacity;
    let coupling = progress * (1.0 - progress) * 4.0;
    score += coupling * 25.0 * (future_need - rn).abs();
    // mean residual alignment: prefer bins near the mean residual (smooth)
    score += 5.0 * (pr - mean_residual) * (pr - mean_residual) / capacity;
    // scarcity pressure: few fitting bins -> favor using this bin
    if fitting_bins_count <= 1 {
        score -= 15.0;
    } else {
        score -= 5.0 / fitting_bins_count as f64;
    }
    // mild penalty for proliferating open bins when post-residual is large
    score += (open_bins_count as f64).ln() * rn * 3.0;
    // smooth lookahead bonus: if next item fits post_residual exactly-ish, reward
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / capacity;
        score -= 12.0 * (1.0 - gap) * (1.0 - progress);
    }
    // new-bin candidate: penalize opening new bins mildly, more early in stream
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward post_residuals that are divisible by small harmonic steps
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 5.0; }
        // Penalize awkward dead-space bands (hard-to-fill leftovers)
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 8.0; }

        // Perfect fit classes: leftover exactly matches a plausible next item size
        if next_item_size > 0 && pr == next_item_size { score -= 20.0; }
        if next_item_size > 0 && next_item_size <= pr {
            // next item fits here too: strong reward, scaled by leftover quality
            score -= 10.0 + (pr - next_item_size) as f64 * 0.05;
        } else if next_item_size > 0 {
            score += 6.0; // next item won't fit in this bin's leftover
        }
    } else {
        score -= 30.0; // exact fill is ideal
    }

    // Tightness coupling: fraction of bin used by this item
    let tightness = item_size as f64 / cap;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless existing bins are badly fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual - post_residual as f64).abs();
        score += 22.0 - frag * 0.2 - (open_bins_count as f64) * 0.5;
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for bins below mean residual (keep balanced spread)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward residuals that can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when a reasonable fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Late-stream conservatism: keep flexibility as stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chaining is ideal; loose chaining less so.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.25 * chain_slack;
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Dead space relative to the next item's needs.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    }

    // Compare against mean residual across open bins: prefer using bins
    // with below-average residual (more filled) to keep others flexible.
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += 0.35 * residual_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin, unless the current item fits nowhere well
    // (large dead space in all candidates) or the stream is early and spreading
    // capacity helps future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early stream: opening bins is cheaper; late stream: consolidate.
        score -= 25.0 * (1.0 - progress);
        // If no existing bin can fit the item, new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild penalty for leaving large awkward residuals (unusable gaps).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 4.0;
    }

    // Slight preference to fill bins with fewer open bins overall (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space: residuals that can only host tiny items.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0; // small dead space is often unusable
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else {
            score += 2.0; // leftover wasted w.r.t. lookahead
        }
        // Perfect chain fit: item + next item exactly fills capacity.
        if item_size + next_item_size == bin_residual {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer open bins unless this is a good moment.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only opened when fits are poor.
        score += 10.0;
        // As stream progresses, discourage proliferation of open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 3.0 * fitting_bins_count as f64;
        }
        // If mean residual across open bins is large, open bins are underused.
        if mean_residual > item_size as f64 {
            score += 4.0;
        }
        // Early stream with few bins: opening fresh bins is cheaper.
        if open_bins_count < 3 {
            score -= 8.0;
        }
    } else {
        // Mild bonus for consolidating into bins that are already partly used.
        score -= 0.02 * (bin_capacity - bin_residual) as f64;
        // Prefer bins with residual close to item (best-fit sharpening).
        let gap = (bin_residual - item_size) as f64;
        score += 0.03 * gap;
    }

    // Global pressure: when many open bins exist, pack tighter.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded quadratically.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize post_residual that cannot fit the lookahead item (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - post / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: only attractive when no good open fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        score += 18.0 * (1.0 - scarcity) + 8.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - post / cap);
    }

    // Mild preference for bins with residuals below mean (consolidation).
    score += 0.05 * (post - mean_residual);

    // Slight penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality classes
    // class 0 = perfect fit, small residuals are good
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    } else {
        // penalize residuals that no typical item can use (dead space)
        // items in 1..100; residual unusable if it's too small for common small items
        if pr < 10 {
            score += 5.0;
        }
        // modulo structure: residuals that are multiples of common item sizes are reusable
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        score += (pr % 7) as f64 * 0.8; // mild harmonic jitter penalty
    }

    // Coupling with next item: reward if next item fits post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // exact-ish match is even better
            let gap = pr - next_item_size;
            if gap <= 3 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize more if post residual is large (waste)
            score += (pr as f64) * 0.05;
        }
    } else {
        // last item: just minimize waste
        score = pr as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when fits are bad
    if bin_residual == bin_capacity {
        score = 60.0 + (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Slight preference for tighter bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / bin_capacity as f64) * (5.0 - 3.0 * progress);

    // Prefer bins whose residual is below mean (tighter packing)
    score += ((mean_residual - bin_residual as f64) * -0.05).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable small gap" zone
    // (below the minimum plausible item size) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score += 5.0; // mild penalty: keeps residual but consumes fit
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferating bins; mildly encourage filling
    // existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than the mean residual (waste-averse selection).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make empty bin attractive only when current bin would
    // leave a bad gap or no open bin fits well.
    if bin_residual == bin_capacity {
        if post_residual < 10 {
            score -= 20.0; // allow fresh bin over dead-space creation
        } else {
            score += 15.0; // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual near 0).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item (dead space).
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).min(1.0);
    }

    // Relative to mean residual: prefer bins tighter than the average.
    if mean_residual > 0.0 {
        score += 2.0 * ((post_residual as f64) - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: heavily reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling already-open bins over opening new ones; stronger early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    // Mild preference for bins with larger residual when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect/near-perfect fit bonus.
    if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize large dead space that nothing (size >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // unusable sliver is fine (already nearly full)
    } else if post_residual >= 10 && post_residual < item_size.min(30) {
        score -= 6.0; // moderate residual may still be usable
    } else if post_residual >= 30 {
        score += 4.0; // wasteful leftover
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing bins are crowded or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / (bin_capacity as f64) < 0.25;
        let poor_fit = (bin_capacity - item_size.min(bin_capacity)) as f64 > 40.0;
        // Early stream: keep bins open and compacted.
        score += 30.0 * (1.0 - progress);
        if crowded { score -= 20.0; }
        if poor_fit { score -= 15.0; }
        if open_bins_count == 0 { score -= 50.0; }
    } else {
        // Reward using bins whose residual is close to item size (good match).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * gap;
    }

    // Lookahead coupling: if the next item fits the post-residual well,
    // placing here sets up a chain; reward that.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 * chain_tightness;
        } else if is_new_bin && (bin_capacity as f64) - (item_size as f64) >= next_item_size as f64 {
            // New bin can host both items.
            score -= 8.0;
        }
    }

    // Mild penalty for scattering across many open bins.
    score += 0.3 * open_bins_count as f64;

    // Prefer bins below mean residual (compact them) when residual is plentiful.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * 4.0;
    score -= poly * cap * (0.6 + 0.4 * progress);

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.3 + 0.5 * progress);

    // Penalize dead space relative to mean residual
    score += 0.15 * (pr - mean_residual);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if next item fits into post_residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 0.05 * (nxt - pr);
        }
    }

    // Slight preference for reusing existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is much worse when it falls
    // into "unfillable" residue classes (below typical small item sizes).
    let small = 10u32.min(bin_capacity / 10).max(1);
    if post_residual > 0 && post_residual < small {
        score += 40.0; // unusable sliver
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit, bin closed
    }

    // Integer-division thresholds on post_residual (capacity fractions).
    let q1 = bin_capacity / 4;
    let q2 = bin_capacity / 2;
    let q3 = (3 * bin_capacity) / 4;
    if post_residual >= q3 {
        score -= 8.0; // large leftover still flexible
    } else if post_residual >= q2 {
        score -= 3.0;
    } else if post_residual >= q1 {
        score += 4.0; // mid-range leftover is awkward
    } else if post_residual > 0 {
        score += 12.0; // small leftover, low utility
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Harmonic bonus: bigger reward when slack is small but sufficient.
            score -= 10.0 + (slack as f64).sqrt() * 2.0;
        } else {
            score += 6.0; // next item cannot follow into this bin
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are bad,
    // but reward it when many bins already exist (limit open-bin sprawl).
    if bin_residual == bin_capacity {
        score += 15.0 - (open_bins_count as f64).min(15.0);
    }

    // Progress-aware tiebreak: later in stream, tighten packing (favor tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.3;

    // Coupling with mean residual: prefer bins close to the mean (balanced packing).
    score += ((post_residual as f64) - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
