pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are wasted space -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: nearly as bad as filling the bin perfectly,
            // but we lose the flexibility entirely.
            score += 40.0;
        } else if post_residual < item_size.min(30) {
            // Small gap unlikely to be reusable soon.
            score += 12.0;
        }
    } else {
        // Perfect closure of a bin is excellent: reward strongly.
        score -= 25.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.35 * open_bins_count as f64;

    // If this bin is the ONLY fitting bin, strongly prefer using it
    // (otherwise we waste the residual already committed there).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when it enables a good
    // pairing with the lookahead item or mean residuals are very low.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 {
            // Opening a fresh bin is good if next item would fit well
            // alongside current item in the leftover space.
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size && (leftover - next_item_size) < 15 {
                -18.0
            } else {
                0.0
            }
        } else {
            0.0
        };
        score += 30.0 + lookahead_bonus;
        // Less pressure to open new bins when few are open.
        score -= 0.2 * open_bins_count as f64;
    }

    // Lookahead synergy: if post_residual exactly fits the next item,
    // this placement is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 22.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual can still serve the next item: mild reward.
        score -= 6.0;
    }

    // Mean residual coupling: if this bin's residual is far below the
    // mean, it is an outlier worth filling down.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.1 * dev;
    }

    // Late in the stream, avoid leaving many half-empty bins: tighten up.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable leftovers (dead space below min item size).
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item + 9.0 {
            score += 20.0;
        }
        // Reward tight fits: smaller relative waste is better.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // 2-step lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves more waste: mild bonus scaled by tightness.
            let after_next = post_residual - next_item_size;
            score -= 100.0 - (after_next as f64);
        } else {
            // Next item won't fit here; penalize bins whose residual is just below next item
            // (wasted capacity the next item could have used elsewhere).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make the empty bin moderately attractive only when the current
    // item is large relative to capacity or fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Empty bin baseline: prefer using existing bins for small items.
        score += 60.0;
        // Large items justify opening fresh bins more readily.
        score -= fill_ratio * 80.0;
        // Late in the stream, avoid leaving many scattered partial bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 30.0;
    }

    // Slight preference for consolidating when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 90.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;  // marginal dead space
    }

    // Lookahead coupling: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Many competing bins => prefer the tightest; few bins => be more permissive.
    let crowding = (open_bins_count as f64).ln().max(1.0);
    score += 6.0 * (post_residual as f64) / crowding;

    // Mean-residual context: placing in a bin far below mean residual wastes spread.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.35 * dev; // prefer fuller-than-average bins

    // Time-horizon: early in stream, keep bins open and flexible; late, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    // New-bin candidate handling: empty bin has post_residual = capacity - item_size.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is good when: item is large, or no real alternative exists,
        // or the stream is early and flexibility is valuable.
        let large_item = item_size as f64 / bin_capacity as f64;
        let mut new_bin_bonus = -5.0 + 70.0 * large_item * large_item;
        if fitting_bins_count <= 1 {
            new_bin_bonus -= 30.0;
        }
        if progress < 0.3 {
            new_bin_bonus -= 15.0 * (0.3 - progress);
        }
        // If this bin would leave a huge awkward residual compared to alternatives, penalize.
        if post_residual > 40 && large_item < 0.5 {
            new_bin_bonus += 20.0;
        }
        score += new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;
    let post_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) tightening
    let mut score = pr as f64 + 40.0 * post_norm * post_norm;

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, waste is penalized more (quadratic in progress)
    score += 60.0 * post_norm * post_norm * progress * progress;

    // Tight-fit reward: non-linear in fill ratio, amplified over time
    score -= 30.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin, smoothly scaled
    if fitting_bins_count == 1 {
        score -= 50.0 + 30.0 * progress;
    }

    // Lookahead: reward leaving space for the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let diff = (pr - nx) as f64 / cap;
            score -= 20.0 * (1.0 - diff * diff);
        } else {
            let gap = (nx - pr) as f64 / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Penalize bins far from mean residual (non-linear dispersion term)
    let disp = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * disp * disp;

    // Mild penalty for proliferation of open bins
    score += 0.5 * (open_bins_count as f64).sqrt();

    // New-bin candidate: keep it slightly unattractive unless waste is severe
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items are 1..=100, so classify residual
    // into residue classes mod small integers to detect "reusable" vs "dead" space.
    let pr = post_residual;

    // Dead-space penalty: residuals that no plausible item (>=10) can fill well.
    if pr > 0 && pr < 10 {
        score += 40.0; // tiny unusable sliver
    } else if pr < 20 && pr > 0 {
        score += 12.0; // hard-to-fill zone
    }

    // Modulo-10 harmony: residual divisible by 10 aligns with typical item sizes.
    let mod10 = pr % 10;
    score -= (10 - mod10 as i64).abs() as f64 * 0.6;
    if mod10 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Modulo-5 secondary harmony.
    let mod5 = pr % 5;
    if mod5 == 0 {
        score -= 3.0;
    } else {
        score += mod5 as f64 * 0.8;
    }

    // Integer-division thresholds: residual in "half", "third", "quarter" bands.
    let cap = bin_capacity as f64;
    let frac = pr as f64 / cap;
    if frac >= 0.5 {
        score -= 10.0; // still roomy, good to keep open
    } else if frac >= 1.0 / 3.0 {
        score -= 4.0;
    } else if frac >= 0.25 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 - slack as f64 * 0.25;
        } else {
            // next item cannot fit here; penalize proportional to overshoot class
            let over = next_item_size - pr;
            score += (over / 10 + 1) as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer denser bins among many open bins.
    score += mean_residual * 0.15;

    // Stream progression: early on, be pickier about wasting space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * (1.0 - progress);

    // New-bin candidate: make empty bins mildly unattractive unless residuals are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    if post_residual > 0 {
        if post_residual < 10 {
