    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: mild penalty for blocking lookahead.
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    // (penalize the fresh-bin candidate implicitly by rewarding existing bins).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 4.0 * open_pressure;
    } else {
        // New-bin candidate: penalize when many bins are already open,
        // unless the current bin residual is too small for the item.
        score += 6.0 * open_pressure;
        // Allow new bin when mean residual of open bins is very low (all nearly full).
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Early in the stream, opening bins is cheaper (build diversity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

