    let next = next_item_size as f64;

    // Base: prefer minimal post residual (tight fits).
    let mut score = post;

    // Perfect 2-step lookahead: if the next item exactly fills the post residual,
    // this is an ideal chain placement — reward strongly.
    if next > 0.0 && (post - next).abs() < 0.5 {
        score -= 45.0;
    }
    // Near-perfect chain: next item leaves a small usable remainder.
    else if next > 0.0 && next <= post {
        let chain_waste = post - next;
        if chain_waste <= 10.0 {
            score -= 25.0 - chain_waste * 1.5;
        } else {
            score -= 8.0 / chain_waste.sqrt();
        }
    }
    // Next item does NOT fit here: post residual becomes dead space unless
    // small enough to be negligible. Penalize medium dead space.
    else if next > 0.0 && next > post {
        let dead = post;
        if dead > 25.0 {
            score += (dead - 25.0) * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when all
    // existing fits are poor. Give it a moderate baseline so tight fits win.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening new bins is less costly than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: placing into a bin whose residual is far
    // below the mean preserves large-space bins for larger future items.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score += residual_gap * 0.35;
    } else {
        score += residual_gap * 0.15;
    }

    // Mild penalty for very large open-bin sets (fragmentation pressure).
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small but usable.
    if post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        // Perfect fill is excellent.
        score -= 40.0;
    }

    // Penalize dead space that likely cannot be reused by the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward exact compatibility with the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when the item fits poorly
    // everywhere else or open bins are congested.
    if bin_residual == bin_capacity {
        let congested = (open_bins_count as f64).max(1.0) / (fitting_bins_count.max(1) as f64);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        if poor_fit || congested > 4.0 {
            score -= 8.0 + 0.3 * item_size as f64;
        } else {
            score += 35.0; // discourage opening new bins on good fits
        }
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (favor balance); late, pack tightly to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.15;

    // Global residual pressure: if mean residual is high, prefer filling
    // already-open bins rather than fragmenting space.
    if mean_residual > item_size as f64 {
        score -= 0.2 * (mean_residual - item_size as f64);
    } else {
        score += 0.2 * (item_size as f64 - mean_residual);
    }

    // Mild penalty proportional to open bins to encourage consolidation.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 8.0 * poly;

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }

    // Penalize bins far below mean residual (fragmentation)
    score += 3.0 * (mean_residual - bin_residual as f64).max(0.0) / cap;

    // Lookahead: reward post_residual matching next item size
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 4.0 * (diff / cap) * (1.0 - progress);
    }

    // Mild penalty for many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals that fall into "usable" harmonic
    // classes (multiples of common item sizes / small fractions of capacity)
    // are rewarded; awkward leftovers are penalized.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows super-linearly for tiny unusable leftovers.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // Harmonic class via integer division thresholds on post_residual.
        let class = pr / 10; // 0..=10 harmonic class
        // Reward residuals in classes that common items (10..80) can still fill:
        // class >= 1 means at least one minimum item fits.
        score -= (class as f64) * 2.5;

        // Modulo arithmetic: residuals close to multiples of 25 or 50 are
        // "harmonic" with capacity fractions and tend to pack well.
        let m25 = (pr % 25) as f64;
        let m50 = (pr % 50) as f64;
        score -= (25.0 - m25).abs().min(m25) * 0.15;
        score -= (50.0 - m50).abs().min(m50) * 0.20;
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this bin is a harmonic chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // Next item fits; the leftover after that also matters.
            let pr2 = post_residual - next_item_size;
            if pr2 < 10 {
                score += (10 - pr2) as f64 * 1.5; // would create new dead space
            } else {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much space would be stranded.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the stream is early (exploration phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = (post_residual as f64) / cap;
        // A new bin is attractive when the alternative leaves lots of dead
        // space, or early in the stream when spreading is cheap.
        score += 40.0 * (1.0 - progress) + 30.0 * fit_quality;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // next item needs a fresh bin anyway
        }
    }

    // Global context: when open bins already hold lots of slack on average,
    // prefer tightening the worst (largest-residual) bins.
    if (bin_residual as f64) > mean_residual {
        score += ((bin_residual as f64) - mean_residual) * 0.1;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are almost unusable
    // (items are >= 1 but typical useful chunks are larger); penalize hard.
    if post_residual >= 1 && post_residual <= 12 {
        score += (13 - post_residual as f64) * 8.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 6.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure on open bins count: opening new bins is costly, so penalize
    // the empty-bin candidate (bin_residual == bin_capacity) progressively.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
    } else {
        // Slight reward for using existing bins, scaled by how many are open.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Lookahead: if next item could use the leftover space, reward leaving
    // a usable gap; if the leftover is just below next_item_size, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a "junk drawer"; prefer consolidating into low-residual bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.15;

    // Early in the stream, be more willing to open bins (diversity); later,
    // consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let diff = post_residual as f64 - next;
            // Perfect chain: next item exactly fills the bin
            if diff == 0.0 {
                score -= 800.0;
            } else {
                score -= 300.0 * (1.0 - diff / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this bin's residual: penalize wasted space
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Compare residual against mean residual: prefer below-average residual usage
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when open bins can fit, scaled by stream progress
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 + 100.0 * progress;
        // New bin is acceptable if current item is huge and post_residual tiny
        if post_residual <= 20 {
            score -= 80.0;
        }
    }

    // Mild penalty for leaving large dead space relative to smallest item size
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.12;
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Lookahead: penalize if the next item would no longer fit after this placement.
    if next_item_size > 0 {
        if (post_residual as u64) < next_item_size as u64 {
            score += 8.0 + 0.15 * next_item_size as f64;
        } else {
            // reward bins that can still host the next item
            score -= 3.0 + 0.05 * (post_residual as f64 - next_item_size as f64);
        }
        // bonus if post_residual exactly matches next item (chaining perfect fits)
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for using a bin when many alternatives exist; prefer best fit anyway
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Dead-space penalty: residuals too small for the minimum item size are wasted.
    if post_residual < 1 {
        score += 15.0;
    } else if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 1.5;
    }

    // Global state coupling: if mean residual across open bins is high,
    // encourage filling existing bins rather than fragmenting.
    score -= 0.08 * mean_residual;

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Time horizon: early in the stream, keep bins flexible (penalize very low post_residual
    // slightly to preserve packing options); late in the stream, just fill bins greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 4.0 * (1.0 - progress / 0.3) * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: opening a new bin is only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when current bin fits are bad
        let bad_fit = (post_residual as f64 / bin_capacity as f64) > 0.5
            && next_item_size > 0
            && (post_residual as u64) < next_item_size as u64;
        if bad_fit {
            score -= 6.0;
        } else {
            score += 30.0 + 0.1 * open_bins_count as f64;
        }
        // late in the stream, opening bins is cheap since utilization is already high
        if progress > 0.7 {
            score -= 10.0 * (progress - 0.7);
        }
    }

    // Mild preference for bins with larger residual when item is large (avoid overflow-prone choices)
    if item_size > bin_capacity / 2 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual
    let fit = item_size as f64 / cap;

    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    // Smooth quadratic coupling of fill ratio with stream progress.
    let fill_bonus = (fit * fit) * cap * (0.6 + 1.2 * progress);
    score -= fill_bonus;

    // Penalize small-but-unusable post residual (dead space) with a smooth bump
    // centered at pr ~ 0.1 (worst leftover zone), decaying via cosine kernel.
    let dead = ((pr - 0.1) * std::f64::consts::PI / 0.2).cos();
    if pr < 0.2 {
        score += 8.0 * (0.5 - 0.5 * dead) * (1.0 + progress);
    }

    // Perfect-fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, reward using it to avoid
    // opening a new bin, scaled by how well the item fits.
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * fit;
    }

    // Lookahead coupling: if the next item would fit in the post residual,
    // reward preserving that compatibility; otherwise penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 4.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 3.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (concentrate waste) with smooth non-linear weighting.
    score += 0.5 * (mean_residual - (bin_residual as f64)) * (0.3 + 0.7 * progress);

    // Slight preference for using existing bins over opening new ones,
    // stronger late in the stream (new-bin candidate has bin_residual == cap
    // and thus a large raw post_residual, so it is naturally penalized).
    score -= 2.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).powi(2));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "clean" slots
    // (likely to be exactly filled by future items drawn from decile distributions).
    let residue_class = (post_residual % 10) as f64;
    if residue_class == 0.0 {
        score -= 6.0; // perfect harmonic slot: keep it tight
    } else {
        score += residue_class * 0.35; // penalize ragged dead space
    }

    // Integer-division thresholds: post_residual in "small pocket" is nearly dead
    let pocket = post_residual / 10; // 0..=10
    if pocket <= 1 && post_residual > 0 {
        score += 3.0; // tiny unusable sliver
    }
    if pocket >= 8 {
        score += 2.0; // large leftover: wasteful placement of a small item
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            let nres = post_residual - next_item_size;
            score -= 4.0 + ((10 - (nres % 10)) as f64) * 0.2;
        } else {
            score += 2.5; // next item won't fit here: this bin becomes terminal
        }
    }

    // New-bin candidate handling: only open a fresh bin when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win
        score += 14.0;
        // Relax penalty late in stream or when many bins are open (consolidation pressure)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * progress + (open_bins_count as f64).sqrt() * 0.8;
        // If this is the only fitting bin, opening new is fine
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // Opening a bin for a large item that leaves a harmonic residual is good
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly prefer using it to avoid opening a new bin
        score -= 9.0;
    }

    // Mild global pressure: prefer filling bins when mean residual is high
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item
    // (assume min item footprint ~ 10% of capacity) but not zero.
    let min_gap = bin_capacity as f64 * 0.10;
    if post_residual > 0 && (post_residual as f64) < min_gap {
        // The smaller the dead gap, the harsher the penalty (wasted space).
        score += (min_gap - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as f64) < min_gap * 0.5 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving a gap nothing can use.
        if post_residual > 0 && (post_residual as f64) < min_gap {
            score += 4.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a compact fit exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.15;

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: make the empty bin only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced under high open-bin pressure.
        score += 30.0 - (open_bins_count as f64 * 0.5);
        // If this item would leave a big gap in an open bin anyway, opening fresh is fine.
        if (post_residual as f64) >= min_gap {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits comfortably.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot follow into this bin: penalize proportionally to wasted potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize unusable dead space (fragmentation): small post_residual that fits nothing.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward filling bins tightly relative to the mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no open bin can fit the item, opening is attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If next item is huge, a fresh bin is a good host for it.
        if next_item_size > 0 && (next_item_size as f64) > 0.8 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Early in stream, be less conservative about opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    score *= 1.0 + (post_residual as f64) / bin_capacity as f64;

    // Penalize post-residual that the next item cannot use (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Reward leaving exactly the next item's size.
            score -= ((post_residual - next_item_size) as f64).abs().min(20.0) * 0.3;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 5.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when other bins fit, more so late in stream.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    } else if bin_residual == bin_capacity {
        // Fresh bin when nothing fits: mild penalty to prefer any fit.
        score += 5.0;
    }

    // Global state coupling: prefer filling bins when mean residual is low (bins nearly full).
    score += (mean_residual - post_residual as f64) * 0.15;

    // Slight preference for bins below mean residual (balance across bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Time-horizon term: early on, be conservative; late, squeeze bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic + cubic shaping of post-residual
    score += 12.0 * fit_norm * fit_norm - 8.0 * fit_norm * fit_norm * fit_norm;

    // Stream-progress interaction: later in stream, penalize large residuals more
    score += (1.0 + progress) * 10.0 * fit_norm * (1.0 - fit_norm);

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= (1.0 - progress) * 6.0 * (-pr / (0.25 * cap)).exp();

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Crowding penalty: many open bins -> prefer consolidation
    score += 0.3 * open_bins_count as f64 * fit_norm;

    // Lookahead coupling: if next item fits into post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - nxt / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual deviation: prefer bins deviating below mean residual (tighter bins)
    score += 0.5 * (mean_residual - pr).max(0.0);

    // Slight bias against opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - fit_norm) + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it fall in?
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1

    // Penalize dead space in "unusable" bands: residuals that no typical item (1..=100)
    // can pair with well are small residuals. Reward near-zero post residual strongly.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else if post_residual <= 50 {
        score += 3.0;
    }

    // Modulo-class logic on post_residual: residuals that are multiples of common
    // item sizes are more likely reusable by future items.
    let reusable_mod = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 20 == 0);
    if reusable_mod {
        score -= 8.0;
    } else {
        score += (post_residual % 10) as f64 * 0.6; // ragged remainders are less useful
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
            score -= 10.0 + 20.0 * snug;
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin is decent.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (scaled by stream progress).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 + 20.0 * progress;
        // But if current bin fit is terrible (large ragged post residual) and next item
        // is large, opening fresh is attractive.
        if next_item_size > post_residual && post_residual < 20 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins? no:
    // prefer filling bins tighter than average to keep large residuals available).
    if post_f < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Slight preference to keep many open bins from proliferating: favor existing bins
    // when several fit.
    if fitting_bins_count > 2 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate penalty for gaps that only fit tiny items.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count and stream progress.
        score += 20.0 + 8.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // But if no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if open_bins_count > 1 {
        score -= 5.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize if next item is large and this placement leaves a bad gap.
    if next_item_size > post_residual && post_residual < next_item_size {
        score += 3.0;
    }

    // Slight preference for filling bins below mean residual (consolidating space).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 50.0;
        } else if post_residual as i64 > next_item_size as i64 {
            // next item still fits after: mild reward proportional to closeness
            score -= (10.0 / (1.0 + gap)) - 5.0 * (gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted residual
            score += 3.0 + 0.15 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize creating tiny unusable slivers (< 10) that nothing can fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 6.0 + 0.1 * open_bins_count as f64;
    }

    // Late in stream, be more frugal with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize unusable dead space: post residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins where the NEXT item also fits in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    }
    // Penalize if next item nearly fits but not quite (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits for the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 18.0;
        // Attractive if the item is large and nothing fits well.
        let fit_quality = (bin_residual - item_size) as f64;
        let global_pressure = mean_residual / bin_capacity as f64;
        if fit_quality < 5.0 && global_pressure < 0.25 {
            score -= 30.0; // item nearly fills a fresh bin; go new
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins with slack: discourage new bins.
        score += open_bins_count as f64 * 0.6;
        score += mean_residual * 0.15;
    } else {
        // Prefer fuller bins (best-fit bias) scaled by how full the bin is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 8.0;
        // Slight bonus for using bins when many are open (avoid bin sprawl).
        score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Mild time-dependent tightening: early on, be more exploratory (less penalty),
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit rewarded (low post residual), normalized.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste is cheap (bins plentiful); late, waste is costly.
    let waste_penalty = (pr / cap).powi(2) * (0.5 + 2.0 * progress * progress);
    score += waste_penalty;

    // Smooth cubic term: mid-stream, prefer leaving moderately usable residuals.
    let usable = (pr / cap) * (1.0 - pr / cap); // peaks at half-full residual
    score -= 0.6 * usable * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.5 * (pr - nxt) / cap * (1.0 + progress);
        } else {
            score += 0.3 * (nxt - pr) / cap;
        }
    }

    // Slight penalty for very full bins early (keep flexibility), none late.
    score += 0.2 * (1.0 - progress) * (item_size as f64 / cap);

    // Mean residual coupling: prefer bins deviating below mean (tighten tight bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.25 * dev * dev * (0.5 + progress) - 0.15 * dev;

    // New-bin candidate: penalize slightly unless nothing fits well late.
    if bin_residual == bin_capacity {
        score += 0.4 - 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward placements that leave residuals in "useful" harmonic classes.
    // Classes: multiples of 10 (well aligned with typical item sizes) are best.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 8.0;
    } else if cls <= 2 || cls >= 8 {
        score -= 3.0;
    }

    // Penalize tiny unusable residuals (dead space < 10 can never be filled).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (creates a chain of harmonic fills).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let chain = post_residual % next_item_size;
            score -= (next_item_size as f64) * 0.15;
            if chain == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's leftover: slight penalty for
            // leaving residual in a narrow band the stream can't exploit.
            score += 2.0;
        }
    }

    // Fractional capacity coupling: prefer residuals near half or full capacity
    // mid-stream (flexibility), prefer tight fills near the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if frac > 0.45 && frac < 0.55 {
        score -= 4.0 * (1.0 - progress);
    }
    if frac < 0.2 && post_residual >= 10 {
        score += 3.0 * progress; // small leftovers less valuable late
    }

    // Last-chance bin: avoid opening a new bin if this bin fits reasonably.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // fragmented (high mean residual spread) or residual is very tight.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = cap * 0.85;
        if open_bins_count == 0 {
            score = 0.0;
        }
        // Open a new bin if open bins are nearly full on average.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        // Open a new bin if the item is large and residuals are fragmented.
        if item_size > 60 && mean_residual > 40.0 {
            score -= 15.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        if progress > 0.8 {
            score += 10.0;
        }
        // If next item is huge, keep a fresh bin ready.
        if next_item_size > 70 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for any
    // plausible future item (sizes can be as small as 1) are pure waste, but
    // gaps below a "useful threshold" are especially toxic.
    let useful_threshold = 20.0;
    if (post_residual as f64) < useful_threshold {
        // Unusable sliver: penalize quadratically beyond the base score.
        score += (useful_threshold - post_residual as f64) * 3.0;
    }

    // Perfect / near-perfect fits are gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward; if the next item would NOT fit in the post residual but would
    // fit elsewhere, mild penalty for blocking it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already small; encourage consolidation when mean residual is high.
    let mean_r = mean_residual;
    if (post_residual as f64) < mean_r {
        score += 5.0; // creating below-average residual fragments the stream
    } else {
        score -= 3.0;
    }
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate handling: an empty bin is a fresh, flexible resource.
    // Only open a new bin when no open bin offers a decent fit, i.e. when the
    // best alternative would leave a bad gap. Penalize the new bin mildly so
    // that reasonable fits in existing bins win, but not so much that a bad
    // fit (tiny post residual) beats it.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.5;
        // Late in the stream, be slightly more willing to open new bins since
        // leftover flexibility matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If next item is large and would need a big bin anyway, opening now
        // is attractive.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits into the post-residual,
    // this placement is doubly good (chains two items into one bin).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let chain_residual = post_residual - next_item_size;
            // Reward chaining, penalize leaving awkward slivers the next item can't use.
            if chain_residual <= 10 {
                score -= 150.0;
            } else {
                score -= 30.0 - (chain_residual as f64).min(60.0);
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Coupling with mean residual: prefer bins that are tighter than average
    // (fills nearly-full bins first), but avoid extremely fragmented ones.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.5;
    } else {
        score += (res_f - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large or no good fits exist; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (bin_capacity as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 90.0 - 60.0 * pressure - 200.0 * scarcity;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
    }

    // Mild penalty for leaving medium dead-space that few item sizes can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let prn = pr / cap;
    let pr2 = prn * prn;

    // Tight fits rewarded more strongly as stream progresses (waste less early slack)
    let tightness = (1.0 - prn).powf(2.0);
    score -= 30.0 * tightness * (0.5 + 1.5 * p2 + p3);

    // Penalize large residual quadratically, ramping with progress
    score += 40.0 * pr2 * (0.3 + 1.2 * progress) * (1.0 + 0.5 * p3);

    // Dead-space penalty: residual too small for typical future items
    if prn > 0.0 && prn < 0.1 {
        score += 15.0 * (0.1 - prn) * (1.0 + 2.0 * progress);
    }

    // Lookahead: reward if next item fits in post_residual (smooth cubic coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = 1.0 - ((pr - nxt) / cap);
            score -= 20.0 * slack * slack * (0.4 + 1.6 * progress);
        } else {
            let miss = ((nxt - pr) / cap).min(1.0);
            score += 10.0 * miss * miss;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: keep it attractive early, discourage as stream progresses
    if bin_residual == bin_capacity {
        let openness = (1.0 - progress).powf(2.0);
        score = 5.0 + 60.0 * openness + 20.0 * prn * (1.0 - progress);
    }

    // Mild regularization against bin sprawl
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions
    let item_class = (item_size * 4) / bin_capacity; // 0..3 (tiny, small, medium, large)
    let next_class = if next_item_size == 0 { 255 } else { (next_item_size * 4) / bin_capacity };

    // Reward near-perfect fills: post_residual in tiny dead-space classes
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space in "unfillable" residue classes:
    // residuals that no typical item (1..100) can pair with efficiently
    let dead_zone = post_residual > 0 && post_residual < 10 && post_residual % 2 == 1;
    if dead_zone {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // prefer leaving room divisible into harmonic classes
            let fit_slack = post_residual - next_item_size;
            if fit_slack <= 5 {
                score -= 18.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: penalize more if we waste a large residual
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tighter fits (already captured by post_residual)
        score += (fitting_bins_count as f64) * 0.5;
    }

    // Class-aware penalty: placing a large item into a nearly full bin is good,
    // placing a small item into a fresh bin wastes it
    if item_class >= 2 {
        score -= 5.0;
    } else if item_class == 0 && bin_residual == bin_capacity {
        // small item into brand-new bin: discourage unless nothing else fits
        score += 15.0;
    }

    // Mean residual context: if the fleet average is low, tighten selection
    score += (mean_residual - post_residual as f64) * 0.1;

    // Progress-based pressure: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Integer division threshold on post_residual: quarter-bin harmonics
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual < 2 * quarter {
        // residual in [25,50): moderately reusable
        score += 3.0;
    } else if post_residual >= 2 * quarter {
        // residual >= 50: very reusable, but only if a large item remains
        if next_item_size >= 2 * quarter {
            score -= 10.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 6.0 * open_bins_count as f64 + 10.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 5.0; // gap unusable for the known next item
    }

    // Prefer bins below mean residual (consolidate space usage).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fit is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space quadratically, normalized by capacity.
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += 50.0 * dead_frac * dead_frac;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly fit the next item (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Chainable but not perfect: mild bonus proportional to slack.
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize small post residuals
            // that become dead space relative to the lookahead item.
            let waste = next_item_size - post_residual;
            score += 20.0 * (waste as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins below mean residual are
    // already "full-ish"; prefer packing into them (smaller score).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a brand-new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty for new bin; reduced if many open bins are congested
        // or if this is early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 300.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 150.0; // new bin offers good lookahead chain
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 400.0; // nothing fits, must open
        }
        new_bin_penalty -= 100.0 * (1.0 - progress);
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Penalize dead space: residual too small to hold typical future items
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // prefer opening new bin early or when open bins are crowded
        let new_bin_bonus = 20.0 * (1.0 - fragmentation) + 15.0 * (1.0 - progress);
        score -= new_bin_bonus;
        // but discourage hoarding many open bins late in the stream
        score += 3.0 * open_bins_count as f64 * progress;
    }

    // Global balance: prefer bins whose residual is below the mean (fill fuller bins)
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * pr_norm);

    // Smooth dead-space penalty: quadratic in normalized post-residual.
    score += 40.0 * pr_norm * pr_norm * (0.5 + 0.5 * progress);

    // Reward tight fits (post_residual near zero) with a smooth bump.
    score -= 15.0 * (1.0 - pr_norm).powi(3) * (1.0 - item_norm);

    // Penalize wasting a last-chance bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - pr_norm);
    }

    // Lookahead: bonus if next item fits well in post-residual.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let gap = (pr_norm - next_norm).abs();
        score -= 10.0 * (1.0 - gap.min(1.0)) * (1.0 - progress);
    }

    // Mild preference for fuller bins as stream advances.
    score -= 5.0 * progress * (1.0 - pr_norm) * (mean_residual / cap);

    // New-bin candidate: penalize opening new bins unless current bin leaves bad dead space.
    if bin_residual == bin_capacity {
        score += 8.0 + 25.0 * (1.0 - item_norm) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: leftovers smaller than a quarter are hard to reuse.
    if post_residual < quarter {
        score += (quarter - post_residual) as f64 * 1.5;
    } else if post_residual <= half {
        // Sweet spot: leftover that can host medium items — reward.
        score -= 6.0;
    } else {
        score -= 2.0;
    }

    // Exact-fit reward via modulo structure on post_residual.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Coupling with next item (lookahead k=2): does the leftover admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainable bin: reward, more so if next item fills it well.
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(20.0) * 0.3;
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post-residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < eighth {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only if the current
    // item is large relative to capacity or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Prefer new bin when existing residuals are fragmented (low mean) and item is big.
        let new_bin_bias = 20.0 + item_size as f64 * 0.4 - fragmentation * 30.0 - progress * 5.0;
        score += new_bin_bias;
        // Never open a new bin for a tiny item.
        if item_size <= quarter {
            score += 25.0;
        }
    } else {
        // Slight preference for tighter existing bins (lower residual before placement).
        score += (bin_residual as f64) * 0.05;
        // Diversification: when many bins are open, mildly discourage hoarding in one bin.
        if open_bins_count > 3 {
            score += open_bins_count as f64 * 0.2;
        }
    }

    // Stream-phase modulation: late in the stream, avoid creating small leftovers.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < eighth && post_residual > 0 {
        score += progress * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin before opening a new one: reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > 10 {
        // Next item cannot use the leftover gap -> mild penalty for wasteful split.
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + 2.0 * progress);

    // Brand-new empty bin candidate: make it unattractive unless existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 120.0 + 8.0 * open_bins_count as f64;
        // If no open bin fits well (this is the only fitting option), soften the penalty.
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
    }

    // Slightly prefer bins with residuals close to the item (tight fit).
    score += 0.3 * ((bin_residual - item_size) as f64 - post_residual as f64).abs();

    // Penalize placement into bins whose residual deviates far from the mean (fragmentation).
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

