    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 500.0; // chains a perfect fit for the next item
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to wasted lookahead potential
        score += 25.0;
    }

    // Penalize small unusable dead space (< min item size 1..100, use 20 as dead-space threshold)
    if post_residual > 0 && post_residual < 20 {
        score += 40.0;
    }

    // Prefer bins with residual below mean (tighter bins fill first)
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 20;
        score += if poor_fit { 500.0 } else { 150.0 };
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0; // fresh bin can host the next item too
        }
    }

    // Mild late-stream consolidation pressure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post-residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
