        }
    }

    // Mild pressure toward bins with residual above the mean (consolidate slack).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 4.0;
        } else {
            score += 4.0;
        }
    }

    // Prefer filling more crowded bins slightly (fewer partially used bins).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on wasted space (non-linear coupling)
    let mut score = pr * pr / cap;

    // Smooth non-linear interaction between waste and stream progress:
    // waste matters less early, more later (tighter packing pressure over time)
    let coupling = 1.0 + progress * (pr / cap);
    score *= coupling;

    // Reward tight fits: subtract a smooth function of normalized fit quality
    let fit_quality = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= fit_quality * fit_quality * 12.0;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild preference for bins with below-mean residual (balance open bins)
    let resid_norm = bin_residual as f64 / cap;
    let mean_norm = mean_residual / cap;
    score += 3.0 * (resid_norm - mean_norm);

    // Lookahead: penalize leaving a residual that only barely fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // residual too small for next item -> dead space penalty
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // New-bin candidate: neutral-to-slightly-high base so it's chosen only
    // when all open bins would leave large waste
    if bin_residual == bin_capacity {
        score = cap * 0.35 + 10.0 * (1.0 - progress);
        // allow new bin late in stream when waste in existing bins is high
        if mean_residual / cap > 0.35 && fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space
    // in coarse capacity-fraction bands (0 = perfect, 5 = nearly empty bin).
    let q = post_residual * 5 / bin_capacity; // 0..=5 harmonic class
    let class_penalty = match q {
        0 => -60.0, // perfect fit: strongly reward
        1 => -25.0, // leaves a slot for a small item
        2 => -5.0,  // half-full leftover, still flexible
        3 => 15.0,  // awkward dead zone
        4 => 35.0,  // large dead space
        _ => 0.0,   // near-empty bin class, neutral
    };
    score += class_penalty;

    // Integer-division threshold on post_residual vs next item:
    // reward when the lookahead item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (next_item_size as f64) * 0.3;
        } else {
            // dead space for the known next item: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            // modulo coupling: residuals near multiples of common small sizes
            // (10/20/25/50) are statistically reusable
            let pr = post_residual;
            if pr % 10 == 0 && pr > 0 { score -= 8.0; }
            if pr % 20 == 0 && pr > 0 { score -= 6.0; }
            if pr % 25 == 0 && pr > 0 { score -= 6.0; }
            if pr % 50 == 0 && pr > 0 { score -= 10.0; }
        }
    } else {
        // last item: only the immediate fit matters
        if post_residual == 0 { score -= 80.0; }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: brand-new empty bin. Prefer it only when the
    // item is large relative to capacity or open-bin residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // large items deserve a fresh bin; small items should use leftovers
        let size_pull = (item_frac - 0.45).max(0.0) * 120.0;
        // fragmentation pressure: many open bins with high mean residual
        let frag = (open_bins_count as f64) * (mean_residual / bin_capacity as f64) * 4.0;
        score -= size_pull + frag;
        // late in the stream, avoid spawning bins for marginal gains
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Mild global pressure: prefer already-open bins when many are open
    score += (open_bins_count as f64) * 0.15;

    // Tie-break: slightly prefer tighter fits beyond the class bands
    score += (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Gap too small for any item (min size 1..100 stream: keep threshold conservative)
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 10.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight packing.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: an empty bin is attractive only if current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap - item_size as f64 + 12.0 + (open_bins_count as f64) * 0.8;
        // If the next item is large and would waste this fresh bin, penalize slightly.
        if next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Mild stream-progression term: later in stream, slightly favor using existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 3.0 * progress * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let post = post_residual as f64;

    // 2-step lookahead: reward when post_residual matches the next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_err = (post - nx).abs();
        // Strong reward for a near-perfect chain fit (item then next item).
        score -= (100.0 - match_err).max(0.0) * 0.35;
        // Penalize leaving residual the next item cannot use (dead space).
        if nx > post {
            score += (nx - post) * 0.8;
        }
        // Perfect chain fill bonus (item + next item exactly fills bin).
        if (item_size as f64 + nx - (bin_capacity as f64)).abs() < 0.5 {
            score -= 60.0;
        }
    }

    // Penalize large dead space that likely becomes unusable (items up to 100,
    // but small residuals < 10 are almost always dead).
    if post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins already tighter than average.
    score += (post - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        // Neutral-ish base; penalize so we prefer reusing bins with decent fits.
        score += 30.0 + 0.5 * (item_size as f64);
        // If the next item chains perfectly into a fresh bin, allow opening it.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 80.0;
        }
    }

    // Late in the stream, consolidate more aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item (size >= 10) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // this is a great chain placement; reward it proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't chain here: mild penalty scaled by how far off we are.
        score += 3.0 * ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins are poor fits or the stream is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (open_bins_count as f64).ln().max(0.0);
        // Base penalty so open bins are preferred, growing with stream progress
        // and number of open bins (more fragmentation => more reluctant to open).
        let mut new_bin_penalty = 30.0 + 8.0 * fragmentation * (1.0 + progress);
        // If the current item is large relative to mean residual of open bins,
        // opening a fresh bin becomes more attractive.
        let avg_room = mean_residual.max(0.0);
        if (item_size as f64) > avg_room + 0.5 * bin_capacity as f64 {
            new_bin_penalty -= 20.0;
        }
        // Late in the stream, avoid opening bins that will be nearly empty forever.
        if progress > 0.85 {
            new_bin_penalty += 15.0 * progress;
        }
        score += new_bin_penalty;
    }

    // Mild global pressure: when many bins are open with high mean residual,
    // encourage consolidation into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        let fill_fraction = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * fill_fraction * (1.0 + progress);
        // Prefer bins already below mean residual (i.e., fuller than average).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Discourage leaving residuals that only match tiny items (10-20 range)
    // when the stream is still young; usable space is more valuable early.
    if post_residual >= 10 && post_residual <= 20 && progress < 0.5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post residual, with non-linear polynomial coupling to progress.
    // Early in the stream, larger residuals are more acceptable (future items can fill them),
    // so the penalty on pr is scaled down; late in the stream, dead space is costly.
    let progress_coupling = 0.5 + 1.5 * progress * progress;
    let mut score = pr * progress_coupling;

    // Non-linear penalty on unusable dead space: residual too small for the smallest item.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * dead * 40.0 * (0.5 + progress);

    // Reward tight fits (small post_residual relative to capacity) with a smooth term.
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * tightness * 15.0;

    // Lookahead coupling: bonus if the next item fits into the post residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 10.0 * fit_quality * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 5.0 * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly in open bins (large post_residual elsewhere) or few bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 30.0 + 5.0 * open_pressure;
        // Late in the stream, consolidation matters more: make new bins costlier.
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is high (fragmentation).
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 act as "dead-space classes".
    let post = post_residual as i64;
    let residue = (post % 10) as f64;
    // Perfect-fill reward: exact fit is always ideal.
    if post == 0 {
        score -= 1000.0;
    }
    // Small usable residuals (<= next item) are valuable; large odd residues are dead space.
    if next_item_size > 0 {
        let next = next_item_size as i64;
        if post >= next {
            // This bin can also serve the next item: strong reward, scaled by tightness.
            score -= 30.0 + (post - next) as f64 * -0.2;
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += (next - post) as f64 * 0.5;
        }
    }
    // Modulo-10 class penalty: residuals like 5..9 are hard to fill later.
    score += match post % 10 {
        0 => -8.0,
        1..=4 => residue * 0.4,
        5..=9 => residue * 0.9,
        _ => 0.0,
    };
    // Integer-division thresholds: quarter classes of capacity.
    let quarter = post / 25;
    score += match quarter {
        0 => -5.0,          // nearly full bin: good, close it out
        1 => 2.0,
        2 => 6.0,
        _ => 10.0 - post as f64 * 0.05, // half-empty: less attractive than fresh bin
    };
    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // New-bin candidate: baseline cost so it only wins when open bins are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 2.0;
        // Opening a new bin is good if next item is large and this item is small.
        if next_item_size > 50 && item_size < 40 {
            score -= 15.0;
        }
    }
    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - (post as f64 / bin_capacity as f64));
    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky when the next item can't use them.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // keeps a slot usable for the lookahead item
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 18.0; // gap becomes dead relative to lookahead
        }
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0; // extra penalty for ignoring existing fitting bins
        }
    } else {
        score -= 5.0; // mild preference for reusing open bins
    }

    // Mean residual coupling: bins far below mean residual are good filler candidates.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early stream: be slightly more liberal with new bins (future packing flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect/near-perfect match with next item.
    if next_item_size > 0 {
        let slack = post_residual as f64;
        let nxt = next_item_size as f64;

        if nxt <= slack {
            // Next item fits in the post residual: reward tight chains.
            let gap = slack - nxt;
            // Strong reward for exact two-item completion.
            if gap <= 1.0 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item will NOT fit here: penalize leaving awkward leftovers,
            // scaled by how badly the next item misses.
            let miss = nxt - slack;
            score += 8.0 * (miss / bin_capacity as f64).min(1.0);
        }

        // Penalize residuals that are too small for typical future items
        // (dead space): anything below the smallest plausible item (size 1).
        if slack > 0.0 && slack < 10.0 {
            score += 12.0 * (1.0 - slack / 10.0);
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score -= 15.0;
    }

    // Relative-to-mean coupling: prefer bins with below-average residual
    // (tighten the fullest bins first), penalize far-above-average ones.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make the fresh bin attractive only when
    // the item is large relative to typical open-bin residuals, otherwise
    // discourage wasting a fresh bin.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        // Fresh bin reward grows with item size and fitting scarcity.
        score -= 30.0 * pressure * scarcity;
        // But penalize opening new bins when existing residuals are large.
        score += 0.25 * mean_residual;
        // Late in the stream, opening new bins is less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is already good; amplify exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        let dead = post_residual as f64 / bin_capacity as f64;
        // Penalize dead space super-linearly if it can't fit a typical small item (>=10 assumed min, but sizes 1..100: use item_size as reference)
        if post_residual < item_size.min(next_item_size.max(1)) {
            score += dead * 40.0;
        }
        // Nonlinear penalty on wasted residual
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 25.0; // keeps a usable slot for the next item
        } else {
            score += 10.0; // next item won't fit here; mild penalty
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, scaled by how many bins already fit.
        let fit_pressure = if fitting_bins_count == 0 { -300.0 } else { 250.0 * (fitting_bins_count as f64) };
        score += fit_pressure;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 80.0;
        // Few open bins relative to mean residual: opening new bin wastes potential.
        if mean_residual > item_size as f64 * 1.5 {
            score += 60.0;
        }
    }

    // Prefer fuller bins: subtract proportional fill fraction.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Global state: many open bins with high mean residual -> encourage filling existing ones.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize residual that cannot fit next item (dead space), smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).max(0.0);
        score += 0.15 * gap * gap / cap;
        // Reward if next item fits snugly in post_residual.
        if n <= pr {
            score -= 8.0 * (1.0 - (pr - n) / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (pr / cap);

    // Smooth polynomial term coupling residual with mean residual.
    let mr = mean_residual / cap;
    score += 6.0 * (pr / cap) * (pr / cap) * (1.0 - mr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by integer division.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Harmonic buckets: post_residual / (capacity / 8) classes.
        let class = post_residual * 8 / bin_capacity; // 0..7
        match class {
            0 => score -= 40.0,   // tiny dead space, nearly perfect
            1 => score -= 10.0,
            2 => score += 5.0,
            3 => score += 12.0,
            4 => score += 20.0,   // mid dead space, worst reuse potential
            5 => score += 12.0,
            6 => score -= 5.0,
            _ => score -= 25.0,   // large residual still broadly usable
        }
        // Modulo harmony: post_residual divisible by small item classes (10s)
        // is more likely to be filled later; reward such residuals.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 20 == 0 {
            score -= 6.0;
        }
        // Penalize residuals in the awkward band (just above common item sizes).
        if post_residual > 1 && post_residual < 10 {
            score += 30.0; // unusable dead space
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Harmonic class of the slack after the next item.
            if slack == 0.0 {
                score -= 60.0;
            } else if slack < 10.0 {
                score += 15.0;
            } else {
                score -= slack * 0.3;
            }
        } else {
            // Next item won't fit here; mild penalty scaled by gap.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that
    // decreases as the stream progresses (later items prefer consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = cap * 0.9 - progress * 20.0;
        // Avoid opening new bins when a decent fit exists elsewhere.
        if post_residual == cap as u32 && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Congestion control: many open bins with high mean residual -> prefer
    // filling existing bins harder (avoid bin sprawl).
    if open_bins_count > 3 && mean_residual > cap * 0.35 {
        score += 10.0;
    }

    // Mild global pressure to prefer tight fits overall.
    score += (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to remaining space.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 15.0 + 2.0 * open_bins_count as f64 + 30.0 * progress;
        // If no open bin fits, opening may be necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Reward using existing bins, more when many bins are open.
        score -= 1.5 * open_bins_count.min(20) as f64;
        // Last-chance bin: strongly favor using it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits in the post-residual, reward leaving that gap.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Gap won't fit next item: penalize as dead space.
        score += 8.0;
    }

    // Mild preference for bins below mean residual (keeps larger gaps spread out).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but reward exact 2-step matches harder.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: post_residual exactly fits the next item -> strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize leftover that next item cannot use at all (dead space for lookahead).
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.8;
            } else {
                // Slack larger than next item: mildly reward, scaled by how much is wasted beyond the match.
                score -= (next_item_size as f64) * 0.3;
                score += diff * 0.15;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless residuals are all poor.
    if bin_residual == bin_capacity {
        let tightness = if post_residual < next_item_size && next_item_size > 0 {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        // Opening a new bin costs ~1 unit of capacity waste; only attractive when
        // existing bins would leave big unusable remnants or are nearly full.
        score += 70.0;
        score -= tightness * 0.6;
        // Late in the stream, opening new bins is more acceptable (no need to hoard).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
    }

    // Mild preference for bins whose residual deviates favorably from the mean
    // (concentrate waste in few bins rather than spreading it).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
        // Prefer filling already-low bins (less fragmentation).
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Small nudge toward fewer open bins when many are open (encourage consolidation).
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically.
    score += (post_residual as f64) * (post_residual as f64) * 0.02;

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + 0.3 * slack.max(0.0) * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize proportionally to dead space.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, discounted when many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 60.0 - 20.0 * progress;
        // If existing bins would leave large dead space, opening a new bin is better.
        let waste_here = post_residual as f64;
        new_bin_score -= 0.5 * (waste_here - 0.0).min(30.0);
        // If the current item is large relative to mean residual, prefer new bin.
        if (item_size as f64) > mean_residual {
            new_bin_score -= 15.0;
        }
        score = new_bin_score;
    }

    // Slight preference for filling bins with smaller residuals (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - post_residual as f64).max(0.0);

    // Encourage consolidating residuals toward the mean when many bins are open.
    if open_bins_count > 2 && !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.02 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r_norm = pr / cap;

    // Base: prefer low post-residual (tight fit), non-linearly.
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post-residual with stream progress.
    // Early in the stream: mild penalty for slack; late: strong penalty (dead space costly).
    let w = 0.5 + 0.9 * progress * progress;
    score += w * (r_norm * r_norm) * cap;

    // Cubic term: amplify penalty for very small residuals unless they are near zero (perfect fit).
    let tightness = 1.0 - r_norm;
    score -= 0.35 * tightness * tightness * tightness * cap * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless residual
    // of existing bins would be unusable for the next item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly; grows with number of open bins.
        score += 25.0 + 2.0 * open_bins_count as f64;
        // If next item would fit in the post-residual, opening a fresh bin is fine.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 20.0;
        }
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
        } else {
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Mean-residual coupling: penalize bins far below the mean residual (fragmenting outliers).
    let dev = (mean_residual - pr) / cap;
    score += 4.0 * dev * dev * cap * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by modulo classes
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -40.0,                      // perfect fit
        1..=5 => -25.0,                  // near-perfect
        6..=10 => -10.0,                 // small gap, still usable
        _ => {
            // integer-division thresholds on post_residual
            let q = pr / 10;             // decade class
            let r = pr % 10;             // harmonic remainder
            let base = q as f64 * 4.0;
            let rem_pen = match r {
                0 => -3.0,               // round decade: easy to fill
                1..=4 => 1.5,            // awkward small remainder
                _ => 3.0,
            };
            base + rem_pen
        }
    };
    score += class;

    // Capacity fraction coupling: how much of the bin the item consumes
    let frac = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * frac;             // reward large fills

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item's class relative to gap
            let diff = pr - next_item_size;
            let bonus = if diff == 0 { -12.0 } else if diff <= 10 { -6.0 } else { -2.0 };
            score += bonus;
        } else {
            // next item cannot use this gap -> penalize proportionally
            score += 0.05 * (next_item_size as f64 - pr as f64).min(20.0);
        }
    } else {
        // last item: prefer any bin, especially perfect fits
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only open a new bin when item is huge
    // and no bin offers a reasonable fit.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.1;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 60 && tight {
            score -= 5.0 + 5.0 * progress;
        } else {
            score += 12.0;           // discourage wasting fresh bins
        }
    }

    // Mean residual divergence: prefer bins whose residual deviates from mean
    // (fill the outliers, keep homogeneous bins for future items)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Mild pressure against bin sprawl late in the stream
    score += 0.01 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the minimum
    // item (1) are useless; anything below the smallest plausible item
    // creates unusable gaps -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap blocks the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few bins, opening new ones is cheap so prefer tight fits there.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: mild penalty growing with stream progress
        // and number of open bins, so late in the stream we consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + progress * 10.0 + pressure * 1.5;
        // But if the item is huge relative to mean residual elsewhere,
        // opening a fresh bin can be fine: soften the penalty.
        if item_size as f64 > mean_residual {
            score -= 6.0;
        }
    } else {
        // Existing bin: slight reward for packing into already-open bins.
        score -= 2.0 + pressure * 0.05;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
    }

    // Prefer post_residual close to mean residual (balanced packing)
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Penalize tiny unusable dead space
    if post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Reward filling bins tightly as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.3;

    // Make new-bin candidate slightly costly unless post_residual is huge
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual dominates, add quadratic penalty for large waste.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item fits almost perfectly afterwards.
        let second_waste = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * (1.0 - second_waste);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving dead space the next item cannot use.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: this is the only bin that fits; strongly prefer it over a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Mild competition penalty when many bins fit; prefer best-fit resolution.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin gets a fixed opening cost, discounted
    // late in the stream or when open bins are collectively full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fullness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 45.0 - 15.0 * progress - 20.0 * fullness;
        // If item is huge, opening a fresh bin is often wise.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Reward filling bins that are already below-average residual (dense bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
        // Slight preference for fewer open bins when residuals are healthy.
        if post_residual as f64 >= 10.0 {
            score -= 3.0;
        }
    }

    // Early stream: consolidate aggressively into few bins; late stream: allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score -= 4.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fill, small unusable gap anyway
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted post residual, quadratically (dead space grows costly).
    let mut score = norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (mild penalty on small residuals);
    // late, strongly reward tight fits (small post_residual).
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (0.5 + 3.0 * progress) * 10.0;

    // Cubic interaction: mid-stream prefers balanced residuals.
    let balance = (norm_pr - mean_residual / cap).abs();
    score += (0.5 + 2.0 * progress) * balance * balance * cap * 0.5;

    // Last-chance bonus: smooth reward when few bins fit.
    if fitting_bins_count <= 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth in gap size).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score -= (gap / cap) * (4.0 + 6.0 * progress);
    }

    // Mild penalty when many bins are open (encourage consolidation early).
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate: make it attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        score -= 3.0 + 10.0 * progress;
        score += norm_pr * norm_pr * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: eliminate the bin
    } else if pr % 10 == 0 {
        score -= 12.0; // decadal leftover stays reusable
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        score += 6.0;  // odd dead space is penalized
    }

    // Integer-division thresholds: leftover small enough to be nearly dead.
    if pr <= 10 {
        score += 18.0; // sliver below minimum item size
    } else if pr <= 20 {
        score += 4.0;
    } else if pr >= 80 {
        score -= 8.0;  // roomy bin still flexible
    }

    // Coupling with lookahead item: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 20.0; // leaves a harmonic residual again
            } else if slack <= 10 {
                score -= 14.0; // near-perfect chain fit
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize more if leftover is awkward
            if pr % 10 != 0 {
                score += 10.0;
            } else {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when open bins are very full
    // (mean residual low) or few bins fit the item.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let pressure = (mean_r / bin_capacity as f64).clamp(0.0, 1.0);
        score = 100.0 - 40.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity / 2 {
            score += 5.0; // fresh bin useful for large follow-up
        }
    }

    // Early in the stream, be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that no item (min size ~10) can use are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits the post_residual exactly, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (post_residual of a fresh bin = capacity - item, naturally large, so
    // nudge it up unless it's a genuinely bad fit elsewhere).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this bin is a perfect two-item chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits but not perfectly: small reward proportional to tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * tight;
        } else {
            // Next item cannot use the leftover space: penalize dead space.
            score += 8.0 + (post_residual as f64) * 0.15;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // placing here and leaving a residual far below the mean creates fragmented space.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 && pr > 0.0 {
        score += 6.0;
    } else if pr >= mean_residual {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize wasting a nearly-empty bin's flexibility on tiny items.
    let frac_used = item_size as f64 / bin_capacity as f64;
    if bin_residual == bin_capacity && frac_used < 0.35 {
        score += 12.0;
    }

    // Late in the stream, tighten packing (less tolerance for leftover space).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.02 + 0.03 * progress);

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing (min size 1..100 stream) can reuse later:
    // mid-range post residuals (e.g. 1..=15) are least reusable.
    if post_residual > 0 && post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item can use the post residual, reward leaving exactly that space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain fit
        } else if next_item_size < post_residual {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here: dead space risk grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are tight relative to the item, or many bins are already open.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.3;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_penalty = 25.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        if tight {
            open_penalty += 30.0;
        }
        score += open_penalty;
    } else {
        // Reusing an open bin is generally good; scale reward by global fragmentation.
        score -= 8.0 + 0.05 * mean_residual;
    }

    // Late in the stream, consolidation matters more: penalize spreading residual thin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear waste penalty: cubic in normalized post-residual, weighted by stream progress.
    // Later in the stream, residual waste is increasingly costly.
    let waste_penalty = norm_post * norm_post * norm_post * (0.5 + 2.5 * progress);
    score += waste_penalty;

    // Smooth coupling with mean residual: prefer bins whose post-residual deviates
    // beneficially from the mean; penalize bins that would stay far above mean residual.
    let dev = (post - mean_residual) / cap;
    score += 0.35 * dev * dev * (1.0 - progress);

    // Lookahead coupling: if next item exactly fits the post-residual, reward strongly
    // with a smooth (non-piecewise) bell-shaped term.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / cap;
        let fit_bonus = (-6.0 * gap * gap).exp() * 3.0 * (0.3 + 0.7 * progress);
        score -= fit_bonus;
        // If post-residual is too small for next item, mildly penalize (dead space risk),
        // smoothly scaled by how close post_residual is to being unusable.
        let unusable = (next_item_size as f64 - post).max(0.0) / cap;
        score += 1.2 * unusable * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // (avoids opening a new bin), with smooth scaling by progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 3.0 * progress;
    }

    // New-bin candidate: neutral baseline, slightly penalized early (consolidate first),
    // gradually more acceptable as the stream progresses.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (large enough for typical small items) are rewarded.
    let pr = post_residual;
    let class = pr / 10; // integer division: harmonic class 0..=10
    match class {
        0 => score += 40.0,                       // dead space (<10): heavily penalize
        1 => score += 15.0,                       // marginal space
        2 | 3 => score -= 10.0,                   // sweet spot for 10-30 items
        4 | 5 => score -= 20.0,                   // excellent leftover classes
        _ => score -= 5.0,                        // large leftover: fine but wasteful
    }

    // Exact-fill bonus via modulo arithmetic
    if pr == 0 {
        score -= 100.0;
    } else if pr % 10 == 0 {
        score -= 8.0 * (pr as f64 / 10.0).min(5.0);
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here too: reward, scaled by how snugly
            let snug = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 12.0 + 10.0 * snug;
        } else {
            // next item cannot use this leftover: penalize proportional to gap class
            let gap = (next_item_size - pr) / 10;
            score += 5.0 * gap as f64;
        }
    }

    // Last-chance bin logic: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current item is large and the stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_frac = item_size as f64 / cap;
        // reward new bin when item is big and few bins are open
        score -= 30.0 * size_frac * (1.0 - progress);
        score += 10.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // mild penalty for spreading across many open bins
        score += (open_bins_count as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter than average bins get priority).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Phase-aware dead-space pressure: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (pr as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (min item size is small but gaps < ~15 rarely get filled later).
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 10.0; // still small enough for the smallest items
    }

    // Reward bins whose residual matches the item size well (tight packing).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when fits are bad.
        score += 30.0;
        // Less penalty late in the stream? keep neutral; slight bonus if
        // next item is large and current fits are all tight.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // dead space for the known next item
    }

    // Slight preference for bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: subtract a bonus proportional to how snugly next item fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 + 0.5 * slack_after_next as f64;
        } else {
            // Next item won't fit here; penalize leftover dead space.
            score += 0.3 * post_residual as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a great lookahead chain.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild preference for compacting when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively when many bins compete.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64) * (1.0 + fitting_bins_count as f64 * 0.05);

    // Penalize dead space: small post_residual that cannot fit typical future items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 30.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty for wasting the lookahead opportunity.
        score += 5.0;
    }

    // Last-chance bonus: only fitting bin -> avoid opening new bin unless residual is huge.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, penalize unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 * 0.9 - crowding * 3.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for sequencing large items
        }
    }

    // Time horizon: early in stream, be pickier about waste (long future to regret it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    // Deviation from mean residual: prefer bins that are outliers (very full or fitting well).
    score -= (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, large dead space is penalized more heavily.
    let dead = (pr / cap).powi(2);
    score += (1.0 + 3.0 * progress) * 20.0 * dead;

    // Cubic coupling: reward very tight fits super-linearly.
    score -= 15.0 * (1.0 - pr / cap).powi(3);

    // Mean-residual interaction: prefer bins whose remaining space aligns
    // with the global average (keeps residual distribution balanced).
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: penalize leaving a residual that barely misses next item,
    // reward a residual that can host it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance fitting: strongly favor using the only bin that fits,
    // scaled by smooth progress term.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: only attractive when no open bin fits or the
    // current bin would leave excessive waste late in the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            score += 30.0 + 25.0 * (1.0 - progress) + 0.2 * (mean_residual / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes are reusable.
    let class_bonus = if post_residual == 0 {
        -60.0 // perfect closure, best possible outcome
    } else if post_residual % 50 == 0 {
        -18.0
    } else if post_residual % 25 == 0 {
        -12.0
    } else if post_residual % 10 == 0 {
        -8.0
    } else if post_residual % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward residue -> dead-space risk
    };
    score += class_bonus;

    // Lookahead coupling: reward exact/near fits with the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 30.0; // next item closes this bin exactly
        } else if post_residual % next_item_size == 0 {
            score -= 10.0; // harmonic divisibility with lookahead
        } else if slack <= 5.0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use leftover: penalize proportionally to wasted fraction
        score += 0.25 * pr;
    }

    // Last-chance bin: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0); // competition: be stricter
    }

    // New-bin candidate: only attractive when post_residual would be very wasteful elsewhere.
    if bin_residual == bin_capacity {
        // Opening fresh gives full flexibility; score relative to mean residual pressure.
        score = 45.0 + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let after = bin_capacity - next_item_size;
            if after % 10 == 0 { score -= 8.0; }
        }
        // Discourage opening new bins early in the stream when fragmentation is low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        if open_bins_count == 0 { score -= 40.0; }
    }

    // Tight-fit reward: small post_residual relative to capacity is good.
    score += 10.0 * (pr / cap).powi(2);

    // Penalize bins far below mean residual (fragmenting well-packed bins).
    if bin_residual != bin_capacity {
        score += 0.15 * (mean_residual - pr).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open.
    score += (open_bins_count as f64) * 0.5 + mean_residual * 0.05;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // New-bin candidate: mildly penalized unless residual pressure is high.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Aggressive 2-step lookahead: reward when the next item fits exactly or well
    // into the post_residual; penalize when it does not.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits; reward proportionally to how tightly it fills the leftover.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_fill;
        } else {
            // Next item won't fit here: penalize dead space more heavily.
            let dead = (next_item_size - post_residual) as f64;
            score += dead.min(40.0) * 0.8;
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (i.e., tighter bins) to keep loose bins available for future items.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the stream is early and consolidation is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    // Mild pressure to close out nearly-full bins as the stream progresses.
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, with a nonlinear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Bonus if the bin can still host the next item after this placement.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, prefer spreading load (favor new bins
    // less aggressively); late, prefer closing out bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Global residual pressure: if mean residual is high, prefer filling
    // below-average-residual bins (consolidation).
    let rel = bin_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        score += 20.0 - 25.0 * fragmentation;
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic coupling of post_residual with stream progress.
    score += 0.8 * (pr / cap) * (pr / cap) * cap * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize bins that are much worse than the mean residual (dead space creation).
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only bin that fits to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Lookahead: reward if next item fits into resulting post_residual; penalize blocking.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - (pr - nx) / cap) * (0.6 + 0.4 * progress);
        } else {
            score += 3.0 * ((nx - pr) / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Penalize opening a brand-new bin when progress is low and open bins exist.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: opening is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead space quality depends on size class.
    // Residuals in (0..10] are nearly useless; penalize hard.
    if post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Modulo arithmetic: post_residual congruence classes mod 10.
    // Residuals divisible by 10 pair well with the 10..80 item range.
    let m10 = post_residual % 10;
    score += 8.0 * (5 - m10) as f64 * 0.2;

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain continues. Reward proportionally to snugness.
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * snug;
        } else if post_residual > 0 && next_item_size % post_residual == 0 {
            // Harmonic divisibility: residual divides next item — likely waste.
            score += 12.0;
        } else {
            // Next item can't use this residual: penalize dead space more.
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Last item: pure tightness matters.
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would leave large unusable space and many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = (bin_capacity - item_size) as f64;
        if dead < 20.0 {
            score -= 25.0; // fresh bin keeps near-full packing
        } else {
            score += dead * 0.6 + 20.0 * progress;
        }
    }

    // Prefer bins below mean residual (keeps residual variance low).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item can use are heavily penalized.
    // Items range 1..100, so any residual < 10 is pure dead space; 10..=30 is hard to fill.
    if post_residual < 10 {
        score += 60.0; // unusable gap
    } else if post_residual <= 30 {
        score += 18.0;
    } else if post_residual <= 50 {
        score += 4.0;
    } else {
        // Larger leftovers are reusable: reward keeping flexible space.
        score -= 6.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual == 1 {
        score -= 40.0;
    }

    // Dead-space coupling: if the leftover is smaller than the next item, it is likely wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }
    // If the next item fits exactly into the leftover, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across too many bins when the mean
    // residual is already large (bins are under-filled).
    let openness = open_bins_count as f64;
    score += 0.35 * openness * (mean_residual / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize using a nearly full bin for a small item (waste of a tight fit).
    if item_size < 20 && bin_residual <= 40 && bin_residual != bin_capacity {
        score += 8.0;
    }

    // Late in the stream, tighten up: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space sliver
    }

    // 2-step lookahead: if next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to remaining space
            let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 25.0 * (1.0 - gap).max(0.0);
        } else {
            // next item won't fit here; penalize leaving large leftover that may be wasted
            score += 0.05 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline; make it slightly unattractive unless post_residual is large.
    if bin_residual == bin_capacity {
        score = 55.0 - 0.4 * (post_residual as f64);
    }

    // Late in the stream, be more conservative (prefer filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
