pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, scaled by progress (tighten bins later in stream)
    let mut score = pr * (0.5 + 1.5 * progress);

    // Non-linear penalty for dead space: quadratic in normalized post-residual
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward small residuals (good fits) with cubic term
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * progress);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: favor bins whose post-residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual coupling: penalize bins far from mean residual (keep diversity)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // Mild penalty for opening new bins late in the stream when many bins exist
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward tight fits: post_residual in small harmonic classes
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 60.0; // near-perfect fit, dead space negligible
    } else {
        // penalize residuals in awkward modulo classes (unfillable by small items)
        let m = post_residual % 10;
        if m != 0 && pr < 10.0 + m {
            score += 8.0;
        }
        // harmonic class penalty: residual in (50,100) half-full class vs quarter classes
        if frac > 0.5 {
            score -= 15.0; // still roomy bin, good
        } else if frac > 0.25 {
            score -= 5.0;
        } else {
            score += 10.0 * (0.25 - frac); // dead-space penalty grows
        }
    }

    // Integer-division threshold: post_residual buckets of 20
    let bucket = post_residual / 20;
    score += bucket as f64 * 3.0;

    // Last-chance bonus: only this bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let nf = next_item_size as f64;
            let pf = post_residual as f64;
            // prefer leaving residual that is a good host for next item
            score -= 30.0 * (nf / pf);
            // penalize leaving residual just barely above next item (fragmentation)
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score += 10.0;
            }
        } else {
            // next item won't fit here; slight penalty for blocking lookahead
            score += 5.0;
        }
    } else {
        // last item: minimize residual
        score += 0.0;
    }

    // Stream progression: early on, prefer filling existing bins less aggressively? 
    let progress = step_index as f64 / total_items.max(1) as f64;
    // late in stream, tighten packing (favor existing bins)
    score -= 12.0 * progress * (mean_residual / cap);

    // Penalty for opening new bins when many already open and mean residual large
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost
        score += 25.0;
        if mean_residual > 30.0 {
            score += mean_residual - 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        }
    } else {
        // prefer reusing bins; slight reward scaled by how full bin already is
        score -= 10.0 * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical future items.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0;
    }
    // If next item would not fit and post_residual is small, slight penalty (dead end).
    if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual < 10 {
        score += 8.0;
    }

    // Prefer bins with residual close to item (tight fit) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // New-bin candidate: neutral-ish baseline; encourage when open bins are crowded.
    if bin_residual == bin_capacity {
        let baseline = 40.0 + mean_residual * 0.2;
        score = score.max(baseline);
        if open_bins_count > 0 && mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

