    // 2-step lookahead: reward if next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // next item fits: residual consumed next step, mild bonus
            score -= 12.0;
        } else {
            // next item won't fit: penalize proportional to wasted gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.6;
        }
    }

    // Penalize bins far above mean residual (fragmented leftovers) mildly;
    // favor bins tighter than mean.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit, especially early/mid stream.
    if bin_residual == bin_capacity {
