    }

    // Many open bins: prefer consolidating into existing bins to close them out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual deviates below the mean (fill the emptier ones).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more as the stream progresses
        // (fewer chances to fill it later), but slightly less when many
        // items remain to help fill it.
        score += 35.0 + 20.0 * progress - 5.0 * (total_items.saturating_sub(step_index) as f64 / total_items.max(1) as f64);
        // If current item is large, a fresh bin wastes less elsewhere.
        if fill_ratio > 0.6 {
            score -= 10.0;
        }
        // If the only fitting bin is a bad fit (large post-residual), new bin looks better.
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 0.35 * (pr * pr) / cap;

    // Non-linear penalty for dead space (small post_residual) modulated by progress
    let dead = (cap - pr) / cap;
    score += 12.0 * dead * dead * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    score -= 6.0 * (item_size as f64 / cap) * (0.5 + progress);

    // Lookahead: reward bins whose post_residual accommodates the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (1.0 + progress);
    } else if next_item_size > post_residual {
        score += 3.0 * progress;
    }

    // Last-chance bonus: penalize leaving this bin unused when it is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
        // New-bin candidate looks attractive if mean residuals are large (fragmentation)
        score -= 0.05 * mean_residual;
    }

    // Coupling term: interaction between item size and mean residual state
    score += 0.02 * (mean_residual - pr) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Class boundaries at multiples of the smallest item size (assume >=10 scale,
    // but robust to small items via integer division on 10-unit classes).
    let post_class = post_residual / 10;
    let residual_class = bin_residual / 10;

    // Penalize dead space: leftover that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Reward leaving a "harmonic" leftover: divisible-friendly chunks (10,20,...).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0 * (post_class.min(9) as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward scaled by tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item would NOT fit here: leftover becomes dead weight for the lookahead
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit,
    // or when the stream is early and we can afford spreading load.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening fresh bins is penalized more as the stream progresses.
        score += 25.0 + 60.0 * progress;
        // But if the item is large and fits perfectly in a fresh bin, soften.
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Many open bins with high mean residual: prefer filling those instead.
        score += 0.5 * open_bins_count as f64 + 0.3 * mean_residual;
    }

    // Prefer bins tighter than the mean (fill well-packed bins first).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Modulo-class tiebreak: leftover congruent to common item sizes is reusable.
    let m = post_residual % 20;
    if m == 0 || m == 10 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit a typical upcoming item (size >= 10).
    if post_residual > 0 && post_residual < item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover gap; penalize proportionally.
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: neutral-ish baseline, slightly penalized so good
    // existing fits win, but competitive when all fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 - 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact-fit lookahead bonus: next item fills remaining space nearly perfectly.
        let lookahead_waste = (post_residual as f64 - next_item_size as f64).abs();
        score -= (bin_capacity as f64 / (lookahead_waste + 1.0)) * 2.0;

        // Perfect two-item closure: current + next exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space proportionally.
        score += (next_item_size as f64) * 0.3;
    }

    // Penalize small unusable residuals (dead space) with non-linear growth.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect closure of the bin
    }

    // Prefer tight fits relative to mean residual state of the system.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in the stream, be more willing to spread items (favor new bins slightly);
    // later, consolidate to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless lookahead suggests a good pairing.
        score += 15.0 - 20.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    } else if progress > 0.7 {
        score -= 5.0; // consolidation pressure late in stream
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize leaving small dead space that few items can use
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Progress-based exploration: early in stream, be more willing to open new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: slightly above a good fit, below a bad fit
        score = bin_capacity as f64 * 0.6 + progress * 20.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Prefer bins with residual close to item (tight packing)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 40.0;

        // Mild bonus for filling bins when many bins are open (consolidation)
        score -= 0.3 * open_bins_count as f64 * (1.0 - progress);

        // Prefer bins below mean residual (use up emptier space first)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress) - 6.0 * norm_post * (1.0 - norm_post) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_post).powi(3) * 10.0 * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.5 + progress);
        } else {
            score -= 2.0 * (1.0 - (post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.15;

    // Pull toward mean residual to keep bins balanced
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction classes (C=100)
    let item_class = item_size / 10; // 0..=10 harmonic class
    let post_class = post_residual / 10;

    // Reward tight fits: small post_residual strongly favored
    score -= 18.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // Penalize "dead space": post_residual in awkward small bands (1..9, 11..19)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Reward post_residual that is a harmonic multiple (divisible residual classes)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (slack as f64) / (bin_capacity as f64));
            if slack < 10 {
                score += 8.0; // leaves a sliver for next item too
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it's only
    // chosen when no decent fit exists among open bins
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if item is huge (class >= 7), fresh bin is fine
        if item_class >= 7 {
            score -= 20.0;
        }
        // late in the stream, avoid opening new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer filling bins that deviate below mean residual (pack fuller bins first)
    score -= 2.0 * (mean_residual - bin_residual as f64).max(0.0) / 10.0;

    // Modulo coupling: item + post_residual aligned to capacity quanta
    if (item_size + post_residual) % bin_capacity == 0 {
        score -= 10.0;
    }

    // Integer-division threshold on post_residual classes
    score -= 1.5 * post_class as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Gaps too small for the lookahead item are semi-dead if the next item can't use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits: bonus proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; early stream, allow exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.3 + 0.5 * progress);

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when few bins fit or item is large.
        let mut nb = 30.0;
        if fitting_bins_count <= 1 {
            nb -= 35.0; // no real alternative
        }
        if item_size >= 60 {
            nb -= 8.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            nb += 5.0; // keep new bin clean for next item
        }
        score += nb;
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with the next item's size (perfect chain placement).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward near-matches: post_residual close to next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // next item could still fit here afterwards
            score -= (10.0 / (1.0 + gap)).min(8.0);
        } else {
            // next item won't fit in leftover; penalize dead space relative to gap
            score += gap.min(40.0) * 0.25;
        }
    }

    // Compare post_residual against mean residual: leaving residuals near the
    // mean keeps flexibility across bins.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.15;

    // Penalize large unusable dead space (small post_residual that is not zero).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item leaves a very awkward residual and the next item is large.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 10;
        let next_big = next_item_size >= 60;
        if awkward && next_big {
            score -= 25.0;
        } else {
            score += 30.0; // discourage opening new bins by default
        }
    }

    // Late in the stream, consolidate: favor tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well next item uses leftover space
            let use_ratio = (next_item_size as f64) / (post_residual as f64);
            score -= 12.0 * use_ratio;
        } else {
            // leftover too small for next item: penalize dead space if below min item size
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New bin candidate: penalize opening a new bin when decent alternatives exist,
    // but allow it when current bin would leave a large unusable hole.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let hole = (bin_residual - item_size) as f64;
        let hole_ratio = hole / (bin_capacity as f64);
        // if the hole is small (good fit in new bin), opening is attractive
        score -= 15.0 * (1.0 - hole_ratio);
        // discourage excessive bin proliferation early on
        score += 3.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
        // if no other bin fits, opening is the only option
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate space).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Slight preference for filling fuller bins later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty growth
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr * norm_pr) * 100.0;

    // Smooth polynomial coupling with stream progress: tighten packing later
    let tighten = 1.0 + 2.0 * progress * progress;
    score *= tighten;

    // Reward near-perfect fits smoothly (quadratic dip near zero residual)
    let perfect = 1.0 - norm_pr;
    score -= 40.0 * perfect * perfect * perfect;

    // Penalize leaving residual that can't fit the lookahead item (smooth gate)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr) / cap;
            score += 30.0 * gap * gap * cap;
        } else {
            // Reward residual that accommodates next item, decaying smoothly
            let room = (pr - ni) / cap;
            score -= 10.0 * room * (1.0 - room);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin (smooth sigmoid-like)
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance-aware, smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev - 3.0 * dev;

    // New-bin candidate: penalize opening new bins unless item is large
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 25.0 * (1.0 - size_frac) * (1.0 - size_frac) + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes of capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Class bonus: post_residual landing exactly on harmonic divisors is valuable
    // (it can host many common item sizes exactly).
    if pr == 0 {
        score -= 40.0; // perfect fit, best possible
    } else if pr % 10 == 0 {
        score -= 12.0; // multiple of 10: fits typical item sizes exactly
    } else if pr % quarter == 0 || pr % eighth == 0 {
        score -= 8.0;
    } else if pr < 10 {
        score += 25.0; // dead space below minimum item size
    } else {
        score += 5.0; // awkward residue class
    }

    // Integer-division threshold: penalize leaving residual in "useless" band
    let useless_band = pr > 0 && pr < 10;
    if useless_band {
        score += 20.0;
    }

    // Lookahead coupling: does post_residual exactly host the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (next_item_size as f64 / cap); // next item can't use this space
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fractional capacity coupling: reward filling a large fraction of the bin
    let fill_fraction = item_size as f64 / cap;
    score -= 20.0 * fill_fraction * fill_fraction;

    // Late in stream: prefer tighter packing, fewer open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.5;

    // Prefer bins below mean residual (tighter bins get filled first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 30.0; // default penalty for opening a new bin
        if next_item_size > 0 && next_item_size >= item_size && fitting_bins_count <= 1 {
            score -= 35.0; // big item with no alternatives: open fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize small-but-maybe-usable gaps more as stream progresses (future flexibility worth less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (0.5 + progress);
    }

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fits (small post residual relative to item) rewarded mildly.
    score -= 10.0 / (1.0 + post_residual as f64 / item_size.max(1) as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones; opening new bins costs more.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 0.35 * pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is large and few bins fit it.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual { 15.0 } else { 0.0 };
        score += 30.0 - 0.5 * open_bins_count as f64 - lookahead_bonus
            + 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving gap that nothing can use soon.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: perfect match for the next item is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // next item exactly fills this bin
        } else if post_residual > next_item_size {
            // next item fits too; reward tightness of the pair
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * pair_waste;
        } else {
            // next item cannot use the leftover: dead space risk
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize unusable slivers (small leftover nothing may fit into).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is a terrible sliver).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual >= 10 {
            score -= 20.0;
        } else {
            score += 5.0;
        }
    }

    // Prefer bins tighter than average residual (best-fit style).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in the stream, allow opening fresh bins more freely; late in the
    // stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, costly later.
        score -= 10.0 * (1.0 - progress);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.8 {
        score -= 12.0 * (fit_ratio - 0.8);
    }

    // Penalize leaving dead space that is hard to reuse: post_residual < 10 is nearly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
    } else if post_residual > 0 {
        score += (post_residual as f64).powf(0.35) * 0.8;
    }

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be pickier, penalize loose fits.
        score += 3.0 * (1.0 - fit_ratio);
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 6.0;
        } else {
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 0.15;
        }
    }

    // Global state: opening new bins early is fine when few bins are open; later prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 8.0 + 20.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Prefer bins whose residual deviates from the mean in a reusable way (large residuals get used).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs() - 0.05 * dev;

    // Prefer filling bins with many open bins (reduce bin count pressure).
    score -= 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr;

    // Smooth non-linear coupling: normalized post residual with progress
    let prn = pr / cap;
    score += 30.0 * prn * prn * (1.0 + progress) - 15.0 * prn * progress;

    // Reward tight fits: quadratic bonus as post_residual approaches 0
    score -= 25.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + 0.5 * progress);

    // Lookahead: penalize residual that cannot fit next item, reward exact fit
    if nx > 0.0 {
        if pr >= nx {
            score -= 10.0 * (nx / cap);
        } else {
            score += 12.0 * (1.0 - pr / nx.max(1.0)) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // Mean residual coupling: prefer bins near the mean (smooth gaussian-ish)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for spreading across many bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod common item sizes.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Tightness reward: quadratic bonus as post_residual approaches 0.
    score -= (1.0 - post / cap_f).powi(3) * 30.0;

    // Perfect fit gets a strong harmonic bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize post_residuals that form "dead" classes: too small for
        // typical next items (items >= 10 originally, but be safe for 1..100).
        let min_next = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        if post < min_next {
            score += (min_next - post) * 1.5; // dead space relative to lookahead
        }
        // Harmonic residue classes: post_residual divisible by small sizes
        // (2,4,5,10) is more reusable.
        let pr = post_residual;
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 2 == 0 { score -= 1.0; }
        else { score += 2.0; } // odd awkward residue
        // Class by integer-division threshold bands on post_residual.
        let band = pr / 25; // 0..3 bands
        score += band as f64 * 4.0; // larger leftover -> worse
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            score -= (rem2 as f64).sqrt() * 5.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual - post).abs();
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty keeps new bins as fallback; relax late in stream or
        // when mean residual is large (fragmented bins).
        score = cap_f + 50.0 * pressure - frag * 0.3 - progress * 10.0;
        if item / cap_f > 0.5 {
            score += 20.0; // big items: prefer fresh bin slightly less penalized? no -> add penalty
            score += 15.0;
        }
    }

    // Slight preference to balance residual spread.
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful for typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with open_bins_count pressure: when many bins are open,
    // prefer consolidating into existing bins (penalize new-bin opening).
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable when few bins open or item is large.
        score += pressure * 1.5;
        if item_size > 50 {
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strongly favor using this bin to avoid a new bin.
        score -= 30.0 + pressure * 0.5;
    }

    // Lookahead: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // dead space relative to the known future item
    }

    // Mild attraction toward bins tighter than the mean residual (better fit).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream tightening: waste matters more as the stream nears its end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
