pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_frac * fill_frac;

    // Lookahead: bonus if the next item fits the post residual well.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual as u32 == next_item_size {
            score -= 200.0; // chain of perfect fits
        } else {
            // next item won't fit; penalize leaving medium dead space
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening new bins when many bins are open and crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 + 80.0 * (1.0 - t) + 5.0 * open_bins_count as f64;
        // still allow new bin if existing residuals are large (bad fits everywhere)
        score -= 0.5 * mean_residual;
    }

    // Prefer bins below mean residual (consume the emptier bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).abs().signum() * (bin_residual as f64 - mean_residual);

    // Mild late-stream pressure to consolidate.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * t * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = pr * (1.0 + 0.8 * progress * (pr / cap));

    // Quadratic dead-space penalty: small residuals are near-wasted space.
    score += 12.0 * (pr / cap).powi(2) * cap;

    // Smooth coupling: exact-fit reward via cubic term on utilization.
    let used = item_size as f64 / cap;
    score -= 10.0 * used.powi(3) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin early, allow it late
    // or when the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) * cap / (cap + pr);
        score -= 5.0 * (pr / cap) * progress;
        if next_item_size as f64 > pr {
            score -= 6.0; // new bin can host the next item too
        }
    }

    // Lookahead synergy: reward bins whose residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 3.0 + 4.0 * (next_item_size as f64 / cap);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64 * (pr / cap);

    // Mean-residual alignment: prefer bins near the average residual.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on residual space.
    // Residuals in low classes (0..=10) are near-perfect fills; large residuals waste bins.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill is ideal
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr > 50 {
        score += 15.0; // big dead space
    }

    // Integer-division thresholds: pair the post residual with the lookahead item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead still fits here: strong reward scaled by snugness
            score -= 20.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // lookahead won't fit: penalize proportional to leftover dead class
            let dead = next_item_size - pr;
            score += (dead as f64).min(40.0) * 0.5;
        }
        // harmonic class of next item: small items pair well with medium residuals
        let next_class = next_item_size / 10;
        let resid_class = pr / 10;
        if next_class == resid_class && pr >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing fits are bad or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_exists = fitting_bins_count > 0 && (post_residual as f64) <= 15.0;
        if tight_exists {
            score += 25.0; // keep existing good fit
        } else {
            score -= 12.0 * (1.0 - progress); // early stream: fresh bins cheap
        }
        if open_bins_count > 8 {
            score += 10.0; // too many open bins: consolidate
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tighten the tightest).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the smallest
    // item (size 1..10) are pure waste. Penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Small-but-usable residuals (10..=19) are also fragile: only tiny items
    // can use them, so apply a moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: small usable post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // (especially the last fitting one) over spreading items.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else. Base cost for opening a new bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But a fresh bin is good when the next item is large and would leave
        // this bin with dead space anyway.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 8.0;
    }

    // Late in the stream, avoid opening new bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item fits exactly into leftover: strong reward
            score -= 60.0 * (1.0 - diff / 100.0);
            if diff == 0.0 {
                score -= 200.0;
            }
        } else {
            // leftover too small for next item: penalize dead space, worse if very small
            let waste = post_residual as f64;
            score += 0.8 * waste;
            if waste < 10.0 {
                score += 50.0; // tiny unusable sliver
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or lookahead is bad
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size >= 60 {
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 40.0; // fresh bin gives room for next item
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for fuller bins overall
    score += 0.3 * (bin_residual as f64 - post_residual as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Lookahead: reward bins whose post residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0; // next item cannot follow into this bin
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is high.
    score += 0.15 * (open_bins_count as f64) * (mean_residual / bin_capacity as f64);

    // Time-horizon scaling: early on, be conservative about fragmenting bins;
    // late in the stream, prioritize closing bins out (accept larger fills).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    // New-bin candidate: keep it neutral-ish but discourage unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * tightness;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual weighted by stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    // Early in stream: prefer tight fits (penalize large residuals quadratically).
    // Late in stream: residual waste matters more (amplified cubic term).
    let w = 1.0 + 2.0 * progress * progress;
    score += w * 8.0 * prn * prn * cap * (0.5 + 0.5 * progress);

    // Reward near-perfect fits with smooth exponential-like polynomial.
    let tight = 1.0 - prn;
    score -= 6.0 * tight * tight * tight * (1.0 + progress);

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 4.0 * (1.0 - (nx / cap)) * (1.0 - progress * 0.5);
        } else {
            score += 3.0 * (1.0 - progress) * (nx - pr) / cap;
        }
    }

    // Discourage fragmenting bins far below mean residual (smooth coupling).
    let mrn = mean_residual / cap;
    score += 2.0 * (prn - mrn).abs() * (prn - mrn);

    // Mild preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * prn;

    // New-bin candidate: baseline so it's chosen only when open bins look bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "useful" size classes (divisible by common small item sizes).
    let mut class_bonus = 0.0;
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            class_bonus -= 3.0 * (d as f64 / 10.0);
        }
    }
    score += class_bonus;

    // Penalize awkward dead space: post_residual in (0,10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does next_item_size fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic match: next item leaves another clean class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        if crowd < 0.25 {
            score -= 20.0; // open bins nearly full -> fresh bin is fine
        } else {
            score += 25.0; // prefer packing into existing bins
        }
    }

    // Tight-fit reward: small post_residual relative to item size
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * (1.0 - frac).max(0.0) * (item_size as f64 / bin_capacity as f64);

    // Late-stream consolidation: prefer filling bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(10) {
        score += 40.0;
    }
    // General dead-space curve: small residuals are worst.
    let pr = post_residual as f64;
    score += 6.0 * (1.0 - pr / bin_capacity as f64) * (1.0 - pr / bin_capacity as f64) * 10.0;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if pr <= 5.0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a gap that wastes space.
        score += 8.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: fewer open bins is better; penalize using bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Prefer tighter bins among open ones (residual close to item size).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // must open new bin anyway
        } else {
            // Opening a new bin costs; make it slightly worse than a decent fit.
            score += 12.0 + open_bins_count as f64 * 0.3;
        }
    }

    // Progress-based mild adjustment: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residual left behind relative to mean residual of open bins.
    let post = post_residual as f64;
    let mean_r = if mean_residual.is_finite() { mean_residual } else { cap };
    score += 0.35 * (post - mean_r).abs();

    // Aggressive 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as u64 == next_item_size as u64 {
            // Perfect 2-item closure: post_residual == next item size.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to tightness of that second fit.
            let second_slack = post - nxt;
            score -= 30.0 * (1.0 - second_slack / cap);
        } else {
            // Next item cannot fit here: penalize proportionally to how much space is wasted.
            let gap = nxt - post;
            score += 0.5 * gap.min(60.0);
        }
    }

    // Tight first fit reward: small post residual is good.
    score += 0.25 * post;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty-bin candidate: penalize unless item is huge relative to capacity
    // or no real alternative exists (large post residual wasted in an existing bin).
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // Favor a fresh bin for very large items (they'd leave big dead space elsewhere),
        // penalize for small items.
        score += 18.0;
        score -= 30.0 * fill_frac * fill_frac;
        // If many bins are open and mean residual is small, opening new bins is wasteful.
        score += 0.15 * open_bins_count as f64;
        if mean_r < 25.0 {
            score += 12.0;
        }
    }

    // Early stream: be slightly more willing to open bins for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large post-residual dead space, but softly (small leftovers can be useful).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny gap is nearly dead space -> actually good, we used the bin well
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // awkward medium gap
    }

    // Lookahead: reward if the next item fits into the post-residual of this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; slight penalty unless post_residual ~ 0.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with how many bins are already open.
        score += 20.0 + 1.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more items to come to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If many bins already fit the item, discourage the new bin.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the item is huge relative to capacity and fits perfectly in a fresh bin, mild discount.
        if item_size >= bin_capacity * 8 / 10 {
            score -= 10.0;
        }
    } else {
        // Reusing an open bin is generally good: reward proportional to global mean residual pressure.
        score -= 2.0 * (mean_residual / bin_capacity as f64);
        // Prefer reusing bins with below-average residual (keeps big spaces free).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing bins completely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker noise-free coupling with item size to diversify decisions.
    score += 0.01 * item_size as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = norm_pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 0.35 * norm_pr * norm_pr * (1.0 + t);
    score -= 0.25 * norm_item * norm_pr * t * (1.0 - t);
    score += 0.15 * norm_pr * norm_pr * norm_pr * (1.0 - t);

    // Penalize dead space more as stream progresses
    score += 0.20 * norm_pr * (t * t);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.60 + 0.30 * t;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        if pr as u32 >= next_item_size {
            score -= 0.30 * nxt * (1.0 - 0.5 * t);
        } else {
            score += 0.10 * nxt * t;
        }
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Slight preference for bins tighter than the mean residual
    score += 0.10 * (mean_residual / cap - norm_pr).max(0.0);

    // Discourage opening new bins early when a decent fit exists
    if bin_residual == bin_capacity {
        score += 0.40 * (1.0 - t) + 0.10;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity quartiles
    let q = bin_capacity / 4; // 25
    let class = post_residual / q; // 0..4 harmonic class

    // Reward near-exact fits heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Penalize mid-class dead space (class 2 => residual in 50..75 worst zone)
    score += match class {
        0 => -50.0,
        1 => 10.0,
        2 => 40.0,
        _ => 0.0,
    };

    // Harmonic coupling: does next item fit the post residual exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            // reward leaving residual that is a good harmonic class for next item
            if nxt_res <= 10 {
                score -= 80.0;
            } else if nxt_res / q == 2 {
                score += 30.0;
            }
        } else {
            // next item cannot fit here: penalize slightly less if this bin is last chance
            if fitting_bins_count == 1 {
                score -= 60.0;
            } else {
                score += 25.0;
            }
        }
    }

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: fresh empty bin
    if bin_residual == bin_capacity {
        // prefer new bin when existing bins would leave bad harmonic class
        if class == 2 && post_residual > 20 {
            score -= 40.0;
        } else {
            score += 30.0 + (open_bins_count as f64) * 2.0;
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    // Tie-break toward bins below mean residual (keep large holes for large items)
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if post_residual < 20 {
        score += 12.0; // likely dead space given min item size 1..100
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Lookahead: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 8.0; // next item won't fit here -> gap likely wasted
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.4 * progress);

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let poor_alternatives = mean_residual < item_size as f64 * 1.15;
        if poor_alternatives || item_size >= 70 {
            score -= 10.0;
        } else {
            score += 35.0; // keep using open bins when they fit reasonably
        }
    }

    // Slight preference for bins below mean residual (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item perfectly fills bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward near-exact matches with next item (tight 2-step packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also fit here: bonus scaled by closeness.
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead space, worse if gap is small (near-miss).
            score += 2.0 * gap + 50.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Penalize residuals that are unusably small dead space (below min item size 1..10 zone).
    if post_residual < 10 && post_residual > 0 {
        score += 120.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Prefer bins with residual below mean residual (tighter bins first), keeping big bins for big items.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening a new bin when other bins fit, especially early in the stream.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));
    }
    // But if next item is huge and this bin is fresh, opening new bin is attractive.
    if bin_residual == bin_capacity && next_item_size > item_size {
        score -= 80.0;
    }

    // Slight preference to fill nearly-full bins first.
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins with small post residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer opening new bins less; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> encourage filling.
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score -= 5.0 * mean_res_norm * (open_bins_count as f64).ln().max(0.0) * 0.1;

    // New-bin candidate handling: empty bin gets a mild penalty so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - progress);
        // If no open bin fits, allow new bin: fitting_bins_count reflects open bins only.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Reward using bins whose residual is close to item (minimize fragmentation).
    score -= 5.0 * (1.0 - (bin_residual - item_size).abs() as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual weighted by stream progress
    let coupling = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 30.0 * coupling;

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (20.0 + 40.0 * progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: penalize if post_residual can't fit next item (waste)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap;
        } else {
            score -= 4.0 * (pr - nxt) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: slightly discouraged early, acceptable for large items
    if bin_residual == bin_capacity {
        score += 10.0 - 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0..=10) is nearly useless,
    // (11..=20) marginal; larger residuals keep future options open.
    let dead_zone = post_residual > 0 && post_residual <= 10;
    if dead_zone {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if the next item fits into post_residual,
    // extra reward for an exact chaining fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 18.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for next item: penalize proportionally to waste.
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // unattractive unless current placement would create dead space or no
    // open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // But if placing here would leave dead space in an existing bin,
        // opening a fresh bin becomes relatively attractive.
        if dead_zone {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        // Late in the stream, avoid accumulating many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is already below the mean (tighter bins):
    // consolidating waste into few bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Harmonic modulo classes on post_residual: residuals congruent to small
    // remainders mod 10 pair poorly with typical item sizes (multiples of 10).
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0;
    } else if class <= 3 {
        score += 4.0;
    }

    // Mild pressure to keep the number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny dead space (below the smallest possible item) — worst outcome.
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        } else if post_residual <= 25 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits generally.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Pressure from number of open bins: prefer filling existing bins
    // rather than proliferating bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // But if the current item leaves a bad gap in every open bin,
        // a fresh bin becomes relatively better.
        if post_residual > 0 && post_residual < 10 {
            score -= 70.0;
        }
        // If next item is large, an empty bin is valuable.
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0;
        }
    }

    // Lookahead: if the post residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be a bit more selective about tight fits.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Squared dead-space penalty, amplified for very small leftovers.
        let pr = post_residual as f64;
        score += (bin_capacity as f64 - pr) * 0.0;
        score += 60.0 / (1.0 + (bin_capacity as f64 - pr) / 10.0);
    }

    // Lookahead: reward when next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 80.0 / (1.0 + gap / 8.0);
        } else {
            // Next item cannot fit here: mild penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless current item is large relative to capacity
    // and open bins are crowded (poor fits). Encourage fresh bin only for big items.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let crowd = open_bins_count as f64;
        score += 120.0 - fill_ratio * 100.0 - crowd * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0; // fresh bin can host current + next
        }
    }

    // Slight preference for using bins earlier in the stream (stability term).
    score += (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; penalize wasted residual slightly.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just fill anything reasonable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.6 + 0.8 * progress;

    // Crowding: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        let spread = mean_residual - post_residual as f64;
        score += 0.05 * spread;
        score -= 0.02 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize unless current bins are crowded/tight.
        let avg_pressure = mean_residual / bin_capacity as f64;
        score += 15.0 * (1.0 - avg_pressure);
        score += 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0; // fresh bin can absorb next item too
        }
    }

    // Slight preference for filling larger items into fuller bins.
    score -= 0.05 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 40.0 * base * base * (1.0 - t);
    score -= 30.0 * base * base * base * t;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - base;
    score -= 25.0 * tightness * tightness * (0.5 + t);

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 20.0 * (1.0 - slack * slack);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Penalize creating dead space relative to mean residual
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }
    score += 0.05 * (mean_residual - pr).abs();

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild penalty for opening new bins early, weaker later
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - t) - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact quarters are "clean" states.
    let q = post_residual % 25;
    match q {
        0 => score -= 18.0,          // perfectly harmonic residual (0,25,50,75)
        10 => score -= 6.0,          // common item size class fits next
        20 => score -= 3.0,
        _ => score += (q as f64) * 0.15, // off-class remainder penalized
    }

    // Integer-division thresholds: dead space below the smallest item is unusable.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let nxt_mod = next_item_size % 10;
            score -= 8.0 - (nxt_mod as f64) * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }
    if fitting_bins_count == 0 && bin_residual == bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual - post_residual as f64).abs();
        score -= 12.0 + frag * 0.3;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Prefer tight fits relative to mean residual.
        score += (mean_residual - post_residual as f64).abs() * 0.25;
    }

    // Late-stream consolidation: fewer bins preferred as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 15.0;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score += gap as f64 * 3.0; // still leaves dead space afterwards
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 0.5;

    // Tightness coupling: reward filling bins with small residuals tightly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // New-bin candidate: only attractive when item is large relative to capacity
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 8.0;                       // default: prefer existing bins
        if large_item > 0.7 {
            score -= 4.0 * (large_item - 0.7) * 10.0; // allow fresh bin for big items
        }
        if fitting_bins_count > 0 {
            score += 6.0;                   // don't open new bin if others fit
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 3.0;
        }
    }

    // Mild stream-progression coupling: later in stream, waste matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += post_residual as f64 * progress * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Aggressive 2-step lookahead: if the next item exactly fits the post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        let post = post_residual as u32;
        if post == next_item_size {
            score -= 60.0;
        } else if post >= next_item_size {
            // Next item fits: reward proportionally to how well it fills again.
            let second_fill = next_item_size as f64 / post as f64;
            score -= 25.0 * second_fill;
        } else {
            // Next item won't fit here: penalize leaving residual close to but
            // below next_item_size (near-miss dead space).
            let gap = (next_item_size - post) as f64;
            score += 0.6 * gap;
        }
    }

    // Penalize residuals too small to ever fit typical items (dead space),
    // but only when no lookahead chain rescues them.
    if post_residual < 10 && next_item_size == 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins whose post_residual diverges
    // from mean in the "clean" direction (very full or matching mean).
    let mean_post = mean_residual - item_size as f64;
    if post_residual as f64 > mean_post {
        score += 0.2 * (post_residual as f64 - mean_post);
    } else {
        score -= 0.1 * (mean_post - post_residual as f64);
    }

    // New-bin candidate: prefer it only when open bins are badly fragmented
    // (high mean residual spread) or late in the stream with tight fits unlikely.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).powi(2);
        score += 40.0 * (1.0 - fragmentation);
        score -= 20.0 * fragmentation;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0; // new bin can't chain, discourage
        }
        let _ = progress;
    }

    // Mild penalty for opening many bins relative to items.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) strongly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; slight penalty if we leave awkward gap.
            score += (next_item_size - post_residual) as f64 * 0.05;
        } else {
            score -= (next_item_size as f64) * 0.1;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin normally, but relax
    // penalty when the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 30.0;
        if item_size >= bin_capacity / 2 {
            new_bin_penalty -= 10.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        // Late in the stream, avoid opening bins we'll never fill.
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty;
    }

    // Prefer bins with residuals below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else if (bin_residual as f64) > mean_residual * 1.5 {
        score += 2.0;
    }

    // Slight preference for keeping open_bins_count low early on.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / c; // normalized post residual

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress.
    // Early stream: tolerate larger residuals (future items can fill them).
    // Late stream: penalize residual quadratically/cubically (dead space).
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress * progress;
    score += w_late * 40.0 * x * x * c;
    score -= w_early * 15.0 * x * c;

    // Perfect fit reward (smooth bump near x ~ 0)
    score -= 25.0 * (-(x * 8.0)).exp();

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        score -= fits * 30.0 * (-(gap / c * 6.0)).exp();
        // penalize post residual that is small but useless for next item
        score += (1.0 - fits) * (next_item_size as f64 / c) * 10.0 * x;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized early,
    // more attractive late when residuals are fragmented
    if bin_residual == bin_capacity {
        score = c + w_late * 20.0 * (mean_residual / c) - w_early * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / c) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into buckets
    // via integer division on capacity fractions (e.g. 0..5, 5..10, ...).
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;

    // Class of post residual: 0 = perfect fit, higher = more wasted space class.
    let class_width = 10.0;
    let post_class = (post / class_width).floor();
    score += post_class * 3.0; // penalize deeper dead-space classes super-linearly
    score += post_class * post_class * 0.05;

    // Perfect fit bonus (post_residual == 0): strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small residual classes that are still useful for small items (harmonic slots).
    // Residuals in [1, 10] are "almost perfect" — reward gently.
    if post_residual >= 1 && post_residual <= 10 {
        score -= 5.0;
    }

    // Penalize residuals that are unusable for typical items (dead space zone).
    // Dead zone: residual in (0, 10) exclusive handled above; penalize residuals
    // that fall just below common item sizes via modulo structure.
    for k in 1..9u32 {
        let slot = k * 10;
        if post_residual + 1 == slot {
            // residual just under a harmonic slot: item sizes equal to slot won't fit
            score += 2.0;
        }
        if post_residual == slot {
            score -= 1.5; // exactly at a slot boundary: clean class
        }
    }

    // Modulo arithmetic on post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    match post_residual % quarter.max(1) {
        0 => score -= 2.0,
        1 => score += 1.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills remainder
            let next_post = post_residual - next_item_size;
            score -= 10.0 - (next_post as f64) * 0.2;
        } else {
            // next item won't fit here: mild penalty, this bin becomes dead after
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; adjusted by stream progress and load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 30.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;

        // If current item is large relative to capacity, new bin is attractive.
        let frac = item_size as f64 / capacity;
        if frac > 0.6 {
            score -= 20.0 * frac;
        }
        // If mean residual across open bins is low, opening new bin is better.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // If next item is large and no open bin could hold both, favor new bin.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 8.0;
        }
    }

    // Mild tie-break: prefer bins with residual close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / capacity;
    score += tightness * 8.0;

    // Prefer bins below mean residual (fill emptier bins first to consolidate).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space): residuals below 10 are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving gaps that are too small for the minimum item size (1..100 range, be conservative)
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open bins pressure: penalize spreading across many bins when residuals are fragmented
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item won't fit in the gap: penalize creating a useless gap
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    let bin_residual_f = bin_residual as f64;
    if bin_residual_f < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Progress pressure: as stream advances, be more conservative with new space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    // New-bin candidate: empty bin gets a moderate penalty so it's chosen only when
    // no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 60.0;
        } else {
            // next item won't fit: penalize wasted post_residual scaled by its size
            score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let tightness = if bin_residual >= item_size { 1.0 } else { 0.0 };
        score += 150.0 * tightness;
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item (<= 10) is truly wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver -> strongly penalize
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use leftover: mild penalty proportional to waste
        score += 0.10 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin is only attractive when the item is
    // large relative to typical residual capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins early and for small items; allow later when bins are scarce.
        score += 18.0 + 30.0 * (1.0 - fill_ratio) + 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits: must open new bin
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state coupling: if mean residual across open bins is high,
    // prefer consolidating into existing bins (penalize new bins implicitly,
    // reward bins whose residual is near the mean).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    // Slight preference for bins that keep residual in "usable" band [10, 50]
    if post_residual >= 10 && post_residual <= 50 {
        score -= 5.0;
    }

    // Time horizon: late in the stream, avoid opening bins (encourage packing out).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: as the stream advances, tighten tolerance for wasted space.
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Lookahead: reward if next item exactly fits the post-residual (smoothly).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 18.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Penalize post-residuals that are awkwardly small for the next item (dead space).
        let dead = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * dead * dead;
    }

    // Last chance: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (item_size as f64 / cap);
    }

    // New-bin candidate: only attractive when existing residuals are badly fragmented
    // or this is a poor fit everywhere; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (1.0 - progress);
        score -= 15.0 * (mean_residual / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild penalty when the bin's residual is far above the mean (fragmented outlier bin).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "useful"
    // residue classes (multiples of common small sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Perfect fit reward
        if pr == 0 {
            score -= 1000.0;
        }
        // Reward post-residuals that are multiples of 10 (align with item grid)
        if pr % 10 == 0 {
            score -= 25.0;
        }
        // Penalize awkward tiny dead space classes (1..=9 leftover)
        if pr < 10 {
            score += 40.0;
        }
        // Harmonic bonus: leftover divisible by several common item sizes
        let mut harmonics = 0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmonics += 1;
            }
        }
        score -= 15.0 * harmonics as f64;
        // Penalize leftovers in odd residue classes modulo 7 (rarely reusable)
        if pr % 7 != 0 && pr < 30 {
            score += 8.0;
        }
    } else {
        score -= 500.0; // exact fill
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to tightness
            score -= 30.0 * (next_item_size as f64 / pr as f64);
            // harmonic match of next item size with post residual
            if pr % next_item_size == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this leftover: mild penalty scaled by wasted potential
            score += 10.0 * (1.0 - pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer only when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: opening bins is cheap; late stream: prefer consolidation
        let openness = 1.0 - t;
        score = 70.0 + 60.0 * openness + (open_bins_count as f64).sqrt() * 5.0;
        // if the item is large relative to capacity, a fresh bin is attractive
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
        if pr == 0 {
            score -= 200.0; // exact fit in fresh bin
        }
    }

    // Mild preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable
    // dead space. Penalize them heavily, but only mildly for exact fits.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score += 45.0; // unusable sliver of space
    } else {
        // Penalize residual that cannot fit the smallest plausible item
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let min_useful = 10.0 + 15.0 * progress;
        if (post_residual as f64) < min_useful {
            score += 25.0;
        }
        // Reward moderate leftovers that remain reusable
        score -= 8.0 * ((post_residual as f64) / bin_capacity as f64).min(1.0);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 10.0; // next item won't fit here anyway
        } else {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline offset so it only wins for bad fits.
        score += 20.0 + 4.0 * open_bins_count as f64;
        // A new bin is attractive if mean residual across open bins is small.
        score -= mean_residual.min(50.0);
    } else {
        // Slight preference for tighter existing bins (small residual used well)
        score += 3.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item fits exactly or near-exactly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus for exact chain closure.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit: penalize dead space creation, scaled by how close we came.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 10.0;
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual means we consolidated space well.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins already exist, unless it's early
    // in the stream (hedging for future items) or the fit is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_capacity - item_size) as f64;
        score += 15.0 + 35.0 * progress - 0.2 * poor_fit;
        // New bin is attractive if the next item is large and won't fit elsewhere well.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically relative to capacity.
    let frag = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += frag * 40.0;

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Exact match with next item is even better.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits or mean residual is tiny.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 || (fitting_bins_count == 0) {
            score -= 30.0;
        } else {
            score += 10.0 + mean_residual * 0.3;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Prefer tighter bins among equals.
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear (quadratic) waste penalty
    let mut score = post * (1.0 + 0.8 * x);

    // Smooth stream-progress coupling: early on tolerate slack (future items may fill),
    // late in the stream punish dead space harder.
    let late = progress * progress;
    score += post * late * 1.5;

    // Reward using existing bins, especially when few alternatives fit.
    if bin_residual != bin_capacity {
        score -= 4.0;
        if fitting_bins_count <= 1 {
            score -= 8.0; // last chance: strongly favor this bin
        }
    } else {
        // New-bin candidate: penalize opening a bin unless the current bin leaves a
        // large unusable gap or few bins exist.
        score += 6.0 + 10.0 * (1.0 - progress);
        if open_bins_count < 2 {
            score -= 12.0;
        }
        // If this item would leave a tiny gap in an existing bin, opening new bin is fine.
        if x > 0.0 && x < 0.15 {
            score += 5.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap_after = post - nxt;
            if gap_after < 10.0 {
                score -= 6.0 * (1.0 - gap_after / 10.0);
            }
        } else {
            score += 2.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins first)
    score -= (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by residue mod 10
    // and by which capacity fraction band it falls into.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    let band = match pr {
        0 => 0.0,               // perfect fit — reward heavily
        1..=10 => 1.0,          // tiny sliver, nearly dead space
        11..=30 => 2.0,         // small leftover, still useful for tiny items
        31..=50 => 3.0,         // mid leftover
        _ => 4.0,               // large leftover, plenty reusable
    };

    // Reward perfect fits strongly.
    if pr == 0 {
        score -= 200.0;
    }

    // Penalize dead-space slivers (post_residual in 1..=10) — hard to reuse.
    if pr >= 1 && pr <= 10 {
        score += 40.0 + residue_class;
    }

    // Lookahead: does the next item fit into the post placement?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward leaving room for the lookahead item, scaled by how well it fits.
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 + slack * 0.5;
            // Extra reward if the next item leaves a perfect fit after itself.
            if (pr - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // Penalize placements that strand the lookahead item.
            score += 10.0 + (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be a terrible sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr >= 10 {
            score -= 60.0;
        } else {
            score -= 20.0; // still prefer it, but less when creating slivers
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are small relative to the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base bias: slightly favor reusing bins; new bin must earn it.
        score += 25.0;
        // If mean residual across open bins is small, a new bin is reasonable.
        if (mean_residual as u32) < item_size {
            score -= 20.0;
        }
        // Early in the stream, keep open-bin count lean; later, allow more bins.
        score += (1.0 - progress) * 15.0;
        // Don't open a new bin if plenty of bins already fit the item well.
        if fitting_bins_count > 2 {
            score += 30.0;
        }
    }

    // Tightness coupling: prefer bins where the item fills a large fraction of residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 20.0;

    // Mild preference for keeping mean residual spread healthy.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Band penalty shaping: large leftovers are mildly good, mid ones neutral.
    score += band * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space in the "unusable" small-gap zone (1..=20):
    // such gaps rarely fit future items (sizes >= 10 mostly), so waste them explicitly.
    if post_residual > 0 && post_residual <= 20 {
        score += 45.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fits (small post_residual but still usable) get a moderate bonus.
    if post_residual > 20 && post_residual <= 35 {
        score -= 10.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item would fit exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit here anyway; penalize leaving a gap that blocks nothing useful.
        score += 5.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score = 55.0 + crowded - 8.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step lookahead match: this bin can hold
    // the current item AND the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 100.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            // reward tight (but feasible) lookahead fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to leftover dead space
            score += 0.5 * post_residual as f64;
            // extra penalty if the leftover is small and unusable
            if post_residual < 10 {
                score += 25.0;
            }
        }
    } else {
        // last item: prefer tightest fit
        score += 2.0 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already "tight" — favor filling them if the fit is good.
    let rel = (post_residual as f64) - mean_residual;
    score += 0.3 * rel;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Penalize opening brand-new bins, especially early in the stream
    // when open bins still exist and could absorb the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * (1.0 - progress);
        // but allow a new bin if no open bin fits well (fitting count small)
        score -= 15.0 * (fitting_bins_count as f64).min(3.0);
    }

    // Mild pressure to keep the number of open bins from exploding.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual < 10 {
        score -= 15.0; // near-perfect closure is excellent
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        score += 12.0; // dead space the next item can't use
    }

    // Lookahead: if the next item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tightness = next_item_size as f64 / post_residual as f64;
        if lookahead_tightness > 0.8 {
            score -= 20.0 * lookahead_tightness;
        } else {
            score -= 5.0 * lookahead_tightness;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual > bin_capacity / 2 {
            score += 10.0; // poor fit in the only bin: soften the bonus
        }
    }

    // New-bin candidate handling: an empty bin gets a mild penalty so we only open
    // a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheap and builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // Many open bins with slack: opening yet another bin is wasteful.
        if open_bins_count > 4 && mean_residual > 30.0 {
            score += 15.0;
        }
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins below mean residual (consolidate slack into emptier bins).
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.08 * residual_diff;

    // Late in the stream, be conservative: avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.9 && bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;                       // normalized post residual in [0,1]
    let fit = item_size as f64 / cap;             // normalized item size
    let mean_r = mean_residual / cap;             // normalized mean residual

    // Base: penalize leftover space, quadratically (dead space is worse than small gaps).
    let mut score = norm_pr * norm_pr;

    // Smooth interaction: early in the stream, keep bins flexible (favor larger post residual);
    // late in the stream, squeeze tightly (favor small post residual).
    let flexibility = (1.0 - t) * (1.0 - t);
    score += 0.8 * flexibility * norm_pr;
    score -= 0.6 * t * norm_pr * fit;

    // Reward tight fits: post residual close to zero gets a strong cubic discount.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 0.5 * tightness * fit;

    // Penalize bins whose post residual is awkwardly small relative to the mean residual
    // (creates unusable slivers), but softly, via smooth coupling.
    let sliver = (norm_pr - mean_r).abs();
    score += 0.25 * sliver * sliver * (0.5 + t);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 0.4 * (1.0 - gap) * (1.0 - gap) * (1.0 - gap);
    }

    // New-bin candidate (empty bin): penalize moderately so it is only chosen when
    // no open bin offers a decent fit; decay the penalty as the stream progresses.
    if bin_residual == bin_capacity {
        score += 0.9 + 0.4 * (1.0 - t) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, scaled by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Harmonic class of post_residual: dead space in small classes is costly.
    let cap = bin_capacity as u32;
    let cls = post_residual % (cap / 4).max(1);
    if cls != 0 {
        score += 3.0;
    }
    // Perfect harmonic classes (0, 25, 50, 75 mod 100) are reusable.
    if post_residual % (cap / 4) == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: reward post_residual that can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Integer division threshold: post_residual / next_item_size >= 2
            if post_residual / next_item_size >= 2 {
                score -= 4.0;
            }
        } else {
            // Wasted lookahead space: penalize proportionally to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
    }

    // Stream progression: early on, be pickier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - item_size) as f64 * 0.1;

    // Mean residual coupling: if this bin is far below mean residual, it is
    // already fragmented; prefer bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Penalize leaving tiny unusable slivers (post_residual < 10 threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Modulo-10 harmonic alignment between item and post residual.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    // Many open bins: discourage spreading, favor consolidation.
    if open_bins_count > 8 {
        score += open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are pure waste -> heavy penalty.
    if post_residual > 0 {
        let dead = (post_residual as f64) < 10.0;
        if dead {
            score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading waste;
    // prefer filling existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: residual likely becomes dead space.
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (consolidate waste into few bins, keep large residuals concentrated).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 5.0 * (res - mean_residual) / mean_residual;
    }

    // New-bin candidate: only attractive when no good fit exists among open
    // bins (i.e., this empty bin competes via its raw residual = capacity).
    if bin_residual == bin_capacity {
        // Penalize mildly so poor fits in open bins still win, but allow
        // opening when open bins would create large dead space.
        score += 20.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // 2-step lookahead: reward when post_residual matches next item size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 25.0 * (1.0 - gap.min(1.0));
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to next item: penalize proportionally.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when item is large / fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening a new bin normally; relax penalty for large items or late stream.
        score += 35.0 - 25.0 * fill_ratio - 10.0 * pressure;
        // If no open bin could fit, new bin is the only option: neutralize penalty.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by a fit-quality factor.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score *= 1.0 - 0.35 * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 + 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more as the stream progresses and when many bins are open.
        score += 30.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // If the item is small relative to mean residual, opening a new bin is wasteful.
        if (item_size as f64) < mean_residual {
            score += 10.0;
        }
    }

    // Mild penalty for deviating from mean residual (encourages balanced bin usage).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr as f64 * (1.0 + 0.8 * post_norm * post_norm) - 20.0 * post_norm * post_norm * post_norm;

    // Smooth coupling with stream progress: tight packing matters more early
    let urgency = (1.0 - progress).powi(2);
    score += 15.0 * urgency * (1.0 - fit_ratio);

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: reward if next item could fit into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr / cap.max(1.0));
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: make it attractive only when residual is huge and stream is late
    if bin_residual == bin_capacity {
        score -= 25.0 * progress;
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead space penalty: residuals below a quarter are hard to reuse.
    if post_residual < 10 {
        score -= 100.0; // perfect fill, excellent
    } else if pr < quarter {
        score += 12.0; // small dead space, penalize mildly
    } else if pr < 2.0 * quarter {
        score -= 3.0; // half-class: decent
    } else {
        score -= 6.0; // large residual still reusable
    }

    // Integer-division harmonic class of post_residual (multiples of 8).
    let hclass = post_residual / 8;
    let harmonic_bonus = match hclass {
        0 => 8.0,
        1 => 4.0,
        2 => 2.0,
        3 => 1.0,
        _ => 0.5,
    };
    score -= harmonic_bonus;

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward for tight chaining (next item nearly fills leftover)
            let gap = post_residual - next_item_size;
            if gap <= 8 {
                score -= 8.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: prefer filling as tightly as possible
        score += pr * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty to keep bin count from proliferating.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(4.0);
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = mean_residual < item_size as f64 * 0.9;
        if poor_fit && open_bins_count > 0 {
            score -= 20.0 * progress;
        } else {
            score += 25.0; // discourage opening new bins unnecessarily
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - pr) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is nearly unusable
    // (min item size is 10), so punish it heavily beyond its raw value.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit is the ideal outcome: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-but-usable fits (post_residual small but >= min item) are good.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin; if next item can't fit anywhere else and fits
    // here, favor it too.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit in the leftover: leftover may become dead space.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; new-bin candidate (residual == capacity)
    // gets penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 2.0;
        // But allow a new bin when existing fits would create dead space.
        if post_residual == bin_capacity - item_size && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild progression term: early in the stream, be a bit more willing to
    // open bins (spread risk); later, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Prefer bins whose residual is below the mean (more full bins get filled).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins where post_residual exactly
    // matches the next item size (perfect 2-chain), penalize mismatches.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as u32 == next_item_size {
            score -= 30.0; // perfect 2-chain: bin closed by next item
        } else if post_residual as u32 > next_item_size {
            score += diff * 0.5; // next item fits but leaves more slack
        } else {
            score += diff * 1.5; // next item won't fit: dead space risk
        }
    } else {
        // Last item: prefer tightest fit
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize wasting a nearly-full bin's identity on a loose fit
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // tiny leftover is near-perfect packing
    }

    // New-bin candidate: keep it neutral-to-slightly-penalized so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 4.0;
    }

    // Discourage many small open bins from all getting loose fits
    if open_bins_count > 4 {
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // penalize leaving a gap too small for the next item
            score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 30.0 + 20.0 * progress;
        // If mean residual across open bins is large, opening new bins is wasteful
        score += (mean_residual / bin_capacity as f64).powi(2) * 40.0;
        // Few fitting bins -> new bin less costly
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // Large items prefer fresh bins
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Time horizon: early on, keep bins flexible (moderate residuals); late, pack greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * tightness;

    // Many open bins: encourage consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - tightness);

    // Prefer bins below mean residual (keep residual distribution balanced)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with a smooth
    // non-linear penalty for mid-range dead space (worst around x ~ 0.5).
    let mut score = post;
    score += 25.0 * 4.0 * x * (1.0 - x); // peaks at x=0.5, zero at x=0 or 1

    // Smooth coupling with stream progress: early on, waste matters less;
    // later, tighten fits more aggressively.
    score -= (1.0 - progress) * 10.0 * x * x;
    score += progress * 15.0 * x * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: if this is the only bin that fits, reward strongly
    // (smoothly scaled by how much room remains after placement).
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x * x);
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward; if it leaves a near-perfect pair, discount the score.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        let fit_quality = 1.0 - gap / cap;
        if post >= nx {
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            score += 8.0 * (nx - post) / cap;
        }
    }

    // Mild pressure toward reusing existing bins vs opening new ones:
    // new empty bin (post == cap) gets a penalty that grows with open bins.
    if post_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (consolidating space).
    score -= 3.0 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover: classify post_residual by integer division
    // against common item-size bands (items 1..100). Residuals in the smallest
    // classes are nearly unusable dead space.
    let cls = post_residual / 10; // class 0..10
    score += match cls {
        0 => -50.0,                     // leftover < 10: dead space anyway, fine
        1 => 30.0,                      // 10..19: only tiny items can use it
        2 => 15.0,                      // 20..29
        3 => 5.0,                       // 30..39
        4 => 0.0,
        _ => -5.0,                      // large leftovers are flexible
    };

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward; if next item cannot fit into post_residual but the
    // post_residual is small, mild penalty (dead space).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; leftover becomes dead space
            score += (post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin progressively as the
    // stream matures and bins are already open, unless it's early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 80.0 * progress + 2.0 * open_bins_count as f64;
        // But if item is large (>= 70), a fresh bin is often good.
        if item_size >= 70 {
            score -= 60.0;
        }
    }

    // Prefer bins below mean residual (tighter bins get used first),
    // gently steering toward best-fit behavior.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Small tie-break favoring fuller bins via modulo harmonic of residual.
    if post_residual > 0 {
        score += (post_residual % 7) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post residual that cannot fit even the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    } else {
        // Larger residuals remain useful; reward them mildly.
        score -= 3.0;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit here; mild reward.
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the leftover gap: penalize proportionally
        // to how much dead space is created relative to the gap.
        score += 8.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than leaving many half-empty bins around.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 2.5;
    if bin_residual != bin_capacity {
        // This is an existing bin: reward using it when many bins are open.
        score -= open_pressure;
    } else {
        // New-bin candidate: penalize opening a new bin more when many bins
        // are already open, unless post residual would be very usable.
        score += open_pressure * 1.5;
        // A fresh bin has huge residual; only attractive if the item is large
        // and would leave a well-usable residual anyway.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, using it
    // avoids opening a new bin; strongly favor it (unless it creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 && post_residual > 0 {
            score += 25.0; // but not if it creates dead space
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight; filling it further is efficient consolidation.
    let residual_gap = mean_residual - bin_residual as f64;
    if bin_residual != bin_capacity {
        if residual_gap > 0.0 {
            score -= residual_gap * 0.3;
        } else {
            score += (-residual_gap) * 0.15;
        }
    }

    // Stream progression: early in the stream, be slightly more willing to
    // open bins (future items unknown); late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    } else {
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect or near-perfect
    // match between post_residual and the next item's size (chained fit).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain (post_residual == next_item_size) gets a big bonus.
        if lookahead_gap == 0.0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: reward closeness, scaled by fit ratio.
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fit_ratio;
        } else {
            // Next item cannot follow in this bin: penalize dead space
            // proportional to how much would be wasted relative to capacity.
            let waste_ratio = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste_ratio;
        }
        // Extra coupling: gap penalty grows quadratically with small gaps.
        score += 0.35 * (lookahead_gap * lookahead_gap) / (bin_capacity as f64);
    } else {
        // Last item: simply minimize residual as tightly as possible.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize bins whose residual deviates from the fleet mean residual
    // (keep residuals homogeneous so future items fit many bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild pressure against proliferating bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to typical residuals, i.e. poor fits elsewhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer a new bin for large items or when open bins are crowded.
        score = score - 10.0 * tightness + 6.0 * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 15.0; // next item needs a fresh bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual already favored; amplify with ratio.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;

    // Penalize tiny dead space that nothing (min size 1) could still use well:
    // if post_residual is smaller than half the next item, it's likely dead.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // Lookahead: chain fit is valuable, reward strongly.
            score -= 12.0 + (next_item_size as f64 / post_residual as f64) * 6.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted space.
            score += (post_residual as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a neutral-to-high score so we
    // only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (late in the stream, opening a bin is less costly since fewer future items).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 - progress * 15.0;

        // If many bins are open with slack, discourage yet another one.
        score += (open_bins_count as f64) * 1.5;
        // If mean residual is large, existing bins have room; discourage new bin.
        score += mean_residual * 0.3;
        // But if the item is large relative to capacity, a fresh bin is attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // If no other bin fits, opening is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        return score;
    }

    // Prefer bins whose residual is far below the mean (consolidate slack usage).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Slight preference for filling older/emptier bins as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes costlier.
    let coupling = 1.0 + progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 0.35 * pr * pr / cap * coupling;

    // Reward near-perfect fits smoothly (small post_residual).
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize residuals that cannot fit the next item (smooth logistic).
    if next_item_size > 0 {
        let ratio = pr as f64 / next_item_size as f64;
        let usable = 1.0 / (1.0 + (-3.0 * (ratio - 1.0)).exp());
        score -= 8.0 * usable;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mildly prefer consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // New empty bin candidate: post_residual == capacity, naturally high score;
    // add extra penalty unless current bins are badly fragmented.
    if (bin_residual as u32) == (bin_capacity as u32) {
        score += 15.0 - 10.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are great: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic class: classify post_residual into capacity-fraction classes.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score -= 10.0; // dead space small, good
    } else if post_residual <= half {
        // mid leftover: penalize slightly unless it can host the next item
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    } else {
        score += 10.0; // large leftover wasted
    }

    // Modulo arithmetic on post_residual: small mod classes are harder to fill later.
    let m = post_residual % 10;
    if m > 0 && m < 5 {
        score += (5 - m) as f64 * 1.5; // awkward remainder penalty
    } else if m == 0 {
        score -= 4.0; // round residual more reusable
    }

    // Next-item lookahead coupling.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // this bin can chain the next item
        } else if post_residual >= next_item_size / 2 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue.
    if bin_residual == bin_capacity {
        // empty bin: neutral baseline; penalize if item is small (waste of fresh bin)
        score += (item_size as f64) * 0.35;
        if item_size <= 20 {
            score += 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count.min(50) as f64).sqrt();

    // Prefer bins below mean residual (fill emptier bins first to consolidate).
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score += (resid_f - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - resid_f) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps (< 10) are pure waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual > 0 {
        score -= (item_size as f64 / post_residual as f64) * 2.0;
    } else {
        score -= 20.0; // perfect fit bonus
    }

    // Pressure on number of open bins: discourage spreading when many bins open,
    // but encourage using open bins when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += bin_pressure * 0.3;

    // Prefer bins whose residual is close to what's needed (avoid fragmentation).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0; // dead space that next item can't use
    }

    // New bin candidate: mild penalty so open bins are preferred unless fit is bad.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: penalize small post-residuals super-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0 + 3.0 * (10 - post_residual) as f64;
    }

    // 2-step lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Bonus scaled by tightness of the lookahead fit.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 200.0; // chain of perfect fits
            }
        } else {
            // Post-residual too small for next item: dead space penalty.
            score += 10.0 + 0.5 * (nxt - post_residual as f64);
        }
    }

    // Compare residual to mean: prefer filling bins below-average residual (tighter bins).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening new bins early in the stream; allow it late when bins are fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 150.0 - 100.0 * progress;
        // New bin attractive only if item leaves large residual for future items.
        score += 0.2 * post_residual as f64;
    }

    // Slight preference for bins with larger pre-residual when many bins are open.
    score += 0.1 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But allow new bins late in stream or when mean residual is very fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 && progress > 0.5 {
            score -= 12.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear polynomial shaping
    let mut score = pr + 40.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (tight packing)
    score += 20.0 * norm_pr.powf(2.0) * progress;
    score -= 15.0 * norm_pr * progress;

    // Penalize residual that is too small to be useful (dead space),
    // scaled by how far we are through the stream
    let dead = (norm_pr - (next_item_size as f64 / cap)).max(0.0);
    score += 10.0 * dead * (0.5 + 0.5 * progress);

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates favorably from the mean residual
    score -= 0.3 * (mean_residual - pr);

    // Lookahead: bonus if next item fits exactly in the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.2 * gap;
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // New-bin candidate: slight penalty so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low divisors is worse
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by small integers => more reusable
    let mut harmony = 0.0;
    if post_residual > 0 {
        if post_residual % 10 == 0 { harmony += 6.0; }
        else if post_residual % 5 == 0 { harmony += 3.0; }
        if post_residual % 2 == 0 { harmony += 1.0; }
        if post_residual >= 10 && post_residual <= 30 { harmony += 4.0; }
        if post_residual < 10 { harmony -= 8.0; } // tiny dead space
    }
    score -= harmony;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item still fits: good chain, but prefer leaving harmonious residue
            let next_res = post_residual - next_item_size;
            if next_res % 10 == 0 { score -= 60.0; }
            score -= (next_item_size as f64) * 0.3;
        } else {
            // next item won't fit here; penalize less if post_residual is small waste
            score += (next_item_size as f64) * 0.1;
        }
    }

    // Last-chance bin: avoid opening a new bin if this fits well
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless residual capacity is large relative to typical need
    if bin_residual == bin_capacity {
        // opening new bin: base cost, discounted late in stream or when bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0 - 150.0 * progress;
        if mean_residual > cap * 0.4 { score -= 50.0; } // fragmentation justifies fresh bin
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size { score -= 40.0; }
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score += (mean_residual - (bin_residual as f64)) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (min item size is small, but very small gaps waste capacity).
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // worst: unusable sliver
        } else if post_residual <= 20 {
            score += 18.0;
        } else if post_residual <= 35 {
            score += 6.0;
        }
    } else {
        // Perfect fit is highly desirable
        score -= 30.0;
    }

    // Reward exact or near-exact fits relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            // next item cannot use this residual: mild penalty unless residual is large
            if post_residual < 25 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open
    // with slack available.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // If mean residual across open bins is high, avoid adding more slack
    // to an already-slack bin; prefer concentrating slack.
    if mean_residual > 40.0 && post_residual > mean_residual {
        score += 5.0;
    } else if post_residual as f64 <= mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced if open bins are congested
        // (high mean residual means existing bins are nearly full).
        let congestion = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 45.0 - 35.0 * congestion;
        // A fresh bin has huge residual; don't let the raw residual term
        // make it look artificially bad/good — neutralize via the above.
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but avoid tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 120.0; // exact two-item chain fill
        } else {
            score += diff * 0.9;
        }
        // If next item fits exactly into residual after this placement OR
        // next item fits current residual better after placing here.
        if next_item_size <= post_residual {
            score -= 15.0;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: filling a bin below-average residual is good.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins are all tight or item is huge.
    let tight = open_bins_count == 0 || mean_residual < item_size as f64 * 0.5;
    if bin_residual == bin_capacity {
        if tight {
            score -= 30.0;
        } else {
            score += 40.0 + mean_residual * 0.2;
        }
    }

    // Prefer filling nearly-full bins more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on large post-residual.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Penalize dead space that no future item (>= min size 1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable slivers
    }

    // Lookahead: if next item fits perfectly into post_residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0; // next item won't chain here
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many fitting bins: this is a commodity placement; prefer best fit only.
    if fitting_bins_count > 1 {
        score += 0.5 * fitting_bins_count as f64;
    }

    // New-bin candidate handling: opening a fresh bin is attractive early or
    // when mean residual is fragmented, but costly late in the stream.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 * (1.0 - t);                       // cheap early
        score += 35.0 * t;                               // expensive late
        score += 5.0 * (open_bins_count as f64).ln();    // many open bins already
        if fragmentation > 40.0 {
            score -= 8.0; // open bins are fragmented, fresh bin helps
        }
    }

    // Mild preference for bins with residual close to item (near-exact fit).
    let fit_gap = (bin_residual as f64 - item_size as f64);
    score += 0.15 * fit_gap;

    // Penalize placing large items into nearly-full bins when more space exists elsewhere.
    if item_size > 60 && bin_residual < item_size + 15 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Base: penalize leftover space, but nonlinearly — small residuals are cheap.
    let mut score = (pr / cap).powf(1.6) * cap;

    // Smooth coupling: tight fits rewarded more as stream progresses.
    score -= fit * fit * (1.0 + 2.0 * progress) * 30.0;

    // Dead-space penalty: residual that can't hold even the next item is worse.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        // Reward leaving room exactly for the next item.
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-gap / 10.0).exp();
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins below mean residual (consolidation).
    score += (mean_residual - pr) * 0.3 * (0.5 + progress);

    // Mild penalty on spreading across many bins early.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // Slight preference for using existing bins vs new bin (new bin has pr = cap,
    // so its base score is already high; add small extra nudge scaled by fit).
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible by common
    // item sizes (10, 20, 25, 50) is "reusable", otherwise it's dead space.
    let pr = post_residual;
    let mut reusable = 0.0;
    if pr == 0 {
        reusable += 12.0; // perfect fit is best
    } else {
        if pr % 10 == 0 { reusable += 4.0; }
        if pr % 20 == 0 { reusable += 3.0; }
        if pr % 25 == 0 { reusable += 3.0; }
        if pr % 50 == 0 { reusable += 4.0; }
    }
    score -= reusable;

    // Penalize small dead space that nothing (>=10) can ever use.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the leftover class match the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // leftover can host next item exactly or with harmonious residue
            let r2 = pr - next_item_size;
            score -= 5.0;
            if r2 == 0 { score -= 6.0; }
            if r2 % 10 == 0 { score -= 2.0; }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when
    // existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        // fresh bin score ~ mid-range leftover; discourage when good fits exist
        score += 10.0 - 0.15 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing fits anywhere: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // big item coming, fresh capacity useful
        }
    }

    // Tightness term: prefer filling bins proportionally tighter.
    score += 0.25 * (1.0 - (item_size as f64) / cap) * (post_residual as f64 / cap);

    // Late in the stream, prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * (open_bins_count as f64).sqrt();

    // Mild preference for bins below mean residual (balance avoidance of
    // many half-empty bins) weighted by harmonic class of mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable item (1..100 range) are wasted forever.
    // Penalize "unusable" gaps quadratically: gaps below ~10 can never be
    // filled by typical items, gaps just above a plausible next size are risky.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // pure dead space: hard penalty
            score += (10.0 - gap) * 8.0;
        } else if gap < 25.0 {
            // risky small gap: moderate quadratic penalty
            score += (25.0 - gap) * (25.0 - gap) * 0.12;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward heavily; if next item is blocked by this placement, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when bins are few.
    if bin_residual == bin_capacity {
        // new-bin candidate: add pressure proportional to open bins count
        score += open_bins_count as f64 * 4.0;
        // but if mean residual across open bins is small (all bins crowded),
        // a new bin is more acceptable: subtract a bit.
        score -= mean_residual * 0.15;
        // early in the stream, opening bins is cheap; later it is costly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else {
        // placing into an existing bin relieves pressure
        score -= 3.0;
    }

    // Slight preference for bins below mean residual (balance load,
    // keep some large bins available for large future items).
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin completely
        } else if post_residual > next_item_size {
            // next item fits; the tighter the leftover chain, the better
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Prefer tight fits relative to current item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Avoid wasting bins with large residuals when many bins are open
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins far below mean residual are "dusty" -> penalize
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // slightly reward below-mean (tighter) bins
    }

    // Late in the stream, consolidate: favor filling existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 10.0 + 30.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for typical items (unusable slivers).
    let pr = post_residual as f64;
    if pr > 0.0 {
        let sliver = (pr / cap).powf(2.0);
        score += 12.0 * sliver * (1.0 - pr / cap);
    }

    // Lookahead: penalize leaving a residual that barely fails to fit the next item,
    // reward leaving room that comfortably accommodates it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr + 1.0) >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt + 1.0) / cap);
        } else if pr > 0.0 && nxt - pr <= 10.0 {
            score += 10.0; // near-miss: residual almost fits next item
        }
    }

    // Last-chance bin: strong bonus so we avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).ln() + 1.0
        } else {
            0.0
        };
        // Base penalty for opening a new bin, softened when many bins fit poorly.
        score += 30.0 - 10.0 * pressure;
        // If the new bin would be nearly full from this item, it's a good open.
        score -= 14.0 * fill_ratio;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If open bins have lots of residual but we still open, that's wasteful.
        score += 0.15 * mean_residual;
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Quadratic dead-space penalty, stronger later in the stream
    score += 40.0 * norm_pr * norm_pr * (0.3 + progress);

    // Reward tight fits (small post_residual) with smooth interaction
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * 0.5;

    // Lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 15.0 * progress;
        } else {
            score -= (pr - next_item_size as f64) * 0.15;
        }
    }

    // Last-chance fitting bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild preference for bins below mean residual (balance)
    score += 0.1 * (pr - mean_residual).abs();

    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..=10, 11..=25) are more valuable than
    // mid-range residues. Reward tight packing.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fill
    } else if post <= 10 {
        score -= 35.0;
    } else if post <= 25 {
        score -= 15.0;
    } else if post <= 50 {
        score += 8.0;
    } else {
        score += 18.0; // large dead space
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size < post {
            let chain_waste = post - next_item_size;
            if chain_waste <= 10 {
                score -= 20.0;
            } else {
                score += chain_waste as f64 * 0.3;
            }
        } else {
            // next item cannot follow here: mild penalty proportional to gap
            score += (next_item_size - post) as f64 * 0.2;
        }
    }

    // Last chance bin: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large relative to capacity or the current bin would leave bad residue.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64;
        // opening a new bin is discouraged generally, more so early on
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 25.0 + 10.0 * (1.0 - fill_ratio) + 5.0 * progress;
        // if it would be the only fitting bin, opening is less bad
        if fitting_bins_count == 0 {
            new_bin_penalty -= 40.0;
        }
        score += new_bin_penalty + pressure * 0.5;
    }

    // Modulo-harmonic bonus: residues that are multiples of common item
    // classes (10, 20, 25, 50) are reusable by future items.
    let harmonic = post % 10 == 0 || post % 25 == 0 || post % 20 == 0;
    if harmonic && post > 0 && post <= 60 {
        score -= 12.0;
    }

    // Prefer bins tighter than the mean residual (best-fit bias).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild preference for filling fewer bins when many are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones,
    // and opening a new empty bin becomes more costly.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but slightly prefer fuller-than-mean bins to consolidate waste.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is better (already base).
    // Penalize dead space relative to mean residual.
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-gap / 12.0).exp(); // perfect 2-chain bonus
            score += 0.25 * gap; // penalize leftover after chain
        } else {
            // next item cannot follow here; penalize proportionally
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
        // Extra reward if next item would fit exactly after this one
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // last item: purely minimize waste
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin early in the stream or when few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
        // New bin is attractive only if item is large and no good fit exists
        if item_size >= 60 && (fitting_bins_count == 0 || post_residual < 10) {
            score -= 15.0;
        }
    }

    // Slight preference for filling nearly-full bins
    score -= 0.05 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small leftover space (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item (pairing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // Penalize blocking the next item badly.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when current
    // open bins are crowded or the fit here is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64;
        // Penalize new bin when existing bins still have room; relax over time.
        score += 55.0 - 25.0 * crowded - 10.0 * progress;
        // If no open bin fits at all, new bin is essential (fitting_bins_count==0).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for using bins with larger residuals when many are open,
    // balancing load and avoiding fragmentation accumulation.
    score += 0.05 * (open_bins_count as f64) * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Slight global pressure: as mean residual shrinks, tighten selection further.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in stream, penalize waste more strongly
    score += 30.0 * norm_pr * progress * (1.0 - progress * 0.5);

    // Penalize dead space relative to mean residual of open bins (smooth quadratic)
    let dead = (pr - mean_residual) / cap;
    score += 15.0 * dead * dead;

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    } else {
        score -= 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item fits into post-residual (smooth coupling)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = (next_item_size as f64) / pr.max(1.0);
        score -= 20.0 * fit_frac * (1.0 - fit_frac) * 4.0 * fit_frac.max(0.25);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty scaled by gap
        let gap = ((next_item_size as f64) - pr) / cap;
        score += 10.0 * gap * gap;
    }

    // New-bin candidate handling: penalize opening new bins mildly, less as stream progresses
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress;
    }

    // Slight preference for bins with lower residual before placement (tighter packing)
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

