    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let fill = 1.0 - norm_pr; // fill fraction achieved by this placement

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Smooth polynomial coupling: tight fits are increasingly valuable later in the stream
    score -= fill * fill * (1.0 + 40.0 * progress) * cap * 0.25;

    // Penalize dead space quadratically, but only for unusable gaps
    let dead = norm_pr;
    score += dead * dead * cap * (0.5 + 0.5 * progress);

    // Lookahead: reward bins whose post residual can host the next item (smooth margin)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let margin = (pr - ns) / cap;
        if margin >= 0.0 {
            score -= 12.0 * margin * (1.0 - margin) * (1.0 + progress);
        } else {
            score += 8.0 * (-margin) * cap * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins (encourage consolidation)
    score += (open_bins_count as f64).ln1p() * (1.0 + norm_pr) * 2.0;

    // Mean residual coupling: placing into a below-average residual bin is good
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (5.0 + 10.0 * progress);

    // New-bin candidate: make empty bins attractive only when placement would leave big gaps
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - item_size as f64 / cap) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
