pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use well
    // are heavily penalized. Small leftover gaps (1..=10) are "dead space".
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity (low waste ratio).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Penalize bins whose residual is far below the mean (they are already
    // fragmented); prefer bins with large residual that can absorb this item.
    let resid_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= resid_gap * 6.0;

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // by making the fresh-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + open_bins_count as f64 * 1.5 + progress * 5.0;
    } else {
        // Reward using existing bins, more so when bins are plentiful.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; mild penalty for stranding space.
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize dead space.
        score += 8.0;
    }

    // Exact wrap reward: post_residual equals next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 5.0;
        if fit_ratio > 0.8 && next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0; // open new bin for a good fit that leaves room
        }
    }

    // Early stream: be slightly conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space that no realistic item can use:
    // dead space below the minimum item size is wasted.
    if post_residual < 10 {
        score -= 8.0; // perfectly sealed bin — great
    } else if post_residual < item_size {
        // residual too small for another item of this size class; mildly bad
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // heavily reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // next item won't fit here; penalize more when post_residual is small
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 6.0 + fit_ratio * 4.0;
    }

    // Global state: when many bins are open relative to progress, prefer
    // consolidating into existing bins (penalize new-bin candidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bins_per_step = open_bins_count as f64 / (step_index.max(1) as f64);
    score += bins_per_step * 5.0 * progress;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (high mean residual dispersion vs. item) or few bins fit the item.
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        score += 10.0;
        if mean_fit_gap > 20.0 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        score -= (1.0 - progress) * 5.0;
    }

    // Mild preference for filling bins that are already quite full
    // (keeps many near-full bins instead of many half-full ones).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill * 4.0;

    // Penalize leaving residual far from mean (fragmentation of global state).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual polynomial in progress
    let prn = pr / cap;
    score += 12.0 * prn * prn * (1.0 + progress) - 8.0 * prn * progress;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 10.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + 0.5 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn);
    }

    // Prefer bins with residual below mean (consolidating space)
    score += 0.05 * (pr - mean_residual);

    // Lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }

    // Slight preference to fill existing bins when many are open
    score += 0.02 * open_bins_count as f64 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall in "usable" classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes on post_residual: multiples of small sizes (10..=30) are highly reusable
    let mut harmonic_bonus = 0.0;
    for m in [10u32, 20, 25, 30, 50].iter() {
        if post_residual % m == 0 && post_residual > 0 {
            harmonic_bonus += 12.0;
        }
    }
    // Small post_residual = tight fit (good packing), but avoid dead space < 10
    if post_residual == 0 {
        harmonic_bonus += 40.0; // perfect fill
    } else if post_residual < 10 {
        harmonic_bonus -= 25.0; // dead space
    }

    // Integer division threshold: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        harmonic_bonus += 8.0;
    } else if post_residual >= 3 * quarter {
        harmonic_bonus += 5.0; // large residual still flexible
    }

    // Lookahead: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        harmonic_bonus += 15.0;
        // harmonic class match: next item divides residual evenly
        if post_residual % next_item_size == 0 {
            harmonic_bonus += 10.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        harmonic_bonus -= 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        harmonic_bonus -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are congested
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64) * (mean_residual / cap);
        // open new bin only if existing residuals are small relative to item
        if item_size as f64 > mean_residual {
            harmonic_bonus -= 10.0 + congestion;
        } else {
            harmonic_bonus += 30.0 + congestion * 5.0;
        }
    }

    // Late in the stream: favor tighter fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= harmonic_bonus * (0.7 + 0.6 * progress);

    // Slight penalty for deviating from mean residual (balance bin usage)
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward filling a large fraction of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure and mean residual.
        score += 15.0 + pressure * 5.0 + mean_residual * 0.5;
        // But if no existing bin fits well (this item is large relative to mean residual),
        // soften the penalty so a fresh bin becomes attractive.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    } else {
        // Using an existing bin slightly relieves pressure.
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tightness = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - lookahead_tightness / bin_capacity as f64);
    }
    // Penalize if post-residual is too small for the next item (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: post_residual exactly
    // equals next_item_size, so the next item seals this bin completely.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Partial reward: next item fits with little waste left over.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack / 10.0);
    }
    // Penalize creating dead space smaller than the minimum plausible item (1..=100
    // range): residual too small for the next item is likely wasted forever.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // Early in the stream, opening bins is cheaper (more items to come to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 60.0;
        // If next item is large and current bin would leave a bad remainder anyway,
        // slightly favor a fresh bin.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 20.0;
        }
    }

    // Mild penalty for leaving large residuals that few future items can use.
    if pr > 50.0 {
        score += (pr - 50.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Waste that blocks the next item.
        score += 6.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If few bins fit the item, opening fresh is more attractive.
        if fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Tight bins (low residual) are precious; prefer placing into loose bins.
    let tightness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score += 5.0 * tightness;

    // Prefer bins below mean residual slightly (balance load).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be conservative about opening bins;
    // late in stream, exploit exact fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage fragmentation into more bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear sharpening.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * norm_pr);

    // Smooth polynomial coupling of post residual with stream progress:
    // late in the stream, tight packing matters more.
    let coupling = norm_pr * (1.0 - norm_pr) * (0.5 + progress);
    score -= 0.35 * coupling;

    // Reward exact / near-exact fits with a smooth bump.
    let fit_quality = 1.0 - norm_pr;
    score -= 0.6 * fit_quality * fit_quality * fit_quality;

    // Penalize leaving dead space that the next item cannot use (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (pr - nxt).max(0.0) / cap;
        score += 0.8 * slack * slack;
        // Bonus when this placement also sets up the next item nicely.
        let usable = 1.0 - ((nxt - pr).abs() / cap).min(1.0);
        score -= 0.25 * usable * usable * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.5;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; smooth in count.
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Encourage balancing residuals across bins early, tighten late.
    let dev = (mean_residual - pr) / cap;
    score += (0.3 - 0.45 * progress) * dev * dev;

    // New-bin candidate: make it unattractive unless residual of this bin is hopeless.
    if bin_residual == bin_capacity {
        score += 2.0 - 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "friendly"
    // (multiples of small divisors) are more likely reusable later.
    let r = post_residual;
    if r > 0 {
        let mut friendliness = 0.0;
        for d in [2u32, 4, 5, 8, 10, 20, 25, 50] {
            if r % d == 0 {
                friendliness += 1.0;
            }
        }
        score -= 2.0 * friendliness;
    }

    // Dead-space penalty: tiny post-residuals are wasted space.
    if r < 10 {
        score += 25.0;
    } else if r < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if r == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 6.0;
            // Harmonic bonus: next item divides the post residual evenly.
            if r % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += 5.0;
        }
    } else {
        // Last item: prefer zero residual strongly.
        score -= 10.0 * (bin_capacity - r) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // fit is terrible (large dead space) and stream is still young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if r >= 10 || progress > 0.7 {
            score += 15.0;
        } else {
            score -= 3.0;
        }
    }

    // Tie-break: tighter bins (small residual before placement) slightly preferred.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    // Small global pressure: many open bins -> pack tighter.
    score += 0.01 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
