        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0 * (20 - post_residual) as f64 / 10.0;
    }

    // Reward tight fits: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Penalize bins whose residual is far above mean (avoid fragmenting large gaps).
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if next item could use the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap just below the next item's need (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // New-bin candidate: prefer it only late in the stream or when open bins are numerous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 25.0 * progress + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer minimal post_residual (best fit).
    // Reward tight fits super-linearly (dead space is the enemy).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64);

    // Aggressive 2-step lookahead: reward if the NEXT item exactly fits
    // the post_residual of this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step chain: extremely desirable.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits after placement: moderate reward, scaled
            // by how snugly it lands (smaller leftover is better).
            let chain_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - (chain_left as f64) / (bin_capacity as f64));
        } else {
            // Next item cannot use this bin's leftover: penalize
            // proportionally to the overshoot, favoring bins whose
            // leftover is at least somewhat reusable later.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.35 * overshoot;
        }
    }

    // Compare against mean residual: placing into a bin that is already
    // tighter than average concentrates waste, which is good (fewer
    // fragmented bins). Placing into a looser-than-average bin spreads
    // waste and is mildly penalized.
    score += 0.25 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when
    // no open bin offers a decent fit. Penalize the fresh bin so it
    // loses to any reasonable existing fit, but let it win over bins
    // that would strand large dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening fresh bins is less risky since
        // fragmentation matters less; relax the penalty slightly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
    } else if post_residual < 10 {
        // Existing bin nearly perfectly filled: great, big reward.
        score -= 20.0;
    }

    // Mild pressure to consolidate: with many open bins, prefer
    // filling existing ones over spreading.
    score += 0.15 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly (waste grows superlinearly).
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / bin_capacity as f64;

    // Reward tight fits.
    score -= 6.0 * (item_size as f64 / bin_residual as f64);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        // Extra reward if next item fills the bin completely after this placement.
        if next_item_size == post_residual {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this residual; mild penalty proportional to leftover.
        score += 1.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual
    // or existing bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 20.0 * (1.0 - crowding);
        // Late in stream, prefer filling existing bins more strongly.
        score += 10.0 * progress;
        if item_size >= 50 {
            score -= 8.0; // large items fine in fresh bins
        }
    }

    // Prefer bins whose residual deviates below mean (compact bins) when mean is small.
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, penalize large post residuals quadratically
    let mut score = post + 40.0 * norm_post * norm_post * cap;

    // Non-linear coupling: large residuals matter more early, tight fits matter more late
    let early = (1.0 - progress).powi(2);
    let late = progress.powi(2);
    score += 12.0 * early * norm_post * cap;
    score -= 15.0 * late * (1.0 - norm_post) * cap;

    // Dead-space penalty: post residual too small to hold typical future items
    let useless = if post > 0.0 && post < 10.0 { (10.0 - post) / 10.0 } else { 0.0 };
    score += 25.0 * useless * useless;

    // Lookahead: reward if next item fits the post residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let snug = 1.0 - ((post - nxt) / cap).powf(2.0);
            score -= 18.0 * snug;
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - norm_post);
    }

    // Mean-residual coupling: prefer bins deviating below the mean (consolidate slack)
    let dev = (mean_residual - post) / cap;
    score += 10.0 * dev * dev.abs();

    // Mild penalty for proliferation of open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral-ish score, penalized mildly so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 8.0 * (1.0 - late);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(2) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // New-bin candidate: generally penalized so we prefer filling open bins...
        score += 35.0 + 0.6 * open_bins_count as f64;
        // ...unless NO open bin can fit the item (forced open)
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // Open a fresh bin for large items when existing residuals are small/fragmented
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 25.0 + 10.0 * progress;
        }
    } else {
        // Last-chance bin: strongly favor using it to avoid waste
        if fitting_bins_count == 1 {
            score -= 55.0;
        }
        // Perfect closure
        if post_residual == 0 {
            score -= 45.0;
        }
        // Harmonic class of dead space: tiny slivers (<10) are nearly useless
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
        // Modulo-10 class: residuals that are multiples of 10 are reusable
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 4.0;
        }
        // Lookahead coupling: reward if next item fits into the leftover space
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 8.0;
            } else {
                // penalty grows with how much the next item overshoots the residual
                score += ((next_item_size - post_residual).min(25)) as f64 * 0.6;
            }
        }
        // Mild dispersion term: prefer bins whose residual is near the mean
        score += 0.08 * (mean_residual - post_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are pure waste.
    if post_residual < 10 {
        score -= 40.0; // perfect/usable-closure reward
    } else if post_residual < 20 {
        score += 25.0; // very likely dead space
    } else if post_residual < 35 {
        score += 10.0; // risky gap
    }

    // Prefer bins whose gap is a good match for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64) * 0.3;
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor tighter packing.
    score += (open_bins_count as f64) * 0.4;

    // Slight preference for bins tighter than average (fill the fullest first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits too: mildly good, prefer small leftover after both
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here afterwards: penalize dead space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if the item is large and next item is large too, a fresh bin is fine
        if item_size + next_item_size > bin_capacity {
            score -= 200.0;
        }
    }

    // Early in stream, slightly prefer consolidating (fewer open bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (<= 1..100 range, use 1 as floor)
    if post_residual > 0 && post_residual < 1 {
        score += 50.0;
    }
    // Penalize residuals too small for the lookahead item if the next item would fit here instead
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leaving room for the next item is valuable
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys the chance to host the next item
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // with alternatives, prefer bins that would be nearly emptied
        score += 2.0 * (1.0 - tightness);
    }

    // New-bin candidate handling: empty bin gets a mild handicap so it's only chosen
    // when open bins are poor fits, but late in the stream opening new bins is cheap
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 14.0 - 10.0 * progress;
    }

    // Prefer bins below mean residual (less-packed bins absorb big items better)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Slight preference for placing into bins when many bins are open (consolidation)
    score -= 0.02 * open_bins_count as f64 * tightness;

    // Penalize very large leftover fragments late in stream
    if post_residual > bin_capacity / 2 {
        score += 3.0 * (post_residual as f64 / bin_capacity as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual, slightly compressed non-linearly
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, prefer tight fills (low post_residual) strongly; later,
    // tolerate residual but reward near-perfect packing via a quartic dip.
    let tightness = 1.0 - norm_pr; // 1 = perfect fit
    let progress_coupling = (1.0 - progress) * 30.0 * norm_pr * norm_pr
        + progress * 25.0 * (1.0 - tightness * tightness * tightness * tightness);
    score += progress_coupling;

    // Penalize dead space relative to mean residual (smooth quadratic divergence)
    let dead = pr - mean_residual;
    score += 0.15 * dead * dead / cap;

    // Lookahead: reward if next item fits smoothly into post_residual (cubic affinity)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_frac = nx / pr.max(1.0);
            score -= 12.0 * fit_frac * (1.0 - fit_frac) * (1.0 + fit_frac);
        } else {
            // penalize leaving residual that next item cannot use, scaled by gap
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - norm_item);
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it mid-range so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 0.5 * cap + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose residual matches common
    // small-item sizes are valuable; penalize "dead" residuals.
    let pr = post_residual;
    if pr > 0 {
        // Residuals divisible by common item sizes (1..=10) are reusable.
        let mut reusability = 0.0f64;
        for k in 1..=10u32 {
            if pr % k == 0 {
                reusability += 1.0 / k as f64;
            }
        }
        score -= 3.0 * reusability;

        // Integer-division thresholds: residual in a "small dead zone" is bad.
        if pr < 10 {
            score += 40.0; // unusable dead space
        } else if pr < 25 {
            score += 8.0;
        } else if pr < 50 {
            score -= 2.0;
        }
        // Modulo-class bonus: residual exactly matching next item is perfect.
        if next_item_size > 0 && pr == next_item_size {
            score -= 25.0;
        }
        // Fractional capacity coupling: residual as fraction of capacity.
        let frac = pr as f64 / cap;
        score -= 10.0 * (frac * std::f64::consts::PI).sin().abs();
    } else {
        score -= 30.0; // perfect fill
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets neutral-but-not-low score,
    // unless current fit is poor.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 15.0; // pairing won't work anyway; fresh bin fine
        }
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer bins below mean residual (tighter bins absorb items well).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gap threshold grows with item size).
    let dead_threshold = (item_size as f64 * 0.5).max(10.0);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // creating a gap that cannot fit the next item: penalize
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate opening new bins less readily.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins
    // are all poor fits; scale with mean residual of open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight progression term: late in the stream, be more conservative
    // about dead space since fewer items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: reward when next item exactly fills post_residual,
    // penalize when next item cannot use the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nxt;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if diff > 0.0 {
            // next item fits: mild reward proportional to how well it matches
            score -= 25.0 * (1.0 - (diff / bin_capacity as f64));
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 15.0 + (-diff / bin_capacity as f64) * 30.0;
        }
    }

    // Compare against mean residual: prefer bins whose residual is below
    // average (closing them out) when post_residual is small.
    if post_residual as f64 <= mean_residual {
        score -= 10.0;
    } else {
        score += 5.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is expensive early on; penalize when open bins exist
        // that fit, but allow it when the item is large relative to capacity.
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        if open_bins_count > 0 && !large_item {
            score += 25.0 + 0.5 * (open_bins_count as f64);
        } else if large_item {
            score -= 10.0;
        }
    } else if post_residual < 10 {
        // Nearly-full bin: reward closing it out.
        score -= 20.0;
    }

    // Mild stream-progression pressure: later in the stream, be slightly more
    // conservative about spreading items across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit even the smallest future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // Creates a sliver the next item cannot use — penalize.
            score += 12.0;
        }
        // Bonus if post_residual fits next item snugly.
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer it only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded && open_bins_count > 0 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        // Early stream: filling fresh bins is fine; late stream: prefer consolidation.
        if progress > 0.7 {
            score += 20.0;
        }
    }

    // Favor bins below mean residual (rebalancing toward fuller bins).
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Slight preference for more-filled bins overall.
    score -= 0.05 * (item_size as f64 / bin_capacity as f64) * bin_residual as f64;

    // Mild penalty for accumulating many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth non-linear waste potential: dead space grows quadratically when
    // post_residual becomes small and hard to reuse (below typical item size).
    let reuse_floor = 10.0_f64.min(cap * 0.1);
    let dead = ((reuse_floor - post).max(0.0) / reuse_floor).powi(2) * 40.0;

    // Base: prefer leaving moderately large, reusable residuals.
    let mut score = post * (0.9 + 0.4 * progress);

    // Quadratic coupling of post_residual with stream progress: early on,
    // keep bins flexible; late, prefer tight packing (small post_residual).
    let tight = (norm_post * (1.0 - progress)).powi(2) * cap * 0.6;
    score += tight;

    // Reward if the lookahead item fits the post residual (smooth kernel).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 18.0 * (-gap / 12.0).powi(2) * (1.0 - gap / (cap + 1.0)).max(0.0);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 25.0 * progress;
    }

    // Penalize opening a new bin when good open bins exist (new-bin candidate
    // gets high residual; make it less attractive unless open bins are full).
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score = cap * (1.2 + 0.6 * progress) + 15.0 * scarcity;
    }

    // Mild penalty relative to mean residual: avoid bins that deviate badly.
    score += ((post - mean_residual) / cap).abs() * 6.0;

    // Dead-space penalty.
    score += dead;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to small item sizes
    // Residuals divisible by common size classes (e.g. 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        // divisibility bonuses: residual that future items likely tile exactly
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 || pr % 50 == 0 { score -= 5.0; }
        // small dead-space penalty: residual below the minimum item size is dead
        if pr < 10 { score += 40.0; }
        // harmonic class: residual mod 10 — prefer low, tileable classes
        score += ((pr % 10) as f64) * 1.5;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward, more so if it leaves a tileable remainder
            let rem = pr - next_item_size;
            score -= 15.0;
            if rem % 10 == 0 { score -= 5.0; }
        } else if next_item_size <= bin_residual {
            // next item would have fit before this placement but not after: penalize
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; scaled by stream progression
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 20.0 * (1.0 - progress);
        // if many bins fit the item, opening new is clearly bad
        score += (fitting_bins_count as f64) * 12.0;
    } else {
        // prefer tighter bins (small residual before placement) — best-fit flavor
        score += (bin_residual as f64) * 0.15;
        // reward filling bins when many open bins exist (bin consolidation)
        score -= (open_bins_count as f64) * 0.5;
        // if this bin is far below mean residual, it is relatively full: favor it
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    // Post-residual below the smallest possible item is pure dead space.
    if post_residual < 1 {
        score += 40.0;
    }

    // Reward tight fits (waste ratio penalty).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: prefer bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.8;

    // Mild preference toward bins with residuals below mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins on bad fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Late-stream consolidation: tighter packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin closed by next item
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how well it uses leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item won't fit here; penalize dead space that likely becomes waste
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // the item is large and no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = fitting_bins_count == 0 || (post_residual as f64) < mean_residual * 0.2;
        if (large_item && poor_fit) || (progress > 0.8 && fitting_bins_count <= 1) {
            score -= 45.0;
        } else {
            score += 50.0; // discourage spreading into fresh bins early
        }
    }

    // Slight bonus for exact fills now
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted space, but discount small residuals less as time passes
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let waste_weight = 1.0 - 0.35 * progress;
    score = waste_weight * post_residual as f64;

    // Tight fits are excellent
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 18.0;
            } else {
                score -= (10.0 / (1.0 + slack as f64)) * 4.0;
            }
        } else {
            // next item cannot fit here; mildly penalize blocking residual
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: be picky, penalize mediocre fits
        score += (fitting_bins_count as f64 - 3.0).min(5.0) * 2.0;
    }

    // Global residual pressure: if mean residual is large, prefer filling bins
    // with big items relative to their bin; if mean residual is small, tighten.
    let mean_r = mean_residual;
    if mean_r > 40.0 {
        // lots of slack across bins: reward larger consumption now
        score -= item_size as f64 * 0.3;
    } else {
        // bins are tight: penalize leaving awkward mid-size gaps
        if post_residual > 0 && post_residual < 20 {
            score += (20 - post_residual) as f64 * 0.4;
        }
    }

    // Time horizon: late in the stream, avoid opening new bins at all costs
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // New-bin candidate: only attractive when nothing decent is open or item is huge
    if bin_residual == bin_capacity {
        let open_benefit = if open_bins_count == 0 {
            -100.0
        } else if item_size > 60 {
            -5.0
        } else {
            15.0 + 0.5 * open_bins_count as f64
        };
        score += open_benefit;
        // late stream: new bins are expensive
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * t) - norm_pr * (1.0 - t) * (1.0 - t);
    score += 20.0 * coupling;

    // Lookahead: penalize post_residual that cannot fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0) / cap;
        score += 15.0 * gap * gap;
        // Reward if next item fits exactly-ish
        let fit_gap = (pr - ns).max(0.0) / cap;
        score -= 8.0 * (1.0 - fit_gap.min(1.0));
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Penalize bins far from mean residual (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Slight pressure toward tighter fills as stream progresses
    score -= (1.0 - norm_pr) * (5.0 + 10.0 * t);

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is leftover space?
    // Residuals in high bands (>= next typical item) remain usable.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize dead space quadratically, scaled by capacity fraction.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * dead * dead * bin_capacity as f64;

    // Harmonic classes via integer division thresholds on post_residual:
    // class 0: post_residual >= 50 (half-full usable), class 1: 25..50, class 2: <25
    let class = if post_residual >= bin_capacity / 2 { 0 } else if post_residual >= bin_capacity / 4 { 1 } else { 2 };
    score += 8.0 * class as f64;

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10/20/25) are more likely to be exactly filled later.
    let harmonic_bonus = if post_residual % 10 == 0 { 4.0 } else if post_residual % 5 == 0 { 2.0 } else { 0.0 };
    score -= harmonic_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many bins fit => discourage new bin; few fit => allow).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() + 1.0 };
        score += 6.0 * pressure + 4.0 * (open_bins_count as f64).sqrt();
        // Early in stream, opening bins is cheap; later, consolidate.
        score -= 5.0 * (1.0 - progress);
        // If item is large, a fresh bin avoids fragmenting.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Slight preference for tighter existing bins relative to mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit any plausible
    // future item (min size 1, but practically < 10) are pure waste.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Semi-dead zone: only very small items can use it.
        score += 15.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: post_residual close to zero is good (perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Fractional fit quality: prefer bins where item fills most of residual.
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins when fragmentation risk is low.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has no dead space yet, but
    // opening new bins should be penalized unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * (open_bins_count as f64).min(20.0);
        // If next item is large, a fresh bin may be attractive for pairing.
        if next_item_size >= 50 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; using it consolidates waste.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to 0 is ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for the minimum item size (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: strongly reward exact match of post_residual with next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 180.0;
        } else if diff <= 5.0 {
            score -= 90.0;
        } else if diff <= 15.0 {
            score -= 30.0;
        } else {
            score += diff * 0.5;
        }
        // Penalize leaving residual that can't fit the next item at all.
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 25.0;
        }
    } else {
        // Last item: minimize residual aggressively.
        score += post_residual as f64 * 0.3;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.4;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate: make it moderately attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        // Empty bin has huge residual; base score already high. Nudge down slightly
        // when many bins are open (consolidation pressure) but not too much.
        score -= 20.0;
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
    }

    // Stream progression: early on, be more willing to spread into new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;

    // Mild penalty for very loose fits (large residual left over).
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space: residuals that are too small
    // to be useful for typical future items (1..100 unknown distribution).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver is nearly dead space
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // moderately awkward
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is truly terrible).
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item could fill this bin's post
    // residual exactly-ish, reward; if next item would be wasted here,
    // slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect follow-up fill
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).recip().min(1.0);
        } else {
            // next item won't fit here; dead space risk grows with gap
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 0.0 {
        let consolidation = (mean_residual / bin_capacity as f64).tanh();
        score -= 8.0 * consolidation * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Only attractive when item is large (would leave little usable space anyway)
    // or when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are opened only when justified
        score += 15.0;
        // large items pack cleanly into fresh bins
        score -= 0.25 * item_size as f64;
        // late in the stream, prefer closing out with fresh bins less
        score += 10.0 * progress;
    } else if open_bins_count > 0 {
        // mild preference for existing bins
        score -= 2.0;
    }

    // Slight reward for bins whose residual is close to item (best-fit flavor)
    score -= 20.0 / (1.0 + (bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: minimize waste, non-linearly scaled
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Tight fits rewarded strongly (quadratic coupling of fill ratio)
    let fill = norm_item;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Late in the stream, prefer compacting into existing bins
    score += 6.0 * norm_post * progress * progress;

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Many open bins: penalize spreading further unless fit is excellent
    score += 0.4 * (open_bins_count as f64).ln() * (1.0 - fill);

    // Mean residual coupling: avoid bins deviating far from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Lookahead: if next item fits perfectly in post residual, big reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let next_fit = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 6.0 * next_fit * next_fit;
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty for leaving large dead space
        score += 2.0 * norm_post * (next_item_size as f64 / cap);
    }

    // New-bin candidate: keep it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: modulo arithmetic on capacity fractions.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let quarter = cap / 4;
    let eighth = cap / 8;

    // Dead-space penalty: residuals too small to be useful are heavily penalized.
    if pr < eighth {
        score += (eighth - pr) as f64 * 6.0;
    }
    // Reward residuals in "harmonic sweet spots": near quarter/half/eighth multiples.
    let mut harmony = 0.0;
    for (mult, w) in [(quarter, 3.0), (cap / 2, 2.5), (eighth, 1.5), (3 * quarter, 2.0)] {
        let d = (pr - mult).abs();
        if d <= eighth {
            harmony += w * (1.0 - d as f64 / eighth as f64);
        }
    }
    score -= harmony;

    // Modulo-10 class: residuals divisible by 5 or 10 pair better with integer items.
    if pr % 10 == 0 {
        score -= 4.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += ((next_item_size as f64 - post_residual as f64) * 0.3).min(8.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it neutral-ish, but discourage opening
    // new bins when open bins have large residuals and few bins are open.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.5;
        if mean_residual > 40.0 {
            score += (mean_residual - 40.0) * 0.4;
        }
    }

    // Tight fit bonus: reward near-perfect packing.
    if pr == 0 {
        score -= 20.0;
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (build diverse residual pool); later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 4.0;
    } else {
        score += progress * 2.0;
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balance).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 12.0;
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 150.0;
    }
    // Reward tight fits relative to bin capacity.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can use the post residual exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Slight late-stream conservatism: keep residuals usable as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        // Strong bonus for exact match: item + next item fills bin perfectly
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after current placement; penalize leftover beyond next item
            let leftover = (post_residual - next_item_size) as f64;
            score += leftover * 0.3;
        } else {
            // next item won't fit here after placement; dead space penalty
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    } else {
        // Last item: prefer minimal residual
        score += (post_residual as f64) * 0.5;
    }

    // Penalize deviation of post_residual from mean residual (avoid fragmenting)
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect chain
    if bin_residual == bin_capacity {
        let base = 20.0;
        let chain_bonus = if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            (bin_capacity - item_size - next_item_size) as f64
        } else {
            0.0
        };
        score = base + chain_bonus * 1.5 - post_residual as f64;
    }

    // Slight preference for tighter bins early, spreading later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * (0.2 * (1.0 - progress));

    // Small tie-break: prefer bins with fewer competitors
    score += fitting_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Penalize dead space relative to smallest possible future item (1..100 unknown; use 10 as floor-ish).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 120.0;

    // Lookahead: if next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting large residual.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are bad
    // or open-bin pressure is low.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 90.0;
        // Cheaper to open bins early in the stream.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * (1.0 - t);
        // If many bins are open with slack, discourage new bin.
        score += (open_bins_count as f64).sqrt() * 8.0;
        score += (mean_residual / bin_capacity as f64).max(0.0) * 70.0;
        // If next item is large and current fit is tight, new bin can be good.
        if next_item_size > 0 && next_item_size > post_residual + item_size {
            score -= 50.0;
        }
    }

    // Prefer tighter bins generally (smaller residual before placement).
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Mild bonus for consolidating when many bins are open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), scaled non-linearly.
    let mut score = norm_post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, tight fits matter more; early on, keep bins flexible.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (0.5 + 1.5 * progress);

    // Penalize dead space relative to mean residual (wasted capacity coupling).
    let mean_n = mean_residual / cap;
    score += 0.4 * (norm_post - mean_n).abs() * (1.0 - progress);

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 0.6 * (1.0 - slack_fit) * (1.0 - progress);
        } else {
            score += 0.5 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.0 * progress;
    }

    // Mild penalty for spreading across many open bins; stronger late.
    score += 0.05 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: prefer it only when no open bin gives a decent fit.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score = cap - 0.5 * post; // baseline: 0 residual empty bin scores high unless others worse
        score += 1.5 * (1.0 - progress); // early on, opening bins is cheap
        if fitting_bins_count <= 1 {
            score -= 3.0; // no real alternative: definitely open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes capture which leftover
    // sizes are "dead" (cannot be filled by typical item sizes).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that are too small for most items
    // (items >= 10 in classic streams, but be conservative for 1..100 range).
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 120.0;
    }

    // Harmonic class bonus: residuals divisible by common item classes
    // (10, 20, 25, 50) are more reusable.
    if post_residual % 10 == 0 { score -= 15.0; }
    if post_residual % 20 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 50 == 0 { score -= 10.0; }

    // Fractional capacity coupling: prefer bins whose post residual is a
    // "nice" fraction of capacity.
    let frac = post / cap;
    if frac > 0.4 {
        score -= 10.0 * frac;
    } else if frac < 0.1 && post_residual > 0 {
        score += 25.0 * (0.1 - frac) * 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // penalize if next placement leaves awkward dead space
            if next_post < 12 && next_post > 0 {
                score += 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 70.0 - 20.0 * progress;

        // Large items are better placed fresh.
        if item_size > bin_capacity / 2 {
            score -= 55.0;
        }
        // If few bins fit the item, opening fresh is reasonable.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // If open bins are crowded (low mean residual), fresh bin is better.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 30.0;
        }
    } else {
        // Reward tight fits in existing bins.
        score -= 20.0 * (1.0 - (post_residual as f64 / bin_residual as f64).max(0.0));
    }

    // Mild pressure against bin explosion.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty proportional to how "wasted" it is.
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        } else {
            // Larger gaps decay in usefulness nonlinearly (perfect fits rewarded).
            score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Prefer bins whose residual is close to item_size (tight fit measure).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Open-bin pressure: with many bins open, discourage spreading; with few
    // bins, mildly discourage opening new ones unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current fit is poor and few bins open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly prefer bins that get filled exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Penalize dead space the next item cannot use (wasted residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Reward residual that leaves room for typical future items.
    if post_residual >= 10 {
        score -= 5.0;
    } else {
        score += 10.0; // tiny unusable slivers
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for wasting a fresh bin; reduced when lookahead is large
        // (next item won't fit anywhere anyway) or late in stream.
        let mut new_bin_penalty = 150.0;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            new_bin_penalty -= 100.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty -= 30.0 * progress;
        score += new_bin_penalty;
    }

    // Mild preference for fuller bins (smaller residual) scaled by stream length.
    score += post_residual as f64 * 0.3;

    // Encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 0.1 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.6;

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 2.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64 - mean_residual).abs() > 15.0;
        // Prefer new bin early or when open bins have scattered residuals.
        score -= 3.0 * (1.0 - progress);
        if poor_fit {
            score -= 5.0;
        }
        // Discard excessive bin proliferation late in the stream.
        score += 0.05 * open_bins_count as f64 * progress;
    } else {
        // Prefer bins whose residual is close to the mean (balanced usage).
        score += (bin_residual as f64 - mean_residual).abs() * 0.08;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_residual as f64 / bin_capacity as f64) * 1.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = (item_size as f64) / cap;
    let post_norm = pr / cap;
    let mean_norm = mean_residual / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = post_norm * (1.0 + 0.6 * post_norm * post_norm);

    // Stream-progress coupling: later in the stream, dead space is more costly.
    let progress_coupling = progress * (post_norm * post_norm) * 12.0;
    score += progress_coupling;

    // Reward bins whose residual is "wasted" anyway (large mean residual context):
    // placing here reduces fragmentation relative to the fleet average.
    score -= 1.5 * (mean_norm - post_norm).max(0.0);

    // Lookahead: penalize if the next item cannot use the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt as u32 {
            // next item won't fit here: dead space penalty, stronger late in stream
            score += 3.0 + 4.0 * progress * (1.0 - post_norm);
        } else {
            // next item fits: reward tight chain placement
            let chain_tightness = 1.0 - ((pr - nxt as f64) / cap);
            score -= 2.0 * chain_tightness * (1.0 - progress * 0.5);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else {
        // Mild penalty when many bins compete, to encourage consolidation.
        score += 0.15 * (fitting_bins_count as f64).sqrt();
    }

    // New-bin candidate: empty bin gets a neutral-but-competitive score that
    // decreases as the stream progresses (favor consolidation early),
    // and increases with open bin count pressure to avoid bin explosion.
    if bin_residual == bin_capacity {
        score = cap / 100.0 * (8.0 - 3.0 * progress) + 0.4 * (open_bins_count as f64);
        // If next item is large and this item is small, opening fresh is attractive.
        if next_item_size as f64 > fit_norm * cap + 10.0 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity-fraction buckets (C/4 granularity)
    let quarter = bin_capacity / 4;
    let item_class = item_size / quarter.max(1);
    let next_class = next_item_size / quarter.max(1);

    // Integer-division threshold on post_residual: classify dead space
    let post_class = post_residual / quarter.max(1);

    // Penalize post-residuals that are too small to ever be useful
    // (below the minimum conceivable next item of size 1, but especially
    //  below the harmonic class floor of the next item)
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward when post_residual exactly matches the next item's class band
    // (post_residual / quarter == next_class means a likely perfect follow-up fit)
    if next_item_size > 0 && post_class == next_class && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Modulo arithmetic on post_residual: residuals near multiples of small
    // harmonics (e.g. 10, 20, 25, 50) are more reusable
    let r = post_residual;
    if r % 10 == 0 { score -= 3.0; }
    else if r % 5 == 0 { score -= 1.5; }
    if r % 25 == 0 && r > 0 { score -= 2.0; }
    if r % 50 == 0 && r > 0 { score -= 2.0; }

    // Penalize awkward mid-band residuals (dead space unlikely to fit anything)
    if r > 0 && r < quarter / 2 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling nearly-full bins (low residual = tight packing)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 12.0 };
        score += pressure;
        // Opening a new bin is better if the item leaves a large, clean residual
        // elsewhere but here we start fresh; slight penalty to avoid bin explosion
        score += open_bins_count as f64 * 0.5;
        // If next item is large and current residual plan is bad, favor new bin
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 4.0;
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - bin_residual as f64) * 0.2;

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // a "tight" bin — prefer using it up
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the next item (lookahead fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fills the bin exactly afterwards.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else if post_residual > 0 {
            // Next item won't fit: this residual becomes dead space.
            score += 10.0;
        }
    }

    // Tight-fit reward relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // unless the fit is genuinely good.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
        // But if no open bin fits well (many fitting bins means fragmentation), allow new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: penalize bins whose residual is far below average
    // (they fragment the pool of usable space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early in the stream, be more tolerant of opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if the next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chains that leave small slack after next item too
            score -= 200.0 - 0.5 * slack;
            if post_residual == next_item_size {
                score -= 500.0; // perfect 2-item chain
            }
        } else {
            // Penalize residuals that cannot host the next item, scaled by dead space
            let dead = post_residual as f64;
            score += 0.3 * dead;
            if dead < 10.0 {
                score += 150.0; // tiny unusable gap is bad
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let residual = bin_residual as f64;
    score += 0.2 * (residual - mean_residual);

    // Last-chance bin bonus: if this is the only bin that fits, use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Late in stream: prefer closing bins tightly, avoid opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or early on
        score += 50.0 + 20.0 * open_bins_count as f64 + 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward fuller utilization: bins that end up tighter get a bonus.
    let fill = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= fill * 6.0;

    // Lookahead: strongly favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 + slack * 0.05;
        } else {
            // Dead-end for lookahead: penalize proportionally to wasted residual.
            score += post_residual as f64 * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // (avoid opening a new bin), but only if the fit isn't terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Brand-new empty bin candidate: penalize mildly so we only open new bins
    // when no open bin gives a decent fit. Penalize less for large items
    // (big items are better placed fresh than squeezed in).
    if bin_residual == bin_capacity {
        score += 12.0 - item_size as f64 * 0.08;
    }

    // Penalize tiny unusable fragments (dead space < 10 can rarely host anything).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Late in the stream, consolidate: prefer bins close to the mean residual
    // to keep the bin set balanced and closeable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.03 * progress;

    // Slight preference for already-open bins when many are open (reduce sprawl).
    if bin_residual != bin_capacity && open_bins_count > 3 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: penalize leftover space, with non-linear polynomial coupling to stream progress.
    // Later in the stream, small residuals matter less (bins are near-closed), so the
    // effective penalty on post_residual is damped by a smooth quadratic decay.
    let progress_damp = 1.0 - 0.5 * progress * progress;
    let mut score = pr * (0.9 + 0.6 * progress_damp);

    // Non-linear dead-space shaping: residuals that are too small to ever fit a
    // meaningful item are pure waste; add a convex penalty peaking near tiny residuals.
    let tiny = (1.0 - pr / cap).max(0.0);
    score += 12.0 * tiny * tiny * tiny;

    // Reward tight fits: small post_residual relative to item size.
    if it > 0.0 {
        score -= 8.0 * (1.0 - pr / cap) * (it / cap);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily;
    // if the next item would be blocked, penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = pr - nxt;
            score -= 6.0 * (1.0 - slack_after_next / cap);
        } else {
            let block = (nxt - pr) / cap;
            score += 9.0 * block * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when all
    // open bins would leave huge dead space. Penalize new bins mildly, scaled by
    // how many bins already fit and how scattered residuals are.
    if bin_residual == bin_capacity {
        let scatter = (mean_residual - pr).abs() / cap;
        score += 4.0 + 6.0 * (1.0 - scatter.min(1.0));
        if fitting_bins_count >= 1 {
            score += 8.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
    }

    // Mild preference to fill bins with larger residual when many bins are open.
    score -= 2.0 * (bin_residual as f64 / cap) / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "dead space"
    // (small, unusable) should be heavily penalized.
    let dead_zone = post_residual < 10 && post_residual > 0;
    if dead_zone {
        score += 60.0; // residual too small for any item (min size 1..100 guard)
    }

    // Perfect fit reward: post_residual exactly 0 or an exact multiple of
    // common item sizes (harmonic classes via modulo).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Residue classes of post_residual mod small capacities: residuals
        // divisible by 5/10 pair well with typical item sizes.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }
        // Very small residuals that could still fit tiny items (1..10)
        if post_residual < 10 {
            score -= 3.0 * post_residual as f64;
        }
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: excellent chaining, reward proportionally
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
            // harmonic bonus if next item exactly fills remainder
            if next_item_size == post_residual {
                score -= 40.0;
            }
        } else {
            // next item won't fit here: penalize mildly, worse if residual is mid-sized
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post residual is dead space).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if dead_zone {
            score += 55.0; // don't waste the last fitting bin on dead space
        }
    }

    // New-bin candidate handling: empty bin gets a mild opening penalty so
    // decent fits into existing bins win, but big items prefer fresh bins.
    if bin_residual == bin_capacity {
        let openness = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 15.0 * openness;
        // if next item is large too, a fresh bin is attractive
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Progression-aware tightness: late in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (pack tight bins first, keep
    // loose bins flexible).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Many open bins: discourage spreading; favor bins that become tight.
    if open_bins_count > 3 {
        score -= 0.1 * (bin_capacity - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Pressure against accumulating many open bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is large and would not fit anywhere after this placement, mildly penalize.
    if next_item_size > post_residual && next_item_size > bin_capacity - item_size.min(bin_residual) {
        score += 5.0;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when the item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progression.
        score = bin_capacity as f64 * 0.6 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if item_size >= 50 {
            score -= 30.0; // large items are fine in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Post-residual can still fit the next item: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item: penalize unusable remainder.
        let dead = post_residual as f64;
        score += 8.0 * (dead / bin_capacity as f64);
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when several open bins could fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item fits perfectly with the next item in a fresh bin, ease the penalty.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Late in the stream, tighten up: avoid leaving small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);

    // Base: prefer small post-residual (tight fit), with non-linear sharpening.
    let tightness = (post / cap).powf(1.6);
    let mut score = 40.0 + 60.0 * tightness;

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 35.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: if the next item fits the post-residual well, reward.
    if next_item_size > 0 && next_item_size as f64 <= post {
        let gap = post - next_item_size as f64;
        score -= 14.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to leftover.
        score += 6.0 * (post / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing.
    let pressure = (open_bins_count as f64).ln() * (mean_residual / cap);
    score -= 10.0 * pressure.clamp(0.0, 3.0);

    // Time horizon: late in the stream, consolidate harder (avoid opening bins).
    let late = progress * progress;
    score += 18.0 * late * (post / cap); // penalize loose fits late
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline anchored near mid, adjusted by context.
        let mut nb = 55.0;
        nb += 30.0 * late;                 // reluctant to open bins late
        if fitting_bins_count > 0 {
            nb += 15.0;                    // open bins exist that fit
        }
        if item_size <= 20 {
            nb += 10.0;                    // small items shouldn't open bins
        }
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(next_item_size) >= item_size {
            nb -= 8.0;                     // new bin can host item + next item
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - 2.0 * progress);
    score -= 6.0 * poly;

    // Penalize dead space more strongly as the stream progresses
    score += 0.5 * x * x * progress;

    // Reward tight fits
    score -= 4.0 * (1.0 - x).powi(3);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap / cap;
        if pr >= next_item_size as f64 {
            score -= 2.0;
        }
    }

    // Mild preference for consolidating into fewer bins
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Bias toward bins with residuals near the mean (balance-aware)
    score += 0.05 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity
    let pr = post_residual;
    let mod_class = pr % 10;
    // Reward residuals in "usable" harmonic classes (small multiples that pair with typical items)
    match mod_class {
        0 => score -= 6.0,                 // perfectly divisible residual
        1 | 2 | 3 => score -= 2.0,         // near-full bin, tiny dead space
        8 | 9 => score += 3.0,             // awkward residue just under a decade
        _ => {}
    }

    // Integer division thresholds: residual bucket by quarter-capacity
    let quarter = bin_capacity / 4;
    if pr < quarter / 2 {
        score += 4.0; // nearly dead space
    } else if pr <= quarter {
        score -= 3.0; // tight fit zone, good
    } else if pr <= 2 * quarter {
        score -= 1.0;
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= pr {
            // reward if next item divides post_residual evenly (perfect future packing)
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            } else {
                score -= 1.5;
            }
            // reward if next fills residual almost exactly
            let gap = pr as f64 - nxt;
            if gap <= 5.0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize leaving large unusable residual
            score += 2.0 + (pr as f64) * 0.02;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / cap;
        if fit_quality > 0.5 {
            score += 5.0; // poor fit into open bin -> prefer new bin
        } else {
            score += 12.0; // decent fit exists -> discourage new bin
        }
        // fewer open bins relative to stream progress -> cheaper to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 2.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced packing)
    score -= 0.5 * (mean_residual - post_residual as f64).abs() / cap;

    // Mild tightness reward scaled by fill fraction
    score -= (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * fit_ratio;
    }

    // Dead-space penalty: post_residual gaps that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // If the leftover can exactly fit the lookahead item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If leftover cannot fit the next item and is small, penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheap so favor consolidation instead.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Give it a moderate baseline so tight fits in existing
    // bins beat it, but large dead space in existing bins loses to it.
    if bin_residual == bin_capacity {
        score = 35.0 + item_size as f64 * 0.1;
        if fitting_bins_count == 1 {
            // An existing last-chance bin should beat a new bin.
            score += 25.0;
        }
    }

    // Slight preference for bins below mean residual (consolidating slack).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 500.0; // next item fills this bin exactly
            } else if slack <= 10 {
                score -= 100.0;
            } else {
                score -= 50.0 / (1.0 + slack as f64 / 20.0);
            }
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: avoid leaving unusually large
    // dead space relative to the fleet average (waste), but also avoid bins that
    // become outliers with tiny residuals (fragmentation).
    if post_residual as f64 > mean_residual + 15.0 {
        score += (post_residual as f64 - mean_residual - 15.0) * 0.8;
    } else if (post_residual as f64) < mean_residual - 20.0 {
        score += (mean_residual - 20.0 - post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin fits poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If lookahead shows next item is small, a new bin is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual.max(next_item_size) {
            score -= 10.0;
        }
    }

    // Mild preference to fill bins more aggressively early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight bias toward consolidating into fewer bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead: penalize residuals too small for the next item (dead space),
    // reward residuals that still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // bonus if next item fits almost exactly
            let gap = post_residual as f64 - next_item_size as f64;
            if gap <= 5.0 {
                score -= 10.0;
            }
        } else {
            // dead space: worse the larger the residual relative to next item
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: prefer the tightest; slight tie-break via mean residual.
    if fitting_bins_count > 1 {
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    // New empty bin candidate: make it costly unless it's the only option
    // or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let base = 40.0;
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        // late in stream, fewer open bins is fine; early, discourage proliferation mildly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let time_term = progress * 10.0;
        score += base - big_item_bonus + scarcity_bonus + time_term;
    }

    // Penalize creating residuals in the awkward 20-40 range (hard to fill later).
    if post_residual >= 20 && post_residual <= 40 {
        score += 5.0;
    }

    // Mild preference to consolidate into bins with less residual overall.
    score += (post_residual as f64 - mean_residual).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: reward small post-residual, but with a smooth non-linear twist.
    // Squared post-residual punishes large dead space more aggressively.
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, tight packing matters more (bins are nearly closed out).
    let tightness = 1.0 - (pr / cap);
    score -= (0.5 + 2.0 * progress) * tightness * tightness * it;

    // Reward near-perfect fits with a smooth bump centered at pr == 0.
    let perfect = (-pr / (0.25 * cap)).exp();
    score -= 8.0 * perfect * (0.5 + progress);

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // reward; if post-residual is awkwardly small-but-nonzero for next item,
    // penalize smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        // smooth soft-threshold via logistic on gap
        let logistic = 1.0 / (1.0 + (gap / (0.2 * cap)).exp());
        score -= 3.0 * fits_next * logistic * (nx / cap);
        score += 1.5 * (1.0 - fits_next) * (1.0 - gap / cap).max(0.0) * 0.0;
        // penalize leaving residual that no future item likely uses
        score += 2.0 * (pr / cap) * (1.0 - logistic) * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is penalized, more so
    // early in the stream when consolidation is cheap, and when many bins
    // are already open (fragmentation pressure).
    if bin_residual == bin_capacity {
        let frag = (open_bins_count as f64 / (1.0 + open_bins_count as f64));
        score += 6.0 + 4.0 * (1.0 - progress) - 3.0 * frag * (it / cap);
    }

    // Slight preference for bins with below-average residual (consolidate
    // small leftovers), smooth via tanh.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 2.0 * dev.tanh();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that sit on "useful" fractions
    // of capacity (small, and divisible into common item classes like 10/20/25/50).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr % 25 == 0 {
        score -= 25.0; // quarter-capacity harmonic
    } else if pr % 10 == 0 {
        score -= 18.0; // decile harmonic
    } else if pr % 5 == 0 {
        score -= 10.0;
    }

    // Penalize dead space in the awkward 6..19 band (too small for most items).
    if pr >= 6 && pr <= 19 {
        score += 22.0;
    }

    // Integer-division threshold: residual in [1..9] is nearly dead too.
    if pr >= 1 && pr <= 9 {
        score += 10.0;
    }

    // Coupling with lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: baseline penalty so it's only chosen when all open bins
    // would leave large dead space.
    if bin_residual == bin_capacity {
        score += 35.0;
        // opening new bins late in the stream is wasteful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer packing into bins whose residual is already below mean (tight bins).
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Mild pressure against accumulating many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: residuals in 1..=10 are nearly unusable
    // (item sizes 10..80 in the canonical setting; keep a small tolerance for 1..100 streams).
    if post_residual >= 1 && post_residual < 10 {
        score += 90.0; // hard penalty: creating unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // risky small gap
    } else if post_residual < 35 {
        score += 8.0;  // moderate dead space
    }

    // Reward bins whose residual closely matches the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Lookahead coupling: if the next item fits the post-residual well, favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 30.0; // next item will nearly perfectly fill this bin
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // leftover too small for the next item
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Mean residual coupling: if this bin's residual is below mean, it's relatively full -> favor
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New empty bin candidate: only attractive if no decent fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let worst_gap = mean_residual; // typical slack available
            if worst_gap > item_size as f64 * 1.5 {
                score -= 5.0; // existing bins are roomy, new bin less needed
            }
            score += 15.0; // default penalty: prefer filling open bins
            if post_residual < 20 {
                score += 40.0; // opening a bin that immediately becomes a sliver is terrible
            }
        } else {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    if next_item_size > 0 {
        // Perfect 2-step match: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward proportionally to leftover after the pair
            let pair_left = post_residual - next_item_size;
            score -= 25.0 - 0.4 * pair_left as f64;
        } else {
            // Next item cannot use this residual: penalize dead space
            score += 8.0 + 0.25 * next_item_size as f64;
        }
    }

    // Relative to mean residual: bins with more room than average absorb big items well
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no open bin fits well, opening a new bin is fine
        if post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Early stream: be more conservative with open bins (keep flexibility)
    let progress = step_index as f64 / total_items as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fills (small post_residual), with slight non-linearity.
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Penalize dead space that no future item (10..80) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0 + 8.0 * (1.0 - (nxt / cap));
        } else {
            score += 6.0 * (1.0 - t);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins -> consolidate; few -> spreading is fine.
    let pressure = (open_bins_count as f64) / (open_bins_count as f64 + 5.0);
    score += pressure * (post / cap) * 10.0;

    // Deviation from mean residual: prefer bins that balance residuals early,
    // but allow aggressive packing into tight bins late in the stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08 * (1.0 - t);

    // Late stream: tighten tolerance for wasted space.
    score += t * (post / cap) * 8.0;

    // New-bin candidate: neutral baseline; chosen only when all fits look bad.
    if bin_residual == bin_capacity {
        let new_bin_score = 55.0 + 0.15 * item - 10.0 * t
            - if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: small residuals are quadratic dead space.
    let pr_norm = pr / cap;
    score += 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * pr_norm;

    // Reward tight fits, more strongly as stream progresses.
    let tightness = 1.0 - pr_norm;
    score -= (8.0 + 14.0 * progress) * tightness * tightness;

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / cap).exp();
    } else {
        // Last item: prefer fuller bins.
        score -= 6.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly, more when open bins exist and fit well.
    if bin_residual == bin_capacity {
        let penalty = 6.0 + 10.0 * (1.0 - progress);
        score += penalty;
        if open_bins_count > 0 {
            score += 4.0 * (open_bins_count as f64).ln();
        }
    } else {
        // Prefer bins whose residual is below the mean (consolidate emptier space).
        score += 3.0 * (pr - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction does the leftover fall into?
    let frac = post_residual as f64 / bin_capacity as f64;
    let eighth = (post_residual * 8) / bin_capacity; // integer division threshold class 0..7

    // Reward small leftovers strongly (tight fits), with harmonic weighting per class
    let tight_bonus = match eighth {
        0 => 60.0,                       // post_residual < C/8 : excellent fit
        1 => 35.0,
        2 => 20.0,
        3 => 8.0,
        4 => 0.0,
        5 => -6.0,
        6 => -12.0,
        _ => -18.0,                      // > 7/8 empty after placement: wasteful
    };
    score -= tight_bonus;

    // Nonlinear exact-fit coupling: perfect fill gets extra reward
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= bin_capacity / 16 {
        score -= 25.0;
    }

    // Lookahead: does the next item fit into post_residual? Reward chaining.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 15.0 - chain_quality * 0.2;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a dead-space residual near next size
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Competition exists: prefer bins where this item fits most snugly relative to others
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Opening a new bin is good if open bins are mostly full (low mean residual)
        score = 50.0 - 45.0 * (1.0 - desperation) - 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, be slightly more willing to open fresh bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mild penalty for scattering across too many bins when mean residual is high
    if open_bins_count > 2 && mean_residual > bin_capacity as f64 * 0.5 {
        score += 4.0;
    }

    // Modulo harmonic nudge: residual divisible by common item sizes is more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: unusable small gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits (post_residual small relative to capacity)
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 20.0;

    // Open bins pressure: penalize spreading across many bins
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post_residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // gap too small for next item: dead space
    }

    // New-bin candidate: prefer opening a new bin only if current fit is bad
    if bin_residual == bin_capacity {
        score -= 12.0;
        if post_residual as f64 > mean_residual {
            score -= 8.0;
        }
    }

    // Stream progression: tighten behavior as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly (within a small slack)
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // full reward at slack 0, decaying to 0 at slack 40
    }
    // Next item does NOT fit this bin: penalize proportionally to wasted potential
    else if next_item_size > 0 && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        score += miss.min(80.0) * 0.5;
    }

    // Reward tight fits relative to current residual (small post_residual is good)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize bins whose residual is far below the mean (they are already cramped)
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 15.0 * dev.max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 5.0 + open_bins_count as f64 * 0.5;
    }

    // New-bin candidate: only attractive if current bins are nearly full / bad fits
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64);
        score = 70.0 - 40.0 * avg_fill;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.15 * dead;
        if next_item_size > 0 && next_item_size > post_residual {
            // Lookahead item cannot fit in the leftover -> wasted space.
            score += 0.25 * (next_item_size as f64 - dead).min(30.0);
        } else if next_item_size > 0 {
            // Lookahead chains nicely into this bin: big reward.
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 18.0 - 0.3 * gap;
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    // Many fitting bins: slight penalty to encourage diversification elsewhere.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Prefer filling bins that are already relatively full.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        score -= 6.0 * pressure;
        // Time horizon: early on be conservative, later consolidate aggressively.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * t * pressure;
    } else {
        // New-bin candidate: penalize when open bins have plenty of room,
        // reward when existing bins are nearly exhausted.
        score += 8.0 + 10.0 * (mean_residual / (bin_capacity as f64));
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // Late in the stream, opening a fresh bin is cheap; early, avoid it.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * t;
        // Large item nearly filling a new bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 5.0;
        }
    }

    // Mild penalty on opening bins when many are already open.
    if bin_residual == bin_capacity {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    score += 18.0 * prn * prn * (0.5 + progress);
    score -= 10.0 * prn * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tight = 1.0 - prn;
    score -= 14.0 * tight * tight * tight * (0.3 + 0.7 * progress);

    // Penalize waste relative to mean residual (dead space coupling)
    let dev = pr - mean_residual;
    score += 0.08 * dev * dev / cap;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (nx / cap) * (1.0 - prn);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.02 * (open_bins_count as f64) * progress;

    // New-bin candidate: prefer it only when it clearly beats poor fits
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead space that is too small to be useful later (harmonic bands)
    if post_residual > 0 {
        // residue classes modulo 10: small leftovers are near-worthless
        let m = post_residual % 10;
        if m > 0 && m < 5 {
            score += 6.0; // unusable sliver
        }
        // post_residual below the minimum plausible item size = dead space
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward tight fits (post_residual in a "good" harmonic band)
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if frac <= 0.1 {
        score -= 10.0; // very tight fit, small waste
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // prefer leaving space that matches a harmonic fraction of next item
            let r = post_residual - next_item_size;
            if r < 10 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: slightly penalize leaving large gaps unused
            score += 0.02 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // but if no open bin fits, this is forced; make it attractive relative to bad fits
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // early in stream, allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer filling bins with below-average residual (consolidate emptiness)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.05 * dev;
    }

    // Integer-division threshold: reward leaving space in coarse buckets
    let bucket = post_residual / 20;
    score -= bucket as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space severity relative to item size (small items creating small gaps)
    if post_residual > 0 && (post_residual as f64) < 0.35 * (item_size as f64) {
        score += 8.0;
    }

    // Open-bin pressure: fewer open bins preferred for filling existing ones
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 30.0;
        }
    }

    // Mean residual deviation: bins far below mean residual are worse targets
    score += 0.3 * ((post_residual as f64) - mean_residual).abs();

    // Stream progression: later in stream, be slightly more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (low dead space).
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 30.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly into post_residual,
    // this placement is excellent — reward it heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // next item fits; residual after that would be post_residual - next
            let after_next = post_residual - next_item_size;
            score -= 20.0 + after_next as f64 * 0.2;
        } else {
            // next item won't fit here; penalize leaving large awkward gaps
            let gap = post_residual as f64;
            score += gap * 0.3;
        }
    }

    // Penalize waste relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in stream, opening new bins is less costly (fewer future chances to fill).
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 20.0;
        // If next item is large and this bin is fresh, opening may pay off.
        if next_item_size > item_size && next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Slight penalty for accumulating many open bins with poor utilization.
    if open_bins_count > 5 && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful later (wasted space).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - next_fit / cap);
    } else if next_item_size > 0 {
        // Next item cannot use this residual: mild penalty scaled by wasted potential.
        score += 3.0 * (post_residual as f64) / cap;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into bins below the mean (filling the emptiest-feeling bins less favorably).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 6.0 * dev;
    }

    // Time horizon: early in the stream, be conservative (prefer existing bins);
    // late in the stream, prioritize perfect packing since stream end is near.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., when the item would leave a large or awkward residual elsewhere).
    if bin_residual == bin_capacity {
        let fresh_score = (item_size as f64) * 0.55
            - 15.0 * (fitting_bins_count == 0) as i32 as f64;
        // Compare against typical existing-bin scores: prefer new bin when
        // the best existing fit would be poor (post_residual large).
        let poor_fit = (post_residual as f64) / cap;
        score = fresh_score + 40.0 * poor_fit * (1.0 - progress);
    }

    // Mild penalty for proliferating bins when existing ones fit decently.
    if bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr;

    // Smooth non-linear penalty on wasted space, stronger as stream progresses
    score += 30.0 * x * x * (0.5 + progress);

    // Coupling: post_residual vs mean residual of open bins — avoid outliers
    score += 8.0 * (pr - mean_residual) * (pr - mean_residual) / (cap * cap);

    // Lookahead: reward post_residual that can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - (diff / cap).powi(2));
        } else {
            score += 6.0 * (-diff / cap);
        }
    }

    // Scarcity: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for opening a new bin when many bins are open and low fill
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: waste quantization ---
    // Items 1..=100; treat capacity in fifths (harmonic classes of 20).
    let class = post_residual / 20;                       // 0..=5
    let class_mid = class * 20 + 10;                      // midpoint of the class
    // Penalize residuals that fall in "dead" classes (too small to host typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;                                    // unusable sliver
    } else {
        // reward landing exactly on class boundaries (harmonic alignment)
        let off = (post_residual as f64 - class_mid as f64).abs();
        score -= (20.0 - off) * 0.25;
    }

    // --- Modular arithmetic on post_residual: divisibility bonuses ---
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;                                     // aligns with decile item sizes
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;                                     // quarter-capacity alignment
    }
    if post_residual % 7 == 0 && post_residual > 0 {
        score += 2.0;                                     // odd modulus => likely dead space
    }

    // --- Perfect closure ---
    if post_residual == 0 {
        score -= 100.0;
    }

    // --- Lookahead coupling: can next item fill the residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;                                // perfect chain
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // harmonic class match between next item and residual
            if next_item_size / 20 == class {
                score -= 8.0;
            }
        } else {
            // residual too small for next item: penalize proportionally to dead space
            score += (post_residual as f64) * (next_item_size as f64 / bin_capacity as f64) * 0.3;
        }
    }

    // --- Last-chance bin: strongly prefer using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: only attractive when nothing fits well ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 30.0 + open_bins_count as f64 * 0.5;
        // if some existing bin fits tightly, discourage the new bin
        if fitting_bins_count > 0 && post_residual <= 15 {
            score += 60.0;
        }
        // late in the stream, opening bins is cheaper than scattering residue
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // large items prefer fresh bins when mean residual is small
        if item_size >= 60 && mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    } else {
        // prefer tighter fits among open bins
        score += (bin_residual - item_size) as f64 * 0.1;
        // mild pressure to consolidate when many bins are open
        score += open_bins_count as f64 * 0.05;
    }

    // --- Mean-residual coupling: reward bins below mean residual (tighter) ---
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (1..=100 range,
    // assume small items may exist, but heavily penalize gaps below ~10 when they
    // can never be filled by typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Tight-fit reward: exact or near-exact fills.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness).max(0.0) * (1.0 - tightness).max(0.0);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading; a new empty bin gets a penalty proportional to count.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mean-residual alignment: bins far from the mean residual are less attractive.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Slight preference to fill bins earlier in the stream's lifecycle
    // (mild aging term to consolidate).
    score += 0.01 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual with next item is ideal.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact/near matches aggressively.
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 + 0.5 * progress);
        // Extra bonus for exact match.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual < next_item_size {
            // Next item can't follow here; mild penalty proportional to gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Dead-space penalty: small residuals that nothing can use (min item is small but
    // keep residual near-mean or tiny penalized if too fragmented).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean waste potential.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.10 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 45.0 - 30.0 * crowded.min(1.5);
        // If the new bin offers a perfect 2-step layout (item + next), encourage it.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild preference for tighter bins overall as stream progresses.
    score += 0.05 * (bin_residual as f64) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize post_residual quadratically (waste is super-linearly bad)
    let waste = post_residual as f64;
    score += 1.5 * (waste / 100.0) * (waste / 100.0) * 100.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves more waste: mild reward proportional to resulting tightness
            let pr2 = post_residual - next_item_size;
            if pr2 < 10 {
                score -= 80.0;
            } else {
                score -= 30.0 * (1.0 - pr2 as f64 / 100.0);
            }
        } else {
            // next item does NOT fit here: this bin becomes dead space after placement
            score += 40.0 + 0.5 * post_residual as f64;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate logic: opening a new bin is expensive unless current fits are terrible
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 60.0;
        // If many bins fit the item, opening new is wasteful
        if fitting_bins_count > 0 {
            score += 80.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // Large item into fresh bin is fine (big item leaves small residual anyway)
        score -= 0.3 * item_size as f64;
    }

    // Prefer bins with residual close to item size (relative fit)
    let rel_fit = item_size as f64 / bin_residual.max(1) as f64;
    score += 50.0 * (1.0 - rel_fit).abs();

    // Global state: many open bins with high mean residual -> encourage consolidation into low-residual bins
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 0.2 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = post / cap;

    // Base: reward tight fits (small post_residual), non-linearly.
    let mut score = post * (1.0 + 2.0 * fit_ratio * fit_ratio);

    // Stream-progress coupling: early on, prefer leaving flexible space;
    // late in the stream, aggressively minimize post_residual.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * post * post / cap;

    // Penalize dead space relative to mean residual of open bins (smooth coupling).
    score += 0.3 * (post - mean_residual).abs() * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let gap = post - next_item_size as f64;
        score -= 15.0 * (1.0 - gap / cap);
    }

    // Mild penalty for spreading across many bins early (encourages consolidation).
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    // New-bin candidate: make the empty bin attractive only when the item
    // would leave a large unusable gap in every existing bin.
    if bin_residual == bin_capacity {
        score = post + 10.0 - 20.0 * (fitting_bins_count == 0) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead space"
    // (too small for typical items) are heavily penalized.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0; // unusable sliver
    }

    // Integer division class: post_residual bucketed into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = post_residual / quarter; // 0..4 harmonic class
    score += (4 - class) as f64 * 2.0;

    // Perfect-fit harmonic bonus: post_residual divisible by common item classes.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual % 10 == 0 {
        score -= 8.0; // aligns with item-size grid
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chain two items into one bin
            let leftover2 = post_residual - next_item_size;
            if leftover2 == 0 {
                score -= 15.0; // exact double fill
            }
        } else {
            score += 4.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: prefer tighter ones implicitly via post_residual,
    // but add mild penalty proportional to crowding to avoid bin sprawl.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: empty bin gets a moderate opening cost,
    // waived when all open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count > 0 && mean_residual < (item_size as f64) * 0.5;
        let poor_fit = bin_capacity.saturating_sub(item_size) > half
            && next_item_size > bin_capacity.saturating_sub(item_size);
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        } else if crowded || poor_fit {
            score -= 10.0; // opening is reasonable
        } else {
            score += 30.0; // prefer reusing open bins
        }
    }

    // Slight time decay: later in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;
    score += mean_residual * 0.05; // prefer bins below mean residual (tighter)

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful (below the minimum plausible item size) are heavily
    // penalized as wasted capacity.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (bin_capacity as f64) * 2.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= (bin_capacity as f64) * 1.5;
    }

    // Non-linear penalty on small-but-maybe-usable gaps: the tighter the
    // leftover relative to capacity, the more we discourage squandering it
    // on a mediocre fit.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Reward leaving room for the lookahead item if it would fit the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(dead_threshold as u32) {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (bin_capacity as f64) * 1.2;
    }

    // Open-bin pressure: with many open bins, avoid spreading further;
    // opening new bins becomes less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.05 * pressure;

    // New-bin candidate: penalize relative to how well existing bins fit.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64) * 0.8 + mean_residual * 0.3;
        // Allow opening a new bin early when few bins exist.
        if open_bins_count < 3 {
            score -= (bin_capacity as f64) * 0.6;
        }
    }

    // Mild preference for bins whose residual is close to the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // 2-step lookahead: strongly reward if the NEXT item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Relative-to-mean-residual coupling: placing into a bin whose residual is
    // below average preserves large residuals elsewhere for future big items.
    let r = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (r - mean_residual) / mean_residual;
        score += 5.0 * rel.clamp(-1.5, 1.5);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible (post_residual leaves a big dead fragment).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64;
        if waste < 20.0 {
            score -= 30.0; // decent fit in the only option: take it
        } else {
            score += 10.0; // poor fit: allow a new bin to win instead
        }
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // It should only win when the item is large (little waste in an open bin anyway)
    // or no open bin fits well. Penalize the fresh bin mildly so tight fits win.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * fill_ratio; // large items justify opening a bin
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (open_bins_count as f64).ln_1p();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - t * t);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded (mean residual low) or none fit well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = mean_residual / bin_capacity as f64;
        // Base cost of a fresh bin, discounted when open bins are nearly full.
        score = bin_capacity as f64 * (0.9 - 0.5 * crowding) + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 5.0; // prefer saving fresh bins for larger items
        }
    }

    // Global pressure: with many open bins, favor consolidating into existing ones.
    score += open_bins_count as f64 * 0.5;

    // Mild bonus for filling bins above half capacity.
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.5 {
        score -= 10.0 * (fill - 0.5);
    }

    // Time-horizon term: late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), scaled non-linearly.
    let mut score = pr;

    // Non-linear tightening reward: quadratic coupling of post_residual with capacity.
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= 8.0 * tightness * tightness * tightness;

    // Perfect-fit bonus (post_residual == 0).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item are useless.
    let dead_threshold = 10.0_f64.min(cap * 0.1);
    if pr > 0.0 && pr < dead_threshold {
        score += 25.0 * (dead_threshold - pr) / dead_threshold;
    }

    // Lookahead coupling: reward if next item fits into post_residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - nxt / pr) * (1.0 - progress);
        } else {
            score += 6.0 * (1.0 - pr / nxt) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score = 45.0 + 40.0 * fragmentation + 10.0 * progress;
    }

    // Mild stream-progress term: later in the stream, favor tighter packing more aggressively.
    score += (1.0 - progress) * 2.0 - progress * 2.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact multiples / near-full bins are prized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Small dead-space classes (harmonic thresholds)
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual > bin_capacity / 2 {
        // Large residual is fine (usable), but if this is a NEW bin it's neutral
        score -= 5.0;
    }

    // Modulo-10 class: residuals that are multiples of 10 pair with common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 10.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins with low residual relative to mean (best-fit sharpening)
    score -= 0.5 * (mean_residual - pr);

    // Mild pressure to use open bins as stream progresses, countering new-bin bias
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 + 10.0 * progress;
    } else {
        // New-bin candidate: penalize slightly unless it's early or the fit is bad elsewhere
        score += 8.0 - 6.0 * progress;
    }

    // Integer-division threshold: bins whose residual halves cleanly are attractive targets
    if post_residual > 0 && (post_residual / 2) * 2 == post_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item are pure waste; penalize super-linearly.
    if post_residual > 0 {
        let dead = post_residual < 10; // cannot hold even the smallest item
        if dead {
            score += 60.0 + (10 - post_residual) as f64 * 8.0;
        } else {
            // Fragility: small-but-usable gaps are risky; scale penalty with gap smallness.
            let fragility = (100.0 - post_residual as f64) / 100.0;
            score += fragility * fragility * 12.0;
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or tightly,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 18.0 - slack * 2.0;
            } else {
                score += slack * 0.3;
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; opening new bins is penalized via the empty-bin call.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin starts with a baseline penalty
    // so consolidation wins unless this bin's fit is bad.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.2 - (open_bins_count as f64).sqrt() * 5.0;
        // If no open bin fits well (this call is the fallback), allow opening.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Progress: later in the stream, tighten up (value dense packing more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if (post_residual as i64) >= next_item_size as i64 {
            // Next item fits exactly or nearly: strong reward.
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit: penalize proportionally to wasted potential.
            score += 10.0 + gap * 0.5;
        }
    }

    // Compare residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating dead space below smallest plausible item (1..100 unknown, use small threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it attractive only when open bins are fragmented or fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / (bin_capacity as f64) } else { 0.0 };
        // Prefer new bin when existing residuals are scattered (high mean residual spread)
        // and current fit leaves a lot of dead space.
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        score -= 5.0 + fragmentation * 20.0 * poor_fit;
        // But discourage opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    // Mild penalty for too many open bins relative to stream length.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the next item can't use.
        let waste = (post_residual as f64 - next_item_size as f64).abs();
        score += 10.0 * (waste / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer filling bins with below-average residual (consolidate emptier bins).
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.3 * diff;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let fit_quality = post_residual as f64 / bin_capacity as f64; // = 1 - item/C for empty bin
        score += 80.0 * crowding * (1.0 - fit_quality) - 30.0 * (1.0 - crowding);
        score += 20.0 * progress;
        // Discourage new bin if an existing bin gives a near-perfect fit elsewhere.
        if item_size >= 90 {
            score += 40.0;
        }
    }

    // Mild penalty for very small items going into large residuals early in stream.
    let small_item_penalty = (item_size as f64 / bin_capacity as f64) * (1.0 - step_index as f64 / total_items.max(1) as f64);
    score += 5.0 * small_item_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: waste tolerated; late: strongly penalize large residuals.
    let w = 1.0 + 2.5 * progress * progress;
    score += 0.6 * w * (post / cap) * post / 10.0;

    // Reward tight fits (small post_residual) with smooth cubic shaping.
    let tight = 1.0 - post / cap;
    score -= 3.0 * tight * tight * tight * (1.0 + progress);

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 2.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Penalize leaving residual that the next item cannot use.
            let miss = (nxt - post) / cap;
            score += 4.0 * miss * miss * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        // Mild penalty when many bins fit, favoring better fills elsewhere.
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a bin unless it is a last resort
    // or mean residual across open bins is very low.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        let pressure = (mean_r / cap).min(1.0);
        score += 6.0 * (1.0 - pressure * pressure) * (1.0 - progress * 0.5);
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is close to the item size.
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * ratio * ratio;

    // Small open-bin count balancing term.
    score += 0.05 * (open_bins_count as f64).sqrt() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Class 0: post_residual divisible into nice chunks (multiples of 10/25/50).
    let pr = post_residual;
    let harmonic = if pr == 0 {
        3.0 // perfect fit — strongly reward
    } else if pr % 50 == 0 {
        2.0
    } else if pr % 25 == 0 {
        1.5
    } else if pr % 10 == 0 {
        1.0
    } else if pr < 10 {
        0.0 // dead space below min item size
    } else {
        -1.0
    };
    score -= harmonic * 12.0;

    // Dead-space penalty: leftover below the smallest possible item is wasted.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= 20.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot use this bin; penalize leaving large awkward residual
            score += 8.0 * (pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this bin is empty) and stream is early/many bins open.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // cheaper to open when few bins exist relative to progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // penalize opening when mean residual across open bins is large
        score += 0.5 * mean_residual;
        // large items justify fresh bins
        score -= (item_size as f64 - 50.0).max(0.0) * 0.4;
    }

    // Prefer tighter existing bins: residual close to item size is a good fit.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Mild preference to fill bins with high residual among many open bins.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // Modulo-class penalty: post_residual in "awkward" middle bands (11..24, 26..39)
    if (11..=24).contains(&pr) {
        score += 10.0;
    } else if (26..=39).contains(&pr) {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // realistic item (below the minimum plausible size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small unusable gaps (hard to fill later) get a non-linear penalty.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into
    // existing bins rather than spreading out.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: penalize when many bins are open
        // or when mean residual suggests existing bins have room.
        score += 40.0 + open_pressure;
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
    } else {
        // Existing bin: slight reward proportional to consolidation pressure.
        score -= open_pressure * 0.25;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.8;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

