    // Last-chance bin: heavy reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist.
    if bin_residual == bin_capacity {
        let open_penalty = 90.0 + 4.0 * open_bins_count as f64;
        let fit_bonus = if fitting_bins_count > 1 { 40.0 } else { 0.0 };
        score += open_penalty + fit_bonus;
        // Late in the stream, consolidating is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If mean residual across open bins is large, prefer using them.
        score += mean_residual.clamp(0.0, 100.0) * 0.6;
    } else {
        // Mild reward for packing into bins that are already partially filled below mean.
        if (bin_residual as f64) < mean_residual {
