        }
    }

    // Penalize creating residuals that are awkwardly small but nonzero (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: post residual, mildly discounted as stream progresses (tighter packing matters later)
    let mut score = pr * (1.0 - 0.35 * t * t);

    // Non-linear penalty for unusable dead space: residuals too small for typical future items
    let dead = if next_item_size > 0 {
        (next_item_size as f64 - pr).max(0.0) / cap
    } else {
        (0.0)
    };
    score += 18.0 * dead * dead * (1.0 + t);

    // Reward near-perfect fits (smooth quadratic in post-residual)
    let fit_quality = 1.0 - (pr / cap);
    score -= 10.0 * fit_quality * fit_quality;

    // Last-chance bonus: sole fitting bin should be strongly preferred
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when many open bins already exist
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / cap)).ln_1p();
        score += 12.0 + 4.0 * pressure + 8.0 * t;
    } else {
        // Favor bins tighter than the mean residual (smooth coupling)
        let rel = (mean_residual - bin_residual as f64) / cap;
        score -= 6.0 * rel;
    }

    // Lookahead coupling: prefer bins whose post-residual pairs well with next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 8.0 * gap * gap;
    }

    // Small smooth item-size interaction: big items prefer big residuals
    score -= 0.05 * item * (bin_residual as f64 / cap) * (0.5 + 0.5 * t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fit gets strong reward.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
