    } else {
        // Classify residual into harmonic bands via integer division thresholds.
        let q = post_residual / 10; // classes 0..10
        score += q as f64 * 2.0;    // larger dead space penalized progressively

        // Coupling: can the lookahead item fit into the post residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // reward chains that allow the next item to co-fit
                let slack_after = post_residual - next_item_size;
                score -= 30.0 + (10 - slack_after / 10) as f64 * 2.0;
            } else {
