    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits too: reward proportionally to how well it fills
            score -= 200.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize post residuals that are too small to ever be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Compare against mean residual across open bins: prefer bins with residual
    // close to or below mean (already well-utilized bins)
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive if no good fit exists
    if bin_residual == bin_capacity {
        score += 250.0;
        // late in the stream, avoid opening new bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 * progress;
        // if next item is large, a fresh bin may be worthwhile
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 100.0;
        }
    }

    // Mild preference for tighter bins overall
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-full packing more than linearly.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that no future item could plausibly use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).max(0) as f64
        } else {
            post_residual as f64
        };
        score += 0.9 * dead;
        // Perfect fit for the next item is highly desirable.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    // (large post_residual relative to mean residual) or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (post_residual as f64 - mean_residual).max(0.0);
        score += 30.0; // base cost of opening a bin
        score -= 12.0 * (1.0 - progress); // early stream: fresh bins more acceptable
        score -= 0.35 * poor_fit; // if open bins fit badly, new bin gains appeal
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
        // Never open a new bin if the item would fit an open bin snugly.
        if mean_residual < 0.0 { score += 100.0; }
    } else {
        // Reward using bins whose residual is close to the item (good fit).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * fit_gap;
        // Slightly prefer balancing residuals toward the mean.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Mild time pressure: later in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits, stronger as stream progresses
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * (0.5 + progress);

    // Penalize last-chance bins less when fit is good
    if fitting_bins_count == 1 {
        score -= 8.0 * tightness;
    }

    // Lookahead: reward residual that can hold next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Mild penalty relative to mean residual (avoid wasting well-packed bins)
    score += 0.05 * (pr - mean_residual).max(-50.0);

    // Slight preference to keep number of open bins low early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover space: exact halves/quarters are "usable" slots
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let mut bonus = 0.0;
    if post_residual == 0 {
        bonus -= 40.0; // perfect fit
    } else if post_residual == half {
        bonus -= 12.0; // half slot reusable by mid-size items
    } else if post_residual == quarter || post_residual == 3 * quarter {
        bonus -= 6.0; // quarter slots
    } else if post_residual % 10 == 0 {
        bonus -= 2.0; // decadal leftovers tend to match item sizes
    } else if post_residual < 10 {
        bonus += 15.0; // dead space below minimum item size
    }

    // Penalize small residuals that cannot host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            bonus -= 8.0; // chain placement possible
        } else {
            bonus += (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        bonus -= 20.0;
    }

    // New-bin candidate: keep it attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 { post_residual < 10 } else { false };
        if poor_fit || next_item_size > item_size {
            bonus -= 10.0;
        } else {
            bonus += 25.0;
        }
    }

    // Phase-based tightening: late in stream, prefer tight packing
    let phase = step_index as f64 / total_items.max(1) as f64;
    bonus -= phase * 5.0 * (1.0 - (post_residual as f64 / cap));

    // Coupling with mean residual: avoid bins far from the fleet average
    let dev = (post_residual as f64 - mean_residual).abs();
    bonus += dev * 0.05;

    score += bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits generally: the smaller post_residual relative to capacity, the better.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly in the post residual, reward;
    // if post residual is too small for the next item, penalize the dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new/loose bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 15.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current bins are poorly filled.
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
