pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize tiny dead space that nothing can use (post_residual < 10 unusable).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; slight penalty for wasting space next item can't use.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Time horizon: early in stream, be more conservative (prefer spreading);
    // late in stream, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins far from mean residual (prefer balanced usage).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let openness = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += 35.0 - openness - fit_ratio * 20.0;
        if fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Slight penalty for opening many bins relative to items.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Smooth non-linear coupling: quadratic growth of dead-space penalty with progress
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = it / (it + pr + 1.0);
    score -= 30.0 * tightness * tightness;

    // Lookahead: penalize if post_residual is just below next item size (wasted space),
    // reward if next item fits in the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (nx / cap);
        } else {
            let gap = (nx - pr) / cap;
            score += 18.0 * gap * gap;
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer opening a new bin early or when mean residual is high (fragmentation)
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0);
        score = 35.0 + 45.0 * frag * (0.3 + progress) - 25.0 * (1.0 - progress) * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score += 60.0; // don't open new bin when this is the only fitting option
        }
    } else if fitting_bins_count > 2 {
        // many alternatives: be pickier about large residuals
        score += 10.0 * norm_pr;
    }

    // Mild preference to consolidate into fewer bins as stream progresses
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that are "usable" sizes (multiples of small units)
    let unit = 10u32;
    let dead = post_residual % unit;
    score += dead as f64 * 2.5;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Post-residual in harmonic classes: classify via integer division
    let class = post_residual / 25; // 0..4 quartile classes
    match class {
        0 => score -= 10.0,          // tiny leftover, great fit
        1 => score -= 3.0,           // moderate leftover
        2 => score += 0.0,
        _ => score += 8.0,           // large waste
    }

    // Coupling with next item: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next fits, but check harmonic compatibility
            let pair_dead = (post_residual - next_item_size) % unit;
            score -= 15.0 - pair_dead as f64 * 1.5;
        } else {
            // next item won't fit here; penalize less if post_residual is a common class
            let cls = post_residual / unit;
            if cls >= 2 && cls <= 7 {
                score += 5.0;
            } else {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 20.0 + (fitting_bins_count as f64) * 4.0;
        // but if mean residual is low (all bins tight), new bin is fine
        score -= mean_residual * 0.3;
    }

    // Small lookahead-aware penalty for creating residual that mismatches typical sizes
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (<10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0; // semi-dead space
    }

    // Reward tight fits (perfect fill strongly favored).
    if post_residual == 0 {
        score -= 100.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins could have taken the item.
        score = bin_capacity as f64 - 25.0
            + 8.0 * fitting_bins_count as f64
            + 0.5 * open_bins_count as f64;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferation of open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
        return score;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer bins below mean residual
    // (consolidate leftovers) to reduce fragmentation.
    if (post_residual as f64) > mean_residual && open_bins_count > 3 {
        score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving large-ish gap.
        score += 2.0;
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

