        // Extra bonus for chain: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Penalize residuals too small for the next item (likely dead space)
        score += 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Penalize large waste relative to mean residual across open bins
    let waste = post_residual as f64 - mean_residual;
    score += 0.15 * waste;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with small residual before placement (tight fits)
    score += 0.25 * (bin_residual as f64 - item_size as f64);

    // New-bin candidate handling: keep it neutral-ish but discourage unless residuals are tight
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins would leave big waste
        let avg_waste = mean_residual - item_size as f64;
        score += 55.0 - 0.5 * avg_waste.max(0.0);
    }

    // Mild late-stream tightening: encourage filling bins fully as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: waste created by this placement.
    let mut score = post;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - post / cap;
    score -= 0.35 * tightness * item;

    // Penalize dead space that is too small for typical future items:
    // residual in (0, 10) is unusable waste; residual >= next item is useful.
    if post > 0.0 && post < 10.0 {
        score += 12.0;
    }
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.25 * nxt; // bin remains useful for lookahead item
        } else {
            score += 0.15 * (nxt - post); // lookahead won't fit here
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening bins unless item is large / stream early.
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_pressure = if fitting_bins_count == 0 { 40.0 } else {
            (fitting_bins_count as f64).ln().max(0.0) * 18.0
        };
        score += 25.0 + fit_pressure + 20.0 * progress;
        // Early stream: opening bins is cheaper.
        score -= 15.0 * (1.0 - progress);
        // Large items leave less fragmentation in a fresh bin.
        score -= 0.1 * item;
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer filling existing bins rather than spreading.
    if !is_new_bin {
        score -= 0.05 * mean_residual;
        score += 0.3 * open_bins_count as f64;
    }

    // Mild noise-free tie-break favoring fuller bins.
    score += 0.1 * (cap - bin_residual as f64).recip().min(1.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
