    score += 18.0 * post_norm * post_norm * (1.0 + progress);

    // Reward tight fits (small post residual) more strongly late in the stream
    let tightness = 1.0 - post_norm;
    score -= 10.0 * tightness * tightness * tightness * (0.5 + progress);

    // Coupling with mean residual: prefer bins whose residual deviates favorably from the mean
    let dev = (res - mean_residual) / cap;
    score += 6.0 * dev * (1.0 - 2.0 * post_norm);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Scarcity pressure: many open bins -> discourage spreading, favor filling existing bins
    let scarcity = (open_bins_count as f64).ln() / 10.0;
    score += scarcity * post_norm * 12.0;

    // Lookahead: if next item fits snugly into the post residual, reward; if it wastes it, penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 14.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let overshoot = (nxt - post) / cap;
            score += 8.0 * overshoot * overshoot;
        }
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    let is_new = bin_residual == bin_capacity && item_size > 0;
    if is_new {
        let avg_waste = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        let poor_fits = (fitting_bins_count as f64).recip();
        let new_bonus = 4.0 + 30.0 * avg_waste * avg_waste + 15.0 * poor_fits * poor_fits + 8.0 * (1.0 - progress);
        score += new_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover into deciles of capacity.
    let class = (post_residual * 10 / bin_capacity) as i32; // 0..=9
    // Dead-space penalty grows superlinearly for mid-small leftovers (hard to fill),
    // but tiny leftovers (class 0) are perfect fits -> strong reward.
    match class {
        0 => score -= 40.0,
        1 => score += 25.0,
        2 => score += 30.0,
        3 => score += 20.0,
        4 => score += 10.0,
        5 => score += 5.0,
        _ => {}
    }

    // Perfect fit reward scaled by how "rare" the fit is.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leftovers that no plausible next item (>=10) can use.
            if post_residual > 0 && post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Harmonic pairing: post_residual and next_item_size in same modulo class of 10
    // suggests complementary sizes in structured streams.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual % 10) == (next_item_size % 10) {
        score -= 10.0;
    }

    // Prefer tighter bins early (best-fit bias), relax toward mean residual later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to typical residuals, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals too small for the smallest possible next item (1..100 range).
    if post_residual > 0 && post_residual < next_item_size as f64 && next_item_size > 0 {
        score += 8.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // unless the new bin gives a perfect fit for the item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with open bins and stream progress.
        score += 15.0 + 0.8 * open_bins_count as f64 + 20.0 * progress;
        // But if item fills new bin exactly, allow it.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    } else {
        // Reward using existing bins more as open_bins_count grows.
        score -= 0.3 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (balanced use),
    // penalize outliers creating fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fit (small post_residual)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr {
            let gap = post_residual as f64 - nr;
            if gap == 0.0 {
                score -= 45.0; // perfect chain: next item fills this bin exactly
            } else if gap <= 10.0 {
                score -= 25.0 - gap * 1.5;
            } else {
                score -= (20.0 / (gap * 0.5)).min(10.0);
            }
        } else {
            // post_residual too small for next item: penalize dead space proportionally
            let dead = nr - post_residual as f64;
            score += dead * 0.6;
        }
    }

    // Penalize large residual waste relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.35;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual as f64 > 0.0 && (post_residual as f64 - next_item_size as f64).abs() > 15.0;
        let mut penalty = 18.0;
        if fitting_bins_count > 0 {
            penalty += 15.0;
        }
        if post_residual <= 10 {
            penalty += 30.0; // fresh bin with tiny item is wasteful
        }
        if bad_fit {
            penalty -= 12.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += progress * 8.0;
        score += penalty;
    }

    // Mild penalty for very large leftover space that likely becomes dead
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.4;
    }

    // Tie-break: prefer bins with less residual overall, slight noise-free determinism
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating dead space too small for typical items (1..100 range),
    // but only if it can't combine with the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // dead space the lookahead item cannot use
        } else if post_residual > 0 && post_residual >= next_item_size {
            score -= 8.0; // leaves room for the next item: good chaining
        }
        // Exact chain: leftover exactly fits next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // (would leave a big hole in existing bins) or existing bins are crowded.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let size_relief = (item_size as f64 / bin_capacity as f64) * 30.0;
        let crowding_relief = if mean_residual > 0.0 {
            (mean_residual / bin_capacity as f64) * 15.0
        } else { 0.0 };
        score = base_penalty - size_relief - crowding_relief + post_residual as f64;
        // If no other bin fits, opening is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild time-varying exploration: early in stream, encourage consolidation;
    // late in stream, slightly relax to reduce leftover fragments.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Prefer bins with residual below mean (fill the emptier-of-space bins
    // keeps a spread of usable residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Slight penalty for many open bins: encourage closing bins out.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual, amplified by stream progress
    let pr_norm = pr / cap;
    score += 6.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= 4.0 * (-(pr / (0.25 * cap + 1.0))).exp();

    // Lookahead: penalize residuals that cannot host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 3.0 * (nx - pr) / cap;
        } else {
            score -= 1.5 * (pr - nx) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: mildly penalize early, allow late when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score += 2.0 - 3.0 * progress + 4.0 * fragmentation;
    }

    // Prefer filling bins with low mean residual (consolidation)
    score += 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into
    // capacity fractions. Residuals that are "small and usable" by the
    // common small items (<= 20) are rewarded; large dead space penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction classes of residual: 1/4, 1/2, 3/4 of capacity.
    let q1 = cap * 0.25;
    let q2 = cap * 0.5;
    let q3 = cap * 0.75;

    // Reward bins whose post residual falls in a "harmonic class"
    // (matches likely future small items), penalize awkward middles.
    if pr <= q1 {
        score -= 6.0 * (1.0 - pr / q1); // tight fit is great
    } else if pr <= q2 {
        score += 3.0 * ((pr - q1) / q1); // awkward quarter: dead space risk
    } else if pr <= q3 {
        score -= 2.0 * ((pr - q2) / q1); // half-class: still reusable
    } else {
        score += 4.0 * ((pr - q3) / q1); // nearly empty: wasted opening
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: mild penalty proportional
            // to how much of the residual is "wasted" relative to next item.
            score += 2.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening cost grows with number of open bins and stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
        // If mean residual across open bins is large, opening new bin is bad.
        score += (mean_residual / cap) * 15.0;
    } else {
        // Existing bin: slight preference for fuller bins (smaller residual before placement).
        score += (bin_residual as f64 / cap) * 2.0;
    }

    // Modulo-class bonus: residuals that are multiples of 10 (or of the
    // item size) tend to tile well with integer item sizes.
    if post_residual % 10 == 0 {
        score -= 2.0;
    }
    if post_residual % item_size.max(1) == 0 {
        score -= 3.0;
    }

    // Late-stream consolidation: prefer packing into fewest bins near the end.
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.8 {
        score += (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: near-zero post residual is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Strict dead-space avoidance: gaps that no plausible item (min size 1..10)
    // can use are wasted. Penalize unusable small gaps hard.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold.min(20) {
        score += (dead_threshold.min(20) - post_residual) as f64 * 3.0;
    }
    // Extremely small unusable slivers (<10) are dead space regardless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: mild penalty proportional to waste.
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let open_pressure = (open_bins_count as f64 / 20.0).min(2.0);
    score -= open_pressure * (item_size as f64 / bin_capacity as f64) * 8.0;

    // New-bin candidate: only attractive when the item is huge relative to
    // typical residuals or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, discounted for large items.
        score = 30.0 - 25.0 * fill;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: when mean residual is large, existing bins are
    // spacious; prefer them over new bins slightly more.
    if bin_residual != bin_capacity {
        score -= (mean_residual / bin_capacity as f64) * 4.0;
    }

    // Late in the stream, closing out bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-perfect lookahead match: next item leaves a tiny usable remainder.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 / (1.0 + slack);
    }

    // Penalize residuals too small for typical future items (dead space).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 20.0;
    }

    // Reward bins tighter than average residual (good fillers).
    let pr = post_residual as f64;
    score -= (mean_residual - pr) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual == next_item_size;
        if !good_lookahead {
            score += 100.0 + 10.0 * open_bins_count as f64;
            if fitting_bins_count > 0 {
                score += 80.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual relative to capacity (dead space)
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac;

    // Reward tight fits (post_residual near zero)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (fitting_bins_count as f64).max(1.0);
        let tightness = if post_residual == 0 { 1.0 } else { 0.0 };
        score += 20.0 + 5.0 * pressure - 15.0 * tightness;
        // Opening a new bin is fine when item is large and mean residual low
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward leaving a residual that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_fit = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack_fit / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Global state: many open bins -> prefer filling existing ones
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (1.0 - t);

    // Prefer bins whose residual is close to the item (minimal waste)
    let waste = (bin_residual - item_size) as f64;
    score += 0.15 * waste;

    // Mean residual alignment: favor bins near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual, with a non-linear (quadratic) penalty
    // on leaving awkward mid-sized gaps (dead space ~ half capacity is worst).
    let normalized_post = post / cap;
    let mut score = post * (1.0 + normalized_post * (1.0 - normalized_post) * 2.0);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers; late in the stream, squeeze tightly.
    let tightness = 0.5 + 1.5 * progress * progress;
    score += post * normalized_post * tightness;

    // Penalize bins whose residual is far above the mean (hoarded space),
    // with a smooth quadratic spread term.
    let spread = residual - mean_residual;
    score += spread * spread * 0.01;

    // Reward tight fits: fraction of the bin consumed by this item.
    let fill = item / residual.max(1.0);
    score -= fill * fill * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin (smooth exponential reward).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item exactly,
    // penalize near-misses with a smooth kernel.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        if post >= next_item_size as f64 {
            score -= 10.0 * (-gap / 15.0) * (-gap / 15.0);
        } else {
            score += 5.0 * (1.0 - (gap / cap).min(1.0));
        }
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.05 * (1.0 + progress);

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity or no good fit exists (smooth logistic gate).
    if bin_residual == bin_capacity {
        let largeness = item / cap;
        score += 12.0 / (1.0 + (largeness * largeness * 30.0)) - 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "nice" fractions
    // of capacity (0, cap/4, cap/2, 3cap/4) are reusable; others are dead space.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post == quarter || post == half || post == 3 * quarter {
        score -= 25.0;
    } else if post < quarter {
        score += (quarter - post) as f64 * 0.6; // small unusable sliver
    } else if post >= half {
        score -= 10.0; // still roomy, likely reusable
    } else {
        // mid-range residue: bonus if next item fits exactly into it
        if next_item_size > 0 && next_item_size <= post {
            let next_post = post - next_item_size;
            if next_post == 0 {
                score -= 35.0;
            } else if next_post < quarter {
                score += 8.0;
            } else {
                score -= 6.0;
            }
        } else if next_item_size > post {
            score += 12.0; // residue can't host the lookahead item
        }
    }

    // Integer-division threshold classes on item size vs capacity
    let item_class = item_size / (bin_capacity / 10); // 0..10 classes
    match item_class {
        0 | 1 => score -= 4.0,   // tiny items: place anywhere cheaply
        7 | 8 => score -= 8.0,   // large items: urgent to place, avoid waste
        9 => score -= 15.0,      // near-capacity item: must go somewhere now
        _ => {}
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when the current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit_penalty = (post_residual as f64).powi(2) / cap; // quadratic dead-space cost
        score = 100.0 + bad_fit_penalty + open_bins_count as f64 * 2.0
            - progress * 20.0
            - if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
        // A fresh bin is attractive only for very large items or terrible fits
        if item_size > 3 * bin_capacity / 4 {
            score -= 70.0;
        }
        if post_residual < quarter && fitting_bins_count > 0 {
            score += 25.0; // don't open a bin for a fit that leaves a sliver
        }
    }

    // Mild pressure to prefer bins with low mean residual (denser bins)
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual that is too small for the smallest plausible item (size 1..)
    // is pure waste; residuals just above common item sizes are semi-usable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // tiny dead gap: extremely bad
        score += 60.0 * (10.0 - pr) / 10.0;
    } else if pr >= 10.0 && pr < 20.0 {
        // small gap: only fits very small items, moderately bad
        score += 15.0;
    }

    // Reward tight fits (post residual near zero but not creating tiny gap).
    if pr == 0.0 {
        score -= 40.0; // perfect fill
    } else if pr <= 5.0 {
        score -= 20.0;
    }

    // Reward when post_residual can host the lookahead item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / 80.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post residual can't host next item: mild penalty scaled by closeness
        score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Open-bin pressure: discourage spreading across many open bins unless fit is great.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_pressure * (pr / bin_capacity as f64);

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., leaving this bin with much more space than average) is worse.
    score += 0.5 * ((pr as f64) - mean_residual).abs() * 0.2;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fit is poor. Base cost for opening a bin.
    if bin_residual == bin_capacity {
        score += 30.0; // fixed opening cost
        // but if the item fits badly anywhere (post_residual in dead zone),
        // the empty bin becomes comparatively attractive because its post
        // residual is large and usable.
        if post_residual >= 20.0 {
            score -= 10.0;
        }
    }

    // Progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        // Exact match bonus: post_residual == next_item_size -> perfect packing
        let gap = (pr - next).abs();
        if gap < 1.0 {
            score -= 60.0; // perfect 2-item fill
        } else if pr > next {
            // next item fits in the remaining space; reward tighter fits
            let tightness = 1.0 - gap / bin_capacity as f64;
            score -= 25.0 * tightness;
        } else {
            // next item won't fit: penalize dead space that's too small to be useful
            let dead = pr / bin_capacity as f64;
            score += 15.0 * (1.0 - dead * 2.0).max(0.0);
        }
        // Coupling with mean residual: prefer bins deviating from mean when a match exists
        let dev = (pr - mean_residual).abs();
        score -= 8.0 / (1.0 + dev / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * fill_ratio;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with small residual overall (tight packing)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild penalty proportional to number of open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that no future item (min size 1) can use well:
    // residual below 10 is nearly unusable; penalize being in the "dead zone"
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // next item still fits here: mild reward scaled by how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here after placement: mild penalty
            score += 8.0;
        }
    }

    // Last chance: this is the only bin that fits — strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins. Penalize new bins unless current fit is poor.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64) / (bin_capacity as f64);
        score += 40.0 + 10.0 * waste;
        // If no open bin can fit at all, allow opening a new bin
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer closing out open bins over opening new ones
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Encourage balancing residuals toward the mean when many bins are open
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count.min(50) as f64).sqrt();

    // Slight preference for filling fuller bins early (best-fit-like pressure)
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post-residual, with non-linear (quadratic) waste penalty.
    let mut score = post + 0.8 * (post * post) / cap;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - post / cap;
    score -= 6.0 * tightness * tightness * (item / cap);

    // Penalize residual that is likely unusable: post_residual smaller than the
    // minimum plausible item size creates dead space.
    let dead = ((20.0 - post).max(0.0)) / 20.0;
    score += 5.0 * dead * dead;

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post - next_item_size as f64;
        score -= 4.0 * (1.0 - slack / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot fit the lookahead item.
        score += 3.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Late-stream consolidation: prefer filling existing bins rather than opening new ones.
    let progress_boost = 4.0 * progress;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, unless it perfectly
        // accommodates a large item with near-zero waste elsewhere.
        score += progress_boost + 0.02 * open_bins_count as f64;
    } else {
        // Slight preference for bins below mean residual (balancing load).
        score += 0.5 * (post - mean_residual) / cap;
    }

    // Smooth non-linear coupling of progress with waste.
    score += progress * (post * post) / (cap * cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small sizes) are more likely reusable.
    let pr = post_residual as u32;
    if pr > 0 {
        let mut class_bonus = 0.0;
        for m in [10u32, 15, 20, 25, 30, 40, 50].iter() {
            if pr % m == 0 {
                class_bonus += 6.0;
            }
        }
        // exact division thresholds: leftover divisible by next item is golden
        if next_item_size > 0 && pr % next_item_size == 0 {
            class_bonus += 25.0;
        }
        score -= class_bonus;
    }

    // Perfect fit: zero waste is ideal
    if pr == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: leftover too small for the minimum item size (1)
    // is fine, but leftover in the awkward band (1..10) is nearly unusable.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit here afterward: mild penalty scaled by how much
        // of the next item would be wasted relative to capacity fraction
        let frac = (next_item_size as f64 - pr as f64) / cap;
        score += 8.0 * frac.max(0.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.5 {
            score -= 30.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin fits well. Penalize the fresh bin (residual == capacity)
    // unless the item is large relative to capacity or many bins are open.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let mut new_bin_score = 15.0; // base cost of consuming fresh capacity
        if item_frac > 0.7 {
            new_bin_score -= 20.0; // large items deserve a fresh bin
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // nothing fits: must open
        }
        // many open bins with high mean residual -> prefer reusing space
        new_bin_score += (open_bins_count as f64).min(20.0) * 0.5;
        new_bin_score += (mean_residual / cap).min(1.0) * 10.0;
        // stream progression: late in stream, consolidation matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 10.0 * progress;
        score += new_bin_score;
    }

    // Mild preference to fill emptier bins first (balance load across bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for even the
    // smallest plausible item are pure waste; penalize them heavily.
    if post_residual > 0 {
        // Smallest item that could still use the gap (interface floor = 1).
        if post_residual < 10 {
            // Unusable sliver: nearly as bad as wasted space.
            score += 40.0 + (10 - post_residual) as f64 * 8.0;
        } else if post_residual < 20 {
            score += 12.0 + (20 - post_residual) as f64 * 2.0;
        } else {
            // Larger usable gaps are mildly rewarded relative to raw residual.
            score -= (post_residual as f64) * 0.05;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Tight fit reward: how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // placing here over opening a new bin (unless post_residual is a sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; few open bins -> opening a new one is cheaper.
    score += (open_bins_count as f64) * 1.5;

    // Compare against mean residual: bins with residual well below mean are
    // already "cramped"; placing here risks stranding the mean gap.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    // Lookahead coupling: if the next item could use this bin's post_residual,
    // reward leaving exactly that much room.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or nearly: excellent chaining.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.5;
        } else if next_item_size > bin_residual {
            // Next item won't fit this bin either way; slight relief on
            // dead-space pressure here.
            score -= 3.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with open-bin pressure, so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // But if no tight fit is available elsewhere, opening is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer reusing bins to avoid trailing waste.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference for bins whose post_residual aligns with common item
    // sizes (multiples of 10): such gaps are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1) are pure waste.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward if the NEXT item fits exactly into the post-residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < f64::EPSILON {
            score -= 55.0; // chain of perfect fits
        } else if next <= post_residual as f64 {
            let slack = post_residual as f64 - next;
            score -= 20.0 * (1.0 - slack / cap); // next fits: reward tight chains
        } else {
            // next item won't fit here; penalize proportionally to the gap
            score += 8.0 + 0.15 * (next - post_residual as f64);
        }
    }

    // Favor bins whose residual is already below mean (consolidating fuller bins).
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.10 * mean_gap;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += cap * 0.35 + 20.0;
        // But allow opening when existing fit leaves a huge unusable residual.
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 10 {
            score -= 10.0;
        }
    }

    // Mild pressure to spread across bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits into post_residual, this placement chains nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64 / bin_capacity as f64) * 12.0;
        } else {
            // Dead space the next item cannot use.
            score += (post_residual as f64).min(next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with residual below mean residual (already committed bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are very poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: open new bin
        } else if mean_residual > item_size as f64 * 1.6 {
            score -= 20.0; // existing residuals are loose anyway
        }
        // Late in the stream, avoid spreading items across new bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    // Mild preference for bins that become highly fragmented otherwise.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill
    }

    // Many open bins: consolidate.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);

    // Penalty for very small unusable post-residual (dead space) unless near end
    let dead = (norm_pr - 0.05).max(0.0) / 0.95;
    score -= 25.0 * (1.0 - dead) * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 35.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Prefer filling bins with high residual relative to mean (consolidate)
    score -= 8.0 * (bin_residual as f64 - mean_residual) / cap;

    // Mild preference to keep open bin count low
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        let new_penalty = if fitting_bins_count == 0 { -30.0 } else { 55.0 * (1.0 + progress) };
        score += new_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are prized, since tiny leftovers = tight fit.
    // Classes defined by integer division on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual / (bin_capacity / 10).max(1)) as i64; // 0..10 harmonic class
    let class_bonus: f64 = match class {
        0 => 45.0,           // post_residual < 10% : nearly perfect fit
        1 => 30.0,
        2 => 18.0,
        3 => 8.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize leftovers in the "dead zone": too small for the smallest
    // plausible future item, i.e. unusable waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that can host it only awkwardly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover still useful for the known next item
            score -= 12.0;
            // harmonic check: can it also host next item plus a small extra?
            if post_residual >= next_item_size + 10 {
                score -= 6.0;
            }
        } else {
            // the next item won't fit here -> this bin becomes dead weight
            score += (next_item_size as f64 - post) * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin gets a neutral baseline.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when few bins are open or stream is early;
        // penalize slightly when many bins are already open and mean residual
        // suggests open bins are under-filled.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0
            + 0.4 * mean_residual
            + 25.0 * (1.0 - progress)
            + (open_bins_count as f64).sqrt() * 4.0;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 8.0; // a fresh bin trivially fits the next item
        }
        return score;
    }

    // Prefer fuller bins overall: tighter packing keeps mean residual low.
    let fill = (bin_residual as f64) / cap;
    score -= 20.0 * fill * fill;

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it is one of the "tightest" bins -> reward using it up.
    let diff = mean_residual - post;
    if diff > 0.0 {
        score -= diff * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (dead space).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 30.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits (post_residual close to 0 but not wasted).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are already open (open-bins pressure) and when another bin fits well.
    if bin_residual == bin_capacity {
        score += 60.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if post residual is nonzero but too small for the next item.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * progress;

    // Prefer bins with residual close to item (tight fit relative to others).
    score += 0.1 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64);
    }

    // Penalize post-residual that cannot host the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Prefer bins whose residual is tighter than average (best-fit flavor).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    // Slight late-stream preference for compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear in wasted space).
    let waste = post_residual as f64;
    score -= (bin_capacity as f64 - waste) * 0.5;

    // Penalize leaving dead space that cannot host typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 40.0 + 0.5 * (post_residual as f64 - nxt);
        } else {
            // Penalize residual that blocks a large next item.
            score += 0.3 * (nxt - post_residual as f64).min(50.0);
        }
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, prefer consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than spreading.
    score += open_bins_count as f64 * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins near the mean residual (balanced usage),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (post_residual as f64) > 0.7 * bin_capacity as f64;
        if desperation > 0.0 || (poor_fit && progress < 0.9) {
            score -= 150.0 * desperation + if poor_fit { 20.0 } else { 0.0 };
        } else {
            score += 100.0; // discourage opening new bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: penalize large post-residual, with a mild convexity term
    // so mid-size dead space is punished more than near-perfect fits.
    let mut score = pr + 18.0 * x * (1.0 - x) * cap;

    // Non-linear coupling with stream progress: early on, keep bins flexible
    // (favor larger post-residual slightly); late in stream, prefer tight fits.
    let tightness = 1.0 - progress;
    score += 24.0 * x * x * tightness * cap * 0.15;
    score -= 20.0 * x * progress;

    // Lookahead coupling: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = (x - nx).max(0.0);
        score -= 12.0 * fit_next * (1.0 - fit_next);
        // Penalize leaving a residual just barely below next item (dead space)
        let gap = (nx - x).max(0.0);
        score += 10.0 * gap * gap * cap * 0.05;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 10.0 * progress;
    }

    // Crowding: with many open bins, prefer consolidating (tight fits).
    let crowding = (open_bins_count as f64).ln() / 4.0;
    score += crowding * 8.0 * x;

    // Mean residual context: if this bin's residual is far below the mean,
    // it's a good "filler" bin; reward closing the gap.
    let gap_mean = (mean_residual - pr).max(0.0) / cap;
    score -= 6.0 * gap_mean * (1.0 + progress);

    // New-bin candidate adjustment: empty-bin call gets neutral-ish score,
    // slightly worse than a decent fit but better than a terrible one.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 25.0 * progress - 8.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets strong discount.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Harmonic-class discount: bins whose residual falls into low modulo classes
        // of capacity are more reusable for typical item sizes.
        let frac = post_residual as f64 / bin_capacity as f64;
        score -= 60.0 * (1.0 - frac) * (1.0 - frac);

        // Dead-space penalty: residual too small for the smallest plausible item.
        if post_residual < 10 {
            score += 80.0;
        }
    }

    // Lookahead coupling: favor bins whose post_residual matches next item size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use leftover; mild penalty proportional to waste.
            score += 10.0;
        }
        // Exact lookahead fit is excellent.
        if post_residual == next_item_size {
            score -= 120.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Penalize spreading across too many open bins when mean residual is high.
    if open_bins_count > 1 {
        score += 0.5 * (open_bins_count as f64 - 1.0) * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual as f64 - mean_residual).abs() < f64::EPSILON; // always true for new bin; use fitting count instead
        let _ = good_fit_exists;
        // Base cost of opening a new bin.
        score += 150.0;
        // But if the current item is large relative to mean residual, opening
        // a fresh bin may be better than fragmenting a partially-filled one.
        let pressure = item_size as f64 / mean_residual.max(1.0);
        if pressure > 0.9 {
            score -= 120.0;
        }
        // Late in the stream, prefer consolidating.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // Large items into a fresh bin keep residuals clean.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Harmonic modulo classes on post_residual: residuals divisible into
    // common item chunks (e.g. multiples of 10) are more valuable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual > 0 && post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // If next item is close but leaves a tiny dead gap again, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using an existing bin when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., tighter bins get filled first, keeping loose bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only allow it
    // when the item would leave a large awkward gap in an existing bin.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * -0.2;
    }

    // Stream progression: later in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual,
    // or fits comfortably into it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item matches residual
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 0.5;
        } else {
            // next item cannot use this residual: penalize small dead space
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize creating small unusable residuals (dead space) that no
    // typical item (>= 1) could be assumed to fill precisely.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave awkward residuals relative to mean residual.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual {
            score += 250.0; // discourage opening new bin when open bins are roomy
        } else {
            score -= 50.0; // mild encouragement when open bins are tight
        }
    } else {
        // Favor bins with below-mean residual (tighter packing first).
        if (bin_residual as f64) < mean_residual {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // Slight preference to fill older/more populated bins to keep bin count low.
    score += open_bins_count as f64 * 0.05;

    // Stream progression: become more conservative (avoid new bins) late in stream.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear squash.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that becomes unusable for typical future items:
    // small residuals (1..=9) are almost certainly dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can also fit here -> excellent chaining
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // residual too small for next item: mild penalty scaled by waste
            let waste = post_residual as f64;
            score += 4.0 * (waste / 10.0).min(1.0);
        }
        // If next item exactly fills this bin after placement, big bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Dynamic time horizon: early in stream, be more willing to open new bins
    // (spread items); late in stream, consolidate into existing bins.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> discourage
    // opening new bins, encourage filling existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are underutilized.
        score += 6.0 + 0.15 * open_bins_count as f64 + 0.1 * mean_residual;
        // But late in the stream with fragmented bins, opening may be fine.
        score -= 8.0 * progress;
    } else {
        // Existing bin: reward relative to mean residual (better-than-average fit).
        score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Mild penalty for very large items going into nearly empty bins when
    // many bins are open (keep big items together with big residual bins).
    if item_size >= 50 && bin_residual as f64 > mean_residual + 20.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + progress) + norm_post * (1.0 - progress) * 0.3;
    score += 40.0 * poly;

    // Reward tight fits, stronger later in the stream
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - progress);
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Penalize fragmenting bins relative to mean residual
    let frag = (post_residual as f64 - mean_residual) / cap;
    score += 12.0 * frag * frag.abs();

    // Mild pressure against spreading across many bins early
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive for very large items
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls on "useful"
    // residue classes (small leftovers, easily filled) are rewarded.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 8.0,           // perfectly divisible leftover
        1 | 2 => score -= 4.0,       // near-perfect fill
        3 | 4 | 5 => score -= 1.5,   // decent mid-class
        6 | 7 => score += 3.0,       // awkward mid leftover
        8 => score += 6.0,           // very awkward (8-9 gap too small for min item)
        _ => score += 1.0,
    }

    // Integer-division threshold: leftover that cannot hold even a minimum item
    // is pure dead space; punish proportionally.
    if pr < 10 && pr > 0 {
        score += 25.0;
    }
    if pr == 0 {
        score -= 30.0; // perfect closure
    }

    // Coupling with lookahead: if next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit anywhere else, prefer this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when existing bins are underutilized.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But allow new bins when mean residual is small (all bins nearly full).
        score -= mean_residual * 0.4;
    }

    // Slight preference to fill older bins as the stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 0.0
        - (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit any future item (1..10)
    // are pure waste; penalize them heavily and nonlinearly.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize large leftover gaps that will likely become dead space anyway,
    // but less than unusable ones.
    if post_residual > 80 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it cannot fit, this gap is likely dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 12.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count == 1 {
        score -= 25.0; // last-chance bin: prefer using it over opening a new bin
    }
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual < 10 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (smaller residual = tighter bin = better use).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Mild stream progression: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Exact match: huge reward
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 20.0;
    }

    // Penalize post_residual far above mean residual (wasteful leftover)
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.8 * (pr - mean_residual);
    } else {
        score -= 0.4 * (mean_residual - pr);
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins give a decent fit
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin if existing fits would leave large dead space
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 > 20 {
            score -= 35.0;
        }
    }

    // Mild late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * pr * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Penalize leaving residual that is too small to ever be useful
    // (dead space): residual below the minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin; if next item would leave this bin's
    // residual unusable, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave very poor fits and mean residual is fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Fresh bin is attractive when existing bins are highly fragmented
        // and this item is large.
        score += 120.0;
        score -= 150.0 * fragmentation;
        score -= 50.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        if poor_fit < 0.2 {
            score += 100.0;
        }
    }

    // Mild preference for fuller bins (waste-averse): penalize bins with
    // large residual before placement less if they end up fuller.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Time horizon: early in the stream, be more conservative (favor
    // spreading items); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - tightness);

    // When many bins are open, favor consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 8.0 * tightness;

    // Slight bonus when this bin's residual is below the mean residual
    // (it is already one of the fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, but with diminishing (quadratic) cost
    let mut score = pr - 0.5 * cap * norm_pr * norm_pr;

    // Smooth non-linear coupling with stream progress:
    // early on, waste matters less; late, compact bins are precious
    let progress_coupling = 2.0 * progress * (1.0 - progress); // peaks mid-stream
    score += pr * (0.3 + 1.2 * progress) * (1.0 - 0.4 * progress_coupling);

    // Lookahead: reward residual that can host the next item (smooth kernel)
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64).abs();
        let kernel = (-fit_gap / 25.0).exp();
        score -= 6.0 * kernel * (1.0 + progress);
        // penalize residuals that are tantalizingly close but insufficient
        let near_miss = if pr < next_item_size as f64 {
            (-(next_item_size as f64 - pr) / 15.0).exp()
        } else {
            0.0
        };
        score += 4.0 * near_miss * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // Crowding: with many open bins, prefer tightening existing ones
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 0.15 * crowd * norm_pr * (0.5 + progress);

    // Mean-residual alignment: prefer bins whose residual is near the mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: mild default penalty so it only wins when open bins are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into coarse buckets.
    let pr = post_residual;
    let class = pr / 10; // integer division: 0..10 harmonic class of leftover
    score += (class as f64) * 0.7;

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100 unknown).
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr == 0 {
        score -= 15.0; // perfect fill reward
    }

    // Capacity fraction coupling: reward bins whose fill fraction crosses harmonic marks.
    let fill = (cap_f - post_residual as f64) / cap_f;
    let harmonic = (fill * 4.0).floor(); // quarters of the bin
    score -= harmonic * 3.0;

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // mod-10 harmonic match between leftover and next item
            if pr % 10 == next_item_size % 10 {
                score -= 8.0;
            }
            score -= (pr - next_item_size) as f64 * 0.2;
        } else {
            // leftover cannot host next item: penalize proportionally to wasted potential
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well; penalize opening bins early.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // late in the stream, avoid spawning bins with small leftover potential
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mean-residual deviation: prefer bins whose residual diverges from the mean
    // (harmonic specialization: keep diverse leftover classes alive).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    // Modulo threshold on item size: large items (mod classes >= 7 of 10) prefer tight bins.
    if item_size >= 70 && post_residual < 20 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize especially gaps in the "unusable" band (1..=10).
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Penalize leaving a gap that the next item could have used but this bin won't fit it.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) > post_residual && (next_item_size as u32) <= bin_residual {
            score += 15.0; // next item could have gone here, now it can't
        }
        if (next_item_size as u32) == post_residual {
            score -= 30.0; // perfect two-item chaining opportunity
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making new bins less attractive.
    let new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if new_bin {
        score += open_bins_count as f64 * 8.0;
        // Opening a new bin is fine if existing bins are nearly full on average.
        score += (mean_residual - 20.0).max(0.0) * -1.5;
    } else {
        // Favor bins with residual close to mean (balanced packing), slight effect.
        score += ((post_residual as f64 - mean_residual).abs()) * 0.3;
    }

    // Late in the stream, waste matters more; tighten dead-space penalties.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (post_residual as f64 / bin_capacity as f64) * progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

