    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
