        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward proportional to fill
            score -= (next_item_size as f64) * 0.5;
        } else {
            // next item cannot use this residual: penalize small leftovers
            score += (cap_f - post) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer fuller bins relative to mean residual.
    score += (mean_residual - post) * 0.3;

    // Early in stream: keep bins flexible; late: squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = cap_f * 0.6;
        score = score.max(base) + if fitting_bins_count == 0 { -50.0 } else { 40.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (below a "usefulness floor") are heavily penalized.
    let dead_floor: f64 = 9.0; // smallest plausible item is 1, but tiny gaps waste capacity
    if (post_residual as f64) < dead_floor && post_residual > 0 {
        score += (dead_floor - post_residual as f64) * 8.0;
    }

    // Reward tight fits: the smaller the post_residual relative to the bin,
    // the better the packing efficiency.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Penalize bins whose residual deviates strongly from the mean residual:
    // prefer balanced packing unless it is a perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and avoid opening new bins.
    score += open_bins_count as f64 * 0.8;

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            // next item cannot use the leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // no open bin fits well; make it a fallback with a moderate base cost.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step lookahead: post_residual matches next item exactly.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item fits exactly into the post-residual.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits after current one: reward proportionally to tightness.
            score -= 25.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit: penalize wasted residual relative to gap.
            score += 8.0 + lookahead_gap * 0.3;
        }
    }

    // Tight fit reward: small post_residual is good, but avoid dead space < smallest item (1).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * tightness * tightness;

    // Relative-to-mean coupling: bins with residual above mean can absorb more.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, consolidating matters more; keep penalty high.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot hold even the smallest plausible item (size ~1).
    if post_residual < 1 {
        score += 50.0;
    }
    // Penalize residuals too small to pair with typical lookahead items.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
    }
    // Strong reward when this placement leaves room exactly for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    // Many fitting bins: slight penalty to prefer spreading / best fit elsewhere.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Encourage filling bins that are far below the mean residual (balancing).
    let resid_gap = mean_residual - bin_residual as f64;
    score += 0.05 * resid_gap;

    // Time horizon: early in stream, be conservative (penalize fragmentation);
    // late in stream, prioritize closing bins out (reward low post_residual harder).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let crowding = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        let poor_fit_elsewhere = if next_item_size > 0 {
            ((bin_capacity - item_size) as f64 - next_item_size as f64).abs() / bin_capacity as f64
        } else { 0.0 };
        // Baseline: new bin is usually worse than a decent existing fit.
        score += 10.0 - 2.0 * crowding.min(4.0) + 8.0 * poor_fit_elsewhere;
        // If this is the only option (no other fitting bins), make new bin viable.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer reusing open bins to consolidate.
        score += 8.0 * progress;
    }

    // Mild penalty for opening many bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Small non-linear bonus for medium residuals that remain versatile.
    if post_residual >= 20 && post_residual <= 50 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: as stream advances, tighten preference for tight fits
    // (dead space becomes more costly later).
    score += 25.0 * progress * norm_post * norm_post * cap / 100.0;

    // Smooth penalty for leaving residual just below the minimum item size range
    // (unusable dead space), modeled as a smooth bump around small residuals.
    let dead = (1.0 - (norm_post / 0.10).min(1.0)).max(0.0);
    score += 15.0 * dead * (1.0 - norm_post);

    // Lookahead coupling: reward residual that can fit the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (nxt / cap) * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_post);
    }

    // Mild pressure toward consolidating residuals near the mean.
    score += 0.5 * (post - mean_residual).abs() / cap;

    // New-bin candidate: neutral baseline so it wins only when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small leftovers are dead space
    let pr = post_residual;
    if pr <= 10 {
        score -= 40.0; // tiny gap still usable by min-size items
    } else if pr < 50 {
        score += (50 - pr) as f64 * 0.8; // mid-range dead space penalty
    }

    // Modulo arithmetic on capacity fractions: bins whose residual lies in
    // "harmonic" bands (multiples of 10 / 25) are easier to fill later.
    if pr % 10 == 0 {
        score -= 12.0;
    }
    if pr % 25 == 0 {
        score -= 8.0;
    }

    // Integer-division threshold: residual in (50, 100) half-band
    if pr / 50 == 1 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward leaving space usable by next item, scaled by tightness
        score -= (pr - next_item_size) as f64 * 0.3;
        if (pr - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here; penalize leaving awkward gap
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Prefer filling bins with low mean residual (tighten packing)
    score -= (mean_residual / bin_capacity as f64) * 10.0;

    // Slight preference to reuse existing bins vs opening new ones as stream matures
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize early, allow late when open bins are full-ish
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 25.0 + 40.0 * (1.0 - progress) - 30.0 * avg_fill;
    } else {
        score -= 5.0;
    }

    // Tie-break: tighter fits first
    score -= (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable gaps: residual that is hard to fill later.
    // A gap is "dead" if it's below the minimum plausible item size (1..100 range),
    // with escalating penalty for very small gaps (1..15).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 15.0 {
            score += 60.0 * (15.0 - gap); // strongly punish tiny dead space
        } else if gap < 30.0 {
            score += 20.0 * (30.0 - gap) / 15.0; // moderately punish small gaps
        }
        // Reward leaving gaps that the lookahead item could fill.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
            // Extra reward if the gap matches the next item closely.
            let slack = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 20.0 / (1.0 + slack);
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, prefer it heavily
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // encourage consolidating into existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 40.0 + 8.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual;
        // Late in the stream, strongly avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    } else {
        // Existing bin: slight reward scaled by how much this reduces open pressure.
        score -= 2.0 * open_bins_count.min(20) as f64 * 0.1;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * residual_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild convex penalty
    // on very small post_residuals to avoid creating unusable dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the
    // next item size exactly (chain packing), penalize mismatch relative to
    // mean residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain match gets a strong bonus.
        if post_residual == next_item_size {
            score -= 8.0;
        }
        // If next item cannot fit this bin's post residual, penalize relative
        // to how much slack the average open bin has.
        if post_residual < next_item_size {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).max(0.0));
            score += 0.5 * (mean_residual - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins overall: compare residual against mean residual.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: make it unattractive unless open bins are badly
    // fragmented (high mean residual with few fitting options).
    if bin_residual == bin_capacity {
        score += 20.0;
        if mean_residual > 40.0 && fitting_bins_count <= 2 {
            score -= 25.0;
        }
    }

    // Late in the stream, consolidate: penalize opening bins when many exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space relative to remaining stream horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 1.0 - progress;
    score += 0.05 * (post_residual as f64) * horizon;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins with fewer alternatives when fits are tight
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0;
            // extra reward if next item fills bin nearly exactly
            let nxt_waste = post_residual - next_item_size as u32;
            score -= 10.0 * (1.0 - nxt_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize small post_residuals that strand space
            score += 0.08 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Prefer bins below mean residual (keep a spread of sizes)
    score += 0.5 * ((post_residual as f64) - mean_residual).abs().signum()
        * ((post_residual as f64) - mean_residual);

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if fitting_bins_count > 0 {
            // waste if forced into an existing bin is unknown; use mean residual gap
            (mean_residual - item_size as f64).max(0.0)
        } else { 0.0 };
        // discourage new bin mildly; allow it when existing residuals are all tiny
        score += 20.0 - 0.3 * best_possible.min(50.0);
        score -= 5.0 * horizon; // early on, opening bins is cheaper
    }

    // Mild penalty for very large open_bins_count (encourage consolidation)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for fuller bins late in the stream
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize very tight fits less as stream progresses (dead space matters more early)
    let tightness = (pr / cap) * (pr / cap);
    score += 20.0 * tightness * (1.0 - progress) - 10.0 * tightness * progress;

    // Interaction with mean residual: prefer bins near the mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Last-chance bonus (only fitting bin): reward strongly, smoothly scaled by progress
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward; smooth quadratic coupling
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        let miss = (next_item_size as f64 - pr) / cap;
        score += 6.0 * miss * miss;
    }

    // Slight penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64) * 0.3 * progress;

    // New-bin candidate: mildly discourage unless residuals are poor
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - progress) - (mean_residual / cap) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue classes.
    let pr = post_residual;
    let class = pr % 10; // decade residue class
    // Residues that pair well with common item sizes (1..=100): small residues are "usable" dead space.
    let class_bonus: f64 = match class {
        0 => -14.0,
        1 => -6.0,
        2 => -3.0,
        3 => -1.0,
        4 => 0.0,
        5 => 2.0,
        6 => 4.0,
        7 => 6.0,
        8 => 9.0,
        _ => 12.0,
    };
    score += class_bonus;

    // Integer-division threshold: exact fill is golden.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Fraction of capacity left after placement: quadratic penalty on wasted fraction.
    let frac = pr as f64 / bin_capacity as f64;
    score += 18.0 * frac * frac;

    // Tight-fit reward: item fills most of the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward (harmonic chaining).
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 45.0;
        } else {
            // modulo harmony: next item leaves a small residue again
            let next_res = pr - next_item_size;
            if next_res % 10 <= 2 {
                score -= 12.0;
            }
            score -= 8.0 * (next_item_size as f64 / pr.max(1) as f64);
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here: mild penalty for leaving it stranded
        score += 6.0;
    }

    // New-bin candidate handling: empty bin should win only when no good fit exists.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: neutral residual value plus a modest opening cost
        score = bin_capacity as f64 * 0.5 + 8.0;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative, allow opening
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin useful for large follow-up
        }
    }

    // Stream progression: early on, be conservative with new bins; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 6.0 * progress;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    score += 0.4 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; a new
    // empty bin is penalized unless the current fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64;
        score -= 10.0 - 0.05 * open_bins_count as f64;
        score += fit_quality * 0.5; // new bin starts with large residual
    } else {
        score -= 0.08 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Prefer bins below the mean residual when residuals are large (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Slight extra reward when next item fits exactly (diff == 0 handled above).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: just minimize waste, already done by base score.
        score -= 5.0;
    }

    // Penalize creating unusably small residuals relative to the smallest plausible item (1..100 range, assume ~10 useful floor).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when it preserves
    // large contiguous space. Base post_residual for an empty bin is large (capacity - item),
    // which already favors it; add a mild opening penalty so tight fits in open bins win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If current item is small relative to capacity, opening a bin wastes space.
        score += (bin_capacity - item_size) as f64 * 0.05;
    } else {
        // Reward filling existing bins tightly relative to their own residual.
        score -= (bin_residual - post_residual) as f64 * 0.1;
    }

    // Prefer balanced residual distribution: avoid making this bin's residual deviate far below mean.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let deviation = mean_residual - post_residual as f64;
    if deviation > 0.0 {
        score += deviation * 0.15 * (0.5 + progress);
    }

    // Mild penalty for proliferating bins late in the stream.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is naturally better via base term.
    // Penalize dead space: leftover that cannot fit the next item is wasted.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual as u32) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Slight preference for bins below mean residual (spread load evenly).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Early in the stream, encourage keeping some flexibility (mild new-bin bias);
    // late in the stream, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0;

    // New-bin candidate: only attractive when the item is large relative to
    // capacity (existing bins would leave big dead space) or no tight option exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bin generally; discount penalty when item is large.
        score += 18.0 - 20.0 * fill_ratio;
        // If this is a last-chance situation, opening new bin is fine.
        if fitting_bins_count == 1 {
            score -= 6.0;
        }
    }

    // Small coupling: many open bins -> discourage new bins, encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Tightness reward: strongly favor placements leaving small residuals,
    // amplified non-linearly by stream progress.
    let tightness = 1.0 - post / cap;
    score -= 2.5 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that no realistic item can use (items <= 80):
    // if post_residual is very small but nonzero, it's wasted.
    if post > 0.0 && post < 10.0 {
        score += 6.0 * (10.0 - post) / 10.0;
    }

    // Penalize leaving residuals that exceed the max plausible item size
    // relative to remaining stream length (dead space risk).
    if post > 80.0 {
        score += (post - 80.0) * (1.0 - progress) * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early on and when
    // existing bins have slack; reward it only if it enables a near-perfect
    // future pairing with the lookahead item.
    let is_new_bin = (res - cap).abs() < 1e-9;
    if is_new_bin {
        score += 8.0 + 6.0 * (1.0 - progress);
        if next_item_size > 0 && post >= next_item_size as f64 {
            let pair_fit = 1.0 - (post - next_item_size as f64) / cap;
            score -= 5.0 * pair_fit * pair_fit;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Current placement breaks room for the lookahead item; mild penalty.
        score += 1.5 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Reward leaving room exactly usable by the next item.
        let slack = (post - next_item_size as f64) / cap;
        score -= 2.0 * (1.0 - slack) * (1.0 - slack);
    }

    // Mild pressure to consolidate into fewer bins as many bins accumulate.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Nudge toward bins whose residual is below the mean (compacting bins).
    score += 0.3 * (res - mean_residual) / cap;

    // Small smooth tie-breaker coupling item size and post residual.
    score -= 0.1 * (item / cap) * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let post = post_residual;
    let class = (post % 10) as f64;
    let decile = (post / 10) as f64;

    // Reward small post_residual (tight fit), with modulo-class bonus
    score -= (cap - post as f64) * 0.15;
    score += class * 0.3; // penalize residuals whose last digit is large (awkward class)

    // Perfect or near-perfect fits
    if post == 0 {
        score -= 50.0;
    } else if post <= 5 {
        score -= 20.0;
    }

    // Integer-division thresholds: residual that cannot host the smallest plausible item
    if post < 10 {
        score += 5.0; // dead space class
    }

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // harmonic bonus if next_item_size divides nicely into post_residual
            if post % next_item_size.max(1) == 0 {
                score -= 12.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize more if residual is mid-range
            score += 4.0 + (post as f64 / cap) * 4.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score = cap * 0.6 + fragmentation * 20.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        if fitting_bins_count == 0 {
            score -= cap; // forced new bin
        }
    }

    // Mild preference for bins below mean residual (balance)
    score += ((post as f64 - mean_residual) * 0.05).clamp(-5.0, 5.0);

    // Tie-break: earlier bins slightly favored via open_bins_count pressure
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Archetype: strict dead-space avoidance.
    // Tiny leftover gaps (< 10) are nearly unusable for future items -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Slightly-larger-but-still-awkward gaps get a graded penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit: zero waste -> strong reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead (k=2): reward bins whose leftover gap can still host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If the leftover gap is too small even for the next item, penalize mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: if this is the only open bin that fits, prefer it over
    // opening a new bin (unless it creates severe dead space, handled above).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Open-bins pressure: mild consolidation pressure proportional to the number
    // of active bins, encouraging reuse of existing bins over proliferation.
    score += open_bins_count as f64 * 0.05;

    // Progress-aware nudge: late in the stream, be slightly more tolerant of
    // imperfect fits to avoid spawning bins for few remaining items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: exact fill leaves no dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly accommodates the next item (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // reward small slack after the hypothetical next placement
            let after_next = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize tight residuals that
            // waste space relative to the mean residual of open bins.
            score += 40.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score -= 200.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a brand-new bin when open bins fit reasonably well,
    // unless the fit into existing bins would be very poor.
    if bin_residual == bin_capacity {
        let poor_fit_threshold = bin_capacity as f64 * 0.5;
        if post_residual as f64 >= poor_fit_threshold {
            // opening a new bin is fine for large items
            score -= 60.0;
        } else {
            // discourage new bin when item fits decently elsewhere
            score += 80.0 + (open_bins_count as f64).sqrt() * 10.0;
        }
    }

    // Slight preference for tighter bins overall relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early-stream tie-break: prefer filling bins tightly when few bins open.
    if open_bins_count > 0 {
        score -= 10.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin filled by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Penalize large dead space that few items could use
    if post_residual > 0 && post_residual < 10 {
        score -= 40.0; // nearly-unusable sliver is fine (best-fit style)
    } else if post_residual >= 10 && post_residual < 40 {
        score += 5.0 * (40 - post_residual) as f64 / 30.0; // mild penalty mid-range
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // extra reward if post_residual matches next item nearly exactly
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement blocks the next item from this bin: penalize
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: default to open bins unless it's early,
    // open bins are crowded, or mean residual is too small to matter
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        // opening new bins is more attractive early and when mean residual is low
        score += 80.0 + 50.0 * progress + 4.0 * crowd;
        if mean_residual > item_size as f64 + 20.0 {
            score -= 30.0; // there is still roomy capacity around; avoid new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can absorb the next item too
        }
    }

    // Slight preference for bins with below-mean residual (consolidate waste)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Normalized post-residual and its non-linear polynomial shaping
    let x = pr / cap; // 0..1
    let x2 = x * x;
    let x3 = x2 * x;

    // Base: reward tight fits (small post_residual), with non-linear curvature
    let mut score = 10.0 * x - 6.0 * x2 + 8.0 * x3;

    // Smooth coupling: as stream progresses, tighten tolerance for wasted space
    let tightness = 1.0 + 2.0 * progress;
    score += tightness * (x2 + 0.5 * x3);

    // Penalize bins far below mean residual (fragmentation risk), smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 5.0 + 4.0 * progress;
    }

    // Lookahead coupling: reward leaving room close to next item size (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 4.0 * (-40.0 * diff * diff).exp();
