    // Slight penalty for opening a new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable dead space (dead zone threshold).
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward tight fits relative to bin capacity.
        score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, reward proportional to how well next item fills leftover.
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 - (slack_after_next as f64) * 0.5;
        } else {
            // Next item won't chain; penalize leaving residual just below next item size.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 15.0 * (1.0 - miss / 10.0); // near-miss: painful dead space
            }
            score += 5.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins with residual below mean (tighter bins)
    // to keep large residuals available for large future items.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Late in the stream, consolidate more aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress;

    // If many bins are open, discourage opening new ones (penalize empty-bin candidate lightly).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fits
    if post_residual == 0 {
        score -= 200.0;
    } else {
        let pr = post_residual as f64;
        // Penalize dead space non-linearly: residuals too small for typical items are wasteful
        if pr < 10.0 {
            score += 30.0 * (10.0 - pr) / 10.0;
        }
        // Reward leaving space usable by the next item (lookahead)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0 + 0.25 * next_item_size as f64;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // Penalize blocking the next item with a tiny leftover
            score += 0.4 * (next_item_size as f64 - pr);
        }
    }

    // Reward tight fill ratio of this bin
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 40.0 * fill * fill;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Cheaper to open a new bin early in the stream (long horizon ahead)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // More open bins with large mean residual => avoid adding another
        if mean_residual > 40.0 {
            score += 0.5 * (mean_residual - 40.0);
        }
        score += 2.0 * open_bins_count as f64;
        // If current item is large, new bin is relatively fine; if small, prefer existing bins
        score -= 0.3 * item_size as f64;
    } else {
        // Existing bin: slight preference for bins already below mean residual (balance)
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling: post_residual weighted by stream progress
    score += 40.0 * norm_pr * (0.5 + progress) * (1.0 - fit * 0.5);

    // Smooth penalty for dead space relative to mean residual
    let dead = (pr as f64 - mean_residual) / cap;
    score += 25.0 * dead * dead * (1.0 + progress);

    // Last-chance bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
        if nxt > pr {
            score += 10.0 * progress;
        }
    }

    // Mild penalty for bin proliferation early on
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes (tight fits) are rewarded; large dead-space classes penalized.
    let post_class = post_residual / 10; // integer division threshold classes
    let mod3 = post_residual % 3;
    let mod5 = post_residual % 5;

    // Reward near-perfect fits: post_residual in {0,1,2}
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 2 {
        score -= 18.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Penalize dead-space classes: leftover that no typical item (>=10) can use
    // is pure waste; leftover < 10 is only waste if next item can't use it.
    if post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 5 {
                score -= 10.0;
            }
            // harmonic alignment: next_post divisible by small moduli => chainable
            if next_post % 5 == 0 || next_post % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot fit here; leftover risk depends on class
            score += 6.0 + mod3 as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // New-bin candidate guard: only allow opening a new bin when current bin fit
    // would be terrible (large post_residual class) or bin is nearly full.
    if bin_residual == bin_capacity {
        // A fresh bin has full flexibility; make it attractive unless an open bin
        // achieves a very tight fit (post_residual small).
        if post_residual > 20 {
            score -= 14.0;
        } else {
            score += 10.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Mean-residual context: if this bin's residual is far below mean, it's an outlier
    // worth filling; if far above mean, deprioritize.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild modulo noise on classes to break ties deterministically.
    score += ((post_class as f64) * 0.01) + (mod5 as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual can host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 25.0 + open_bins_count as f64 * 6.0;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the average residual (good fit relative to fleet).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0;
    }

    // 2-step lookahead: perfect match for the next item is highly desirable.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - next).abs();

        if diff < 0.5 {
            // Exact fit for the next item: strong reward.
            score -= 45.0;
        } else if pr >= next {
            // Next item fits, but with slack: mild reward scaled by tightness.
            let tightness = 1.0 - diff / 100.0;
            score -= 20.0 * tightness;
        } else {
            // Next item will NOT fit in the leftover: penalize dead space,
            // worse when the leftover is small (nearly wasted capacity).
            let waste_ratio = 1.0 - pr / next.max(1.0);
            score += 25.0 * waste_ratio;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Prefer bins whose residual is already below average (tighter bins close out).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Prefer filling bins more completely relative to capacity.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Late in the stream, prioritize closing bins (leave small residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty, scaled by capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many fitting bins: mild penalty for wasting a scarce-fit resource is
    // avoided; instead penalize picking a bin among many that fits poorly.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln() * (post_residual as f64) * 0.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how well it fills remainder
            score -= 20.0 * (nxt / pr);
        } else {
            // next item won't fit here: penalize small post residuals that
            // become dead space, more so early in the stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (pr / nxt) * (1.5 - progress) * 10.0;
        }
    }

    // Global state: prefer filling bins when mean residual is high
    // (lots of scattered space) to consolidate.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Penalize opening a new bin when open bins fit and stream is late,
    // unless item is large relative to residual (poor fit anyway).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // New bin cost grows with progress and number of open bins.
        score += 25.0 + progress * 30.0 + open_bins_count as f64 * 2.0;
        // But if the item is huge and would leave big residual anywhere,
        // a fresh bin is attractive: subtract for large items.
        score -= fit_ratio * 40.0;
        // Early in stream, new bins are cheap-ish.
        score -= (1.0 - progress) * 15.0;
    }

    // Mild preference for bins with residual closest above the item
    // (classic best-fit tiebreak already via post_residual, add smoothing).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: reward small post-residual, with smooth polynomial shaping
    let mut score = post * post / cap;

    // Non-linear coupling with stream progress: later in the stream,
    // dead space becomes more costly (bins won't be reused much longer)
    score -= (1.0 - progress) * norm_post * cap * 0.5;
    score += progress * norm_post * norm_post * cap * 0.35;

    // Perfect-fit bonus (smooth via quadratic term)
    if post_residual == 0 {
        score -= cap * 0.8;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * (0.4 + 0.4 * progress);
    }

    // Penalize bins whose residual deviates badly from the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.2;

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit: penalize creating stranded space
        score += norm_post * cap * 0.25 * (0.5 + progress);
    }

    // Discourage opening new bins when many open bins already exist and fit is decent
    if bin_residual == bin_capacity {
        score += cap * 0.6 + open_bins_count as f64 * 0.5;
        // but allow new bin late in stream if mean residual is very tight
        score -= progress * mean_residual * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Small leftovers (tight fits) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows super-linearly for unusable slivers.
    if post_residual > 0 {
        let frac = pr / cap;
        // Harmonic weighting: leftover in (0,10] is nearly dead space.
        if post_residual < 10 {
            score += 60.0 * (1.0 - frac);
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            score -= 6.0; // generous leftover can still host future items
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Lookahead: does next_item_size fit exactly into the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chained fill
        } else if next_item_size <= post_residual {
            // Modular harmony: leftover after the next item also matters.
            let r2 = post_residual - next_item_size;
            score -= 12.0 - (r2 as f64) * 0.15;
        } else {
            // Next item cannot use this bin's leftover; penalize by the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Mild pressure to consolidate early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // New-bin candidate: only attractive when current leftovers are all poor.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count.max(1) as f64;
        let poor_leftovers = if mean_residual < 25.0 { 1.0 } else { 0.0 };
        score += 15.0 - poor_leftovers * 25.0 + open_f * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Penalize small-but-unusable gaps harder than large gaps (dead space is superlinear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (item_size as f64 + post_residual as f64) * 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // (open_bins_count pressure) and when the item fits comfortably elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 3.0;
        // But if no open bin fits well, new bin becomes attractive:
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early stream: allow opening bins to build diversity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Mild preference for bins below mean residual (consolidate space).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post >= nxt {
            let match_err = (post - nxt).abs();
            // Reward closeness of post_residual to next item size
            score -= (1.0 - match_err / bin_capacity as f64) * 15.0;
            // Perfect chain: post_residual exactly equals next item size
            if post == nxt {
                score -= 10.0;
            }
        } else {
            // Post residual too small for next item: dead space penalty
            score += (nxt - post) * 0.5;
        }
    }

    // Relative to mean residual: prefer bins that leave residuals near the mean
    // (keeps residual distribution balanced, avoids fragmenting outliers)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity {
        // New bin candidate: only attractive if no good fit exists
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Discourage new bin if existing bins can fit, especially tightly
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += 10.0 + tightness * 30.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    // Slight preference for filling fuller bins (waste minimization)
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 heuristic: below ~15).
    if post_residual > 0 && post_residual < 15 {
        score += 30.0; // unusable sliver
    } else if post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.4;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 3.0;
        }
    }

    // New-bin candidate handling: empty bin gets baseline score; discourage opening
    // new bins when decent fits exist, encourage when residual is fragmented.
    if bin_residual == bin_capacity {
        // baseline: slightly above a perfect fit, below a bad fit
        score = 45.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0; // big next item: fresh bin is attractive
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        let consolidation = (bin_residual as f64 - mean_residual).abs();
        score += consolidation * 0.15;
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Time horizon: early in stream, be conservative (favor good fits for future);
    // late in stream, just fill bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= post_residual as f64 * 0.3; // fill remaining space late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (0..1)
    let pr = post_residual as f64 / cap;

    // Smooth non-linear coupling: waste pressure grows as stream progresses.
    // Early on, spreading items across bins is fine; late, tight fits matter.
    let waste_pressure = pr * pr * (0.5 + 2.0 * progress);
    score += 8.0 * waste_pressure;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64 + 1.0);
    score -= 6.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx as u32) <= post_residual {
            let fill = nx / cap;
            score -= 5.0 * fill * (1.0 - fill) * 4.0;
        } else {
            // Penalize leaving residual that next item cannot use, scaled by progress
            score += 3.0 * (nx - post_residual as f64) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist,
    // but allow it early or when open bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = if cap > 0.0 { mean_residual / cap } else { 0.0 };
        let open_bins_f = open_bins_count as f64;
        // New bin is attractive when existing bins are fragmented or few exist.
        let new_bin_bonus = 10.0
            - 14.0 * fragmentation
            - 4.0 * (1.0 - progress);
        score += new_bin_bonus.max(-20.0).min(20.0);
        // Mild penalty per open bin to consolidate early.
        score += 0.3 * open_bins_f * (1.0 - progress);
    } else {
        // Existing bin: slight reward relative to mean residual (prefer fuller bins).
        score -= 2.0 * (mean_residual - bin_residual as f64) / cap;
    }

    // Smooth sinusoidal modulation to break ties by exact residual value.
    score += 0.5 * (pr * std::f64::consts::PI).sin() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Quantize post_residual into harmonic buckets; prefer residuals that
        // align with common item sizes (multiples of 10 are re-usable).
        let class = post_residual / 10;
        score -= 8.0 * (class % 2) as f64; // odd tens slightly worse than even
    }

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0; // chain placement possible
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Harmonic modulo coupling between next item and residual class
        if post_residual > 0 && (next_item_size % 20) <= (post_residual % 20) {
            score -= 5.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are awful.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    } else {
        // Prefer fuller bins: reward closeness to capacity.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 12.0 * fill;
    }

    // Progression: later in stream, be greedier about filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation.
    if open_bins_count > 4 {
        score -= 2.0 * open_bins_count.min(20) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are nearly useless.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 11.0);
    } else if post_residual > 10 && post_residual <= 25 {
        // Medium gaps: moderate penalty scaled by how far below the useful threshold they are.
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits strongly (perfect fit gets a big discount).
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 25.0 * tightness * tightness;
    }

    // Lookahead coupling: if the next item exactly fits the post-residual, favor this bin.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to how well it fills the gap.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the residual: penalize dead space creation.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Mean-residual coupling: if this bin's residual is far below the mean, it's a
    // "cramped" bin — prefer filling it rather than leaving it as clutter.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.15 * diff.min(50.0);
    } else {
        score += 0.10 * (-diff).min(50.0);
    }

    // Late-stream consolidation: as the stream progresses, prefer tighter packing
    // and avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; allow early on.
        score += 25.0 + 45.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (post_residual close to 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        // dead-space penalty grows superlinearly for small residuals
        if pr < 20.0 {
            score -= 60.0 * (20.0 - pr) / 20.0; // small residual is good
        }
        // penalize residuals that are too small to ever be useful (< 10 min item)
        if pr > 0 && pr < 10.0 {
            score += 80.0;
        }
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if nxt <= pr {
            // next item fits: reward tight coupling
            score -= 40.0 * (1.0 - diff / 100.0);
            if diff < 1.0 {
                score -= 120.0; // perfect chaining
            }
        } else {
            // next item does NOT fit in leftover: mild penalty scaled by gap
            score += 10.0 * ((nxt - pr) / 100.0);
        }
        // also compare against mean residual structure
        if nxt <= mean_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive if no tight fit exists;
        // give it a neutral-to-slightly-high score so tight fits win
        score += 25.0;
        // but if item is large and would leave tiny residual elsewhere,
        // empty bin still loses due to subtracted bonuses above
        if post_residual == 0 {
            score -= 1000.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    if open_bins_count > 4 {
        score -= 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Late in stream: be greedier, avoid opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 6.0 * (slack_after_next as f64) / (bin_capacity as f64);
        } else {
            score += 3.0; // next item won't fit here after this placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidation (favor filling existing bins).
    let crowding = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0) * 0.05);
    score += 4.0 * crowding * (post_residual as f64) / (bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far above mean, filling it
    // is valuable (it holds the most slack); penalize leaving big residual there.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * (post_residual as f64) / (bin_capacity as f64);

    // Time horizon: early in stream, keep bins open and balanced; late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= 5.0 * tightness;
    } else {
        score += 2.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin gives a good fit or when open bins are nearly exhausted of space.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity - item_size) > 0;
        let avg_open_slack = mean_residual;
        if fitting_bins_count == 0 || avg_open_slack < item_size as f64 * 0.5 {
            score -= 10.0; // open new bin when open bins are poor
        } else if good_fit_exists {
            score += 20.0; // discourage new bin when decent fits exist
        }
        // Late stream: prefer squeezing into existing bins.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: post residual (waste), modulated smoothly by stream progress
    let mut score = post * (0.7 + 0.9 * progress);

    // Non-linear polynomial coupling: quadratic/cubic penalty on normalized post residual
    let poly = post_norm * post_norm * (1.0 + 2.0 * post_norm) * (1.0 + progress);
    score += 25.0 * poly;

    // Reward near-perfect fits smoothly (post close to 0)
    let tightness = 1.0 - post_norm;
    score -= 15.0 * tightness * tightness * tightness;

    // Lookahead coupling: penalize if post residual can't fit next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap) * (1.0 + progress);
        } else {
            let gap = (nxt - post) / cap;
            score += 12.0 * gap * gap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // Mean residual coupling: penalize bins deviating far below mean (fragmentation)
    let dev = (mean_residual - post) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a bin when others fit, more so early
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Smooth occupancy reward: bigger fill fraction of the bin is good
    let fill = (cap - post) / cap;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals that are multiples of common item sizes are more reusable.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0f64;
    if pr == 0 {
        harmonic_bonus -= 60.0; // perfect fit, best outcome
    } else if pr < 10 {
        harmonic_bonus += 25.0; // dead space below minimum item size
    } else {
        // modulo arithmetic: residual divisible by common size classes
        let classes: [u32; 6] = [10, 20, 25, 40, 50, 80];
        let mut div_count = 0;
        for c in classes.iter() {
            if pr % c == 0 {
                div_count += 1;
            }
        }
        harmonic_bonus -= 8.0 * div_count as f64;
        // integer division thresholds on post_residual
        let tier = pr / 10; // 0..10
        harmonic_bonus -= match tier {
            0 => 2.0,
            1 => 4.0,
            2 => 5.0,
            3 => 3.0,
            4 => 6.0,
            _ => 0.0,
        } as f64;
        // capacity fraction coupling: residual as fraction of capacity
        let frac = pr as f64 / bin_capacity as f64;
        if (frac - 0.5).abs() < 0.05 {
            harmonic_bonus -= 6.0; // half-full leftovers pair well with ~50 items
        }
    }
    score += harmonic_bonus;

    // Lookahead: reward leaving room for the next item exactly (harmonic match)
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr > next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.5; // next item won't fit here
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // penalize opening a new bin generally; relax for large items
        score += 45.0 - 40.0 * tightness;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0; // fresh bin can also take the next item
        }
    }

    // Stream progression: as stream advances, prefer filling existing bins tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Many open bins: discourage spreading, reward consolidation into fuller bins
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps too small for the lookahead item (dead space for known future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits.
    score -= 2.0 * item_size as f64 / bin_capacity as f64;

    // Open-bin pressure: penalize placements in bins when many bins are open,
    // encouraging consolidation... but reward consolidation when few bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual close to mean (balanced packing).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Reward when this bin can also fit the next item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits after this placement; reward proportionally to how well
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item would not fit here after placement; penalize large leftovers
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(100.0);
        }
    }

    // Penalize leaving dead space that nothing small could use (post_residual < 10 is hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins with residual above mean (tighter bins get used first)
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only choose a new bin when no open bin gives a good fit
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin, softened if few bins open or stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 180.0 - 60.0 * (1.0 - progress) - (open_bins_count.min(10) as f64) * 2.0;
        // still allow new bin if next item is large and current item is small (avoid fragmenting)
        if next_item_size > 0 && next_item_size > item_size && item_size <= 30 {
            score -= 40.0;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual dominates).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Dead-space penalty: leftover space too small for the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Bonus when the leftover can host the lookahead item.
            score -= 2.5 * (post_residual as f64 / next_item_size.max(1) as f64).min(2.0);
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize new-bin candidate mildly; more so late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 9.0 + 6.0 * progress;
        if fitting_bins_count > 0 && (bin_residual - item_size) < next_item_size.max(1) {
            score += 4.0;
        }
    }

    // Prefer bins below mean residual (spread load evenly among large leftovers).
    score += 0.08 * (post_residual as f64 - mean_residual);

    // Slight preference for fuller bins as stream progresses.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 3.0 * fill * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 0.5 * t * t;
    score *= poly;

    // Penalize large dead space scaled by item size fraction
    let dead = (post / cap) * (post / cap) * cap * 0.5;
    score += dead * (0.5 + 0.5 * t);

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tight = (cap - post) / cap;
    score -= 6.0 * tight * tight * (0.3 + 0.7 * t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - post / cap);
    }

    // Lookahead: reward if next item fits post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - post / cap);
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo classes
    let post = post_residual;
    let class = post % 10; // coarse harmonic class
    let div = post / 10;   // integer division tier

    // Penalize dead space that is too small to ever be useful again
    // (residuals < 10 are pure waste; residuals in [10,30] are semi-usable)
    if post > 0 && post < 10 {
        score += 40.0 - 2.0 * post as f64; // tiny unusable slivers are bad
    } else if post >= 10 && post < 30 {
        score += 8.0 - 0.25 * post as f64;
    }

    // Reward near-perfect fits: post_residual in a "sweet spot" class
    if post == 0 {
        score -= 100.0;
    } else if post <= 5 {
        score -= 50.0;
    }

    // Harmonic coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 90.0;
        } else if next_item_size < post {
            let slack = post - next_item_size;
            // reward proportionally, but penalize if slack becomes a dead sliver
            score -= 30.0 * (1.0 - slack as f64 / 40.0).max(0.0);
            if slack < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to overshoot class
            let over = (next_item_size - post) / 10;
            score += 2.0 + over as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, adjusted by stream phase
    if bin_residual == bin_capacity {
        // opening a new bin is more attractive early (many items remain)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 20.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 60.0; // next item needs a fresh bin anyway
        }
        return score;
    }

    // Prefer bins whose residual is harmonically aligned with mean residual
    let dev = (post as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Modulo-class tie-breaking: bins whose post residual falls in "round"
    // classes (multiples of 10) are more reusable
    score -= (10 - class) as f64 * 0.3;
    score += div as f64 * 0.5; // larger absolute residual: mild penalty

    // Crowding: with many open bins, prefer tightening existing ones
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residual below smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0;
    } else if post_residual < 50 {
        score += (50.0 - post_residual as f64) * 0.6;
    }

