    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use leftover: mild penalty scaled by wasted space
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer fuller bins relative to global mean residual.
    score += 2.0 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be pickier (penalize loose fits more);
    // late in stream, just close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // If many bins are open, encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 1.5 * (open_bins_count as f64).ln();
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let x = r / c; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit), with smooth non-linear shaping.
    let mut score = r;

    // Non-linear polynomial coupling: penalize large residual more aggressively
    // as the stream progresses (dead space matters more later).
    let progress_weight = 0.5 + t;
    score += progress_weight * 40.0 * x * x * x;

    // Reward near-perfect fits smoothly (small residual bonus, quadratic decay).
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement smoothly; otherwise penalize mildly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= r {
            score -= 15.0 * (1.0 - n / r.max(1.0));
        } else {
            score += 8.0 * ((n - r) / c);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 + t);
    }

    // New-bin candidate: smooth penalty so a fresh bin is chosen only when
    // existing placements would leave very awkward residuals.
    if bin_residual == bin_capacity {
        score += 20.0 + 60.0 * (1.0 - t) * x * x;
    }

    // Coupling with mean residual: bins far from the mean get a gentle
    // polynomial repulsion, encouraging residual homogenization.
    let dev = (r - mean_residual) / c;
    score += 10.0 * dev * dev;

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.3 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals in "dead zones" that few item sizes (1..100) can fill exactly.
    // Small residuals (<10) are nearly dead space; large residuals are useful.
    if post_residual < 10 {
        score += 40.0 * (10.0 - pr);
    } else if post_residual <= 25 {
        score += 8.0; // awkward band: only small items fit
    } else if post_residual <= 40 {
        score += 2.0;
    }

    // Reward near-exact fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Harmonic modulo logic: residual divisible by common item sizes is reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic class of the leftover after the next item
            let next_left = (post_residual - next_item_size) % 10;
            score -= 25.0 - 0.6 * slack - next_left as f64;
        } else {
            // next item won't fit here; penalize more if this bin was the only fitting one
            score += 5.0;
        }
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 15.0 * (fill_ratio - 0.9) * 10.0;
    } else if fill_ratio > 0.7 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // but if existing bins are highly fragmented (low mean residual relative to item),
        // opening a new bin is reasonable
        let fragmentation = (mean_residual - item_size as f64) / cap;
        if fragmentation < 0.0 {
            score -= 20.0 + (-fragmentation) * 30.0;
        }
        // early in stream, new bins are cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if next item is large and bins are fragmented, new bin helps
        if next_item_size >= 50 && mean_residual < 40.0 {
            score -= 15.0;
        }
    }

    // Mild penalty for many open bins (consolidation pressure)
    score += 0.15 * open_bins_count as f64;

    // Slight preference to keep mean residual balanced
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

