    // Reward tight fills: fraction of the item's own size relative to bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: bonus if the post-residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that blocks the next item while a smaller gap would do.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // mean residual is already large; encourage consolidation.
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score += 0.05 * pressure;

    // Early in the stream, opening bins is cheaper; late, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
