    score += open_bins_count as f64 * 0.3;

    // Prefer placing large items into bins with proportionally small residual.
    if bin_residual > 0 {
        let waste = (bin_residual - item_size) as f64;
        score += waste * waste / (bin_capacity as f64 * bin_capacity as f64) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
