        let slack = pr - n;
        if slack >= 0.0 {
            let fit_quality = 1.0 - (slack / cap);
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            score += 6.0 * (-slack / cap);
        }
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild preference for fuller bins relative to the fleet mean
    score -= 3.0 * (mean_residual - pr) / cap;

    // Crowding: slightly prefer opening new bins when many bins are open and progress is early
    score += 0.05 * (open_bins_count as f64) * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands
    let post = post_residual as f64;
    let class = (post_residual * 4) / bin_capacity; // 0..3 harmonic quartile class
    match class {
        0 => score -= 12.0,                       // tiny dead space: excellent fit
        1 => score += 2.0,                        // quarter band: mediocre
        2 => score += 5.0,                        // half band
        _ => score += 9.0,                        // large leftover: wasteful
    }

    // Modulo arithmetic: post_residual mod 10 (small-slot harmony)
    let m = post_residual % 10;
    if m == 0 { score -= 6.0; }                  // residual divisible into 10-slots
    else if m <= 3 { score -= 1.5; }             // near-divisible
    else { score += (m as f64) * 0.4; }          // ragged leftover penalty

    // Next item lookahead via its harmonic class (integer division by 25)
    if next_item_size > 0 {
        let nclass = next_item_size / 25;
        let fits_next = next_item_size <= post_residual;
        match nclass {
            0 => { if fits_next { score -= 4.0; } else { score += 3.0; } } // small next: keep flexible bins
            1 => { if fits_next { score -= 6.0; } else { score += 2.0; } }
            2 => { if fits_next { score -= 3.0; } else { score += 5.0; } } // big next: prefer tight fit now
            _ => { if fits_next { score -= 1.0; } else { score += 7.0; } }
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }
    if fitting_bins_count > 3 { score += 1.5; }  // plenty of alternatives: be picky

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Only open a new bin when current bin would leave bad dead space
        let dead = post / cap;
        if dead > 0.45 && open_bins_count > 2 { score -= 8.0; }
        else { score += 10.0; }
    }

    // Mean residual coupling: discourage diverging from fleet average
    let dev = (post - mean_residual).abs();
    score += dev * 0.15;

    // Progress-based tightening: late in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual below 10 is nearly useless)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 5.0 + (open_bins_count as f64) * 0.5;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item almost fits but not quite (creates near-dead space)
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(3) && post_residual < next_item_size {
        score += 10.0;
    }

    // Slight preference for bins below mean residual (balance residuals)
    if !is_new_bin {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if next item fits into the post residual,
    // reward heavily; if it doesn't, penalize proportionally to leftover waste.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item chains perfectly: reward matching residual to next size.
            score -= 150.0 + (post_residual as f64 - nxt).max(0.0) * 0.5;
        } else {
            // Dead space that next item cannot use.
            score += (post_residual as f64 - (post_residual as f64 - nxt).abs()) * 0.0;
            score += post_residual as f64 * 0.8 + 20.0;
        }
    }

    // Compare against mean residual: prefer bins whose post residual is near
    // the mean (balanced packing) when mean residual is small.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    if mean_residual < 25.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the item is huge relative to residuals elsewhere.
    if bin_residual == bin_capacity {
        let bad_fit = pr > 40.0 || (next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && fitting_bins_count <= 1);
        if bad_fit {
            score -= 30.0;
        } else {
            score += 60.0;
        }
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mild preference for tighter bins (smaller residual before placement).
    score += bin_residual as f64 * 0.05;

    // Slight penalty when many bins are open (consolidation pressure).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual) with a non-linear term.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot host the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else {
            // Reward bins whose residual can still host the next item.
            score -= 8.0;
        }
    } else {
        // Near the end of the stream: fill bins aggressively.
        score -= 15.0;
    }

    // Last-chance bin: strong bonus to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make opening a new bin moderately costly,
    // but attractive when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Cost of a new bin shrinks late in the stream or when mean residual is low.
        let new_bin_cost = 60.0 - 30.0 * progress - 40.0 * (1.0 - avg_pressure);
        score = 100.0 + new_bin_cost.max(5.0);
    }

    // Mild preference for fuller bins when many bins are open (consolidation).
    score -= (open_bins_count as f64).ln() * (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Small penalty for very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // base: prefer tight fits (small post_residual)
    let mut score = pr;

    // non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 + t) * 60.0 + prn * t * t * 40.0;
    score += poly;

    // dead-space penalty grows with progress
    score += (prn - 0.5).abs() * (1.0 + t) * 25.0;

    // last-chance bonus: subtract to strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 45.0 + 30.0 * t;
    }

    // lookahead: reward bins that can still fit the next item after placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 10.0 * t;
        } else {
            score += 8.0 * prn * (1.0 - t);
        }
    }

    // crowd penalty when many bins are open and residual is above mean
    score += ((pr - mean_residual) / cap) * (open_bins_count as f64).sqrt() * 6.0;

    // new-bin candidate: penalize mildly early, more when existing bins fit poorly
    score += is_new * (15.0 + 35.0 * t - (fitting_bins_count as f64) * 5.0).max(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction buckets
    let item_class = item_size / (bin_capacity / 4); // 0..3 (small, medium, large, huge)
    let next_class = next_item_size / (bin_capacity / 4);

    // Reward tight fits: small post_residual is good
    if post_residual > 0 && post_residual < (bin_capacity / 10) {
        score -= 6.0;
    }

    // Penalize dead space that only a small item could fill
    if post_residual >= 1 && post_residual < 10 {
        score += 2.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = post_residual - next_item_size;
        // Perfect harmonic match: next item exactly fills the bin
        if leftover == 0 {
            score -= 12.0;
        } else if leftover < (bin_capacity / 10) {
            score -= 7.0;
        } else {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty, scaled by how big it is
        score += (next_item_size as f64) * 0.05;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item classes (10, 20, 25, 50) are more reusable
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 3.0;
    }

    // Integer-division threshold: residual in a "useful band" for medium items
    let band = r / 10; // 0..10
    if band >= 3 && band <= 5 {
        score -= 1.5; // 30..59 residual: fits most medium items
    } else if band < 3 && r > 0 {
        score += 1.0; // tiny sliver, likely dead space
    }

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: neutral baseline; open a fresh bin only when
    // existing bins are fragmented or the item is huge
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap_f;
        // New bin is attractive if open bins are nearly full on average
        score = cap_f * 0.55 - fragmentation * cap_f * 0.5 - (item_class as f64) * 3.0 + progress * 2.0;
        // But if there's a perfect harmonic match somewhere, prefer it
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0;
        }
        if fitting_bins_count == 1 {
            score += 15.0; // strongly prefer using the last fitting bin
        }
    }

    // Coupling with mean residual: prefer bins below mean (balance residuals)
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.15;
    } else {
        score += (bin_res_f - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    if post_residual == 0 {
        score -= 80.0; // perfect fit
    }

    // Prefer bins whose residual was close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Pressure from number of open bins: discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        // Allow new bin only if it enables a good next-item fit.
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 15.0;
        }
    } else {
        // Last-chance bin gets a strong discount.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Favor bins with below-mean residual (more filled).
        score -= (mean_residual - bin_residual as f64) * 0.3;
        // Lookahead: reward if next item fits the resulting gap.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post-residual exactly matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if next <= post {
            // Next item fits after this placement: reward tight chains.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain match is highly desirable.
            if gap == 0.0 { score -= 25.0; }
        } else {
            // Next item will NOT fit: penalize leaving awkward leftover space.
            score += 8.0 + 0.25 * (next - post).min(40.0) as f64;
        }
    }

    // Tightness reward: prefer bins that become nearly full after placement.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Relative-to-mean coupling: avoid wasting large residuals on small items
    // when other bins hold more slack (and vice versa).
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a fresh bin costly unless the item is
    // huge relative to capacity (poor fit elsewhere justifies a new bin).
    if bin_residual == bin_capacity {
        score += 30.0 - 0.2 * item_size as f64;
        // If lookahead also matches an empty bin well, soften slightly.
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 3.0 {
            score -= 10.0;
        }
    }

    // Early-stream exploration: slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    // Small deterministic tiebreak favoring larger items into tighter bins.
    score += 0.01 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing (including lookahead) can use.
    if post_residual > 0 {
        let min_useful = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
        if (post_residual as u32) < min_useful.min(10).max(1) {
            score += 6.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins unless residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (cap - item_size as f64)).abs();
        // open a new bin when open bins are full-ish (mean residual small) or early stream
        let open_bias = if mean_residual < item_size as f64 * 1.2 { -10.0 } else { 15.0 + fragmentation * 0.3 };
        score += open_bias + 5.0 * (1.0 - progress);
        // never open a new bin if this bin would fit perfectly
        if post_residual == 0 { score += 40.0; }
    } else {
        // Mild penalty for spreading across many open bins
        score += 0.4 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to mean (balance), scaled by progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic penalty on post_residual (dead space), scaled by stream progress
    let mut score = x * x * (1.0 + 2.0 * progress) * cap;

    // Smooth cubic interaction: post_residual vs progress — early stream tolerates slack,
    // late stream strongly punishes it (polynomial coupling, no piecewise constants)
    score += (x - 0.5) * (x - 0.5) * (x - 0.5) * cap * (progress - 0.5) * 4.0;

    // Reward tight fits (small post_residual) more when next item may reuse the space
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        score -= (x - nx).abs() * cap * 0.5 * (1.0 - progress);
        if (x - nx).abs() < 0.05 {
            score -= 8.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty proportional to open bins count to discourage fragmentation
    score += open_bins_count as f64 * 0.05;

    // Discourage bins whose residual deviates strongly from mean residual (waste coupling)
    score += (pr - mean_residual).abs() * 0.1;

    // Slight nudge so a truly perfect fit (post_residual == 0) wins outright
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction class does
    // the post residual fall into? Leftovers in "dead" classes (very small,
    // unusable slivers) should be penalized; leftovers that are still usable
    // by typical items (>= 10) should be favored.
    let pr = post_residual;
    let class = pr / 10; // integer division: harmonic class 0..10
    match class {
        0 => score += 40.0,                      // dead sliver, nearly useless
        1 => score += 18.0,                      // barely usable
        2 => score += 8.0,
        3 => score -= 2.0,                       // sweet spot: fits mid items
        4 => score -= 5.0,
        5 => score -= 4.0,
        6 => score -= 1.0,
        _ => {}                                  // near-empty bin, neutral
    }

    // Exact fit is perfect.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead harmony: if the next item fits exactly into the post residual,
    // strongly reward this pairing (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // soft reward scaled by how snugly the next item fits
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional
            // to how much of the leftover is wasted relative to next item
            score += 6.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last chance: if this is the only bin that can fit the item, avoid opening
    // a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when no
    // open bin offers a decent fit. Penalize opening a new bin unless the
    // current item is large relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let item_frac = item_size as f64 / cap;
        // baseline: empty bin is worse than any reasonable existing fit
        score += 55.0;
        // but relax if item is big, stream is early, or bins are crowded
        score -= 30.0 * item_frac * (1.0 - progress) + 25.0 * crowding;
    }

    // Prefer tighter bins overall: compare residual to the mean residual of
    // open bins; choosing a bin below mean residual is a tight fit.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference to fill bins that are already more than half full
    // (encourage closing bins out).
    let fill = 1.0 - bin_residual as f64 / cap;
    if fill > 0.5 {
        score -= 10.0 * (fill - 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps below minimum item size 1..threshold)
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open
        score += 15.0 * bin_pressure * (0.5 + progress);
    } else {
        // Slight reward for using existing bins as open count grows
        score -= 2.0 * bin_pressure * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 2 {
            score -= 20.0;
        } else {
            score -= (gap as f64).ln() * 3.0;
        }
    }

    // Prefer bins tighter than the mean residual (good packing)
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Strong reward for perfect two-item packing (post_residual == next_item_size)
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).powi(8);
    } else if next_item_size > 0 {
        // Penalize bins that leave post_residual too small for the next item (dead space)
        let overshoot = (next_item_size - post_residual) as f64;
        if post_residual < next_item_size {
            score += 6.0 * (overshoot / item_size.max(1) as f64).sqrt();
        }
    }

    // Prefer tight fits relative to mean residual
    let mean_res = mean_residual.max(1.0);
    if (post_residual as f64) < mean_res {
        score -= 4.0 * (mean_res - post_residual as f64) / mean_res;
    } else {
        score += 2.0 * ((post_residual as f64) - mean_res) / mean_res;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // New bin gets penalized more when open bins still have usable space
        score += 20.0 + 25.0 * fragmentation + 10.0 * (1.0 - progress);
        // But if next item pairs perfectly with a fresh bin residual, soften slightly
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Mild preference for filling nearly-full bins
    score -= 3.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 -> use 10 as typical floor).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        score += 15.0 + 10.0 * open_bins_count as f64 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 40.0 * poor_fit;
        }
    }

    // Prefer bins below mean residual early (keep big bins flexible), above later.
    let dev = bin_residual as f64 - mean_residual;
    if progress < 0.5 {
        score += 0.05 * dev;
    } else {
        score -= 0.05 * dev;
    }

    // Mild consolidation pressure when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: tight fit reward via smooth polynomial in normalized post-residual
    let mut score = 2.0 * norm_post * norm_post + 1.5 * norm_post;

    // Non-linear coupling of post-residual with stream progress:
    // later in the stream, dead space is more costly -> superlinear penalty
    let progress_coupling = norm_post * norm_post * (progress * progress) * 3.0
        + norm_post * progress * 1.0;
    score += progress_coupling;

    // Reward filling a bin deeply, scaled by how full the stream is
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * progress;
    }

    // Lookahead: penalize if post-residual can't fit the next item but almost could
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post as u32 >= next_item_size {
            // good: next item still fits -> reward proportional to usability
            let usable = (post / next).min(3.0);
            score -= 0.3 * (usable.ln() + 1.0) * (1.0 - progress);
        } else {
            // bad: dead space for the next item -> smooth penalty near the boundary
            let gap = (next - post) / cap;
            score += 1.0 * gap * (1.0 - gap) * (1.0 + progress);
        }
    }

    // Penalize bins deviating from mean residual (fragmentation control)
    let dev = (post - mean_residual) / cap;
    score += 0.4 * dev * dev;

    // Mild penalty for proliferating open bins late in the stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: neutral baseline slightly above a good fit
    if bin_residual == bin_capacity {
        score += 1.2 + 0.8 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls in
    // "awkward" residue classes modulo common item sizes (1..100 stream).
    let pr = post_residual;
    // Perfect fit: strongly reward.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals that are too small to hold any plausible item
        // (min size 1, but tiny slivers are dead weight).
        if pr < 10 {
            score += (10 - pr) as f64 * 8.0;
        }
        // Harmonic divisibility bonus: residuals divisible by common item
        // classes (10, 20, 25, 50) are more reusable.
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                bonus += 15.0;
            }
        }
        // Residual that exactly matches a plausible next item size is gold.
        if next_item_size > 0 && pr == next_item_size {
            bonus += 60.0;
        } else if next_item_size > 0 && pr >= next_item_size {
            // Could fit the lookahead item: mild reward proportional to slack.
            bonus += (pr - next_item_size).min(30) as f64 * 0.5;
        } else {
            // Lookahead cannot fit here: penalize proportionally to mismatch.
            bonus -= (next_item_size - pr).min(50) as f64 * 1.5;
        }
        // Integer-division threshold: residuals in [0..10] are near-dead,
        // [10..30] medium, >=30 still flexible.
        let band = pr / 30;
        bonus -= band as f64 * 5.0; // larger residuals slightly favored via band
        // Last-chance bin: strongly prefer using it before opening new bins.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            bonus -= 80.0;
        }
        // New-bin candidate: only attractive when current bins fit poorly.
        if bin_residual == bin_capacity {
            let tight = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
            // Opening a new bin is penalized; less so if item is large and
            // would leave big post_residual in existing bins.
            let waste = (pr as f64 - tight * 0.5).max(0.0);
            bonus += 120.0 + waste * 0.3 + (open_bins_count as f64) * 2.0;
        }
        score += bonus;
    }

    // Mild preference for tighter (smaller-residual) bins overall.
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;
    // Slight tie-break toward bins that keep mean residual balanced.
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (1.0 - pr / 10.0); // dead space zone
        } else if pr < 20.0 {
            score += 25.0 * (1.0 - (pr - 10.0) / 10.0);
        }
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose residual is exactly consumed by this item plus lookahead.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 12.0 + 0.8 * open_bins_count as f64;
        score += base;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else if post_residual >= 40 {
            score -= 15.0; // large item into fresh bin is fine
        }
    }

    // Slight preference for tighter (smaller-residual) bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mean residual coupling: when open bins are already loose, be pickier about waste.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Strong reward for a two-item perfect fill.
        score -= 30.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        // Extra bonus if next item fills bin almost completely after both placements.
        if slack_after_next <= 5 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportional to wasted lookahead opportunity.
        let overflow = (next_item_size - post_residual) as f64;
        score += 0.15 * overflow;
    }

    // Penalize dead space that no plausible item (min size 1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Prefer tight fits relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when current open
    // bins would leave large post residuals (poor fits) or few fitting options.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > mean_residual * 0.9;
        if poor_fit || fitting_bins_count == 0 {
            score -= 40.0; // open a fresh bin instead of fragmenting
        } else {
            score += 35.0; // discourage opening new bins when fits are decent
        }
    }

    // Early in the stream, slightly favor consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Lookahead: reward bins whose post_residual can still hold the next item,
    // penalize bins that leave a dead gap just below next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // wasted sliver that next item cannot use
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.6;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 12.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: only attractive when the current fit is bad
    // or no good residual reuse is possible.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Big item leaving little waste -> fine; small item in fresh bin -> wasteful.
        score += fit_quality * 40.0;
        // As stream matures, discourage proliferating bins unless necessary.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0 + open_bins_count as f64 * 0.5;
        // If many bins already fit the item, opening a new one is clearly worse.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // If the next item is large and this item is small, a fresh bin may be worth it.
        if next_item_size > 60 && item_size < 30 {
            score -= 15.0;
        }
    }

    // Global state coupling: prefer bins with residual near the mean (balanced usage),
    // penalize outliers that hoard space.
    let dev = bin_residual as f64 - mean_residual;
    score += (dev.abs()) * 0.08;

    // Mild penalty for leaving very small unusable residuals (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 - 0.5 * progress) + 2.0 * x * x * (0.5 + progress);

    // Penalize near-full waste more as stream advances (smooth cubic term)
    score += 3.0 * x * x * x * progress;

    // Reward tight fits smoothly: subtract when post_residual is small
    score -= (1.0 - x).powi(3) * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.8 * (1.0 - (next_item_size as f64) / pr.max(1.0));
    } else if next_item_size > 0 {
        score += 0.4 * ((next_item_size as f64) - pr) / cap;
    }

    // Mild penalty scaled by number of open bins to discourage fragmentation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate adjustment: neutral baseline so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 0.6 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residuals divisible by 10 are
    // "harmonic" (easy to fill with typical item sizes); odd/prime-ish remainders
    // create dead space. Penalize non-harmonic residuals.
    let rem10 = (post_residual % 10) as f64;
    score += rem10 * 0.8;

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 5 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Harmonic class via integer division: residuals in [0,20] are hard to reuse.
    let hclass = post_residual / 20;
    score += match hclass {
        0 => 12.0,          // tiny leftover, mostly dead
        1 => 0.0,           // 20..40: moderate
        2 => -6.0,          // 40..60: good reuse potential
        3 => -10.0,         // 60..80: very reusable
        _ => -14.0,         // near-empty bin, very flexible
    };

    // Lookahead coupling: if next item fits harmonically into post_residual,
    // reward strongly; if it almost fits (gap <= 10), mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 200.0;
        } else if gap <= 10 {
            score -= 40.0;
        } else {
            score -= (10.0 - (gap % 10) as f64) * 0.5;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize leftover magnitude
        score += post_residual as f64 * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Compare against mean residual: placing into a bin below the mean reduces
    // fragmentation spread.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Progress-aware pressure: late in the stream, be more conservative with
    // new bins (favor filling existing ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins and progress.
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 40.0;
        // Allow new bin early on or when residual would be tiny harmonic class.
        if post_residual as f64 > mean_residual + 15.0 && progress < 0.5 {
            score -= 45.0;
        }
    } else if open_bins_count > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0 * (10 - pr) as f64; // dead space in [1,9] is wasted capacity
    } else if pr == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward good fits generally: low post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - fit_ratio);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when current bins
    // would leave large dead space or open-bin pressure is low.
    if bin_residual == bin_capacity {
        score = 85.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 100.0; // strongly prefer the existing last-chance bin
        }
        if pr >= 10 && item_size <= 50 {
            score -= 15.0; // roomy placement in a fresh bin for medium items
        }
    }

    // Open-bin pressure: mildly discourage proliferating bins.
    score += 0.4 * open_bins_count as f64;

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if post residual is too small for next item but next item is small
    // (dead space that blocks the future item).
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Stream progression: late in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot use leftover: penalize leftover dead space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Prefer bins whose residual deviates above the mean (consume bulky residuals first).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a new bin unless the current item is huge
    // and would leave a very awkward residual in existing bins.
    if bin_residual == bin_capacity {
        let awkward = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 55.0 - 35.0 * awkward - 0.1 * item_size as f64;
        // Late in the stream, opening fresh bins is less attractive (fewer future pairings).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild pressure against accumulating many open bins with slack.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good via base term.

    // Penalize large post_residual scaled by global slack pressure.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let slack = mean_residual / bin_capacity as f64;
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * (20.0 + 40.0 * slack);

    // Last chance: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 25.0 - (leftover as f64).min(25.0);
        } else {
            // next item cannot follow here; slight penalty
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin is a fallback, prefer it only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 * 0.5;
        if decent_fit_exists && fitting_bins_count > 1 {
            score += 45.0; // discourage opening new bin when fits exist
        } else if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        } else {
            score += 10.0;
        }
        // late in stream, avoid opening bins for small items
        if item_size < 40 && t > 0.7 {
            score += 15.0;
        }
    }

    // Prefer filling bins with larger residual when many bins are open.
    score += (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mild bonus for near-exact fills even if not perfect.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let norm_post = post_residual as f64 / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling: post residual penalized more as stream progresses
    let poly = norm_post * norm_post * (0.5 + progress) + norm_post * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits, more strongly late in stream
    score -= (1.0 - norm_post) * (1.0 + progress) * 10.0;

    // Penalize large item filling bin nearly fully if next item can't use remainder
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 > 0.0 && nxt > post_residual as f64 {
            score += 8.0 * (1.0 - post_residual as f64 / nxt);
        } else {
            score -= 4.0 * (1.0 - norm_post);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Mild penalty when many open bins with high mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * progress;

    // New-bin candidate: keep neutral-ish unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by large chunk sizes
    // are more reusable. Reward (subtract) for low-entropy residual classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual exactly divisible by 10 -> highly reusable slot
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Class 2: post_residual divisible by 25 (quarter/half classes)
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Dead space penalty: tiny residuals that likely can't fit typical items
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fit
    }

    // Integer-division threshold coupling: how well next_item_size fits the
    // harmonic class of post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into this bin's residual class
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            } else {
                score -= 5.0;
            }
            // penalize leaving a new dead zone after the next item
            let nr = post_residual - next_item_size;
            if nr < 10 && nr > 0 {
                score += 8.0;
            }
        } else {
            score += 6.0; // next item won't fit here; residual likely wasted
        }
    }

    // Fractional capacity fill: reward bins whose post-fill occupancy is a
    // "clean" fraction of capacity (>= 3/4 filled)
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill >= 0.75 {
        score -= 7.0 * fill;
    } else if fill < 0.5 {
        score += 4.0 * (0.5 - fill);
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: mildly penalize so we only open when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0 + 0.15 * open_bins_count as f64;
        // but if residual classes of open bins are poor, new bin is fine
        if mean_residual < 20.0 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, be pickier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible item are dead space.
    let dead_threshold = 10.0; // minimum item size is 10 in canonical streams; treat <10 as pure waste
    if (post_residual as f64) < dead_threshold {
        score -= 50.0; // perfect fill: strongly favored
    } else {
        // Penalize gaps that are small but nonzero: unusable dead space.
        let dead = if (post_residual as f64) < 20.0 {
            (20.0 - post_residual as f64) * 2.0
        } else {
            0.0
        };
        score += dead;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.3;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // exact match bonus
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow here; mild penalty scaled by leftover size
        score += (post_residual as f64) * 0.1;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // new bin: base cost plus pressure from open bins count and mean residual
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // if mean residual is large, opening a new bin is wasteful
        score += mean_residual * 0.5;
        // early in stream, new bins are cheaper (exploration)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // if no other bin fits, this is the only option anyway
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // using an existing bin reduces open-bin pressure slightly
        score -= (open_bins_count as f64) * 0.2;
    }

    // Alignment with mean residual: prefer bins whose residual is below average
    // (consolidating space into fewer, fuller bins).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit is better (smaller post_residual).
    // Reward near-perfect fits strongly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= (1.0 - pr / cap) * 20.0;

    // 2-step lookahead: reward when post_residual closely matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item fits: reward closeness of match.
            score -= (1.0 - gap / cap) * 30.0;
            // Chain-fit bonus: both this item and next fill the bin nearly exactly.
            if pr == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize leftover dead space.
            score += gap * 0.5;
            // Tiny unusable residue (<10) is dead space: heavy penalty.
            if post_residual < 10 {
                score += 40.0;
            }
        }
    } else {
        // Last item: maximize fill.
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins whose residual deviates
    // in a useful way (tighter than average is good).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): penalize unless nothing else works well.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Opening a new bin is attractive if current bins have large residuals
        // (fragmentation) and many bins are open.
        score += (open_bins_count as f64).sqrt() * 2.0;
        score += (mean_residual / cap) * 15.0;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 15.0; // wasteful large dead space
    }

    // Relative fill ratio bonus: fuller bins are better.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless item is small relative to capacity
    // or existing bins are all poor fits (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 25.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            penalty -= 60.0; // no alternative: new bin is fine
        }
        // If next item could combine with this one in a fresh bin, mild discount.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity
            && next_item_size as f64 > mean_residual {
            penalty -= 15.0;
        }
        score += penalty;
    }

    // Lookahead synergy: if next item exactly fits the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Slightly prefer bins with residuals below the mean (consolidate small holes).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early in the stream, be more open to spreading items across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothed with a saturating quadratic term
    let mut score = pr + 40.0 * norm_pr * (1.0 - norm_pr);

    // Stream-progress coupling: later in stream, penalize waste more strongly
    let prog_term = progress * progress;
    score += 60.0 * prog_term * norm_pr * norm_pr;

    // Tight fit reward: quadratic in item_size ratio
    let fit_ratio = item_size as f64 / cap;
    score -= 30.0 * fit_ratio * (1.0 - fit_ratio) * (1.0 - progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Penalize bins far from mean residual (fragmentation avoidance)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild penalty for too many open bins
    score += 0.5 * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: keep it competitive only for large items
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod 10 define "dead zones".
    let residue_class = (post_residual % 10) as f64;
    // Penalize leftovers that are not useful harmonic classes (small nonzero remainders).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.5 * residue_class; // worst: leftover 1..9 is nearly unusable
    } else if post_residual >= 10 {
        // Reward leftovers that are multiples of 10 (perfect harmonic alignment).
        if residue_class == 0.0 {
            score -= 6.0;
        } else {
            score += residue_class * 0.4;
        }
        // Reward leftovers that could exactly fit a "harmonic" next item size
        // (next_item_size divisible into post_residual via integer division).
        if next_item_size > 0 && post_residual >= next_item_size {
            let quot = post_residual / next_item_size;
            if post_residual % next_item_size == 0 {
                score -= 8.0 + quot as f64;
            } else {
                score -= quot as f64 * 0.5;
            }
        }
    }

    // Integer-division threshold on post_residual: bins with residual >= 50 are "half-empty",
    // keep them flexible; bins below 50 are closing out, penalize slightly.
    if post_residual >= bin_capacity / 2 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 5.0;
        }
    }

    // Late in the stream, tighten packing (prefer minimal post_residual more strongly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Prefer bins tighter than average (below mean residual => better filled).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

