    // Reward tight fits (small waste relative to item size).
    score -= (item_size as f64) * 0.15;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else {
