            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening a new bin (residual == capacity) is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open,
        // especially late in the stream.
        score += open_bins_count as f64 * 8.0 * (0.5 + progress);
        // A new bin only makes sense for large items that leave big usable gaps.
        score += (item_size as f64) * 0.2;
    } else {
        // Existing bins get a mild advantage, reduced as bins pile up.
        score -= 5.0 - (open_bins_count as f64 * 0.3).min(4.0);
    }

    // Prefer bins whose residual is above the mean (use the big gaps first,
    // keeping tight bins for tight fits).
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
