    // Lookahead: if the next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.08;
        } else {
            // Post-residual too small for next item: dead space penalty grows
            // with how close the next item is to fitting.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.12;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about residual quality.
        score += post_residual as f64 * 0.10;
    }

    // Global state: prefer spreading load when many open bins have large residuals.
    if bin_residual as f64 > mean_residual {
        score -= 2.0; // use the roomier bins first
    } else {
        score += 1.5;
    }

    // Time horizon: early in the stream, favor opening fresh bins for flexibility;
    // later, consolidate aggressively to avoid bin proliferation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 4.0 * open_bins_count as f64 * 0.2;
    score -= t * 3.0;

    // New-bin candidate handling: an empty bin is attractive only when the fit
    // into existing bins would leave large dead space or when bins are crowded.
    if bin_residual == bin_capacity {
        let dead = (post_residual as f64).powf(1.5) * 0.06;
        score += 8.0 + dead - t * 6.0;
        if fitting_bins_count <= 1 {
            score -= 14.0; // no real alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr / cap;
    // reward tight fits more as stream progresses
    score -= (1.0 - (pr / cap).powi(2)) * (0.5 + progress);
    // penalize large dead space non-linearly
    score += (pr / cap).powi(3) * 2.0;
    // lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 0.6 * (1.0 - ((pr - nx) / cap).powi(2));
        } else {
            score += 0.4;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 0.5 * (1.0 - (pr / cap).powi(2));
    }
    // avoid fragmenting bins when many are open and mean residual is high
    score += (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (pr / cap) * (1.0 - progress);
    // new-bin candidate: keep it slightly unattractive unless current fit is bad
    if bin_residual == bin_capacity {
        score += 0.3 + 0.5 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect packing
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 10.0;
    } else {
        // dead-space penalty grows for unusable residuals
        let unusable = (pr as f64).min(30.0);
        score += 0.35 * unusable;
    }

    // Harmonic class via integer division: residuals divisible by common item sizes are reusable
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                reuse_bonus += 6.0;
            }
        }
        if pr >= 10 && pr % 10 == 0 {
            reuse_bonus += 4.0;
        }
        score -= reuse_bonus;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 && pr >= next_item_size {
        score -= 12.0;
        if pr - next_item_size <= 5 {
            score -= 8.0; // chain of tight fits
        }
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 6.0; // dead space for the known next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 55.0;
        // allow new bin late in the stream or when many bins already open and mean residual is fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 20.0 && open_bins_count > 2 {
            score -= 25.0;
        }
        if progress > 0.9 {
            score -= 5.0;
        }
    }

    // Mild preference for fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the smallest possible
    // follow-up item are permanently unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }
    // Small gaps that only the smallest items could use are near-dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 60.0;
    }

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        // or late in the stream.
        score += 25.0 + 8.0 * open_bins_count as f64 + 30.0 * progress;
    } else {
        // Existing bin: reward using it, especially when few alternatives exist.
        score -= 5.0;
        if fitting_bins_count == 1 {
            // Last-chance bin: strongly favor using it to avoid opening a new bin.
            score -= 35.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit in the gap: mild penalty for wasting space.
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (packing into below-average-residual bins keeps large gaps available).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.3 * dev; // negative dev lowers score slightly
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect two-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0;
        } else {
            // penalize mismatch scaled by how far next item is from fitting
            score += diff as f64 * 0.35;
            // slight reward if next item can still fit into post residual
            if post_residual >= next_item_size {
                score -= 8.0;
            } else {
                // dead space for the next item: penalize wasted gap
                score += (post_residual as f64) * 0.25;
            }
        }
    }

    // Reward tight fits relative to current bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Penalize bins whose residual deviates badly from mean residual (keep pool balanced)
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it yields a near-perfect 2-step chain
    if bin_residual == bin_capacity {
        score += 10.0; // default penalty: prefer existing bins
        if next_item_size > 0 {
            let chain = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if chain == 0 {
                score -= 55.0; // perfect two-item packing in a fresh bin
            } else if chain < 0 {
                score -= 5.0;
            }
        }
        // early in stream, opening bins is cheaper
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 6.0;
        }
    }

    // Small penalty for leaving tiny unusable slivers (dead space < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (bin_residual - item_size) as f64 > 0.5 * cap;
        // Prefer new bin when the item leaves a large awkward gap in open bins
        // and many open bins exist (fragmentation pressure).
        let frag_pressure = (open_bins_count as f64).ln().max(0.0);
        if poor_fit {
            score -= 8.0 + 4.0 * frag_pressure * (1.0 - progress);
        } else {
            score += 15.0 + 5.0 * frag_pressure;
        }
        // Early stream: opening bins is cheap; late stream: consolidate.
        score += 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let leftover = post_residual as f64 - nxt;
            if leftover < 5.0 {
                score -= 20.0; // perfect chain fit
            } else {
                score -= 6.0 * (1.0 - leftover / cap);
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Global residual balance: prefer bins below mean residual (fill emptier-relative bins less).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev;

    // Mild pressure to use existing bins as open bin count grows.
    score += 0.3 * open_bins_count as f64 * (is_new_bin as i32 as f64);

    // Prefer bins whose residual is close to item size (minimal waste ratio).
    if bin_residual >= item_size {
        let waste_ratio = (bin_residual - item_size) as f64 / bin_residual as f64;
        score += 10.0 * waste_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate larger leftovers; late, punish them harder.
    let post_norm = post / cap;
    let progress_coupling = post_norm * (1.0 + 2.0 * progress * post_norm);
    score += 1.5 * progress_coupling;

    // Quadratic dead-space penalty (smooth, non-piecewise).
    score += 0.02 * post_norm * post_norm * cap;

    // Reward tight fits (post_residual near zero) with a smooth bowl.
    score -= 12.0 * (-2.0 * post_norm * post_norm).exp();

    // Last-chance bin: strong smooth bonus to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: penalize if next item cannot fit the post-residual (smooth term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 10.0 * gap + 5.0 * gap * gap;
        } else {
            // Reward leaving exactly enough room for the next item.
            let snug = 1.0 - (post - nxt).abs() / cap;
            score -= 4.0 * snug * snug;
        }
    }

    // Mild penalty for opening a brand-new bin when many bins are open,
    // scaled smoothly by mean residual fragmentation.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let frag = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 6.0 + 4.0 * frag + 3.0 * progress;
    }

    // Slight preference for bins with residual close to item_size (best fit).
    let waste = (bin_residual as f64 - item_size as f64) / cap;
    score += 3.0 * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Perfect fit bonus (zero or tiny dead space)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic dead-space classes: residuals that few future items can use are penalized.
    // Items are 1..100; a residual r is "usable" if some plausible item fits exactly-ish.
    // Class by integer division into harmonic bands of capacity/8.
    let band = post_residual / (bin_capacity / 8).max(1); // 0..=8
    let band_penalty = match band {
        0 => -10.0,                 // almost full: great
        1 => 0.0,                   // small leftover, mildly useful
        2 => 6.0,                   // ~12-25 dead space
        3 => 10.0,
        4 => 14.0,                  // ~half full: worst harmonic for exact fits
        5 => 10.0,
        6 => 6.0,
        7 => 2.0,                   // large residual still flexible
        _ => 0.0,
    };
    score += band_penalty as f64;

    // Modulo arithmetic on post_residual: residuals congruent to small values mod common
    // item sizes (10, 20, 25, 50) are likely to be exactly filled later.
    let harmonic_bonus: f64 = if post_residual % 10 == 0 {
        -8.0
    } else if post_residual % 5 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap_f);
        } else {
            // Next item cannot follow here; mild penalty scaled by how much it overshoots
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / cap_f).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.05 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin has maximal flexibility; only prefer it
    // when no open bin gives a decent fit (i.e., when our score would otherwise be poor).
    if bin_residual == bin_capacity {
        // Neutral base: an empty bin scores post_residual == capacity (100) plus band 7 bonus.
        // Encourage new bin early in stream (cheap exploration), discourage near the end.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
        // Penalize new bins when many bins are already open and mean residual is high.
        score += 0.15 * open_bins_count as f64 + 0.10 * mean_residual;
    } else {
        // Mild reward for packing into bins that are already substantially filled
        // (best-fit bias beyond raw post_residual).
        let fill = 1.0 - frac;
        score -= 6.0 * fill;
    }

    // Small tie-break: prefer lower-index-feel bins via mean residual alignment.
    score += 0.02 * ((mean_residual - post_f).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space pressure grows with stream progression.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate: prefer it only when residuals across open bins are large
    // (i.e., current bins are too full to be useful) or fit is terrible.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred on decent fits.
        score += 15.0;
        // But if this bin's fit is excellent while open bins are fragmented, ease it.
        if post_residual < 10 {
            score -= 20.0;
        }
        // If mean residual of open bins is small, opening new bin is attractive.
        score -= mean_residual * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in the post-residual,
    // this is a chain of perfect fills — reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 600.0;
        } else {
            score -= 120.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: post-residual too small for the next item — penalize
        // proportionally to how much of the residual becomes unusable.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 90.0 * dead;
    }

    // Relative-to-mean coupling: bins tighter than average are worth filling,
    // bins looser than average should be saved for larger future items.
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 40.0 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // in the stream or when nothing else fits well; otherwise discourage it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count >= 1 {
            score += 150.0; // an open bin fits — strongly prefer reusing it
        } else {
            score -= 50.0 * (1.0 - progress); // early stream: fresh bin is fine
        }
    }

    // Mild pressure to prefer bins with less residual among equally good fits.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space that likely can never be used
    // (dead space below the minimum item size is wasted forever).
    let min_size = 1.0f64; // unknown distribution, so treat any leftover as potentially usable
    if post_residual > 0 {
        // Wasted fraction relative to capacity, non-linearly amplified.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste * waste;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to how snugly it fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + snug);
        } else {
            // Next item will NOT fit here: penalize more when leftover is small
            // (creating unusable sliver right before a forced new bin).
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (gap / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating
    // into fuller bins (lower post_residual relative to mean residual).
    if open_bins_count > 0 {
        let mean_r = mean_residual.max(0.0);
        if (post_residual as f64) < mean_r {
            score -= 10.0 * (mean_r - post_residual as f64) / bin_capacity as f64;
        } else {
            score += 10.0 * (post_residual as f64 - mean_r) / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (keep residuals flexible); late in the stream, pack tightly.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // Only prefer it when existing fits would be terrible (item barely fits
    // leaving a sliver, or too many bins already open and stream is early).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 50.0;
        // If the best alternative is a poor fit, opening a new bin is better.
        // Poor fit signal: item fills most of an existing bin leaving tiny gap.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 400.0;
        }
        // Early stream with few bins: new bin is cheap (flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * (1.0 - progress);
        if open_bins_count < 2 {
            score -= 40.0;
        }
        // If next item is large, having a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Smooth polynomial coupling of post-residual with stream progress
    let mut score = base * (1.0 + 0.9 * progress * progress);

    // Reward tight fits smoothly (low post residual), stronger later in stream
    let tightness = 1.0 - base;
    score -= 1.8 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that next item can't use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) / cap * 2.5;
        } else {
            score -= 0.6 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin bonus (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.8 * progress;
    }

    // Slight preference for bins below mean residual (consolidation)
    score += 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate: mildly penalized so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 0.8 + 1.5 * progress;
    }

    // Mild pressure against many open bins
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: only attractive if no open bin can fit the item,
    // or if the item is huge and would leave an awkward gap elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Forced new bin: strong reward.
            return -1000.0;
        }
        // Otherwise penalize opening a new bin; worse when many bins already fit.
        return 500.0 + 50.0 * fitting_bins_count as f64 + item_size as f64;
    }

    // Tight fit reward: quadratic in how snugly the item lands.
    let tight = (bin_residual - item_size) as f64;
    score -= (bin_capacity as f64 - tight) * 0.05;

    // Dead space: residuals below the minimum item size (harmonic class 0)
    // are permanently unusable -> penalize proportionally to their smallness.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Harmonic classes via integer division on post_residual:
    // classify leftover into buckets of 10 (capacity fractions).
    let class = post_residual / 10;
    // Reward leftovers that match common item-size classes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Very large leftovers are fine (flexible), very tiny ones are bad.
    score += match class {
        0 => 15.0,
        1 => 8.0,
        2 => 4.0,
        3 => 0.0,
        4 => -2.0,
        _ => -5.0,
    } as f64;

    // Lookahead: if the next item cannot fit into this bin's post-residual,
    // we'll need another bin anyway; penalize more when the gap is large.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Next item fits here: reward leaving exactly enough room.
            score -= 4.0;
            if post_residual - next_item_size < 10 {
                score -= 3.0; // near-perfect two-item packing
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Stream progression: late in the stream, prefer consolidating into
    // existing bins (avoid scattering across many nearly-empty bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins whose residual is below the mean (fill the emptier-tail bins
    // less; keep large-residual bins flexible) — invert: favor below-mean bins.
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a
    // minimum-size item (1) are worthless; residuals below the lookahead
    // item size are dead space for the next step.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable sliver -> dead space penalty.
        score += 300.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 120.0;
    }

    // Reward leaving residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size).min(30) as f64 * 2.0;
    }

    // Last-chance pressure: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; a fresh bin is only attractive when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 60.0 + 40.0 * (open_bins_count as f64).ln() + 50.0 * (1.0 - progress);
        // Never open a new bin if the item fits perfectly somewhere else is
        // handled by perfect-fit reward; also discourage new bin for tiny items.
        if item_size <= 20 {
            score += 150.0;
        }
    } else {
        // Slight preference for bins tighter than average (best-fit flavor).
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        }
    }

    // General tightness coupling: quadratic reward for small post_residual.
    score -= (100.0 - post_residual.min(100) as f64).powi(2) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual non-linearly.
    let residual_f = post_residual as f64;
    score = residual_f * (1.0 + residual_f / bin_capacity as f64);

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item cannot follow; penalize dead space creation
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: minimize residual as usual
        score -= 10.0;
    }

    // Relative to mean residual: bins with less residual than average are more precious;
    // wasting them is costly.
    if (bin_residual as f64) < mean_residual {
        score += 8.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 || item_size >= 70 {
            score -= 55.0;
        }
        // late in stream, opening fresh bins is fine (better long-run packing)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins that are already committed (more open bins => keep them tight)
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0 * (10.0 - pr) / 10.0; // tiny useless slivers
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: strongly penalize opening a new bin
    // unless the fit into existing bins would be very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_capacity - item_size) as f64;
        score += 55.0 + 0.5 * waste;
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If many open bins with large mean residual, prefer using them.
        score += 0.15 * open_bins_count as f64;
        if mean_residual > item_size as f64 + 10.0 {
            score += 20.0;
        }
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // post-residual too small for next item: mild penalty scaled by closeness
            score += 6.0 * (nxt - pr).min(30.0) / 30.0;
        }
    }

    // Prefer filling bins that already have low residual (consolidation).
    score += 0.1 * ((mean_residual - bin_residual as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 1.0 + 0.8 * t - 1.2 * t * t + 0.6 * t * t * t;
    score *= poly.max(0.1);

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item (lookahead coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0);
        score += 0.35 * waste * waste / cap;
        // Reward bins whose post-residual exactly accommodates the next item.
        if pr >= nx && pr - nx < 10.0 {
            score -= 6.0;
        }
    } else {
        // End of stream: strongly prefer filling existing bins.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight penalty when many bins are open and residual is large (fragmentation).
    let open_f = open_bins_count as f64;
    score += 0.02 * open_f * (pr / cap);

    // Encourage balance with the mean residual of open bins.
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only for large items or early stream.
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / cap) > 0.6;
        if large || (fitting_bins_count == 0) {
            score -= 8.0;
        } else {
            score += 15.0 + 20.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals in coarse buckets (multiples of 10) are more reusable.
    let post_class = post_residual / 10;
    let item_class = item_size / 10;

    // Reward residuals that fall into "harmonic" classes: divisible nicely.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0; // round leftover: easy future fit
        }
        if post_residual % 25 == 0 {
            score -= 4.0; // quarter-class leftover
        }
        if post_residual % 50 == 0 {
            score -= 3.0; // half-class leftover
        }
        // Penalize tiny dead-space classes
        if post_residual < 10 {
            score += 18.0;
        } else if post_residual < 20 {
            score += 6.0;
        }
    } else {
        score -= 14.0; // perfect fill
    }

    // Coupling with lookahead item: if next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
        // Harmonic bonus if next item exactly consumes the leftover class
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual % 10 == next_item_size % 10 {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by mismatch
        let gap = (next_item_size - post_residual) as f64;
        score += 0.08 * gap;
    }

    // Last-chance bin logic: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 16.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // current item is large (harmonic class >= 6, i.e. >= 60) and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_class >= 6;
        if large_item {
            score -= 4.0; // big items fine in fresh bins
        } else {
            score += 10.0 + 20.0 * (1.0 - progress); // discourage early bin opening for small items
        }
        // If many bins already open and mean residual is tight, opening is fine.
        if open_bins_count > 4 && mean_residual < 15.0 {
            score -= 8.0;
        }
    }

    // Tightness reward: the less slack left relative to item, the better the fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Prefer bins whose residual is close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: bonus proportional to fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space relative to known next item
    }

    // New-bin candidate handling: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            score += 45.0 + 2.0 * open_bins_count as f64; // discourage opening when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 50.0 / (post_residual as f64).sqrt();
    }

    // 2-step lookahead: if next item fits exactly in the post residual,
    // this is a perfect chain — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves more dead space: mild penalty
            // proportional to how much slack remains after the next item.
            let after_next = post_residual - next_item_size;
            score += (after_next as f64) * 0.6;
        } else {
            // Next item cannot use the residual: penalize dead space,
            // worse when the leftover is small (unusable).
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 60.0; // nearly-fitting dead space is the worst
            } else {
                score += (post_residual as f64) * 0.3;
            }
        }
    } else {
        // Last item: strongly prefer fullest bin.
        score -= 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual large relative to capacity) or few bins fit.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; discourage early in the stream
        // or when good alternatives exist.
        score += 30.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // opening fresh bin helps chain large items
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Slight preference to consolidate into fewer bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space (< 10) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver is worse than a slightly larger gap
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item can use the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            score += 6.0;
        }
        // Strong coupling: next item exactly fills leftover
        if next_item_size == post_residual {
            score -= 22.0;
        }
    }

    // Last chance: only one bin fits -> strongly prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with residual close to item size (best-fit style, non-linear)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Global state: many open bins with high mean residual -> favor consolidation
    if open_bins_count > 2 {
        let spread = mean_residual - post_residual as f64;
        score += 0.4 * spread;
    }

    // Time horizon: early in stream, opening new bins is cheaper; late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate
        let mut new_bin_penalty = 12.0 + 40.0 * progress + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            new_bin_penalty -= 5.0; // fresh bin guarantees room for lookahead
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: reward more heavily late in the stream
        score -= 10.0 * progress;
    }

    // Mild penalty for very loose fits creating large stranded residual
    if post_residual > 50 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate spread (favor balanced fills); late, squeeze residuals hard.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap;

    // Quadratic penalty for dead space that no item can use (sizes 1..=100),
    // smoothly scaled by progress.
    let dead = if pr > 0.0 { (cap - pr).min(cap) / cap } else { 1.0 };
    let dead_penalty = (1.0 - dead).powi(3) * (10.0 + 30.0 * progress);
    score += dead_penalty;

    // Reward tight fits (small post_residual) with a smooth inverse coupling.
    if pr > 0.0 {
        score -= 20.0 / (1.0 + pr * 0.1);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it nearly fits, mildly penalize fragmentation.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = (pr - n) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - progress * 0.5);
        } else {
            let overflow = (n - pr) / cap;
            score += 8.0 * overflow;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity (smooth term), so big items start bins early.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 30.0 - 40.0 * size_frac * size_frac;
        score += 0.5 * open_bins_count as f64;
    }

    // Mild drift toward bins below mean residual (balance open bins smoothly).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Tight-fit reward: harmonic classes of post_residual ----
    let pr = post_residual;
    let cap = bin_capacity as f64;
    // Exact fit is golden.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 25.0;
    }

    // ---- Harmonic / modulo classes on post_residual ----
    // Residuals divisible by small common item granularities (e.g. 10, 20, 25)
    // are more reusable by future items.
    if pr % 10 == 0 {
        score -= 15.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 10.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Dead-space penalty: residuals in awkward bands (1..9 and 21..29 style gaps)
    let band = pr % 30;
    if band >= 21 && band <= 29 && pr > 30 {
        score += 10.0; // awkward leftover class
    }

    // ---- Relative tightness: fraction of capacity consumed ----
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 40.0;

    // ---- Lookahead: does the next item fit the resulting residual? ----
    if next_item_size > 0 && post_residual >= next_item_size {
        // Chain-friendly placement: residual still usable by next item.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0;
        score -= (next_item_size as f64 / cap) * 20.0;
        if (slack as u32) % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual becomes dead relative to lookahead: penalize proportionally.
        score += (post_residual as f64 / cap) * 30.0;
    }

    // ---- Last-chance bonus: this is the only open bin that fits ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; discourage unless no good open fit exists.
        // Base penalty grows with how many bins are already open (amortization).
        score += 90.0 + (open_bins_count as f64) * 2.0;
        // If item is large, a fresh bin is actually attractive (keeps big space intact).
        if item_size >= 60 {
            score -= 55.0;
        }
        // Mid-stream, slightly discourage proliferation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If open bins have large mean residual, prefer them over a new bin.
        score += (mean_residual / cap).min(1.0) * 40.0;
    } else {
        // Mild preference for using existing bins, scaled by how full they are.
        let use_ratio = bin_residual as f64 / cap;
        score -= use_ratio * 25.0;
        // Prefer bins below mean residual (i.e. fuller than average) to consolidate.
        if (bin_residual as f64) < mean_residual {
            score -= 12.0;
        }
    }

    // ---- Small global regularization ----
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as i32) as f64 * 8.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 10.0 * fill_ratio;
    }

    // Penalize leaving a gap that is smaller than the next item (dead space for lookahead),
    // but reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 6.0;
        } else if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins when residuals are small.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.15 + 0.25 * progress);

    // Slight preference toward bins with residuals near the mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Brand-new empty bin: only attractive if the item is large and fits alone,
    // otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post residual: strong bonus, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.15 * slack;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use the leftover.
        score += 10.0;
    }

    // Penalize tiny unusable residuals (wasted dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Prefer bins whose residual is tighter than the mean (good packing).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it unattractive unless residual after placement
    // is large and current bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual > 40.0 && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 30.0;
        }
    }

    // Early in stream: consolidate into few bins; late: allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving large awkward residue.
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize it,
    // but less so when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = 20.0 + 30.0 * (1.0 - progress);
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score += open_penalty + 5.0 * crowd;
        // If mean residual across open bins is small (all bins crowded),
        // opening a new bin becomes more attractive.
        score -= 0.3 * (mean_residual.max(0.0));
    } else {
        // Prefer reusing bins with larger residual (keep small slivers consolidated).
        score -= 0.05 * bin_residual as f64;
        // Penalize bins whose residual is far above mean (fragmentation avoidance).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev.abs();
    }

    // Penalize creating dead space below the minimum item size (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: post_residual weighted by progress polynomial
    let prog_poly = 0.5 + 2.0 * progress * progress;
    score *= 1.0 + 0.35 * prog_poly * (pr / cap);

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.4 + progress);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = nx - pr;
            score += 6.0 * (gap / cap).sqrt() * (1.0 + progress);
        } else {
            // reward leaving exactly usable space for next item
            score -= 4.0 * (1.0 - ((pr - nx) / cap).abs());
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and fit is loose
    let open_f = open_bins_count as f64;
    score += 0.5 * (open_f / (open_f + 5.0)) * (pr / cap) * (1.0 - progress);

    // Mean residual coupling: prefer bins near the mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: keep it neutral-ish unless current fits are bad
    if bin_residual == bin_capacity {
        score = pr + 20.0 - 10.0 * (1.0 - tightness) - 8.0 * progress * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition residual space into capacity-fraction classes.
    // Residuals that are "usable" for common item sizes (>=10) should be rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional class of post_residual (quarters of capacity)
    let quarter = (pr / (cap / 4.0)).floor();
    // Penalize residuals in "dead" classes: too small for the smallest item (1..=100 range, use 10)
    if post_residual < 10 {
        score += 50.0; // dead space penalty
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Harmonic reward: residual that is a multiple of common item classes is good
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Residual matching next item exactly is perfect
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // reward leaving room for the lookahead item
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        // lookahead cannot fit in this residual: penalize proportionally
        score += 4.0 * (next_item_size as f64 - pr) / cap * 10.0;
    }

    // Modulo coupling on bin_residual: near-full bins (small residual) preferred
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= 6.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is hopeless
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual >= 50.0 {
            score -= 5.0; // a fresh bin has long usable life
        }
    }

    // Stream progression: early on, be conservative about fragmentation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (pr / cap);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Integer-division threshold on post_residual: prefer residual <= half capacity
    if post_residual > bin_capacity / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold another item (min item size 1, but practically < ~10) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Reward tight fits relative to the residual before placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize leaving a gap that neither fits the next item nor any typical item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 8.0; // next item cannot use this bin
        } else if post_residual == next_item_size {
            score -= 12.0; // perfect chain
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 30.0; // but not if it creates dead space
        }
    }

    // Open-bin pressure: discourage scattering across many bins when mean
    // residual is already low (bins are nearly full).
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 2.0;
    }
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it
    // only when no good fit exists elsewhere. Give it a mild default penalty
    // so existing tight fits win, but it beats dead-space placements above.
    if bin_residual == bin_capacity {
        score += 10.0;
        // early in stream, opening bins is cheap and keeps future options open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
        // if the item is large, filling a fresh bin is fine
        if item_size >= 60 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    // (or next item fits with minimal slack). Strongly reward this bin.
    if next_item_size > 0 {
        let slack = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight match to next item
        score -= 30.0 * (1.0 - slack / (bin_capacity as f64)).max(0.0) * (1.0 - slack / 40.0).max(0.0);
        // Penalize if the next item CANNOT fit here (creates a stranded residual)
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    } else {
        // Last item: minimize residual as hard as possible
        score -= 40.0;
    }

    // Penalize residuals that deviate from the mean (prefer balanced/waste-minimizing fills)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize large unusable dead space (residual too small for typical future items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: nothing (min size 1..100 unknown) may fit
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins when many bins are open (avoid bin sprawl)
    if open_bins_count > 4 {
        score -= 2.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residual waste
    // from using an existing bin would be severe. Penalize opening new bins
    // progressively as the stream advances.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + 30.0 * progress;
        // Allow new bin only if item barely fits anywhere else is impossible to know
        // here, but a big lookahead match in the new bin is somewhat attractive:
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 5 {
            score -= 45.0;
        }
    }

    // Mild tie-break: favor bins with smaller residual overall (tighter packing)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 1.5 * cap * tightness * tightness;

    // Penalize leaving dead space that likely can't be used by future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * (dead / 10.0).powi(2);
    }

    // Lookahead: reward if next item fits exactly into the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            // next item won't fit here; slight penalty proportional to leftover gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize placing into a bin whose residual deviates wildly from the mean
    // (keeps a balanced portfolio of residual sizes for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Discourage opening new bins when decent open bins exist; encourage it
    // when the fit would be very loose and many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        score = 0.9 * cap;
        // Cheaper to open early in the stream; more expensive later.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score *= 1.0 + 0.5 * progress;
        // If item is small relative to capacity and fits elsewhere, new bin is bad.
        score += 0.5 * (cap - item_size as f64);
        // If nothing fits except this candidate, opening is inevitable: soften.
        if fitting_bins_count == 0 {
            score -= 0.4 * cap;
        }
    } else {
        // Mild penalty for using bins with large residuals on small items
        // (save big-residual bins for big future items).
        let waste = (bin_residual as f64 - item_size as f64) / cap;
        score += 10.0 * waste * waste;
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += 6.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (2.0 + 4.0 * progress);

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let gap_norm = gap / cap;
        score += 3.0 * gap_norm * gap_norm;
        if nxt <= post {
            score -= 2.5 * (1.0 - gap_norm);
        } else {
            score += 2.0 * gap_norm;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 + 3.0 * progress;
    }

    // Penalize crowding relative to mean residual across open bins
    score += 0.05 * (open_bins_count as f64) * ((mean_residual - post) / cap).abs();

    // New-bin candidate: keep it competitive only when current fits are poor
    if bin_residual == bin_capacity {
        score += 4.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity/10 buckets
    let class = post_residual / (bin_capacity / 10);
    // Reward exact fits and near-exact fits
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else {
        // penalize dead space that no typical item can fill (items >= 1, but
        // residual below the smallest useful class wastes capacity)
        if post_residual < 10 {
            score += 40.0;
        }
        // harmonic penalty: residual that is not a multiple of common item classes
        let m = post_residual % 10;
        if m != 0 {
            score += m as f64 * 1.5;
        }
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect chain: next item exactly fills what's left
            if next_item_size == post_residual {
                score -= 90.0;
            } else {
                score -= 30.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // next item won't fit here; residual becomes dead space unless tiny
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins with residuals close to the mean (balance open bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Early in stream: keep bins open for flexibility; late: pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 70.0;
        // more open bins -> cheaper to open another (spread load)
        score -= open_bins_count as f64 * 2.0;
        // if no existing bin fits at all, opening is mandatory-ish
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // large item into fresh bin leaves large residual; fine early
        score -= progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any item (min size 1, but
    // practically small gaps below ~10) are nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let fit_ratio = post_residual as f64 / item_size as f64;
        score -= 25.0 / (1.0 + fit_ratio);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bin attractive only when it is genuinely needed.
    if bin_residual == bin_capacity {
        // Base mild penalty so existing decent fits win.
        score += 15.0;
        // But if only one bin fits (or none besides this), opening fresh is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Large next item favors keeping a fresh bin available.
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // If the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item would be blocked by the post residual, mild penalty.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 6.0;
    }

    // Slight preference for bins below mean residual (balance residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item almost fits the leftover space.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap <= 10 {
            score -= (10 - gap) as f64 * 2.0;
        }
        // Penalize leaving dead space smaller than the smallest plausible item (1..100 range).
        if gap < 0 && post_residual > 0 && post_residual < 10 {
            score += (10 - post_residual) as f64 * 3.0;
        }
        // Strongly penalize wasted space that cannot fit the next item but is large.
        if gap < 0 && post_residual >= 10 {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Favor bins whose residual is above mean residual (absorb item into fuller bins).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins on genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no real fit is good (large leftover vs next item), allow opening new bin
        if next_item_size > 0 && post_residual < next_item_size as u32 {
            score -= 30.0;
        }
    }

    // Late in stream: tighten packing, prefer fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Strong reward for perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: penalize bins whose leftover cannot fit the next item,
    // reward bins where leftover exactly matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 15.0; // leaves a perfect slot for next item
            } else if slack < 10 {
                score += 5.0; // awkward small leftover
            } else {
                score += slack as f64 * 0.3;
            }
        } else {
            // leftover unusable for next item: dead space
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when good existing options exist,
    // scaled by how many bins already fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin.
        let mut new_bin_score = bin_capacity as f64 * 0.8;
        // If few bins fit the item, opening a new bin is more acceptable.
        new_bin_score -= (fitting_bins_count as f64) * 8.0;
        // Early in stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= (1.0 - progress) * 20.0;
        // If mean residual of open bins is high, existing bins are wasteful anyway;
        // opening a new bin is fine.
        new_bin_score -= mean_residual * 0.3;
        // If the item is large, prefer new bin to avoid fragmentation.
        if item_size > bin_capacity / 2 {
            new_bin_score -= 10.0;
        }
        // Many open bins already: discourage sprawl.
        new_bin_score += open_bins_count as f64 * 1.5;
        score = new_bin_score;
    } else {
        // Existing bin: slight penalty for many open bins to encourage consolidation.
        score += open_bins_count as f64 * 0.2;
        // Prefer bins with residual close to item (best-fit behavior).
        let fit_gap = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
        score += fit_gap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Smooth non-linear penalty on wasted residual (quadratic coupling).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += 0.8 * norm_pr * norm_pr * cap;

    // Stream progress term: later in the stream, tighten tolerance for sloppy fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits (small post_residual) with a smooth inverse coupling.
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (item_size as f64 / cap);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving a mid-sized gap.
        score += 2.0 * norm_pr * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: opening a new bin is penalized, more so early
    // in the stream and when many bins are already open with useful residual.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 12.0 + 8.0 * (1.0 - progress) + 10.0 * openness;
        if next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 4.0; // existing bins likely hold the next item too
        }
    }

    // Mild preference for bins already below mean residual (consolidation).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 1.5 * (mean_residual - res_f) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left

    // Dead-space penalty: residuals that are too small to host typical items are bad.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // nearly unusable sliver
    }

    // Harmonic class bonus: residuals that are multiples of small units (10, 20, 25)
    // are reusable by future items; reward exact harmonic classes.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 {
        score -= 6.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size exactly / at all?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward tightness of that follow-up fit
            let follow = (post_residual - next_item_size) as f64;
            score -= 12.0 + 10.0 * (1.0 - follow / cap);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0 + 8.0 * (1.0 - (post_residual as f64) / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that grows
    // with number of open bins, so we prefer existing bins on decent fits.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        // Prefer bins tighter than average (better fit quality).
        score += 0.3 * (pr - mean_residual);
    }

    // Progress-based tilt: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9)
    // are pure waste. Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 8.0;
    }

    // If this is the only fitting bin, strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into a new bin unless the fit is poor.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But if the new bin would fit both this item and the lookahead item
        // snugly, opening is attractive when existing bins fit poorly.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        // Late in the stream, new bins are less useful; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless it creates dead space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if post_residual >= 10 {
        score += dev * 0.15;
    }

    // Lookahead coupling: if the post-residual exactly fits the next item,
    // this placement is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If post-residual is nonzero but smaller than the next item and below
    // the minimum item size, it is dead space for the lookahead too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + fit_gap * 0.15);
    }

    // Penalize residuals that are too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize small post_residual relative to mean residual (fragmentation risk).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless item is large.
    if bin_residual == bin_capacity {
        score += 15.0 - item_size as f64 * 0.1;
    }

    // Late in stream, tighten packing (avoid waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer minimal leftover space after placement.
    let mut score = post_residual as f64;

    // Reward bins that are already partially filled (consolidation).
    score += (bin_capacity - bin_residual) as f64 * 0.08;

    // Lookahead coupling (k=2): strongly reward a post_residual that can
    // host the next item; mildly penalize when the next item won't fit,
    // since residual then risks becoming dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= next_item_size as f64 * 1.4;
        } else {
            score += next_item_size as f64 * 0.25;
        }
    }

    // Last-chance bonus: if this is the ONLY open bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin should be discouraged
    // increasingly with the number of open bins and their average slack.
    if is_new_bin {
        score += 25.0
            + mean_residual * 0.6
            + open_bins_count as f64 * 3.0
            + progress * 15.0;
        // Exception: a fresh bin is attractive for large items whose
        // post_residual still accommodates the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Penalize residuals far from the mean residual of open bins
    // (favoring a homogeneous, predictable pool of bin slacks).
    score += (mean_residual - post_residual as f64).abs() * 0.12;

    // Late in the stream, mildly favor compacting into fewer bins.
    score -= progress * 4.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized tightness of the resulting fit (0 = perfect fill, 1 = empty bin)
    let tight = pr / cap;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let reward = (1.0 - tight * tight) * (1.0 + 40.0 * progress);
    score -= reward;

    // Penalize leaving residuals that are awkwardly mid-range (neither full nor large)
    let awkward = 4.0 * tight * (1.0 - tight);
    score += awkward * (10.0 + 20.0 * progress);

    // Lookahead: penalize if the next item cannot use this bin's post-residual
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 8.0 + 12.0 * progress;
        } else {
            // reward if next item exactly or nearly fits the leftover
            let gap = (pr - next_item_size as f64) / cap;
            score -= 10.0 * (1.0 - gap).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: prefer opening a new bin only when open bins have
    // large mean residual (poor fits elsewhere) or late in the stream
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / cap;
        score += 30.0 - 25.0 * open_pressure * open_pressure - 10.0 * progress;
    } else {
        // Slight preference for bins with lower residual among fitting bins
        score += 3.0 * (bin_residual as f64 / cap);
    }

    // Mild penalty for accumulating many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward "perfect" classes (0, small)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect: dead space unlikely to fit anything
    }

    // Dead-space classes: residuals in [11..=30] are semi-usable; [31..=50] usable for medium items
    let class = post_residual / 10; // integer division harmonic class
    match class {
        0 => score -= 20.0,
        1 => score += 4.0,
        2 => score += 10.0,
        3 => score += 2.0,
        4 => score -= 3.0,
        _ => {}
    }

    // Reward if next item fits exactly into post_residual (chained tight fit)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += 6.0; // next item won't fit here: bin will be closed anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // penalize opening new bins generally, more as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // but if this item is huge and leaves big post_residual in existing bins, opening is fine
        if item_size as f64 > 0.8 * cap {
            score -= 25.0;
        }
    } else {
        // prefer bins whose residual is close to item (tight fit relative)
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score -= 12.0 * tightness;
        // prefer bins below mean residual (more filled bins get closed sooner)
        if post < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=9) are almost unusable
    // since future items are >= 1 but practically waste; penalize hard.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 - (post_residual as f64) * 4.0; // +56..+24 penalty
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Pressure: with many open bins, prefer filling existing ones over opening new.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count and
        // mean residual, so we only open when existing fits are bad.
        score += 30.0 + (open_bins_count as f64) * 4.0 + mean_residual * 0.5;
        // But if no open bin fits (this is the only candidate), the penalty
        // is irrelevant; soften so a new bin is opened when needed.
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly reward using it to avoid a new bin.
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item would be blocked by a tiny post residual, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 9 {
        score += 10.0;
    }

    // Mild preference to fill bins with large residuals early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

