    // Lookahead coupling: bonus if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = (post_residual as f64 - nxt) / cap;
            score -= 12.0 * (1.0 - gap);
        } else {
            // next item won't fit here; penalize leaving medium dead space
            let dead = post_residual as f64 / cap;
            if dead > 0.05 && dead < 0.35 {
                score += 15.0 * dead;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading across many open bins lightly; encourage consolidation
    // when mean residual is large.
    let mean_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score += 0.5 * open_bins_count as f64 * (1.0 - mean_tight);

    // Time horizon: early in the stream, be more willing to open new bins
    // (explore); later, consolidate to avoid bin proliferation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let exploration = (1.0 - progress).clamp(0.0, 1.0);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin costs one bin; accept it if existing bins fit poorly.
        let poor_fit = if post_residual == 0 { 0.0 } else { post_residual as f64 / cap };
        score = cap * 0.6 + 40.0 * poor_fit - 20.0 * exploration;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open
        }
    } else {
        // Late stream: reward using already-open bins.
        score -= 10.0 * progress;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
