    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.35 * p2 + 0.25 * p3);

    // Reward tight fits more strongly as the stream matures (smooth coupling).
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (20.0 + 60.0 * p2);

    // Penalize dead space relative to mean residual, amplified late in stream.
    let dead = pr - mean_residual;
    score += dead * (0.4 + 0.8 * p3);

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
