            let x = 1.0 - gap / cap;
            score -= 18.0 * x * x;
        } else {
            score += 12.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 30.0 + 40.0 * p2;
    }

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
