}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 5 classes of 20
    let class = post_residual / 20;
    // Reward tight fits more strongly for lower (tighter) classes
    score -= match class {
        0 => 30.0,           // post_residual <= 19: excellent fit
        1 => 20.0,           // 20..39
        2 => 10.0,           // 40..59
        3 => 4.0,            // 60..79
        _ => 0.0,            // 80..100: poor fit
    };

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo-10 class: small residues divisible by 10 pair well with common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit_quality = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.25 * lookahead_fit_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space risk if next item won't fit
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // good fit in an existing bin beats a fresh bin
        score += 15.0;
        if class <= 1 || post_residual == 0 {
            score += 50.0;
        }
    }

    // Progress-based mild pressure to close bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // Prefer filling bins when many bins are open
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: favor bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

