            let gap = (post_residual as f64 - next).abs();
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            // exact match bonus
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item cannot fit after placement: penalize proportional to shortfall
            let shortfall = next - post_residual as f64;
            score += 6.0 * (shortfall / next).min(1.0);
