    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    } else {
        // dead space penalty for large unusable residuals
        score += 0.15 * (post_residual as f64).powf(1.1) / bin_capacity as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins as stream progresses (fill existing bins late)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
        // opening a new bin is acceptable if current bin leaves huge dead space
        if post_residual > 40 && post_residual < next_item_size.max(1) {
            score -= 30.0;
        }
    }

    // Prefer denser bins (more items already packed) via residual vs capacity ratio
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
