        0 => 8.0,        // nearly full bin: great, but handled by small residual anyway
        1 => 0.0,        // moderate leftover
        2 => 2.0,        // large leftover wastes capacity
        _ => 5.0,        // huge leftover = bin barely used
    };

    // Exact fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportional to how well next item fills remaining space
            let fill = (next_item_size as f64) / (post_residual.max(1) as f64);
            score -= 5.0 + 5.0 * fill;
            // harmonic match: next item leaves a multiple-of-10 residual too
            if (post_residual - next_item_size) % 10 == 0 {
