        let fragmentation = (mean_residual - post_residual as f64).abs();
        // penalize new bin normally; discount penalty when many fragmented open bins
        score = 60.0 + 40.0 * (1.0 - progress) - open_bins_count as f64 * 0.5 - fragmentation * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
