            score -= 30.0; // perfect pairing
        } else if post_residual >= next_item_size {
            // Next item fits, but measure how much slack would remain after it.
            let two_step_slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - two_step_slack / (bin_capacity as f64));
        } else {
            // Next item cannot fit here: penalize proportionally to the gap,
            // unless post_residual is small dead space that nothing would use anyway.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are "efficient"
    // bins; placing there keeps good bins in play. Bins above mean residual are
    // wasteful targets unless the fit is very tight.
    if (bin_residual as f64) > mean_residual {
        score += 0.15 * ((bin_residual as f64) - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - (bin_residual as f64));
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible (huge dead space).
    if fitting_bins_count == 1 {
        if post_residual as f64 <= 0.35 * (bin_capacity as f64) {
            score -= 25.0;
        } else {
            score += 0.30 * (post_residual as f64);
        }
    }

    // Penalize leaving residuals that are too small to be useful for any item
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild stream-progression term: late in the stream, consolidation matters more;
    // early on, allow spreading to build flexible bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    // Prefer filling bins when many bins are open (avoid bin proliferation).
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / (bin_capacity as f64));

    // New-bin candidate: only attractive when nothing fits well anywhere.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.10 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0; // stranded residual
        }
        // Exact pairing bonus: item + next fills bin almost perfectly.
        if item_size + next_item_size as u32 == bin_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 20.0 * (fitting_bins_count as f64).max(1.0);
        // Early in the stream, tolerate new bins slightly more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (consolidate large holes).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins with larger residuals when item is large.
    if item_size > bin_capacity / 2 {
        score -= 0.1 * bin_residual as f64;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit_frac = item_size as f64 / cap;

    // Tight fit reward: strongly favor bins where the item nearly fills residual,
    // with a smooth non-linear (quartic) coupling scaled by stream progress.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness.powf(4.0) * (0.5 + progress);

    // Penalize dead space: small-but-nonzero post residuals are wasteful.
    // Smooth bump around post_residual in (0, ~10).
    let dead = post_residual as f64;
    let dead_bump = dead * (20.0 - dead).max(0.0) / 100.0;
    score += 4.0 * dead_bump * (1.0 - progress * 0.5);

    // Lookahead coupling: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        score += 0.35 * gap;
        // Exact match with next item is excellent.
        if post_residual as f64 >= nxt {
            score -= 8.0 * (-gap / 10.0).exp();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - fit_frac);
    }

    // New-bin candidate: penalize opening a new bin mildly early, more strongly
    // when good fits exist elsewhere; allow it late when residuals fragment.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 18.0 * (1.0 - progress) + 10.0 * (1.0 - fragmentation) - 6.0 * progress;
    }

    // Mild preference for bins below mean residual (balance load smoothly).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction classes. Residuals that are "usable" by typical item
    // sizes (multiples of small divisors) are rewarded; odd dead space is penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Class the post residual into harmonic bands: [0, 1/8, 1/4, 1/2, 1]
    // Leftovers below 1/8 of capacity are near-dead space -> strong penalty.
    if frac < 0.125 {
        score += 12.0 * (0.125 - frac) * cap * 0.1;
    } else if frac < 0.25 {
        // quarter-bin leftover: moderately useful
        score -= 2.0;
    } else if frac < 0.5 {
        // half-bin leftover: very reusable
        score -= 6.0;
    } else {
        // more than half left: bin barely used, wasteful placement
        score += 5.0;
    }

    // Integer-division harmonic class: does post_residual divide nicely into
    // common item granularity? Reward residuals divisible by 10 or 20.
    if post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual % 20 == 0 {
        score -= 2.0;
    }
    // Odd residuals below 10 are pure dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that would be
            let pr2 = post_residual - next_item_size;
            score -= 8.0 - 0.05 * pr2 as f64;
            if pr2 % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item will not fit here; if post_residual is small it's
            // effectively sealed, which is fine; if large, we stranded capacity.
            if post_residual >= next_item_size * 2 / 3 {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: this is the only bin that fits the item. Strongly
    // favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin wastes the mean residual of open bins.
    // Only allow it when open bins are nearly full (mean residual small) or
    // there are no open bins at all.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if open_bins_count > 0 {
            // Penalize new bin proportional to wasted average residual.
            score += 20.0 + 0.5 * mean_r;
            // But if mean residual is too small to hold typical future items,
            // opening fresh capacity is fine.
            if mean_r < 15.0 {
                score -= 25.0;
            }
        } else {
            score -= 5.0; // first bin
        }
    }

    // Tight fit reward: placing item that nearly fills the bin is excellent.
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.9 {
        score -= 10.0;
    } else if tightness > 0.75 {
        score -= 5.0;
    }

    // Slight preference for filling more-full bins early in the stream
    // (best-fit style); mild progression term for exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 1.0 * (1.0 - progress) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing a bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: a small leftover gap that cannot
    // hold the next item is wasted space -> penalize it heavily.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap too small even for the lookahead item.
            score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
            // If the gap is below the absolute minimum item size, it is
            // almost certainly dead space forever.
            if post_residual < 10 {
                score += 15.0;
            }
        } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            // The leftover can still accommodate the next item: reward.
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly discourage proliferating bins; this
    // nudges consolidation when scores would otherwise tie.
    score += open_bins_count as f64 * 0.25;

    // Slight preference for tighter fits relative to mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: minimize post_residual aggressively (superlinear).
    score += 0.6 * (post_residual as f64).powf(1.5) / bin_capacity as f64;

    // 2-step lookahead: strongly reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin becomes exactly reusable
        } else if post_residual > next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            // Favor bins whose leftover after next item stays small.
            score += 0.4 * chain_waste;
            if (post_residual - next_item_size) <= 10 {
                score -= 15.0; // tight two-item chain
            }
        } else {
            // next item cannot follow into this bin; penalize by gap size,
            // unless the leftover is small enough to be negligible dead space.
            let gap = (next_item_size - post_residual) as f64;
            if post_residual >= 10 {
                score += 0.5 * gap;
            } else {
                score -= 10.0; // tiny dead space, effectively a closed fit
            }
        }
    } else {
        // Last item: pure tightness matters.
        score -= 5.0;
    }

    // Relative-to-mean coupling: prefer bins with residual near the mean
    // (keeps pool homogeneous), punish outliers used wastefully.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is generally bad unless
    // item is large and no good fit exists. Make new bin moderately unattractive.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).max(1.0);
        score += 18.0 + 2.0 * openness;
        // Large items with poor fit alternatives justify a new bin:
        if item_size >= 60 {
            score -= 22.0;
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference to fill bins that are already mostly full.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 => keep threshold moderate).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 12.0 {
            score += 10.0; // nearly unusable sliver
        } else if dead < 25.0 {
            score += 4.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Penalize if this placement leaves residual that fits next item too perfectly,
        // wasting opportunity elsewhere? Slight coupling with mean residual.
        let mean_gap = mean_residual - (post_residual as f64);
        score += 0.05 * mean_gap;
    }

    // Prefer filling bins with larger residuals first (keep small-residual bins flexible).
    score -= 0.15 * (bin_residual as f64);

    // New-bin candidate logic: opening a new bin is attractive when current item is small
    // relative to mean residual (poor fit everywhere) or few bins fit the item.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 35.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 6.0;
        }
        // Late in stream, be more conservative about opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 10.0 * progress;
        // Many open bins with high mean residual => better to reuse.
        new_bin_score += 0.3 * open_bins_count as f64 + 0.2 * mean_residual;
        // Small items leave lots of space; new bin fine.
        new_bin_score -= 5.0 * (1.0 - fit_ratio);
        score = score.max(new_bin_score) * 0.0 + new_bin_score.min(score);
        if new_bin_score < score {
            score = new_bin_score;
        }
    }

    // Mild exploration noise-free deterministic tie-break: favor earlier bins slightly.
    score += 0.001 * (step_index as f64 % 7.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits: small post_residual gets a strong bonus
    let tight = (1.0 - norm_pr).powi(3);
    score -= 25.0 * tight;

    // Lookahead: if the next item fits exactly in the post residual, reward
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - pr / (next_item_size as f64 + 1.0));
    } else if next_item_size > 0 {
        // next item won't fit here; penalize leaving large dead space
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize spreading when many bins are open; favor consolidation early
    let openness = open_bins_count as f64 / (1.0 + progress * open_bins_count as f64);
    score += 3.0 * openness * norm_pr;

    // Mean residual deviation: prefer bins whose residual is close to the mean (balanced packing)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // baseline penalty so open bins with decent fits win, but relax late in stream
        score = 55.0 + 30.0 * progress - 10.0 * (fitting_bins_count as f64).min(3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual mod small integers create dead-space classes.
    // Residuals that are multiples of common item sizes (or tiny) are "usable classes".
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 12.0,                       // perfectly aligned class
            1 | 2 | 3 => -8.0,               // sliver class: nearly dead space
            4 | 5 | 6 => 4.0,                // medium class
            _ => 0.0,
        };
        score -= class_bonus;

        // Harmonic weight: dead space relative to capacity, amplified for tiny residuals.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0; // unusable sliver penalty
        }
    }

    // Integer-division threshold: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fit quality: harmonic class of combined packing
            let comb = (pr - next_item_size) as f64;
            score -= 10.0;
            score -= comb * 0.25;
            if comb as u32 % 10 == 0 { score -= 6.0; }
        } else {
            score += 6.0 + (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Perfect fit reward (harmonic alignment with capacity).
    if pr == 0 {
        score -= 40.0;
    } else if bin_capacity % pr == 0 && pr <= 50 {
        score -= 8.0; // capacity-fraction class
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // With many options, prefer tighter fills.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins tighter than average residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Early in stream: tolerate opening bins; late: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * progress;

    // New-bin candidate: neutral baseline with mild pressure toward reuse.
    if bin_residual == bin_capacity {
        score += 18.0 - (next_item_size as f64) * 0.05;
        if open_bins_count == 0 { score -= 30.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        // Gap is "dead" if the next item cannot use it.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (post_residual as f64);
        }
        // Very small gaps are almost certainly waste.
        if post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * (next_item_size as f64);
    }

    // Open-bin pressure: discourage spreading across many bins early,
    // but relax near the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Tight fit bonus: filling most of the residual is desirable.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 10.0;
    }

    // Prefer bins with residuals near the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins unless the current fit is poor.
        let poor_fit = post_residual > 30 || (next_item_size > 0 && post_residual < next_item_size);
        if poor_fit {
            score -= 5.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit with the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (-slack / 25.0).exp();
        } else {
            // Next item cannot fit here; penalize proportionally to wasted potential.
            let excess = (next_item_size - post_residual) as f64;
            score += 8.0 * (excess / 40.0).min(1.5);
        }
    }

    // Best-fit bias: small residuals are good, but tiny unusable residuals (<10) are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Reward tight fits relative to current item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across too many open bins; encourage filling existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins with residuals below the mean (denser bins) — keeps loose bins for later items.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_cost = 100.0 + 40.0 * (1.0 - fit_ratio);
        // If next item would exactly fill the new bin after this one, allow opening.
        if next_item_size > 0 && post_residual == 0 {
            return score - 10.0;
        }
        return new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: square of post-residual dampened.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 2.0);

    // Lookahead synergy: if next item fits perfectly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3;
        } else {
            // next item can't use this residual; mild penalty proportional to leftover
            score += 2.0;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when existing bins have decent mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / (bin_capacity as f64);
        // New bin penalty grows with open bins and mean residual availability.
        score += 30.0 + open_bins_count as f64 * 4.0 + pressure * 20.0 * (1.0 - progress);
        // Late in stream, consolidation matters more: slightly cheaper to open early.
        score -= progress * 10.0;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 5.0 + open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is close to item (relative fit quality).
    let fit_ratio = item_size as f64 / (bin_residual.max(1) as f64);
    score -= fit_ratio * 10.0;

    // Global balance: bins far from mean residual slightly discouraged to keep spread even.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Discourage leaving residuals in the awkward 1..=9 zone.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Base: quadratic in post_residual, weighted more heavily as stream progresses.
    let t = post / cap;
    let poly = t * t * (1.0 + progress) + t * (1.0 - progress * 0.5);
    let mut score = poly * cap * 0.5;

    // Reward tight fits: small post_residual relative to capacity.
    score -= (1.0 - t).powi(3) * 10.0;

    // Lookahead coupling: penalize post_residual that neither fits the next item
    // nor is small enough to be dead space; reward residual that exactly hosts next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item could reuse this bin; reward proportional to match quality
            let diff = (post - nxt) / cap;
            score -= 8.0 * (1.0 - diff).powi(2);
        } else {
            // dead space for next item: penalize proportionally to leftover gap
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Mean-residual coupling: penalize bins far from the mean residual (outliers
    // tend to become dead space), scaled smoothly by open bin count saturation.
    let open_f = open_bins_count.max(1) as f64;
    let sat = open_f / (open_f + 4.0);
    score += sat * (post - mean_residual).abs() * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make opening a new bin attractive only when progress is
    // early or the fit into existing bins is poor; penalize mid-stream proliferation.
    if bin_residual == bin_capacity {
        score = cap * 0.5 - 12.0 * (1.0 - progress);
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but dead space that is
    // too small to ever be reused is worse than moderate slack.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // tiny unusable sliver: heavy penalty
        score += 30.0;
    } else if pr == 0 {
        // perfect closure: strong reward
        score -= 60.0;
    }

    // Harmonic classes: classify post_residual by capacity fraction bands.
    // Classes near common item sizes (multiples of 10-ish) are more reusable.
    let class = pr / 10; // integer division threshold class 0..10
    score -= (class as f64) * 4.0;

    // Modulo arithmetic: residual congruent to small values mod 10 pairs
    // well with typical item granularity; congruent to 1..=4 mod 10 is dead.
    let m = pr % 10;
    if m >= 1 && m <= 4 && pr > 0 {
        score += 12.0;
    } else if m >= 8 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is a two-item closure candidate.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 15.0 - (gap as f64) * 0.3;
            if gap < 5 {
                score += 10.0; // leaves near-dead sliver after next item
            }
        } else {
            // next item won't fit here; slight penalty scaled by excess
            score += ((next_item_size - pr) as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // keep its score competitive but slightly worse than a good fit.
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64) * 0.1;
        // open new bins more readily late in the stream when many bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mean-residual coupling: when open bins are generally slack, waste here
    // is less costly; when mean residual is tight, preserve big residuals.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Mild pressure to consolidate: fewer open bins is better.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (min item size is 1, but very small gaps are still poor utilization).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Dead-space pressure relative to capacity: small post_residual is good.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: prefer spreading across fewer bins when many are open,
    // but reward using existing bins over opening new ones.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is more acceptable when few bins are open
        // and the mean residual of open bins is small (they are full).
        score -= 0.3 * mean_residual / bin_capacity as f64 * 10.0;
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in post_residual, mildly penalize leaving a gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Early in the stream, be more willing to open bins (exploration).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize bins whose residual deviates far below mean residual (wasteful spread).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with mild superlinearity to punish dead space.
    score += (post_residual as f64).powi(2) / bin_capacity as f64 * 0.5;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect follow-up placement
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            // small gap means next item still fits with little waste
            score -= 30.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted leftover
            let miss = next_item_size - post_residual;
            score += miss as f64 * 0.35;
        }
    } else {
        // last item: any placement is fine, slight preference for tight fit
        score -= 10.0;
    }

    // Relative-to-mean-residual coupling: bins already below mean residual are
    // "more used" — prefer filling them further to consolidate waste.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: opening a bin is penalized more when many bins
    // are open or stream is early (consolidation phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // allow opening a new bin if lookahead suggests a near-perfect future fit
        // in the current bin is impossible anyway (handled via miss penalty above).
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let fit_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += fit_ratio * fit_ratio * 30.0;

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the new bin would clearly be better (post_residual in new bin = C - item).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist; reward it when residuals are large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bin more attractive when mean residual across open bins is large (poor packing).
        score += (mean_residual / bin_capacity as f64) * 40.0;
        // Late in stream, prefer consolidating into open bins.
        score += progress * 20.0;
        // More open bins -> prefer reusing one.
        score += (open_bins_count as f64) * 2.0;
    }

    // Lookahead coupling: penalize leaving post_residual that cannot fit the next item
    // (wasted dead space), reward post_residual that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Prefer bins with residual already below mean (denser bins).
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: reward tight fit via smooth non-linear function of post_residual.
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = 30.0 * x * x + 10.0 * x; // convex penalty on wasted space

    // Non-linear coupling: as stream progresses, dead space becomes more costly.
    score += 40.0 * progress * x * x;

    // Reward bins whose residual is close to the item (smooth best-fit kernel).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 20.0 * (-fit_gap * fit_gap * 20.0).exp();

    // Penalize bins far from mean residual (fragmentation smoothing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 18.0 * (-gap * gap * 30.0).exp();
        // If next item is large and won't fit here, mild penalty for hogging this bin.
        if next_item_size as f64 > pr {
            score += 5.0 * progress;
        }
    }

    // New-bin candidate handling: empty bin gets a smooth opening cost,
    // decreasing with progress and with number of open bins relative pressure.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Slight preference for fewer open bins when fit is loose.
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits using harmonic residual classes.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 70.0;
    }

    // Harmonic class: post_residual bucketed by integer division thresholds.
    let class = post_residual / 15; // 0..=6 harmonic band
    score -= (6 - class.min(6)) as f64 * 8.0;

    // Penalize dead space that no plausible item (1..=80) can use efficiently.
    if post_residual > 20 && post_residual < 31 {
        score += 25.0; // awkward band: too small for many items, too big to waste
    }

    // Lookahead coupling: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_leftover = post_residual - next_item_size;
        score -= 40.0 + (chain_leftover as f64).min(30.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slightly penalize blocking good bins.
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 - mean_residual;
        score = 100.0 + poor_fit.max(0.0) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin is fine if item itself is large relative to capacity.
            score -= item_size as f64 * 0.2;
        }
        if fitting_bins_count == 0 {
            score -= 150.0; // no open bin fits: must open new bin
        }
        if post_residual as f64 > mean_residual + 10.0 {
            score += 30.0; // item leaves lots of waste; avoid opening for it
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    // Slight preference for bins with below-average residual (fill emptier-first inverse:
    // favor bins already tighter than average to concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // Small gap: likely unusable unless a tiny item arrives later.
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    } else {
        // Usable residual: reward proportionally to tightness of fit.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // If the next item can exactly fill this bin's post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If the next item would NOT fit in the leftover space, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few bins,
    // opening a fresh bin (residual == capacity) is more acceptable.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bin count.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 4.0;
        // If nothing else fits well, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Existing bin: mild bonus for using it when many bins are open.
        score -= open_bins_count as f64 * 1.5;
    }

    // Prefer bins whose residual is below the mean (tighter bins get packed first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near match: next item fits with small slack -> moderate reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.35 * slack;
    }
    // Next item won't fit here: penalize proportionally to wasted lookahead potential.
    else if next_item_size > 0 {
        let miss = (next_item_size - post_residual) as f64;
        score += 0.25 * miss;
    }

    // Penalize residuals that are too small to ever hold a meaningful item (dead space).
    if post_residual < 10 {
        score += 12.0 + (10 - post_residual) as f64;
    }

    // Prefer tight fits relative to the mean residual of open bins.
    let tightness = (post_residual as f64 - mean_residual).abs();
    score += 0.12 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when decent open bins exist, more so early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Mild bonus for filling bins deeply (high fill ratio).
    score -= 0.08 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for any plausible future item (min size 1,
    // but typical items are larger) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; competition resolves via tightness.
        score += 1.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward;
    // if next item cannot fit post residual, mild penalty proportional to gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap.min(40.0);
        }
    }

    // Time horizon: late in the stream, avoid opening new bins; prefer packing into
    // existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly as stream progresses and as open bins grow.
        score += 6.0 + 25.0 * progress + 1.5 * (open_bins_count as f64).ln().max(0.0);
        // But if no existing bin fits well (this call still happens for empty bin), the
        // tightness bonus is zero, so opening is favored only when fits are poor.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        score -= 4.0 * progress;
    }

    // Global state: if mean residual across open bins is large, we have slack overall;
    // prefer consolidating into bins with below-mean residual (this bin's residual small
    // relative to mean means it's already partly filled — favor filling it further).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 2.0 * (1.0 - rel);
        } else {
            score += 1.0 * (rel - 1.0).min(2.0);
        }
    }

    // Fragmentation guard: heavily penalize leaving residuals in the awkward 20..40 band
    // late in the stream (hard to fill).
    if post_residual >= 20 && post_residual <= 40 && progress > 0.6 {
        score += 5.0 * progress;
    }

    // Small stabilizing term favoring more complete bins as open bin count grows.
    score -= 0.3 * (open_bins_count as f64) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 + 3.0 * progress);
    score += 20.0 * poly;

    // Penalize wasted residual scaled by how full the stream is
    score += (pr_norm * pr_norm) * 10.0 * (0.5 + progress);

    // Reward tight fits: subtract based on item fraction of capacity
    let item_frac = item_size as f64 / cap;
    score -= 15.0 * item_frac * item_frac * (1.0 + progress);

    // Last-chance bin bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless residual would be very small
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 5.0 * (post_residual as f64 / cap);
    }

    // Lookahead: reward if next item fits in the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Coupling with mean residual across open bins
    score += 0.05 * (mean_residual - pr).abs();

    // Mild penalty for too many open bins late in stream
    score += 0.5 * (open_bins_count as f64) * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction

    // Penalize residuals that are too small to ever fit typical items (1..100)
    if post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 50 {
        score += 8.0;
    }

    // Modulo arithmetic on post_residual: harmonic classes of 10
    let class = post_residual / 10;
    let phase = post_residual % 10;
    // Prefer residuals aligned to multiples of 10 (likely future fits)
    score -= (phase == 0) as i32 as f64 * 5.0;
    score += (class % 3 == 1) as i32 as f64 * 2.0;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * (next_item_size as f64);
        } else {
            // next item won't fit: waste potential is post_residual itself
            score += 10.0 * (1.0 - (next_item_size as f64 - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a great fit
    if bin_residual == bin_capacity {
        score += 40.0;
        // allow new bin if item is large relative to capacity
        score -= (item_size as f64 / cap) * 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tight fit reward: item fills most of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 20.0;

    // Stream progression: early on, be more conservative (keep bins balanced)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - frac * cap).abs() * 0.05 * (1.0 - progress);

    // Prefer bins with residual close to item (minimize fragmentation)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are "dead" — penalize them heavily.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual > 0 && post_residual <= 10 {
        score -= 30.0;
    }

    // If the next item fits exactly in post_residual, big reward:
    // this bin becomes perfectly filled by the lookahead pair.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap < dead_threshold {
            score += 20.0; // lookahead would leave dead space, discourage
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many
    // bins are open and residuals are healthy; cheap when open bins are
    // fragmented.
    if bin_residual == bin_capacity {
        // brand-new empty bin candidate
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64;
        score = 55.0 + pressure * 2.0 - fragmentation * 20.0;
        // If the only fitting bin is this new one, it must be attractive.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    // Slight bias toward bins with residual close to item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in stream, be greedy; later, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_w = 0.5 + 1.5 * progress;

    // Core: reward exact 2-step lookahead match (post_residual == next_item_size).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        // Perfect match bonus: next item exactly fills this bin.
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        } else {
            // Penalize proportional to how "wasted" the residual is vs lookahead.
            score += 0.6 * gap * progress_w;
            // Extra penalty if post_residual is small but unusable by next item.
            if post_residual < next_item_size && post_residual > 0 {
                score += 8.0 * (post_residual as f64 / next_item_size as f64);
            }
        }
    }

    // Reward tight fits relative to bin capacity (small post_residual overall).
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 100.0 * progress_w;

    // Relative to mean residual: bins already tight should be preferred for filling.
    let rel = post_residual as f64 - mean_residual;
    score += 0.25 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 * 1.2;
        // Attractive if lookahead matches a fresh bin well (item + next fill it).
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 2 {
            score -= 45.0;
        }
        // Early stream: opening bins is cheaper.
        score -= 30.0 * (1.0 - progress);
        // Many open bins: discourage more sprawl.
        score += 2.0 * open_bins_count as f64;
        // If this bin would be a perfect fit for the item alone, still allow.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space: residuals that are too small to hold
    // a typical future item are wasted. Reward bins whose post_residual is either
    // near zero or large enough to stay useful.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;  // marginal dead space
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 3.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        // But if the new-bin candidate would be much better, allow opening.
        if post_residual > bin_capacity / 2 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit, or when open bins are all nearly full.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin, scaled by how many good alternatives exist.
        score = (bin_capacity - item_size) as f64; // residual left in fresh bin
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else {
            // Compare against mean fit quality of open bins: if mean residual is
            // small (bins nearly full), opening is relatively attractive.
            let openness = mean_residual / bin_capacity as f64;
            score -= 30.0 * (1.0 - openness);
            if fitting_bins_count == 1 {
                score += 6.0; // discourage stealing the single fitting bin
            }
            // Late in the stream, prefer consolidating into existing bins.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * progress;
        }
        // Too many open bins: penalize spreading further.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild global pressure: when many bins are open with high mean residual,
    // prefer placements that reduce dispersion (fill the fullest bins first).
    if bin_residual < mean_residual as u32 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling: penalize small-but-nonzero post_residual (dead space)
    // via a quadratic bowl centered near zero, rewarding either tight fits or
    // large remaining space.
    let pr_norm = pr / cap;
    score += 8.0 * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Stream progress coupling: later in the stream, tighten preference for
    // compact placements (small post_residual weighted more heavily).
    score += progress * pr * pr / cap;

    // Lookahead: reward leaving room for the next item, with smooth falloff.
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let gap = pr - nis;
        let match_term = (gap / cap).abs();
        score -= 6.0 * (-6.0 * match_term).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading many open bins; reward consolidation.
    score += 0.05 * open_bins_count as f64;

    // Distance from mean residual: prefer bins deviating smoothly (quadratic).
    score += 0.01 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and tiny remainders are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 8.0;
    } else if pr <= 30 {
        score += 6.0;
    } else {
        score += 14.0; // large dead space
    }

    // Modulo classes: remainders divisible by common small sizes are reusable.
    if pr > 0 {
        let reusable = (pr % 10 == 0) as f64 * 10.0
            + (pr % 20 == 0) as f64 * 6.0
            + (pr % 25 == 0) as f64 * 5.0
            + (pr % 5 == 0) as f64 * 3.0;
        score -= reusable;
    }

    // Lookahead: reward if next item fits exactly in post_residual (harmonic pair).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use leftover: penalize proportionally to waste
            score += 5.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Tightness reward: filling a bin nearly to capacity is good.
    let fill = (bin_residual - post_residual) as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // among many fitting bins, prefer the tightest (implicit via post_residual),
        // but add mild congestion penalty scaled by open bins
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // Progress-based calibration: early in stream, be picky about waste;
    // late in stream, accept slightly worse fits to avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate: neutral-ish base so it wins only when all open bins are bad.
    if bin_residual == bin_capacity {
        score = cap - 0.5 * (item_size as f64) + 0.3 * mean_residual
            - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual <= 20 {
        // Moderately awkward gap.
        score += 8.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.35 * tightness;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 0.4 * next_item_size as f64;
        } else {
            // Next item won't fit here: slight penalty for leaving a large gap.
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Open-bin pressure: prefer spreading across fewer bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (more filled bins).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count == 0 { -20.0 } else { 15.0 + 0.5 * open_bins_count as f64 };
        score += poor_fit_pressure;
        // A fresh bin is good if the item is large (small post_residual waste).
        score += 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item: reward tight-but-usable fits
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space: post_residual cannot fit the next item
        score += 15.0 + 0.2 * (post_residual as f64);
    }

    // Penalize being far from mean residual (outlier waste)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fit_ratio;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0; // discourage new bin when an open bin serves the lookahead too
        }
        if open_bins_count > 0 && item_size <= 50 {
            score += 20.0; // small items should go into existing bins
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strongly favor tight fits: square the post-residual waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward bins that can also host the next item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * progress;
    }

    // Penalize bins that become near-empty slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        // Penalize opening a new bin proportional to residual left behind,
        // softened when many bins are open (consolidation pressure) or late in stream.
        score += 15.0 + waste * 0.5 - (open_bins_count as f64) * 0.4 - 5.0 * progress;
        // If a lookahead item could fill the new bin's remainder, reward it.
        if next_item_size > 0 && waste >= next_item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (balance pressure).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Mild preference for reusing bins as the stream progresses (limit bin sprawl).
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 1.0 + t * (2.0 - 3.0 * t) + t * t * (1.5 - t);
    score += norm_pr * norm_pr * 20.0 * poly;

    // Reward tight fits, stronger as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * t);

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap) * (0.5 + t);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Penalize waste relative to mean residual of open bins.
    score += (pr - mean_residual).abs() * 0.15;

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild pressure against proliferating bins early.
    score += open_bins_count as f64 * 0.05 * (1.0 - t);

    // New-bin candidate penalty: prefer filling existing bins unless residual is tiny.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (small, or large enough for a mid-size item) get rewarded.
    let pr = post_residual;
    let cap = bin_capacity;

    // Perfect fit reward.
    if pr == 0 {
        score -= 1000.0;
    }

    // Class A: tiny dead space (pr <= 10) — nearly perfect packing.
    if pr > 0 && pr <= 10 {
        score -= 60.0;
    }

    // Class B: large leftover that can still host a big item.
    if pr >= 40 {
        score -= 15.0;
    }

    // Class C: awkward middle leftovers (11..=25) — hard to fill, penalize.
    if pr >= 11 && pr <= 25 {
        score += 25.0;
    }

    // Integer-division harmonic bands on post_residual: quantize leftover space
    // into fifths of capacity; bins in the lowest band are best.
    let band = pr / (cap / 5).max(1);
    score -= (5 - band.min(5)) as f64 * 4.0;

    // Lookahead coupling: reward if the next item fits exactly in the leftover.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // Harmonic class of the slack after next placement.
            if slack <= 10 {
                score -= 80.0;
            } else if slack <= 25 {
                score += 10.0;
            }
        } else {
            // Next item won't fit here; mildly penalize hoarding space.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are
    // already fragmented or the item simply doesn't compress well.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap as f64;
        let pressure = open_bins_count as f64;
        // Opening a new bin is penalized normally, but less when open bins
        // have low mean residual (little room left anywhere).
        score = 50.0 + pressure * 2.0 - fragmentation * 40.0;
        if pr == 0 {
            score -= 1000.0; // unreachable, keeps symmetry
        }
        if next_item_size > 0 && next_item_size <= cap && cap - next_item_size >= item_size {
            score -= 20.0; // new bin leaves room for a follow-up
        }
        if fitting_bins_count <= 2 {
            score += 30.0; // prefer reusing scarce fitting bins
        }
    }

    // Mild stream-phase modulation: pack tighter early, allow slack later.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (below min item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Penalize leaving gaps that no small item can usefully fill later.
    if post_residual > 0 && post_residual < item_size {
        score += (item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline with mild openness, chosen only if fits are bad.
    if bin_residual == bin_capacity {
        score = 50.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 400.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let gap = post_residual as f64 - nxt;
            if gap <= 10.0 {
                score -= 250.0 - gap * 10.0;
            } else {
                score -= (100.0 / gap).min(50.0);
            }
        } else {
            // next item cannot fit here: penalize proportionally to the mismatch
            let miss = nxt - post_residual as f64;
            score += miss * 2.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better reuse targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Slight progression bias: late in the stream, prefer tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    // Penalize the brand-new empty bin candidate unless it clearly beats reuse
    // (i.e., only attractive when item is large relative to all residuals).
    if bin_residual == bin_capacity {
        score += 150.0 - (item_size as f64 * 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);

    let mut score = post;

    // Reward tight fits: the fuller the bin relative to the item, the better.
    score -= 8.0 * (item / res);

    // Penalize quadratic dead space (small leftovers are fine, large ones waste capacity).
    score += 0.15 * (post * post) / cap;

    // Lookahead coupling (k=2): reward bins whose leftover can host the next item,
    // penalize leftovers that are just barely too small for it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - post / cap);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: mild structural penalty so existing bins are preferred,
    // partially relieved for large items where a fresh bin is naturally attractive.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
        score -= 0.05 * item;
    }

    // Prefer bins whose current residual is close to the item size (minimal slack mismatch).
    let dev = (res - item).abs();
    score += 0.05 * dev;

    // Dynamic time horizon: later in the stream, penalize divergence between this bin's
    // post-residual and the global mean residual (keeps the fleet homogeneous late on).
    score += 2.0 * t * (mean_residual - post).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual); late, tolerate slack less too.
    let norm_pr = pr / cap;
    let coupling = norm_pr * (1.0 + 2.0 * progress * progress);
    score += 4.0 * coupling;

    // Penalize residuals that cannot fit the lookahead item (smooth falloff).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 6.0 * gap * gap;
        // Reward residual that fits next item, scaled by how snugly.
        let snug = (pr - next_item_size as f64).abs() / cap;
        score -= 3.0 * (1.0 - snug) * (pr >= next_item_size as f64) as i32 as f64;
    }

    // Last-chance bin bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Discourage spreading thin across many open bins late in the stream.
    score += 0.05 * (open_bins_count as f64) * progress;

    // Mild preference toward bins with residual above mean (keeps balance).
    score += 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "usable" classes
    // (residuals that typical small items can still fill) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // class = floor(sqrt(pr)) harmonic banding
        let band = (pr as f64).sqrt().floor() as u32;
        score -= band as f64 * 0.8;
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Modulo coupling: post_residual that is a multiple of common small sizes is reusable
    for m in [10u32, 20, 25, 50] {
        if pr >= m && pr % m == 0 {
            score -= 4.0;
        }
    }

    // Penalize dead space: post_residual too small for the smallest item (1)
    // but with interface range 10..80 penalize residuals < 10 strongly
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap_f);
        } else {
            // next item cannot follow here; penalize proportionally
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it if mean residual across open bins is very fragmented.
    if bin_residual == bin_capacity {
        let base = 45.0 + 0.35 * mean_residual;
        // early stream: opening bins is cheaper; late stream: prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + 20.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64).ln();
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin guarantees fit for next item too
            score -= 8.0;
        }
    }

    // Mild fragmentation penalty relative to mean residual
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any gap too small for the smallest plausible
    // next item (or the actual lookahead item) is essentially wasted capacity.
    let min_useful = if next_item_size > 0 { next_item_size.min(30).max(10) } else { 10 };
    if post_residual < min_useful {
        // Dead space penalty: quadratic in how close the gap is to unusable.
        score += 25.0 + 0.5 * (min_useful - post_residual) as f64;
    }

    // Reward very tight fits (post_residual near zero is fine, near-perfect fill).
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize mid-range gaps that are large enough to invite an item but
    // likely to fragment (post_residual in awkward zone above min_useful).
    if post_residual >= min_useful && post_residual < 2 * min_useful {
        score -= 3.0; // still useful for the lookahead item: good
    }

    // Coupling with lookahead: if this placement leaves room for exactly the
    // next item, strongly reward the chain fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
        // Extra reward if after placing the next item the bin would be near full.
        if post_residual - next_item_size <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Lookahead won't fit here; slight penalty to prefer bins that chain.
        score += 2.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; this makes the new-bin candidate less attractive.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well (its raw post_residual is
    // naturally high, plus a mild penalty so it loses to decent fits).
    if bin_residual == bin_capacity {
        score += 10.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is below the mean (filling the emptier-ish
    // bins consolidates space into fewer, fuller bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // 2-step lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, penalize score proportional to tightness.
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 150.0 - chain_tightness * 2.0;
        } else {
            // Next item won't fit here; penalize proportional to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare against mean residual across open bins: bins with less residual than
    // average are "tighter" and should be preferred to consume them first.
    let residual_diff = post_residual as f64 - mean_residual;
    score += residual_diff * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Make the empty bin moderately attractive by default,
    // but less so than a tight existing fit.
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin: neutral residual score.
        score = bin_capacity as f64 * 0.35; // ~35 baseline
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // If many bins are open, discourage opening yet another one.
        score += open_bins_count as f64 * 3.0;
        // If this is the last chance elsewhere, opening new bin is fine fallback:
        // keep score moderate so tight fits still beat it.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score += 100.0; // (defensive; empty bin has fitting_bins_count >= 1 anyway)
        }
    }

    // Penalize creating large awkward dead space that few typical items could use.
    if post_residual > 0 && post_residual < 10 {
        // Small unusable slivers are bad unless they exactly match next item (already rewarded).
        score += 20.0;
    }

    // Slight preference to fill bins with larger residual first when ties occur,
    // to consolidate open bins and allow closing emptier ones.
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 6.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 && next_item_size > 0 {
            score -= 10.0; // existing bins have room; new bin is wasteful
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    } else {
        // Favor bins whose residual deviates usefully from the mean (diversity of gaps).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Time horizon: early in stream, be conservative (favor compacting);
    // late in stream, just close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // Small jitter-free tiebreak: prefer bins with less residual.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth polynomial base: reward small residuals (good packing) with a cubic coupling
    let base = post * (1.0 + 0.9 * norm_post + 0.6 * norm_post * norm_post);

    // Stream-progress coupling: later in stream, tighten preference for tight fits
    let prog_coupling = -2.5 * progress * (cap - post) * (norm_post * 0.5 + 0.1);

    // Dead-space penalty: residual too small to be useful (smooth via sigmoid-like term)
    let dead = 30.0 / (1.0 + (post / 12.0).exp()) - 15.0;

    // Last-chance bonus: strongly favor the only bin that fits
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -60.0
    } else {
        0.0
    };

    // Lookahead: reward if next item fits in post_residual
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= post {
        -12.0 * (1.0 - post / cap)
    } else if next_item_size > 0 {
        4.0 * (post / cap)
    } else {
        0.0
    };

    // New-bin candidate: penalize mildly so we prefer good fits, but allow when open bins are fragmented
    let new_bin = if bin_residual == bin_capacity {
        18.0 + 10.0 * progress - 3.0 * mean_residual / cap
    } else {
        0.0
    };

    // Congestion: many open bins -> prefer filling existing ones
    let congestion = if bin_residual != bin_capacity {
        -1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post)
    } else {
        0.0
    };

    base + prog_coupling + dead + last_chance + lookahead + new_bin + congestion
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: how well post_residual divides into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let harmonic = (cap / (pr + 1.0)).sin().abs(); // small when pr near a divisor-friendly residual
    score += harmonic * 20.0;

    // Modulo classes on post_residual relative to capacity / common item sizes
    let m = post_residual % 10;
    score += m as f64 * 1.5; // prefer residuals that are multiples of 10

    // Integer-division threshold: large post_residual chunks are reusable
    let chunks = post_residual / 25;
    score -= chunks as f64 * 8.0;

    // Next-item lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here; penalize leaving awkward residual
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it if it fits
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: prefer tighter fit
        score += (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else {
            // discourage opening new bin if an open bin gives small residual
            score += mean_residual * 0.5;
        }
        // late in the stream, prefer reusing open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
    }

    // Penalize dead space relative to mean residual
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 {
        score += 45.0 + 2.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small waste relative to item size).
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Lookahead coupling: keep room for the next item if possible.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 5.0; // this bin likely becomes dead space after placement
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64 + 10.0 * progress;
        // But if all open bins would leave bad fits, allow new bin to win.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 30.0;
        }
    } else {
        // Existing bins get a mild baseline preference.
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: mild reward, closer match better.
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover space: penalize dead space,
            // especially small unusable slivers.
            let excess = (next_item_size - post_residual) as f64;
            score += 0.5 * excess;
        }
    }

    // Penalize small nonzero residuals (unusable slivers) with a non-linear term.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Compare against mean residual: prefer bins already tighter than average
    // (compact placement), penalize wasting a very large residual on a small item.
    let residual_f = post_residual as f64;
    if residual_f > mean_residual {
        score += 0.3 * (residual_f - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - residual_f);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only allow it
    // when no open bin offers a decent fit. Base penalty for a fresh bin:
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if the item is large (hard to place later), opening fresh is fine.
        if item_size >= bin_capacity / 2 {
            score -= 120.0;
        }
        // If many bins are open and mean residual is large, discourage new bins.
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 100.0;
        }
    }

    // Mild late-stream tightening: as the stream progresses, be greedier
    // about filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * residual_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to ever be useful (below min item size 1 -> none,
    // but tiny residuals relative to typical items are waste).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item cannot use leftover space
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when this bin would
    // leave a large unusable gap or the bin is nearly full.
    if bin_residual == bin_capacity {
        // New bin: base cost plus pressure from open bins count.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // If current item is large, a fresh bin is fine.
        if item_size >= 60 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Global residual state: if mean residual is high, spread items less aggressively.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild time-horizon modulation: early stream, be exploratory (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * fit_ratio * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.5 * progress) - 12.0 * norm_post * (1.0 - norm_post) * (1.0 - progress);

    // Penalize near-full bins slightly less as stream ends (waste matters less)
    score += 8.0 * norm_post * norm_post * progress;

    // Reward tight fits: small post_residual relative to item size
    score -= 6.0 * (item_size as f64) / (bin_residual as f64 + 1.0);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for spreading across many open bins
    score += 0.4 * open_bins_count as f64 * (0.3 + progress);

    // Deviation from mean residual: prefer bins close to mean to keep balance
    score += 2.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands on
    // "coarse" residue classes (large unusable gaps) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement; quantize into 20 harmonic buckets.
    let frac = post / cap;
    let bucket = (frac * 20.0).floor() as i32;

    // Dead-space penalty grows quadratically for small leftovers (hard-to-fill).
    if post > 0 {
        score += (20.0 - frac * 20.0).powi(2) * 0.35;
    } else {
        // Perfect fit is heavily rewarded.
        score -= 60.0;
    }

    // Modulo-class logic: leftovers divisible by common item sizes (10, 20, 25, 50)
    // are reusable; reward them.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 8.0;
    }
    if pr > 0 && pr < 10 {
        // Tiny sliver: nearly dead space.
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin; if next item cannot fit, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            if slack == 0.0 {
                score -= 45.0;
            } else if slack <= 10.0 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
            // Harmonic match: next item divides post residual evenly.
            if (post_residual % next_item_size) == 0 {
                score -= 12.0;
            }
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: prefer keeping it closed early; allow opening later
    // when open bins are congested (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (cap - mean_residual) / cap;
        score = cap - 30.0 * progress + 25.0 * congestion;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Mild tie-break toward consolidating fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Prefer bins whose residual is close to the item size (minimal waste).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * waste;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity and gets penalized.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no existing bin fits well, allow opening new bins late in stream.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item can exactly use post_residual, reward heavily.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Slight progression term to stabilize late-stream behavior.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize wasted residual quadratically, normalized by capacity
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste * waste;
    }

    // 2-step lookahead: if next item fits perfectly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // reward if next item can also fit here later (chained packing)
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving residual that blocks nothing useful
            score += 30.0;
        }
    }

    // Compare post_residual against mean residual: avoid making bin much worse than average
    score += 5.0 * (post_residual as f64 - mean_residual).max(0.0) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 150.0;
        // if current item is large relative to capacity, new bin is attractive
        score -= 1.5 * item_size as f64;
        // if few bins fit the item, opening a new bin is more acceptable
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if fitting_bins_count == 1 {
            score -= 180.0;
        }
        // early in stream, allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Mild bonus for consolidating into bins with low residual already
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * 18.0;

    // Penalize dead space that no plausible future item can use.
    if post > 0.0 {
        if next_item_size > 0 && (post_residual < next_item_size) {
            score += (next_item_size as f64 - post) * 0.55;
        }
        // Small residuals are likely unusable; large ones keep options open.
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Lookahead pairing: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer filling existing ones, discourage spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += crowd * (0.4 + 0.8 * progress);

    // Deviation from mean residual: prefer bins whose residual is below average
    // (concentrate waste in few bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 10.0;

    // New-bin candidate handling: empty bin gets baseline penalty unless
    // no reasonable alternative exists (post_residual here == cap - item).
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 4.0; // existing bins likely fine
        }
    }

    // Mild time-horizon annealing: early on be conservative, later exploit tight fits.
    score -= tightness * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core waste term with non-linear (quadratic) coupling on normalized residual.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Penalize dead space that is too small to be useful (unusable sliver).
    let small_gap = post < next_item_size as f64 && next_item_size > 0.0;
    if small_gap {
        score += 6.0 + 10.0 * norm_post; // residual below next item's need is wasted
    }

    // Reward when the next item can fit into the post residual (chaining).
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let snug = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 4.0 + 8.0 * snug * snug;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress);
        score -= 6.0 * progress;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.15 * open_bins_count as f64 * norm_post;

    // Tight fit reward relative to mean residual across open bins.
    if post < mean_residual {
        score -= 2.0 * (mean_residual - post) / cap;
    } else {
        score += 1.5 * (post - mean_residual) / cap;
    }

    // New empty bin candidate: penalize mildly so it's chosen only for poor fits,
    // with penalty relaxing late in the stream when closing bins is fine.
    if bin_residual == bin_capacity {
        let relax = 0.5 + 0.5 * progress;
        score = cap + 8.0 * relax - 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction classes
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / 10) as f64; // decade class 0..10

    // Reward small post_residual strongly (best-fit core with non-linear coupling)
    score -= (post_residual == 0) as f64 * 1000.0;
    score -= (pr * pr) / (c * c) * 60.0;

    // Penalize "dead" residuals that few item sizes can use (harmonic classes):
    // residuals in (0,10) are unusable for any item; 10..=19 only usable by tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Modulo-arithmetic coupling: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be exactly filled later.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 50 == 0 { score -= 5.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 1.5;
        } else {
