    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we prefer good existing fits,
    // but allow opening a new bin when existing residuals are dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
        // if mean residual across open bins is small (mostly dead space), new bin is fine
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins (prefer filling existing ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_residual != bin_capacity) as i32 as f64;

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Class-based tie-breaker: prefer bins whose decade class matches residual
    score -= class * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to host even the
    // smallest plausible future item (<= 10) are pure waste. Quadratic wall.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual <= 30 {
        // Mid-range gaps are semi-usable; mild penalty decaying with size.
        score += 0.35 * (30 - post_residual) as f64;
    } else {
        // Large residual is valuable: reward keeping big gaps alive.
        score -= 0.25 * (post_residual as f64 - 30.0);
    }

    // Perfect fit bonus: filling a bin exactly is free.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item lookahead: if the next item fits exactly into
    // the post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this gap -> gap risks becoming dead space.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible (small unusable residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 25.0;
        } else {
            score += 20.0; // poor fit in the only bin: prefer new bin
        }
    }

    // New-bin candidate handling: an empty bin is a safe fallback. Give it a
    // moderate score so it wins only when all fits are bad, but loses when
    // any decent fit exists. Pressure grows with open_bins_count to reuse.
    if bin_residual == bin_capacity {
        score = 45.0 + 3.0 * open_bins_count as f64;
    } else {
        // Open-bin pressure: reusing existing bins is cheaper than opening.
        score -= 1.5 * open_bins_count as f64;
    }

    // Early in the stream, be slightly more willing to open bins for clean
    // structure; late in the stream, squeeze everything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: waste = 0 over two items.
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits again; reward closeness to exact fill.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize dead space relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: prefer leaving small residuals
    // (tight packing) but not so small they become dead space.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Penalize very small unusable residuals (dead space < 10).
    if pr > 0.0 && pr < 10.0 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin late in stream when many bins already open and fit is loose.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 * 1.5 && open_bins_count > 2 {
            score -= 10.0 + 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect-fit style bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Lookahead coupling: reward if next item can use the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead space if next item cannot fit in the remainder.
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins where this item is a better relative fit.
        score += 2.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins far from the mean residual (favor consolidation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.20 * dev.abs();

    // Slightly favor fuller bins (lower residual) globally.
    score += 0.05 * bin_residual as f64;

    // Time horizon: early on, be conservative (penalize near-empty usage);
    // late in the stream, pack aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a moderate penalty that
    // shrinks as the stream progresses or when no good fit exists.
    if bin_residual == bin_capacity {
        let mut open_penalty = 14.0;
        if fitting_bins_count == 0 {
            open_penalty -= 20.0; // nothing else fits: open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            open_penalty -= 4.0; // large pair coming, fresh bin useful
        }
        score += open_penalty * (1.0 - 0.5 * progress);
    }

    // Mild penalty for many open bins (encourage closing out bins).
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Small deterministic tie-breaker by bin residual.
    score += 0.001 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits: low post_residual relative to item size.
    score -= 30.0 * (1.0 - post / cap) * fit;

    // Smooth non-linear coupling: tightness valued more as stream progresses.
    let tight = (1.0 - post / cap).max(0.0);
    score -= 25.0 * progress * tight * tight;

    // Penalize dead space: small residuals that likely fit nothing.
    let dead = (1.0 - post / cap) * (post / cap);
    score += 15.0 * dead * (1.0 - fit);

    // Last-chance bonus: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate: discourage unless residual is very large / bin is empty
    // and current fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if post / cap < 0.35 {
            score += 25.0 * (0.35 - post / cap);
        }
    }

    // Lookahead: reward bins whose post-residual accommodates the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - progress * 0.5);
    }

    // Mild pressure toward using many open bins efficiently.
    score -= 0.5 * (mean_residual / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (harmonic classes on post_residual)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual <= 20 {
        score -= 120.0;
    } else if post_residual <= 30 {
        score -= 40.0;
    }

    // Penalize dead space that cannot fit the next item's size class
    if next_item_size > 0 {
        let nxt = next_item_size.min(bin_capacity);
        if post_residual > 0 && post_residual < nxt {
            // dead space for the lookahead item
            score += 0.6 * (nxt - post_residual) as f64;
        } else if post_residual >= nxt {
            score -= 0.3 * nxt as f64; // reward chains with next item
        }
        // modulo / integer-division class coupling between post_residual and next item
        let pr = post_residual as i64;
        let ni = nxt as i64;
        let gap = (pr % ni.max(1)) as f64;
        score -= 0.15 * gap;
    } else {
        // last item: strongly prefer zero residual
        score += 0.0;
        if post_residual == 0 { score -= 500.0; }
    }

    // Last-chance bin: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless
    // no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 150.0;
        // cheaper to open if current bins have poor fits (large mean residual mismatch)
        let waste = (mean_residual - item_size as f64).abs();
        score -= 0.5 * waste;
        // late in stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 * progress;
        // many open bins already -> discourage opening more
        score += 5.0 * open_bins_count as f64;
    }

    // Prefer bins with less residual overall (fill fuller bins first)
    score += 0.05 * (bin_residual as f64 - post_residual as f64).signum() * 0.0;
    score += 0.02 * (bin_capacity as f64 - bin_residual as f64);

    // Harmonic class penalty: residuals in awkward classes (just below common item sizes)
    for k in 1..=4u32 {
        let cls = (bin_capacity / (k + 1)) * k / 2;
        if post_residual > 0 && post_residual <= cls && post_residual + 10 > cls {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1).max(next_item_size.min(item_size)) {
        // Unusable sliver: heavy penalty scaled by how close it is to a "just barely unusable" gap.
        score += 40.0 + (bin_capacity as f64 - post_residual as f64) * 0.2;
    }
    // Penalize any residual that cannot fit the lookahead item (k=2 lookahead dead zone).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
    }
    // Reward a perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins, opening new ones is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);
    score += pressure;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to mean residual space
    // (i.e., existing bins would be shredded) or late in the stream with tight bins.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let tightness = mean_residual / bin_capacity as f64;
        let base = 45.0 + 0.5 * post_residual as f64;
        let discount = 55.0 * (fit_ratio - 0.35).max(0.0) * (1.0 - tightness).max(0.0);
        score = base - discount + pressure;
    }

    // Mild preference for bins whose residual is close to the item (best-fit sharpening).
    score += 0.15 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: keep post_residual small (tight fit).
    score -= (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward post_residual exactly matching next_item_size,
    // or slightly above it (next item fills this bin nearly perfectly).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 60.0; // perfect 2-step match
            } else if slack <= 10.0 {
                score -= 45.0 - slack * 2.0; // near-perfect follow-up fit
            } else {
                // leftover after next item; penalize proportionally
                score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // next item cannot use this bin; small penalty for wasted residual
            score += 5.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and lookahead suggests a fresh bin is useful.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > bin_capacity as f64 * 0.6;
        if bad_fit {
            score -= 10.0; // fresh bin attractive when item is small relative to capacity
        } else {
            score += 30.0; // discourage opening new bin for good fits
        }
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 15.0; // big item coming: keep capacity free
        }
    }

    // Mild stream-progression pressure: consolidate more as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference to fill already-open bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Reward tight fits proportionally to how small the dead space is
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 40.0;

        // If the leftover dead space is unusable for the next item, penalize extra
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
        // If next item fits exactly into the leftover, reward strongly
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item could fit in this bin's residual after placement,
    // slight reward for preserving that possibility
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // High mean residual => plenty of room, discourage new bin
        score += 60.0 + crowding * 50.0 - progress * 10.0;
        // If few bins can fit the item, new bin is more acceptable
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    if open_bins_count > 1 && mean_residual > bin_capacity as f64 * 0.5 {
        score += 3.0;
    }

    // Prefer filling bins with larger residual less (waste less space)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 + 0.8 * progress) + 0.35 * x * (1.0 - progress);

    let mut score = pr + 12.0 * poly;

    // Reward tight fits, stronger as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 30.0 * progress);

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - x) * (1.0 + progress);
    }
    // Reward leaving room exactly for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0 + 10.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Mild pressure toward consolidation via mean residual coupling
    score -= 0.05 * mean_residual * (1.0 - progress) / (1.0 + open_bins_count as f64);

    // New-bin candidate: make it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score = pr + 20.0 * (1.0 - crowded) * (1.0 - progress) - 15.0 * crowded * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (quadratic waste penalty).
    score += (post_residual as f64 / cap).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: residual buckets by integer division thresholds.
    // Residuals in (0..10] are near-dead space -> penalize creating them,
    // unless the next item can fill them.
    let class = post_residual / 10; // 0..10 harmonic classes
    match class {
        0 => {
            // post_residual in 1..=9: dangerous dead space unless next item fits.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 25.0; // lookahead chain: next item plugs the hole
            } else if next_item_size > 0 {
                score += 20.0; // creates unusable sliver
            } else {
                score += 10.0; // end of stream, dead space anyway
            }
        }
        1 => {
            // 10..=19: mid-small pocket; reward if next item is in this class.
            if next_item_size >= 10 && next_item_size <= 19 {
                score -= 15.0;
            } else {
                score += 5.0;
            }
        }
        2 | 3 => {
            // 20..=39: useful pocket, mildly good.
            score -= 5.0;
            if next_item_size >= 20 && next_item_size <= 39 {
                score -= 10.0;
            }
        }
        _ => {
            // Large residual left: fine, bin still flexible.
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins relative to the fleet mean residual (balance toward consolidation).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be more willing to open new bins (better long-term packing);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (0.5 - progress) * 10.0;

    // If many bins are open, discourage spreading; favor consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: neutral baseline so it's chosen only when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64 - cap) * 0.0;
        // Make new bin attractive early or when item is large relative to mean residual.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are worthless.
    if post_residual > 0 {
        // Dead-space penalty grows sharply as the gap becomes unusable.
        // A gap is "dead" if it's smaller than the smallest plausible item (1)
        // or smaller than the lookahead item, making it unlikely to be reused.
        let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < dead_threshold {
            score += 40.0 * (1.0 - post_residual as f64 / dead_threshold.max(1) as f64);
        }
        // General convex penalty on leftover space: prefer tight fits strongly.
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward using a bin that would otherwise be the last chance before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the fit would be poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 18.0;
        // Pressure from number of open bins: with many open bins, prefer packing
        // into existing ones; with few, a fresh bin is cheap.
        score -= open_bins_count as f64 * 1.5;
        // If no existing bin fits well (post_residual of this empty bin is the
        // best possible), opening is more attractive when the stream is early.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 6.0;
        }
    } else {
        // Slight preference for bins with larger residuals when fits are comparable,
        // keeping big gaps available for big future items.
        score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;
        // Coupling with mean residual: avoid destroying the largest remaining gaps
        // when the fleet is already tight.
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    // Lookahead synergy: reward placements leaving room for the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is excellent.
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: mild penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual != bin_capacity {
        score -= 2.0 * pressure.min(10.0);
    } else {
        // New-bin candidate: penalize more when many bins are open or mean residual is high.
        score += 8.0 + 1.5 * open_bins_count as f64 + 0.3 * mean_residual;
        // Late in the stream, opening new bins is cheaper (no long tail to pay off).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is already small (consolidate waste).
    if bin_residual != bin_capacity {
        let closeness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 5.0 * closeness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer bins whose post_residual matches the next item's need.
    let mut score = pr;

    // Smooth quadratic dead-space penalty: residuals near 0..12 are wasted space.
    let dead = ((12.0 - pr).max(0.0)) / 12.0;
    score += 40.0 * dead * dead;

    // Non-linear coupling: reward post_residual that closely matches next item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 * (-gap / 20.0).exp();
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize smoothly.
        let over = (next_item_size as f64 - pr) / cap;
        score += 30.0 * over * over;
    }

    // Progress-scaled tightness bonus: later in stream, value tight fits more.
    let tightness = 1.0 - pr / cap;
    score -= (10.0 + 30.0 * progress) * tightness * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: penalize so it only wins when open bins are genuinely bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Dead-space penalty: small residuals that most items cannot use.
    // Items 1..100 unknown; treat residual < 20 as likely dead unless next item fits.
    if pr > 0 {
        if next_item_size > 0 && next_item_size <= pr {
            // Next item fits perfectly-ish: strong reward.
            let slack = (pr - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // Next item cannot use this residual: penalize by dead-space class.
            let class = pr / 10; // harmonic decade class
            score += (20.0 - class as f64 * 2.0).max(0.0) * 2.0;
        }
    }

    // Perfect fit reward (harmonic alignment with capacity).
    if pr == 0 {
        score -= 80.0;
    } else if pr <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad,
    // but reward it when the stream is early (amortization) or many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 30.0 + 40.0 * progress;
        score += base;
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual deviates favorably from mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for high utilization fraction classes.
    let used_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= used_frac * 15.0;

    // Coupling: if next item is small, leaving medium residual is okay.
    if next_item_size > 0 && next_item_size < 30 && pr >= 30 {
        score -= 10.0;
    }

    // Modulo tie-breaker on post_residual classes (prefer multiples of 10).
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are dead space.
    if post_residual < 10 {
        score += 200.0; // unusable gap penalty
    } else {
        // Reward tight fits: large fraction of residual consumed.
        let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
        score -= 60.0 * fill_frac;

        // Reward exact or near-exact fills.
        if post_residual == 0 {
            score -= 50.0;
        } else if post_residual <= 20 {
            score -= 15.0;
        }

        // If lookahead item fits into the post residual, reward saving space for it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer compacting.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or nothing fits well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progress coupling: early in the stream, tolerate spreading slightly more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let next = if next_item_size == 0 { 0.0 } else { next_item_size as f64 };
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Base: tight fit = low residual = low score.
    let mut score = post;

    // Perfect fill: zero waste is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // ---- Aggressive 2-step lookahead matching ----
    if next > 0.0 {
        let gap = post - next;
        if gap == 0.0 {
            // Residual exactly matches next item: perfect chain, place here.
            score -= 800.0;
        } else if gap > 0.0 {
            // Next item also fits here; reward snugness (small leftover after chaining).
            score -= 150.0 * (1.0 - gap / cap);
        } else {
            // Dead space relative to the lookahead item: penalize, more so late in stream.
            score += (-gap) * (0.6 + 0.8 * progress);
        }
    }

    // ---- Mean-residual coupling ----
    // Prefer bins that end tighter than the fleet average (consume the fullest space first);
    // penalize leaving this bin looser than average (fragmentation).
    score += (post - mean_residual) * 0.25;

    // ---- Last-chance bin ----
    // If this is the only open bin that fits, strongly favor using it over opening a new one.
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 120.0;
    }

    // ---- New-bin candidate penalty ----
    // Opening a fresh bin is discouraged, increasingly late in the stream and when many
    // bins are already open; it only wins when all fitting bins score worse (bad fits).
    score += is_new_bin * (40.0 + 120.0 * progress + 15.0 * open_bins_count as f64);

    // Mild normalized tightness term to break ties toward fuller bins.
    score += (post / cap) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead (k=2): reward bins that can also host the next item (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize bins that will strand the next item, scaled by the gap.
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Tight-fit reward: bins left with small post-residual are efficient.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * (1.0 - tight);

    // Near-perfect fill bonus (dead space almost eliminated).
    if post_residual < 10 {
        score -= 15.0;
    }

    if is_new_bin {
        // Opening a new bin: good only as a last resort or when all open bins fit badly.
        let last_chance = fitting_bins_count == 0;
        let desperation = mean_residual < item_size as f64 * 0.9;
        if last_chance || desperation {
            score -= 40.0 + 30.0 * (1.0 - progress);
        } else {
            // Discourage fragmentation: new bins are costly, more so when open bins are roomy.
            score += 25.0 + 20.0 * (mean_residual / bin_capacity as f64);
        }
    } else {
        // Best-fit bias: prefer bins whose residual is below the mean (tighter bins).
        score += 0.05 * (mean_residual - bin_residual as f64);
        // Last-chance bin: strongly favor using it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling roomier bins.
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Core: prefer tight fits, with non-linear sharpening of small residuals
    let mut score = pr * (1.0 + 0.8 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate loose fits; late in the stream punish them more
    let prog_term = pr * (progress * progress + 0.5 * progress);
    score += 0.6 * prog_term;

    // Dead-space penalty: residuals too small for the smallest plausible item
    let dead = (pr / cap).powi(3);
    score += 40.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward residuals that still fit the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0);
        // perfect lookahead fit bonus (quadratic smoothness)
        if pr >= nx {
            score -= 10.0 * (nx / cap) * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild competition normalization
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a bin unless this is a poor fit elsewhere
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - fill);
        // more attractive late in stream when open bins are fragmented
        score -= 10.0 * progress * (mean_residual / cap);
    }

    // Mean-residual fragmentation term (smooth quadratic)
    score += 0.05 * (mean_residual - pr) * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (near capacity multiples) are "dead space" traps.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize post_residuals that are too small to ever fit a typical item
    // (items >= 1, but typical stream items are mid-sized). Dead space below
    // the smallest useful class is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - frac);
    }

    // Harmonic class via integer division: reward residuals divisible into
    // clean capacity fractions (post_residual % 25 == 0 style classes).
    let class_mod: u32 = 20;
    if post_residual % class_mod == 0 && post_residual > 0 {
        score -= 12.0;
    } else {
        let off = (post_residual % class_mod) as f64;
        score += 0.35 * off;
    }

    // Reward tight fits: exact fill is perfect.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this bin (harmonic pairing of consecutive classes).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left % class_mod == 0 {
                score -= 8.0;
            }
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; mild penalty proportional to how
            // much post_residual is wasted relative to next item.
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor fits. Penalize fresh bin when mean residual is still healthy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_frac = mean_residual / cap;
        // Penalize new bin proportional to available slack in open bins.
        score += 20.0 + 25.0 * mean_frac + 10.0 * (1.0 - progress);
        // But if open bins are nearly full on average, new bin is fine.
        if mean_frac < 0.15 {
            score -= 30.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * frac;

    // Late-stream tightening: prefer filling existing bins as stream ends.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= 6.0 * t * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable by future items (min size 1..100,
    // but practically small fragments rarely match). Penalize hard when post_residual is a
    // small nonzero gap that no plausible next item can use.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space: gap smaller than any realistic item
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, this is a great chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else if gap < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit into post_residual, mild penalty proportional to wasted chain.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: prefer existing bins when many are open; discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: raw capacity residual. Add pressure growing with open bins count.
        score += (open_bins_count as f64) * 4.0 + 10.0 * progress;
        // Allow new bin only if no existing bin fits well (post_residual would be small gap).
        if fitting_bins_count > 0 && bin_residual - item_size >= 20 {
            score += 40.0; // strongly prefer using an existing bin with decent leftover
        }
    } else {
        // Existing bin: slight bonus for being one of few fitting bins (last-chance bin).
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Reward bins tighter than the mean residual (better consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - match_gap / bin_capacity as f64).max(0.0);

        // Perfect chain: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item fits with small leftover (tight 2-item chain)
        else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 25.0;
        }
        // Next item cannot fit here at all: mild penalty for dead space
        else if post_residual < next_item_size {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: avoid making bin much emptier than average
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when good open fits exist (new bin has residual == capacity)
    if bin_residual == bin_capacity {
        score += 20.0 + 0.2 * open_bins_count as f64;
        // But allow new bin if item is huge and mean residual is small
        if item_size as f64 > mean_residual + 5.0 {
            score -= 45.0;
        }
    }

    // Progress-based mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight fit), scaled non-linearly.
    let mut score = (post / cap).powf(1.6) * cap;

    // Reward tight fits more strongly: gap between residual and item.
    let gap = resid - item;
    score += (gap / cap) * 8.0;

    // Penalize leaving dead space that no plausible item can use.
    if post > 0.0 {
        let next = next_item_size as f64;
        if next > 0.0 {
            if next > post {
                // Next item can't use leftover; mild penalty unless residual still large.
                score += 2.0 * (1.0 - post / cap);
            } else {
                // Next item fits the post residual: strong reward for this bin.
                score -= 6.0 * (1.0 - (post - next) / cap);
            }
        } else {
            // Last item: strongly prefer filling bins as much as possible.
            score -= 10.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged early,
    // but acceptable late or when mean residual across open bins is small.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        let pressure = mean_residual / cap;
        let new_bin_bias = 3.0 + 10.0 * progress + 8.0 * (1.0 - pressure) - 2.0 * openness;
        // Penalize new bin unless item is small relative to capacity.
        score += new_bin_bias * (item / cap);
        // If item would leave a huge hole in an existing bin, new bin looks better.
        if post > 0.5 * cap {
            score -= 5.0;
        }
    } else {
        // Slight preference for reusing bins to keep bin count low.
        score -= 1.0 + 0.5 * (open_bins_count as f64).ln_1p();
    }

    // Coupling with global mean residual: bins far from mean get normalized.
    let dev = (resid - mean_residual).abs() / cap;
    score += 2.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Core: post-residual, with smooth polynomial coupling to stream progress.
    let mut score = pr;

    // Later in the stream: penalize residual more strongly (dead space hurts more).
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += 30.0 * norm_pr * norm_pr * progress_weight;

    // Smooth convexity bonus for very tight fits (post_residual near 0).
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Many open bins: mild penalty to prefer consolidation into existing space.
    let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 10.0 * openness * norm_pr;

    // Lookahead: reward leaving room exactly for the next item (smooth gaussian-like match).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (-30.0 * diff * diff).exp();
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer-division thresholds (dead-space classes).
    let post = post_residual;
    let class: f64 = if post == 0 {
        -60.0 // perfect fit: strongly reward
    } else if post <= 10 {
        -35.0
    } else if post <= 20 {
        -18.0
    } else if post <= 30 {
        -5.0
    } else if post <= 40 {
        8.0
    } else if post <= 50 {
        18.0
    } else {
        30.0 // large dead space: penalize heavily
    };
    score += class;

    // Fractional capacity coupling: how full the bin becomes.
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill * fill; // reward fuller fills non-linearly

    // Lookahead coupling: reward leaving a residual that the next item can use.
    if next_item_size > 0 && post >= next_item_size {
        let slack = (post - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap); // near-exact two-item packing
    } else if next_item_size > 0 && post > 0 {
        score += 6.0; // next item cannot use this leftover
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the fit here
    // would be poor and we already have many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post > 30 && (next_item_size == 0 || next_item_size > post);
        if poor_fit && open_bins_count > 3 && progress > 0.1 {
            score -= 20.0; // open a new bin rather than fragment this one
        } else {
            score += 35.0; // default: discourage opening new bins
        }
    }

    // Mild pressure toward consolidating bins when mean residual is large.
    score += 0.05 * (mean_residual - post as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // "Awkward gap" penalty: residuals that fit few future item sizes.
    // Reward post_residual values that are either 0 (perfect fit) or large
    // enough to remain flexible.
    if post_residual > 0 && post_residual <= 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Tight-fit reward: subtract more when the item fills a large fraction
    // of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.3;
    }
    // If next item cannot fit the post_residual, the leftover is likely dead.
    else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; opening new bins becomes less attractive.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, softened early in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + open_pressure - progress * 10.0;
    } else {
        // Slight reward for using existing bins proportional to pressure.
        score -= open_pressure * 0.2;
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing) to keep future options even.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
