pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small but nonzero dead space (unusable fragments)
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward tight fits relative to item size
        let tightness = post_residual as f64 / (bin_residual as f64 + 1.0);
        score += tightness * 20.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.2 * next_item_size as f64;
        } else {
            // If next item would leave this bin stranded with tiny residual
            let leftover_after_next = post_residual as i64 - next_item_size as i64;
            if leftover_after_next < 0 && post_residual < 15 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening new bins when many open bins still have room
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 35.0 * pressure + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in the stream, prefer opening bins (cheap); later, avoid it
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 20.0 * progress;
    } else {
        // Favor bins whose residual is below the mean (fill the emptier ones)
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Mild preference for higher occupancy rate
    score -= 0.1 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, larger residuals are fine (bins stay flexible); late, we
    // punish leftover space more since future reuse is less likely.
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth cubic term: dead space that is too small to be useful is penalized
    // super-linearly as the stream advances.
    let dead = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
    score += dead * (10.0 + 40.0 * progress) * (norm_pr * (1.0 - norm_pr) + 0.01);

    // Lookahead coupling: reward residuals that can still host the next item,
    // with a smooth bell-shaped preference for tight-but-compatible fits.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let bell = (-gap * gap / (2.0 * (cap * 0.25).powi(2))).exp();
        score -= 25.0 * bell * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin to avoid
    // opening a new one, scaled smoothly by scarcity.
    if fitting_bins_count == 1 {
        score -= 30.0 + 50.0 * progress;
    }

    // Mild tie-break toward bins whose residual deviates from the mean
    // (prefer consolidating into atypical bins), smooth in mean_residual.
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish score so it only wins when open bins
    // are genuinely bad (large residuals or dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.6 * progress) + 20.0 * dead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
