    // Favor bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.8;

    // Last-chance bin: strongly reward using it, else we open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 4.0;
    } else {
        score -= 5.0;
    }

    // Lookahead coupling: reward leaving a residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
