    }
    // Penalize leaving a residual that almost fits the next item (near-dead space).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mean-residual alignment: prefer bins near the mean residual to keep
    // the bin pool balanced.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Slight early-stream bias toward consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

