}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward tight packing.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space relative to smallest possible item (1..100 unknown, use next_item_size as reference).
        if next_item_size > 0 {
            // Aggressive 2-step lookahead: if next item fits exactly into post_residual, huge reward.
            if post_residual == next_item_size {
                score -= 40.0;
            } else if post_residual >= next_item_size {
                // Next item fits but leaves slack; mild reward scaled by tightness.
                let slack = (post_residual - next_item_size) as f64;
                score -= 15.0 - slack * 0.2;
            } else {
                // Next item cannot fit: dead space until later; penalize proportionally.
                let gap = (next_item_size - post_residual) as f64;
                score += gap * 0.5;
            }
        }

        // Reward residuals that are small relative to mean residual (tighter than average bin).
        let mean_gap = post_residual as f64 - mean_residual;
        score += mean_gap * 0.3;

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no open bin
    // offers a decent fit. Make the empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
        // If item is large and would leave a large residual anyway, new bin is more acceptable.
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= big_item * 25.0;
        // Lookahead: if next item is large and current open bins are full-ish, new bin helps.
        if next_item_size > 0 && (mean_residual < next_item_size as f64) {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;
    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (quadratic coupling).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Lookahead: reward bins whose post_residual can host the next item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_pair = (post_residual - next_item_size) as f64;
        let pair_quality = 1.0 - slack_after_pair / (bin_capacity as f64);
        score -= 10.0 * pair_quality;
    } else if next_item_size > 0 {
        // Penalize leaving residual that the next item cannot use (likely dead space).
        score += 3.0 * ((post_residual as f64) - (next_item_size as f64)).abs().sqrt();
    }

    // Last-chance bin: strong bonus to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when alternatives exist.
    if bin_residual != bin_capacity {
        score += 0.35 * (open_bins_count as f64).ln();
    }

    // New-bin candidate logic: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let poor_fit = (post_residual as f64) / bin_capacity as f64;
        // A new bin is good when the item leaves little waste anyway, or when
        // no open bin fits well (few fitting bins, high mean residual mismatch).
        let pressure = if fitting_bins_count == 0 { 12.0 } else { 0.0 };
        score -= 8.0 * fit_ratio + pressure - 6.0 * poor_fit;
        // Late in the stream, consolidation matters more: discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Mild global-state coupling: bins with residual far from mean are slightly
    // favored if they are tighter than average (homogenization pressure).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Small exact-fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: tightness with smooth polynomial shaping of post-residual.
    let mut score = pr / cap;
    score += 0.35 * (pr / cap).powi(3);

    // Smooth progress coupling: later in the stream, value tight fits more.
    score -= 0.6 * progress * (1.0 - pr / cap).powi(2);

    // Last-chance bin (only one fitting bin): strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 1.5 + 0.8 * progress;
    }

    // New-bin candidate: penalize, but less when open bins are full-ish
    // (mean residual low) or the item is large.
    if is_new_bin {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let size_norm = item / cap;
        score += 1.2 - 0.9 * (1.0 - mean_norm).powi(2) - 0.5 * size_norm;
    } else {
        // Reward matching against bins whose residual is close to the item (smooth coupling).
        let diff = (bin_residual as f64 - item) / cap;
        score -= 0.4 * (-diff * diff * 8.0).exp();
    }

    // Lookahead: if next item would fit the post-residual nicely, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 0.5 * (-gap * gap * 10.0).exp();
        } else {
            let gap = (nxt - pr) / cap;
            score += 0.3 * (-gap * gap * 6.0).exp();
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into nice
    // packing partners (multiples of 10) are more reusable than odd scraps.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fill, ideal
    } else {
        let class = match pr {
            0..=9 => 0.0,
            10..=19 => 1.0,
            20..=29 => 2.0,
            30..=39 => 3.0,
            40..=49 => 4.0,
            50..=59 => 5.0,
            60..=69 => 6.0,
            70..=79 => 7.0,
            _ => 8.0,
        };
        // Larger usable classes are better: subtract proportional reward.
        score -= class * 3.0;
        // Penalize odd dead-space residues that few item sizes can use.
        if pr % 10 != 0 {
            score += (pr % 10) as f64 * 0.8;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot follow here; mild penalty scaled by overflow.
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large and current residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / cap; // small mean_residual => open bins nearly full
        let penalty = 25.0 + item_size as f64 * 0.2 - tight * 30.0 - progress * 5.0;
        score += penalty.max(2.0);
    }

    // Prefer bins whose residual is far below mean (tighter bins first),
    // keeping a spread of residual sizes among open bins.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Slight preference for high fill fraction early in the stream.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be practically useful
    // (below the typical item floor) are heavily penalized as wasted space.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 3.0;
    }

    // Perfect fit reward: subtractions favor using a bin that closes exactly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item can still fit in the post residual,
    // this placement preserves future packing ability.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // This bin becomes dead space for the lookahead item: mild penalty.
        score += 4.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins are
    // crowded (low mean residual) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual < 20.0 {
            score -= 20.0;
        }
        score += open_bins_count as f64 * 0.5;
    }

    // Open-bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.3;

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus: next item almost fills the leftover space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64).powi(3);
    } else if next_item_size > 0 {
        // Next item doesn't fit here: penalize proportionally to the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.3 * gap;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    // (item leaves large dead space or fits nowhere nicely).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer opening a new bin for large items; penalize for small items.
        score += 40.0 * (1.0 - tightness);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin perfectly chains with the next item too.
            if bin_capacity - item_size == next_item_size {
                score -= 55.0;
            }
        }
        // If several bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 30.0;
        }
    }

    // Penalize creating dead space far below the mean residual (fragmentation).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    }

    // Slight preference for keeping many bins consolidated early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize leaving dead space too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would exactly fill post_residual, even better
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if post_residual is small but next item needs a lot
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0 * (next_item_size - post_residual) as f64 / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer consolidation into fuller bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is near mean (balanced) or much lower
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // New-bin candidate handling: mildly penalize so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // If item is large relative to mean residual, opening a fresh bin is attractive
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Base: tight fits (small post_residual) preferred, non-linearly.
    let x = post / cap;
    let mut score = 100.0 * x * x + 20.0 * x;

    // Smooth interaction: waste penalty grows with stream progress.
    score += 60.0 * x * x * (0.5 + progress);

    // Reward filling bins nearly exactly (post_residual near 0).
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Lookahead coupling: penalize leaving residual that fits next item poorly
    // (encourage leaving residuals the next item can use well).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let nxt_fit_quality = 1.0 - (post - nxt) / cap;
            score -= 15.0 * nxt_fit_quality * nxt_fit_quality;
        } else {
            // residual too small for next item: dead space penalty
            score += 10.0 * (post / nxt) * (post / nxt);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new empty bin, unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 40.0 - 70.0 * x * x * 0.0; // constant new-bin penalty
        score += 35.0 * (1.0 - (item_size as f64 / cap)); // big items into new bins OK
        // smooth forgiveness: if item nearly fills a fresh bin, reduce penalty
        score -= 30.0 * (item_size as f64 / cap).powi(2);
    }

    // Mild pressure toward bins with lower residual (denser bins) via mean_residual.
    score += 0.05 * (mean_residual - post);

    // Slight preference for fewer open bins early (keeps consolidation pressure).
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small" residue
    // classes (<=10) are nearly perfect, reward them strongly.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 40.0;
    } else {
        // modulo-class penalty: leftover in awkward classes (11..=20) is dead space
        let class = pr % 10;
        score += 6.0 * (class as f64) / 9.0;
        // integer-division thresholds: quarter fractions of capacity
        let quarter = bin_capacity / 4;
        if pr < quarter { score -= 8.0; }
        else if pr < 2 * quarter { score += 4.0; }
        else { score += 12.0; }
    }

    // Reward tight fits relative to residual (fractional capacity coupling)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr {
            score -= 12.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; penalize less if leftover is tiny anyway
            score += 5.0 * (next_item_size as f64 - pr as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately unattractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // late in the stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress;
    }

    // Mild pressure to balance residuals when many bins are open
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable.
    if post_residual > 0 && post_residual < 11 {
        score += 60.0;
    } else if post_residual < 21 {
        score += 25.0;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose leftover can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that almost fits the next item (near-miss waste).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Pressure: many open bins -> discourage spreading, prefer tight packing.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score = 80.0 + post_residual as f64
            - (fitting_bins_count == 0) as i32 as f64 * 70.0
            + open_bins_count as f64 * 0.5;
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead: next item fits in the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted lookahead opportunity.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.35 * gap;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 0.25 * (bin_capacity - post_residual) as f64;

    // Penalize creating dead space that is small but unusable (hard to fill later).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(10) {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.2 * mean_residual;
    }

    // Prefer filling bins with low mean residual (consolidate nearly-full bins).
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // New-bin candidate: baseline slightly worse than a perfect fit,
    // but increasingly penalized when plenty of open bins already fit,
    // so a fresh bin only wins when the item fits existing bins poorly.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 1.0
            + 4.0 * fitting_bins_count as f64
            + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // Late in the stream, be more reluctant to open new bins.
        score += 8.0 * progress;
        return score;
    }

    // Reward near-perfect fits: tiny post_residual is valuable.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        // Dead space too small for the smallest item (1..100 range).
        score += 15.0;
    }

    // Lookahead (k=2): reward bins whose residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.15 * snug;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0;
    }

    // Global pressure: many open bins with high mean residual ->
    // prefer consolidating into bins already below average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early on, tolerate slack for future flexibility;
    // later, prioritize tight packing.
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild preference to fill bins that are already fairly full.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial base: penalize wasted residual super-linearly
    let mut score = pr * (1.0 + norm_pr * norm_pr * 2.5);

    // Tight-fit reward: subtract a smooth bonus shrinking as residual grows
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness.powi(3);

    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // penalize residuals that just barely miss the next item
            let miss = (nxt - pr) / cap;
            score += 8.0 * miss * (1.0 - progress);
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (consolidation)
    score += 0.35 * (mean_residual - pr).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: smooth penalty growing with stream progress
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 40.0 + 60.0 * (1.0 - progress) * (1.0 - progress);
        // allow opening when existing bins would leave very awkward residuals
        score -= 0.5 * norm_pr;
    }

    // Mild pressure to close out bins late in the stream
    score += progress * norm_pr * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Exact fits (residue 0 mod 25/50) are golden — reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual % 50 == 0 {
        score -= 60.0;
    } else if post_residual % 25 == 0 {
        score -= 30.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    } else {
        // penalize awkward residues (dead space hard to fill)
        score += (post_residual % 10) as f64 * 2.0;
    }

    // Integer-division thresholds: how many "typical" small items (size <= 20)
    // could still fit? More usable slots => better bin.
    let slots = post_residual / 20;
    score -= slots as f64 * 12.0;

    // Lookahead: does the next item fit into post_residual? Big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0 + (post_residual - next_item_size) as f64 * 0.3;
        // exact pairing: post_residual == next_item_size is perfect
        if next_item_size == post_residual {
            score -= 120.0;
        }
    } else if next_item_size > post_residual {
        // next item can't use leftover: penalize proportionally to wasted space
        score += (post_residual as f64) * 0.4;
    }

    // Tightness of current fit: prefer bins where item fills a large fraction.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 25.0;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): make it attractive only when open bins
    // have poor fits; otherwise push it behind existing bins.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 4.0;
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.25;
    }

    // Mild preference to keep number of open bins low.
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual relative to item size, the better.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 12.0;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (below min item size 1... but practically below
    // next_item_size) are wasted. Penalize unusable gaps hard.
    if post_residual < next_item_size && next_item_size > 0 {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.8;
    }
    // Very small unusable slivers are dead space regardless of lookahead.
    if post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        // If no existing bin fits, opening is unavoidable-ish; soften penalty.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // already-open bins rather than spreading.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is already below average (they are the
    // "nearly full" ones; filling them closes bins sooner).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Lookahead pairing: if next item fits exactly into the resulting gap,
    // reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small residuals that are hard to reuse later.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 - pr * 4.0; // dead space under 10 is nearly unusable (min item = 1..100 range)
        }
        // Reward residuals that can host the next item (2-step lookahead matching).
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                // Perfect 2-chain: post_residual exactly matches next item.
                let gap = pr - nxt;
                if gap == 0.0 {
                    score -= 400.0;
                } else {
                    // Scaled reward: smaller gap is better, but bounded.
                    score -= 150.0 * (1.0 - gap / bin_capacity as f64);
                }
            } else {
                // Next item won't fit in the leftover: mild penalty proportional to shortfall.
                score += 0.5 * (nxt - pr);
            }
        }
    }

    // Compare this bin's residual against the mean residual of open bins.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        // Bins with residual below mean are "tighter" — prefer using them up
        // (they are less likely to serve future items), so reward choosing them.
        let rel = (res - mean_residual) / mean_residual;
        score += 8.0 * rel;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // fits poorly everywhere else. Penalize opening a new bin unless the item
    // is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of a new bin, discounted for large items.
        score = 100.0 - 40.0 * fill_ratio;
        // If many bins are open and fragmented, opening fresh is more acceptable.
        score -= 2.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If the next item is small, a fresh big residual is valuable.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let left = (bin_capacity as f64) - item_size as f64;
            if left >= nxt {
                score -= 20.0 * (1.0 - (left - nxt) / bin_capacity as f64);
            }
        }
    }

    // Mild tie-breaking: prefer bins with larger residual when all else equal
    // (keeps small-residual bins for small items).
    score -= 0.01 * res;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: how far through the stream we are.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot be used again:
    // if post_residual is smaller than the smallest plausible item, it's dead space.
    if post_residual < 10 {
        score -= 100.0; // perfect fill, excellent
    } else if post_residual < next_item_size as f64 as u32 && next_item_size > 0 && post_residual > 0 {
        // residual too small for the next item: dead space penalty scaled by progress
        score += 15.0 + 20.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0; // can't chain next item here
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Compare against mean residual: bins with residual well below mean are "fuller",
    // prefer filling them further (best-fit-like behavior).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (large post_residual) or many bins are already open
    // with plenty of spread. Give it a baseline cost that grows with progress.
    if bin_residual == bin_capacity {
        score += 35.0 + 30.0 * progress;
        // If nothing else fits well, allow new bin: reduce penalty when item is large.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out bins rather than opening new ones.
        if progress > 0.8 {
            score += 25.0;
        }
    }

    // Mild pressure to keep the number of open bins bounded: when many bins are open,
    // prefer placing into existing bins (penalize the new-bin option implicitly via
    // rewarding placements into crowded states).
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Slight preference for bins whose residual is close to item_size (near-exact fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial penalty on wasted residual (quartic, normalized)
    let waste = pr / cap;
    score += 12.0 * waste * waste * waste * waste * cap;

    // Reward tight fits (small post_residual) with smooth coupling to stream progress
    let tightness = 1.0 - waste;
    score -= 8.0 * tightness * tightness * (1.0 + 2.0 * progress);

    // Lookahead coupling: favor residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 4.0 * (1.0 - slack * slack) * (1.0 + progress);
        } else {
            // post-residual cannot fit next item: penalize proportionally to shortfall
            let gap = (nx - pr) / nx;
            score += 5.0 * gap * gap * cap * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mean-residual context: penalize bins far below mean residual (fragmented small leftovers)
    let dev = (mean_residual - pr) / cap;
    score += 2.0 * dev * dev * cap;

    // New-bin candidate: keep it competitive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = cap + 6.0 * (1.0 - progress) * open_bins_count as f64 - 2.0 * crowding;
        if fitting_bins_count == 1 {
            score += 25.0; // never open a new bin when a unique last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful" classes
    // (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    let useful = if pr == 0 {
        30.0
    } else if pr % 10 == 0 {
        12.0
    } else if pr % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= useful;

    // Integer-division thresholds: small post_residual = dead space, penalize.
    if pr <= 10 && pr > 0 {
        score += 25.0;
    }
    if pr < next_item_size as u32 && next_item_size > 0 && pr > 0 {
        score += 15.0;
    }

    // Reward using nearly-full bins (tight fit).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly favor to avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly unless current bin would leave bad residue.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * (mean_residual / bin_capacity as f64);
        if next_item_size as u32 > post_residual && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Lookahead harmony: if next item fits exactly in post_residual class, reward.
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let after2 = pr - next_item_size;
        if after2 % 10 == 0 || after2 == 0 {
            score -= 8.0;
        }
    }

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1) are pure waste; residuals below a "usable
    // gap" threshold are heavily penalized with a non-linear spike.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable dead space (below minimum item size): severe penalty
        // that grows as the gap shrinks toward nothing useful.
        score += (10.0 - pr) * 3.0;
    } else {
        // Usable residual: mild penalty, favor tighter fits.
        score += pr * 0.15;
    }

    // Reward bins whose residual is a tight fit for the item.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / (1.0 + total_items as f64));
    score += pressure * 0.5;

    // New-bin candidate handling: empty bin gets a base cost, but becomes
    // attractive when existing bins would leave bad dead space or when the
    // next item needs fresh space.
    if bin_residual == bin_capacity {
        score += 25.0;
        if open_bins_count > 0 {
            // Prefer new bin if all open bins would create unusable gaps.
            if post_residual < 10 && bin_residual - item_size >= 10 {
                score -= 30.0;
            }
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0;
        }
    } else {
        // Existing bin: penalize if placing here destroys space the
        // lookahead item could otherwise use.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (bin_residual as u32) >= next_item_size {
            score += 6.0;
        }
        // Reward using bins whose residual is close to the mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= (10.0 - dev.min(10.0)) * 0.2;
    }

    // Early stream: be slightly more willing to open bins (future packing
    // flexibility); late stream: consolidate hard.
    let progress = step_index as f64 / (1.0 + total_items as f64);
    score -= (1.0 - progress) * 3.0;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this bin is extremely valuable (chain packing).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: residual gap after two placements
            let two_step_gap = post_residual - next_item_size;
            score -= 200.0 - (two_step_gap as f64) * 2.0;
        } else {
            // Next item won't fit here: penalize leaving large unusable space
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    }

    // Penalize large post residual relative to mean residual (dead space)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild preference for filling bins tightly when many bins are open
    if open_bins_count > 4 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Slight bias toward reusing existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use — mild penalty scaled by dead space.
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        let mut new_bin_score = 15.0 + open_bins_count as f64 * 1.5;
        // If next item is large and no open bin will hold both, opening fresh is attractive.
        if next_item_size > 0 && next_item_size + item_size > bin_residual {
            new_bin_score -= 5.0;
        }
        // Early in the stream, be more willing to open bins (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= (1.0 - progress) * 5.0;
        // If mean residual across open bins is low (bins are full), new bin is natural.
        new_bin_score += (mean_residual / bin_capacity as f64) * 10.0;
        score = new_bin_score;
    }

    // Slight preference to fill bins with low residual relative to mean.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = pr / cap;

    // Core: reward small post-residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * tightness * tightness);

    // Extra reward for near-perfect fits (smooth polynomial dip).
    score -= 30.0 * (1.0 - tightness).powi(6);

    // Stream progress: as stream advances, tolerate residual less (favor tighter packing).
    score *= 1.0 + 0.6 * progress * (1.0 - tightness);

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        // Penalize leaving a residual that the next item almost but does not fit.
        score += 5.0 * (1.0 - (pr / next_item_size as f64).min(1.0));
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new.
    score += 0.05 * open_bins_count as f64 * tightness;

    // Slight alignment with mean residual: avoid creating outliers far below mean.
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate: make empty-bin choice mildly costly unless residual math favors it.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, normalized slightly.
    score *= 1.0 + 0.10 * (post_residual as f64 / cap);

    // Tight-fit bonus: harmonic classes of post_residual.
    // Class A: post_residual <= 10 -> near-perfect fit, strong reward.
    if post_residual <= 10 {
        score -= 25.0;
    }
    // Class B: post_residual in 11..=20 -> still very usable for small items.
    else if post_residual <= 20 {
        score -= 12.0;
    }
    // Class C: dead space zone 21..=39 -> penalize; hard to fill with items >=10
    // only partially fillable.
    else if post_residual < 40 {
        score += 8.0;
    }
    // Class D: post_residual >= 40 -> half-bin or more remains, acceptable.
    else {
        score -= 3.0;
    }

    // Exact modulo classes on post_residual: multiples of 10 are "harmonic"
    // with the 10..80 item range -> residue aligns with minimum item size.
    let pr = post_residual;
    if pr > 0 && pr % 10 == 0 {
        score -= 4.0;
    }
    // Residues in [10, 19] mod 20 leave room for exactly one small item.
    if pr >= 10 && pr < 20 && pr % 20 >= 10 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly or well,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 15.0;
            } else {
                score -= 5.0 * (1.0 - slack as f64 / cap);
            }
        } else {
            // Next item cannot use this bin's remainder: mild penalty if the
            // remainder is awkward (in dead-space class).
            if pr >= 21 && pr < 40 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (huge post-residual dead zone).
    if fitting_bins_count == 1 {
        if !(pr >= 21 && pr < 40) {
            score -= 20.0;
        }
    }

    // New-bin candidate (empty bin): penalize opening a new bin when decent
    // fits exist; but a fresh bin is attractive when all open fits are bad
    // (handled implicitly by classes above) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
        // If many bins are open and mean residual is large, prefer reusing.
        if mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Small penalty per open bin to discourage bin proliferation.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but still usable).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 15 {
        score -= 25.0; // tight fit, likely reusable
    }

    // Reward good relative fill ratio of the bin.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 40.0;

    // Lookahead: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for next item: penalize mildly unless it's dead space.
        score += 8.0;
    }

    // Open-bin pressure: prefer placing into existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: penalize bins whose residual deviates far above
    // the mean (they are likely to become dead-space bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.max(0.0);

    // Early stream: be slightly more conservative (favor new bins for large
    // items so small ones can fill later); late stream: pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // New-bin candidate: give it a moderate baseline so it is chosen only
    // when existing bins have bad fits (their penalties push them above this).
    if bin_residual == bin_capacity {
        score = 55.0 + item_size as f64 * 0.2 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core: exact / tight fits are heavily favored.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual < 10 {
        score -= 300.0; // near-perfect fill
    } else {
        // Penalize dead space proportionally to how unusable it is.
        // Residual smaller than the minimum item (1) can't happen, but
        // residuals much smaller than typical items are dead weight.
        let dead = (post_residual as f64 / capacity).powi(2);
        score += 40.0 * dead;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly
    // consumes the post_residual, or the current item is a tight fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain fit: next item closes this bin perfectly
        } else if next_item_size < post_residual {
            let next_leftover = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - next_leftover / capacity);
        } else {
            // Next item cannot use this bin's leftover: leftover is more likely dead.
            score += 25.0 * (1.0 - fit_ratio);
        }
    }

    // Relative-to-mean coupling: prefer bins that are already more filled
    // than average (consolidation), penalize spreading across bins.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual.max(1.0);
        score += 30.0 * rel; // lower residual than mean => lower score => favored
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // item is large relative to capacity (poor fit everywhere else likely).
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win first.
        score += 120.0;
        // Large items justify opening a fresh bin.
        score -= 1.2 * (item_size as f64);
        // Early in the stream, opening bins is cheaper (more items to come
        // will fill them); late in the stream, avoid fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
        // If next item is small, a fresh big bin can host it later.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 80.0;
        }
    }

    // Mild penalty per open bin: discourage proliferation of many open bins.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual) with a nonlinear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (post_residual as f64 + 1.0).ln();

    // Penalize dead space that can't fit a typical future item.
    if post_residual > 0 {
        let dead = (post_residual as f64 / 10.0).floor() * 10.0;
        score += 0.35 * dead;
    }

    // Lookahead: reward leaving space exactly usable by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 / (1.0 + slack * 0.1);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize stranding the next item's fit options.
        score += 2.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Mild penalty when many bins compete, prefer consolidating.
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 { 0.0 } else { 0.0 };
        let best_possible = (mean_residual - item_size as f64).max(0.0);
        let urgency = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let _ = poor_fit;
        score = item_size as f64 * 0.9
            + best_possible * 0.5
            + 4.0 * (1.0 - urgency)
            - urgency * 15.0;
        // Late in the stream, avoid opening new bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
        // Many open bins with plenty of mean residual -> discourage new bin.
        score += 0.4 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Global consolidation pressure: many open bins -> prefer filling existing ones.
    score -= 0.05 * open_bins_count as f64 * tightness;

    // Small time-dependent tie-breaker encouraging diversity early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (progress * std::f64::consts::PI).sin() * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear penalty on leftover space (convex, punishes large residuals)
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Coupling with stream progress: early on, tolerate slack; late, squeeze bins tightly
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * norm_pr * cap * 0.25;

    // Reward tight fits more strongly as the stream advances
    score -= (1.0 - norm_pr) * (1.0 + progress) * 3.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // More fitting bins => this bin less critical; slight penalty to prefer scarce fits
    score += fitting_bins_count as f64 * 0.4;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= (1.0 - diff / cap) * 5.0;
        } else {
            score += 1.0;
        }
    }

    // Prefer bins whose residual is near the mean (balanced packing), scaled by progress
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += dev * (2.0 + 3.0 * progress);

    // Mild penalty for accumulating many open bins late in the stream
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small, still-usable" classes are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class A: perfect or near-perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Class B: leftover in "harmonic" sizes (multiples of 10, 20, 25) that
    // typical items can still fill -> moderate reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Class C: dead space — leftover too small for the smallest plausible
    // follow-up item (next item if known, else generic small item).
    let min_next = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < min_next {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a chained perfect fit -> big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Next item fits but leaves another residual: mild reward scaled
        // by how tight the chain is.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - chain_waste / cap);
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize more when the
        // leftover is large (wasted capacity ahead).
        score += 10.0 * frac;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has neutral base score (=100).
    // Prefer it only when no open bin offers a good (tight) fit.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If many open bins are nearly empty, opening another is wasteful.
        if mean_residual > 0.6 * cap {
            score += 20.0;
        }
    }

    // Prefer packing into bins with below-average residual (consolidate
    // nearly-full bins, keep slack bins flexible).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    // Modulo threshold on residual classes: residuals in (50, 80] are the
    // most flexible "half-bin" class; gently favor preserving them unless
    // the current fit is tight.
    if post_residual > 50 && post_residual <= 80 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10 band)
    // are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        score += 25.0 * (20.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // If the next item fits exactly in the post-residual, reward heavily (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        if chain < 10 {
            score -= 45.0;
        } else {
            score -= 15.0;
        }
    }
    // Penalize if next item cannot use the leftover space and leftover is small.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // encourage consolidation when few are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.35 * bin_pressure * (1.0 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: make it attractive only when existing bins would leave
    // bad dead space; otherwise keep it mildly unattractive (consolidation bias).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with how many are already open.
        score += 12.0 + 1.2 * open_bins_count as f64;
        // But if the current item is large, a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // Late in the stream, prefer filling existing bins.
        score += 30.0 * progress;
        // If no existing bin gives a decent fit, allow the new bin.
        if post_residual > item_size / 2 && fitting_bins_count > 0 {
            // existing bins fit poorly (this call is the new bin, so post_residual==item_size)
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with superlinear dead-space penalty
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits perfectly here -> strong reward
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasted residual
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare against mean residual of open bins: prefer bins below-mean fill (larger residual)
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream, be more tolerant of residual spread
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly usable by the next item.
            score -= 0.25 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current fits are bad
    // (few fitting bins and high mean residual fragmentation).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let bad_fit_pressure = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let bonus = 25.0 * bad_fit_pressure * (0.5 + 0.5 * fragmentation) * (0.5 + 0.5 * progress);
        score -= bonus;
        // Mild penalty so a decent existing fit still wins over a fresh bin.
        score += 8.0;
    }

    // Prefer filling bins that are already mostly consumed (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Slight preference to keep number of open bins low early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Small time-horizon modulation: be greedier toward the end of stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: post_residual beyond a soft threshold grows quadratically.
    let norm_pr = pr / cap;
    score += 6.0 * norm_pr * norm_pr * cap;

    // Tight fits rewarded, scaled by stream progress (late stream favors tight packing).
    let tightness = 1.0 - norm_pr;
    score -= (2.0 + 4.0 * progress) * tightness * tightness * cap;

    // Lookahead coupling: penalize leaving residual that fails to host next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 1.5 * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly unless existing fits are very poor.
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    // Mean residual divergence: prefer bins deviating from mean (consolidation).
    score += 0.5 * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post_residual is better (already baseline), but
    // give extra credit for post_residual in "harmonic" classes that are hard
    // to fill later (small odd-ish residues).
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Strongly penalize leaving residuals that no plausible item (1..=100) can
    // use well: residual 1..10 is dead space.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Harmonic class bonus: post_residual exactly divisible into useful chunks.
    // Residuals divisible by 25 or 50 are reusable (items 25/50/75).
    if pr % 50 == 0 && pr > 0 {
        score -= 15.0;
    } else if pr % 25 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward proportional to how well next item fills the leftover
        let fill = next_item_size as f64 / pr as f64;
        score -= 20.0 * fill;
    }

    // Penalize wasting a nearly-full bin on an item when many bins fit
    // (prefer compacting large items into emptier bins is wrong; we want
    // tight fits, so slight penalty if this bin's fit is loose while others fit).
    if fitting_bins_count > 1 {
        let tightness = item_size as f64 / bin_residual as f64;
        score += 10.0 * (1.0 - tightness);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline preference; open new bin only when existing
    // fits are poor. Give the empty bin a moderate score so tight existing
    // fits win, but loose fits lose.
    if bin_residual == bin_capacity {
        // neutral-ish: post_residual = capacity - item_size already baseline
        // small bonus late in stream when many bins open (consolidate)
        if open_bins_count > 8 {
            score += 12.0;
        }
    }

    // Mean-residual coupling: penalize bins far below mean residual
    // (they are nearly full — using them is good, so reward instead).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Progression: early in stream, be slightly more willing to open bins
    // (score empty bin lower), late in stream prefer consolidation.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin pressure: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: prefer consolidation when many bins are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual below mean (tighter bins first)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0)
            || (post_residual as f64 > mean_residual * 2.0);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly into post_residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = post - next_f;
            score -= 25.0 * (1.0 - slack / 100.0); // good lookahead fit, tighter is better
        } else {
            // next item cannot follow here; penalize if post_residual becomes dead space
            if post_residual < 10 {
                score += 8.0 * (10 - post_residual) as f64;
            } else {
                let gap = next_f - post;
                score += 0.3 * gap.min(50.0); // mild penalty for unusable-for-next residual
            }
        }
    }

    // Tight fit reward relative to current item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Compare against mean residual: bins with residual far from item are less attractive.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Early in stream, prefer consolidating into fewer bins; late, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer keeping some bins with large residuals for big future items.
    if post_residual >= 60 {
        score -= 4.0;
    }
    if post_residual > 0 && post_residual < 5 {
        score += 6.0; // nearly dead space
    }

    // New empty bin candidate: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin supports a good chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward filling the bin completely (post_residual very small).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item can use.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        // small unusable sliver: acceptable only late in stream
        score += 20.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Prefer filling bins with large residuals when many bins are open (bin consolidation).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Penalize opening new bins when plenty of open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty grows with open bins count
        score += 15.0 + 2.0 * open_bins_count as f64;
        // but if current fit would be terrible (huge post_residual), allow new bin
        let would_be_waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        if would_be_waste > 0.7 {
            score -= 30.0;
        }
        // early in stream, opening bins is cheap
        score -= 20.0 * (1.0 - progress);
    }

    // Mild time-horizon pressure: late in stream, tighten up placements.
    score -= 15.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - post / cap;

    // Base: prefer tight fits (minimize post_residual), non-linearly sharpened.
    let mut score = post * (1.0 + 2.0 * fill * fill);

    // Smooth polynomial coupling of waste with stream progress:
    // late in the stream, dead space becomes more costly.
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_coupling * post * post / cap;

    // Reward near-perfect fills.
    if post == 0 { score -= 50.0; }
    else if post <= 5 { score -= 20.0 * (1.0 - post / 5.0); }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // Lookahead: penalize blocking the next item; reward if next item fits leftover.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post >= next_f {
            score -= 8.0 * (1.0 - post / cap) * (next_f / cap);
        } else {
            score += 6.0 * (next_f - post) / cap;
        }
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        // Penalty decays as existing residuals are large (item fits nowhere well).
        score = cap * 0.9 + 30.0 * (1.0 - mean_fit_gap) - 25.0 * mean_fit_gap * mean_fit_gap;
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    // Mild penalty for many open bins when the fit is loose (fragmentation control).
    score += (open_bins_count as f64).ln().max(0.0) * (post / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which fraction of capacity remains.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Dead-space penalty: residuals that are hard to fill (small but not tiny).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // 1..9 slivers are usually unusable
    }

    // Harmonic residue classes: residuals congruent to "usable" sizes
    // (multiples of 10/20 are easier to fill with typical items).
    let r = post_residual % 20;
    if r == 0 {
        score -= 30.0;
    } else if r <= 5 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 120.0 - (gap as f64).min(100.0);
        } else {
            // next item cannot follow in this bin: mild penalty scaled by overflow
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer filling already-open bins over opening new ones, especially early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open / early stream.
        score += 40.0 + 60.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
    } else {
        score -= 10.0 + 20.0 * progress;
    }

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it is already "tight" — finishing it is good.
    let diff = mean_residual - post_frac * cap;
    score += 0.3 * diff;

    // Non-linear squash on post_residual to prefer mid-range usable residuals
    // over large ones quadratically.
    score += 0.002 * post_residual as f64 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are unusable -> heavy penalty.
    let dead_zone = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64) * 0.15;

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Discourage bins far below mean residual (poor consolidation).
    score += ((mean_residual - post_residual as f64).abs()) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless nothing decent exists.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        // If no open bin fits well, allow opening a new bin sometimes.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits (post_residual small => already low base).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64) * 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect 2-chain: next item fills bin completely.
            if slack == 0.0 {
                score -= 800.0;
            } else {
                score -= 300.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; penalize more if leftover is tiny (unusable).
            let leftover = post_residual as f64;
            if leftover < 10.0 {
                score += 200.0 * (1.0 - leftover / 10.0);
            }
        }
    }

    // Compare against mean residual: prefer bins that are already tight.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: neutral-ish default, only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Late in the stream, slightly discourage opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.10 * next_item_size as f64;
        } else {
            score += 8.0 + 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0;
    }

    // Perfect or near-perfect fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Penalize creating unusable dead space relative to mean residual.
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.15 * dead;
    } else {
        score -= 0.05 * dead.abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize early (reuse bins), relax as stream progresses
    // or when many bins are open and fragmented.
    if is_new_bin {
        score += 40.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0; // fresh bin guarantees room for next item
        }
    } else {
        // Slight preference for fuller bins (best-fit flavor).
        score += 0.10 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;
    }

    // Late in the stream, favor consolidating into fewer bins.
    if progress > 0.8 {
        score -= 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;
    let x2 = x * x;
    let x3 = x2 * x;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    score += (x2 * 8.0 + x3 * 12.0) * (0.5 + t);

    // Reward tight fits, more so late in the stream
    score -= (1.0 - x2).max(0.0) * (item_size as f64 / cap) * (1.0 + t);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * t;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (next_item_size as f64 / cap) * (1.0 - t);
    }

    // Penalize bins far below the mean residual (fragmentation pressure)
    score += (mean_residual - pr).max(0.0) * 0.15;

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.05 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: partition residual space by capacity fractions (quarters).
    // A post_residual falling in a "useless" low class (can't hold typical items) is penalized.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    match class {
        0 => score -= 15.0, // tiny leftover: nearly perfect, good
        1 => score += 10.0, // awkward quarter: dead space risk
        2 => score += 5.0,  // half-full leftover: moderately reusable
        _ => {}             // large residual: bin stays flexible
    }

    // Penalize post_residual that cannot fit the next item (lookahead coupling),
    // but reward when it exactly accommodates the next item (chained fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 60.0; // perfect chain fit
            } else {
                score -= 8.0; // keeps chain alive
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5; // dead space for lookahead
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin for a marginal item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Penalize opening a new empty bin when open bins already have plenty of room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_residual = if open_bins_count > 0 { mean_residual } else { 0.0 };
        score += 70.0 + 30.0 * progress + avg_open_residual * 0.2;
    } else {
        // Slight preference for bins with less residual (fill fuller bins first).
        score += (bin_residual as f64) * 0.05;
    }

    // Harmonic modulo threshold on post_residual: residuals divisible into
    // common item sizes (10-grid multiples) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10, the classic min item size,
    // but items can be as small as 1 here, so scale the "dead zone" adaptively).
    // Penalize residuals that are too small to be useful relative to the stream.
    let dead_zone = 12.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }

    // Tight fit reward: placing item nearly filling the bin is excellent.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 15.0;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Extra reward if next item fills the leftover well.
        let next_tightness = (next_item_size as f64) / (post_residual as f64).max(1.0);
        score -= next_tightness * 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item does NOT fit: leftover may become dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones; penalize the new-bin candidate implicitly by
    // rewarding placements into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (open_bins_count as f64) * 0.3 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // But if the item fits poorly everywhere (high mean residual fragmentation
        // and few fitting bins), allow opening: reduce penalty.
        let fragmentation = if mean_residual > 0.0 { 1.0 - (item_size as f64 / mean_residual).min(1.0) } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 100.0; // no choice anyway
        } else if fragmentation > 0.7 {
            score -= 30.0 * (fragmentation - 0.7) / 0.3;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing),
    // avoid draining one bin while others stay full.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small bonus for using bins with larger residuals when item is large.
    if item_size > bin_capacity / 2 && bin_residual >= item_size {
        score -= (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Exact 2-step chain fill (bin fully consumed over two items).
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving a residual that no plausible item can use (dead space).
        if post_residual > 0 && post_residual < next_item_size.min(10).max(1) {
            score += 50.0;
        }
    }

    // Prefer bins tighter than the mean residual (good packing), penalize loose bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Mild preference for filling older/more populated bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * mean_residual / bin_capacity as f64;
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            score -= 300.0; // opening a fresh bin that chains perfectly with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space that nothing can use (min item size 1, but small gaps are wasteful)
        let gap = post_residual as f64;
        score += (gap / bin_capacity as f64).powi(2) * 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward if next item fits the post-residual (chaining), penalize otherwise
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - ni / bin_capacity as f64);
        } else {
            score += 6.0 * (ni / bin_capacity as f64);
        }
    }

    // Global pressure: when many bins are open, prefer tight packing of existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += pressure * 2.0 * (0.5 + progress);

    // Prefer bins whose residual deviates favorably from the mean (below-mean residual = tighter bin)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild time-horizon scaling: early on be conservative, later pack aggressively
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: discourage opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // opening a new bin is fine if a big item follows
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr;

    // Tightness reward: smooth quadratic coupling of fit quality
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness;

    // Lookahead coupling: reward residual that still fits the next item,
    // penalize residual just barely too small (dead space trap)
    if nx > 0.0 {
        let fits_next = (pr - nx).max(0.0);
        score -= 12.0 * (fits_next / cap);
        let miss_gap = (nx - pr).max(0.0);
        score += 18.0 * (miss_gap / cap) * (miss_gap / cap);
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Stream-progress coupling: early on, prefer consolidation;
    // late, mildly prefer keeping residuals balanced vs mean
    let mean_gap = (pr - mean_residual).abs();
    score += progress * 6.0 * (mean_gap / cap);
    score -= (1.0 - progress) * 8.0 * (pr / cap);

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (it / cap);
        score += 20.0 + 25.0 * fit_quality;
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good alternative, opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 penalize "awkward" leftover space
    let pr = post_residual as i64;
    let residue = pr % 10;
    score += match residue {
        0 => -12.0,                    // perfectly divisible leftover, very reusable
        5 => -6.0,                     // half-class, still flexible
        2 | 8 => -3.0,
        _ => 2.0,                      // odd/awkward residues are dead-space prone
    } as f64;

    // Integer-division thresholds: large leftover chunks (>= half capacity) are valuable
    if pr >= (bin_capacity as i64) / 2 {
        score -= 8.0;
    } else if pr >= (bin_capacity as i64) / 4 {
        score -= 3.0;
    } else if pr > 0 {
        score += 4.0; // small slivers waste capacity
    }

    // Coupling with next item: reward residuals that can host the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if pr >= nx {
            score -= 6.0;
            // exact harmonic match: post_residual is a multiple of next item size
            if nx > 0 && pr % nx == 0 {
                score -= 5.0;
            }
        } else {
            score += 5.0; // lookahead cannot fit here -> future must open another bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    // Progress-based tightening: late in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64) * 0.05;

    // Prefer bins already below mean residual (balancing harmonic classes)
    score += (post_residual as f64 - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=10) are wasted space.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 30.0 / (1.0 + tightness);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: strongly favor using the only bin that fits, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure on number of open bins: penalize placements that spread across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits the post residual, this placement is doubly good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Penalize bins whose residual is far below the mean (fragmented bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // New-bin candidate: keep it competitive only when open bins are fragmented or tight.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 25.0 {
            score -= 20.0; // open bins are nearly full; prefer a new bin
        } else {
            score += 15.0; // plenty of usable space remains; reuse bins
        }
    }

    // Slight time pressure: early in the stream, prefer consolidation.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score += 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: item + next item exactly fill bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize post_residual that cannot fit the next item (dead space risk),
    // scaled by how close it came to fitting.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let closeness = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 20.0 * closeness;
    }

    // Reward keeping residuals near the mean residual (harmonized bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent fits exist,
    // but allow it when the new bin enables a perfect next-item pairing.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual == next_item_size {
            penalty -= 70.0;
        }
        if item_size + next_item_size <= bin_capacity && next_item_size > 0 {
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Mild late-stream tightening: prefer tight packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins that end up with small residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: penalize residuals that are positive but too small for the
    // next item (dead space), reward residuals that can host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            let waste = post_residual as f64;
            score += 0.6 * waste;
        }
        // Chain fit: this bin's residual exactly matches the next item
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or existing bins are nearly full everywhere.
    if bin_residual == bin_capacity {
        score += 55.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 30.0; // large items better in a fresh bin
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // If mean residual across open bins is small, opening a new bin is fine.
        score -= 0.3 * mean_residual;
    } else {
        // Prefer bins with residual close to item size (best-fit flavor).
        let diff = (bin_residual - item_size) as f64;
        score += 0.1 * diff;
    }

    // Mild global pressure: many open bins -> favor filling existing ones.
    score += 1.5 * open_bins_count as f64 * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post residual with stream progress
    let mut score = x * (1.0 + 0.8 * t + 0.6 * t * t) * cap;
    score += 12.0 * x * x * (1.0 - t);
    score -= 15.0 * x * x * x * t;

    // Penalize residuals that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let fits_next = if pr as u32 >= next_item_size { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * x * (1.0 - t);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 10.0 * t;
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64 * (0.5 + t);
    }

    // Smooth coupling with mean residual: prefer bins below mean residual (tighter packing)
    score += 0.05 * (mean_residual - pr) * (1.0 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: bins whose residual falls into a
    // "usable" class (multiples of common item sizes) are more valuable.
    let mut usable_bonus = 0.0;
    for m in [10u32, 20, 25, 30, 40, 50].iter() {
        if post_residual >= *m && post_residual % m == 0 {
            usable_bonus += 8.0;
        }
        if post_residual >= next_item_size && next_item_size > 0 && post_residual % m == 0 {
            usable_bonus += 6.0;
        }
    }
    score -= usable_bonus;

    // Perfect fit is excellent
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward exact match for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Penalize leaving residual just below the smallest useful class (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Dead space: residual too small for any plausible item (min size 1, but
    // typical small items ~10): residual in [1,9] is nearly unusable
    if post_residual >= 1 && post_residual < 5 {
        score += 15.0;
    }

    // Penalize creating residual that cannot fit the next item when it could
    // have fit elsewhere
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are congested (low mean residual) or many bins are open
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 20.0;
        // Congestion makes new bins attractive
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 25.0;
        }
        // Many open bins with room: prefer reusing
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // Late in stream, prefer closing out existing bins
        if progress > 0.7 {
            score += 10.0 * progress;
        }
        // Big item into fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with larger residual when item is large
    // (keep small residuals for small items)
    if item_size > 50 && post_residual > 0 {
        score += (50.0 - post_residual as f64).max(0.0) * 0.1;
    }

    // Small tie-breaker by mean residual alignment
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // to any plausible future item are heavily penalized.
    let min_future = 1u32; // smallest possible item
    if post_residual > 0 && post_residual < 10 {
        // unusable micro-gap: nearly a full wasted unit
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // only fits tiny items: partially wasted
        score += 18.0 + (25 - post_residual) as f64 * 0.8;
    }

    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.85 {
            score -= 15.0 * fill_ratio;
        } else if fill_ratio < 0.35 && bin_residual < bin_capacity {
            // placing a small item into a large residual wastes the big gap
            score += 12.0 * (1.0 - fill_ratio);
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out; also keep score near
    // mean_residual alignment.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * open_pressure;

    // Reward using bins whose residual is close to the item (good packing).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Last-chance bin: if this is the only bin that fits, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when no open bin offers a good
    // fit (i.e., mean residual is small relative to item) or when many
    // bins are already congested.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        let congestion = open_bins_count as f64 / 8.0;
        // base penalty so we prefer reusing bins with decent fits
        score += 25.0 + congestion * 4.0;
        // but if open bins all have poor residuals (mean_residual barely
        // fits the item), opening a fresh bin becomes attractive
        if mean_gap < 15.0 {
            score -= (15.0 - mean_gap.max(-100.0)) * 1.2;
        }
        // lookahead: if next item is large and mean residual can't host it,
        // a fresh bin preserves flexibility
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Existing bin whose residual can host the next item is flexible;
        // slight reward for preserving that flexibility when possible.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // this placement destroys ability to host the known next item
            score += 6.0;
        }
    }

    // Mild stream progression term: later in the stream, waste matters
    // more since fewer opportunities remain to recover.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead coupling: reward when the NEXT item fits the leftover ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect 2-chain: next item exactly fills post_residual -> huge reward
            let exact = if next_item_size == post_residual { 60.0 } else { 0.0 };
            // Reward proportional to how well next item uses the residual
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill_ratio + exact + 10.0 * progress;
        } else {
            // Next item won't fit: penalize dead space that blocks the chain
            let dead = post_residual as f64;
            let waste_ratio = dead / bin_capacity as f64;
            score += 15.0 * waste_ratio * (1.0 + progress);
        }
    } else {
        // Last item: just minimize residual
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Compare against mean residual across open bins ---
    // Bins with residual far below mean are "tighter" fits: prefer using them
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.3 * mean_gap;

    // Penalize bins whose residual is much larger than mean (loosely filled bins
    // should be saved for large items unless this is a great fit)
    if post_residual as f64 > mean_residual * 1.5 && item_size < 50 {
        score += 8.0;
    }

    // --- Last-chance bin: strongly favor filling the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 + 5.0;
        // If the item is large relative to capacity, a fresh bin is attractive
        score -= 0.4 * item_size as f64;
        // If no existing bin fits well (post_residual huge relative to item),
        // opening a new bin becomes more attractive
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into open bins
        score += 10.0 * progress;
        // If many bins are open, discourage opening yet another
        score += 1.5 * open_bins_count as f64;
    }

    // --- Small tie-breaker against leaving awkward residuals (e.g. < 10) ---
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // nearly perfect fill, reward it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    // Lookahead: bonus if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin but not after placing current -> mild penalty for wasting chain.
            score += 4.0;
        }
        // Perfect pair: item + next exactly fill bin.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 30.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // More alternatives -> slight penalty to keep competition meaningful.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: prefer filling bins when many are open (consolidation pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // Prefer bins whose residual deviates favorably from the mean: below-mean residual = tighter bin.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // New-bin candidate: penalize opening a new bin unless current item is large and
    // no open bin offers a decent fit (encourage fresh bin for big items early).
    if bin_residual == bin_capacity {
        let base = 25.0;
        let big_item_bonus = if item_size >= bin_capacity / 2 { -20.0 } else { 0.0 };
        let early = (1.0 - progress) * 10.0;
        score += base + big_item_bonus - early;
    }

    // Mild non-linear coupling of utilization.
    let util = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * util * (1.0 - util) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit tightness: fraction of the bin consumed by this item
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = (fit_ratio - 0.5).abs(); // small when near-half fits

    // Reward near-perfect fits strongly (post_residual close to 0)
    let perfect = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 40.0 * (1.0 - perfect);

    // Penalize dead space: non-linear quadratic in post_residual
    score += 0.02 * (post_residual as f64).powf(1.5);

    // Smooth coupling: tight fits matter more later in the stream
    score -= (1.0 - tightness) * (20.0 + 30.0 * progress);

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 5.0 + 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Many open bins: prefer consolidating into bins with below-average residual
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev * (1.0 + open_bins_count as f64 / 10.0);

    // Mild preference for existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residuals that fall into "usable" residue classes.
    // Small post_residuals (0..=10) are excellent (near-perfect fit) -> strong reward.
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else if post_residual >= 70 {
        // Large leftover space is fine only for a fresh bin; for used bins it's wasteful.
        if bin_residual == bin_capacity {
            score -= 25.0;
        } else {
            score += 20.0;
        }
    }

    // Modulo arithmetic on post_residual: multiples of 10 are "harmonic" with typical
    // item sizes (multiples of 5/10), making future pairing more likely.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a new residual: judge quality of that chain.
            let chain_residual = post_residual - next_item_size;
            if chain_residual <= 10 {
                score -= 30.0;
            } else if chain_residual <= 25 {
                score -= 10.0;
            } else {
                score += chain_residual as f64 * 0.3;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted opportunity,
            // but less if post_residual is small (bin already well used).
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer filling bins with lower residual relative to the mean (tight packing).
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Early in the stream, encourage opening bins to build a good spread of residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: competitive only when no great fit exists elsewhere.
        // Base it on post_residual (= capacity - item_size) with a mild penalty that
        // decays as the stream progresses.
        score += 12.0 * (1.0 - progress);
    }

    // Slight penalty for proliferating bins late in the stream.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are already minimal, but residuals in the awkward
    // band (1..=10) are pure waste — penalize them quadratically.
    if post_residual <= 10 {
        score += (11 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post_residual, this
    // placement preserves future utility — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards; penalize proportionally.
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded
    // or this is a very early step with few open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0
            + 0.8 * open_bins_count as f64
            - 10.0 * progress
            - 0.05 * mean_residual;
    }

    // Mild pressure against proliferating bins when mean residual is high.
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 4.0;
    }
    // Next item cannot fit here: penalize proportionally to wasted lookahead potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits
    // (large item relative to residuals) or many bins are already poorly packed.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        let desperation = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).clamp(0.0, 3.0)
        } else { 3.0 };
        // Prefer new bin when item is big and mean residual is small relative to item.
        score = 100.0 - tightness * 60.0 - desperation * 20.0;
        // Late in the stream, consolidating is cheaper than opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Penalize creating tiny dead space (< 10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Mild preference for bins tighter than the mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * (1.0 + post / cap);

    // Reward tight fits strongly
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-full bin's residual if item barely fits elsewhere
    if bin_residual != bin_capacity && post < 10.0 {
        score -= 8.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are bad
    if bin_residual == bin_capacity {
        let bad_fit = post / cap; // large when item small in fresh bin
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (post_residual as f64 / cap).min(1.0) };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_bonus = -12.0 * bad_fit * bad_fit;
        // lookahead: if next item pairs with the leftover, opening a new bin is good
        if next_item_size > 0 && (next_item_size as f64) <= post {
            new_bin_bonus -= 15.0;
        } else if next_item_size > 0 {
            new_bin_bonus += 6.0;
        }
        // late in stream, consolidate rather than open
        new_bin_bonus += 10.0 * progress;
        // many open bins with slack: discourage opening
        if open_bins_count > 2 && mean_residual > post {
            new_bin_bonus += 8.0;
        }
        score += new_bin_bonus;
    } else {
        // prefer bins whose post-residual matches next item (pairing)
        if next_item_size > 0 {
            let gap = ((post_residual as i64 - next_item_size as i64).abs()) as f64;
            score -= 10.0 * (1.0 - gap.min(cap) / cap);
        }
        // spread load across bins with high residual
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;                       // normalized post residual [0,1]
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr as f64;

    // smooth non-linear coupling: quadratic/cubic terms in x modulated by progress
    score += 18.0 * x * x * (0.5 + t);      // penalize large dead space more as stream progresses
    score -= 12.0 * x * (1.0 - x) * (1.0 - t); // reward mid-range fits early (tight packing)

    // lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - pr / cap) * (1.0 - t);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // discourage spreading across many open bins when mean residual is high
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // mild preference for tighter bins overall
    score -= (bin_residual as f64 - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: values in the "usable window" [10..80]
    // are worth keeping; dead space below 10 is nearly worthless.
    if post_residual < 10 {
        score += 40.0; // dead space penalty
    } else if post_residual <= 80 {
        // reward residuals that future items (10..80) can still use,
        // scaled by how deep in the window we are
        score -= 12.0 * (post_residual as f64 / 80.0);
    } else {
        // large residual: mildly good, it stays flexible
        score -= 6.0;
    }

    // Modulo-class logic on post_residual vs next_item_size:
    // if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nr = post_residual - next_item_size;
            // harmonic remainder class: exact multiples / small remainders are good
            if nr < 10 {
                score -= 20.0 - nr as f64;
            } else if nr <= 80 {
                score -= 8.0 * (1.0 - nr as f64 / 80.0);
            } else {
                score += 4.0;
            }
            // integer-division threshold: next item divides post_residual into
            // chunks >= 10 -> still reusable
            if post_residual / next_item_size.max(1) >= 2 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Tight-fit reward: small post_residual relative to capacity
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 15.0 * tight * tight;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Spread vs mean residual: bins far below mean residual are good to fill
    score -= 3.0 * (mean_residual - post_residual as f64) / cap;

    // Early stream: be slightly greedy about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * tight * (1.0 - progress);

    // New-bin candidate handling: an empty bin has post_residual = cap - item.
    // Only prefer it when no existing bin fits well (post_residual of real bins
    // would be small). Penalize new bin unless its residual is genuinely useful.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= 100 {
            score -= 8.0; // fresh bin can host the next item too
        } else {
            score += 10.0; // discourage opening bins when fits exist
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // nothing else fits well: open the bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space also penalized (harder for future items to use).
    if post_residual >= 10 && post_residual < 20 {
        score += 20.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure on number of open bins: when many bins are open, prefer
    // consolidating into existing bins rather than opening new ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already exist,
        // but allow opening when item is large (would leave tiny residual anyway).
        score += 30.0 + open_pressure;
        if item_size > bin_capacity * 2 / 3 {
            score -= 15.0;
        }
    } else {
        // Favor existing bins slightly more as open_bins_count grows.
        score -= open_pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 90.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for next item: dead space penalty.
        score += 10.0;
    }

    // Stream progression: later in the stream, tighten up (avoid waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Prefer bins whose residual is close to what we consume (best fit flavor).
    score += (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-perfect lookahead: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportional to wasted potential.
        score += 10.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to the mean residual of open bins.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin only when residuals in open bins are large.
    if bin_residual == bin_capacity {
        score += 0.5 * mean_residual + 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host a good pair
        }
    }

    // Late in the stream: prefer tighter packing to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Penalize dead space relative to item size: small leftover after big item is fine,
    // small leftover after small item is wasteful.
    if item_size > 0 {
        let waste = post_residual as f64 / item_size as f64;
        score += 6.0 * (waste * waste).min(20.0);
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    }
    // If next item cannot fit post_residual, mild penalty proportional to leftover.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Discourage spreading into bins when many bins are open and residuals are high.
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual as f64 > mean_residual {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Early in the stream, slightly favor consolidating into fewer bins.
    score += (1.0 - prog) * open_bins_count as f64 * 0.8;

    // New-bin candidate: penalize opening a new bin unless the item is large or
    // current bin residuals are too fragmented to be useful.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let base = 18.0;
        let discount = if item_size >= 60 { 20.0 } else { 0.0 }
            + if fragmentation < 0.15 { 12.0 } else { 0.0 };
        score += base - discount;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling: penalize residual more strongly as stream progresses
    let norm_post = post / cap;
    score += (norm_post * norm_post) * cap * (0.5 + progress);

    // Reward tight fits (low post residual) with a smooth quadratic bonus
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 8.0;

    // Last-chance bonus: strongly prefer the only fitting bin, smoothly scaled
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Penalize bins that are much tighter than the average open bin
    score += (mean_residual - post) * 0.05;

    // Lookahead: penalize leaving residual just below the next item size (smooth gap)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 {
            score += gap * gap / cap * 2.0;
        } else {
            score -= gap * 0.3;
        }
    }

    // Mild preference for reusing open bins over opening new ones
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Dead space classes: residuals not expressible as sums of typical item sizes are worse
    let dead_penalty = match class {
        0 => -6.0,   // perfectly harmonic
        5 => -4.0,
        2 | 8 => -2.0,
        4 | 6 => -1.0,
        1 | 9 => 3.0,
        3 | 7 => 4.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Large post_residual is good (leaves room), tiny-but-nonzero post_residual is dead space
    if pr == 0 {
        score -= 25.0; // perfect fit reward
    } else if pr < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let fit_frac = next_item_size as f64 / pr as f64;
            score -= 8.0 * fit_frac;
        } else {
            // next item cannot use this residual; residual likely wasted
            score += 4.0 + 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 10.0;
        // opening a new bin is fine late in the stream when many bins already open
        score -= 0.02 * open_bins_count as f64;
        // if next item is huge, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Small stream-progression term: early on, be conservative about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (pr as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post-residuals that are too small to be
    // usable by future items are heavily penalized (quadratic in gap smallness).
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        let dead = (min_useful - post_residual) as f64;
        score += dead * dead * 0.35;
    }
    // Zero post-residual (perfect fit) is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: the smaller the item relative to residual, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins when few bins fit.
    let obp = open_bins_count as f64;
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 30.0;
    } else {
        score += obp * 1.5;
    }

    // New-bin candidate handling: only attractive when open bins have poor fit
    // potential (high mean residual wasted) or stream is early.
    if bin_residual == bin_capacity {
        let waste = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - waste * 20.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0; // new bin will perfectly serve the next item too
        }
    } else {
        // Slight penalty proportional to how much mean residual deviates
        // from this bin's residual (prefer bins consistent with fleet state).
        score += (bin_residual as f64 - mean_residual).abs() * 0.1;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_fit = next_item_size as f64 / post_residual as f64;
        if nxt_fit > 0.8 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space at all).
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual > next_item_size {
            // Next item fits here afterwards: mildly reward closeness of match.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize leftover sliver.
            let waste = next_item_size - post_residual;
            if post_residual < 10 {
                score += 25.0 + waste as f64;
            }
        }
    }

    // Penalize creating unusable dead space (residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Reward bins tighter than the current mean residual (compact packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Discourage opening a brand-new bin when reasonable alternatives exist,
    // unless the item is large and would leave a very awkward residual.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 10;
        if !awkward {
            score += 30.0 + 0.5 * open_bins_count as f64;
        } else {
            score += 5.0;
        }
    }

    // Late in the stream, consolidate: slightly favor already-open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: small post-residual is good.
    score -= (cap - post) * 0.15;

    // Penalize dead space that is too small to be useful later (below min item size 10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == post {
            score -= 40.0;
        } else if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + post * 0.1;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is wasteful when good fits exist elsewhere.
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Early in the stream, keeping options open is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Few open bins -> new bin less costly.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    } else {
        // Prefer bins whose residual is below the mean (consolidate fullness).
        score += (post - mean_residual) * 0.2;
        // Reward using bins that are already quite full.
        let fullness = 1.0 - (bin_residual as f64 / cap);
        score -= fullness * 10.0;
    }

    // Late in the stream, prefer tightest possible packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth progress-weighted penalty: dead space matters more later in stream
    let w = 0.5 + 0.5 * progress;
    score += w * (x * x) * cap * 0.5;

    // Reward tight fits (small post residual) with a quadratic bonus
    score -= (1.0 - x) * (1.0 - x) * 10.0;

    // Exact fit gets strong reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter)
    score -= 0.3 * (mean_residual - pr);

    // Mild penalty for very large wasted residual via cubic term
    score += 4.0 * x * x * x * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item (size 1..100 unknown,
    // but use harmonic class boundaries). Penalize residuals in the "unusable sliver" class.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Harmonic class of post_residual via integer division on capacity quarters.
    // Class 0: post_residual >= 3/4 C (roomy), class 3: tiny.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    match class {
        0 => score -= 12.0,                 // very roomy remainder
        1 => score -= 6.0,                  // decent remainder
        2 => score -= 1.0,                  // half-class
        _ => score += 8.0,                  // small remainder class
    }

    // Modulo coupling: residuals divisible into clean capacity fractions are better
    // (they align with common item sizes). Reward post_residual % 25 == 0 style alignment.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward if next item fits almost exactly (harmonic complement).
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: penalize proportional to wasted fraction.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; add pressure proportional to stream progress
        // so late in the stream we prefer consolidating into open bins.
        score = cap_f * 0.6 + (step_index as f64 / (total_items.max(1) as f64)) * 20.0
            + (open_bins_count as f64).sqrt() * 2.0;
        // If next item is huge, a fresh bin is more attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference to balance residuals toward the mean (avoid one bin hogged, others stranded).
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 stream)
    // Treat residuals below a "useful threshold" as progressively wasted.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Strong penalty for very tiny unusable gaps (classic dead-space trap)
    if post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (near-perfect packing)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Open-bin pressure: discourage spreading across many bins when a good fit exists
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty if the leftover is dead space for it
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean
    score += (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer opening a new bin when existing placements would create large dead space.
    if bin_residual == bin_capacity {
        // Base neutral cost of opening a new bin
        score += 12.0;
        // Escalate open-bin pressure over the stream
        score += (step_index as f64 / total_items.max(1) as f64) * 6.0;
    }

    // Slight progression scaling of dead-space penalty (late stream, be stricter)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.0 + progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: low post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - chain_waste / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 8.0 + 10.0 * (1.0 - dead / (next_item_size as f64));
            }
            // If post_residual is tiny (unusable), penalize more.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0 * tightness;
    }

    // Mean-residual coupling: prefer bins below mean residual (fill emptier-toward-full bins).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Prefer new bin if existing fits would leave big dead space or none fit tightly.
        let bad_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score = 45.0 + 20.0 * bad_fit + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when only one bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward residuals that can still fit the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 10.0;
        } else {
            score += 6.0;
        }
        // Extra reward if next item fits exactly into post_residual.
        if post_residual == next_item_size as u32 {
            score -= 12.0;
        }
    } else {
        // Last item: prefer filling an existing bin as much as possible.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are already open and could fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits (fitting_bins_count excludes new bin), allow opening.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state coupling: if mean residual is large, prefer bins below mean
    // (consolidate into emptier bins to keep tight bins for small items).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Mild penalty for creating residuals that are awkward (e.g. between 31 and 49,
    // hard to fill with typical items but not zero).
    if post_residual >= 31 && post_residual <= 49 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: post residual, smoothed with a non-linear penalty on small residuals (dead space)
    let mut score = post * (1.0 + 0.8 * norm_post * (1.0 - norm_post));

    // Non-linear coupling with stream progress: early on, tolerate waste; later, punish it harder
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Perfect fit reward (subtract), stronger as stream progresses
    let fit_ratio = 1.0 - norm_post;
    score -= 20.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (imbalance), smooth quadratic
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // Lookahead: reward if next item could fill this bin's post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (nxt / cap) * (1.0 - (post - nxt) / cap).abs();
        } else {
            score += 3.0 * ((nxt - post) / cap);
        }
    }

    // Mild penalty for too many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let frac = post_residual as f64 / cap; // 0.0 (perfect) .. 1.0 (new bin)
    // Dead-space classes: residuals that can rarely be refilled (<= 10, or 11..=19 awkward).
    let dead = if post_residual == 0 { 0.0 }
        else if post_residual <= 10 { 3.0 }
        else if post_residual <= 19 { 1.5 }
        else if post_residual <= 30 { 0.8 }
        else { 0.0 };
    score += dead;

    // Perfect-fit reward: harmonic class 0.
    if post_residual == 0 { score -= 40.0; }

    // Tight fit: residual used is a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: penalize if next item cannot use this bin's post_residual.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += 6.0 + 0.05 * (next_item_size - post_residual.min(next_item_size)) as f64;
        } else {
            // next item fits: reward proportional to how well it fills leftover
            let nfill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 * nfill;
        }
    } else {
        // last item: prefer filling existing bins, avoid new bins
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin starts with full residual (high score naturally),
    // but modulate: if any open bin fits (fitting_bins_count > 0), discourage new bin
    // unless this item is huge and current residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 20.0; // base penalty for opening a new bin
        if fitting_bins_count == 0 {
            score -= 45.0; // forced: no open bin fits
        } else if item_size >= 60 && mean_residual < (item_size as f64) {
            score -= 30.0; // item barely fits anywhere, avoid fragmenting? actually prefer new bin
        } else if mean_residual / cap > 0.5 && item_size <= 30 {
            score -= 10.0; // small item, plenty of room around: still mild penalty
        }
    }

    // Stream progression: early on, be more willing to open bins (explore); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * progress;
    }

    // Mean-residual coupling: many fragmented open bins -> discourage spreading.
    if open_bins_count > 4 && mean_residual / cap < 0.35 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Harmonic modulo class on post_residual: residuals in [10,20) mod 10 are awkward.
    if post_residual > 0 && post_residual % 10 != 0 && post_residual < 40 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to plausibly hold a future item
    // (assume min item size ~ 1..100, treat gaps < 25 as increasingly wasteful).
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 25.0 {
        score += (25.0 - gap) * 3.0; // steep penalty for near-dead space
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward filling a bin deeply (low post_residual relative to capacity)
    score -= (bin_capacity as f64 - gap) * 0.1;

    // Open-bin pressure: prefer using existing bins over opening new ones
    // when the fit is decent.
    if bin_residual != bin_capacity {
        // existing bin: subtract to favor reuse, scaled by congestion
        score -= 5.0 + open_bins_count as f64 * 0.5;
        // last-chance bin: strongly favor placing here if it fits
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    } else {
        // brand-new bin candidate: penalize unless current bins are congested
        // or this is a very tight fit that existing bins can't match.
        score += 15.0 + open_bins_count as f64 * 0.3;
        // If the item exactly fills a fresh bin, opening a new one is fine
        if item_size == bin_capacity {
            score -= 60.0;
        }
    }

    // Lookahead: if next item would fit snugly in the post residual, reward;
    // if next item is bigger than post residual, penalize slightly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= slack.max(0.0) * 0.2 + 3.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight fit — favor it.
    score += (mean_residual - gap) * 0.3;

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            // Perfect chain: next item exactly fills post-residual -> strong reward
            let diff = post_residual as f64 - nx;
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 { score -= 15.0; }
        } else {
            // Next item cannot chain into this bin: penalize dead space relative to mean residual
            score += 0.6 * (post_residual as f64 - mean_residual).abs();
            // Extra penalty if post-residual is a small unusable sliver
            if post_residual > 0 && post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Reward tight fits (small post residual) especially under bin pressure
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 5.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // When many bins are open, prefer consolidation (small post-residual weighted more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (open_bins_count as f64).ln().max(0.0) * tightness;

    // Penalize opening a new bin when a decent fit exists among open bins
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 4.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: post_residual too small for any plausible future item (1..=100).
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 25.0 * dead * dead * (1.0 - tight);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = (next_item_size as f64) / (post_residual as f64);
        score -= 20.0 * lookahead_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize creating stranded space.
        score += 8.0;
    }

    // Global state coupling: when mean residual is high, prefer filling existing bins.
    if bin_residual < bin_capacity {
        let mr = mean_residual / (bin_capacity as f64);
        score -= 6.0 * mr;
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep options open);
    // late in the stream, consolidate into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper early, expensive late.
        score = 45.0 + 55.0 * t;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Never open a new bin when a last-chance bin exists.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    } else {
        // Existing-bin preference grows with progress.
        score -= 15.0 * t;
        // Many open bins: encourage consolidation.
        score += 1.5 * open_bins_count as f64 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: polynomial in normalized post_residual modulated by progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 24.0 * poly * (0.5 + progress);

    // Reward tight fits, penalize large waste with quadratic growth
    let tight = 1.0 - norm_pr;
    score -= 6.0 * tight * tight * (1.0 + progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 + 4.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer it late in the stream or when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score -= 5.0 * progress + 4.0 * fragmentation;
    } else {
        // Slight penalty for spreading across many open bins
        score += 0.3 * (open_bins_count as f64).sqrt();
    }

    // Mean-residual deviation term (smooth coupling)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste quantized in 10-unit bands.
    let band = post_residual / 10;
    score += band as f64 * 2.5;

    // Reward tight fits (post_residual small) super-linearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals that few item sizes can use (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic class: does next_item_size divide into post_residual cleanly?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact or near-exact follow-up fit is very desirable.
            let rem2 = post_residual % next_item_size;
            if rem2 == 0 {
                score -= 20.0;
            } else if rem2 <= 5 {
                score -= 8.0;
            } else {
                score += rem2 as f64 * 0.3;
            }
            // Bonus if next item exactly fills the bin after placement.
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this bin's residual; penalize leaving large gaps.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 3.0 + mean_residual * 0.15;
        // Opening a new bin is penalized unless current fit is terrible.
        if post_residual < bin_capacity {
            score = 1000.0 - pressure.min(200.0);
        }
        // If all residuals are fragmented (mean residual high but unusable), new bin wins.
        if mean_residual > 25.0 && fitting_bins_count == 1 {
            score -= 150.0;
        }
    }

    // Progress coupling: late in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Prefer bins whose residual is close to mean (keep residuals uniform).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any small unusable gap is heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 250.0 * (dead_threshold - post_residual) as f64;
    }

    // Penalize medium-small gaps that likely become dead space later.
    if post_residual >= dead_threshold && post_residual < 30 {
        score += 0.5 * (30 - post_residual) as f64;
    }

    // Reward gaps that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Extra reward if lookahead fits snugly into the post gap.
        if post_residual - next_item_size < dead_threshold {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size >= bin_residual {
        // Lookahead won't fit here anyway; slight penalty to deprioritize.
        score += 10.0;
    }

    // Open bins pressure: discourage spreading across too many bins,
    // but relax pressure when this bin is the last chance.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }
    score += 3.0 * open_bins_count as f64;

    // Prefer bins whose residual deviates below the mean (tighter bins fill first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow more liberal bin usage; later, be conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress);

    // New-bin candidate: only attractive when current item is large or nothing fits well.
    if bin_residual == bin_capacity {
        if item_size >= 60 || (fitting_bins_count <= 1 && bin_residual >= item_size) {
            score -= 200.0;
        } else {
            score += 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: perfect match with next item is ideal
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        // If next item fits exactly after this placement, strongly favor
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize if post_residual is too small for next item but nonzero (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid wasting the only fitting bin's capacity on a bad fit
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if lookahead pairs perfectly with a fresh bin, allow it
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, favor existing bins
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (waste-aware quadratic penalty on post-residual)
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * (next_item_size as f64);
        } else {
            // creating dead space the next item cannot use
            score += 6.0;
            // extra penalty if the dead space is small and unusable
            if post_residual < 10 {
                score += 10.0;
            }
        }
        // perfect chain fit: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // last item in stream: pure waste minimization, prefer any open bin
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have poor residuals relative to the item
    if bin_residual == bin_capacity {
        let pressure = mean_residual - item_size as f64;
        // if mean residual comfortably exceeds item, discourage new bin
        score += 30.0 + pressure.clamp(-40.0, 40.0);
        // late in the stream, avoid opening bins (no time to fill them)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // early stream: new bins are cheap-ish
        score -= 10.0 * (1.0 - progress);
        // if no open bin fits at all, allow the new bin
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    let consolidation = (open_bins_count as f64).ln() * (mean_residual - post_residual as f64);
    score += 0.15 * consolidation;

    // Slight preference for bins with residual close to item size (perfect fit shaping)
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer minimal post_residual, non-linearly (waste amplification).
    let mut score = post * (1.0 + 0.9 * (post / cap).powi(2));

    // Smooth stream-progress coupling: tighten packing as stream advances.
    score *= 1.0 + 0.6 * progress * (post / cap);

    // Reward high fill ratio (item nearly fills the bin) via smooth saturation.
    let fill = (item / cap).clamp(0.0, 1.0);
    score -= 12.0 * fill * fill;

    // Lookahead: penalize leaving residual too small for the next item,
    // reward leaving residual that exactly accommodates it.
    if nxt > 0.0 {
        let gap = (post - nxt).abs();
        score += 0.35 * gap;
        score -= 6.0 * (-((post - nxt) / cap).abs() * 8.0).exp();
        // Perfect lookahead fit bonus
        if post == nxt {
            score -= 10.0;
        }
    }

    // Mean-residual context: if this bin's residual is far below the mean,
    // closing it out is good; penalize leaving isolated large residuals.
    let dev = (res - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Last-chance bin: strongly reward using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete, prefer tightest.
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive if nothing else fits well
    // or the item is large relative to capacity (better to start fresh).
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0;
        let big_item = item / cap > 0.7;
        if desperate || big_item {
            score -= 20.0 + 15.0 * big_item as i32 as f64;
        } else {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild open-bin pressure: with many open bins, prefer reusing existing ones.
    score += 0.15 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common item sizes are more valuable.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 20 == 0 { harmony_bonus += 4.0; }
        if pr % 25 == 0 { harmony_bonus += 3.0; }
        if pr % 50 == 0 { harmony_bonus += 3.0; }
        // small residuals are dead space unless perfectly harmonic
        if pr < 10 { harmony_bonus -= 12.0; }
        else if pr < 20 { harmony_bonus -= 6.0; }
    } else {
        // perfect fill: strong reward
        harmony_bonus += 30.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            harmony_bonus += 8.0;
            // extra reward if leftover after next item is again harmonic
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { harmony_bonus += 3.0; }
            if pr2 == 0 { harmony_bonus += 10.0; }
        } else {
            harmony_bonus -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        harmony_bonus -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, softened when many bins already open
        // and mean residual is high (existing bins are fragmented).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        let new_bin_cost = 40.0 + 20.0 * fragmentation - 10.0 * progress;
        harmony_bonus += new_bin_cost;
    }

    // Slight penalty when this bin's residual deviates far from mean (balance bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    harmony_bonus += 0.05 * dev;

    score -= harmony_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space". Penalize them quadratically.
    let dead_threshold = 25.0;
    if (post_residual as f64) < dead_threshold {
        let gap = dead_threshold - post_residual as f64;
        score += 6.0 * gap * gap;
    } else {
        // Reward leaving a residual that can host a mid-size item
        score -= 4.0 * ((post_residual as f64) - dead_threshold).sqrt();
    }

    // Perfect or near-perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0;
        if slack < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; mildly penalize leaving a gap it almost fits
        if next_item_size - post_residual <= 8 {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6
            + pressure * 3.0
            + if fitting_bins_count == 0 { -100.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= item_size { -5.0 } else { 0.0 };
    }

    // Slight progression term: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is typical or tight
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= (bin_capacity as f64 / (1.0 + tightness)) * 0.5;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits into post_residual, this is a great pairing.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64 * 0.4);
    } else if next_item_size > 0 {
        // Penalize leaving residuals that waste the next item's potential.
        let waste = post_residual as f64 - (next_item_size as f64 * 0.5);
        if waste > 0.0 {
            score += waste * 0.25;
        }
    }

    // Compare against mean residual: bins below mean residual are more "settled".
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: only open a new bin when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bins unless the fit elsewhere would be terrible.
        score += 40.0
            + (post_residual as f64 * 0.2)
            - (mean_residual * 0.15)
            + (open_bins_count as f64 * -0.5);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Late in the stream, prefer consolidation into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score -= 40.0 * poly * (0.5 + progress);

    // Tight fits are strongly favored
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness;

    // Penalize dead space relative to mean residual
    score += 0.5 * (pr - mean_residual).abs();

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            score += 5.0 * (1.0 - (cap - next_item_size as f64) / cap);
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer keeping number of open bins moderate
    score += 0.2 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let q = post_residual / (bin_capacity / 4).max(1);
    let harmonic_penalty: f64 = match q {
        0 => 0.0,                       // near-perfect fit
        1 => 6.0,                       // dead space of 25-50% band
        2 => 12.0,                      // 50-75% band
        _ => 20.0,                      // mostly-empty bin placement
    };
    score += harmonic_penalty;

    // Reward when post_residual can exactly host the next item (harmonic pairing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // partial harmony: next item still fits, scaled by slack left after that
        let slack = post_residual - next_item_size;
        score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space cannot serve the lookahead item
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if
    // this placement would create large unusable residue in a crowded field.
    if bin_residual == bin_capacity {
        let waste_threshold = bin_capacity / 2;
        if post_residual > waste_threshold && fitting_bins_count > 0 {
            score -= 10.0; // fresh bin beats wasting a big slot
        } else {
            score += 15.0; // prefer existing bins for reasonable fits
        }
    }

    // Tightness reward: reward near-full packing nonlinearly
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Progress modulation: later in the stream, be more conservative with residue
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: penalize bins far below mean residual (fragmenting)
    score += 0.5 * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for typical
    // items (1..=100 range) are nearly worthless; penalize them heavily.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    // Perfect fit: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward fits that leave room for the lookahead item (k=2) exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Penalize blocking the next item into a near-miss gap.
        let miss = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += 0.15 * miss;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // Open-bin pressure: discourage spreading across many open bins; favor
    // consolidating into existing bins when several bins are open.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean residual (denser bins),
    // which concentrates capacity into fewer bins.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty so it is only chosen when existing fits
    // are poor, but keep it competitive when open bins are numerous.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // If the item is large, opening a fresh bin is reasonable.
        score -= 0.05 * item_size as f64;
    }

    // Late in the stream, tighten up: dead space matters more as we approach
    // the end since there is less time to recover it.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            // next item fits: mild reward proportional to how snugly
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit: penalize leftover dead space relative to mean residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
        // small residual unusable by next item is dead space
        if post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
    }

    // Compare residual against mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening new bins when open bins can fit and stream is progressing
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * progress;
    }

    // Slight preference to fill bins with larger residual less when many bins open
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within stream (0..1)
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Tight fit reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 18.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 8.0 * fit_ratio;
    }

    // Penalize large dead space relative to typical future needs.
    if post_residual as f64 > mean_residual * 1.4 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin normally, but if the
    // item is large and current residuals are all small, opening is fine.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 * (1.0 - 0.5 * progress);
        let pressure = if mean_residual < item_size as f64 { 20.0 } else { 0.0 };
        score += base_penalty - pressure;
        // Perfect fit of a large item in fresh bin: mild bonus.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, reward leaving
    // that exact space (chain packing).
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 15.0;
        } else if diff > 0 && (diff as u32) <= 10 {
            score -= 6.0;
        } else if diff < 0 && (-diff) as u32 <= 10 {
            score += 4.0;
        }
    }

    // Many open bins: encourage consolidating into existing bins rather
    // than spreading; slight extra reward for using fullest-fitting bin.
    if open_bins_count > 4 {
        score -= 3.0 * (1.0 - fit_ratio.min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, weight residual waste more.
    let prn = pr / cap;
    let coupling = prn * prn * (1.0 + progress * 2.0) + prn * (1.0 - progress);
    score += 30.0 * coupling;

    // Reward fitting into nearly-full bins (small post_residual) with a smooth bonus.
    score -= 20.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize placements that leave residual too small for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            // Smooth reward when residual still accommodates next item well.
            let fit_quality = 1.0 - ((pr - nx) / cap).powi(2);
            score -= 6.0 * fit_quality.max(0.0);
        }
    }

    // Mean residual pressure: bins far below mean residual are less attractive late.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + progress);

    // Penalize spreading across too many open bins.
    score += 0.3 * open_bins_count as f64 * prn;

    // New-bin candidate: only attractive when existing bins would waste a lot.
    if bin_residual == bin_capacity {
        let waste_pressure = mean_residual / cap;
        score = pr + 40.0 - 35.0 * waste_pressure * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Perfect fills (0) are heavily rewarded; small dead space (1..=5) heavily penalized.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score += 25.0; // unusable sliver
    } else if post_residual <= 10 {
        score += 8.0;
    }

    // Integer-division thresholds: post_residual buckets by capacity/8.
    let eighth = (bin_capacity / 8).max(1);
    let bucket = post_residual / eighth;
    score += match bucket {
        0 => -10.0,
        1 => 2.0,
        2 => 0.0,
        3 => -3.0,
        _ => 1.0,
    };

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / cap);
            if slack <= 5 { score += 10.0; }
        }
        // Harmonic complement: next_item + item_size == capacity means perfect pairing
        if next_item_size + item_size == bin_capacity {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones over spreading.
    score -= (open_bins_count as f64).ln() * 2.0 * (item_size as f64 / cap);

    // Tight fits rewarded: closeness of item to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness;

    // New-bin candidate: penalize mildly unless current fit is terrible,
    // so a fresh bin wins only when the alternative wastes space.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if post_residual of an existing fit would be a tiny sliver, new bin looks good:
        // handled implicitly since sliver bins get +25.
        if post_residual == bin_capacity {
            score -= (open_bins_count as f64) * 0.5; // slight damping early
        }
    }

    // Progress coupling: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / cap);

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced filling).
    score -= 3.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item are "dead" — penalize them super-linearly.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // unreachable, but guard
    }
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score -= 20.0 / (post_residual as f64);
    }

    // Reward using a bin whose residual closely matches the item (perfect match).
    let fit_gap = (bin_residual as f64 - item_size as f64);
    score -= 15.0 * (1.0 - fit_gap / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; penalize the new-bin candidate.
    let pressure = (open_bins_count as f64) * 0.8;
    if bin_residual == bin_capacity {
        score += 10.0 + pressure;
        // But if this bin would be nearly full afterwards, opening is fine.
        let new_post = bin_capacity as f64 - item_size as f64;
        if new_post <= dead_threshold {
            score -= 25.0 + pressure;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (denser bins),
    // keeping emptier bins available for larger future items.
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Lookahead: if next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Early stream: be slightly more conservative (keep bins flexible).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chains item -> next_item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // next item exactly fills this bin
        } else if post_residual > next_item_size {
            let r2 = post_residual - next_item_size;
            score -= 12.0 / (1.0 + r2 as f64); // chain leaves small dead space
        } else {
            // next item won't fit here; penalize wasted residual
            score += 0.05 * post_residual as f64;
        }
    }

    // Tight fit reward: residual close to item size
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 8.0 * tightness;

    // Penalize leaving tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins already below-average residual
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: default mild penalty; allow opening only when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host a full 2-item chain
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative, open new bin
        }
    }

    // Late-stream consolidation: favor packing into few bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit gets a large reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual of an empty bin is large, so it's naturally penalized,
    //  but give it a dynamic bonus when existing bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in the stream, opening a new bin is cheaper than wasting space.
        let new_bin_bonus = 30.0 * (1.0 - progress) - 40.0 * fragmentation;
        score += new_bin_bonus;
        // Penalize opening a new bin when several bins already fit the item.
        if fitting_bins_count >= 2 {
            score += 80.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward for a near-perfect two-item packing.
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 30.0;
            }
        } else {
            // Post-residual too small for the next item: dead space penalty,
            // scaled by how much of the residual is wasted.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Prefer bins with residual below the mean (consolidate waste into few bins).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.3 * residual_gap;

    // Mild preference for using more-open bins (keeps bin count manageable).
    score += 0.5 * open_bins_count as f64;

    // Slight time-varying exploration pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (progress - 0.5) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post residual, with non-linear emphasis.
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Smooth stream-progress coupling: later in the stream, tolerate tight fits more
    // (consolidation), earlier prefer leaving room (exploration).
    score *= 1.0 + 0.25 * (progress - 0.5) * (norm_post - 0.5);

    // Dead-space penalty: residuals too small to plausibly fit a future item.
    let dead = (norm_post - 0.1).max(0.0) * (0.1 - norm_post).max(0.0);
    score -= 30.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post - norm_next * cap) / cap).abs();
        score -= 8.0 * snug * norm_next;
    } else if next_item_size > 0 {
        score += 4.0 * norm_next * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading across many bins when mean residual is high.
    score += 0.15 * open_bins_count as f64 * (mean_residual / cap) * norm_item;

    // New empty bin candidate: only attractive when no open bin fits well.
    let is_new = (bin_residual == bin_capacity) && bin_capacity > 0;
    if is_new {
        if fitting_bins_count == 0 {
            score = -100.0;
        } else {
            score = post * (1.0 + 0.6 * norm_post * norm_post)
                + 40.0
                + 20.0 * (1.0 - progress) * (fitting_bins_count as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small divisors.
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r20 = (pr % 20) as f64;
    let q10 = (pr / 10) as f64;

    // Penalize awkward dead space: post_residual that is small but nonzero
    // is nearly unusable (items >= 10 in classic regime).
    if pr > 0 && pr < 10 {
        score += 12.0;
    }
    // Perfect fits are golden.
    if pr == 0 {
        score -= 30.0;
    }

    // Harmonic bonus: post_residual that is a multiple of 10 or 20 is
    // more likely to be exactly filled by future items.
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0;
    }
    if pr > 0 && pr % 20 == 0 {
        score -= 4.0;
    }

    // Fractional penalty tied to capacity fraction occupied.
    let frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * frac;

    // Lookahead: reward bins whose post_residual can host the next item,
    // with harmonic coupling on next_item_size class.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward when post_residual - next_item_size is again harmonic.
            let pr2 = post_residual - next_item_size;
            if pr2 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0;
        }
        // Penalize near-miss: next item barely doesn't fit.
        if post_residual < next_item_size && next_item_size - post_residual <= 5 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-ish but penalize when open bins
    // have plenty of slack (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (mean_residual / bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Tightness coupling: prefer bins whose residual is close to item size.
    let tight = (bin_residual - item_size) as f64;
    score += 0.1 * tight;

    // Small residue-modulation to break ties deterministically.
    score += 0.01 * r10 - 0.005 * r20 + 0.002 * q10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // awkward gap
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to residual (waste ratio).
    if bin_residual > 0 {
        score += 0.6 * (item_size as f64 / bin_residual as f64).recip().min(3.0);
        score -= 0.8 * (item_size as f64 / bin_residual as f64);
    }

    // Pressure from number of open bins: prefer filling existing bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but give it a fresh large residual advantage.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space for the known next item
    }

    // Mean residual context: bins far below mean residual are less attractive.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-perfect match: next item fits with small leftover (<= 5).
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover <= 5 {
            score -= (6 - leftover) as f64 * 3.0;
        }
    }

    // Penalize residuals too small for the next item (dead space risk),
    // but only mildly if the next item is large relative to capacity.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.15;
    }

    // Tight fit reward: residual almost exactly consumed by current item.
    if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: bins with residual near mean are neutral,
    // bins far above mean (underfilled) get a small bonus to consolidate.
    let resid = post_residual as f64;
    let dev = (resid - mean_residual).abs();
    score -= dev * 0.05;

    // Early in the stream, be more willing to open/spread bins; late in the
    // stream, pack tightly to avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 - progress * 2.0;

    // Mild penalty if many open bins (encourage consolidation into fewer bins).
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: only attractive when current item is large and
    // no open bin fits well (post_residual would be small in a fresh bin).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 20.0;
        // Attractive when item is large (poor fit elsewhere likely).
        score -= (item_size as f64 / 100.0) * 12.0;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base, but
    // amplify the advantage of near-perfect packing.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (1.0 - tightness) * 20.0;

    // Penalize creating dead space that no plausible future item can use:
    // if post_residual is smaller than the smallest item (1..100 unknown,
    // assume conservative 10), it is wasted capacity.
    if post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; mild penalty since residual stays stranded.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * (open_bins_count as f64);
    }

    // New-bin candidate handling: opening a new bin is justified when
    // existing bins fit poorly. Compare item fit against mean residual.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to open bins (fragmentation).
        score = bin_capacity as f64 + 5.0;
        // If existing bins are crowded (mean residual small relative to item),
        // a new bin is more attractive: discount it.
        let crowdedness = mean_residual / (bin_capacity as f64);
        score -= crowdedness * 30.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
        // If many bins can fit the item, a new bin is clearly wasteful.
        score += (fitting_bins_count as f64) * 6.0;
    } else {
        // Prefer bins whose residual is close to item_size (best-fit flavor)
        // but also slightly prefer fuller bins generally.
        let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
        score -= fill_ratio * 5.0;
        // Spread load when too many bins are open with large residuals.
        if mean_residual > 0.5 * (bin_capacity as f64) && open_bins_count > 3 {
            score += 3.0;
        }
    }

    // Global pressure: when few bins fit the item across the system,
    // reward using this one to avoid proliferation.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let it = item_size as f64;
    let fit_ratio = it / cap;

    // Reward tight fits: strongly discount small post_residual with a non-linear term.
    score -= (cap - pr) * (0.5 + fit_ratio) * (1.0 + 0.5 * progress);

    // Non-linear penalty on dead space: post_residual that is too small to fit
    // typical future items is wasted; penalize quadratic growth of unusable space.
    let unusable = if (next_item_size as f64) > pr { pr } else { 0.0 };
    score += 0.35 * (unusable / cap) * (unusable / cap) * cap;

    // Smooth interaction: waste matters more as the stream progresses.
    score += 0.25 * (pr / cap) * (pr / cap) * cap * progress;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let chain = next_item_size as f64 / cap;
        score -= 8.0 * chain * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let badness = (mean_residual - it).max(0.0) / cap;
        score += 15.0 + 10.0 * (1.0 - badness) * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (consolidating emptier bins).
    score += 0.1 * ((pr - mean_residual) / cap) * cap.max(1.0) / cap * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that are "useful"
    // for typical future items. Classify via capacity fractions and modulo.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual (tight fit) with a non-linear squash.
    let tightness = 1.0 - (pr / c);
    score -= 2.5 * tightness * tightness;

    // Harmonic class penalty: residuals in "dead zones" (very small, unusable)
    // are penalized more than mid-range residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Modulo-class logic: residuals that are multiples of common size classes
    // (e.g., multiples of 10, 20, 25) are more likely to be exactly filled.
    let r = post_residual;
    if r % 10 == 0 { score -= 6.0; }
    if r % 20 == 0 { score -= 3.0; }
    if r % 25 == 0 { score -= 3.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: mild reward scaled by fit ratio
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fit_ratio;
        } else {
            // next item cannot use this bin's remainder: penalize large leftovers
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Large items justify fresh bins (avoid fragmenting open bins).
        if item_size >= 50 { score -= 20.0; }
        if item_size >= 70 { score -= 10.0; }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many bins are open already, discourage spreading.
        score += 0.5 * open_bins_count as f64;
        // If mean residual across open bins is small, a new bin is attractive.
        if mean_residual < item_size as f64 { score -= 8.0; }
    } else {
        // Favor placing into bins whose residual is close to the item (best fit).
        let waste = (bin_residual - item_size) as f64;
        score += 0.2 * waste;
        // Prefer bins with below-mean residual (fill fuller bins first).
        if (bin_residual as f64) < mean_residual { score -= 3.0; } else { score += 2.0; }
    }

    // Slight preference to keep number of open bins low when item fits many bins.
    if fitting_bins_count > 3 { score -= 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps that no
    // plausible future item (>= 1) could use efficiently.
    if post_residual > 0 {
        // gap smaller than the smallest meaningful item is pure waste
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 25 {
            score += 12.0;
        } else if post_residual < 50 {
            score += 4.0;
        }
    }

    // Strongly reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual closely matches the item (good packing density).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless existing bins are badly
    // fragmented (mean residual very low relative to item size) or no open
    // bin fits well.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // base penalty for opening a new bin
        score += 18.0;
        // but if open bins are nearly full / fragmented, opening is fine
        score -= 25.0 * (1.0 - fragmentation.min(1.0));
        // late in the stream, filling existing bins matters more
        score += 10.0 * progress;
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 12.0;
        } else if slack <= 15 {
            score -= 5.0;
        }
    }
    // Penalize if post_residual is just barely too small for the next item
    // (dead space we could have avoided by choosing differently).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: minimize wasted space, but reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // extra reward if next item then leaves near-zero residual again
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here; penalize leaving medium dead space
            if post_residual >= 10 {
                score += 6.0;
            }
            // but if the bin would be nearly empty anyway, mild penalty
            if post_residual < 10 {
                score -= 3.0;
            }
        }
    } else {
        // last item: strongly prefer tight fits / emptying bins
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins that are already more filled than average.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.6 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, use it rather than open new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // (large post_residual relative to next item) or many bins already open.
    if bin_residual == bin_capacity {
        score += 55.0;
        // allow opening when open bins are crowded and lookahead won't chain well
        if next_item_size > 0 && post_residual >= next_item_size + 20 {
            score -= 20.0;
        }
        if open_bins_count > 6 {
            score -= 10.0;
        }
    }

    // Mild pressure against accumulating too many open bins with large residuals.
    if open_bins_count > 4 && post_residual > 50 {
        score += 4.0;
    }

    // Progress scaling: early on, be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (mean_gap / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer minimal post-residual, with non-linear saturation.
    let mut score = pr * (1.0 + 0.35 * (pr / cap).powi(2));

    // Reward tight fits (small post_residual relative to capacity), smoothly.
    let tight = 1.0 - (pr / cap);
    score -= 18.0 * tight.powi(3);

    // Non-linear stream-progress coupling: as stream advances, waste matters more.
    score -= 10.0 * progress * tight.powi(2);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Many fitting bins => competition; slight penalty unless very tight.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0) * (1.0 - tight);
    }

    // Lookahead coupling: penalize leaving a residual that is awkward for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            // residual unusable by next item: dead-space penalty grows with progress.
            score += 6.0 * (1.0 - pr / cap) * (0.5 + progress);
        } else {
            // residual nicely fits next item: reward near-perfect packing.
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack).powi(2) * (0.4 + 0.6 * progress);
        }
    }

    // Mean-residual coupling: if this bin's residual deviates strongly below mean,
    // it is a good consolidation target.
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res - mean_residual) / mean_residual;
        score -= 3.0 * dev; // below-mean residual => negative dev => bonus
    }

    // Slight penalty for opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let best_possible = cap - item_size as f64;
        score += 6.0 + 4.0 * (open_bins_count as f64).sqrt() + 0.05 * best_possible;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic: partition residual space into capacity-fraction classes ---
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50
    let three_quarter = 3 * quarter;     // 75

    // Reward exact / tight fits via integer-division class of post_residual
    let post_class = post_residual / quarter; // 0..=4 harmonic class
    // Class 0 (post_residual < 25) is nearly-sealed: strong reward
    match post_class {
        0 => score -= 12.0 + (quarter - post_residual) as f64 * 0.4,
        1 => score -= 4.0,
        2 => score += 1.0,   // half-full leftover: mildly penalize
        3 => score += 3.0,   // large leftover: penalize
        _ => score += 6.0,   // nearly empty bin used for a small item: bad
    }

    // Modulo arithmetic: exact multiples of quarter are golden residuals
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Residuals leaving a divisible-by-10 chunk pair well with typical sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.5;
    }
    // Awkward prime-ish leftovers (mod 10 in {1,3,7,9}) create dead space
    let m = post_residual % 10;
    if m == 1 || m == 3 || m == 7 || m == 9 {
        score += 1.0;
    }

    // --- Lookahead coupling: does post_residual harmonically fit next item? ---
    if next_item_size > 0 {
        let d = post_residual as i64 - next_item_size as i64;
        if d == 0 {
            score -= 10.0; // next item seals this bin perfectly
        } else if d > 0 {
            // how harmonic is the leftover after the next item?
            let nd = d as u32;
            let nclass = nd / quarter;
            match nclass {
                0 => score -= 5.0,
                1 => score -= 1.0,
                _ => score += 2.0,
            }
        } else {
            // next item cannot use this bin's remainder; leftover is a dead class
            score += (post_residual as f64) * 0.05;
        }
    }

    // --- Last-chance logic: this is the only bin that fits; avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // --- New-bin candidate: only open a new bin when current fit is terrible ---
    if bin_residual == bin_capacity {
        // baseline for fresh bin: prefer it only if all open fits are poor
        score = half as f64 - 2.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 2.0; // fresh bin gracefully takes the next item too
        }
        // late in stream, consolidating is cheaper than spawning
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 4.0;
    }

    // Mild pressure toward filling bins with high mean residual
    score -= mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let min_item = 1u32; // items can be as small as 1
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(bin_residual)) {
        // dead space that next_item cannot even use
        score += 40.0;
    }

    // Penalize small unusable gaps relative to next item lookahead
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits (small post_residual) more aggressively
    score -= (bin_capacity - post_residual) as f64 * 0.25;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open new bin when many bins already open and mean residual is high (fragmented)
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        // if item is large, a fresh bin is more attractive
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // late in the stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight penalty for leaving residual far from mean (imbalance)
    let diff = post_residual as f64 - mean_residual;
    score += diff.abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for perfect match on next item
        if diff == 0.0 {
            score -= 60.0 + 30.0 * (1.0 - progress);
        } else {
            // Penalize proportional to mismatch, scaled by next item size
            score += 0.35 * diff * (next_item_size as f64 / 100.0).max(0.2);
        }
        // Also reward when next item fits with small leftover after two placements
        if next_item_size <= post_residual {
            let two_step_waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - two_step_waste as f64 / 100.0);
        } else {
            // Next item won't fit here: penalize small residuals that become dead space
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer bins whose residual is below mean residual (tight packing)
    score += 0.4 * (mean_residual - post_residual as f64).abs * 0.0; // no-op guard
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: prefer it only late in stream or when current fit is very loose
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.85 {
            score -= 30.0; // large item: fresh bin is good
        } else {
            score += 10.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty for accumulating many open bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * (post_residual as f64);
        } else if post_residual >= next_item_size {
            // Reward leaving exactly enough room for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / (bin_capacity as f64));
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 0.5 * (post_residual as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin fits well. The empty-bin call has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 18.0;
        // More open bins => prefer consolidating into existing bins.
        score += 2.0 * (open_bins_count as f64).sqrt();
        // Early in the stream, new bins are cheaper (long horizon to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If the item is large, a fresh bin is more attractive.
        score -= 0.08 * (item_size as f64);
        // If existing bins are crowded on average, new bin is more acceptable.
        score -= 0.05 * mean_residual;
        // If this is the only option that fits (fitting_bins_count == 0 means
        // only the new bin), make it clearly the best choice.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: mild penalty proportional to fragmentation risk.
        if post_residual > 0 && post_residual < 10 {
            score += 4.0; // tiny slivers are wasted space
        }
        // Prefer bins with lower residual among equals (fill fullest bins first).
        score += 0.03 * (bin_residual as f64);
    }

    // Global pressure: many open bins with high mean residual -> tighten selection.
    score += 0.02 * mean_residual * (1.0 - (open_bins_count as f64).min(20.0) / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: penalize post residual, non-linearly (waste grows super-linearly).
    let mut score = post * (1.0 + 0.9 * post / cap) * (1.0 + progress);

    // Reward tight fits: low post residual relative to item size.
    score -= (item_size as f64 / (post + 1.0)) * 4.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate some slack; late, demand tight packing.
    let coupling = post / cap;
    score += 30.0 * coupling * coupling * (1.0 - progress);
    score -= 25.0 * (1.0 - coupling) * (1.0 - coupling) * progress;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily;
    // if next item would be blocked by small post_residual, penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * ((nxt - post) / cap);
        }
    }

    // Prefer bins whose residual is below mean (denser bins) with smooth term.
    score += 2.0 * ((post - mean_residual) / cap).tanh();

    // Mild penalty for proliferating open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo 10 classes (capacity fractions)
    let class = post_residual % 10;
    // "Perfect" harmonic classes: 0, and small unusable slivers are dead space
    if class == 0 {
        score -= 12.0; // perfectly aligned residual -> excellent
    } else if class <= 2 {
        score += 6.0; // tiny sliver, likely dead space
    }

    // Integer-division thresholds: can next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportional to how much of next item the residual covers
            let cover = post_residual as f64 / next_item_size as f64;
            score -= 8.0 * (1.0 - 1.0 / cover);
        } else {
            // residual unusable for lookahead: penalize proportional to waste
            let waste = post_residual as f64;
            score += 2.0 + 0.25 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Fractional capacity coupling: item fills bin exactly -> huge reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving large residual when mean residual is small (wasteful outlier)
    let frac = post_residual as f64 / cap;
    if frac > 0.5 && next_item_size > 0 && (next_item_size as f64) < frac * cap * 0.5 {
        score += 3.0 * frac;
    }

    // New-bin candidate handling: empty bin gets neutral-ish baseline,
    // attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score = 45.0
            - 10.0 * (step_index as f64 / total_items.max(1) as f64)
            + if next_item_size > 0 && next_item_size >= bin_capacity / 2 { -5.0 } else { 0.0 };
    }

    // Mild late-stream tightening: prefer compact packing as stream progresses
    score += 0.5 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the next item
    // (or the smallest plausible item) are essentially wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Tightness reward: proportional to how much of the bin is used.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill;

        // Penalize residual that cannot fit the lookahead item (dead space).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0; // bin remains usable for next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (penalize spreading into new bins); when few, mild preference for reuse.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins already exist,
        // scaled by pressure and stream progress.
        score += 15.0 * pressure * (0.5 + progress);
        // But if no bin fits well (mean residual low), allow opening.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 8.0;
        }
    } else {
        // Reusing an existing bin is favored less when pressure is extreme
        // and the fit is loose (large post_residual).
        score += 0.02 * pressure * post_residual as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., tighter bins), keeping loose bins for larger future items.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact chain fit (item + next item fills bin exactly).
        if item_size + next_item_size == bin_residual {
            score -= 400.0;
        }
        // Penalize residuals that are too small for next item but wasted anyway.
        if post_residual > 0 && (post_residual as i64) < (next_item_size as i64) && post_residual < 10 {
            score += 80.0;
        }
    }

    // Tightness relative to bin capacity: prefer small relative waste.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer it only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 100.0; // pair won't fit anywhere anyway, fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 40.0;
    } else {
        score += progress * 60.0;
    }

    // Many open bins: encourage filling existing ones.
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by fraction of bin consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no future item (>=1) can use efficiently.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for leaving awkward gap
            score += 2.0;
        }
    } else {
        // Last item: prefer filling bins as much as possible
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with large mean residual -> discourage
    // opening new bins, encourage consolidation into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by open bins count
        // and remaining stream length; discount late in the stream when
        // consolidation is less valuable.
        score = bin_capacity as f64
            + 10.0 * (open_bins_count as f64).sqrt()
            + 15.0 * (mean_residual / bin_capacity as f64)
            - 20.0 * progress;
        // If a single existing bin fits, opening a new bin is rarely worth it.
        if fitting_bins_count >= 1 {
            score += 8.0;
        }
    } else {
        // Existing bin: slight bonus when mean residual is high (consolidate).
        score -= 4.0 * (mean_residual / bin_capacity as f64);
        // Early in stream, slightly prefer keeping bins balanced.
        score += 3.0 * (1.0 - progress) * ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual, with non-linear penalty for awkward leftover sizes
    let mut score = pr
        + 0.9 * (pr / c) * (1.0 - pr / c) * c
        + 2.5 * (pr / c).powi(3) * c;

    // Favor tight fits: high fill ratio of the bin
    let fill = (r - pr) / c;
    score -= 6.0 * fill * fill;

    // Lookahead coupling: reward leaving space that next item can use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).abs();
        score -= 4.0 * (1.0 - slack / c) * (pr >= nx) as i32 as f64;
        score += 1.5 * (slack / c) * (1.0 - slack / c);
    }

    // Late stream: consolidate into fewer bins
    score += 3.0 * progress * (pr / c);
    score += 0.4 * open_bins_count as f64 * (1.0 - progress) * (pr / c);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly so poor fits in open bins are avoided only if very bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
        // But if current item is large relative to mean residual, opening fresh is attractive
        score -= (item_size as f64 / c) * 12.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins with residuals close to item needs
    score += 0.8 * ((r - item_size as f64) - mean_residual).abs() / c * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity quarters
    let quarter = cap / 4.0;
    let class = (post_residual as f64 / quarter).floor(); // 0..4
    match class as u32 {
        0 => score -= 12.0,              // nearly perfect fit
        1 => score -= 4.0,               // small usable gap
        2 => score += 0.0,               // mid gap
        3 => score += 3.0,               // awkward gap
        _ => score += 0.0,
    }

    // Tightness reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure;
        score += (open_bins_count as f64) * 2.0;
        // allow new bin late in stream if residuals are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Lookahead compatibility: post_residual should pair with next item
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into this gap -> harmonic bonus
            let pair_fit = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * pair_fit;
            if post_residual % next_item_size == 0 {
                score -= 6.0; // exact divisor class: perfect future fill
            }
        } else {
            // gap too small for next item: dead-space risk
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(30.0);
        }
    }

    // Prefer spreading load across bins when mean residual is high
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Modulo-class coupling between item and residual (harmonic alignment)
    let harmony = ((item_size as i64 - bin_residual as i64).abs() % 25) as f64;
    score += 0.1 * harmony;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9)
    // are pure waste, so punish them quadratically.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Penalize leaving a gap the next item almost fits (off-by-small).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
        score += 12.0;
    }

    // Pressure from number of open bins: with many open bins, prefer
    // consolidating into existing bins; opening new bins gets costlier.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;

    // New-bin candidate: only attractive when existing bins would leave
    // large unusable residue or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by how badly existing bins fit.
        let mut new_bin_score = 55.0 + open_pressure;
        if fitting_bins_count == 0 {
            new_bin_score -= 80.0; // forced open
        } else if fitting_bins_count == 1 {
            // Last-chance bin: compare its post_residual slack.
            if post_residual > 0 && post_residual <= 9 {
                new_bin_score -= 45.0; // dead space anyway, open new bin
            }
        }
        // Late in stream, slightly discourage proliferation.
        if total_items > 0 {
            new_bin_score += (step_index as f64 / total_items as f64) * 8.0;
        }
        return new_bin_score;
    }

    // Existing bin: reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 18.0;

    // If this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild preference for bins below mean residual (balance load).
    score += ((post_residual as f64) - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits in the leftover space.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = next / post.max(1.0);
        score -= 25.0 * tightness;
    }
    // Dead space: leftover too small for the next item.
    else if next_item_size > 0 && post_residual > 0 {
        score += 15.0 * (1.0 - post / cap);
    }

    // Reward very tight fits overall (small post_residual relative to capacity).
    score -= 20.0 * (1.0 - post / cap);

    // Penalize bins whose residual deviates badly from mean residual (avoid fragmentation).
    let dev = (post - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mildly discouraged unless the current item is large and
    // no open bin offers a good fit (post_residual would be tiny anyway).
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        let large_item_bonus = (item_size as f64 / cap) * 30.0;
        score += base_penalty - large_item_bonus;
        // Early in stream, opening bins is cheaper (spread load).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with more residual when many bins are open
    // (keep a few bins flexible).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize less when post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness).powi(3);

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.3 * post_residual as f64;
    }
    // Reward leaving room exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with high mean residual -> favor filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score += 5.0 * pressure * (open_bins_count as f64).sqrt();

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as mean residual grows.
        score += 20.0 + 30.0 * progress + 10.0 * pressure;
    } else {
        score -= 8.0 * progress;
    }

    // Slight preference for bins whose residual is close to mean (keep residuals balanced).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Tightness: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tight * tight;

    // Perfect fit gets a strong smooth reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let pair_fit = 1.0 - gap / cap;
        if pair_fit > 0.0 {
            score -= 18.0 * pair_fit * pair_fit * (0.5 + 0.5 * progress);
        }
        // Penalize leaving residual that no plausible item can use.
        if post_residual < next_item_size && post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: opening a bin is penalized mildly,
    // but attractive when current bin fit is poor relative to mean residual.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / cap; // = 1.0 for empty candidate
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 12.0 - 10.0 * open_pressure * (1.0 - progress) - 8.0 * (1.0 - progress);
        // Discourage opening when mean residual across open bins is large.
        score += 0.15 * mean_residual;
        let _ = poor_fit;
    }

    // Smooth stream-progress coupling: later in stream, be greedier about tight fits.
    score -= 8.0 * progress * tight;

    // Mild penalty for wasting large residual relative to mean.
    if post_residual as f64 > mean_residual {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "unusable" residue classes (too small for typical future items).
    let pr = post_residual as f64;
    let cls = (post_residual / 10).min(9); // integer division class 0..=9
    // Penalize small non-zero residue classes (dead space), reward exact fills.
    score += match cls {
        0 => -8.0,                       // perfect fill
        1 => 6.0,                        // 1..9 residue: nearly dead
        2 => 4.5,
        3 => 3.0,
        _ => 0.0,
    };

    // Fractional capacity coupling: prefer bins whose post_residual is a
    // "harmonic" fraction of capacity (multiples of 25, 20, 10).
    let frac = pr / cap;
    if (post_residual % 25) == 0 { score -= 3.0; }
    if (post_residual % 20) == 0 { score -= 2.0; }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // Harmonic pairing: next item exactly consumes residue class
            if post_residual == next_item_size { score -= 4.0; }
            // next item leaves a good class again
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 { score -= 2.0; }
        } else {
            // next item won't fit here: penalize proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap).min(0.8) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate (empty bin): only prefer it when residual spread is
    // tight (mean residual low) or item is large relative to capacity.
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score = cap - pr; // baseline = cap for empty bin
        score -= 12.0 * (1.0 - tight.min(1.0)); // open new bin when open bins are full-ish
        if item_size as f64 > 0.6 * cap { score -= 6.0; }
        if fitting_bins_count <= 1 { score += 20.0; } // don't open when last chance exists
    }

    // Mild tie-break by tightness of fit.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 0.5;

    // Late-stream consolidation: prefer filling existing bins near the end.
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= prog * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: post_residual gaps that are too small to hold
    // even the smallest plausible item are pure waste. Penalize them hard.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits: small (but not dead) post_residual is ideal.
    if post_residual > 0 && post_residual as f64 >= dead_threshold {
        score -= 12.0 * (1.0 - (post_residual as f64 / 50.0).min(1.0));
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // post_residual cannot hold next item; mildly penalize small leftovers
            score += (dead_threshold - (post_residual as f64).min(dead_threshold)) * 2.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, opening is cheaper.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: an empty bin should only win when existing fits
    // are poor. Give the empty bin a moderate baseline score so tight fits beat it.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening fresh bins is less attractive (waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Reward using bins whose residual deviates favorably from the mean
        // (consolidate space into bins that already have room).
        if (bin_residual as f64) > mean_residual {
            score -= ((bin_residual as f64 - mean_residual) * 0.3).min(10.0);
        }
    }

    // Mild penalty for very large leftover relative to capacity (fragmentation).
    if post_residual as f64 > 0.6 * bin_capacity as f64 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.9;
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Post-residual too small to ever fit anything useful (dead space) -> penalize,
        // but mildly, since tight packing still matters.
        if post_residual < 10 && post_residual > 0 {
            score += 8.0;
        }
        // Post-residual that can't fit the next item but is large: mild penalty
        // (fragmentation risk), unless it can still fit typical small items.
        if next_item_size > post_residual && post_residual > 0 {
            score += 3.0;
        }
    }

    // Prefer bins with residual below mean (filling fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: discourage opening yet another bin; the new-bin candidate
    // has bin_residual == bin_capacity, so penalize it when open bins exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 20.0 * open_bins_count as f64 + 10.0 * progress;
        // But if this new bin is the ONLY fitting option, reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference for bins whose residual is close to item size even
    // without lookahead (classic best-fit tightening).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // Many fitting bins: mildly prefer bins with small residual (best-fit behavior)
    if fitting_bins_count > 1 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space that blocks the next item
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer filling bins that deviate below mean residual (balance / close out small bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late in the stream: discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 0.4 * open_bins_count as f64;
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * pr_norm * (0.5 + progress) - pr_norm * (1.0 - progress) * 0.3;
    score += 40.0 * poly;

    // Penalize waste when many bins already fit the item.
    if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0) * (0.5 + 0.5 * progress);
    }
    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (tighter packing).
    score += 0.4 * (mean_residual - pr) * (0.5 + 0.5 * progress);

    // Mild penalty for opening a new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 * (1.0 - progress) + 3.0 * (open_bins_count as f64).ln();
    }

    // Penalize very small dead space (unusable slivers) with smooth ramp.
    if pr > 0.0 {
        score += 15.0 * (-pr / 10.0) * (-pr / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residual landing in "good" residue classes
    // (small, or exactly matching a plausible next-item size).
    let r = post_residual as i64;
    let m = (r % 10) as f64;
    score -= (10.0 - m) * 0.35; // multiples of 10 are reusable

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: penalize if next item cannot fit in the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + (next_item_size as f64 * 0.2);
        } else {
            // dead space unless residual is tiny anyway
            let waste = (next_item_size - post_residual.min(next_item_size)) as f64;
            score += waste * 0.5;
            if post_residual < 10 {
                score -= 15.0; // tiny residual is effectively "closed", fine
            }
        }
    } else {
        // last item: just minimize post_residual extra
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading when many bins are open and residual is far above mean
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15 * (open_bins_count.min(20) as f64).sqrt();

    // Prefer tight fits relative to capacity fraction
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // New-bin candidate (empty bin): penalize opening a new bin mildly,
    // more so early in the stream; allow it late or when item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 25.0 * progress;
        if item_size >= 80 {
            score -= 30.0; // huge items are fine to start fresh
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 20.0; // keep pairing possibility in an existing bin instead
        }
    }

    // Modulo-4 harmonic class of post_residual: odd residuals are awkward
    if r % 2 == 1 && r > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 25.0;
    }

    // Penalize bins whose residual becomes too small to fit any plausible future item
    // (items range 1..100, but small gaps below next_item_size are likely wasted).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual != bin_capacity {
        score -= pressure * 4.0;
    } else {
        // New-bin candidate: penalize opening a bin, more so when decent fits exist.
        score += 20.0 + pressure * 6.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Prefer bins below the mean residual (fill emptier bins first keeps spread tight).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in stream, prefer tight packing; later, avoid fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: favor tight fits (small post_residual), mildly scaled.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powf(1.5) * 100.0;

    // 2-step lookahead: reward when next item fits into post_residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward a two-item chain completion; stronger the tighter the chain.
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize post_residual that is unusable for the next item (dead space).
            let dead = post_residual as f64;
            let next = next_item_size as f64;
            // Worse if dead space is large but smaller than next item (just barely unusable).
            let near_miss = (next - dead).max(0.0);
            score += 0.30 * dead * (1.0 - near_miss / 100.0);
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Compare against mean residual across open bins: prefer bins with residual near mean
    // for balance, but strongly prefer bins with residual close to item_size (tight fit).
    let tightness = 1.0 - ((bin_residual as f64 - item_size as f64) / bin_capacity as f64).abs();
    score -= 6.0 * tightness;

    // Deviation from mean residual: penalize outliers to keep bin portfolio balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.04 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier, penalize loose fits more.
        score += 0.10 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin has large post_residual; discourage opening
    // new bins unless the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powf(2.0) * 30.0;
        score += 20.0 - large_item_bonus;
        // Late in stream, opening new bins is less costly than fragmenting old ones.
        score -= 8.0 * progress;
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early stream: encourage compacting into few bins.
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 12.0 * (1.0 - tightness.min(1.0));

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 15.0;
    }

    // Lookahead: penalize dead space unusable by the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        }
        // Reward if post_residual exactly accommodates next item.
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowd control: with many open bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.35 * crowd * (0.5 + progress);

    // Prefer bins whose residual deviates favorably from the mean (fill low-residual bins).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when the item is large or fits are poor.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * (1.0 - 0.9 * fill_frac);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // resist abandoning the last fitting bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // pairing potential with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let npr = pr / cap; // normalized post residual
    let fill = 1.0 - npr;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on large residuals.
    let mut score = pr * (1.0 + 0.8 * npr * npr);

    // Smooth coupling: waste matters more late in the stream.
    score += 25.0 * npr * npr * (0.5 + progress);

    // Reward high fill ratio smoothly (quartic saturation).
    score -= 30.0 * fill * fill * fill * fill;

    // Penalize bins whose residual after placement diverges from mean residual (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bin: strongly favor using it (smooth exponential-style reward).
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits in post_residual (smooth affinity term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score -= 12.0 * fits_next * (1.0 - gap * gap);
        // Penalize leaving residual that hovers just below next item size (dead space).
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Prefer new bin only when the item would leave a very large, likely unusable residual
    // in existing bins AND we are early/mid stream; otherwise penalize opening bins.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // Base moderate score: opening a bin is mildly costly.
        let mut nb = 20.0 + 15.0 * progress + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Smooth bonus to new bin when item is large relative to capacity (good start fill).
        nb -= 18.0 * (it / cap) * (it / cap);
        // If no existing bin fits well, new bin becomes attractive (smooth via fitting count).
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        nb -= 30.0 * scarcity;
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that are
    // "friendly" to future items (small, or divisible into common chunks).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if pr < 10 {
        score += 25.0 * (10 - pr) as f64 / 10.0; // tiny dead space, penalize
    } else {
        // Modulo-10 harmony: residuals divisible by 10 pair well with
        // integer item sizes.
        let m10 = (pr % 10) as f64;
        score += 1.5 * m10;
        // Half/quarter capacity classes: residual near cap/2 or cap/4
        // is reusable by mid-size items.
        let half = cap / 2.0;
        let quarter = cap / 4.0;
        let d_half = (pr as f64 - half).abs();
        let d_quarter = (pr as f64 - quarter).abs();
        if d_half < 10.0 { score -= (10.0 - d_half) * 0.8; }
        if d_quarter < 8.0 { score -= (8.0 - d_quarter) * 0.6; }
        // Integer-division threshold: bucket the residual into coarse classes
        // and reward classes that match next item's needs.
        let bucket = pr / 20; // 0..5
        if next_item_size > 0 {
            let ni = next_item_size;
            if ni <= pr {
                // lookahead fits here: strong reward
                score -= 18.0;
                // extra reward if after both items residual is still harmonious
                let pr2 = pr - ni;
                if pr2 % 10 == 0 { score -= 6.0; }
                if pr2 == 0 { score -= 10.0; }
            } else {
                // lookahead won't fit here: penalize proportionally to waste
                score += (ni - pr) as f64 * 0.15;
            }
            // Harmonic class match: bucket of residual vs bucket of next item
            if bucket == ni / 20 { score -= 4.0; }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // but if item is large, a fresh bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // late in stream with few bins, opening is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // reward using existing bins relative to how full the fleet is
        if (bin_residual as f64) < mean_residual {
            score -= 5.0; // this bin is tighter than average: prefer filling it
        }
        // reward compacting many bins
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Slight preference to fill larger residuals when item is small
    if item_size <= 20 && bin_residual >= bin_capacity / 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= tightness * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that exactly matches the next item if this bin
    // could instead hold the next item too (encourage reserving via new bin).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.5;

    // New-bin candidate handling: attractive early / when mean residual of
    // open bins is small (fragmented bins), unattractive when open bins have
    // plenty of usable space.
    if bin_residual == bin_capacity {
        let base = 30.0;
        let fragmentation = (mean_residual / bin_capacity as f64).powi(2);
        score = base + pressure * 3.0 - fragmentation * 20.0 - progress * 5.0;
        // If only one bin fits, never open a new one.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    // Mild penalty for wasting a large bin residual on a small item when
    // other bins could take the small item.
    if bin_residual > item_size * 3 && fitting_bins_count > 2 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // accommodates the next item (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 12.0 * (miss / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize leftover.
        score += 5.0;
    }

    // Favor bins already tighter than the fleet average (compact the loose ones).
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full (post_residual would be large dead space elsewhere).
    if bin_residual == bin_capacity {
        let new_bin_score = (bin_capacity - item_size) as f64
            + if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size { -25.0 } else { 0.0 };
        score = new_bin_score + 10.0;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space that can never fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect fill bonus
    } else if post_residual >= 10 {
        // dead space below the smallest plausible item is wasted
        score += 0.05 * (post_residual as f64).powf(1.3);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            // placing here would break a fit for the next item; mild penalty
            score += 6.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when existing
    // fits are poor (large post_residual) or few bins are open.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if fitting_bins_count > 0 {
            (post_residual as f64).max(0.0) // neutral; recompute via mean residual
        } else {
            0.0
        };
        let _ = poor_fit_penalty;
        // base cost of opening a new bin
        score += 25.0;
        // cheaper to open a bin early when few bins are open (future flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // if existing bins fit poorly (high mean residual mismatch), opening is better
        let avg_waste = mean_residual - item_size as f64;
        if avg_waste > 0.0 {
            score -= 0.3 * avg_waste;
        }
        // if the only alternative is a very bad fit, opening a new bin wins
        if fitting_bins_count > 0 && post_residual_of_best_unknown(mean_residual) {
            score -= 0.0;
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

#[inline]
fn post_residual_of_best_unknown(_mean_residual: f64) -> bool {
    false
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Base: waste after placement, normalized
    let mut score = post / cap;

    // Non-linear waste shaping: small residuals are either great (tight fit)
    // or dead space; emphasize via quadratic coupling with progress.
    let pr = post / cap;
    score += 0.6 * pr * pr * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 0.8 * (1.0 - pr) * (1.0 - pr) * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits into post_residual (chaining),
    // penalize if post_residual is a near-miss trap for next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = post >= nxt;
        let gap = (post - nxt).abs() / cap;
        if fits_next {
            score -= 0.5 * (1.0 - gap) * (0.4 + 0.6 * progress);
        } else {
            score += 0.4 * gap * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 1.2;
    }

    // New empty bin: penalize mildly; allow it when item is large (poor fit
    // elsewhere) or late in stream with many bins already open.
    if is_new_bin {
        let largeness = item_size as f64 / cap;
        score += 0.9 - 0.7 * largeness * (0.5 + 0.5 * progress);
        score -= 0.1 * (open_bins_count as f64).ln().max(0.0) * progress;
    }

    // Prefer bins with residuals above the mean (balance preservation),
    // smoothly coupled to progress.
    score += 0.15 * ((post - mean_residual) / cap) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "perfect"
    // complement classes (0, small, half, large) are treated specially.
    let half = bin_capacity / 2;
    let cls = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual == half { 2 }
        else if post_residual >= bin_capacity - 10 { 3 }
        else { 4 };

    match cls {
        0 => score -= 40.0,                              // perfect fill
        1 => score -= 25.0,                              // near-perfect
        2 => score -= 12.0,                              // half residual is reusable
        3 => score -= 5.0,                               // almost-empty bin, fine
        _ => {
            // Dead-space penalty grows super-linearly for awkward middles,
            // quantized by integer division into modulo-10 buckets.
            let bucket = post_residual / 10;
            score += (bucket as f64) * (bucket as f64) * 0.7;
        }
    }

    // Lookahead: reward if the next item can fit into the post-residual
    // (chain packing), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + (next_item_size as f64) * 0.1;
        } else {
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.15;
        }
        // Harmonic pairing: post_residual + next_item_size near capacity
        // or near half capacity is a good chain.
        let s = post_residual + next_item_size;
        if s == bin_capacity { score -= 20.0; }
        else if s == half { score -= 8.0; }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild pressure against hoarding many open bins with large mean residual.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }
    score += (mean_residual - post_residual as f64) * 0.1;

    // Progress-based tie-breaking: later in the stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a future item (min item size 1) but small relative to capacity
    // are pure waste. Penalize the "unusable" band aggressively.
    if post_residual > 0 {
        // smallest plausible item footprint; anything below ~10 is dead space
        let dead_threshold: u32 = 10;
        if post_residual < dead_threshold {
            score += (dead_threshold - post_residual) as f64 * 12.0;
        }
        // Slightly larger but still awkward gaps (11..=19) get a milder penalty
        else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 2.5;
        }
    }

    // Reward near-perfect fits: post_residual close to 0 is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness coupling: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize choices that leave
    // large residuals when bin count is high.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bonus: if this is the only bin that fits, avoid forcing
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer it when the current item would leave a very awkward gap
    // in every existing bin, or when mean residual is large but fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // But if existing bins are highly fragmented (large mean residual yet
        // poor fit), opening fresh is attractive: relax the penalty.
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.5 {
            score -= 20.0 * (fragmentation - 0.5);
        }
        // If next item is large and this item is small, a fresh bin keeps
        // flexibility for the big item elsewhere.
        if next_item_size > 0 && next_item_size > item_size * 2 && item_size <= 30 {
            score -= 12.0;
        }
    }

    // Lookahead synergy: if the next item exactly fits the post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 30.0;
    } else if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
        score -= 10.0;
    }

    // Early-stream mild preference for tight packing to establish good bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= (1.0 - progress) * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits perfectly-ish: strong reward scaled by snugness.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 30.0 * snug;
        } else {
            // Next item won't fit: penalize wasted capacity that strands the bin.
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into bins with large residuals
    // (drain near-full bins less, close bins with small residuals).
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 10.0; // open a new bin rather than a forced poor fit
        } else {
            score += 60.0; // strongly prefer existing bins
        }
    }

    // Slight early-stream preference for keeping bins balanced.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    score += (post_residual as f64 / cap) * 12.0;

    // Reward near-perfect fills strongly (post_residual small relative to item).
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 10.0;
    }

    // Lookahead: if next item fits into the post residual, bonus.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            // next item can also go here: good chaining, mild reward scaled by fill
            score -= 6.0 * (nx / cap);
        } else {
            // dead space that next item cannot use: penalize proportionally
            score += 4.0 * ((pr - nx).abs() / cap) + 3.0;
        }
        // perfect pair: post residual exactly matches next item
        if (pr - nx).abs() < 1.0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; prefer bins below mean residual (denser bins).
    if open_bins_count > 2 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
        // mild pressure to close bins when many are open
        score += 0.5 * (open_bins_count as f64).ln();
    }

    // Time horizon: early in stream, be conservative (prefer new bins over bad fits);
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // New-bin candidate calibration: empty bin gets baseline cost that shrinks
    // when no good fits exist (large post_residual in every open bin).
    if bin_residual == bin_capacity {
        let bad_fit_pressure = if fitting_bins_count == 0 { 30.0 } else {
            (post_residual as f64 / cap) * 25.0
        };
        score += 10.0 - bad_fit_pressure.min(30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;
    // smooth polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += 30.0 * poly;
    // penalize dead space relative to mean residual
    score += 0.15 * (post - mean_residual).abs();
    // reward tight fits strongly
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post);
    // lookahead: reward residual that fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - ((post - nxt) / cap).abs());
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // mild preference for consolidating into fewer bins early
    score += 0.5 * (open_bins_count as f64).ln();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity-fraction classes.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let class = post_residual / fifth; // 0..=5 harmonic class of leftover
    let class_bonus = match class {
        0 => -30.0, // near-perfect fit, almost no waste
        1 => -18.0, // small leftover, likely dead space
        2 => -10.0, // leftover ~20-40, usable for medium items
        3 => -14.0, // leftover ~40-60, good for many sizes
        4 => -6.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Modulo arithmetic on residual: divisibility classes.
    let m7 = (post_residual % 7) as f64;
    let m10 = (post_residual % 10) as f64;
    score += 0.6 * m7 + 0.4 * m10;

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * (next_item_size as f64);
        // Extra reward for exact-ish chain: next item fills to a low residue.
        let chain_res = post_residual - next_item_size;
        if chain_res <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Leftover likely dead space if next item can't use it.
        score += 0.15 * (post_residual as f64);
    }

    // Penalize leaving residuals in the "awkward" band (51..=59) that few sizes fill.
    if post_residual > 50 && post_residual < 60 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with tighter fit (smaller post_residual relative to mean).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate handling: only attractive when no open bin is good.
    if bin_residual == bin_capacity {
        let good_open_exists = fitting_bins_count > 0 && mean_residual < 0.35 * cap;
        if good_open_exists {
            score += 60.0; // discourage opening new bin
        } else {
            score -= 5.0; // mildly encourage fresh bin for poor fits
        }
    }

    // Slight preference for consolidating into fewer bins early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are nearly unusable
    // (min item size is 1, but small gaps rarely match future demand).
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as i32) as f64 * 8.0; // heavy penalty for tiny gaps
    }

    // Reward very tight fits (post_residual == 0 is a perfect closure).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Smooth tightness reward: relative fill of the bin.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 25.0 * fill * fill;
    }

    // Bonus when this bin can also host the lookahead item after placement
    // (chained fit => very desirable).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize if the lookahead item would NOT fit in the resulting residual
    // while it is small enough to be stranded.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(15) {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading; makes the new-bin candidate (residual == capacity)
    // less attractive as open_bins_count grows.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 20.0 + 6.0 * open_bins_count as f64;
        // But if no existing bin fits well, allow opening: mild, so only
        // chosen when open bins score poorly.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        score -= 4.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference toward bins below mean residual early on
    // (keeps larger residuals available), fading as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - post_residual as f64) * (1.0 - progress) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (post_residual - next_item_size) as f64;
        score -= 30.0 - fit_quality.min(30.0);
    } else if next_item_size > 0 {
        // Penalize blocking the next item
        score += 15.0;
    }

    // Relative to mean residual: prefer bins that are already partially filled
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening unless no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Penalize large dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference for tighter fits
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize residual waste that is too small to ever be useful for future
    // items (dead space). Items are >= 1, but small slivers (< ~15) are risky.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 3.0;
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            // This bin could also serve the next item: bonus for perfect pair.
            let gap = post_residual as f64 - n;
            score -= 10.0 / (1.0 + gap);
        } else if n > bin_residual as f64 {
            // Next item won't fit here anyway; residual is free real estate.
            score -= 4.0;
        } else {
            // Placement blocks the next item in this bin.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding: many open bins with slack -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 0 {
        score -= 2.0 * (open_bins_count as f64).ln() * (1.0 + mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin gets a base penalty so that
    // decent fits in existing bins win, but becomes attractive when the fit
    // is bad or the stream is nearly done (no need to hoard slack).
    if bin_residual == bin_capacity {
        score += 20.0;
        // If this bin would be a poor fit elsewhere, opening is fine.
        if post_residual as f64 > 40.0 {
            score -= 25.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * (bin_capacity as f64) {
            score -= 8.0; // big next item: fresh bin is useful
        }
        if progress > 0.9 {
            score += 15.0; // late stream: avoid spreading
        }
    }

    // Early stream: be conservative, keep bins compact.
    if progress < 0.2 {
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild coupling: prefer bins whose residual is near the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - (post_residual as f64 / cap);

    // Reward tight fits (small post_residual) with a non-linear coupling to stream progress.
    let tightness = (1.0 - post_residual as f64 / cap).powi(3);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize large dead space quadratically, growing with progress.
    let waste = post_residual as f64 / cap;
    score += 18.0 * waste * waste * (0.4 + progress);

    // Lookahead coupling: if next item can use the post_residual, reward it smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = if nx <= post_residual as f64 {
            1.0 - ((post_residual as f64 - nx) / cap).abs()
        } else {
            -0.5 * ((nx - post_residual as f64) / cap)
        };
        score -= 8.0 * compat * fill;
    }

    // Last-chance bonus: this is the only fitting bin; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize opening a new bin when many bins fit the item (fragmentation risk).
    if bin_residual == bin_capacity {
        let spread = (mean_residual - (bin_capacity - item_size) as f64).abs() / cap;
        score += 6.0 + 10.0 * (1.0 - progress) + 4.0 * spread;
    } else {
        // Mild reward for keeping residual near the mean (balanced bins).
        score -= 2.0 * (1.0 - ((bin_residual as f64 - mean_residual) / cap).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let small_dead = (bin_capacity / 10) as f64; // leftover below 10 is unusable dead space
    if pr > 0.0 && pr < small_dead {
        score += 60.0; // penalize creating unusable slivers
    }

    // Modulo arithmetic on post_residual: common harmonic residual classes (0, 25, 50, 75, 100)
    let class = post_residual % 25;
    if class == 0 && post_residual > 0 {
        score -= 25.0; // harmonically aligned leftover, reusable by quarter-sized items
    } else {
        score += class as f64 * 0.5;
    }

    // Lookahead coupling: if next item fits harmonically into post_residual, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 25;
            if nxt_class == 0 {
                score -= 40.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 35.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: prefer new bin when current bins are fragmented
    if bin_residual == bin_capacity {
        // new empty bin: baseline score; penalize slightly so decent fits win
        score += 15.0;
        // but if open bins are fragmented (mean residual low), opening new bin is good
        if mean_residual < 0.35 * c {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 45.0;
        }
    }

    // Progress-based mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * (post_residual as f64 / c);

    // Tie-break: prefer bins with residual close to item (tight fit)
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.80;
    score
