pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            // next item fits exactly or nearly: strong reward
            score -= 60.0 * (1.0 - lookahead_gap as f64 / 100.0);
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 0.3 * lookahead_gap as f64;
        }
        // tiny residual (dead space) penalty, softened if lookahead uses it
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Penalize large residuals relative to mean residual (wasteful bins)
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer opening a new bin only when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; offset when many bins open or lookahead won't fit anywhere
        score = 100.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late-stream tightness: encourage compact packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker favoring fuller bins
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tight * tight;

    // Perfect fit.
    if post_residual == 0 { score -= 25.0; }

    // Dead-space penalty: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64; // residual if placed in an open bin would equal post_residual here; use mean_residual as proxy
        let poor_fit = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0) / cap
        } else { 1.0 };
        let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Prefer new bin when open bins are nearly full on average and stream is early (room to consolidate later).
        score = cap * 0.6 - 40.0 * poor_fit - 20.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Lookahead: reward leaving room for the next item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual - next_item_size < 10 { score -= 6.0; } // chain two items perfectly
        } else if post_residual > 0 {
            score += 5.0; // wastes space relative to lookahead
        }
    }

    // Mild preference for fuller bins among many open bins.
    score += 0.4 * (bin_residual as f64 - mean_residual).abs().signum() * (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear quadratic penalty on wasted residual (favor tight fits super-linearly)
    score += 0.8 * (pr * pr) / cap;

    // Smooth progress coupling: waste hurts more as the stream advances
    score += (0.5 + 1.5 * progress) * (pr / cap).powi(3) * cap * 0.5;

    // Reward bins whose post-residual exactly matches the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_deg = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 3.0 * match_deg * match_deg;
    } else if next_item_size > 0 {
        // Penalize residual too small for the next item (dead space)
        score += 2.0 * (next_item_size as f64 - pr) / cap * 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is bad;
    // becomes attractive when open bins are crowded (low mean residual)
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * open_bins_count as f64 - 0.15 * mean_residual;
        // Late in the stream, opening fresh bins is less desirable
        score += 4.0 * progress;
    }

    // Reward filling bins nearly full
    if pr == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit with lookahead: reward residual that matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize mildly so we prefer bins that chain
        score += 2.0;
    }

    // Harmonic class logic: group post_residual into capacity fractions (k+1 classes)
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // residual fraction
    let class = (1.0 / frac.max(1e-9)) as u32; // harmonic class index (1 => nearly full)
    // Reward low class index (bin nearly full) — classic harmonic packing preference
    score -= 3.0 / (class as f64 + 1.0);

    // Modulo arithmetic on post_residual: dead-space classes
    let m = post_residual % 10;
    if m == 0 {
        score -= 1.5; // perfectly divisible residual, likely reusable by common sizes
    } else if m <= 3 {
        score += 2.0; // tiny dead space, unusable
    } else if m >= 8 {
        score += 1.0; // nearly a full decade wasted
    }

    // Integer division thresholds on next_item_size
    if next_item_size > 0 {
        let nd = next_item_size / 20; // coarse size class of next item
        match nd {
            0 => score += 1.0,       // tiny next item: residual flexibility less critical
            1 => score -= 0.5,       // medium
            _ => score -= 1.0,       // large next item: strongly favor bins that can host it
        }
        // Exact fit lookahead bonus
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual / cap;
        // If open bins have little total slack, opening is fine; otherwise discourage
        score = cap * 0.55 - crowded * 0.5;
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative
        }
    } else if post_residual < 10 {
        // creating near-zero residual wastes the bin
        score += 1.0;
    }

    // Slight preference to fill earlier bins as stream progresses (bin count control)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable waste.
    let min_item = 1u32;
    if post_residual < min_item.max(10) && post_residual > 0 {
        score += 50.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 8.0 * (item_size as f64 / (post_residual as f64 + 1.0)).min(3.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure against opening new bins when open bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Slight preference to fill bins with larger residuals (consolidation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize blocking the next item's fit.
        let miss = (next_item_size - post_residual) as f64;
        score += 8.0 * (miss / bin_capacity as f64);
    }

    // Compare post_residual against mean residual across open bins.
    let mean_pr = mean_residual - item_size as f64;
    if mean_pr > 0.0 {
        let ratio = post_residual as f64 / mean_pr;
        if ratio < 1.0 {
            score -= 12.0 * (1.0 - ratio);
        } else {
            score += 6.0 * (ratio - 1.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin is already
    // quite full (waste-avoidance), scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 20.0 + 15.0 * progress;
        // If the item nearly fills a fresh bin, allow it more readily.
        score -= 0.3 * (bin_capacity as f64 - waste);
        // Fewer open bins means new-bin cost is lower.
        score -= 2.0 * open_bins_count as f64;
    }

    // Slight penalty for leaving large unusable gaps relative to smallest items.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect fill bonus
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that cannot hold a typical next item.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * usable;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (post_residual as f64); // unusable sliver penalty
        }
    }

    // Lookahead coupling: bonus if this placement lets the next item fit here too.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin when alternatives exist,
    // scaled by how many bins could fit and remaining stream length.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let horizon = 1.0 - progress;
        score += 18.0 + 3.0 * fitting_bins_count as f64 + 0.15 * open_bins_count as f64;
        score += 10.0 * horizon * (1.0 - (item_size as f64 / bin_capacity as f64));
    } else {
        // Mild preference for bins already below mean residual (balance load).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Prefer filling fuller bins when many bins are open (consolidation).
    score += 0.08 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Core: normalized waste, with non-linear (quadratic) waste penalty that
    // intensifies as the stream progresses (less room for error late in stream).
    let mut score = pr / cap;
    score += 0.8 * (pr / cap) * (pr / cap) * (0.5 + progress);

    // Reward near-perfect fits (small post_residual) with a smooth exponential bonus.
    score -= 1.5 * (-(pr / cap) * 6.0).exp();

    // Lookahead coupling: strongly reward exact preparation for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs() / cap;
        score -= 1.2 * (-diff * 8.0).exp();
        score += 0.3 * diff; // penalize residuals that neither fit nor match next item
    }

    // Last-chance bin: if this is the only fitting bin, reward using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 1.0 + 0.5 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer reusing open bins,
    // but relax the penalty when many bins are open or progress is late (bin consolidation).
    if bin_residual == bin_capacity {
        score += 0.6 + 0.4 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 2.0; // no alternative: new bin is fine
        }
    }

    // Coupling with mean residual: prefer bins whose post_residual moves the bin
    // toward the mean (harmonizing residuals for future packing).
    score += 0.2 * ((pr - mean_residual) / cap).abs();

    // Mild penalty for very small items in large-residual bins (wasteful pairing).
    if fit_ratio < 0.2 {
        score += 0.15 * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes
    let class_size = 10u32;
    let harmonic_class = post_residual / class_size; // integer division threshold
    let harmonic_offset = post_residual % class_size; // modulo arithmetic

    // Reward low post_residual (tight fit), especially when post_residual is small
    score -= (cap - post_residual as f64) * 0.35;

    // Harmonic class coupling: leftover in classes 0-1 (0..20) is near-dead space -> penalize
    if harmonic_class == 0 {
        score += 12.0 - harmonic_offset as f64 * 0.5; // very small leftover: hard to reuse
    } else if harmonic_class == 1 {
        score += 4.0 - harmonic_offset as f64 * 0.2;
    } else {
        // larger leftovers are reusable; reward proportionally
        score -= harmonic_class as f64 * 1.5;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect chain: reward if next item exactly consumes leftover
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 25.0; // perfect lookahead fit
            } else {
                score -= 10.0 - (gap % class_size) as f64 * 0.3;
            }
        } else {
            // next item cannot use leftover: leftover value drops
            score += 6.0;
            // if next item fits exactly into current residual but not post -> bad choice
            if next_item_size <= bin_residual && next_item_size > post_residual {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: new bin is correct
        } else if fitting_bins_count == 1 {
            score += 20.0; // keep the last-chance bin alive
        }
        // early stream: prefer opening bins to build a diverse pool
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Many open bins: discourage scattering into large leftovers
    if open_bins_count > 8 {
        score += (post_residual % 5) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if no open bin fits well, opening may be right; soften when mean residual is low.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Late in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mild preference for bins with residual close to item (best-fit core).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward when next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasted residual relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare against mean residual: favor bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent open bins exist, more so early in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 120.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer filling larger residual bins slightly less when many bins open
    score += 0.1 * post_residual as f64 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 60.0 * tightness * tightness;

    // Penalize large leftover dead space that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
    }
    if post_residual >= 30 && post_residual <= 45 {
        score += 8.0; // awkward zone: leftover hard to fill
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here anyway; slight penalty for wasting space
            score += (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64).max(0.0)).max(0.0) * 0.2;
        }
    }

    // New-bin candidate logic: only open a new bin when current bins fit poorly
    // or too many bins are already open with fragmented space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        let mut new_bin_score = 55.0
            + 30.0 * progress
            + fragmentation * 0.5
            + (open_bins_count as f64).sqrt() * 2.0;
        // If no bin is tight-fitting, opening fresh is attractive.
        if tightness < 0.7 {
            new_bin_score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            new_bin_score += 50.0; // don't abandon last chance
        }
        score += new_bin_score;
    }

    // Mild global pressure: as stream progresses, prefer filling existing bins.
    score -= 10.0 * (step_index as f64 / total_items.max(1) as f64) * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with non-linear emphasis on very tight fits.
    let mut score = pr * (1.0 + 2.0 * (pr / cap) * (pr / cap));

    // Strong reward for exact / near-exact fits (post_residual small relative to item).
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * tightness * cap * 0.5;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate leftovers; late, penalize wasted space more.
    score += pr * progress * progress * 1.5;

    // Interaction: post_residual vs mean residual across open bins.
    // Penalize bins whose leftover deviates badly from fleet mean (fragmentation).
    let dev = pr - mean_residual;
    score += 0.25 * dev * dev / cap;

    // Lookahead: if next item could exactly use this post-residual, reward strongly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        if pr >= ns {
            score -= 30.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 0.1 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residual space would be badly wasted
    // (large dead space in an existing bin) or late in stream with many open bins.
    if bin_residual == bin_capacity {
        let waste = pr / cap; // = 1 - item_size/cap
        let dead = if bin_residual > item_size { (bin_residual - item_size) as f64 } else { 0.0 };
        let _ = dead;
        score = cap * (0.9 + 0.4 * progress) - 20.0 * (1.0 - waste) * (1.0 - waste);
        // discourage hoarding many open bins early
        score += (open_bins_count as f64).sqrt() * 3.0 * (1.0 - progress);
    }

    // Mild penalty for bins that become nearly empty-but-unusable slivers.
    if pr > 0.0 && pr < 10.0 {
        score -= 15.0 * (1.0 - pr / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize residuals in "awkward" classes
    let pr = post_residual;
    if pr > 0 {
        // dead space that nothing in [1,100] pairs with well
        if pr < 10 {
            score += 40.0; // unusable sliver
        } else if pr <= 20 {
            score += 12.0;
        }
        // modulo classes: residuals divisible by 10 pair with many item sizes
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 5 == 0 {
            score -= 2.0;
        }
        // prime-ish residuals are awkward targets
        let awkward = pr % 7 != 0 && pr % 3 != 0 && pr % 2 != 0;
        if awkward && pr > 20 && pr < 60 {
            score += 4.0;
        }
    } else {
        score -= 25.0; // perfect fill is excellent
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0; // creates a bin that likely can't host the next item
    }

    // Perfect match of next item into this bin's post residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Tight fit reward: post_residual small relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fits exist
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred
        score += 30.0;
        // but if many bins and item fits poorly everywhere, opening is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // opening a fresh bin wastes mean_residual across open bins
        score += 0.3 * mean_residual;
        if open_bins_count > 8 {
            score += 10.0;
        }
    }

    // Mild preference to balance residuals: avoid dumping into already-large bins
    if (bin_residual as f64) > mean_residual * 1.5 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // small gaps may still be usable by future items, mild penalty
        score += 8.0;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score += 15.0;
    }

    // Penalize wasting a large residual on a small item
    let waste_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 20.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: prefer filling existing bins when many are open
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it creates a great fit
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if no existing bin fits well (large post residual waste elsewhere), allow it
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Lookahead: reward leaving space that fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Late in the stream, tighten up: prefer compacting into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64) / 100.0;

    // Deviation from mean residual: prefer bins whose post residual is near mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // usable by next item, but penalize leftover after that hypothetical fit
            let after_next = post_residual - next_item_size;
            score -= 20.0 - 0.2 * after_next as f64;
        } else {
            // next item cannot use this residual: penalize dead space
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discourage opening new bins when several bins fit, early in stream.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 30.0 + 10.0 * (1.0 - progress) + 2.0 * fitting_bins_count as f64;
        score += new_bin_penalty;
        // but a new bin is fine if item is large relative to capacity
        score -= 0.2 * item_size as f64;
    }

    // Slight preference to fill older/more-filled bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space that is small enough to be "wasted"
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver under min item size
    }

    // Lookahead coupling: reward residuals that exactly fit the next item,
    // penalize residuals just above next item that would be badly fragmented.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-slack / 20.0).exp();
        } else {
            // next item won't fit here: mild penalty scaled by how close we were
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (1.0 - (-miss / 15.0).exp());
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * mean_residual;
    }

    // Many open bins: prefer consolidating into bins with below-average residual
    // (fills emptier-of-space bins? actually prefer bins with residual near mean to
    // keep a spread of useful residuals)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // When many bins are open, discourage opening new ones
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 12.0 + 2.0 * pressure;
        // early stream: new bins are cheap; late stream: expensive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        score -= 5.0; // mild bonus for using an existing bin
    }

    // Time horizon: late in the stream, prioritize closing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Prefer bins whose residual is a "useful" size (divisible-friendly chunks)
    let r = post_residual % 10;
    if r == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits, quadratically penalized dead space
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth progress coupling: late in stream, dead space matters more
    score += 60.0 * pr_norm * pr_norm * progress;

    // Reward filling a bin completely (smooth exponential term)
    score -= 25.0 * (-(cap - pr) / 30.0).exp() * (1.0 + progress);

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize slightly unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
        // attractive if item perfectly splits a fresh bin with lookahead
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 45.0;
        }
    }

    // Lookahead coupling: reward residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual interaction: avoid leaving bin far from crowd mean
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // Mild pressure against accumulating too many open bins early
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover is
    let post = post_residual as u32;
    let class = post / 10; // integer division threshold classes (0..10)
    let harmonic_bonus = match class {
        0 => 40.0,              // dead space (0..9) - heavily penalize
        1 => 25.0,
        2 => 12.0,
        3 => 4.0,
        4 => -2.0,              // mid residuals slightly fine
        5 => -6.0,
        6 => -10.0,
        7 => -14.0,
        8 => -18.0,
        9 => -22.0,
        _ => -30.0,             // near-empty bin after placement (great fit)
    };
    score += harmonic_bonus;

    // Exact-fill reward
    if post == 0 {
        score -= 60.0;
    }

    // Coupling with lookahead: does the leftover fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post {
            // leftover usable by next item -> reward, scaled by tightness
            let tight = (post - next_item_size) as f64;
            score -= 18.0 - tight * 0.15;
        } else {
            // leftover cannot host next item -> mild penalty
            score += (next_item_size - post) as f64 * 0.08;
        }
    } else {
        // last item: prefer tight packing anywhere
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // cheaper to open a new bin when open bins are already crowded
        score -= (open_bins_count as f64) * 1.5;
        // cheaper when mean residual is low (open bins nearly full)
        score -= (mean_residual / cap_f) * 30.0;
        // cheaper when the fit here would leave dead space
        if post < 10 && bin_residual != bin_capacity {
            score -= 0.0; // handled in class above
        }
        // if item perfectly fills a fresh bin later, opening is fine
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Progress-based mild tightening: later in stream, prefer tighter fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward tight fits relative to bin capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize creating gaps that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Opening a new bin is expensive: penalize the empty-bin candidate,
    // but less so when open bins are nearly full (few good fits remain).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0) * 5.0;
        let waste = mean_residual / bin_capacity as f64;
        score += 25.0 + pressure - 15.0 * waste;
    }

    // Bin-count pressure: prefer consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Mild penalty for leaving residual far from mean (fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let gap = post - nxt;
            // Reward proportional to how well the next item matches the leftover space.
            score -= (bin_capacity as f64 - gap) * 0.8;
            // Perfect chain (item + next fills bin completely): strong bonus.
            if gap == 0.0 {
                score -= 50.0;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space relative to overshoot.
            let overshoot = nxt - post;
            score += overshoot * 0.5;
        }
    }

    // Coupling with mean residual: prefer bins whose post_residual stays near the mean
    // (keeps the fleet of open bins balanced and reusable).
    let post_f = post_residual as f64;
    let dev = (post_f - mean_residual).abs();
    score += dev * 0.15;

    // Penalize bins with large residual before placement less if they become very tight
    // (use the bin fully); reward near-full utilization.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // penalize it mildly so existing tight fits win, but not catastrophically
        // so it wins when all open bins would create large dead space.
        score += 12.0;
        // If the current item is huge relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 6.0;
        }
        // Lookahead: if next item is small, a fresh bin can host both.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 8.0;
        }
    } else {
        // Slight preference for consolidating into fewer bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 3.0;
        // When many bins are open, prefer reusing (penalize spreading thin).
        score += open_bins_count as f64 * 0.05;
    }

    // Small exact-fit bonus regardless of lookahead.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: reward small post_residual non-linearly.
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fit_ratio * fit_ratio * cap * 0.1;

    // Penalize large dead space relative to capacity (wasted volume).
    let waste = post_residual as f64 / cap;
    score += 8.0 * waste * waste * cap;

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 1.5 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many fitting bins: mild penalty to encourage diversity of choice via tightness.
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global residual balance: prefer bins whose residual is below mean (tighter bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate: penalize opening new bins more heavily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with progress and open-bin count.
        score = cap as f64 + 20.0 * progress + 1.0 * open_bins_count as f64;
        // Allow new bin only if it would take the item tightly and lookahead matches.
        if next_item_size > 0 && next_item_size >= post_residual.min(next_item_size) && post_residual >= 10 {
            score -= 3.0;
        }
        // Early stream: fresh bins are cheap.
        score -= 25.0 * (1.0 - progress);
    }

    // Small jitter-free deterministic tie-breaker based on step.
    score += 0.001 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fill = (cap - post) / cap; // fraction of the bin consumed by this placement

    // Base: wasted space after placement.
    let mut score = post;

    // Reward tight fills; the reward grows smoothly with stream progress
    // (later in the stream, consolidating matter more than preserving space).
    score -= fill * (3.0 + 4.0 * progress * progress);

    // Smooth "awkward residual" bump: residuals in the middle of the bin are
    // the hardest to fill later (zero at post == 0 and post == cap, max mid).
    let norm = (post / cap).clamp(0.0, 1.0);
    score += 5.0 * (std::f64::consts::PI * norm).sin() * (0.6 + 0.8 * progress);

    // Lookahead coupling: if the next item also fits this bin's post-residual,
    // reward the chaining; otherwise penalize leftover space that likely dies.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 * (1.0 - post / cap) * (1.0 - 0.5 * progress);
        } else {
            // smooth penalty growing with how far short the residual falls
            score += 0.04 * post * ((post - nxt) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a fresh bin for a marginal gain.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize opening a bin,
    // more so late in the stream; relax slightly when few bins are open.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score += (6.0 + 14.0 * progress) * (0.5 + 0.5 * openness);
    }

    // Mild pull toward bins whose residual is near the mean (balanced load).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how well post_residual decomposes
    // into typical item sizes (capacity fractions / integer division bands).
    let pr = post_residual;
    if pr > 0 {
        // Class the dead space by integer division thresholds.
        let band = pr / 10; // 0..10 bands of 10 units
        let band_penalty: f64 = match band {
            0 => -30.0,              // nearly perfect fit, tiny dead space
            1 => 8.0,                // 10-19: awkward sliver
            2 => 2.0,                // 20-29: usable for small items
            3 => 10.0,               // 30-39: awkward
            4 => -6.0,               // 40-49: good slot for medium items
            5 => 4.0,                // 50-59
            6 => -10.0,              // 60-69: prime slot
            7 => 6.0,                // 70-79
            8 => -14.0,              // 80-89: big slot, very reusable
            _ => -4.0,               // 90-99: nearly empty anyway
        };
        score += band_penalty;

        // Modulo arithmetic: residuals divisible by common item sizes (10, 20, 25, 50)
        // are "harmonic" and likely to be exactly filled later.
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
    } else {
        // Perfect closure of the bin: strongly reward.
        score -= 40.0;
    }

    // Lookahead: reward if the next item fits harmonically into post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0;
            // exact match: next item perfectly seals this bin
            if next_item_size == pr { score -= 20.0; }
            // next item leaves another harmonic residual
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 6.0; }
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins are
    // badly fragmented (high mean residual spread vs this bin) early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Fresh bins are attractive when the item is large and open bins are tight.
        let tightness = mean_residual / cap;
        score = 55.0 + 40.0 * tightness - 30.0 * progress;
        if item_size > 70 { score -= 10.0; }
        if fitting_bins_count == 0 { score -= 20.0; }
    } else {
        // Prefer bins whose residual is close to the item (tight fits).
        score += ((bin_residual - item_size) as f64) * 0.05;
        // Slight preference to fill bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual { score -= 3.0; }
        // Discourage spreading across too many open bins.
        if open_bins_count > 6 { score -= 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead-space gaps (post_residual too small for typical future items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into the resulting residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0; // dead space relative to known next item
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading items across bins
    score += (open_bins_count as f64) * 0.6;

    // Prefer bins with residual close to mean (keep balance), mildly
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // New-bin candidate handling: neutral-ish baseline, penalize opening new bins
    // unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.3;
    }

    // Late in stream, avoid opening new bins even more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use.
        score += 15.0;
    }

    // Relative to mean residual: penalize bins already tighter than average
    // (save roomy bins for future large items), reward bins looser than average.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.25;
        if poor_fit && next_item_size > 0 && next_item_size > bin_residual.saturating_sub(0) {
            score -= 50.0 * scarcity;
        } else {
            score += 25.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Mild stream-progression pressure: consolidate more as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty normalized by capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: penalize placements that leave residual smaller than the next item,
    // creating dead space; reward placements where the next item still fits.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
    } else {
        // Favor bins with below-mean residual (filling fuller bins first).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Slight preference for bins with larger residuals early on (spread load),
    // shifting to tighter packing as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += bin_residual as f64 * 0.05 * (1.0 - progress);

    // Penalize very small leftovers that nothing (min size 1) can waste-fill usefully
    // unless they are near-perfect fits already handled above.
    if post_residual > 0 && post_residual < 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Later in the stream, tight packing (small post_residual) matters more.
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth cubic penalty on wasted residual normalized by capacity.
    score += 25.0 * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead: reward if next item fits into post_residual (smooth soft-max style).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - slack) * (1.0 - progress * 0.5);
    } else if next_item_size > post_residual {
        // Penalize leaving residual that the next item cannot use, scaled by how far off.
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 10.0 * gap * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist
    // and late in the stream; smooth in mean_residual.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        let mean_norm = mean_residual / cap;
        score += 20.0 + 25.0 * fit_pressure * (1.0 - mean_norm) + 15.0 * progress;
    } else {
        // Mild reward for using existing open bins, scaled by how full they already are.
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 8.0 * fill;
    }

    // Slight preference for bins with residual close to item_size (tight fit),
    // smooth Gaussian-like coupling.
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 12.0 * tight * tight;

    // Small dispersion term: avoid creating residuals far from the mean residual.
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of capacity wasted
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_frac) * 50.0;

    // Harmonic class logic: bucket post_residual into classes via integer division.
    // Residuals < 10 are dead space (min item size 1..100, but small residuals rarely reusable)
    let dead_class = post_residual / 10; // harmonic class of residual
    match dead_class {
        0 => score += 60.0,          // 0..9: nearly dead space
        1 => score += 25.0,          // 10..19: poor reuse
        2 => score += 10.0,          // 20..29: moderate
        3 => score += 3.0,           // 30..39
        _ => {}                      // >=40: healthy residual
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (next_item_size as f64 / bin_capacity as f64) * 30.0;
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize leaving a residual close to but below next item
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 10.0 {
            score += 15.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // baseline score for fresh bin: capacity residual, adjusted by open bins and mean residual
        score = 100.0
            + open_bins_count as f64 * 5.0
            - mean_residual * 0.8
            + progress * 20.0;
        // if a perfect fit exists elsewhere we already rewarded it heavily, so new bin rarely wins
        if post_residual == 0 { score -= 1000.0; } // (unreachable for fresh bin, kept for safety)
    }

    // Prefer filling bins with larger items when residual class is awkward
    if post_residual > 0 && post_residual < item_size {
        score += 5.0; // item nearly fills bin, good
        score -= item_size as f64 * 0.1;
    }

    // Modulo-based harmonic adjustment on post_residual vs capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == quarter || post_residual == half || post_residual == 3 * quarter {
        score += 8.0; // round residuals are statistically more reusable, slight penalty offset
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap -> unusable dead space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, zero waste
    }

    // Non-linear penalty on residual that falls into awkward mid-range
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 50.0 {
        score += 0.6 * (50.0 - pr); // smaller leftover in awkward zone penalized more
    }

    // Lookahead coupling: leftover that can still host the next item is valuable
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0; // can host next item
            score -= 0.1 * nx;
        } else if post_residual > 0 {
            score += 0.25 * (nx - pr).min(60.0); // dead space relative to next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight
    let open_pressure = open_bins_count as f64;
    if fitting_bins_count == 1 {
        // last chance bin: strongly favor using it over opening a new bin
        score -= 45.0;
    } else {
        score += 0.08 * open_pressure;
    }

    // New-bin candidate: allow opening a fresh bin when all fits are bad,
    // but only if current open bins are crowded (high mean residual usage).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 20.0;
        if crowded || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 15.0; // keep packing into existing bins when there is room
        }
    }

    // Mild stream-progression term: later in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (100.0 - pr) / 100.0;

    // Reward bins already tighter than average (good fit quality)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.15 * (mean_residual - res);
    } else {
        score += 0.10 * (res - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.5 * next_item_size as f64;
        // Extra bonus if next item fits almost exactly after this placement.
        score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        score += 6.0 + 0.25 * post_residual as f64;
    }

    // Prefer bins with low residual relative to the mean (compact bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless it enables a clean pairing with the next item.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, be more willing to open new bins (fewer leftover fragments).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = (post_residual as f64) - nxt;
            score -= 12.0 / (1.0 + gap);
        } else {
            // Post residual too small for next item: penalize dead space unless it is tiny.
            if post_residual > 0 {
                score += 4.0 * ((post_residual as f64) / 20.0).min(3.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize many fitting bins slightly less if this bin is above mean residual
    // (prefer filling bins that are already emptier to consolidate).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Time horizon: later in the stream, favor keeping residual space balanced
    // (avoid stranding large residuals when few items remain).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.15 * open_bins_count as f64;
        // But allow new bin if current item is large and would leave tiny residual everywhere.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: normalized post-residual squared (quadratic waste penalty)
    let tight = (pr / capacity) * (pr / capacity);
    score += 12.0 * tight;

    // Non-linear coupling: tight fits matter more as the stream progresses
    score -= 10.0 * (1.0 - progress) * (1.0 - tight);

    // Reward filling a bin almost exactly (smooth exponential near-zero residual bonus)
    score -= 15.0 * (-(pr / 8.0)).exp();

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score -= 8.0 * (-(gap / 10.0)).exp();
        // Penalize if post-residual is just barely too small for the next item (dead space)
        let near_miss = (next_item_size as f64 - pr).max(0.0);
        score += 5.0 * (-(near_miss / 6.0)).exp() * (pr > 0.0) as i32 as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize scattering across many open bins when mean residual is large
    score += 0.05 * open_bins_count as f64 * (mean_residual / capacity);

    // New-bin candidate: make it slightly unattractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - progress);
        // Allow new bin if existing bins are all poor fits (post_residual large)
        score -= 0.02 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes via integer division
    let class = post_residual / (bin_capacity / 10); // 10-wide classes
    score += (class as f64).powi(2) * 2.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tiny dead space (<= 5) is nearly unusable: penalize harshly
    if post_residual > 0 && post_residual <= 5 {
        score += 50.0;
    }

    // Coupling with next item: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 3.0 + 15.0;
        } else {
            // penalize wasted space next item cannot use
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item may justify fresh bin
        }
    }

    // Prefer bins whose residual is close to mean (balance)
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Late in stream: tighten packing, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small to be
    // usable by any plausible future item are heavily penalized.
    let dead_zone = 12.0; // smallest plausible item size
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus: strongly reward near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward leaving a residual that can accommodate the lookahead item exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += gap * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // the new-bin candidate (full residual) gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is tighter than the mean (good packing density).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Late in the stream, tighten packing further (fewer chances to fix waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core objective: minimize post_residual.
    // Strongly reward when post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let lookahead_match = if post_residual == next_item_size {
            -60.0
        } else if post_residual > next_item_size {
            // Partial reward proportional to how well the next item fills the leftover.
            -30.0 * (next_item_size as f64 / post_residual as f64)
        } else {
            // Next item cannot fit in leftover: penalize by the unusable gap.
            0.5 * (post_residual as f64 - next_item_size as f64).abs()
        };
        score += lookahead_match;
    }

    // Reward bins that are already well-filled relative to the fleet average residual:
    // tight bins should absorb the item to keep many loose bins available later.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving large dead space that nothing (10..80) can use efficiently.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly perfect fill
    }
    if post_residual > 80 {
        score += 5.0; // bin still mostly empty; deprioritize unless nothing better
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when many bins are already open and this bin would be a poor fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base new-bin score: its "post_residual" equals capacity - item_size, which is
        // naturally large; add a mild penalty that decays as the stream progresses,
        // so late in the stream we prefer squeezing into open bins.
        score += 10.0 * (1.0 - progress);
        // If the current bin fit would leave a very awkward gap, opening fresh is fine.
        if next_item_size > 0 && post_residual < next_item_size as u32 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Mild tie-break: prefer bins with larger absolute residual consumed ratio.
    score -= 0.05 * (item_size as f64 / bin_residual.max(1) as f64) * bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with diminishing returns
    // (dead space of 1 vs 5 matters more than 40 vs 44).
    score = (post_residual as f64).powf(0.75);

    // Strong reward for perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item,
    // penalize bins that would strand a residual just below the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: bonus scaled by how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= 30.0 + 20.0 * (1.0 - snug / bin_capacity as f64);
        } else if post_residual > 0 {
            // Residual too small for next item: penalize proportionally
            // to how close it just missed (frustrated capacity).
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 15.0 * (1.0 - miss / 20.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are nearly full on average, or very many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Cost of a new bin decreases as existing bins get fuller / stream matures.
        let new_bin_cost = 120.0
            - 60.0 * mean_fullness
            - 20.0 * progress
            - (open_bins_count as f64).min(20.0);
        score = new_bin_cost + post_residual as f64;
    } else {
        // Mild penalty for spreading across many open bins (keeps packing tight),
        // but relax late in the stream when consolidation matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (open_bins_count as f64) * (1.0 - progress) * 0.5;
    }

    // Prefer placing into bins whose residual is close to item_size
    // (tightness relative to the bin's own state).
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Global residual balance: bins far below mean residual are better targets
    // (leveling residuals keeps future fits viable).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress.
    let mut score = pr * (1.0 + progress * (pr / cap));

    // Smooth cubic coupling: large residuals matter more early, small dead space penalized late.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * poly * (1.0 - progress);

    // Tight fits rewarded, more strongly when item nearly fills the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving a residual that accommodates the next item.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (gap / cap);
        } else {
            score += 0.15 * gap.abs();
        }
    }

    // Mild penalty for spreading across too many bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64) * ((mean_residual - pr) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" is leftover space
    // Residuals that are multiples of common small item sizes (or near capacity fractions) are valuable.
    let pr = post_residual;
    let pr_mod = (pr % 10) as f64;
    score += 3.0 * pr_mod; // penalize residuals not aligned to 10-grid

    // Harmonic divisibility bonuses: leftover divisible by common sizes is reusable
    if pr > 0 {
        if pr % 50 == 0 { score -= 15.0; }
        else if pr % 25 == 0 { score -= 10.0; }
        else if pr % 20 == 0 { score -= 8.0; }
        else if pr % 10 == 0 { score -= 5.0; }
    }

    // Perfect fit reward
    if pr == 0 { score -= 60.0; }

    // Dead space: small unusable leftover (below min item size 1..=100, treat <10 as dead)
    if pr > 0 && pr < 10 { score += 40.0; }

    // Coupling with next item: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            // partial credit scaled by how well it fits
            let frac = next_item_size as f64 / pr as f64;
            score -= 20.0 * frac;
        } else {
            // next item won't fit here; penalize large leftovers slightly less if bin nearly full
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current fit is terrible
    if bin_residual == bin_capacity {
        // neutral base: score equals post_residual (= capacity - item_size),
        // plus a mild penalty so only genuinely bad fits (tiny score elsewhere impossible) open bins
        score += 20.0;
        // but if item is large relative to capacity, a fresh bin is attractive (avoid fragmentation)
        if (item_size as f64) > 0.6 * cap {
            score -= 30.0;
        }
    }

    // Fractional capacity coupling: reward bins whose residual is a small capacity fraction
    let res_frac = bin_residual as f64 / cap;
    if res_frac < 0.25 { score -= 10.0; } // nearly full bins: pack tightly
    else if res_frac > 0.75 { score += 8.0; } // mostly empty bins: prefer filling them with big items only

    // Progress-aware tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - res_frac);

    // Mean residual alignment: prefer bins close to mean residual (balanced packing)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize medium dead space quadratically
    if post_residual >= 10 && post_residual <= 25 {
        score += 0.6 * (post_residual as f64 - 10.0);
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 0.05 * open_bins_count as f64;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that next item almost fits (wasted potential)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // New-bin candidate: penalize opening new bin mildly, more when pressure low
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        // but if existing fits are all poor, new bin becomes attractive
        if post_residual >= 60 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late stream: be more conservative with dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 60.0 * chain_quality;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        score += (post_residual as f64) * 0.5;
    }

    // Penalize residuals far below mean residual (wasteful bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Slight preference for filling older/denser bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 40.0; // pairing two items in a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: square the post residual so small leftovers are strongly preferred
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        score += gap as f64 * 0.4;
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += post_residual as f64 * 0.5;
        }
    }

    // Last chance: strongly prefer using the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent alternatives exist
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // residual of fresh bin after placement
        score += waste * 0.3;
        // Early in the stream, prefer consolidation into open bins; late, opening is cheaper
        score += (1.0 - progress) * 25.0;
        // If many bins are open and mean residual is small, opening a new bin is fine
        if open_bins_count > 2 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // If no open bin fits tightly, opening is attractive
        if post_residual < item_size / 2 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (use up crowded space)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Slight preference for filling fuller bins as stream progresses
    score -= (bin_capacity - bin_residual) as f64 * (0.05 + 0.1 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits; polynomial coupling with stream progress.
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);
    score += 20.0 * norm_pr * norm_pr * norm_pr * (0.5 + 2.0 * progress);

    // Penalize opening a new bin when open bins could fit.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 45.0 + 60.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).ln();
        }
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 && !is_new_bin {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            // Penalize residuals that strand the next item.
            score += 8.0 * (1.0 - pr / nxt.max(1.0)).max(0.0);
        }
    }

    // Mild coupling with mean residual: avoid bins far from the pack's average.
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Slight preference for consolidating into fewer bins early.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Classes mod 10 and integer-division bands capture typical small-item sizes.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let band = pr / 10; // integer division band (0..10)

    // Perfect-fit reward: post_residual exactly in common small-item classes
    if pr == 0 {
        score -= 60.0;
    } else if pr >= 10 && pr <= 30 && class10 == 0.0 {
        score -= 15.0; // leftover matches a round small item size exactly
    } else if pr < 10 {
        score += (10 - pr) as f64 * 2.0; // tiny dead space penalty
    }

    // Non-round leftovers are harder to fill: penalize odd classes
    score += class10 * 0.8;

    // Lookahead coupling: if next item fits the post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0;
        // harmonic bonus when next item size divides/matches residual class
        if pr % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 8.0; // residual cannot host the lookahead item
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score = 45.0 + congestion * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 5.0;
        }
    }

    // Late in the stream, tighten packing (prefer best-fit more aggressively)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Band-based tie-break: prefer mid bands that remain reusable
    score -= band as f64 * 0.5;

    // Prefer bins tighter than the mean residual (better fill)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: small non-zero gaps are unusable.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr); // dead-space penalty for tiny gaps
        } else if pr < 25.0 {
            score += 0.5 * (25.0 - pr); // mild penalty for smallish gaps
        }

        // Reward leaving room for the lookahead item (k=2 lookahead).
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual && (next_item_size as u32) <= bin_residual {
            // This bin is the only one that could chain the next item; slight bonus.
            score -= 3.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage opening a new one,
    // encourage consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = 2.0 * open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 50.0 + pressure;
        // If this bin is the last chance, opening a new bin is even worse.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    } else {
        // Existing-bin bonus scaled by pressure.
        score -= pressure.min(40.0);
        // Last-chance bin: strongly favor using it.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
    }

    // Prefer bins whose residual is close to what we consume (tight fit),
    // relative to the fleet mean residual.
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * (tight - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
