pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead coupling: great if the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins fit the item, prefer the one with least residual waste;
    // add slight competition pressure.
    if fitting_bins_count > 1 {
        score += 0.8 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: penalize placements that inflate mean residual imbalance.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (keep bins flexible); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += 30.0 * progress - 10.0 * (1.0 - progress);
        // Opening a new bin is bad if an open bin fits nearly perfectly.
        if post_residual == 0 && bin_residual == bin_capacity && item_size < bin_capacity {
            score += 40.0; // never open a new bin for a perfect fit elsewhere
        }
        // Prefer new bin when open bins are very fragmented.
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 8.0;
        }
    } else {
        // Existing bin: bonus for consolidation as stream progresses.
        score -= 6.0 * progress;
    }

    // Mild penalty for accumulating many open bins early (fragmentation).
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer small post_residual, with non-linear shaping
    let mut score = pr;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, low residuals are fine; later, dead space is more costly.
    let dead_penalty = x * x * (1.0 + 3.0 * progress) * cap * 0.5;
    score += dead_penalty;

    // Reward tight fits (post_residual near zero) with a smooth valley
    let tightness = (1.0 - x).powi(3);
    score -= tightness * cap * 0.3;

    // Lookahead coupling: if next item fits in post_residual, reward;
    // smooth interaction term between x and next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = nx - x;
        let fits = (1.0 - gap.max(0.0) / nx.max(0.01)).clamp(0.0, 1.0);
        let bonus = if gap <= 0.0 { 1.0 } else { 0.0 };
        let smooth = bonus * (1.0 - x).powi(2) + fits * 0.5 * (1.0 - bonus);
        score -= smooth * cap * 0.4 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.6 * (1.0 + progress);
    }

    // Mean residual coupling: penalize bins far from the mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.4;

    // New-bin candidate: make it attractive only when no good fit exists;
    // penalize opening new bins mildly, growing with open bins count.
    if bin_residual == bin_capacity {
        score += cap * (0.25 + 0.02 * open_bins_count as f64) - cap * 0.3 * (1.0 - progress) * 0.0;
        score -= 0.0;
        // Slight discount late in the stream when consolidation matters less
        score -= cap * 0.1 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward small post_residual (tight fit), with harmonic (power-of-two) classes.
    if post_residual == 0 {
        score -= 100.0; // perfect closure
    } else if post_residual < eighth {
        score -= 40.0;
    } else if post_residual < quarter {
        score -= 15.0;
    } else if post_residual < quarter * 2 {
        score += 5.0;
    } else {
        score += 15.0; // large dead space
    }

    // Modulo arithmetic on post_residual: values divisible by small integers are more reusable.
    let pr_u = post_residual;
    if pr_u % 10 == 0 {
        score -= 6.0;
    } else if pr_u % 5 == 0 {
        score -= 3.0;
    }
    if pr_u % 2 == 1 {
        score += 2.0; // odd leftovers pair worse with even-ish items
    }

    // Coupling with next item: reward residuals that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // how tightly the next item would fit into this residual
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 8.0; // next item closes this bin exactly
            }
        } else {
            score += 4.0; // lookahead cannot use leftover
        }
        // harmonic threshold classes of next_item_size
        if next_item_size >= quarter * 3 {
            score -= 2.0; // big next item: prefer conserving other bins
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64 / cap;
        let penalty = 30.0 + 40.0 * (1.0 - tightness);
        // relax penalty late in the stream or when many bins are open and fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        let relax = 10.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        score += penalty - relax;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 5.0; // fresh bin can also host lookahead
        }
    }

    // Mild preference for bins with residual far from mean (consolidate extremes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..=9 here) are wasted; penalize hard, scaled by how "dead" they are.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += (min_item as f64 - post_residual as f64 + 9.0) * 4.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Smooth reward for tight fits (small positive post_residual).
        score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 0.5;
    }

    // Prefer existing bins over opening new ones: bonus when bin is already open.
    if bin_residual < bin_capacity {
        score -= 8.0;
        // Extra pressure when many bins are open (consolidation).
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    } else {
        // New-bin candidate: penalize proportional to open bin count so we only
        // open when no decent fit exists.
        score += 6.0 + open_bins_count as f64 * 0.35;
    }

    // Last-chance bin: strongly favor using it to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: reward leaving room that still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize blocking the next item with an awkward gap.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Mild preference for bins whose residual is near the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    // Late-stream urgency: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that match next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 1.5;
        // Exact match for next item
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Post residual can still fit next item (good chaining)
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 80.0;
        }
    }

    // Penalize dead space too small for any item (min size 1, but small waste is bad)
    if post_residual > 0 && post_residual < 5 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless current bins have poor fits or high residual spread
    if bin_residual == bin_capacity {
        score += 250.0;
        // open new bin if open bins are nearly full (low mean residual)
        if mean_residual < 15.0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 120.0;
        }
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 60.0;

    // Coupling with mean residual: prefer bins below mean residual (denser packing)
    score += (mean_residual - post_residual as f64) * 0.4;

    // Late in stream: be more conservative, prefer existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last chance: strongly prefer the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let pair_eff = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * pair_eff;
        } else {
            // Next item won't fit here: mildly penalize large leftover.
            score += 0.05 * post_residual as f64;
        }
    }

    // New-bin candidate handling: empty bin starts at high baseline unless open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 20.0 - 2.0 * congestion.min(10.0);
        // Late in the stream, opening new bins is fine; early, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
    } else {
        // Prefer bins whose residual deviates below the mean (use up the poor bins first).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * dev;
        // Mildly prefer using bins when many are open (reduce open-bin sprawl).
        score -= 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 20.0 * poly;

    // Penalize large dead space more when few fitting bins remain
    if fitting_bins_count <= 1 {
        score += 15.0 * pr_norm;
    }

    // Reward tight fits relative to mean residual
    score -= 5.0 * (mean_residual - pr).tanh();

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (pr / (pr + nxt)).ln().abs().min(1.0);
        } else {
            score += 8.0 * (nxt - pr) / bin_capacity as f64;
        }
    }

    // Mild penalty for proliferating open bins late in the stream
    score += (open_bins_count as f64).ln() * progress * 3.0;

    // Prefer new-bin opening when residual is very large early (smooth sigmoid)
    let new_bin_bias = 1.0 / (1.0 + (-6.0 * (pr_norm - 0.6)).exp());
    score += 10.0 * new_bin_bias * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: classify leftover space by
    // capacity-fraction buckets (dead space is worse in the small classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr * 4.0 / cap).floor(); // 0..3 quartile class of leftover
    score -= match class as u32 {
        0 => 30.0,                     // leftover < 25%: excellent packing
        1 => 10.0,                     // 25-50%: good
        2 => -5.0,                     // 50-75%: mildly discouraged
        _ => -15.0,                    // >75%: wasteful placement
    };

    // Modulo arithmetic: leftover that is a multiple of small harmonics
    // (e.g. divisible by 5 or 10) is more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap); // tighter slack preferred
        } else {
            // Next item cannot use this leftover: penalize proportionally
            // to how much of the leftover is stranded.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new-bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it competitive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~1 bin; make it attractive only if the
        // item is large relative to capacity and no tight fit exists.
        let large_item = item_size as f64 > 0.7 * cap;
        if large_item || fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 35.0; // prefer filling existing bins with small items
        }
    }

    // Prefer bins with below-average residual (denser bins) slightly.
    score += 0.05 * (pr - mean_residual);

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Tight-fit reward: the larger the fraction of the bin's current residual
    // that the item consumes, the better. Ranges up to ~28 when item fills bin.
    let tightness = item / res.max(1.0);
    score -= 28.0 * tightness;

    // Extra reward for near-perfect fills (post_residual near zero).
    if post_residual == 0 {
        score -= 10.0;
    } else if post <= 0.05 * cap {
        score -= 5.0 * (1.0 - post / (0.05 * cap));
    }

    // Dead-space penalty: residual left over that is too small to be useful.
    // Use next_item_size as a dynamic usability threshold when available.
    let thr = if next_item_size > 0 { next_item_size as f64 } else { 0.1 * cap };
    if post_residual > 0 && post < thr {
        // The smaller the leftover relative to what could still be needed,
        // the more likely it becomes permanent dead space.
        score += 18.0 * (1.0 - post / thr.max(1.0));
    }
    // Absolute tiny-gap penalty: gaps below 5% of capacity are almost always dead.
    if post_residual > 0 && post < 0.05 * cap {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin (but never for the new-bin candidate itself).
    let is_new_bin = bin_residual == bin_capacity;
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Favor closing fuller bins: if this bin's residual is below the mean residual
    // across open bins, it is a good candidate to finish off.
    if !is_new_bin {
        score -= 0.15 * (mean_residual - res).max(0.0);
    }

    // Mild penalty for the brand-new bin candidate so it only wins when existing
    // fits are poor; pressure grows slightly with the number of open bins.
    if is_new_bin {
        score += 6.0 + 0.5 * open_bins_count as f64;
    }

    // Late-stream consolidation: as the stream progresses, prefer tighter fits
    // even more to avoid stranding residual capacity in many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // exactly fills the post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0);
        } else {
            // Next item would NOT fit: penalize creating dead space,
            // worse when the leftover chunk is small (unusable).
            let dead = post_residual as f64;
            let deadness = if dead < 10.0 { 120.0 } else { 60.0 * (10.0 - dead / 100.0).max(0.0) };
            score += deadness;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (compact packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0) * 0.8;
    } else {
        score += (pr - mean_residual).min(50.0) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make opening a fresh bin attractive only when the
    // current item is large relative to capacity and no good chain exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; discounted when many bins already open
        // (amortized) or item is huge.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 95.0 - 40.0 * item_frac;
        if open_bins_count == 0 {
            new_bin_score = -1000.0;
        }
        // If the next item is large, a fresh bin has good future utility.
        if next_item_size > 0 {
            new_bin_score -= (next_item_size as f64 / bin_capacity as f64) * 70.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 25.0;
        // Blend: score for a new bin is essentially its own residual (full capacity)
        // plus the calibrated adjustment.
        score = score.max(0.0) * 0.0 + bin_capacity as f64 + new_bin_score - (bin_capacity as f64);
        score = bin_capacity as f64 + new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with diminishing returns for tiny leftovers.
    score = (post_residual as f64).powf(1.15);

    // Tight-fit reward: exact or near-exact fits are heavily favored.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item cannot fit in the resulting residual, this bin's
    // leftover space is likely dead space -> penalize. If it can fit, reward.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global fragmentation pressure: when many open bins have high mean residual,
    // filling existing bins is cheap; when mean residual is low, prefer bins that
    // keep their residual close to the mean (balanced packing).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Time horizon: early in the stream, be conservative (favor spreading items
    // across bins); late in the stream, squeeze hard into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has large residual; it should only
    // win when no open bin fits well. Give it a baseline penalty that grows with
    // the number of already-open bins (discourage bin proliferation), but shrink
    // that penalty when the item is large (poorly placeable items).
    if bin_residual == bin_capacity {
        let open_penalty = 8.0 + 2.0 * open_bins_count as f64;
        let large_item_relief = (item_size as f64 / bin_capacity as f64) * 25.0;
        score = bin_capacity as f64 - open_penalty + large_item_relief;
        // If nothing else fits well (few fitting bins), opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let prog_sq = progress * progress;
    score += 8.0 * norm_pr * norm_pr * (progress + 0.5);
    score -= 4.0 * norm_pr * prog_sq;

    // Penalize tight fits less as stream progresses (favor filling bins)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= 6.0 * tightness * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - pr / cap) * (0.5 + progress);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate penalty tuned by mean residual and progress
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if mean_residual > 0.0 {
            score -= 3.0 * (mean_residual / cap).min(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "clean"
    // fractions of capacity (0, C/4, C/2, C/3) which future items reuse well.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        let classes = [cap / 4.0, cap / 3.0, cap / 2.0, 3.0 * cap / 4.0, cap / 5.0, 2.0 * cap / 3.0];
        for c in classes.iter() {
            if (pr as f64 - c).abs() <= 2.0 {
                score -= 18.0; // residual near a harmonic fraction is reusable
                break;
            }
        }
        // Integer-division thresholds: small dead space (<10) is nearly unusable
        if pr < 10 {
            score += 25.0;
        }
        // Modulo arithmetic: residuals divisible by 10 pair with common sizes
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // Penalize residuals in awkward bands (11..=19 and 81..=99)
        if (11..=19).contains(&pr) {
            score += 6.0;
        }
        if (81..=99).contains(&pr) {
            score += 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // next item fits: residual class matters more
            if pr - next_item_size <= 5 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: mild penalty for tight packing
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin leaves full residual; make it attractive only when
        // this bin's fit would be terrible (post_residual large) or many bins open.
        score += 40.0;
        score -= 0.3 * (open_bins_count as f64);
        // Late in stream, reuse is cheaper than opening
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the item fits this new bin perfectly it's fine to open
        if pr == 0 { score -= 70.0; }
    }

    // Tightness reward: how much of the bin's used space this placement consumes
    let tightness = item_size as f64 / cap;
    score -= 10.0 * tightness;

    // Prefer bins with residual close to item size (best-fit sharpening)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 25.0 * diff;

    // Spread across open bins: discourage hoarding many nearly-empty bins
    if !is_new_bin && (bin_residual as f64) > mean_residual + 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Medium gaps (11..=25) mildly penalized
    else if post_residual <= 25 {
        score += 0.35 * (post_residual as f64);
    }

    // Reward bins whose residual tightly matches the item (good fit)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Pressure: prefer spreading across fewer bins when many are open
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // extra reward if next item nearly fills the remaining gap
        if post_residual - next_item_size <= 10 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // next item can't use this tiny gap: penalize
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * scarcity;                 // penalize new bin if others fit
        score += 1.5 * open_bins_count as f64;    // but new bins are cheap when few open
        if next_item_size > 0 {
            // new bin is great if next item pairs well with current one
            if item_size + next_item_size <= bin_capacity {
                score -= 35.0;
            }
        }
        if mean_residual < item_size as f64 && fitting_bins_count > 0 {
            score -= 10.0; // open residuals can't hold item well anyway
        }
    }

    // Late in stream: tighten packing, avoid leftover fragmentation
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 8.0 * progress * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward proportional to tightness.
        score -= (bin_capacity as f64 - gap) * 0.9;
        // Extra reward if next item fits exactly (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residuals too small for the next item (dead space risk),
        // scaled by how far below the next item the residual falls.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // No lookahead available: fall back to tightness preference.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.3;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (fill fuller bins first),
    // penalize bins already much emptier than average.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness_elsewhere = (mean_residual - post_residual as f64).abs();
        score += 35.0 + tightness_elsewhere * 0.2;
        // Slightly cheaper to open new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Mild penalty for creating very small unusable residuals (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (dead space near zero).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize residual slivers that nothing (>=1) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward if next item fits perfectly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large awkward gap.
            score += 0.05 * (post_residual as f64);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit is bad (large post_residual) and there are many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = post_residual as f64 / bin_capacity as f64; // = item fraction
        // Base reluctance to open new bins, eased as stream progresses.
        let mut nb = 30.0 * (1.0 - 0.5 * progress);
        // If the best fit would leave big dead space, new bin becomes attractive.
        let worst_case_gap = (mean_residual - item_size as f64).max(0.0);
        nb -= 0.3 * worst_case_gap;
        // Few open bins -> prefer consolidating; many open bins -> new bin ok.
        nb += 3.0 * (open_bins_count as f64).ln().max(0.0);
        // Large items naturally start fresh bins.
        nb -= 20.0 * fit_quality;
        score += nb;
    } else {
        // Mild preference for bins whose residual is above average (spread load).
        score += 0.1 * (mean_residual - bin_residual as f64);
        // Slight preference for earlier-opened (likely emptier) bins when many open.
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted post-residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate slack; late in stream punish residual more sharply
    let prog_coupling = 1.0 + 2.0 * progress * progress;
    score *= prog_coupling;

    // Tight fit reward: smooth sigmoid-like term on item/residual ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Last chance bin: strong reward, smoothly modulated by progress
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: reward if next item fits post-residual exactly-ish
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.05 * gap;
        // bonus if next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Prefer bins below mean residual (keeps emptier bins for later)
    score += 0.3 * (pr - mean_residual);

    // Mild penalty for opening many bins: discourage new-bin when alternatives exist
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residues divisible into nice chunks
    // (multiples of 10) leave space reusable by common item sizes.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 {
        score -= 3.0;
    }
    if pr % 50 == 0 {
        score -= 3.0;
    }

    // Coupling with lookahead: does the leftover accommodate next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Bonus scaled by how well next item would fit the leftover.
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 + 12.0 * (1.0 - slack / bin_capacity as f64);
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Leftover too small for the next item: penalize dead space,
            // worse the closer pr is to being useful (just barely fails).
            let gap = (next_item_size - pr) as f64;
            score += 5.0 + 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * (fill_ratio - 0.8) / 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer reusing open bins.
        score += 30.0;
        // But if item is large and few bins fit it, opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: reuse them instead.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Penalize leaving tiny unusable slivers (below min item size 1..10 zone).
    if pr < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: small nonzero gaps are unusable dead space.
        // Penalize any post_residual below the smallest plausible item threshold
        // relative to the unknown distribution: treat gaps <= item_size/2 as dead.
        let dead_threshold = (item_size.min(bin_capacity / 2)) as f64;
        if (post_residual as f64) < dead_threshold * 0.5 {
            score += 400.0 + (dead_threshold - post_residual as f64) * 10.0;
        } else {
            // Reward leaving a gap that could fit the lookahead item (k=2 lookahead).
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 150.0 + (post_residual - next_item_size) as f64 * 0.5;
            } else if next_item_size > 0 {
                // Gap too small for the next item: mild penalty proportional to waste.
                score += 60.0 + (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Reward tight fits relative to residual (prefer bin with least slack used).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 200.0;

    // Open bins pressure: when many bins are open, discourage opening new ones,
    // i.e. penalize the new-bin candidate (residual == capacity) progressively.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 50.0 + open_bins_count as f64 * 20.0 + progress * 100.0;
        // If only one bin can fit the item, strongly prefer using it over a new bin.
        if fitting_bins_count == 1 {
            score += 500.0;
        }
    } else if fitting_bins_count == 1 {
        // This open bin is the last chance: heavy reward to avoid opening a new bin.
        score -= 300.0;
    }

    // Mild alignment with mean residual: prefer bins whose leftover stays near the mean
    // (keeps the bin pool homogeneous and future-fit friendly).
    score += ((post_residual as f64) - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/tight match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect chain: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item fits perfectly with a small margin left.
        if next_item_size < post_residual {
            score -= 6.0 + 0.1 * next_item_size as f64;
        }
    }

    // Penalize creating dead space far from mean residual (fragmentation).
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.35 * dead;
    } else {
        score += 0.15 * dead; // small reward for tighter-than-average fit
    }

    // Penalize very small unusable leftovers unless next item can use them.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would equal capacity minus item anyway) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 50.0)) * (1.0 - progress);
        score += 10.0 + pressure; // bias against opening unless forced
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 15.0; // next item won't fit here anyway; keep open bins
        }
    }

    // Mild reward for filling bins more completely over stream time.
    score -= 0.05 * item_size as f64 * (1.0 + step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that no future item (min size 1, typical >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver under the minimum item size
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 18.0 * chain_fit;
        } else {
            // Next item won't chain into this bin: mild penalty proportional to wasted lookahead.
            let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins with large mean residual: prefer consolidating into fuller bins.
    if open_bins_count > 2 {
        let fullness_gap = mean_residual - post_residual as f64;
        score += 0.08 * fullness_gap; // penalize bins that are emptier than average
        score -= 0.5 * open_bins_count as f64; // mild pressure to reuse existing bins
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are nearly full
        // and the item fits poorly everywhere (large post_residual).
        let spread = (mean_residual - post_residual as f64).abs();
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score += 40.0; // item too small for a fresh bin; use an open one
        } else if fitting_bins_count <= 1 {
            score -= 10.0; // poor fit elsewhere: new bin is reasonable
        } else {
            score += 5.0 + 0.1 * spread;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Slight overall preference for bins with less residual left overall.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space is increasingly costly.
    let norm_post = post / cap;
    score += 3.0 * norm_post * norm_post * cap;

    // Tight fit reward: quadratic coupling of fill ratio with post residual.
    let fill = fit / cap;
    score -= 2.5 * fill * fill * cap;

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that strand just below it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 1.5 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - post) / cap;
            score += 2.0 * gap * gap * cap;
        }
    }

    // Mean-residual deviation: prefer bins whose residual stays near the fleet mean
    // (keeps many bins usable for future items), with smooth cubic interaction.
    let dev = (post - mean_residual) / cap;
    score += 1.2 * dev * dev * cap * (1.0 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize proportionally to how many bins are already open,
    // with a smooth decay late in the stream (consolidation phase).
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 4.0 + open * (1.0 - progress) * 0.5;
        // Late stream: opening a fresh bin is relatively more attractive.
        score -= 3.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strong discount as post_residual shrinks.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Perfect or near-perfect fill.
    if post_residual == 0 { score -= 60.0; }
    else if post_residual < 10 { score -= 30.0; }

    // Harmonic classes: quantize post_residual into deciles (mod-10 logic).
    let pr_class = (post_residual / 10) % 10;
    let class_penalty = match pr_class {
        0 => -15.0, // residual <= 9: nearly full bin, great
        1 => 6.0,   // residual 10..19: awkward small dead space
        2 => -4.0,  // residual 20..29: useful pocket
        3 => 3.0,
        4 => -2.0,
        5 => 2.0,
        6 => -1.0,
        7 => 1.0,
        8 => 0.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
        if slack == 0 { score -= 25.0; } // exact two-item pairing
    } else if next_item_size > post_residual && post_residual > 0 {
        // Leftover cannot host next item: penalize proportionally to wasted fraction.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Harmonic lookahead: next_item_size in a class that pairs with common residuals.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt / 10.0).floor() as i64 % 2 == 0 {
            score -= 3.0; // even-decade items pair well with mid residuals
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.5 + 50.0 * (1.0 - progress);
        // Open a new bin only if no open bin gives a tight fit.
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size) as f64;
            if best_possible > waste + 35.0 { score += 100.0; }
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can host the pair comfortably
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual (more filled).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for fewer open bins early on.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

