    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space for the known next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
        // But if the current fit is terrible, a new bin is preferable:
        if post_residual > 0 && post_residual <= 10 {
            score -= 80.0;
        }
    }

    // Mild preference for bins already below mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight stream-progression pressure to close bins early.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

