    } else {
        score += (pr - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize many open bins slightly, to encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: default is neutral; only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = (bin_residual - item_size) as f64;
        score += 150.0 + bad_fit * 0.5 - (fitting_bins_count as f64) * 50.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0; // pair fits in a fresh bin
        }
    }

    // Late-stream pressure: consolidate more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress horizon: later in the stream, prefer tighter packing (larger residual penalty).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.5;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
