            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize unless the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how many bins already fit the item
        // and how much room would remain.
        let mut new_bin_cost = 120.0 + open_bins_count as f64 * 5.0;
        if post_residual > bin_capacity as f64 / 2.0 {
            new_bin_cost += 30.0; // big item in fresh bin, fine but still costs a bin
        }
        if fitting_bins_count == 0 {
            new_bin_cost -= 200.0; // no alternative: opening is necessary
        }
        score += new_bin_cost;
    }

    // Global residual pressure: if open bins are on average quite full, prefer using them
    // (small mean residual) rather than spreading load.
    score += (mean_residual - post_residual as f64) * 0.4;

    // Mild penalty for leaving residuals in the awkward 20..40 band (hard to fill later).
    if post_residual >= 20 && post_residual <= 40 {
        score += 15.0;
    }

    // Favor bins whose residual is already small (tighter bins first).
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
