    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect two-item chain: strongly reward
        if post_residual == next_item_size {
            score -= 40.0 + 20.0 * progress;
        } else {
            // penalize mismatch, scaled by gap size
            score += gap * 0.35;
            // extra penalty if next item cannot fit in post_residual (dead space for next step)
            if post_residual < next_item_size {
                score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
            }
        }
        // reward post_residual that can still host the next item
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Tight fits are good: small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 10.0;

    // Compare against mean residual: prefer bins with residual below mean (denser bins)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's clearly needed
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0;
        if good_fit_exists {
            // opening new bin is costly; penalize proportionally to how well other bins fit
            score += 45.0 + 25.0 * (1.0 - progress);
        } else {
            // no existing bin fits: opening new bin is the only option
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 2.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating dead space that the next item cannot use.
        let waste = (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)) / bin_capacity as f64;
        score += 2.0 * waste;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // existing fits are poor (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * (1.0 - progress);
    }

    // Penalize bins far from the mean residual (outliers create fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * (dev / bin_capacity as f64);

    // Prefer keeping the number of open bins modest.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins with smaller absolute residual when ties occur.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: tolerate moderate residuals; late stream: strongly penalize waste.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * prn * prn * cap * 0.5;

    // Reward near-perfect fits (small post_residual) with a smooth quadratic bonus.
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the next item (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            // If next item fits exactly-ish, reward leaving usable space.
            let usable = (nx / pr.max(1.0)) as f64;
            score -= 4.0 * usable * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn);
    } else if fitting_bins_count > 2 {
        score += 3.0 * prn * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: prefer opening a new bin when existing residuals are large
    // relative to the item, i.e., when fit is poor.
    let is_new_bin = (bin_residual == bin_capacity) && (post_residual as u64) == (bin_capacity as u64 - item_size as u64);
    if is_new_bin {
        let mean_prn = mean_residual / cap;
        // Opening a bin is attractive if existing bins have large, fragmented residuals.
        score -= 10.0 * mean_prn * (0.5 + progress);
        // But discourage too many open bins early.
        score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - progress);
    }

    // Mild preference for bins with residual close to mean (balanced packing).
    score += ((pr - mean_residual).abs() / cap) * 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (low post_residual).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Harmonic class of post_residual: mod-10 buckets.
    let pr = post_residual;
    let class = pr % 10;
    // Perfect fills and tiny dead space are gold; mid-range residuals (30-60) are semi-reusable.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 15.0;
    } else if class == 0 {
        score -= 8.0; // round residual is easy to fill with common item sizes
    } else if pr >= 30 && pr <= 60 {
        score -= 5.0;
    } else if pr < 10 {
        score += 10.0; // awkward near-dead sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 0.05 * (next_item_size as f64 - pr as f64).min(20.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        if fit_quality < 0.7 {
            score -= 25.0;
        }
    }

    // New-bin candidate: penalize opening a new bin when good fits exist,
    // but allow it when current bins would waste a lot.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins are open with large mean residual, discourage new bins.
        score += (open_bins_count as f64).ln() * 3.0;
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the stream average
    // (keeps open bins balanced and reusable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold: residual divisible by common small sizes is valuable.
    if pr > 0 && (pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero residuals are unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual exactly, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use this gap: penalize proportional dead space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that leave large residuals when many bins are open.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 0.3;
    score += pressure * post_residual as f64;

    // New-bin candidate: mostly neutral score so it's chosen only when fits are bad,
    // but slightly discourage when a good existing fit exists.
    if bin_residual == bin_capacity {
        score = 30.0 + 0.25 * mean_residual - (fitting_bins_count as f64).min(4.0) * 2.0;
        if next_item_size > 0 && item_size <= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual is inherently rewarded by base score).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: strongly reward when the next item fits
    // the post-residual exactly or snugly (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Tighter lookahead fit => bigger reward, decaying with slack.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit here: penalize leaving large unusable gaps
            // relative to the next item size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving much less than the
    // mean residual is good (concentrating space usage).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr);
    } else {
        score += 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize the brand-new empty bin candidate unless no decent fit exists:
    // opening a new bin wastes the residual of the current bin.
    if bin_residual == bin_capacity {
        // New bin is attractive if current bin would leave a large awkward gap
        // (post_residual too small to be useful for typical items).
        let usefulness = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        if usefulness > 0.0 || post_residual <= 10 {
            score += 60.0; // an existing bin chains well; don't open new
        } else {
            score += 5.0;  // mild preference for fresh bin on poor fits
        }
    }

    // Slight late-stream conservatism: consolidate more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins whose residual after placement is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold any plausible future item.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 50.0;
    }
    // Waste penalty grows if leftover space can't fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 4.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
    }
    // Bonus if the leftover exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 / (1.0 + gap);
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to encourage diversity of residual profiles.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins whose residual deviates from the mean (fill outliers first).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // New-bin candidate logic: opening a new bin is only attractive when current
    // bins fit poorly (high post_residual everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = bin_capacity as f64 * 0.55;
        // Cheaper to open early in the stream or when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 10.0 * (1.0 - progress);
        new_bin_score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If the mean residual of open bins is large, bins are roomy: reuse is fine,
        // so make a new bin less attractive.
        new_bin_score += 0.08 * mean_residual;
        // If lookahead item is large, a fresh bin keeps flexibility for it.
        if next_item_size > 0 {
            new_bin_score -= 0.05 * next_item_size as f64;
        }
        return new_bin_score;
    }

    // Slight preference for fuller bins as stream progresses (consolidation).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill * (1.0 + progress_factor(step_index, total_items));

    score
}

#[inline]
fn progress_factor(step_index: usize, total_items: usize) -> f64 {
    if total_items == 0 { 0.0 } else { step_index as f64 / total_items as f64 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.6 * progress - 0.8 * progress * progress;
    score *= poly;

    // Penalize small dead space (wasted slivers) more when stream is late
    let sliver = if pr > 0.0 { (cap - pr) / cap } else { 1.0 };
    score -= 4.0 * sliver * sliver * (0.5 + progress);

    // Reward tight fits (near-zero residual) especially when alternatives are scarce
    if pr == 0 {
        score -= 10.0;
    }
    if fitting_bins_count <= 1 {
        score -= 6.0; // last-chance bin: strongly prefer using it
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - pr / cap);
    }

    // Mild penalty relative to mean residual: prefer bins below-average filled
    score += 0.5 * (mean_residual - pr) / cap;

    // New-bin candidate: discourage opening new bins early, allow later
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 >= item_size as f64 {
            score -= 4.0; // pairing large items with fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else {
        // Harmonic classes: bucket post_residual by capacity fractions.
        let frac = post_residual as f64 / cap;
        if frac < 0.2 {
            score -= 15.0;
        } else if frac < 0.4 {
            score -= 5.0;
        } else if frac < 0.6 {
            score += 5.0;
        } else {
            score += 10.0;
        }
    }

    // If post_residual can exactly host the next item, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Exact match: perfect chain fit.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item leaves a small residue again -> good chain.
        let chain_res = post_residual - next_item_size;
        if chain_res <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; residual is likely dead space.
        score += 8.0;
        if post_residual < 10 {
            score += 5.0; // tiny dead space is acceptable though
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize unless nothing decent fits.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        // If no existing bin can fit the item, opening is necessary.
        if fitting_bins_count == 0 {
            score = -100.0;
        } else {
            score = base_penalty
                + (fitting_bins_count as f64) * 2.0
                + mean_residual * 0.2;
            // Late in stream, prefer consolidating into open bins.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 20.0 * progress;
        }
    }

    // Slight preference to fill bins with larger residuals early (balance load).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Modulo-class bonus: residual divisible into common chunks is reusable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps super-linearly (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: baseline cost of opening a bin, adjusted by stream progress.
    if bin_residual == bin_capacity {
        score += 45.0 + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // Opening a new bin is attractive if no open bin fits well.
        if post_residual as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Favor bins with residuals close to the item (tight fit).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair
        } else if next_item_size <= post_residual {
            // next fits, penalize by leftover slack after next placement
            let slack_after_next = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack_after_next as f64 / cap);
        } else {
            // next item does NOT fit here; penalize large dead space
            score += 8.0 + 0.15 * (post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins with residual near mean (balance),
    // penalize extreme outliers unless they are perfect fits
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins unless current fit is terrible
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.5 * cap;
        if bad_fit {
            score -= 5.0; // item is small; fresh bin acceptable
        } else {
            score += 30.0; // decent fit exists elsewhere; keep item in open bin
        }
    }

    // Slight late-stream pressure to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits into resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 7.0;
            // Extra reward when next item exactly fills the remainder.
            if next_item_size == post_residual {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to wasted opportunity.
            score += 2.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Global state: when many bins are open, discourage spreading; when few open, mild new-bin tolerance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.15 * openness * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below mean residual (tighter than average bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: opening a new bin wastes capacity; only attractive
    // when all existing fits would create large dead space or this is a last-chance failure.
    if bin_residual == bin_capacity {
        let mut base = 14.0; // default cost of opening a new bin
        if fitting_bins_count == 0 {
            base -= 20.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            base += 10.0; // an existing last-chance bin should be used instead
        }
        // Late in the stream, avoid opening new bins more aggressively.
        base *= 1.0 + 0.5 * progress;
        score += base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), mildly superlinear.
    let mut score = pr + 0.15 * (pr * pr) / cap;

    // Smooth waste-rate coupling: dead space hurts more as stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead: reward leaving space that the next item can use.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            // Penalize blocking: post_residual too small for next item.
            score += 4.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin, less so when no good fit exists
    // or many bins are open (diversity of residuals is valuable).
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - item_size as f64 / cap;
        score += 18.0 - 10.0 * fit_quality - 2.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative: open the bin
        }
    } else {
        // Prefer bins whose residual is close to mean (balanced packing) early on;
        // prefer below-mean bins (larger items into emptier bins) later.
        let dev = (residual - mean_residual) / cap;
        score += 3.0 * dev * (1.0 - 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes on post_residual (base-10 modulo arithmetic)
    let pr = post_residual;
    let m = (pr % 10) as f64;
    // Residuals whose last digit is high are "roundable" waste; penalize slightly
    score += m * 0.15;
    // Perfect closure
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 10 {
        // Small residuals are near-closed classes
        score -= 15.0;
    }
    // Unusable dead space: nothing in [1,100] can ever be < item min, but
    // residuals below 10 are effectively dead for future medium items
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Tightness reward (quadratic coupling)
    let tight = 1.0 - pr as f64 / cap;
    score -= 10.0 * tight * tight;

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // scaled by how snugly the next item would fit
    if next_item_size > 0 && pr >= next_item_size {
        let snug = 1.0 - (pr - next_item_size) as f64 / cap;
        score -= 14.0 * snug;
    } else if next_item_size > 0 && pr > 0 {
        score += 6.0; // would strand the lookahead item
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 22.0;
        if fitting_bins_count > 0 {
            // An open bin can take it: penalize opening a fresh one harder
            score += 18.0;
            // But if that fit would create large dead space, soften the penalty
            let waste = bin_residual - item_size;
            if waste > 40 {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only open bin that fits, use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 8.0 * progress * tight;
    }

    // Mild preference for bins below mean residual (keeps residual spread balanced)
    score += 0.05 * ((pr as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for typical future items (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is nearly worthless
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Perfect fit reward: strongly favor bins that get filled exactly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Opening new bin is justified only if the item leaves a poor fit elsewhere.
        let bad_fit = if post_residual > 0 && post_residual < 20 { 1.0 } else { 0.0 };
        score += 55.0 - 60.0 * bad_fit;
        // Pressure: opening new bins becomes costlier as open bin count grows.
        score += open_bins_count as f64 * 1.5;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.05;

    // Coupling with mean residual: prefer bins whose residual is below average
    // (tighter packing) when the fit is decent.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: the residual becomes dead space for the lookahead.
        score += 6.0;
    }

    // Early stream: be slightly more willing to spread out; late stream: tighten.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 25.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 0.25 * miss;
        }
    }

    // Penalize dead space that no typical item could use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Compare against mean residual across open bins: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (better long-run packing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}
